"use client";

import { useCallback, useState } from "react";
import {
  type AgentConfig,
  DEFAULT_AGENT_CONFIG,
  type Expertise,
  type ResponseLength,
  type Tone,
} from "./config-types";

export interface UseAgentConfigHandle {
  config: AgentConfig;
  setTone: (tone: Tone) => void;
  setExpertise: (expertise: Expertise) => void;
  setResponseLength: (length: ResponseLength) => void;
  reset: () => void;
}

export function useAgentConfig(): UseAgentConfigHandle {
  const [config, setConfig] = useState<AgentConfig>(DEFAULT_AGENT_CONFIG);

  const setTone = useCallback(
    (tone: Tone) => setConfig((prev) => ({ ...prev, tone })),
    [],
  );
  const setExpertise = useCallback(
    (expertise: Expertise) => setConfig((prev) => ({ ...prev, expertise })),
    [],
  );
  const setResponseLength = useCallback(
    (responseLength: ResponseLength) =>
      setConfig((prev) => ({ ...prev, responseLength })),
    [],
  );
  const reset = useCallback(() => setConfig(DEFAULT_AGENT_CONFIG), []);

  return { config, setTone, setExpertise, setResponseLength, reset };
}

"use client";

import { CopilotKit } from "@copilotkit/react-core/v2";
import { VoiceChat } from "./voice-chat";

export default function VoiceDemoPage() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-voice"
      agent="voice-demo"
      useSingleEndpoint={false}
      // The dev-only `<cpk-web-inspector>` overlay (auto-enabled on
      // localhost via shouldShowDevConsole) intercepts pointer events
      // on top of the voice sample-audio button, so dev/D5 probe runs
      // can't click it through Playwright. Production isn't localhost
      // so the inspector never mounts there — voice is D5 in prod and
      // D4 locally for this reason alone. Disable explicitly here so
      // the demo behaves the same in both environments.
      enableInspector={false}
    >
      <VoiceChat />
    </CopilotKit>
