"use client";

import React from "react";
import {
  CopilotChat,
  CopilotKit,
  useAgent,
  UseAgentUpdate,
} from "@copilotkit/react-core/v2";
import type { Step } from "./InlineAgentStateCard";
import { MessageListWithState } from "./message-list-with-state";
import { useSuggestions } from "./suggestions";

/**
 * Agentic Generative UI — In-Chat State Rendering
 *
 * The deep agent on the backend defines its own state schema
 * (`steps: list[Step]`) and exposes a custom `set_steps` tool that the model
 * calls to mutate that state. Every `set_steps` call streams the updated
 * `steps` to the client.
 *
 * On the client we subscribe to that live state via `useAgent` (v2) and
 * render a single `InlineAgentStateCard` inside the chat transcript via
 * `messageView.children`. The card re-renders in place as state arrives —
 * no per-message claims, no duplicate cards.
 *
 * This mirrors the pattern used by every other integration's gen-ui-agent
 * demo (mastra, strands, ag2, agno, crewai-crews, langgraph-typescript,
 * pydantic-ai, ...) and replaces the earlier `useCoAgentStateRender`
 * approach which produced one card per state-changing message.
 */
export default function GenUiAgentDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="gen-ui-agent">
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

type AgentState = {
  steps?: Step[];
};

function Chat() {
  const { agent } = useAgent({
    agentId: "gen-ui-agent",
    updates: [UseAgentUpdate.OnStateChanged],
  });

  useSuggestions();

  const steps = (agent.state as AgentState | undefined)?.steps ?? [];
  const status = agent.isRunning ? "inProgress" : "complete";

  return (
    <CopilotChat
      agentId="gen-ui-agent"
      className="h-full rounded-2xl"
      messageView={{
        children: ({ messageElements, interruptElement }) => (
          <MessageListWithState
            messageElements={messageElements}
            interruptElement={interruptElement}
            steps={steps}
            status={status}
          />
        ),
      }}
    />
  );
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";

// The agent backend runs as a separate process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

function createMainAgent() {
  return new HttpAgent({ url: `${AGENT_URL}/agui` });
}

function createReasoningAgent() {
  return new HttpAgent({ url: `${AGENT_URL}/reasoning/agui` });
}

// State-aware agents are served by a custom AGUI handler in agent_server.py
// that emits StateSnapshotEvent after every run. Stock Agno AGUI does NOT
// emit state events, so demos that depend on agent-side state writes
// (set_notes, delegations) must point at these dedicated routes.
function createSharedStateRWAgent() {
  return new HttpAgent({ url: `${AGENT_URL}/shared-state-rw/agui` });
}

function createSubagentsAgent() {
  return new HttpAgent({ url: `${AGENT_URL}/subagents/agui` });
}

// gen-ui-agent: agent owns its own state schema (`steps`) and mutates it
// via the `set_steps` tool. Needs the state-aware AGUI router so the
// frontend's `useAgent({ updates: [OnStateChanged] })` receives the
// StateSnapshotEvent each run — stock Agno AGUI does not emit one.
function createGenUiAgent() {
  return new HttpAgent({ url: `${AGENT_URL}/gen-ui-agent/agui` });
}

// Main agent backs most demos. The Next.js runtime aliases the single
// Agno `main` agent under every demo cell name so per-cell frontend
// tool/component registrations scope correctly.
const mainAgentNames = [
  "agentic_chat",
  "human_in_the_loop",
  "hitl-in-chat",
  "hitl-in-app",
  "tool-rendering",
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "gen-ui-tool-based",
  "shared-state-read",
  "shared-state-write",
  "shared-state-streaming",
  // Neutral / chrome demos reusing the default agent.
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "headless-complete",
  "frontend_tools",
  "frontend-tools-async",
  "readonly-state-agent-context",
  "agent-config",
];

// Interrupt-adapted demos: gen-ui-interrupt and interrupt-headless share
// the same Agno scheduling agent at /interrupt-adapted/agui. The agent has
// tools=[]; `schedule_meeting` is provided by the frontend via
// `useFrontendTool` with an async Promise handler.
function createInterruptAgent() {
  return new HttpAgent({ url: `${AGENT_URL}/interrupt-adapted/agui` });
}

const interruptAgentNames = ["gen-ui-interrupt", "interrupt-headless"];

// Reasoning agent names — backed by the reasoning-enabled Agno agent at
// /reasoning/agui. Emits AG-UI REASONING_MESSAGE_* events that the
// frontend renders via CopilotChatReasoningMessage (or a custom slot).
const reasoningAgentNames = [
  "agentic-chat-reasoning",
  "reasoning-default-render",
  "tool-rendering-reasoning-chain",
  "reasoning-default",
  "reasoning-custom",
];

const agents: Record<string, AbstractAgent> = {};
for (const name of mainAgentNames) {
  agents[name] = createMainAgent();
}
for (const name of interruptAgentNames) {
  agents[name] = createInterruptAgent();
}
for (const name of reasoningAgentNames) {
  agents[name] = createReasoningAgent();
}
// Bidirectional shared-state agent — UI writes preferences, agent writes
// notes back via set_notes and the custom AGUI router emits a
// StateSnapshotEvent that the frontend's useAgent picks up.
// gen-ui-agent — owns its own `steps` state schema and mutates it via the
// `set_steps` tool. Routes to the state-aware AGUI handler that emits a
// StateSnapshotEvent each run so the frontend's progress card updates.
agents["gen-ui-agent"] = createGenUiAgent();
agents["shared-state-read-write"] = createSharedStateRWAgent();
// Sub-agents supervisor — appends to state["delegations"] every time a
// research / writing / critique sub-agent is delegated to. Same custom
// AGUI router emits the StateSnapshotEvent needed for the live log.
agents["subagents"] = createSubagentsAgent();
agents["default"] = createMainAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- Published CopilotRuntime agents type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in source, pending release
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    const err = error as Error;
    console.error(`[copilotkit/route] ERROR: ${err.message}`);
    console.error(`[copilotkit/route] Stack: ${err.stack}`);
    return NextResponse.json(
      { error: err.message, stack: err.stack },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

"use client";

import React from "react";

/**
 * Step shape matches the `Step` TypedDict emitted by the Python deep agent's
 * custom `set_steps` tool (see `src/agents/gen_ui_agent.py`).
 * Status transitions: pending -> in_progress -> completed.
 */
export type Step = {
  id: string;
  title: string;
  status: "pending" | "in_progress" | "completed";
};

export function InlineAgentStateCard({
  steps,
  status,
}: {
  steps: Step[];
  status: "inProgress" | "complete";
}) {
  const total = steps.length;
  const done = steps.filter((s) => s.status === "completed").length;
  const headline =
    status === "complete" || (total > 0 && done === total)
      ? `All ${total} steps complete`
      : total > 0
        ? `Step ${Math.min(done + 1, total)} of ${total}`
        : "Planning…";

  return (
    <div
      data-testid="agent-state-card"
      className="my-3 mx-4 rounded-2xl border border-[#DBDBE5] bg-white p-4 shadow-sm"
    >
      <div className="flex items-center gap-2">
        {status === "inProgress" && done < total ? (
          <SpinnerIcon />
        ) : (
          <CheckIcon />
        )}
        <span className="text-sm font-semibold text-[#010507]">{headline}</span>
      </div>

      {steps.length > 0 && (
        <ol className="mt-3 space-y-2">
          {steps.map((step, idx) => (
            <li
              key={step.id ?? idx}
              data-testid="agent-step"
              data-status={step.status}
              className="flex items-start gap-3"
            >
              <StepMarker status={step.status} index={idx} />
              <span
                className={
                  "text-xs leading-5 " +
                  (step.status === "completed"
                    ? "text-[#838389] line-through"
                    : step.status === "in_progress"
                      ? "text-[#010507] font-medium"
                      : "text-[#57575B]")
                }
              >
                {step.title}
              </span>
            </li>
          ))}
        </ol>
      )}
    </div>
  );
}

function StepMarker({
  status,
  index,
}: {
  status: Step["status"];
  index: number;
}) {
  if (status === "completed") {
    return (
      <span className="mt-0.5 inline-flex h-5 w-5 flex-none items-center justify-center rounded-full bg-[#85ECCE] text-[#010507]">
        <svg
          className="h-3 w-3"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={3}
            d="M5 13l4 4L19 7"
          />
        </svg>
      </span>
    );
  }
  if (status === "in_progress") {
    return (
      <span className="mt-0.5 inline-flex h-5 w-5 flex-none items-center justify-center rounded-full bg-[#BEC2FF] text-[#010507]">
        <svg
          className="h-3 w-3 animate-spin"
          xmlns="http://www.w3.org/2000/svg"
          fill="none"
          viewBox="0 0 24 24"
        >
          <circle
            className="opacity-30"
            cx="12"
            cy="12"
            r="10"
            stroke="currentColor"
            strokeWidth="4"
          />
          <path
            className="opacity-90"
            fill="currentColor"
            d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
          />
        </svg>
      </span>
    );
  }
  return (
    <span className="mt-0.5 inline-flex h-5 w-5 flex-none items-center justify-center rounded-full border border-[#DBDBE5] bg-white text-[10px] font-semibold text-[#838389]">
      {index + 1}
    </span>
  );
}

function SpinnerIcon() {
  return (
    <svg
      className="w-4 h-4 animate-spin text-[#010507]"
      xmlns="http://www.w3.org/2000/svg"
      fill="none"
      viewBox="0 0 24 24"
    >
      <circle
        className="opacity-25"
        cx="12"
        cy="12"
        r="10"
        stroke="currentColor"
        strokeWidth="4"
      />
      <path
        className="opacity-75"
        fill="currentColor"
        d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
      />
    </svg>
  );
}

function CheckIcon() {
  return (
    <svg
      className="w-4 h-4 text-[#189370]"
      fill="none"
      stroke="currentColor"
      viewBox="0 0 24 24"
    >
      <path
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth={3}
        d="M5 13l4 4L19 7"
      />
    </svg>
  );
}

"use client";

import React from "react";
import { InlineAgentStateCard, type Step } from "./InlineAgentStateCard";

export function MessageListWithState({
  messageElements,
  interruptElement,
  steps,
  status,
}: {
  messageElements: React.ReactNode;
  interruptElement: React.ReactNode;
  steps: Step[];
  status: "inProgress" | "complete";
}) {
  return (
    <div data-testid="copilot-message-list" className="flex flex-col">
      {messageElements}
      {steps.length > 0 && (
        <InlineAgentStateCard steps={steps} status={status} />
      )}
      {interruptElement}
    </div>
  );
}

"use client";

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export function useSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Plan a product launch",
        message: "Plan a product launch for a new mobile app.",
      },
      {
        title: "Organize a team offsite",
        message: "Organize a three-day engineering team offsite.",
      },
      {
        title: "Research a competitor",
