"use client";

// Chat Customization (CSS) — every visual choice in this demo lives in
// theme.css and is scoped to the `.chat-css-demo-scope` wrapper. The page
// intentionally stays minimal so the contrast against the default look
// comes entirely from the stylesheet.
//
// https://docs.copilotkit.ai/custom-look-and-feel/customize-built-in-ui-components

import React from "react";
import { CopilotKit, CopilotChat } from "@copilotkit/react-core/v2";
import "./theme.css";

export default function ChatCustomizationCssDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="chat-customization-css">
      <div className="flex justify-center items-center h-screen w-full bg-white p-6">
        <div className="chat-css-demo-scope h-full w-full max-w-4xl">
          <CopilotChat
            agentId="chat-customization-css"
            className="h-full"
            attachments={{ enabled: true }}
          />
        </div>
      </div>
    </CopilotKit>
  );
}

import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
  InMemoryAgentRunner,
} from "@copilotkit/runtime/v2";
import { createBuiltInAgent } from "@/lib/factory/tanstack-factory";
// Per-demo system prompts, ported from the reference's dedicated graphs. The
// demos below that pass one are those whose behaviour the model has to be told
// (walk a plan, invent sample chart data, delegate to sub-agents); the rest are
// genuinely prompt-neutral. See demo-prompts.ts.
import {
  GEN_UI_AGENT_PROMPT,
  GEN_UI_TOOL_BASED_PROMPT,
  SUBAGENTS_PROMPT,
} from "@/lib/factory/demo-prompts";
import { createAgenticChatAgent } from "@/lib/factory/agentic-chat-factory";
import {
  createAgenticChatReasoningAgent,
  createReasoningDefaultRenderAgent,
  createToolRenderingReasoningChainAgent,
} from "@/lib/factory/reasoning-factory";
// `withForwardedHeaders` snapshots inbound x-* headers (e.g.
// x-aimock-context) into an AsyncLocalStorage scope so the wrapped
// OpenAI client's custom fetch can re-attach them on every outbound
// LLM call. Required because `@tanstack/ai-openai`'s `openaiText()`
// adapter has no per-request header hook of its own.
import { withForwardedHeaders } from "@/lib/header-forwarding";
// CVDIAG backend instrumentation (L1-E). No-op pass-through unless
// CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
import { withCvdiagBackend } from "@/cvdiag-backend";

const runtime = new CopilotRuntime({
  agents: {
    // Catch-all agent retained during the LGP-parity migration.
    default: createBuiltInAgent(),

    // Per-demo named agents resolved by the byte-identical LGP frontends via
    // `agent="<id>"` on `/api/copilotkit`. The generic `createBuiltInAgent()`
    // carries the full server/state/subagent tool surface; per-demo behavior
    // is driven by the aimock fixture (same contract the old `default`-routed
    // demos relied on), so the chat-UI / tool / state / HITL / gen-UI demos
    // share it. Reasoning demos use the reasoning adapter factory.
    agentic_chat: createAgenticChatAgent(),

    "chat-customization-css": createBuiltInAgent(),
    "chat-slots": createBuiltInAgent(),
    "prebuilt-popup": createBuiltInAgent(),
    "prebuilt-sidebar": createBuiltInAgent(),
    "headless-simple": createBuiltInAgent(),

    frontend_tools: createBuiltInAgent(),
    "frontend-tools-async": createBuiltInAgent(),

    "tool-rendering": createBuiltInAgent(),
    "tool-rendering-default-catchall": createBuiltInAgent(),
    "tool-rendering-custom-catchall": createBuiltInAgent(),

    "gen-ui-agent": createBuiltInAgent({ systemPrompt: GEN_UI_AGENT_PROMPT }),
    "gen-ui-tool-based": createBuiltInAgent({
      systemPrompt: GEN_UI_TOOL_BASED_PROMPT,
    }),
    "gen-ui-interrupt": createBuiltInAgent(),
    "interrupt-headless": createBuiltInAgent(),

    human_in_the_loop: createBuiltInAgent(),
    "hitl-in-chat": createBuiltInAgent(),
    "hitl-in-app": createBuiltInAgent(),

    "shared-state-read": createBuiltInAgent(),
    "shared-state-read-write": createBuiltInAgent(),
    "shared-state-streaming": createBuiltInAgent(),
    "readonly-state-agent-context": createBuiltInAgent(),

    subagents: createBuiltInAgent({ systemPrompt: SUBAGENTS_PROMPT }),
    "threadid-frontend-tool-roundtrip": createBuiltInAgent(),

    // Reasoning demos — visible chain-of-thought via the reasoning adapter.
    "reasoning-custom": createAgenticChatReasoningAgent(),
    "reasoning-default": createReasoningDefaultRenderAgent(),
    "tool-rendering-reasoning-chain": createToolRenderingReasoningChainAgent(),
  },
  runner: new InMemoryAgentRunner(),
});

const handler = createCopilotRuntimeHandler({
  runtime,
  basePath: "/api/copilotkit",
  mode: "single-route",
});

async function withProbeCompat(req: Request): Promise<Response> {
  const res = await handler(req);
  if (res.status === 404) {
    const body = await res.text();
    return new Response(body, { status: 400, headers: res.headers });
  }
  return res;
}

const copilotkitPost = async (req: Request): Promise<Response> =>
  withForwardedHeaders(req, () => withProbeCompat(req));

export const GET = (req: Request) =>
  withForwardedHeaders(req, () => handler(req));
// Wrap POST with CVDIAG backend instrumentation (L1-E). built-in-agent runs
// its BuiltInAgent in-process inside this route handler. No-op pass-through
// unless CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
export const POST = withCvdiagBackend(copilotkitPost, {
  slug: "built-in-agent",
  agentName: "default",
  provider: "openai",
});
export const OPTIONS = (req: Request) =>
  withForwardedHeaders(req, () => handler(req));

/* HALCYON — a warm-paper editorial theme for CopilotChat.
 *
 * The point of this demo is to show how far a single stylesheet can take
 * CopilotChat away from the default look without touching components or
 * slots. Every selector is namespaced under `.chat-css-demo-scope` so this
 * theme cannot leak into the rest of the showcase.
 *
 * Two layers do the work:
 *   1. v2 token overrides on `[data-copilotkit]` recolor every Tailwind
 *      utility (cpk:bg-muted, cpk:text-foreground, cpk:border, …) the
 *      runtime relies on — see @copilotkit/react-core/v2/styles.css.
 *   2. Targeted class rules on `.copilotKitChat`, `.copilotKitMessage*`,
 *      and `.copilotKitInput` add the editorial details: parchment grain,
 *      corner brackets, serif voice, mono dispatch, ember accents.
 *
 * Class-name reference:
 *   https://docs.copilotkit.ai/custom-look-and-feel/customize-built-in-ui-components
 */

@import url("https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Instrument+Serif:ital@0;1&family=Inter+Tight:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap");

/* HALCYON palette — a private library at golden hour. The whole theme is
 * one warm parchment hue, one warm ink, and a deep copper ember used
 * sparingly so it actually reads as a signal. */
.chat-css-demo-scope {
  --halcyon-paper: #f4efe6;
  --halcyon-paper-soft: #ece6d9;
  --halcyon-paper-elevated: #fbf8f2;
  --halcyon-card: #ffffff;
  --halcyon-rule: #d6cfbe;
  --halcyon-rule-strong: #aea48a;
  --halcyon-ink: #1a1714;
  --halcyon-ink-soft: #3d362e;
  --halcyon-ink-mute: #7a7468;
  --halcyon-ember: #c44a1f;
  --halcyon-ember-bright: #e45f2b;
  --halcyon-ember-soft: #f3d7c5;
  --halcyon-champagne: #98794a;

  --halcyon-display:
    "Instrument Serif", ui-serif, "Iowan Old Style", Georgia, serif;
  --halcyon-serif:
    "Fraunces", "Source Serif Pro", ui-serif, Georgia, "Times New Roman", serif;
  --halcyon-sans:
    "Inter Tight", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  --halcyon-mono:
    "JetBrains Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --halcyon-shadow-soft:
    0 1px 0 rgba(26, 23, 20, 0.04), 0 12px 32px -18px rgba(26, 23, 20, 0.18);
  --halcyon-shadow-ember:
    0 1px 0 rgba(196, 74, 31, 0.18), 0 14px 36px -16px rgba(196, 74, 31, 0.42);
}

/* CopilotKit v2 reads these on the [data-copilotkit] root inside the chat.
 * Re-pointing them under our scope retints every Tailwind utility the
 * runtime renders (user message bubble, prose, borders, focus rings, …)
 * without us having to touch any individual class. */
.chat-css-demo-scope [data-copilotkit] {
  --background: var(--halcyon-paper);
  --foreground: var(--halcyon-ink);
  --card: var(--halcyon-card);
  --card-foreground: var(--halcyon-ink);
  --popover: var(--halcyon-paper-elevated);
  --popover-foreground: var(--halcyon-ink);
  --primary: var(--halcyon-ember);
  --primary-foreground: var(--halcyon-paper-elevated);
  --secondary: var(--halcyon-paper-soft);
  --secondary-foreground: var(--halcyon-ink);
  --muted: var(--halcyon-paper-soft);
  --muted-foreground: var(--halcyon-ink-mute);
  --accent: var(--halcyon-ember-soft);
  --accent-foreground: var(--halcyon-ember);
  --destructive: #b3361b;
  --destructive-foreground: var(--halcyon-paper-elevated);
  --border: var(--halcyon-rule);
  --input: var(--halcyon-rule);
  --ring: var(--halcyon-ember);
  --radius: 0px;
}

/* The chat surface — warm parchment with a single ambient ember glow,
 * a barely-perceptible paper grain via inline SVG noise, and architectural
 * corner brackets. Sharp 90° corners are deliberate; the default look is
 * rounded, so squaring everything off is the fastest visual signal that
 * "this is a different brand". */
.chat-css-demo-scope .copilotKitChat {
  font-family: var(--halcyon-sans);
  color: var(--halcyon-ink);
  background-color: var(--halcyon-paper);
  background-image:
    radial-gradient(
      900px 460px at 0% -10%,
      rgba(228, 95, 43, 0.14),
      transparent 62%
    ),
    radial-gradient(
      720px 380px at 100% 110%,
      rgba(152, 121, 74, 0.08),
      transparent 65%
    ),
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160' viewBox='0 0 160 160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.10 0 0 0 0 0.09 0 0 0 0 0.07 0 0 0 0.045 0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
  border: 1px solid var(--halcyon-rule);
  border-radius: 0;
  box-shadow: var(--halcyon-shadow-soft);
  position: relative;
  overflow: hidden;
}

/* The masthead label — a small mono bar pinned to the top of the surface,
 * playing against the editorial serif voice. Lives on ::before so it
 * tracks the chat root and shows in every state (welcome, mid-thread,
 * empty after clear). */
.chat-css-demo-scope .copilotKitChat::before {
  content: "CopilotChat  ·  Customized with CSS";
  position: absolute;
  top: 18px;
  left: 0;
  right: 0;
  text-align: center;
  font-family: var(--halcyon-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--halcyon-ink-mute);
  white-space: nowrap;
  pointer-events: none;
  z-index: 3;
}


/* The welcome screen — the page-one impression. The default heading is
 * sans-serif and tidy; we replace it with a large italic display serif
 * that wraps the question like a magazine cover line. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] {
  padding-top: 4rem;
}

.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1 {
  font-family: var(--halcyon-display);
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 400;
  font-style: italic;
  color: var(--halcyon-ink);
  letter-spacing: -0.02em;
  line-height: 1.05;
  text-align: center;
  margin: 0 auto 0.6rem;
  max-width: 22ch;
  position: relative;
}

/* A small mono eyebrow above the heading. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::before {
  content: "CopilotKit";
  display: block;
  font-family: var(--halcyon-mono);
  font-size: 11px;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: var(--halcyon-ember);
  margin-bottom: 1.2rem;
}

/* A short rule under the heading as a visual settle point. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::after {
  content: "";
  display: block;
  width: 36px;
  height: 1px;
  background: var(--halcyon-rule-strong);
  margin: 1.4rem auto 0;
}

.chat-css-demo-scope .copilotKitMessages {
  font-family: var(--halcyon-sans);
  background: transparent;
  color: var(--halcyon-ink);
  padding: 5rem 0 2rem;
  line-height: 1.6;
}

/* User message — a "transmission" in JetBrains Mono on a paper card. The
 * outer wrapper is the right-aligning flex column; we leave it transparent
 * and style the inner bubble (which uses cpk:bg-muted, hence we also
 * target the substring class as a stable hook). */
.chat-css-demo-scope .copilotKitMessage.copilotKitUserMessage {
  background: transparent;
  padding: 0;
  border: none;
  box-shadow: none;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitUserMessage
  > [class*="bg-muted"] {
  font-family: var(--halcyon-mono);
  font-size: 0.875rem;
  font-weight: 400;
  color: var(--halcyon-ink);
  background: var(--halcyon-paper-elevated);
  border: 1px solid var(--halcyon-rule);
  border-left: 2px solid var(--halcyon-ember);
  border-radius: 0;
  padding: 12px 16px 12px 18px;
  letter-spacing: -0.005em;
  line-height: 1.55;
  box-shadow: 0 1px 0 rgba(26, 23, 20, 0.03);
  position: relative;
}

/* A mono "→" marker before the user's text to read like a CLI prompt. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitUserMessage
  > [class*="bg-muted"]::before {
  content: "→";
  display: inline-block;
  margin-right: 10px;
  color: var(--halcyon-ember);
  font-weight: 500;
}

/* Assistant message — editorial Fraunces serif, no bubble, just generous
 * paragraphs offset by a thin ember rule on the left. Reads like the
 * voice of a publication, not a chatbot. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage {
  background: transparent;
  color: var(--halcyon-ink);
  font-family: var(--halcyon-serif);
  font-size: 1.0625rem;
  font-weight: 400;
  padding: 4px 0 4px 22px;
  border: none;
  border-radius: 0;
  margin-right: auto;
  margin-bottom: 1.25rem;
  max-width: 78ch;
  position: relative;
}

/* The editorial left rule. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage::before {
  content: "";
  position: absolute;
  top: 0.45em;
  bottom: 0.45em;
  left: 0;
  width: 1px;
  background: var(--halcyon-ember);
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose,
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose p {
  font-family: var(--halcyon-serif);
  font-size: inherit;
  color: inherit;
  line-height: 1.7;
  font-feature-settings: "ss01", "ss02", "ss03", "kern";
  margin: 0 0 0.85em;
}

/* Headings inside assistant content swap to the display serif so a long
 * answer reads like a structured article. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  :is(h1, h2, h3, h4) {
  font-family: var(--halcyon-display);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -0.015em;
  color: var(--halcyon-ink);
  margin: 1em 0 0.4em;
  line-height: 1.15;
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h1 {
  font-size: 2rem;
}
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h2 {
  font-size: 1.55rem;
}
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h3 {
  font-size: 1.25rem;
}

/* Lists — looser, with serif numerals. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  :is(ul, ol) {
  margin: 0.5em 0 1em;
  padding-left: 1.4em;
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose li {
  margin: 0.25em 0;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  ol
  > li::marker {
  color: var(--halcyon-ember);
  font-feature-settings: "tnum";
  font-weight: 500;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  ul
  > li::marker {
  color: var(--halcyon-ember);
}

/* Blockquote — pull-quote treatment in italic display serif. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  blockquote {
  border-left: 0;
  margin: 1.2em 0;
  padding: 0 0 0 1em;
  font-family: var(--halcyon-display);
  font-style: italic;
  font-size: 1.25em;
  color: var(--halcyon-ink-soft);
  position: relative;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  blockquote::before {
  content: "“";
  position: absolute;
  left: -0.05em;
  top: -0.4em;
  font-size: 2.4em;
  color: var(--halcyon-ember);
  line-height: 1;
}

/* Inline code — small ember chip on a tinted card. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose code {
  font-family: var(--halcyon-mono);
  font-size: 0.86em;
  font-weight: 500;
  color: var(--halcyon-ember);
  background: var(--halcyon-ember-soft);
  border: 1px solid color-mix(in srgb, var(--halcyon-ember) 22%, transparent);
  border-radius: 0;
  padding: 1px 6px;
}

/* Code block — dark ink card flipped against the parchment. The contrast
 * is deliberate; it reads like a code excerpt set in a printed book. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose pre,
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  div[data-streamdown="code-block"]
  > pre {
  background: var(--halcyon-ink) !important;
  color: #e8e2d5;
  border: 1px solid var(--halcyon-ink);
  border-radius: 0;
  padding: 14px 16px;
  margin: 1em 0;
  font-family: var(--halcyon-mono);
  font-size: 0.86em;
  line-height: 1.55;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    var(--halcyon-shadow-soft);
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  pre
  code {
  background: transparent;
  color: inherit;
  border: none;
  padding: 0;
}

/* Anchor links — ember underline in classic editorial style. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose a {
  color: var(--halcyon-ember);
  text-decoration-line: underline;
  text-decoration-color: color-mix(
    in srgb,
    var(--halcyon-ember) 35%,
    transparent
  );
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: text-decoration-color 160ms ease;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  a:hover {
  text-decoration-color: var(--halcyon-ember);
}

/* Horizontal rule — short, centered, ornament-like. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose hr {
  border: none;
  height: 1px;
  background: var(--halcyon-rule);
  width: 64px;
  margin: 1.6em auto;
}

/* Composer — a sharp paper card with an ember focus rule. The default
 * pill is rounded; squaring it off is again the visual cue that this is
 * a different brand. The wrapper around .copilotKitInput uses a fixed
 * white background in v2, so we override it directly. */
.chat-css-demo-scope .copilotKitInput {
  font-family: var(--halcyon-sans) !important;
  background: var(--halcyon-card) !important;
  border: 1px solid var(--halcyon-rule);
  border-radius: 0 !important;
  padding: 14px 16px;
  min-height: 56px;
  box-shadow:
    0 1px 0 rgba(26, 23, 20, 0.03),
    0 8px 24px -16px rgba(26, 23, 20, 0.18);
  transition:
    border-color 200ms ease,
    box-shadow 200ms ease,
    transform 120ms ease;
}

.chat-css-demo-scope .copilotKitInput:focus-within {
  border-color: var(--halcyon-ember);
  box-shadow:
    0 0 0 3px rgba(196, 74, 31, 0.12),
    0 1px 0 rgba(196, 74, 31, 0.18),
    0 14px 36px -16px rgba(196, 74, 31, 0.22);
  transform: translateY(-1px);
}

.chat-css-demo-scope .copilotKitInput textarea {
  font-family: var(--halcyon-sans) !important;
  font-size: 1rem;
  font-weight: 400;
  color: var(--halcyon-ink);
  line-height: 1.55;
  letter-spacing: -0.005em;
}

.chat-css-demo-scope .copilotKitInput textarea::placeholder {
  color: var(--halcyon-ink-mute);
  font-style: italic;
  opacity: 1;
}

/* The send button — a square ember chit, not the default circular pill.
 * v2 ships this as `<Button variant="chatInputToolbarPrimary"
 * size="chatInputToolbarIcon" data-testid="copilot-send-button">`, which
 * compiles to `cpk:bg-black cpk:text-white cpk:rounded-full cpk:h-9
 * cpk:w-9`. We override every one of those tokens so the brand wins. */
.chat-css-demo-scope button[data-testid="copilot-send-button"] {
  background-color: var(--halcyon-ember) !important;
  color: var(--halcyon-paper-elevated) !important;
  border: 1px solid var(--halcyon-ember) !important;
  border-radius: 2px !important;
  height: 36px !important;
  width: 36px !important;
  box-shadow: var(--halcyon-shadow-ember);
  transition:
    transform 150ms ease,
    box-shadow 150ms ease,
    background-color 150ms ease;
}

.chat-css-demo-scope button[data-testid="copilot-send-button"]:hover {
  background-color: var(--halcyon-ember-bright) !important;
  transform: translateY(-1px);
}

.chat-css-demo-scope button[data-testid="copilot-send-button"]:disabled {
  background-color: var(--halcyon-paper-soft) !important;
  color: var(--halcyon-ink-mute) !important;
  border-color: var(--halcyon-rule) !important;
  box-shadow: none;
  transform: none;
  opacity: 1 !important;
}

.chat-css-demo-scope button[data-testid="copilot-send-button"] svg {
  color: inherit;
}

/* Secondary input chrome (add-menu plus, mic, transcribe) — ghost squares
 * with an ember tint on hover. v2's `chatInputToolbarSecondary` variant
 * uses transparent bg + #444 text, which we re-tint to match the brand. */
.chat-css-demo-scope
  .copilotKitInput
  button:not([data-testid="copilot-send-button"]) {
  border-radius: 2px !important;
  color: var(--halcyon-ink-soft) !important;
  transition:
    color 150ms ease,
    background-color 150ms ease;
}

.chat-css-demo-scope
  .copilotKitInput
  button:not([data-testid="copilot-send-button"]):hover {
  color: var(--halcyon-ember) !important;
  background-color: var(--halcyon-ember-soft) !important;
}

/* Suggestion pills — sharp outlined chips, not rounded balloons. The
 * inner suggestion text uses the editorial mono so it reads like a
 * curated set of dispatch options. */
.chat-css-demo-scope [class*="copilotKitSuggestion"] {
  background: transparent;
  color: var(--halcyon-ink-soft);
  border: 1px solid var(--halcyon-rule);
  border-radius: 0;
  padding: 8px 14px;
  font-family: var(--halcyon-mono);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  transition:
    color 150ms ease,
    border-color 150ms ease,
    background 150ms ease,
    transform 150ms ease;
}

.chat-css-demo-scope [class*="copilotKitSuggestion"]:hover {
  color: var(--halcyon-ember);
  border-color: var(--halcyon-ember);
  background: var(--halcyon-ember-soft);
  transform: translateY(-1px);
}

.chat-css-demo-scope [data-copilotkit] ::-webkit-scrollbar {
  width: 4px;
}

.chat-css-demo-scope [data-copilotkit] ::-webkit-scrollbar-thumb {
  background: var(--halcyon-rule-strong);
  border-radius: 0;
}

.chat-css-demo-scope [data-copilotkit] ::-webkit-scrollbar-thumb:hover {
  background: var(--halcyon-ember);
}

.chat-css-demo-scope [data-copilotkit] * {
  scrollbar-width: thin;
  scrollbar-color: var(--halcyon-rule-strong) transparent;
}

.chat-css-demo-scope ::selection {
  background: var(--halcyon-ember-soft);
  color: var(--halcyon-ember);
}

/* A single, restrained entrance for the welcome screen — staggered fade-up
 * on the eyebrow / heading / rule. No infinite loops, no bouncy easing. */
@keyframes halcyon-rise {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1 {
  animation: halcyon-rise 700ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::before {
  animation: halcyon-rise 600ms cubic-bezier(0.2, 0.7, 0.2, 1) 80ms both;
}

@media (prefers-reduced-motion: reduce) {
  .chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1,
  .chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::before {
    animation: none;
  }
}

import { BuiltInAgent, convertInputToTanStackAI } from "@copilotkit/runtime/v2";
import type { TanStackChatMessage } from "@copilotkit/runtime/v2";
import { EventType } from "@ag-ui/client";
import type { BaseEvent } from "@ag-ui/client";
import { chat, toolDefinition } from "@tanstack/ai";
import { openaiText } from "@tanstack/ai-openai";
import { z } from "zod";
import { stateTools } from "./state-tools";
import { baseServerTools } from "./server-tools";
import { buildSubagentTools } from "./subagent-tools";
// Custom fetch that injects ALS-bound inbound x-* headers (e.g.
// x-aimock-context) onto every outbound OpenAI call. Required so aimock
// can match fixtures by integration context. See ../header-forwarding.ts
// for the full rationale; mirrors the Mastra precedent.
import { forwardingFetch } from "../header-forwarding";
import { DEMO_AGENT_LOOP_STRATEGY, throwOnRunError } from "./demo-stream";

/**
 * Convert a JSON Schema object to a Zod schema (shallow — handles the
 * common { type: "object", properties: {...} } shape that AG-UI tools
 * produce). Deep/recursive conversion is intentionally omitted: the
 * schema is only used for LLM tool-call declaration, not runtime
 * validation.
 */
// Exported so the OGUI and MCP-Apps factories can declare the tools that
// their runtime middleware injects into `input.tools` (see ogui-factory.ts /
// mcp-apps-factory.ts) without duplicating this conversion.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function jsonSchemaToZod(schema: any): z.ZodTypeAny {
  if (!schema || typeof schema !== "object") return z.object({});
  if (schema.type === "object" && schema.properties) {
    const shape: Record<string, z.ZodTypeAny> = {};
    const required = new Set<string>(schema.required ?? []);
    for (const [key, prop] of Object.entries(schema.properties)) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const p = prop as any;
      let field: z.ZodTypeAny;
      switch (p?.type) {
        case "string":
          field = z.string();
          break;
        case "number":
        case "integer":
          field = z.number();
          break;
        case "boolean":
          field = z.boolean();
          break;
        case "array":
          field = z.array(z.any());
          break;
        default:
          field = z.any();
      }
      if (p?.description) field = field.describe(p.description);
      shape[key] = required.has(key) ? field : field.optional();
    }
    return z.object(shape);
  }
  return z.object({});
}

function randomUUID(): string {
  return crypto.randomUUID();
}

/**
 * Convert a TanStack AI stream to AG-UI events.
 *
 * Unlike the runtime's built-in `convertTanStackStream`, this converter
 * does NOT stop processing after the first RUN_FINISHED event. TanStack's
 * chat() engine runs a multi-turn agent loop: after the model returns tool
 * calls with finish_reason=tool_calls, TanStack emits RUN_FINISHED,
 * executes server-side tools, emits TOOL_CALL_RESULT, then re-prompts the
 * model for a text response. The built-in runtime converter blocks all
 * events after RUN_FINISHED (PR #4476), which breaks server-tool execution
 * and subsequent text responses.
 *
 * This converter deduplicates tool-call events by tracking which
 * toolCallIds have already emitted TOOL_CALL_START. TanStack's
 * buildToolResultChunks re-emits TOOL_CALL_START/ARGS/END for server tool
 * results — we suppress the duplicate START/ARGS but keep the END and
 * RESULT events.
 */
// Exported for unit tests (tanstack-factory.test.ts) — the state-emission
// branches below are the only place a demo's left-hand panel gets its data, and
// they are easy to break silently.
export async function* convertStream(
  stream: AsyncIterable<unknown>,
  abortSignal: AbortSignal,
): AsyncGenerator<BaseEvent> {
  const messageId = randomUUID();
  // Track tool calls that have already emitted TOOL_CALL_END to suppress
  // duplicate START/ARGS/END from TanStack's buildToolResultChunks.
  // TOOL_CALL_RESULT is always emitted (it only comes from buildToolResultChunks).
  const completedToolCalls = new Set<string>();
  // Map toolCallId → toolName for state-tool detection on TOOL_CALL_RESULT.
  const toolNamesById = new Map<string, string>();
  // Accumulate streamed TOOL_CALL_ARGS per call so TOOL_CALL_RESULT can read
  // the call's `task` back out — the subagents delegation log needs the task
  // text, which only ever appears in the args, never in the result.
  const toolArgsById = new Map<string, string>();
  // Running `delegations` list for the subagents demo. Emitted whole on each
  // append (see the STATE_DELTA below for why it is not an RFC-6902 append).
  const delegations: Delegation[] = [];

  for await (const chunk of stream) {
    if (abortSignal.aborted) break;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const raw = chunk as any;
    const type = raw.type as string;

    // Fail loud on an upstream rejection — see ./demo-stream.
    throwOnRunError(raw);

    // Skip RUN_FINISHED from TanStack's adapter — the Agent class emits
    // its own lifecycle events.
    if (type === "RUN_FINISHED") continue;

    if (type === "TEXT_MESSAGE_CONTENT" && raw.delta != null) {
      yield {
        type: EventType.TEXT_MESSAGE_CHUNK,
        role: "assistant",
        messageId,
        delta: raw.delta as string,
      };
    } else if (type === "TOOL_CALL_START") {
      const toolCallId = raw.toolCallId as string;
      if (completedToolCalls.has(toolCallId)) {
        // Duplicate from buildToolResultChunks — skip.
        continue;
      }
      toolNamesById.set(toolCallId, raw.toolCallName as string);
      yield {
        type: EventType.TOOL_CALL_START,
        parentMessageId: messageId,
        toolCallId,
        toolCallName: raw.toolCallName as string,
      };
    } else if (type === "TOOL_CALL_ARGS") {
      const toolCallId = raw.toolCallId as string;
      if (completedToolCalls.has(toolCallId)) continue;
      toolArgsById.set(
        toolCallId,
        (toolArgsById.get(toolCallId) ?? "") + ((raw.delta as string) ?? ""),
      );
      yield {
        type: EventType.TOOL_CALL_ARGS,
        toolCallId,
        delta: raw.delta as string,
      };
    } else if (type === "TOOL_CALL_END") {
      const toolCallId = raw.toolCallId as string;
      if (completedToolCalls.has(toolCallId)) continue;
      completedToolCalls.add(toolCallId);
      yield {
        type: EventType.TOOL_CALL_END,
        toolCallId,
      };
    } else if (type === "TOOL_CALL_RESULT") {
      const toolCallId = raw.toolCallId as string;
      const toolName = toolNamesById.get(toolCallId);
      const rawPayload = raw.content ?? raw.result;
      const parsedContent =
        typeof rawPayload === "string" ? safeParseJSON(rawPayload) : rawPayload;

      // Detect state-snapshot tool results.
      if (
        toolName === "AGUISendStateSnapshot" &&
        parsedContent &&
        typeof parsedContent === "object" &&
        "snapshot" in parsedContent
      ) {
        yield {
          type: EventType.STATE_SNAPSHOT,
          snapshot: (parsedContent as { snapshot: unknown }).snapshot,
        };
      }
      if (
        toolName === "AGUISendStateDelta" &&
        parsedContent &&
        typeof parsedContent === "object" &&
        "delta" in parsedContent
      ) {
        yield {
          type: EventType.STATE_DELTA,
          delta: (parsedContent as { delta: unknown[] }).delta,
        };
      }
      // `set_steps` is the gen-ui-agent demo's custom plan tool (see
      // state-tools.ts). The tool's server handler returns `{ steps }`;
      // translate that into a STATE_DELTA that adds `/steps` on the
      // agent state, so the frontend `useAgent` subscriber sees the
      // plan update and `StepsPanel` mounts `agent-state-card`.
      //
      // Use RFC-6902 `add` (not `replace`): the agent's initial state is
      // `{}` (no STATE_SNAPSHOT precedes the first STATE_DELTA), and
      // `fast-json-patch` in strict mode rejects `replace` on an
      // unresolvable path with OPERATION_PATH_UNRESOLVABLE.
      // `@ag-ui/client@0.0.57` swallows that throw with `console.warn`
      // and never updates state, so `replace` results in the panel
      // staying in its placeholder. `add` creates `/steps` on first
      // emission and idempotently overwrites on subsequent calls.
      if (
        toolName === "set_steps" &&
        parsedContent &&
        typeof parsedContent === "object" &&
        "steps" in parsedContent
      ) {
        yield {
          type: EventType.STATE_DELTA,
          delta: [
            {
              op: "add",
              path: "/steps",
              value: (parsedContent as { steps: unknown }).steps,
            },
          ],
        };
      }
      // `set_notes` is the shared-state-read-write demo's agent-authored
      // notes tool (see server-tools.ts). Its server handler returns
      // `{ notes }`; translate that into a STATE_DELTA that adds `/notes`
      // on the agent state, so the frontend `useAgent` subscriber sees the
      // update and the notes card (`notes-list` / `note-item`) populates.
      //
      // Same RFC-6902 `add`-not-`replace` rationale as `set_steps` above:
      // the agent's initial state carries no `/notes` snapshot before the
      // first delta, and `fast-json-patch` strict mode rejects `replace` on
      // an unresolvable path (OPERATION_PATH_UNRESOLVABLE), which
      // `@ag-ui/client` swallows with a console.warn and never applies —
      // leaving the panel in its placeholder. `add` creates `/notes` on the
      // first emission and idempotently overwrites on subsequent calls.
      if (
        toolName === "set_notes" &&
        parsedContent &&
        typeof parsedContent === "object" &&
        "notes" in parsedContent
      ) {
        yield {
          type: EventType.STATE_DELTA,
          delta: [
            {
              op: "add",
              path: "/notes",
              value: (parsedContent as { notes: unknown }).notes,
            },
          ],
        };
      }

      // Sub-agent delegation results (subagents demo). `buildSubagentTools`
      // exposes `research_agent` / `writing_agent` / `critique_agent`, each
      // returning `{ role, text }`. The frontend
      // (`demos/subagents/page.tsx`) renders `agent.state.delegations` in the
      // left-hand log — but nothing here used to emit that slot, so the tools
      // ran, the chat filled in, and the panel stayed empty forever. The
      // reference declares `delegations` on its agent state with an
      // `operator.add` reducer (`langgraph-python/src/agents/subagents.py`);
      // this is the equivalent for a runtime with no per-agent state schema.
      //
      // Emitted as a whole-array `add` rather than an RFC-6902 `/-` append for
      // the same reason `set_steps` below uses `add`: the agent's initial
      // state is `{}`, so an append into a not-yet-existent `/delegations`
      // array is an unresolvable path. `fast-json-patch` strict mode rejects
      // it and `@ag-ui/client` swallows the throw with a console.warn, which
      // would leave the panel in its placeholder — exactly the bug being
      // fixed. `add` creates the array on the first result and overwrites it
      // with the grown list on each subsequent one.
      if (toolName && SUBAGENT_TOOL_NAMES.has(toolName)) {
        delegations.push({
          id: toolCallId,
          sub_agent: toolName,
          task: extractTask(toolArgsById.get(toolCallId)),
          status: "completed",
          result: extractResultText(parsedContent),
        });
        yield {
          type: EventType.STATE_DELTA,
          delta: [{ op: "add", path: "/delegations", value: [...delegations] }],
        };
      }

      let serializedContent: string;
      if (typeof rawPayload === "string") {
        serializedContent = rawPayload;
      } else {
        try {
          serializedContent = JSON.stringify(rawPayload ?? null);
        } catch {
          serializedContent = "[Unserializable tool result]";
        }
      }

      yield {
        type: EventType.TOOL_CALL_RESULT,
        role: "tool",
        messageId: randomUUID(),
        toolCallId,
        content: serializedContent,
      };
    }
    // All other event types (CUSTOM, STEP_FINISHED, etc.) are silently
    // ignored — the runtime does not need them.
  }
}

function safeParseJSON(value: string): unknown {
  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

/**
 * Delegation-log entry shape. Mirrors `Delegation` in
 * `demos/subagents/delegation-log.tsx` (and the reference's `Delegation`
 * TypedDict) — the frontend reads `sub_agent`, `task`, `status`, `result`.
 */
type Delegation = {
  id: string;
  sub_agent: string;
  task: string;
  status: "completed";
  result: string;
};

/** Tool names `buildSubagentTools` exposes; kept in sync with `subagentRoles`. */
const SUBAGENT_TOOL_NAMES = new Set([
  "research_agent",
  "writing_agent",
  "critique_agent",
]);

/**
 * Pull `task` out of the accumulated TOOL_CALL_ARGS JSON. Args stream in as
 * deltas and a run can be cut short mid-call, so a partial/unparseable buffer
 * is expected rather than exceptional — fall back to an empty task and let the
 * log render the entry without it.
 */
function extractTask(argsJson: string | undefined): string {
  if (!argsJson) return "";
  const parsed = safeParseJSON(argsJson);
  if (parsed && typeof parsed === "object" && "task" in parsed) {
    const task = (parsed as { task: unknown }).task;
    if (typeof task === "string") return task;
  }
  return "";
}

/** Read the sub-agent's prose out of its `{ role, text }` result. */
function extractResultText(parsedContent: unknown): string {
  if (parsedContent && typeof parsedContent === "object") {
    const text = (parsedContent as { text?: unknown }).text;
    if (typeof text === "string") return text;
  }
  return typeof parsedContent === "string" ? parsedContent : "";
}

/**
 * Options for {@link createBuiltInAgent}. All fields are OPT-IN — omitting them
 * (the default for every demo except multimodal) preserves the base agent's
 * behaviour byte-for-byte.
 */
export interface BuiltInAgentOptions {
  /**
   * Async hook to rewrite the converted TanStack messages before they reach
   * the model. Used by the multimodal factory to flatten PDF `document`
   * content parts to text server-side (the OpenAI text adapter cannot consume
   * `document` parts and drops the turn otherwise). Left undefined by default.
   */
  preprocessMessages?: (
    messages: TanStackChatMessage[],
  ) => TanStackChatMessage[] | Promise<TanStackChatMessage[]>;
  /**
   * Per-demo system prompt, prepended ahead of the frontend-supplied
   * `systemPrompts`.
   *
   * The north-star reference wires each demo to its own graph with its own
   * prompt (28 graphs in `langgraph-python/langgraph.json`). This integration
   * shares ONE agent across ~20 demos, so without this option a demo whose
   * behaviour depends on being *told* what to do has nothing driving it. The
   * aimock fixtures hide that — they replay a scripted tool-call sequence
   * keyed on `userMessage` + `context`, so D6 goes green whether or not the
   * model could have reasoned its way there (showcase/GOTCHAS.md #8).
   *
   * Live symptoms this exists to prevent: `gen-ui-tool-based` answering
   * "I used placeholder values since no sales figures were provided" and
   * plotting zeros; `gen-ui-agent` publishing its plan once and then
   * narrating instead of walking the steps.
   */
  systemPrompt?: string;
}

export function createBuiltInAgent(options: BuiltInAgentOptions = {}) {
  return new BuiltInAgent({
    // Use "custom" to bypass the runtime's convertTanStackStream which
    // has a runFinished flag (PR #4476) that blocks all events after the
    // first RUN_FINISHED. This breaks the multi-turn agent loop needed
    // for server-tool execution (tool-rendering, shared-state).
    type: "custom",
    factory: async ({ input, abortController }) => {
      const { messages: convertedMessages, systemPrompts } =
        convertInputToTanStackAI(input);
      // Opt-in message rewrite (multimodal PDF flatten). Default: pass-through.
      const messages = options.preprocessMessages
        ? await options.preprocessMessages(convertedMessages)
        : convertedMessages;
      // Subagent tools are built per-run so their nested chat() calls
      // abort with the parent.
      const subagentTools = buildSubagentTools(abortController);

      const serverTools = [...stateTools, ...baseServerTools, ...subagentTools];

      // Collect server-side tool names so we can skip frontend tools
      // that shadow them (e.g. get_weather has both a server executor
      // and a useRenderTool on the frontend).
      const serverToolNames = new Set(serverTools.map((t) => t.name));

      // Convert AG-UI frontend tools (useHumanInTheLoop, useRenderTool,
      // useFrontendTool) to TanStack definition-only tool declarations.
      // TanStack's chat() treats these as "needs client execution" and
      // pauses the agent loop, allowing the CopilotKit frontend SDK to
      // handle them.
      const frontendTools = (input.tools ?? [])
        .filter((t) => !serverToolNames.has(t.name))
        .map((t) =>
          toolDefinition({
            name: t.name,
            description: t.description ?? "",
            inputSchema: jsonSchemaToZod(t.parameters),
          }),
        );

      const stream = chat({
        // Inject forwardingFetch so the OpenAI client picks up inbound
        // x-* headers (e.g. x-aimock-context) bound into ALS by the
        // route handler. Without this, /v1/responses calls to aimock
        // miss every fixture (404) and the D6 subset goes 0/6.
        adapter: openaiText("gpt-5.4", { fetch: forwardingFetch }),
        messages,
        systemPrompts: options.systemPrompt
          ? [options.systemPrompt, ...systemPrompts]
          : systemPrompts,
        tools: [...serverTools, ...frontendTools],
        abortController,
        agentLoopStrategy: DEMO_AGENT_LOOP_STRATEGY,
      });

      return convertStream(stream, abortController.signal);
    },
  });
}

