"use client";

// Tool Rendering — CUSTOM CATCH-ALL variant (middle of the progression).
//
// Same backend tools as `tool-rendering-default-catchall`, but this
// cell opts out of CopilotKit's built-in default tool-call UI by
// registering a SINGLE custom wildcard renderer via
// `useDefaultRenderTool`. The same branded card now paints every tool
// call — no per-tool renderers yet.

import React from "react";
import {
  CopilotKit,
  CopilotChat,
  useDefaultRenderTool,
} from "@copilotkit/react-core/v2";
import { CustomCatchallRenderer } from "./custom-catchall-renderer";
import type { CatchallToolStatus } from "./custom-catchall-renderer";
import { useSuggestions } from "./suggestions";

export default function ToolRenderingCustomCatchallDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit"
      agent="tool-rendering-custom-catchall"
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  // `useDefaultRenderTool` is a convenience wrapper around
  // `useRenderTool({ name: "*", ... })` — a single wildcard renderer
  // that handles every tool call not claimed by a named renderer.
  useDefaultRenderTool(
    {
      render: ({ name, parameters, status, result }) => (
        <CustomCatchallRenderer
          name={name}
          parameters={parameters}
          status={status as CatchallToolStatus}
          result={result}
        />
      ),
    },
    [],
  );

  useSuggestions();

  return (
    <CopilotChat
      agentId="tool-rendering-custom-catchall"
      className="h-full rounded-2xl"
    />
  );
}

import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
  InMemoryAgentRunner,
} from "@copilotkit/runtime/v2";
import { createBuiltInAgent } from "@/lib/factory/tanstack-factory";
// Per-demo system prompts, ported from the reference's dedicated graphs. The
// demos below that pass one are those whose behaviour the model has to be told
// (walk a plan, invent sample chart data, delegate to sub-agents); the rest are
// genuinely prompt-neutral. See demo-prompts.ts.
import {
  GEN_UI_AGENT_PROMPT,
  GEN_UI_TOOL_BASED_PROMPT,
  SUBAGENTS_PROMPT,
} from "@/lib/factory/demo-prompts";
import { createAgenticChatAgent } from "@/lib/factory/agentic-chat-factory";
import {
  createAgenticChatReasoningAgent,
  createReasoningDefaultRenderAgent,
  createToolRenderingReasoningChainAgent,
} from "@/lib/factory/reasoning-factory";
// `withForwardedHeaders` snapshots inbound x-* headers (e.g.
// x-aimock-context) into an AsyncLocalStorage scope so the wrapped
// OpenAI client's custom fetch can re-attach them on every outbound
// LLM call. Required because `@tanstack/ai-openai`'s `openaiText()`
// adapter has no per-request header hook of its own.
import { withForwardedHeaders } from "@/lib/header-forwarding";
// CVDIAG backend instrumentation (L1-E). No-op pass-through unless
// CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
import { withCvdiagBackend } from "@/cvdiag-backend";

const runtime = new CopilotRuntime({
  agents: {
    // Catch-all agent retained during the LGP-parity migration.
    default: createBuiltInAgent(),

    // Per-demo named agents resolved by the byte-identical LGP frontends via
    // `agent="<id>"` on `/api/copilotkit`. The generic `createBuiltInAgent()`
    // carries the full server/state/subagent tool surface; per-demo behavior
    // is driven by the aimock fixture (same contract the old `default`-routed
    // demos relied on), so the chat-UI / tool / state / HITL / gen-UI demos
    // share it. Reasoning demos use the reasoning adapter factory.
    agentic_chat: createAgenticChatAgent(),

    "chat-customization-css": createBuiltInAgent(),
    "chat-slots": createBuiltInAgent(),
    "prebuilt-popup": createBuiltInAgent(),
    "prebuilt-sidebar": createBuiltInAgent(),
    "headless-simple": createBuiltInAgent(),

    frontend_tools: createBuiltInAgent(),
    "frontend-tools-async": createBuiltInAgent(),

    "tool-rendering": createBuiltInAgent(),
    "tool-rendering-default-catchall": createBuiltInAgent(),
    "tool-rendering-custom-catchall": createBuiltInAgent(),

    "gen-ui-agent": createBuiltInAgent({ systemPrompt: GEN_UI_AGENT_PROMPT }),
    "gen-ui-tool-based": createBuiltInAgent({
      systemPrompt: GEN_UI_TOOL_BASED_PROMPT,
    }),
    "gen-ui-interrupt": createBuiltInAgent(),
    "interrupt-headless": createBuiltInAgent(),

    human_in_the_loop: createBuiltInAgent(),
    "hitl-in-chat": createBuiltInAgent(),
    "hitl-in-app": createBuiltInAgent(),

    "shared-state-read": createBuiltInAgent(),
    "shared-state-read-write": createBuiltInAgent(),
    "shared-state-streaming": createBuiltInAgent(),
    "readonly-state-agent-context": createBuiltInAgent(),

    subagents: createBuiltInAgent({ systemPrompt: SUBAGENTS_PROMPT }),
    "threadid-frontend-tool-roundtrip": createBuiltInAgent(),

    // Reasoning demos — visible chain-of-thought via the reasoning adapter.
    "reasoning-custom": createAgenticChatReasoningAgent(),
    "reasoning-default": createReasoningDefaultRenderAgent(),
    "tool-rendering-reasoning-chain": createToolRenderingReasoningChainAgent(),
  },
  runner: new InMemoryAgentRunner(),
});

const handler = createCopilotRuntimeHandler({
  runtime,
  basePath: "/api/copilotkit",
  mode: "single-route",
});

async function withProbeCompat(req: Request): Promise<Response> {
  const res = await handler(req);
  if (res.status === 404) {
    const body = await res.text();
    return new Response(body, { status: 400, headers: res.headers });
  }
  return res;
}

const copilotkitPost = async (req: Request): Promise<Response> =>
  withForwardedHeaders(req, () => withProbeCompat(req));

export const GET = (req: Request) =>
  withForwardedHeaders(req, () => handler(req));
// Wrap POST with CVDIAG backend instrumentation (L1-E). built-in-agent runs
// its BuiltInAgent in-process inside this route handler. No-op pass-through
// unless CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
export const POST = withCvdiagBackend(copilotkitPost, {
  slug: "built-in-agent",
  agentName: "default",
  provider: "openai",
});
export const OPTIONS = (req: Request) =>
  withForwardedHeaders(req, () => handler(req));

import * as React from "react";

// Inline-cloned shadcn/ui <Badge />. Plain Tailwind classes — no `cn()`,
// no `cva`. Local to this demo only.

type Variant = "default" | "secondary" | "outline" | "success" | "warning";

const variantClasses: Record<Variant, string> = {
  default: "border-transparent bg-neutral-900 text-neutral-50",
  secondary: "border-transparent bg-neutral-100 text-neutral-700",
  outline: "border-neutral-200 text-neutral-900",
  success: "border-transparent bg-emerald-100 text-emerald-700",
  warning: "border-transparent bg-amber-100 text-amber-700",
};

export interface BadgeProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: Variant;
}

export function Badge({
  className = "",
  variant = "default",
  ...props
}: BadgeProps) {
  return (
    <div
      className={`inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] font-medium uppercase tracking-wider transition-colors ${variantClasses[variant]} ${className}`}
      {...props}
    />
  );
}

import * as React from "react";

// Inline-cloned shadcn/ui <Card /> primitives. Hand-written with plain
// Tailwind classes — no `cn()` helper, no `cva`, no Radix primitives.
// Local to this demo only.

export const Card = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className = "", ...props }, ref) => (
  <div
    ref={ref}
    className={`rounded-xl border border-neutral-200 bg-white text-neutral-950 shadow-sm ${className}`}
    {...props}
  />
));
Card.displayName = "Card";

export const CardHeader = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className = "", ...props }, ref) => (
  <div
    ref={ref}
    className={`flex flex-col space-y-1.5 p-4 ${className}`}
    {...props}
  />
));
CardHeader.displayName = "CardHeader";

export const CardTitle = React.forwardRef<
  HTMLHeadingElement,
  React.HTMLAttributes<HTMLHeadingElement>
>(({ className = "", ...props }, ref) => (
  <h3
    ref={ref}
    className={`text-sm font-semibold leading-none tracking-tight text-neutral-900 ${className}`}
    {...props}
  />
));
CardTitle.displayName = "CardTitle";

export const CardDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className = "", ...props }, ref) => (
  <p ref={ref} className={`text-xs text-neutral-500 ${className}`} {...props} />
));
CardDescription.displayName = "CardDescription";

export const CardContent = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className = "", ...props }, ref) => (
  <div ref={ref} className={`p-4 pt-0 ${className}`} {...props} />
));
CardContent.displayName = "CardContent";

"use client";

import React from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "./_components/card";
import { Badge } from "./_components/badge";

// ShadCN-styled catch-all renderer for the tool-rendering-custom-catchall
// cell. A single wildcard renderer handles every tool call — name,
// status, arguments, and result rendered inside a shadcn <Card />.

export type CatchallToolStatus = "inProgress" | "executing" | "complete";

export interface CustomCatchallRendererProps {
  name: string;
  status: CatchallToolStatus;
  parameters: unknown;
  result: string | undefined;
}

export function CustomCatchallRenderer({
  name,
  status,
  parameters,
  result,
}: CustomCatchallRendererProps) {
  const parsedResult = parseResult(result);
  const done = status === "complete";

  return (
    <Card
      data-testid="custom-wildcard-card"
      data-tool-name={name}
      data-status={status}
      className="my-3 overflow-hidden"
    >
      <CardHeader className="flex flex-row items-center justify-between space-y-0 border-b border-neutral-200 bg-neutral-50/60 py-3">
        <div className="flex items-center gap-2">
          <CardTitle
            data-testid="custom-wildcard-tool-name"
            className="font-mono text-sm text-neutral-900"
          >
            {name}
          </CardTitle>
          <CardDescription className="text-[10px] uppercase tracking-wider text-neutral-500">
            tool call
          </CardDescription>
        </div>
        <StatusBadge status={status} />
      </CardHeader>

      <CardContent className="grid gap-3 p-4 text-sm">
        <Section label="Arguments">
          <pre
            data-testid="custom-wildcard-args"
            className="overflow-x-auto rounded-md border border-neutral-200 bg-neutral-50 p-2.5 font-mono text-xs text-neutral-900"
          >
            {safeStringify(parameters)}
          </pre>
        </Section>

        <Section label="Result">
          {done ? (
            <pre
              data-testid="custom-wildcard-result"
              className="overflow-x-auto rounded-md border border-emerald-200 bg-emerald-50 p-2.5 font-mono text-xs text-neutral-900"
            >
              {parsedResult !== undefined
                ? safeStringify(parsedResult)
                : "(empty)"}
            </pre>
          ) : (
            <p className="text-xs italic text-neutral-500">
              waiting for tool to finish…
            </p>
          )}
        </Section>
      </CardContent>
    </Card>
  );
}

function Section({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div>
      <div className="mb-1.5 text-[10px] font-medium uppercase tracking-wider text-neutral-500">
        {label}
      </div>
      {children}
    </div>
  );
}

function StatusBadge({ status }: { status: CatchallToolStatus }) {
  const { label, variant, dot } = describeStatus(status);
  return (
    <Badge data-testid="custom-wildcard-status" variant={variant}>
      <span
        className={`inline-block h-1.5 w-1.5 rounded-full ${dot}`}
        aria-hidden
      />
      {label}
    </Badge>
  );
}

function describeStatus(status: CatchallToolStatus): {
  label: string;
  variant: "warning" | "secondary" | "success";
  dot: string;
} {
  switch (status) {
    case "inProgress":
      return {
        label: "streaming",
        variant: "warning",
        dot: "bg-amber-500 animate-pulse",
      };
    case "executing":
      return {
        label: "running",
        variant: "secondary",
        dot: "bg-neutral-500 animate-pulse",
      };
    case "complete":
      return {
        label: "done",
        variant: "success",
        dot: "bg-emerald-500",
      };
  }
}

function parseResult(result: string | undefined): unknown {
  if (result === undefined || result === null) return undefined;
  if (typeof result !== "string") return result;
  try {
    return JSON.parse(result);
  } catch {
    return result;
  }
}

function safeStringify(value: unknown): string {
  try {
    return JSON.stringify(value, null, 2);
  } catch {
    return String(value);
  }
}

"use client";

