"use client";

import React from "react";

export interface WeatherCardProps {
  loading: boolean;
  location: string;
  temperature?: number;
  humidity?: number;
  windSpeed?: number;
  conditions?: string;
}

export function WeatherCard({
  loading,
  location,
  temperature,
  humidity,
  windSpeed,
  conditions,
}: WeatherCardProps) {
  return (
    <div
      data-testid="weather-card"
      className="rounded-2xl mt-4 mb-4 max-w-md w-full bg-[#EDEDF5] border border-[#DBDBE5] text-[#010507] shadow-sm"
    >
      <div className="p-5">
        <div className="flex items-start justify-between gap-4">
          <div>
            <div className="text-[10px] uppercase tracking-[0.14em] text-[#57575B] mb-1">
              Current weather
            </div>
            <h3
              data-testid="weather-city"
              className="text-xl font-semibold capitalize text-[#010507]"
            >
              {location || "Weather"}
            </h3>
            <p className="text-[#57575B] text-sm mt-0.5">
              {loading ? "Fetching weather..." : conditions || "—"}
            </p>
          </div>
          <div className="text-4xl leading-none" aria-hidden>
            {loading ? "..." : conditionsEmoji(conditions)}
          </div>
        </div>

        {!loading && (
          <>
            <div className="mt-5 text-4xl font-semibold text-[#010507] tracking-tight">
              {temperature ?? "--"}&deg;
              <span className="ml-1 text-lg font-normal text-[#57575B]">F</span>
            </div>
            <div className="mt-5 pt-4 border-t border-[#DBDBE5] grid grid-cols-2 gap-3 text-sm">
              <div data-testid="weather-humidity">
                <p className="text-[10px] uppercase tracking-[0.14em] text-[#57575B]">
                  Humidity
                </p>
                <p className="mt-1 font-medium text-[#010507]">
                  {humidity ?? "--"}%
                </p>
              </div>
              <div data-testid="weather-wind">
                <p className="text-[10px] uppercase tracking-[0.14em] text-[#57575B]">
                  Wind
                </p>
                <p className="mt-1 font-medium text-[#010507]">
                  {windSpeed ?? "--"} mph
                </p>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function conditionsEmoji(conditions?: string): string {
  if (!conditions) return "";
  const c = conditions.toLowerCase();
  if (c.includes("sun") || c.includes("clear")) return "sun";
  if (c.includes("rain") || c.includes("storm")) return "rain";
  if (c.includes("cloud")) return "cloud";
  if (c.includes("snow")) return "snow";
  return "";
}

import { z } from "zod";
import { toolDefinition } from "@tanstack/ai";

export const weatherTool = toolDefinition({
  name: "weather",
  description: "Get current weather for a city",
  inputSchema: z.object({
    city: z.string(),
  }),
}).server(async ({ city }) => ({
  city,
  tempF: 72,
  condition: "Partly cloudy",
  humidity: 0.45,
}));

export const haikuTool = toolDefinition({
  name: "haiku",
  description: "Generate a haiku about a topic",
  inputSchema: z.object({
    topic: z.string(),
  }),
}).server(async ({ topic }) => ({
  topic,
  lines: [
    "Lines on a topic",
    `Eight syllables, on ${topic}`,
    "Then five at the close",
  ],
}));

// Mock travel-and-lifestyle tools used by the tool-rendering demos
// (default-catchall, custom-catchall). They return fake data so the LLM
// can chain them liberally to surface multiple tool-call cards per turn.

export const getWeatherTool = toolDefinition({
  name: "get_weather",
  description:
    "Get the current weather for a given location. Pairs naturally " +
    "with search_flights — when a city is mentioned, also consider " +
    "looking up flights there.",
  inputSchema: z.object({
    location: z.string(),
  }),
}).server(async ({ location }) => ({
  city: location,
  temperature: 68,
  humidity: 55,
  wind_speed: 10,
  conditions: "Sunny",
}));

export const searchFlightsTool = toolDefinition({
  name: "search_flights",
  description:
    "Search mock flights from an origin airport to a destination " +
    "airport. When the user mentions a city without a matching origin, " +
    "default the origin to 'SFO'.",
  inputSchema: z.object({
    origin: z.string(),
    destination: z.string(),
  }),
}).server(async ({ origin, destination }) => ({
  origin,
  destination,
  flights: [
    {
      airline: "United",
      flight: "UA231",
      depart: "08:15",
      arrive: "16:45",
      price_usd: 348,
    },
    {
      airline: "Delta",
      flight: "DL412",
      depart: "11:20",
      arrive: "19:55",
      price_usd: 312,
    },
    {
      airline: "JetBlue",
      flight: "B6722",
      depart: "17:05",
      arrive: "01:30",
      price_usd: 289,
    },
  ],
}));

export const getStockPriceTool = toolDefinition({
  name: "get_stock_price",
  description:
    "Get a mock current price for a stock ticker. Consider also " +
    "pulling a related ticker for comparison context.",
  inputSchema: z.object({
    ticker: z.string(),
  }),
}).server(async ({ ticker }) => {
  const price = Math.round((100 + Math.random() * 400) * 100) / 100;
  const change = Math.round((Math.random() * 6 - 3) * 100) / 100;
  return {
    ticker: ticker.toUpperCase(),
    price_usd: price,
    change_pct: change,
  };
});

// Mock revenue chart for the headless-complete demo's "Revenue chart"
// pill. Returns six months of quarterly revenue data so the
// `get_revenue_chart` tool result drives the ChartCard renderer with a
// deterministic shape (label/value pairs, peaking in June). Mirrors the
// LangGraph Python reference agent's `get_revenue_chart` tool.
export const getRevenueChartTool = toolDefinition({
  name: "get_revenue_chart",
  description:
    "Get a mock chart of quarterly revenue over the last six months. " +
    "Returns label/value points (one per month, Jan–Jun) plus a title " +
    "and subtitle so the client can render a bar chart.",
  inputSchema: z.object({}),
}).server(async () => ({
  title: "Quarterly revenue",
  subtitle: "USD thousands",
  data: [
    { label: "Jan", value: 42 },
    { label: "Feb", value: 51 },
    { label: "Mar", value: 58 },
    { label: "Apr", value: 64 },
    { label: "May", value: 73 },
    { label: "Jun", value: 81 },
  ],
}));

export const rollD20Tool = toolDefinition({
  name: "roll_d20",
  description: "Roll a single die with the given number of sides.",
  inputSchema: z.object({
    sides: z.number().int().min(2).default(6),
  }),
}).server(async ({ sides }) => ({
  sides,
  result: Math.floor(Math.random() * Math.max(2, sides)) + 1,
}));

// Tool for the shared-state-read-write demo. The `set_notes` tool
// updates the `notes` slot in shared state, mirroring the LangGraph
// Python reference agent's `set_notes` tool. The actual state mutation
// happens client-side when the tool result is returned; here we just
// echo the notes back so the runtime/frontend can handle it.
export const setNotesTool = toolDefinition({
  name: "set_notes",
  description:
    "Replace the notes array in shared state with the full updated list. " +
    "Use this tool whenever the user asks you to 'remember' something, or " +
    "when you have an observation about the user worth surfacing in the " +
    "UI's notes panel. Always pass the FULL notes list (existing notes + " +
    "any new ones), not a diff. Keep each note short (< 120 chars).",
  inputSchema: z.object({
    notes: z.array(z.string()).describe("The complete updated list of notes"),
  }),
}).server(async ({ notes }) => ({ success: true, notes }));

export const baseServerTools = [
  weatherTool,
  haikuTool,
  getWeatherTool,
  searchFlightsTool,
  getStockPriceTool,
  getRevenueChartTool,
  rollD20Tool,
  setNotesTool,
] as const;

