"use client";

// Reasoning — Default
//
// Pairs with `reasoning-custom` (the Custom variant) so users can
// compare default vs custom reasoning rendering side by side. This cell
// renders <CopilotChat> with NO slot override — reasoning messages are
// rendered by the built-in `CopilotChatReasoningMessage` component
// (Thinking… / Thought for X header with an expandable content region).
//
// Both demos share the same backend (`reasoning_agent` graph) and the
// same runtime URL (/api/copilotkit). The only difference is whether the
// `messageView.reasoningMessage` slot is overridden.

import { CopilotKit, CopilotChat } from "@copilotkit/react-core/v2";
import { useReasoningDefaultSuggestions } from "./suggestions";

const AGENT_ID = "reasoning-default";

export default function ReasoningDefaultDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent={AGENT_ID}>
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  useReasoningDefaultSuggestions();
  return <CopilotChat agentId={AGENT_ID} className="h-full rounded-2xl" />;
}

import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
  InMemoryAgentRunner,
} from "@copilotkit/runtime/v2";
import { createBuiltInAgent } from "@/lib/factory/tanstack-factory";
// Per-demo system prompts, ported from the reference's dedicated graphs. The
// demos below that pass one are those whose behaviour the model has to be told
// (walk a plan, invent sample chart data, delegate to sub-agents); the rest are
// genuinely prompt-neutral. See demo-prompts.ts.
import {
  GEN_UI_AGENT_PROMPT,
  GEN_UI_TOOL_BASED_PROMPT,
  SUBAGENTS_PROMPT,
} from "@/lib/factory/demo-prompts";
import { createAgenticChatAgent } from "@/lib/factory/agentic-chat-factory";
import {
  createAgenticChatReasoningAgent,
  createReasoningDefaultRenderAgent,
  createToolRenderingReasoningChainAgent,
} from "@/lib/factory/reasoning-factory";
// `withForwardedHeaders` snapshots inbound x-* headers (e.g.
// x-aimock-context) into an AsyncLocalStorage scope so the wrapped
// OpenAI client's custom fetch can re-attach them on every outbound
// LLM call. Required because `@tanstack/ai-openai`'s `openaiText()`
// adapter has no per-request header hook of its own.
import { withForwardedHeaders } from "@/lib/header-forwarding";
// CVDIAG backend instrumentation (L1-E). No-op pass-through unless
// CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
import { withCvdiagBackend } from "@/cvdiag-backend";

const runtime = new CopilotRuntime({
  agents: {
    // Catch-all agent retained during the LGP-parity migration.
    default: createBuiltInAgent(),

    // Per-demo named agents resolved by the byte-identical LGP frontends via
    // `agent="<id>"` on `/api/copilotkit`. The generic `createBuiltInAgent()`
    // carries the full server/state/subagent tool surface; per-demo behavior
    // is driven by the aimock fixture (same contract the old `default`-routed
    // demos relied on), so the chat-UI / tool / state / HITL / gen-UI demos
    // share it. Reasoning demos use the reasoning adapter factory.
    agentic_chat: createAgenticChatAgent(),

    "chat-customization-css": createBuiltInAgent(),
    "chat-slots": createBuiltInAgent(),
    "prebuilt-popup": createBuiltInAgent(),
    "prebuilt-sidebar": createBuiltInAgent(),
    "headless-simple": createBuiltInAgent(),

    frontend_tools: createBuiltInAgent(),
    "frontend-tools-async": createBuiltInAgent(),

    "tool-rendering": createBuiltInAgent(),
    "tool-rendering-default-catchall": createBuiltInAgent(),
    "tool-rendering-custom-catchall": createBuiltInAgent(),

    "gen-ui-agent": createBuiltInAgent({ systemPrompt: GEN_UI_AGENT_PROMPT }),
    "gen-ui-tool-based": createBuiltInAgent({
      systemPrompt: GEN_UI_TOOL_BASED_PROMPT,
    }),
    "gen-ui-interrupt": createBuiltInAgent(),
    "interrupt-headless": createBuiltInAgent(),

    human_in_the_loop: createBuiltInAgent(),
    "hitl-in-chat": createBuiltInAgent(),
    "hitl-in-app": createBuiltInAgent(),

    "shared-state-read": createBuiltInAgent(),
    "shared-state-read-write": createBuiltInAgent(),
    "shared-state-streaming": createBuiltInAgent(),
    "readonly-state-agent-context": createBuiltInAgent(),

    subagents: createBuiltInAgent({ systemPrompt: SUBAGENTS_PROMPT }),
    "threadid-frontend-tool-roundtrip": createBuiltInAgent(),

    // Reasoning demos — visible chain-of-thought via the reasoning adapter.
    "reasoning-custom": createAgenticChatReasoningAgent(),
    "reasoning-default": createReasoningDefaultRenderAgent(),
    "tool-rendering-reasoning-chain": createToolRenderingReasoningChainAgent(),
  },
  runner: new InMemoryAgentRunner(),
});

const handler = createCopilotRuntimeHandler({
  runtime,
  basePath: "/api/copilotkit",
  mode: "single-route",
});

async function withProbeCompat(req: Request): Promise<Response> {
  const res = await handler(req);
  if (res.status === 404) {
    const body = await res.text();
    return new Response(body, { status: 400, headers: res.headers });
  }
  return res;
}

const copilotkitPost = async (req: Request): Promise<Response> =>
  withForwardedHeaders(req, () => withProbeCompat(req));

export const GET = (req: Request) =>
  withForwardedHeaders(req, () => handler(req));
// Wrap POST with CVDIAG backend instrumentation (L1-E). built-in-agent runs
// its BuiltInAgent in-process inside this route handler. No-op pass-through
// unless CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
export const POST = withCvdiagBackend(copilotkitPost, {
  slug: "built-in-agent",
  agentName: "default",
  provider: "openai",
});
export const OPTIONS = (req: Request) =>
  withForwardedHeaders(req, () => handler(req));

"use client";

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

// Suggestions registered via the v2 chat composer hook. The prompt is a
// concrete reasoning-eliciting question — gpt-5-mini (and other OpenAI
// reasoning models) only emit `response.reasoning_summary_text.delta`
// events when there's a real problem to think about. Meta-prompts like
// "show your reasoning" produce no reasoning summary, so the reasoning
// slot would never light up.
export function useReasoningDefaultSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Show reasoning",
        message:
          "Explain step by step why the sky appears blue during the day but red at sunset.",
      },
    ],
    available: "always",
  });
}

import { BuiltInAgent, convertInputToTanStackAI } from "@copilotkit/runtime/v2";
import { EventType } from "@ag-ui/client";
import type { BaseEvent } from "@ag-ui/client";
import { chat } from "@tanstack/ai";
import { openaiText } from "@tanstack/ai-openai";
import { baseServerTools } from "./server-tools";
// Custom fetch that injects ALS-bound inbound x-* headers (e.g.
// x-aimock-context) onto every outbound OpenAI call. Required so aimock
// can match fixtures by integration context. See ../header-forwarding.ts
// for the full rationale; mirrors the Mastra precedent.
import { forwardingFetch } from "../header-forwarding";
import { DEMO_AGENT_LOOP_STRATEGY, throwOnRunError } from "./demo-stream";

/**
 * Reasoning model used by all three reasoning demos.
 *
 * GPT-5.2 is a reasoning-capable model exposed through OpenAI's *Responses*
 * API, which streams a natural-language reasoning summary when asked with
 * `reasoning: { effort, summary }`. Swap via the `REASONING_MODEL` env var to
 * another Responses-API reasoning model (e.g. `o3`, `gpt-5-thinking`) if
 * GPT-5.2 isn't accessible in your environment.
 */
const REASONING_MODEL = process.env.REASONING_MODEL ?? "gpt-5.2";

/**
 * Reasoning effort for the summary. Must be `high`: at `low`/`medium`, real
 * OpenAI (verified) frequently completes the turn WITHOUT emitting any
 * reasoning summary part for short prompts, so the `<ReasoningBlock>` never
 * mounts. `high` reliably streams `response.reasoning_summary_text.delta`
 * events for the demo prompts.
 */
const REASONING_EFFORT: "low" | "medium" | "high" =
  (process.env.REASONING_EFFORT as "low" | "medium" | "high") ?? "high";

function randomUUID(): string {
  return crypto.randomUUID();
}

/**
 * Convert a TanStack AI (Responses-API) stream to AG-UI events, mapping the
 * model's reasoning summary into AG-UI `REASONING_MESSAGE_*` events.
 *
 * Why this custom converter instead of `type: "tanstack"`:
 *   - `openaiText` (TanStack's OpenAI *Responses*-API adapter) surfaces the
 *     reasoning summary as `STEP_STARTED` (`stepType: "thinking"`) followed by
 *     a run of `STEP_FINISHED` chunks that each carry a `delta` of summary
 *     text — NOT as upstream `REASONING_*` chunks.
 *   - The runtime's built-in `convertTanStackStream` only maps `REASONING_*`
 *     chunks to AG-UI reasoning events; it has no `STEP_*` handler, so the
 *     whole trace is silently dropped and `<ReasoningBlock>` never mounts.
 *   - Chat-completions streaming (the previous approach) places reasoning on
 *     `choices[0].delta.reasoning_content`, which real OpenAI does NOT emit
 *     (only aimock did) — so that path produced no trace against a real key.
 *
 * This converter translates the thinking STEP chunks into a
 * REASONING_START → REASONING_MESSAGE_START → REASONING_MESSAGE_CONTENT* →
 * REASONING_MESSAGE_END → REASONING_END lifecycle, closes the reasoning block
 * as soon as text or a tool call begins, and forwards text + tool-call events
 * (de-duplicated across TanStack's multi-turn re-announcements, like
 * tanstack-factory's converter).
 */
async function* convertReasoningStream(
  stream: AsyncIterable<unknown>,
  abortSignal: AbortSignal,
): AsyncGenerator<BaseEvent> {
  const messageId = randomUUID();
  let reasoningMessageId = randomUUID();
  let reasoningOpen = false;
  const completedToolCalls = new Set<string>();

  function* openReasoningIfNeeded(): Generator<BaseEvent> {
    if (reasoningOpen) return;
    reasoningOpen = true;
    reasoningMessageId = randomUUID();
    yield { type: EventType.REASONING_START, messageId: reasoningMessageId };
    yield {
      type: EventType.REASONING_MESSAGE_START,
      messageId: reasoningMessageId,
      role: "reasoning",
    };
  }

  function* closeReasoningIfOpen(): Generator<BaseEvent> {
    if (!reasoningOpen) return;
    reasoningOpen = false;
    yield {
      type: EventType.REASONING_MESSAGE_END,
      messageId: reasoningMessageId,
    };
    yield { type: EventType.REASONING_END, messageId: reasoningMessageId };
  }

  for await (const chunk of stream) {
    if (abortSignal.aborted) break;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const raw = chunk as any;
    const type = raw.type as string;

    if (type === "RUN_STARTED" || type === "RUN_FINISHED") continue;

    throwOnRunError(raw);

    // Reasoning summary: STEP_STARTED(stepType:"thinking") begins the trace;
    // subsequent STEP_STARTED/STEP_FINISHED chunks carry summary text on
    // `delta`. Only treat STEPs as reasoning while a thinking step is active.
    if (type === "STEP_STARTED" || type === "STEP_FINISHED") {
      const isThinking = raw.stepType === "thinking" || reasoningOpen;
      if (isThinking) {
        yield* openReasoningIfNeeded();
        const delta = raw.delta;
        if (typeof delta === "string" && delta.length > 0) {
          yield {
            type: EventType.REASONING_MESSAGE_CONTENT,
            messageId: reasoningMessageId,
            delta,
          };
        }
      }
      continue;
    }

    if (type === "TEXT_MESSAGE_CONTENT" && raw.delta != null) {
      yield* closeReasoningIfOpen();
      if ((raw.delta as string).length === 0) continue;
      yield {
        type: EventType.TEXT_MESSAGE_CHUNK,
        role: "assistant",
        messageId,
        delta: raw.delta as string,
      };
    } else if (type === "TOOL_CALL_START") {
      const toolCallId = raw.toolCallId as string;
      if (completedToolCalls.has(toolCallId)) continue;
      yield* closeReasoningIfOpen();
      yield {
        type: EventType.TOOL_CALL_START,
        parentMessageId: messageId,
        toolCallId,
        toolCallName: raw.toolCallName as string,
      };
    } else if (type === "TOOL_CALL_ARGS") {
      const toolCallId = raw.toolCallId as string;
      if (completedToolCalls.has(toolCallId)) continue;
      yield {
        type: EventType.TOOL_CALL_ARGS,
        toolCallId,
        delta: raw.delta as string,
      };
    } else if (type === "TOOL_CALL_END") {
      const toolCallId = raw.toolCallId as string;
      if (completedToolCalls.has(toolCallId)) continue;
      completedToolCalls.add(toolCallId);
      yield { type: EventType.TOOL_CALL_END, toolCallId };
    } else if (type === "TOOL_CALL_RESULT") {
      const toolCallId = raw.toolCallId as string;
      const rawPayload = raw.content ?? raw.result;
      let serializedContent: string;
      if (typeof rawPayload === "string") {
        serializedContent = rawPayload;
      } else {
        try {
          serializedContent = JSON.stringify(rawPayload ?? null);
        } catch {
          serializedContent = "[Unserializable tool result]";
        }
      }
      yield {
        type: EventType.TOOL_CALL_RESULT,
        role: "tool",
        messageId: randomUUID(),
        toolCallId,
        content: serializedContent,
      };
    }
  }

  yield* closeReasoningIfOpen();
}

/**
 * Built-in agent for `reasoning-custom` — visible thinking chain during
 * normal conversation. Uses the shared server tools so the model can
 * interleave tool calls with reasoning naturally.
 */
export function createAgenticChatReasoningAgent() {
  return new BuiltInAgent({
    // `custom` (not `tanstack`) so our converter can map the Responses-API
    // thinking STEPs to REASONING_MESSAGE_* — the built-in tanstack converter
    // drops STEP_* chunks.
    type: "custom",
    factory: ({ input, abortController }) => {
      const { messages, systemPrompts } = convertInputToTanStackAI(input);
      const stream = chat({
        adapter: openaiText(REASONING_MODEL as "gpt-5.2", {
          fetch: forwardingFetch,
        }),
        messages,
        systemPrompts,
        tools: [...baseServerTools],
        modelOptions: {
          reasoning: { effort: REASONING_EFFORT, summary: "auto" },
        },
        abortController,
        agentLoopStrategy: DEMO_AGENT_LOOP_STRATEGY,
      });
      return convertReasoningStream(stream, abortController.signal);
    },
  });
}

/**
 * Built-in agent for `reasoning-default` — same backend behaviour as
 * `reasoning-custom`; the demo's value is that the frontend passes NO custom
 * `reasoningMessage` slot, so CopilotKit's built-in
 * `CopilotChatReasoningMessage` renders the chain.
 */
export function createReasoningDefaultRenderAgent() {
  return createAgenticChatReasoningAgent();
}

/**
 * Built-in agent for `tool-rendering-reasoning-chain` — combines visible
 * reasoning with sequential tool calls (get_weather, search_flights,
 * roll_d20, get_stock_price) so the demo can show an interleaved
 * reasoning + tool-call chain.
 */
export function createToolRenderingReasoningChainAgent() {
  return createAgenticChatReasoningAgent();
}

