"use client";

/**
 * Fixed A2UI catalog — wires definitions to renderers.
 *
 * `includeBasicCatalog: true` merges CopilotKit's built-in components
 * (Card, Column, Row, Text, Button, Divider, …) into this catalog, so
 * the agent's fixed schema (src/agents/a2ui_schemas/flight_schema.json) can
 * compose custom and basic components interchangeably.
 */
import { createCatalog } from "@copilotkit/a2ui-renderer";

import { definitions } from "./definitions";
import { renderers } from "./renderers";

export const CATALOG_ID = "copilotkit://flight-fixed-catalog";

export const catalog = createCatalog(definitions, renderers, {
  catalogId: CATALOG_ID,
  includeBasicCatalog: true,
});

/**
 * A2UI catalog DEFINITIONS — platform-agnostic.
 *
 * Each entry declares a component name + its Zod props schema. The basic
 * catalog (Card, Column, Row, Text, Button, …) ships with CopilotKit and
 * is mixed in via `createCatalog(..., { includeBasicCatalog: true })`, so
 * we only declare the project-specific additions and the visual overrides
 * here. (Custom entries with the same name as a basic component override
 * the basic one — Catalog dedupes by `comp.name`, last-write-wins.)
 *
 * IMPORTANT — path bindings: fields that can be bound to a data-model path
 * (e.g. `{ path: "/origin" }` in the fixed schema JSON) must declare their
 * Zod type as a union of `z.string()` and `z.object({ path: z.string() })`.
 * The A2UI `GenericBinder` uses this union to detect the field as dynamic
 * and resolve the path against the current data model at render time. Using
 * plain `z.string()` causes the raw `{ path }` object to reach the
 * renderer, which React then throws on (error #31 "object with keys {path}").
 * This matches the canonical catalog's `DynString` helper:
 *   examples/integrations/langgraph-python/src/app/declarative-generative-ui/definitions.ts
 */
import { z } from "zod";
import type { CatalogDefinitions } from "@copilotkit/a2ui-renderer";

/**
 * Dynamic string: literal OR a data-model path binding. The GenericBinder
 * resolves path bindings to the actual value at render time.
 */
const DynString = z.union([z.string(), z.object({ path: z.string() })]);

export const definitions = {
  /**
   * Card override: gives the outer flight-card container a ShadCN look
   * (rounded-xl, neutral-200 border, soft shadow). The basic catalog's
   * Card uses inline styles; overriding here lets the demo's renderer
   * adopt the demo's Tailwind aesthetic without touching the schema JSON.
   */
  Card: {
    description: "A container card with a single child.",
    props: z.object({
      child: z.string(),
    }),
  },
  Title: {
    description: "A prominent heading for the flight card.",
    props: z.object({
      text: DynString,
    }),
  },
  Airport: {
    description: "A 3-letter airport code, displayed large.",
    props: z.object({
      code: DynString,
    }),
  },
  Arrow: {
    description: "A right-pointing arrow used between airports.",
    props: z.object({}),
  },
  AirlineBadge: {
    description: "A pill-styled airline name tag.",
    props: z.object({
      name: DynString,
    }),
  },
  PriceTag: {
    description: "A stylized price display (e.g. '$289').",
    props: z.object({
      amount: DynString,
    }),
  },
  /**
   * Button override: swaps in an ActionButton renderer that tracks
   * its own `done` state so clicking "Book flight" visually updates to
   * a "Booked ✓" confirmation. The basic catalog's Button is stateless,
   * so without this override the click fires the action but the button
   * looks unchanged. Mirrors the pattern in beautiful-chat
   * (src/app/demos/beautiful-chat/declarative-generative-ui/renderers.tsx).
   */
  Button: {
    description:
      "An interactive button with an action event. Use 'child' with a Text component ID for the label. After click, the button shows a confirmation state.",
    props: z.object({
      child: z
        .string()
        .describe(
          "The ID of the child component (e.g. a Text component for the label).",
        ),
      variant: z.enum(["primary", "secondary", "ghost"]).optional(),
      // Union with { event } so GenericBinder resolves this as ACTION → callable () => void.
      action: z
        .union([
          z.object({
            event: z.object({
              name: z.string(),
              context: z.record(z.any()).optional(),
            }),
          }),
          z.null(),
        ])
        .optional(),
    }),
  },
} satisfies CatalogDefinitions;

export type Definitions = typeof definitions;

"use client";

import { CopilotChat } from "@copilotkit/react-core/v2";
import { useA2UIFixedSchemaSuggestions } from "./suggestions";

export function Chat() {
  useA2UIFixedSchemaSuggestions();
  return (
    <CopilotChat agentId="a2ui-fixed-schema" className="h-full rounded-2xl" />
  );
}

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export function useA2UIFixedSchemaSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Find SFO → JFK",
        message: "Find me a flight from SFO to JFK on United for $289.",
      },
    ],
    available: "always",
  });
}

import { BuiltInAgent, convertInputToTanStackAI } from "@copilotkit/runtime/v2";
import { chat, toolDefinition } from "@tanstack/ai";
import { openaiText } from "@tanstack/ai-openai";
import { z } from "zod";
// Custom fetch that injects ALS-bound inbound x-* headers (e.g.
// x-aimock-context) onto every outbound OpenAI call. Required so aimock
// can match fixtures by integration context. See ../header-forwarding.ts
// for the full rationale; mirrors the Mastra precedent.
import { forwardingFetch } from "../header-forwarding";
import { DEMO_AGENT_LOOP_STRATEGY } from "./demo-stream";

const CATALOG_ID = "copilotkit://flight-fixed-catalog";
const SURFACE_ID = "flight-fixed-schema";
const A2UI_OPERATIONS_KEY = "a2ui_operations";

// Fixed flight-card schema. Inlined as a TS const so it ships into the
// Next.js route bundle without runtime fs access. Mirrors
// `showcase/integrations/langgraph-python/src/agents/a2ui_schemas/flight_schema.json`.
const FLIGHT_SCHEMA: unknown[] = [
  { id: "root", component: "Card", child: "content" },
  {
    id: "content",
    component: "Column",
    children: ["title", "route", "meta", "bookButton"],
  },
  { id: "title", component: "Title", text: "Flight Details" },
  {
    id: "route",
    component: "Row",
    justify: "spaceBetween",
    align: "center",
    children: ["from", "arrow", "to"],
  },
  { id: "from", component: "Airport", code: { path: "/origin" } },
  { id: "arrow", component: "Arrow" },
  { id: "to", component: "Airport", code: { path: "/destination" } },
  {
    id: "meta",
    component: "Row",
    justify: "spaceBetween",
    align: "center",
    children: ["airline", "price"],
  },
  {
    id: "airline",
    component: "AirlineBadge",
    name: { path: "/airline" },
  },
  { id: "price", component: "PriceTag", amount: { path: "/price" } },
  {
    id: "bookButton",
    component: "Button",
    variant: "primary",
    child: "bookButtonLabel",
    action: {
      event: {
        name: "book_flight",
        context: {
          origin: { path: "/origin" },
          destination: { path: "/destination" },
          airline: { path: "/airline" },
          price: { path: "/price" },
        },
      },
    },
  },
  { id: "bookButtonLabel", component: "Text", text: "Book flight" },
];

function createSurfaceOp(surfaceId: string, catalogId: string) {
  return {
    version: "v0.9",
    createSurface: { surfaceId, catalogId },
  };
}

function updateComponentsOp(surfaceId: string, components: unknown[]) {
  return {
    version: "v0.9",
    updateComponents: { surfaceId, components },
  };
}

function updateDataModelOp(
  surfaceId: string,
  data: unknown,
  path: string = "/",
) {
  return {
    version: "v0.9",
    updateDataModel: { surfaceId, path, value: data },
  };
}

function renderA2uiOperations(operations: unknown[]) {
  return { [A2UI_OPERATIONS_KEY]: operations };
}

// `display_flight` returns an `a2ui_operations` container directly. The runtime's
// A2UI middleware (configured with `injectA2UITool: false`) detects this shape
// in the tool result and forwards the operations to the frontend renderer, which
// resolves component names against the registered catalog.
const displayFlightTool = toolDefinition({
  name: "display_flight",
  description:
    'Show a flight card for the given trip. Use short airport codes (e.g. "SFO", "JFK") for origin/destination and a price string like "$289".',
  inputSchema: z.object({
    origin: z.string(),
    destination: z.string(),
    airline: z.string(),
    price: z.string(),
  }),
}).server(async ({ origin, destination, airline, price }) =>
  renderA2uiOperations([
    createSurfaceOp(SURFACE_ID, CATALOG_ID),
    updateComponentsOp(SURFACE_ID, FLIGHT_SCHEMA),
    updateDataModelOp(SURFACE_ID, { origin, destination, airline, price }),
  ]),
);

const A2UI_FIXED_SCHEMA_SYSTEM_PROMPT = `\
You help users find flights. When asked about a flight, call display_flight \
with origin, destination, airline, and price. Keep any chat reply to one \
short sentence.`;

/**
 * Built-in agent for the A2UI Fixed Schema demo.
 *
 * The frontend owns the component tree (a fixed JSON schema is
 * `updateComponents`'d once at render time); the agent only streams *data* into
 * the data model via the `display_flight` tool.
 */
export function createA2UIFixedSchemaAgent() {
  return new BuiltInAgent({
    type: "tanstack",
    factory: ({ input, abortController }) => {
      const { messages, systemPrompts } = convertInputToTanStackAI(input);
      return chat({
        adapter: openaiText("gpt-5.4", { fetch: forwardingFetch }),
        messages,
        systemPrompts: [A2UI_FIXED_SCHEMA_SYSTEM_PROMPT, ...systemPrompts],
        tools: [displayFlightTool],
        abortController,
        agentLoopStrategy: DEMO_AGENT_LOOP_STRATEGY,
      });
    },
  });
}

