def _execute_tool(
    name: str,
    tool_input: dict[str, Any],
    state: AgentState,
    conversation_messages: list[dict[str, Any]] | None = None,
) -> tuple[str, AgentState | None]:
    """Execute backend tools and return (result_text, new_state_or_None)."""
    if name == "get_weather":
        return json.dumps(get_weather_impl(tool_input["location"])), None

    if name == "query_data":
        return json.dumps(query_data_impl(tool_input["query"])), None

    if name == "manage_todos":
        state.todos = _coerce_beautiful_chat_todos(tool_input.get("todos"))
        return json.dumps({"status": "updated", "count": len(state.todos)}), state

    if name == "get_todos":
        return json.dumps(_coerce_beautiful_chat_todos(state.todos)), None

    if name == "manage_sales_todos":
        result = manage_sales_todos_impl(tool_input["todos"])
        state.todos = [dict(t) for t in result]
        return json.dumps({"status": "updated", "count": len(result)}), state

    if name == "get_sales_todos":
        return json.dumps(
            get_sales_todos_impl(state.todos if state.todos else None)
        ), None

    if name == "schedule_meeting":
        return json.dumps(schedule_meeting_impl(tool_input["reason"])), None

    if name == "generate_task_steps":
        # Frontend HITL tool -- backend just acknowledges; UI handles the interaction
        steps = tool_input.get("steps", [])
        return f"Presented {len(steps)} steps for review.", None

    if name == "change_background":
        # Frontend tool -- backend just acknowledges
        return f"Background change requested: {tool_input.get('background', '')}", None

    if name == "search_flights":
        if "flights" in tool_input:
            flights_data = tool_input.get("flights", [])
            typed_flights = [Flight(**f) for f in flights_data]
            result = search_flights_impl(typed_flights)
            return json.dumps(result), None
        return json.dumps(
            _search_flights_by_route_impl(
                str(tool_input.get("origin", "")),
                str(tool_input.get("destination", "")),
            )
        ), None

    if name == "get_stock_price":
        return json.dumps(
            _get_stock_price_impl(str(tool_input.get("ticker", "")))
        ), None

    if name == "get_revenue_chart":
        return json.dumps(
            {
                "title": "Revenue trend",
                "subtitle": "Last six months, USD thousands",
                "data": [
                    {"label": "Jan", "value": 42},
                    {"label": "Feb", "value": 48},
                    {"label": "Mar", "value": 53},
                    {"label": "Apr", "value": 57},
                    {"label": "May", "value": 63},
                    {"label": "Jun", "value": 71},
                ],
            }
        ), None

    if name == "roll_d20":
        value = tool_input.get("value")
        return json.dumps(
            {
                "value": int(value)
                if isinstance(value, (int, float))
                else random.randint(1, 20)
            }
        ), None

    if name == "set_steps":
        steps = tool_input.get("steps", [])
        state.steps = [dict(step) for step in steps if isinstance(step, dict)]
        return json.dumps({"status": "updated", "count": len(state.steps)}), state

    if name == "write_document":
        document = str(tool_input.get("document", ""))
        state.document = document
        return json.dumps({"status": "updated", "length": len(document)}), state

    if name == "generate_a2ui":
        context = tool_input.get("context", "")
        client = anthropic.Anthropic(api_key=os.getenv("ANTHROPIC_API_KEY", ""))
        render_tool_schema = {
            "name": RENDER_A2UI_TOOL_SCHEMA["name"],
            "description": RENDER_A2UI_TOOL_SCHEMA["description"],
            "input_schema": RENDER_A2UI_TOOL_SCHEMA["parameters"],
        }
        llm_messages: list[dict[str, Any]] = []
        # Pass conversation messages to the secondary LLM for context
        if conversation_messages:
            llm_messages.extend(
                sanitize_unresolved_tool_uses(
                    conversation_messages,
                )
            )
        else:
            llm_messages.append(
                {
                    "role": "user",
                    "content": "Generate a dynamic A2UI dashboard based on the conversation.",
                }
            )
        response = client.messages.create(
            model=normalize_claude_model(
                os.getenv("ANTHROPIC_MODEL", DEFAULT_ANTHROPIC_MODEL)
            ),
            max_tokens=4096,
            system=context or "Generate a useful dashboard UI.",
            messages=llm_messages,
            tools=[render_tool_schema],
            tool_choice={"type": "tool", "name": "render_a2ui"},
        )
        for block in response.content:
            if (
                getattr(block, "type", None) == "tool_use"
                and block.name == "render_a2ui"
            ):
                a2ui_result = build_a2ui_operations_from_tool_call(dict(block.input))
                return json.dumps(a2ui_result), None
        return json.dumps({"error": "LLM did not call render_a2ui"}), None

    return f"Unknown tool: {name}", None




def _build_frontend_tools(input_data: RunAgentInput) -> list[dict[str, Any]]:
    """Extract frontend-defined tools from the AG-UI request.

    The CopilotKit runtime forwards frontend tool definitions (registered
    via ``useFrontendTool``, ``useHumanInTheLoop``, etc.) in
    ``input_data.tools``. We convert them to the Anthropic ``tools``
    schema so the LLM can call them. The runtime intercepts the resulting
    tool-call events and routes them to the frontend for resolution.
    """
    out: list[dict[str, Any]] = []
    for t in input_data.tools or []:
        name = getattr(t, "name", None) or (
            t.get("name") if isinstance(t, dict) else None
        )
        description = getattr(t, "description", None) or (
            t.get("description", "") if isinstance(t, dict) else ""
        )
        parameters = getattr(t, "parameters", None) or (
            t.get("parameters", {}) if isinstance(t, dict) else {}
        )
        if not name:
            continue
        out.append(
            {
                "name": name,
                "description": description or "",
                "input_schema": parameters or {"type": "object", "properties": {}},
            }
        )
    return out




async def run_agent(
    input_data: RunAgentInput,
    *,
    system_prompt_override: str | None = None,
    disable_tools: bool = False,
    preprocess_user_parts: Any = None,
    tools_override: list[dict[str, Any]] | None = None,
    frontend_tool_names_allowlist: set[str] | None = None,
    latest_user_message_only: bool = False,
) -> AsyncIterator[str]:
    """Run the Claude agent and yield AG-UI SSE events.

    Keyword arguments let dedicated demo endpoints reuse this streaming
    loop with targeted overrides:

    - ``system_prompt_override`` — replace the shared ``SYSTEM_PROMPT``
      (e.g. BYOC demos emit a JSON envelope, so the sales-assistant
      prompt is irrelevant).
    - ``disable_tools`` — run the model with no tool schemas. Useful for
      BYOC / pure-text demos where tool calls would derail the output.
    - ``preprocess_user_parts`` — a ``callable(part) -> part`` applied to
      each content part of every user message before they are sent to
      Claude. Used by the multimodal demo to convert AG-UI
      ``image``/``document`` parts into Claude's Messages API shape
      (``{"type": "image", "source": {...}}``) and to flatten PDFs to
      text via ``pypdf``.
    """
    encoder = EventEncoder()
    client = anthropic.AsyncAnthropic(api_key=os.getenv("ANTHROPIC_API_KEY", ""))

    # Extract state
    state = AgentState()
    if input_data.state and isinstance(input_data.state, dict):
        state = AgentState(**input_data.state)

    # Convert AG-UI messages to Anthropic format. When a preprocessor is
    # supplied we preserve the structured content list (image blocks,
    # document text, etc.) — otherwise we collapse to a flat string for
    # the text-only happy path used by most demos.
    #
    # AG-UI delivers three message roles:
    #   - "user"      → plain user text
    #   - "assistant" → assistant text + optional tool_use blocks
    #   - "tool"      → tool result from a resolved frontend tool
    #
    # Anthropic's Messages API represents tool results as a "user" role
    # message with content blocks of type "tool_result". We must convert
    # AG-UI "tool" messages into that shape so the LLM sees the resolved
    # result and aimock's ``hasToolResult`` matcher fires correctly.
    messages: list[dict[str, Any]] = []
    for msg in input_data.messages or []:
        role = msg.role.value if hasattr(msg.role, "value") else str(msg.role)

        # Handle tool result messages from AG-UI (resolved frontend tools).
        # Convert to Anthropic's format: role="user" with tool_result blocks.
        if role == "tool":
            tool_call_id = getattr(msg, "tool_call_id", None) or (
                getattr(msg, "toolCallId", None)
            )
            raw_content = getattr(msg, "content", None)
            result_text = ""
            if isinstance(raw_content, str):
                result_text = raw_content
            elif isinstance(raw_content, list):
                parts = []
                for part in raw_content:
                    if hasattr(part, "text"):
                        parts.append(part.text)
                    elif isinstance(part, dict) and "text" in part:
                        parts.append(part["text"])
                parts_text = "".join(parts)
                if parts_text:
                    result_text = parts_text
                else:
                    result_text = json.dumps(raw_content)
            if tool_call_id:
                # Anthropic expects the assistant message containing the
                # tool_use to precede this tool_result message. The runtime
                # ensures message ordering, so we just need to emit the
                # tool_result in the right shape.
                messages.append(
                    {
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": tool_call_id,
                                "content": result_text,
                            }
                        ],
                    }
                )
            continue

        if role not in ("user", "assistant"):
            continue

        raw_content = getattr(msg, "content", None)

        if (
            preprocess_user_parts is not None
            and role == "user"
            and isinstance(raw_content, list)
        ):
            converted_parts: list[Any] = []
            for part in raw_content:
                # AG-UI emits pydantic models; normalise to a plain dict
                # before handing to the converter so the demo-specific
                # code can rely on ``.get(...)`` semantics.
                if hasattr(part, "model_dump"):
                    part_dict = part.model_dump()
                elif isinstance(part, dict):
                    part_dict = part
                else:
                    part_dict = part
                converted = preprocess_user_parts(part_dict)
                if converted is not None:
                    converted_parts.append(converted)
            if converted_parts:
                messages.append({"role": role, "content": converted_parts})
            continue

        # For assistant messages, check if there are tool calls (AG-UI's
        # AssistantMessage stores them in `tool_calls`, not in `content`).
        # Anthropic requires tool_use blocks in the assistant content so
        # the subsequent tool_result can pair with them.
        if role == "assistant":
            msg_tool_calls = getattr(msg, "tool_calls", None)
            text_content = ""
            if isinstance(raw_content, str):
                text_content = raw_content
            elif isinstance(raw_content, list):
                for part in raw_content:
                    if hasattr(part, "text"):
                        text_content += part.text
                    elif isinstance(part, dict) and "text" in part:
                        text_content += part["text"]

            if msg_tool_calls:
                content_blocks: list[dict[str, Any]] = []
                if text_content:
                    content_blocks.append({"type": "text", "text": text_content})
                for tc in msg_tool_calls:
                    # AG-UI ToolCall: {id, function: {name, arguments}}
                    tc_id = getattr(tc, "id", None) or (
                        tc.get("id") if isinstance(tc, dict) else None
                    )
                    func = getattr(tc, "function", None) or (
                        tc.get("function") if isinstance(tc, dict) else None
                    )
                    if func:
                        tc_name = getattr(func, "name", None) or (
                            func.get("name") if isinstance(func, dict) else "unknown"
                        )
                        tc_args_str = getattr(func, "arguments", None) or (
                            func.get("arguments", "{}")
                            if isinstance(func, dict)
                            else "{}"
                        )
                    else:
                        tc_name = "unknown"
                        tc_args_str = "{}"
                    try:
                        tc_args = (
                            json.loads(tc_args_str)
                            if isinstance(tc_args_str, str)
                            else tc_args_str
                        )
                    except json.JSONDecodeError:
                        tc_args = {}
                    content_blocks.append(
                        {
                            "type": "tool_use",
                            "id": tc_id or "unknown",
                            "name": tc_name,
                            "input": tc_args,
                        }
                    )
                messages.append({"role": "assistant", "content": content_blocks})
                continue
            elif text_content:
                messages.append({"role": "assistant", "content": text_content})
                continue
            # Fall through to the generic handler if nothing matched

        content = ""
        if isinstance(raw_content, str):
            content = raw_content
        elif isinstance(raw_content, list):
            parts = []
            for part in raw_content:
                if hasattr(part, "text"):
                    parts.append(part.text)
                elif isinstance(part, dict) and "text" in part:
                    parts.append(part["text"])
            content = "".join(parts)
        if content:
            messages.append({"role": role, "content": content})

    sdk_input_data = input_data
    if latest_user_message_only:
        latest_user_message = next(
            (m for m in reversed(messages) if m.get("role") == "user"),
            None,
        )
        messages = [latest_user_message] if latest_user_message else []
        latest_input_message = next(
            (
                m
                for m in reversed(input_data.messages or [])
                if (m.role.value if hasattr(m.role, "value") else str(m.role)) == "user"
            ),
            None,
        )
        sdk_messages = [latest_input_message] if latest_input_message else []
        if hasattr(input_data, "model_copy"):
            sdk_input_data = input_data.model_copy(update={"messages": sdk_messages})
        else:  # pragma: no cover - compatibility with older pydantic models
            sdk_input_data = input_data.copy(update={"messages": sdk_messages})

    # Inject sales pipeline state into system prompt if state exists
    if system_prompt_override is not None:
        system = system_prompt_override
    else:
        system = SYSTEM_PROMPT
        if state.todos:
            todos_json = json.dumps(state.todos, indent=2)
            system = f"{SYSTEM_PROMPT}\n\nCurrent sales pipeline:\n{todos_json}"

    context_entries = getattr(input_data, "context", None) or []
    if context_entries:
        context_lines: list[str] = []
        for entry in context_entries:
            if isinstance(entry, dict):
                description = entry.get("description")
                value = entry.get("value")
            else:
                description = getattr(entry, "description", None)
                value = getattr(entry, "value", None)
            if description:
                context_lines.append(f"{description}: {value}")
        if context_lines:
            system = f"{system}\n\nContext:\n" + "\n".join(context_lines)

    sdk_backend_tools = (
        []
        if disable_tools
        else (tools_override if tools_override is not None else TOOLS)
    )
    sdk_frontend_tools = [] if disable_tools else _build_frontend_tools(input_data)
    if frontend_tool_names_allowlist is not None:
        sdk_frontend_tools = [
            t for t in sdk_frontend_tools if t["name"] in frontend_tool_names_allowlist
        ]
    sdk_frontend_tool_names = {t["name"] for t in sdk_frontend_tools}
    if should_use_claude_agent_sdk(
        input_data=input_data,
        backend_tools=sdk_backend_tools,
        frontend_tool_names=sdk_frontend_tool_names,
        preprocess_user_parts=preprocess_user_parts,
    ):
        async for chunk in run_with_claude_agent_sdk(
            sdk_input_data,
            system_prompt=system,
            tools=sdk_backend_tools,
            state=state,
            model=os.getenv("ANTHROPIC_MODEL", DEFAULT_ANTHROPIC_MODEL),
            execute_tool=_execute_tool,
        ):
            yield chunk
        return

    thread_id = input_data.thread_id or "default"
    run_id = input_data.run_id or "run-1"

    yield encoder.encode(
        RunStartedEvent(type=EventType.RUN_STARTED, thread_id=thread_id, run_id=run_id)
    )

    # Agentic loop -- keep calling Claude until no more tool calls
    while True:
        response_text = ""
        tool_calls: list[dict[str, Any]] = []
        msg_id = f"msg-{run_id}-{len(messages)}"

        yield encoder.encode(
            TextMessageStartEvent(
                type=EventType.TEXT_MESSAGE_START,
                message_id=msg_id,
                role="assistant",
            )
        )

        # Build the combined tools list: backend TOOLS + any frontend-
        # defined tools forwarded by the CopilotKit runtime in
        # input_data.tools. Frontend tools (registered via useFrontendTool,
        # useHumanInTheLoop, etc.) are included so the LLM can call them;
        # the runtime intercepts the resulting events and routes them to
        # the frontend for resolution. Backend tools are executed locally.
        backend_tools = tools_override if tools_override is not None else TOOLS
        backend_tool_names = {t["name"] for t in backend_tools}
        frontend_tools = _build_frontend_tools(input_data)
        if frontend_tool_names_allowlist is not None:
            frontend_tools = [
                t for t in frontend_tools if t["name"] in frontend_tool_names_allowlist
            ]
        # Merge: backend tools first, then frontend tools that don't
        # shadow a backend tool (frontend wins when names collide, because
        # the frontend registration means the runtime should intercept).
        frontend_tool_names = {t["name"] for t in frontend_tools}
        combined_tools: list[dict[str, Any]] = []
        for t in backend_tools:
            if t["name"] not in frontend_tool_names:
                combined_tools.append(t)
        combined_tools.extend(frontend_tools)

        stream_kwargs: dict[str, Any] = {
            "model": normalize_claude_model(
                os.getenv("ANTHROPIC_MODEL", DEFAULT_ANTHROPIC_MODEL)
            ),
            "max_tokens": 4096,
            "system": system,
            "messages": messages,
        }
        if not disable_tools:
            stream_kwargs["tools"] = combined_tools  # type: ignore[assignment]

        try:
            async with client.messages.stream(**stream_kwargs) as stream:
                current_tool_id: str | None = None
                current_tool_name: str | None = None
                current_tool_args = ""
                last_streamed_document = state.document

                async for event in stream:
                    etype = type(event).__name__

                    if etype == "RawContentBlockStartEvent":
                        block = event.content_block  # type: ignore[attr-defined]
                        if block.type == "text":
                            pass  # streaming text chunks follow
                        elif block.type == "tool_use":
                            current_tool_id = block.id
                            current_tool_name = block.name
                            current_tool_args = ""
                            yield encoder.encode(
                                ToolCallStartEvent(
                                    type=EventType.TOOL_CALL_START,
                                    tool_call_id=current_tool_id,
                                    tool_call_name=current_tool_name,
                                    parent_message_id=msg_id,
                                )
                            )

                    elif etype == "RawContentBlockDeltaEvent":
                        delta = event.delta  # type: ignore[attr-defined]
                        if delta.type == "text_delta":
                            response_text += delta.text
                            yield encoder.encode(
                                TextMessageContentEvent(
                                    type=EventType.TEXT_MESSAGE_CONTENT,
                                    message_id=msg_id,
                                    delta=delta.text,
                                )
                            )
                        elif delta.type == "input_json_delta":
                            current_tool_args += delta.partial_json
                            yield encoder.encode(
                                ToolCallArgsEvent(
                                    type=EventType.TOOL_CALL_ARGS,
                                    tool_call_id=current_tool_id or "",
                                    delta=delta.partial_json,
                                )
                            )
                            if current_tool_name == "write_document":
                                streamed_document = _partial_json_string_property(
                                    current_tool_args,
                                    "document",
                                )
                                if (
                                    streamed_document is not None
                                    and streamed_document != last_streamed_document
                                ):
                                    state.document = streamed_document
                                    last_streamed_document = streamed_document
                                    yield encoder.encode(
                                        StateSnapshotEvent(
                                            type=EventType.STATE_SNAPSHOT,
                                            snapshot=state.model_dump(),
                                        )
                                    )

                    elif etype in (
                        "RawContentBlockStopEvent",
                        "ParsedContentBlockStopEvent",
                    ):
                        if current_tool_id and current_tool_name:
                            yield encoder.encode(
                                ToolCallEndEvent(
                                    type=EventType.TOOL_CALL_END,
                                    tool_call_id=current_tool_id,
                                )
                            )
                            try:
                                parsed_args = (
                                    json.loads(current_tool_args)
                                    if current_tool_args
                                    else {}
                                )
                            except json.JSONDecodeError:
                                parsed_args = {}
                            tool_calls.append(
                                {
                                    "id": current_tool_id,
                                    "name": current_tool_name,
                                    "input": parsed_args,
                                }
                            )
                            current_tool_id = None
                            current_tool_name = None
                            current_tool_args = ""
        except Exception:
            # Surface the error as visible text in the chat so D5
            # probes see a non-empty assistant response instead of a
            # silent broken SSE stream. Full traceback is logged
            # server-side by FastAPI's exception handler.
            err_text = f"Agent error: {traceback.format_exc()}"
            yield encoder.encode(
                TextMessageContentEvent(
                    type=EventType.TEXT_MESSAGE_CONTENT,
                    message_id=msg_id,
                    delta=err_text,
                )
            )

        yield encoder.encode(
            TextMessageEndEvent(
                type=EventType.TEXT_MESSAGE_END,
                message_id=msg_id,
            )
        )

        # No tool calls -- we're done
        if not tool_calls:
            break

        # Separate tool calls into backend (locally executed) and frontend
        # (deferred to the CopilotKit runtime / frontend for resolution).
        # A tool whose name was registered on the frontend (present in
        # frontend_tool_names) is a frontend tool even if the backend also
        # defines it — the frontend registration takes precedence because
        # hooks like useHumanInTheLoop rely on intercepting the tool call.
        # Add assistant turn with tool calls to message history
        assistant_content: list[dict[str, Any]] = []
        if response_text:
            assistant_content.append({"type": "text", "text": response_text})
        for tc in tool_calls:
            assistant_content.append(
                {
                    "type": "tool_use",
                    "id": tc["id"],
                    "name": tc["name"],
                    "input": tc["input"],
                }
            )
        messages.append({"role": "assistant", "content": assistant_content})

        # Execute backend tools and build tool-result turn. Frontend tools are
        # intentionally left unresolved here so the CopilotKit runtime can
        # intercept them and re-invoke the agent after the browser handler runs.
        tool_results: list[dict[str, Any]] = []
        has_frontend_tool = False
        for tc in tool_calls:
            if tc["name"] in frontend_tool_names:
                has_frontend_tool = True
                continue
            # Offload to a worker thread: _execute_tool may run a synchronous
            # anthropic.Anthropic() LLM round-trip (the generate_a2ui branch),
            # which would otherwise block the uvicorn event loop and wedge the
            # :8000 /health endpoint under load. asyncio.to_thread keeps the
            # loop free to serve health probes and other concurrent requests.
            result_text, new_state = await asyncio.to_thread(
                _execute_tool,
                tc["name"],
                tc["input"],
                state,
                conversation_messages=messages,
            )
            if new_state is not None:
                state = new_state
                yield encoder.encode(
                    StateSnapshotEvent(
                        type=EventType.STATE_SNAPSHOT,
                        snapshot=state.model_dump(),
                    )
                )
            yield encoder.encode(
                ToolCallResultEvent(
                    type=EventType.TOOL_CALL_RESULT,
                    tool_call_id=tc["id"],
                    message_id=f"{msg_id}-tool-result-{tc['id']}",
                    content=result_text,
                )
            )
            tool_results.append(
                {
                    "type": "tool_result",
                    "tool_use_id": tc["id"],
                    "content": result_text,
                }
            )
        if tool_results:
            messages.append({"role": "user", "content": tool_results})

        if has_frontend_tool:
            # At least one tool call targets a frontend tool. Break the
            # agentic loop after any backend siblings have been resolved; the
            # runtime owns the frontend continuation from here.
            break

    yield encoder.encode(
        RunFinishedEvent(
            type=EventType.RUN_FINISHED, thread_id=thread_id, run_id=run_id
        )
    )


def create_app() -> FastAPI:
    """Create the FastAPI app with AG-UI endpoint."""
    # Local import to avoid a top-level ``agents._header_forwarding``
    # dependency in this module (kept agnostic so unit tests that import
    # individual handlers don't need the starlette middleware shape).
    from agents._header_forwarding import HeaderForwardingHTTPMiddleware

    app = FastAPI(title="Claude Agent SDK (Python) Agent Server")

    app.add_middleware(HealthMiddleware)

    # Capture inbound CopilotKit ``x-*`` headers (e.g. ``x-aimock-context``)
    # into a per-request ContextVar so any outbound LLM/provider httpx call
    # made inside the request scope copies them onto its outbound request.
    # Paired with ``install_global_httpx_hook`` at the top of agent_server.py.
    app.add_middleware(HeaderForwardingHTTPMiddleware)

    app.add_middleware(
        CORSMiddleware,
        allow_origins=["*"],
        allow_methods=["*"],
        allow_headers=["*"],
    )

    @app.post("/")
    async def run_agent_endpoint(request: Request) -> StreamingResponse:
        body = await request.json()
        input_data = RunAgentInput(**body)

        async def event_stream() -> AsyncIterator[str]:
            async for chunk in run_agent(input_data):
                yield chunk

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={
                "Cache-Control": "no-cache",
                "X-Accel-Buffering": "no",
            },
        )

    return app

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { createClaudeHttpAgent } from "@/app/api/_shared/claude-http-agent";
import crypto from "node:crypto";

// The agent backend runs as a separate process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

function createAgent(path = "/") {
  return createClaudeHttpAgent(`${AGENT_URL}${path}`);
}

// Register the same agent under all names used by demo pages. Entries that
// need backend-owned tools/state are re-pointed by `dedicatedAgentPaths`.
const agentNames = [
  "agentic_chat",
  "agentic-chat",
  "human_in_the_loop",
  "hitl",
  "tool-rendering",
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-write",
  "shared-state-streaming",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "frontend_tools",
  "frontend-tools",
  "threadid-frontend-tool-roundtrip",
  "frontend-tools-async",
  "hitl-in-chat",
  "hitl-in-app",
  "readonly-state-agent-context",
  "headless-complete",
  "beautiful-chat",
  "declarative-gen-ui",
  "open-gen-ui",
  "open-gen-ui-advanced",
  "mcp-apps",
  "declarative_json_render",
  "declarative-hashbrown-demo",
  "multimodal-demo",
  "voice-demo",
  "agent-config-demo",
  "auth-demo",
  "gen-ui-interrupt",
  "interrupt-headless",
  "reasoning-default",
  "reasoning-custom",
];

// Demos with dedicated FastAPI endpoints (their own state schema, tool
// set, or prompt). The Python backend mounts each at /<name>; mapping
// the agent name to that path keeps the runtime config flat.
const dedicatedAgentPaths: Record<string, string> = {
  "gen-ui-agent": "/gen-ui-agent",
  "tool-rendering": "/tool-rendering",
  "tool-rendering-default-catchall": "/tool-rendering",
  "tool-rendering-custom-catchall": "/tool-rendering",
  "shared-state-read-write": "/shared-state-read-write",
  "shared-state-streaming": "/shared-state-streaming",
  subagents: "/subagents",
  // Reasoning demos share a single backend that emits AG-UI
  // REASONING_MESSAGE_* events (parsed out of <reasoning>...</reasoning>
  // blocks the model emits). The two demo cells differ only on the
  // frontend slot configuration.
  "reasoning-default": "/reasoning",
  "reasoning-custom": "/reasoning",
  "tool-rendering-reasoning-chain": "/tool-rendering-reasoning-chain",
  "headless-complete": "/headless-complete",
  "hitl-in-chat": "/hitl-in-chat",
  "hitl-in-chat-booking": "/hitl-in-chat",
  "gen-ui-interrupt": "/interrupt-adapted",
  "interrupt-headless": "/interrupt-adapted",
};

const agents: Record<string, AbstractAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent();
}
for (const [name, path] of Object.entries(dedicatedAgentPaths)) {
  agents[name] = createAgent(path);
}
agents["default"] = createAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- Published CopilotRuntime agents type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in source, pending release
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    // Log the full error server-side with a correlation id, but only return
    // a generic message + errorId to the client so we don't leak stack
    // traces or internal error messages to untrusted callers. Mirrors the
    // pattern used in `mastra/src/app/api/copilotkit/route.ts`.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = crypto.randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        route: "/api/copilotkit",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

"use client";

/**
 * Compact chip rendered above the composer for each pending attachment.
 * Shows a thumbnail (image) or icon (document), the filename, and an X
 * button to remove. Doubles as the in-message preview rendered alongside
 * a sent user message in `chat/message-user.tsx`.
 */

import React from "react";
import { File, Loader2, X } from "lucide-react";
import type { Attachment } from "@copilotkit/shared";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export function AttachmentChip({
  attachment,
  onRemove,
}: {
  attachment: Attachment;
  onRemove?: (id: string) => void;
}) {
  const isImage = attachment.type === "image";
  const isUploading = attachment.status === "uploading";
  const src = isImage ? attachmentSrc(attachment) : undefined;

  return (
    <div
      className={cn(
        "group relative inline-flex items-center gap-2 rounded-lg border bg-card px-2 py-1.5 text-xs shadow-sm",
        onRemove ? "pr-7" : "pr-2",
      )}
    >
      <div className="flex h-7 w-7 shrink-0 items-center justify-center overflow-hidden rounded-md bg-muted text-muted-foreground">
        {isUploading ? (
          <Loader2 className="h-4 w-4 animate-spin" />
        ) : isImage && src ? (
          <img
            src={src}
            alt={attachment.filename ?? "attachment"}
            className="h-full w-full object-cover"
          />
        ) : (
          <File className="h-4 w-4" />
        )}
      </div>
      <div className="flex min-w-0 flex-col leading-tight">
        <span className="max-w-[180px] truncate font-medium text-foreground">
          {attachment.filename ?? "attachment"}
        </span>
        <span className="text-[10px] text-muted-foreground">
          {isUploading ? "uploading…" : prettyBytes(attachment.size)}
        </span>
      </div>
      {onRemove && (
        <Button
          type="button"
          size="icon"
          variant="ghost"
          aria-label="Remove attachment"
          onClick={() => onRemove(attachment.id)}
          className="absolute right-0.5 top-1/2 h-5 w-5 -translate-y-1/2"
        >
          <X className="h-3 w-3" />
        </Button>
      )}
    </div>
  );
}

function attachmentSrc(att: Attachment): string | undefined {
  const src = att.source;
  if (src.type === "url") return src.value;
  if (src.type === "data") {
    return `data:${src.mimeType};base64,${src.value}`;
  }
  return undefined;
}

function prettyBytes(size?: number): string {
  if (!size) return "";
  if (size < 1024) return `${size}B`;
  if (size < 1024 * 1024) return `${(size / 1024).toFixed(1)}KB`;
  return `${(size / (1024 * 1024)).toFixed(1)}MB`;
}

"use client";

/**
 * Configures `useAttachments` for the headless-complete demo. Inlines
 * uploads as base64 (no external storage), accepts images and PDFs, and
 * caps each file at 20MB.
 *
 * The hook returns the full attachment pipeline: `fileInputRef` for the
 * hidden `<input type="file">`, `containerRef` for paste support,
 * drag/drop handlers, the live attachment list, plus `consumeAttachments`
 * which is called at submit time and clears the queue.
 */

import { useCallback } from "react";
import { useAttachments } from "@copilotkit/react-core/v2";
import type { UseAttachmentsReturn } from "@copilotkit/react-core/v2";
import type { AttachmentUploadResult } from "@copilotkit/shared";

const MAX_FILE_SIZE_BYTES = 20 * 1024 * 1024;
const ACCEPT_MIME = "image/*,application/pdf";

export function useAttachmentsConfig(): UseAttachmentsReturn {
  const onUpload = useCallback(fileToBase64, []);

  return useAttachments({
    config: {
      enabled: true,
      accept: ACCEPT_MIME,
      maxSize: MAX_FILE_SIZE_BYTES,
      onUpload,
      onUploadFailed: (err) => {
        console.warn("[headless-complete] attachment rejected", err);
      },
    },
  });
}

function fileToBase64(file: File): Promise<AttachmentUploadResult> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () =>
      reject(reader.error ?? new Error(`FileReader failed for ${file.name}`));
    reader.onload = () => {
      const result = reader.result;
      if (typeof result !== "string") {
        reject(new Error(`Unexpected FileReader result for ${file.name}`));
        return;
      }
      const commaIdx = result.indexOf(",");
      const base64 = commaIdx >= 0 ? result.slice(commaIdx + 1) : result;
      resolve({
        type: "data",
        value: base64,
        mimeType: file.type || "application/octet-stream",
        metadata: { filename: file.name, size: file.size },
      });
    };
    reader.readAsDataURL(file);
  });
}

"use client";

/**
 * Hand-rolled chat shell.
 *
 * Owns the read/write loop:
 * - `useAgent`        — message list, isRunning, addMessage, abortRun, setMessages
 * - `useCopilotKit`   — `runAgent({ agent })` to dispatch a turn
 *
 * Renders the message tree via `<MessageList />` (which uses
 * `useRenderToolCall` and `useRenderActivityMessage` internally), shows
 * a typing indicator while the agent is thinking, and composes the
 * suggestion bar + composer (with attachments) at the bottom.
 *
 * The visual chrome is identical to `headless-simple/chat.tsx` — same
 * outer wrapper, same `Card` shell, same bubble palette — so the two
 * demos read as a pair.
 */

import React, { useCallback, useState } from "react";
import { useAgent, useCopilotKit } from "@copilotkit/react-core/v2";
import type { Attachment, InputContent } from "@copilotkit/shared";
import { Card, CardContent } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";
import { useAttachmentsConfig } from "../attachments/use-attachments-config";
import { useAutoScroll } from "../hooks/use-auto-scroll";
import { useTypingIndicator } from "../hooks/use-typing-indicator";
import { Composer } from "./composer";
import { EmptyState } from "./empty-state";
import { Header } from "./header";
import { MessageList } from "./message-list";
import { SuggestionBar } from "./suggestion-bar";
import { TypingIndicator } from "./typing-indicator";

function createMessageId() {
  if (
    typeof crypto !== "undefined" &&
    typeof crypto.randomUUID === "function"
  ) {
    return crypto.randomUUID();
  }
  return `msg-${Date.now().toString(36)}-${Math.random()
    .toString(36)
    .slice(2)}`;
}

export function Chat({ agentId }: { agentId: string }) {
  const { agent } = useAgent({ agentId });
  const { copilotkit } = useCopilotKit();

  const {
    attachments,
    fileInputRef,
    containerRef,
    handleFileUpload,
    handleDragOver,
    handleDragLeave,
    handleDrop,
    dragOver,
    removeAttachment,
    consumeAttachments,
  } = useAttachmentsConfig();

  const [input, setInput] = useState("");
  const messages = agent.messages;
  const { listRef, bottomRef, stickRef } = useAutoScroll(
    messages,
    agent.isRunning,
  );

  // Send pipeline: consume any ready attachments at submit time, build
  // the multimodal `content` array if needed, then dispatch the run.
  const sendText = useCallback(
    (text: string): boolean => {
      const trimmed = text.trim();
      if (agent.isRunning) return false;
      // Consume queued uploads first so they get sent even if the user
      // didn't type any text alongside them.
      const ready = consumeAttachments();
      if (!trimmed && ready.length === 0) return false;

      stickRef.current = true;

      const content = buildContent(trimmed, ready);
      agent.addMessage({
        id: createMessageId(),
        role: "user",
        content,
      });
      void copilotkit
        .runAgent({ agent })
        .catch((err) =>
          console.error("[headless-complete] runAgent failed", err),
        );
      return true;
    },
    [agent, copilotkit, consumeAttachments],
  );

  const handleSend = useCallback(() => {
    if (sendText(input)) {
      setInput("");
    }
  }, [input, sendText]);

  const handleSuggestion = useCallback(
    (text: string) => {
      sendText(text);
    },
    [sendText],
  );

  const handleReset = useCallback(() => {
    if (agent.isRunning) {
      try {
        agent.abortRun();
      } catch {
        // no-op: some transports don't support abort
      }
    }
    agent.setMessages([]);
    setInput("");
    stickRef.current = true;
  }, [agent]);

  const showTypingIndicator = useTypingIndicator(messages, agent.isRunning);

  const hasUploadingAttachment = attachments.some(
    (a) => a.status === "uploading",
  );
  const hasReadyAttachment = attachments.some((a) => a.status === "ready");
  const sendDisabled =
    agent.isRunning ||
    hasUploadingAttachment ||
    (!input.trim() && !hasReadyAttachment);
  const canReset = messages.length > 0 || agent.isRunning;
  const hasMessages = messages.length > 0;

  return (
    <div className="flex h-screen w-full justify-center bg-background p-4 sm:p-6">
      <Card className="flex h-full w-full max-w-3xl flex-col gap-0 overflow-hidden border-border py-0 shadow-2xl shadow-black/10">
        <Header onReset={handleReset} canReset={canReset} />

        <CardContent className="flex min-h-0 flex-1 flex-col p-0">
          {!hasMessages ? (
            // Render empty state outside the ScrollArea so flex-1 + justify-
            // center actually fills the available height. Radix ScrollArea
            // wraps its content in a `display: table` div that breaks
            // `h-full` propagation, so a centered empty state inside it
            // hugs the top of the viewport.
            <div className="flex min-h-0 flex-1 flex-col">
              <EmptyState onPick={handleSuggestion} />
            </div>
          ) : (
            <ScrollArea className="min-h-0 flex-1">
              <div
                ref={listRef}
                className={cn("flex flex-col gap-4 px-4 py-4 sm:px-6")}
              >
                <MessageList messages={messages} />
                {showTypingIndicator && <TypingIndicator />}
                <div ref={bottomRef} />
              </div>
            </ScrollArea>
          )}

          {hasMessages && (
            <SuggestionBar
              agentId={agentId}
              isRunning={agent.isRunning}
              onPick={handleSuggestion}
            />
          )}

          <Separator className="bg-border/60" />

          <Composer
            value={input}
            onChange={setInput}
            onSend={handleSend}
            disabled={sendDisabled}
            isRunning={agent.isRunning}
            attachments={attachments}
            onRemoveAttachment={removeAttachment}
            onFileChange={handleFileUpload}
            fileInputRef={fileInputRef}
            containerRef={containerRef}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            dragOver={dragOver}
          />
        </CardContent>
      </Card>
    </div>
  );
}

// Build the user message body. If no attachments, send a plain string
// (legacy shape). If attachments are present, send the multimodal array
// — text first, then each attachment as its own InputContent part.
function buildContent(
  text: string,
  attachments: Attachment[],
): string | InputContent[] {
  if (attachments.length === 0) return text;
  const parts: InputContent[] = [];
  if (text) parts.push({ type: "text", text });
  for (const att of attachments) {
    parts.push({
      type: att.type,
      source: att.source,
      metadata: {
        ...(att.filename ? { filename: att.filename } : {}),
        ...att.metadata,
      },
    } as InputContent);
  }
  return parts;
}

"use client";

/**
 * Bottom-of-chat composer with attachments support.
 *
 * Layout:
 *   [paperclip icon] [textarea] [send icon]
 * with a chip row above the textarea showing pending attachments. The
 * paperclip triggers the hidden `<input type="file">` exposed by
 * `useAttachments`. Drag/drop handlers are attached to the outer
 * container via the same hook so users can drop a file anywhere on the
 * composer surface.
 */

import React, { useEffect, useRef } from "react";
import { ArrowUp, Paperclip } from "lucide-react";
import type { Attachment } from "@copilotkit/shared";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { AttachmentChip } from "../attachments/attachment-preview";

export interface ComposerProps {
  value: string;
  onChange: (next: string) => void;
  onSend: () => void;
  disabled: boolean;
  isRunning: boolean;
  // Attachments — passthrough from `useAttachments`.
  attachments: Attachment[];
  onRemoveAttachment: (id: string) => void;
  onFileChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  fileInputRef: React.RefObject<HTMLInputElement | null>;
  containerRef: React.RefObject<HTMLDivElement | null>;
  onDragOver: (e: React.DragEvent) => void;
  onDragLeave: (e: React.DragEvent) => void;
  onDrop: (e: React.DragEvent) => void;
  dragOver: boolean;
}

export function Composer({
  value,
  onChange,
  onSend,
  disabled,
  isRunning,
  attachments,
  onRemoveAttachment,
  onFileChange,
  fileInputRef,
  containerRef,
  onDragOver,
  onDragLeave,
  onDrop,
  dragOver,
}: ComposerProps) {
  const ref = useRef<HTMLTextAreaElement | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 160)}px`;
  }, [value]);

  return (
    <div
      ref={containerRef}
      data-testid="headless-composer"
      onDragOver={onDragOver}
      onDragLeave={onDragLeave}
      onDrop={onDrop}
      className="bg-background p-3 sm:p-4"
    >
      <div
        className={cn(
          "flex flex-col gap-2 rounded-2xl border border-border/60 bg-muted/50 p-2",
          "focus-within:bg-background focus-within:ring-2 focus-within:ring-ring/40",
          "transition-colors",
          dragOver && "ring-2 ring-primary/60",
        )}
      >
        {attachments.length > 0 && (
          <div className="flex flex-wrap gap-2 px-1 pt-1">
            {attachments.map((a) => (
              <AttachmentChip
                key={a.id}
                attachment={a}
                onRemove={onRemoveAttachment}
              />
            ))}
          </div>
        )}
        <div className="flex items-end gap-2">
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*,application/pdf"
            multiple
            className="hidden"
            onChange={onFileChange}
          />
          <Button
            type="button"
            size="icon"
            variant="ghost"
            aria-label="Attach file"
            onClick={() => fileInputRef.current?.click()}
            className="h-9 w-9 shrink-0 rounded-xl"
            disabled={isRunning}
          >
            <Paperclip className="h-4 w-4" />
          </Button>
          <Textarea
            ref={ref}
            rows={1}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                if (!disabled) onSend();
              }
            }}
            placeholder={
              isRunning
                ? "Agent is responding..."
                : "Message the agent or drop a file..."
            }
            className={cn(
              "min-h-[40px] max-h-40 flex-1 resize-none border-0 bg-transparent",
              "px-2 py-2 text-sm shadow-none",
              "focus-visible:ring-0 focus-visible:border-transparent",
            )}
          />
          <Button
            type="button"
            size="icon"
            onClick={onSend}
            disabled={disabled}
            aria-label="Send message"
            className="h-9 w-9 shrink-0 rounded-xl"
          >
            <ArrowUp className="h-4 w-4" />
          </Button>
        </div>
      </div>
      <p className="mt-2 px-1 text-center text-[11px] text-muted-foreground">
        Press{" "}
        <kbd className="rounded border bg-muted px-1 py-0.5 font-mono text-[10px]">
          Enter
        </kbd>{" "}
        to send,{" "}
        <kbd className="rounded border bg-muted px-1 py-0.5 font-mono text-[10px]">
          Shift+Enter
        </kbd>{" "}
        for a newline
      </p>
    </div>
  );
}

