"use client";

import { CopilotKit } from "@copilotkit/react-core/v2";
import { AGENT_ID, Chat } from "./chat";

export default function ByocJsonRenderDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-declarative-json-render"
      agent={AGENT_ID}
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

"""Claude Agent SDK backing the BYOC json-render demo.

Emits a single JSON object shaped like ``@json-render/react``'s flat spec
format (``{ root, elements }``) so the frontend can feed it directly into
``<Renderer />`` against a Zod-validated catalog of three components —
MetricCard, BarChart, PieChart.

Wire format
-----------
The agent streams a plain JSON text block (no tool calls, no XML). The
frontend's `JsonRenderAssistantMessage` slot parses the streaming content
and renders the catalog components when the JSON becomes valid.

Scenario mirrors the langgraph-python reference exactly — same catalog
shapes, same example responses — so the two BYOC rows are directly
comparable across frameworks. The only substantive difference is the
underlying LLM provider.
"""

from textwrap import dedent

# System prompt pulled into the dedicated endpoint in agent_server.py.
# Kept verbatim from the langgraph-python reference so behaviour matches
# across frameworks.
BYOC_JSON_RENDER_SYSTEM_PROMPT = dedent(
    """
    You are a sales-dashboard UI generator for a BYOC json-render demo.

    When the user asks for a UI, respond with **exactly one JSON object** and
    nothing else — no prose, no markdown fences, no leading explanation. The
    object must match this schema (the "flat element map" format consumed by
    `@json-render/react`):

    {
      "root": "<id of the root element>",
      "elements": {
        "<id>": {
          "type": "<component name>",
          "props": { ... component-specific props ... },
          "children": [ "<id>", ... ]
        },
        ...
      }
    }

    Available components (use each name verbatim as "type"):

    - MetricCard
      props: { "label": string, "value": string, "trend": string | null }
      Example trend strings: "+12% vs last quarter", "-3% vs last month", null.

    - BarChart
      props: {
        "title": string,
        "description": string | null,
        "data": [ { "label": string, "value": number }, ... ]
      }

    - PieChart
      props: {
        "title": string,
        "description": string | null,
        "data": [ { "label": string, "value": number }, ... ]
      }

    Rules:

    1. Output **only** valid JSON. No markdown code fences. No text outside
       the object.
    2. Every id referenced in `root` or any `children` array must be a key
       in `elements`.
    3. For a multi-component dashboard, use a root MetricCard and list the
       charts in its `children` array, OR pick any element as root and list
       the others as its children. Do not emit orphan elements.
    4. Use realistic sales-domain values (revenue, pipeline, conversion,
       categories, months) — the demo is a sales dashboard.
    5. `children` is optional but when present must be an array of strings.
    6. Never invent component types outside the three listed above.

    ### Worked example — "Show me the sales dashboard with metrics and a revenue chart"

    {
      "root": "revenue-metric",
      "elements": {
        "revenue-metric": {
          "type": "MetricCard",
          "props": {
            "label": "Revenue (Q3)",
            "value": "$1.24M",
            "trend": "+18% vs Q2"
          },
          "children": ["revenue-bar"]
        },
        "revenue-bar": {
          "type": "BarChart",
          "props": {
            "title": "Monthly revenue",
            "description": "Revenue by month across Q3",
            "data": [
              { "label": "Jul", "value": 380000 },
              { "label": "Aug", "value": 410000 },
              { "label": "Sep", "value": 450000 }
            ]
          }
        }
      }
    }

    ### Worked example — "Break down revenue by category as a pie chart"

    {
      "root": "category-pie",
      "elements": {
        "category-pie": {
          "type": "PieChart",
          "props": {
            "title": "Revenue by category",
            "description": "Share of total revenue by product category",
            "data": [
              { "label": "Enterprise", "value": 540000 },
              { "label": "SMB", "value": 310000 },
              { "label": "Self-serve", "value": 220000 },
              { "label": "Partner", "value": 170000 }
            ]
          }
        }
      }
    }

    ### Worked example — "Show me monthly expenses as a bar chart"

    {
      "root": "expense-bar",
      "elements": {
        "expense-bar": {
          "type": "BarChart",
          "props": {
            "title": "Monthly expenses",
            "description": "Operating expenses by month",
            "data": [
              { "label": "Jul", "value": 210000 },
              { "label": "Aug", "value": 225000 },
              { "label": "Sep", "value": 240000 }
            ]
          }
        }
      }
    }

    Respond with the JSON object only.
    """
).strip()


__all__ = ["BYOC_JSON_RENDER_SYSTEM_PROMPT"]

/**
 * Dedicated runtime for the Declarative JSON Render demo.
 *
 * Proxies to the Python FastAPI backend's `/declarative-json-render`
 * endpoint, which swaps in the JSON Render system prompt without leaking it
 * into the shared `/api/copilotkit` runtime.
 */

import type { NextRequest } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { createClaudeHttpAgent } from "@/app/api/_shared/claude-http-agent";
import { internalRuntimeErrorResponse } from "@/app/api/_shared/route-error";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

const agents: Record<string, AbstractAgent> = {
  byoc_json_render: createClaudeHttpAgent(
    `${AGENT_URL}/declarative-json-render`,
  ),
};

const runtime = new CopilotRuntime({
  // @ts-ignore -- see main route.ts
  agents,
});

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-declarative-json-render",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    return internalRuntimeErrorResponse(
      "/api/copilotkit-declarative-json-render",
      error,
    );
  }
};

import { defineCatalog } from "@json-render/core";
import { schema } from "@json-render/react/schema";
// json-render 0.18 requires Zod 4; A2UI stays on Zod 3.
import { z } from "zod4";

const dataPoint = z.object({ label: z.string(), value: z.number() });

export const catalog = defineCatalog(schema, {
  components: {
    MetricCard: {
      props: z.object({
        label: z.string(),
        value: z.string(),
        trend: z.string().nullable(),
      }),
      description:
        "A labelled metric (single number) with an optional trend subtitle",
    },
    BarChart: {
      props: z.object({
        title: z.string(),
        description: z.string().nullable(),
        data: z.array(dataPoint),
      }),
      description:
        "A vertical bar chart for comparing discrete values side by side",
    },
    PieChart: {
      props: z.object({
        title: z.string(),
        description: z.string().nullable(),
        data: z.array(dataPoint),
      }),
      description:
        "A donut-style pie chart for breaking a total down into category slices",
    },
  },
  actions: {},
});

"use client";

import { useRef } from "react";
import {
  BarChart as RechartsBarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Rectangle,
} from "recharts";
import { CHART_COLORS, CHART_CONFIG } from "./chart-config";

export interface BarChartDatum {
  label: string;
  value: number;
}

export interface BarChartComponentProps {
  title: string;
  description?: string | null;
  data: BarChartDatum[];
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function AnimatedBar({ isNew, ...rest }: any) {
  return (
    <g
      style={
        isNew
          ? { animation: "barSlideIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) both" }
          : undefined
      }
    >
      <Rectangle {...rest} />
    </g>
  );
}

export function BarChart({ title, description, data }: BarChartComponentProps) {
  const seen = useRef(new Set<number>());
  const isNew = (i: number) => {
    if (seen.current.has(i)) return false;
    seen.current.add(i);
    return true;
  };

  const hasData = Array.isArray(data) && data.length > 0;

  return (
    <div
      data-testid="bar-chart"
      className="max-w-2xl mx-auto my-4 overflow-hidden rounded-lg border border-[var(--border)] bg-[var(--card)]"
    >
      {hasData && (
        <style>{`@keyframes barSlideIn { from { transform: translateY(40px); opacity: 0; } 20% { opacity: 1; } to { transform: translateY(0); opacity: 1; } }`}</style>
      )}
      <div className="p-6 pb-2">
        <h3 className="text-lg font-semibold leading-none tracking-tight text-[var(--foreground)]">
          {title}
        </h3>
        {description ? (
          <p className="text-sm text-[var(--muted-foreground)]">
            {description}
          </p>
        ) : null}
      </div>
      <div className="p-6 pt-2">
        {hasData ? (
          <ResponsiveContainer width="100%" height={280}>
            <RechartsBarChart
              data={data}
              margin={{ top: 12, right: 12, bottom: 4, left: -8 }}
            >
              <CartesianGrid
                strokeDasharray="3 3"
                stroke="var(--border)"
                vertical={false}
              />
              <XAxis
                dataKey="label"
                tick={{ fontSize: 12, fill: "var(--muted-foreground)" }}
                stroke="var(--border)"
                tickLine={false}
                axisLine={false}
              />
              <YAxis
                tick={{ fontSize: 12, fill: "var(--muted-foreground)" }}
                stroke="var(--border)"
                tickLine={false}
                axisLine={false}
              />
              <Tooltip
                contentStyle={CHART_CONFIG.tooltipStyle}
                cursor={{ fill: "var(--secondary)", opacity: 0.5 }}
              />
              <Bar
                isAnimationActive={false}
                dataKey="value"
                radius={[6, 6, 0, 0]}
                maxBarSize={48}
                shape={(props: unknown) => {
                  const p = props as Record<string, unknown>;
                  return (
                    <AnimatedBar {...p} isNew={isNew(p.index as number)} />
                  );
                }}
              >
                {data.map((_, i) => (
                  <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />
                ))}
              </Bar>
            </RechartsBarChart>
          </ResponsiveContainer>
        ) : (
          <p className="text-[var(--muted-foreground)] text-center py-8 text-sm">
            No data available
          </p>
        )}
      </div>
    </div>
  );
}

export const CHART_COLORS = [
  "#BEC2FF", // lilac-400
  "#85ECCE", // mint-400
  "#FFAC4D", // orange-400
  "#FFF388", // yellow-400
  "#189370", // mint-800
  "#EEE6FE", // primary-100
  "#FA5F67", // red-400
] as const;

export const CHART_CONFIG = {
  tooltipStyle: {
    backgroundColor: "var(--card)",
    border: "1px solid var(--border)",
    borderRadius: "10px",
    padding: "10px 14px",
    color: "var(--foreground)",
    fontSize: "13px",
    fontFamily: "var(--font-body)",
    boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
  },
};

"use client";

import { CHART_COLORS } from "./chart-config";

export interface PieChartDatum {
  label: string;
  value: number;
}

export interface PieChartComponentProps {
  title: string;
  description?: string | null;
  data: PieChartDatum[];
}

function DonutChart({
  data,
  size = 240,
  strokeWidth = 40,
}: {
  data: PieChartDatum[];
  size?: number;
  strokeWidth?: number;
}) {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const center = size / 2;
  const total = data.reduce((sum, d) => sum + (Number(d.value) || 0), 0);

  let accumulated = 0;
  const slices = data.map((item, i) => {
    const arc =
      (total > 0 ? (Number(item.value) || 0) / total : 0) * circumference;
    const dashoffset = -accumulated;
    accumulated += arc;
    return {
      arc,
      gap: circumference - arc,
      dashoffset,
      color: CHART_COLORS[i % CHART_COLORS.length],
    };
  });

  return (
    <svg
      width="100%"
      viewBox={`0 0 ${size} ${size}`}
      className="block mx-auto"
      style={{ maxWidth: size, transform: "scaleX(-1)" }}
    >
      <circle
        cx={center}
        cy={center}
        r={radius}
        fill="none"
        stroke="var(--secondary)"
        strokeWidth={strokeWidth}
      />
      {slices.map((s, i) => (
        <circle
          key={i}
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke={s.color}
          strokeWidth={strokeWidth}
          strokeDasharray={`${s.arc} ${s.gap}`}
          strokeDashoffset={s.dashoffset}
          strokeLinecap="butt"
          transform={`rotate(-90 ${center} ${center})`}
        />
      ))}
    </svg>
  );
}

export function PieChart({ title, description, data }: PieChartComponentProps) {
  const hasData = Array.isArray(data) && data.length > 0;
  const total = hasData
    ? data.reduce((sum, d) => sum + (Number(d.value) || 0), 0)
    : 0;

  return (
    <div
      data-testid="pie-chart"
      className="max-w-lg mx-auto my-4 overflow-hidden rounded-lg border border-[var(--border)] bg-[var(--card)]"
    >
      <div className="p-6 pb-0">
        <h3 className="text-lg font-semibold leading-none tracking-tight text-[var(--foreground)]">
          {title}
        </h3>
        {description ? (
          <p className="text-sm text-[var(--muted-foreground)]">
            {description}
          </p>
        ) : null}
      </div>
      <div className="p-6 pt-4">
        {hasData ? (
          <>
            <DonutChart data={data} />
            <div className="space-y-2 pt-4">
              {data.map((item, i) => {
                const val = Number(item.value) || 0;
                const pct = total > 0 ? ((val / total) * 100).toFixed(0) : 0;
                return (
                  <div key={i} className="flex items-center gap-3 text-sm">
                    <span
                      className="inline-block h-3 w-3 rounded-full shrink-0"
                      style={{
                        backgroundColor: CHART_COLORS[i % CHART_COLORS.length],
                      }}
                    />
                    <span className="flex-1 text-[var(--foreground)] truncate">
                      {item.label}
                    </span>
                    <span className="text-[var(--muted-foreground)] tabular-nums">
                      {val.toLocaleString()}
                    </span>
                    <span className="text-[var(--muted-foreground)] text-sm w-10 text-right tabular-nums">
                      {pct}%
                    </span>
                  </div>
                );
              })}
            </div>
          </>
        ) : (
          <p className="text-[var(--muted-foreground)] text-center py-8 text-sm">
            No data available
          </p>
        )}
      </div>
    </div>
  );
}

"use client";

import type { CopilotChatAssistantMessage } from "@copilotkit/react-core/v2";
import { CopilotChat } from "@copilotkit/react-core/v2";
import { JsonRenderAssistantMessage } from "./json-render-renderer";
import { useByocJsonRenderSuggestions } from "./suggestions";

export const AGENT_ID = "byoc_json_render";

export function Chat() {
  useByocJsonRenderSuggestions();

  return (
    <CopilotChat
      agentId={AGENT_ID}
      className="h-full rounded-2xl"
      messageView={{
        assistantMessage:
          JsonRenderAssistantMessage as unknown as typeof CopilotChatAssistantMessage,
      }}
    />
  );
}

"use client";

import { useMemo } from "react";
import { CopilotChatAssistantMessage } from "@copilotkit/react-core/v2";
import type { CopilotChatAssistantMessageProps } from "@copilotkit/react-core/v2";
import { JSONUIProvider, Renderer } from "@json-render/react";
import { registry } from "./registry";
import type { JsonRenderSpec } from "./types";

const ALLOWED_TYPES = new Set(["MetricCard", "BarChart", "PieChart"]);

export function JsonRenderAssistantMessage(
  props: CopilotChatAssistantMessageProps,
) {
  const content =
    typeof props.message.content === "string" ? props.message.content : "";
  const spec = useMemo(() => parseSpec(content), [content]);

  // Stream not yet a valid spec (or plain prose) — render the default bubble.
  if (!spec) return <CopilotChatAssistantMessage {...props} />;

  return (
    <div
      data-testid="copilot-assistant-message"
      data-message-role="assistant"
      className="w-full"
    >
      <div data-testid="json-render-root" className="w-full">
        <JSONUIProvider registry={registry}>
          <Renderer
            spec={spec as unknown as Parameters<typeof Renderer>[0]["spec"]}
            registry={registry}
          />
        </JSONUIProvider>
      </div>
    </div>
  );
}

/** Parse a json-render spec out of the assistant content, tolerating code fences and prose. */
function parseSpec(raw: string): JsonRenderSpec | null {
  const jsonText = extractJsonObject(raw);
  if (!jsonText) return null;

  let parsed: unknown;
  try {
    parsed = JSON.parse(jsonText);
  } catch {
    return null;
  }

  if (!isRecord(parsed)) return null;
  const { root, elements } = parsed as { root?: unknown; elements?: unknown };
  if (typeof root !== "string" || !isRecord(elements) || !(root in elements)) {
    return null;
  }

  for (const el of Object.values(elements)) {
    if (!isRecord(el)) return null;
    if (typeof el.type !== "string" || !ALLOWED_TYPES.has(el.type)) return null;
    if (el.props !== undefined && !isRecord(el.props)) return null;
  }

  return parsed as unknown as JsonRenderSpec;
}

/** Strip code fences, then return the first balanced {...} object as a string. */
function extractJsonObject(raw: string): string | null {
  if (!raw?.trim()) return null;
  const fence = /```(?:json)?\s*([\s\S]*?)```/i.exec(raw);
  const candidate = (fence ? fence[1] : raw).trim();
  const start = candidate.indexOf("{");
  if (start === -1) return null;

  let depth = 0;
  let inString = false;
  let escape = false;
  for (let i = start; i < candidate.length; i++) {
    const ch = candidate[i];
    if (escape) {
      escape = false;
      continue;
    }
    if (inString) {
      if (ch === "\\") escape = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') {
      inString = true;
      continue;
    }
    if (ch === "{") depth++;
    else if (ch === "}" && --depth === 0) return candidate.slice(start, i + 1);
  }
  return null;
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

"use client";

export interface MetricCardComponentProps {
  label: string;
  value: string;
  trend?: string | null;
}

export function MetricCard({ label, value, trend }: MetricCardComponentProps) {
  const direction = inferTrendDirection(trend);

  return (
    <div
      data-testid="metric-card"
      className="max-w-xs mx-auto my-3 rounded-lg border border-[var(--border)] bg-[var(--card)] p-5"
    >
      <div className="text-xs font-medium uppercase tracking-wider text-[var(--muted-foreground)]">
        {label}
      </div>
      <div className="mt-1 text-3xl font-semibold tabular-nums text-[var(--foreground)]">
        {value}
      </div>
      {trend ? (
        <div
          className={`mt-2 inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium ${BADGE_CLASS[direction]}`}
        >
          {trend}
        </div>
      ) : null}
    </div>
  );
}

function inferTrendDirection(
  trend: string | null | undefined,
): "up" | "down" | "neutral" {
  const t = trend?.trim();
  if (!t) return "neutral";
  if (t.startsWith("+")) return "up";
  if (t.startsWith("-") || t.startsWith("−")) return "down";
  return "neutral";
}

const BADGE_CLASS = {
  up: "bg-[color-mix(in_oklab,var(--primary)_15%,transparent)] text-[var(--primary)]",
  down: "bg-[color-mix(in_oklab,var(--destructive)_15%,transparent)] text-[var(--destructive)]",
  neutral: "bg-[var(--secondary)] text-[var(--muted-foreground)]",
} as const;

