"use client";

import React, { useMemo } from "react";
import {
  CopilotKit,
  CopilotChat,
  useHumanInTheLoop,
  useConfigureSuggestions,
} from "@copilotkit/react-core/v2";
import { z } from "zod";
import type { TimeSlot } from "./time-picker-card";
import { TimePickerCard } from "./time-picker-card";

function buildDefaultSlots(now = new Date()): TimeSlot[] {
  const tomorrow = new Date(now);
  tomorrow.setDate(tomorrow.getDate() + 1);

  const monday = new Date(now);
  const daysUntilMonday = (8 - monday.getDay()) % 7 || 7;
  monday.setDate(monday.getDate() + daysUntilMonday);

  return [
    buildSlot(tomorrow, "Tomorrow", 10, 0),
    buildSlot(tomorrow, "Tomorrow", 14, 0),
    buildSlot(monday, "Monday", 9, 0),
    buildSlot(monday, "Monday", 15, 30),
  ];
}

function buildSlot(
  date: Date,
  labelPrefix: string,
  hour: number,
  minute: number,
): TimeSlot {
  const slotDate = new Date(date);
  slotDate.setHours(hour, minute, 0, 0);
  return {
    label: `${labelPrefix} ${formatTime(slotDate)}`,
    iso: slotDate.toISOString(),
  };
}

function formatTime(date: Date): string {
  return date.toLocaleTimeString([], {
    hour: "numeric",
    minute: "2-digit",
  });
}

export default function HitlInChatDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="hitl-in-chat">
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  const slots = useMemo(() => buildDefaultSlots(), []);

  useConfigureSuggestions({
    suggestions: [
      {
        title: "Book a call with sales",
        message:
          "Please book an intro call with the sales team to discuss pricing.",
      },
      {
        title: "Schedule a 1:1 with Alice",
        message: "Schedule a 1:1 with Alice next week to review Q2 goals.",
      },
    ],
    available: "always",
  });

  useHumanInTheLoop({
    agentId: "hitl-in-chat",
    name: "book_call",
    description:
      "Ask the user to pick a time slot for a call. The picker UI presents fixed candidate slots; the user's choice is returned to the agent.",
    parameters: z.object({
      topic: z
        .string()
        .describe("What the call is about (e.g. 'Intro with sales')"),
      attendee: z
        .string()
        .describe("Who the call is with (e.g. 'Alice from Sales')"),
    }),
    render: ({ args, status, respond }: any) => (
      <TimePickerCard
        topic={args?.topic ?? "a call"}
        attendee={args?.attendee}
        slots={slots}
        status={status}
        onSubmit={(result) => respond?.(result)}
      />
    ),
  });

  return <CopilotChat agentId="hitl-in-chat" className="h-full rounded-2xl" />;
}

"""Claude Agent SDK backend for the In-Chat HITL (useHumanInTheLoop) demo.

The `book_call` tool is defined on the FRONTEND via `useHumanInTheLoop`,
so there is no backend tool here. The agent simply responds in chat and
relies on the standard frontend-tool / tool-call lifecycle to invoke
`book_call` when the user asks to book.

Mirrors the langgraph-python `hitl_in_chat_agent.py` reference.
"""

from __future__ import annotations

import json
import os
import traceback
from collections.abc import AsyncIterator
from textwrap import dedent
from typing import Any

import anthropic
from ag_ui.core import (
    EventType,
    RunAgentInput,
    RunFinishedEvent,
    RunStartedEvent,
    TextMessageContentEvent,
    TextMessageEndEvent,
    TextMessageStartEvent,
    ToolCallArgsEvent,
    ToolCallEndEvent,
    ToolCallStartEvent,
)
from ag_ui.encoder import EventEncoder

from agents.claude_agent_sdk_adapter import normalize_claude_model


SYSTEM_PROMPT = dedent("""
    You help users book an onboarding call with the sales team. When they
    ask to book a call, call the frontend-provided `book_call` tool with a
    short topic and the user's name (use a sensible placeholder like
    'Alice from Sales' if no attendee was specified). Keep any chat reply
    to one short sentence.
""").strip()


async def run_hitl_in_chat_agent(input_data: RunAgentInput) -> AsyncIterator[str]:
    """Stream a Claude response that may call the frontend `book_call` tool.

    `book_call` is defined on the frontend via `useHumanInTheLoop`. AG-UI
    forwards frontend tool definitions in `input_data.tools`, so we just
    pass them straight to Claude and let the standard tool-call lifecycle
    resolve the user's choice back through CopilotKit.
    """
    encoder = EventEncoder()
    client = anthropic.AsyncAnthropic(api_key=os.getenv("ANTHROPIC_API_KEY", ""))

    # Convert AG-UI messages to Anthropic format.
    #
    # AG-UI delivers three message roles:
    #   - "user"      → plain user text
    #   - "assistant" → assistant text + optional tool_use blocks
    #   - "tool"      → tool result from a resolved frontend tool
    #
    # When the CopilotKit runtime re-invokes this agent after the user
    # resolves a frontend tool (e.g. picks a time slot in the book_call
    # HITL UI), the messages array includes:
    #   1. assistant message with tool_use content (the original tool call)
    #   2. tool message with the resolved result
    #
    # Anthropic's Messages API represents tool results as a "user" role
    # message with content blocks of type "tool_result". We must convert
    # AG-UI "tool" messages into that shape, and assistant messages with
    # tool_use content into Anthropic's structured format, so the LLM
    # sees the full conversation and aimock's ``hasToolResult`` matcher
    # fires correctly.
    messages: list[dict[str, Any]] = []
    for msg in input_data.messages or []:
        role = msg.role.value if hasattr(msg.role, "value") else str(msg.role)

        # Handle tool result messages from AG-UI (resolved frontend tools).
        if role == "tool":
            tool_call_id = getattr(msg, "tool_call_id", None) or (
                getattr(msg, "toolCallId", None)
            )
            raw = getattr(msg, "content", None)
            result_text = ""
            if isinstance(raw, str):
                result_text = raw
            elif isinstance(raw, list):
                parts = []
                for part in raw:
                    if hasattr(part, "text"):
                        parts.append(part.text)
                    elif isinstance(part, dict) and "text" in part:
                        parts.append(part["text"])
                parts_text = "".join(parts)
                if parts_text:
                    result_text = parts_text
                else:
                    result_text = json.dumps(raw)
            if tool_call_id:
                messages.append(
                    {
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": tool_call_id,
                                "content": result_text,
                            }
                        ],
                    }
                )
            continue

        if role not in ("user", "assistant"):
            continue

        raw = getattr(msg, "content", None)

        # For assistant messages, check for tool calls (AG-UI's
        # AssistantMessage stores them in `tool_calls`, not in `content`).
        # Anthropic requires tool_use blocks in the assistant content so
        # the subsequent tool_result can pair with them.
        if role == "assistant":
            msg_tool_calls = getattr(msg, "tool_calls", None)
            text_content = ""
            if isinstance(raw, str):
                text_content = raw
            elif isinstance(raw, list):
                for part in raw:
                    if hasattr(part, "text"):
                        text_content += part.text
                    elif isinstance(part, dict) and "text" in part:
                        text_content += part["text"]

            if msg_tool_calls:
                content_blocks: list[dict[str, Any]] = []
                if text_content:
                    content_blocks.append({"type": "text", "text": text_content})
                for tc in msg_tool_calls:
                    tc_id = getattr(tc, "id", None) or (
                        tc.get("id") if isinstance(tc, dict) else None
                    )
                    func = getattr(tc, "function", None) or (
                        tc.get("function") if isinstance(tc, dict) else None
                    )
                    if func:
                        tc_name = getattr(func, "name", None) or (
                            func.get("name") if isinstance(func, dict) else "unknown"
                        )
                        tc_args_str = getattr(func, "arguments", None) or (
                            func.get("arguments", "{}")
                            if isinstance(func, dict)
                            else "{}"
                        )
                    else:
                        tc_name = "unknown"
                        tc_args_str = "{}"
                    try:
                        tc_args = (
                            json.loads(tc_args_str)
                            if isinstance(tc_args_str, str)
                            else tc_args_str
                        )
                    except json.JSONDecodeError:
                        tc_args = {}
                    content_blocks.append(
                        {
                            "type": "tool_use",
                            "id": tc_id or "unknown",
                            "name": tc_name,
                            "input": tc_args,
                        }
                    )
                messages.append({"role": "assistant", "content": content_blocks})
                continue
            elif text_content:
                messages.append({"role": "assistant", "content": text_content})
                continue

        content = ""
        if isinstance(raw, str):
            content = raw
        elif isinstance(raw, list):
            parts = []
            for part in raw:
                if hasattr(part, "text"):
                    parts.append(part.text)
                elif isinstance(part, dict) and "text" in part:
                    parts.append(part["text"])
            content = "".join(parts)
        if content:
            messages.append({"role": role, "content": content})

    # Forward frontend-defined tools (including useHumanInTheLoop's `book_call`)
    # to Claude. AG-UI sends them in `input_data.tools` with JSON-Schema
    # parameters; Claude expects `input_schema` of the same shape.
    tools: list[dict[str, Any]] = []
    for t in input_data.tools or []:
        # AG-UI Tool schema: { name, description, parameters }
        name = getattr(t, "name", None) or (
            t.get("name") if isinstance(t, dict) else None
        )
        description = getattr(t, "description", None) or (
            t.get("description", "") if isinstance(t, dict) else ""
        )
        parameters = getattr(t, "parameters", None) or (
            t.get("parameters", {}) if isinstance(t, dict) else {}
        )
        if not name:
            continue
        tools.append(
            {
                "name": name,
                "description": description or "",
                "input_schema": parameters or {"type": "object", "properties": {}},
            }
        )

    thread_id = input_data.thread_id or "default"
    run_id = input_data.run_id or "run-1"

    yield encoder.encode(
        RunStartedEvent(type=EventType.RUN_STARTED, thread_id=thread_id, run_id=run_id)
    )

    msg_id = f"msg-{run_id}-0"
    yield encoder.encode(
        TextMessageStartEvent(
            type=EventType.TEXT_MESSAGE_START,
            message_id=msg_id,
            role="assistant",
        )
    )

    stream_kwargs: dict[str, Any] = {
        "model": normalize_claude_model(
            os.getenv("ANTHROPIC_MODEL", "claude-opus-4-8")
        ),
        "max_tokens": 1024,
        "system": SYSTEM_PROMPT,
        "messages": messages,
    }
    if tools:
        stream_kwargs["tools"] = tools  # type: ignore[assignment]

    try:
        async with client.messages.stream(**stream_kwargs) as stream:
            current_tool_id: str | None = None
            current_tool_name: str | None = None

            async for event in stream:
                etype = type(event).__name__

                if etype == "RawContentBlockStartEvent":
                    block = event.content_block  # type: ignore[attr-defined]
                    if block.type == "tool_use":
                        current_tool_id = block.id
                        current_tool_name = block.name
                        yield encoder.encode(
                            ToolCallStartEvent(
                                type=EventType.TOOL_CALL_START,
                                tool_call_id=current_tool_id,
                                tool_call_name=current_tool_name,
                                parent_message_id=msg_id,
                            )
                        )

                elif etype == "RawContentBlockDeltaEvent":
                    delta = event.delta  # type: ignore[attr-defined]
                    if delta.type == "text_delta":
                        yield encoder.encode(
                            TextMessageContentEvent(
                                type=EventType.TEXT_MESSAGE_CONTENT,
                                message_id=msg_id,
                                delta=delta.text,
                            )
                        )
                    elif delta.type == "input_json_delta":
                        yield encoder.encode(
                            ToolCallArgsEvent(
                                type=EventType.TOOL_CALL_ARGS,
                                tool_call_id=current_tool_id or "",
                                delta=delta.partial_json,
                            )
                        )

                elif etype in (
                    "RawContentBlockStopEvent",
                    "ParsedContentBlockStopEvent",
                ):
                    if current_tool_id:
                        yield encoder.encode(
                            ToolCallEndEvent(
                                type=EventType.TOOL_CALL_END,
                                tool_call_id=current_tool_id,
                            )
                        )
                        current_tool_id = None
                        current_tool_name = None
    except Exception:
        err_text = f"Agent error: {traceback.format_exc()}"
        yield encoder.encode(
            TextMessageContentEvent(
                type=EventType.TEXT_MESSAGE_CONTENT,
                message_id=msg_id,
                delta=err_text,
            )
        )

    yield encoder.encode(
        TextMessageEndEvent(
            type=EventType.TEXT_MESSAGE_END,
            message_id=msg_id,
        )
    )

    # Frontend (`useHumanInTheLoop`) resolves `book_call` and the runtime
    # injects the resolution back into a follow-up turn. Each turn is its
    # own POST so we don't loop here — emitting RUN_FINISHED returns control
    # to the runtime, which will re-invoke us with the resolved tool result.
    yield encoder.encode(
        RunFinishedEvent(
            type=EventType.RUN_FINISHED, thread_id=thread_id, run_id=run_id
        )
    )

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { createClaudeHttpAgent } from "@/app/api/_shared/claude-http-agent";
import crypto from "node:crypto";

// The agent backend runs as a separate process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

function createAgent(path = "/") {
  return createClaudeHttpAgent(`${AGENT_URL}${path}`);
}

// Register the same agent under all names used by demo pages. Entries that
// need backend-owned tools/state are re-pointed by `dedicatedAgentPaths`.
const agentNames = [
  "agentic_chat",
  "agentic-chat",
  "human_in_the_loop",
  "hitl",
  "tool-rendering",
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-write",
  "shared-state-streaming",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "frontend_tools",
  "frontend-tools",
  "threadid-frontend-tool-roundtrip",
  "frontend-tools-async",
  "hitl-in-chat",
  "hitl-in-app",
  "readonly-state-agent-context",
  "headless-complete",
  "beautiful-chat",
  "declarative-gen-ui",
  "open-gen-ui",
  "open-gen-ui-advanced",
  "mcp-apps",
  "declarative_json_render",
  "declarative-hashbrown-demo",
  "multimodal-demo",
  "voice-demo",
  "agent-config-demo",
  "auth-demo",
  "gen-ui-interrupt",
  "interrupt-headless",
  "reasoning-default",
  "reasoning-custom",
];

// Demos with dedicated FastAPI endpoints (their own state schema, tool
// set, or prompt). The Python backend mounts each at /<name>; mapping
// the agent name to that path keeps the runtime config flat.
const dedicatedAgentPaths: Record<string, string> = {
  "gen-ui-agent": "/gen-ui-agent",
  "tool-rendering": "/tool-rendering",
  "tool-rendering-default-catchall": "/tool-rendering",
  "tool-rendering-custom-catchall": "/tool-rendering",
  "shared-state-read-write": "/shared-state-read-write",
  "shared-state-streaming": "/shared-state-streaming",
  subagents: "/subagents",
  // Reasoning demos share a single backend that emits AG-UI
  // REASONING_MESSAGE_* events (parsed out of <reasoning>...</reasoning>
  // blocks the model emits). The two demo cells differ only on the
  // frontend slot configuration.
  "reasoning-default": "/reasoning",
  "reasoning-custom": "/reasoning",
  "tool-rendering-reasoning-chain": "/tool-rendering-reasoning-chain",
  "headless-complete": "/headless-complete",
  "hitl-in-chat": "/hitl-in-chat",
  "hitl-in-chat-booking": "/hitl-in-chat",
  "gen-ui-interrupt": "/interrupt-adapted",
  "interrupt-headless": "/interrupt-adapted",
};

const agents: Record<string, AbstractAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent();
}
for (const [name, path] of Object.entries(dedicatedAgentPaths)) {
  agents[name] = createAgent(path);
}
agents["default"] = createAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- Published CopilotRuntime agents type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in source, pending release
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    // Log the full error server-side with a correlation id, but only return
    // a generic message + errorId to the client so we don't leak stack
    // traces or internal error messages to untrusted callers. Mirrors the
    // pattern used in `mastra/src/app/api/copilotkit/route.ts`.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = crypto.randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        route: "/api/copilotkit",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

"use client";

import React, { useState } from "react";

export interface TimeSlot {
  label: string;
  iso: string;
}

export type TimePickerStatus = "inProgress" | "executing" | "complete";

export interface TimePickerCardProps {
  topic: string;
  attendee?: string;
  slots: TimeSlot[];
  status: TimePickerStatus;
  onSubmit: (
    result: { chosen_time: string; chosen_label: string } | { cancelled: true },
  ) => void;
}

/**
 * Renders a "Book a call" card with a small grid of time slots.
 * The user picks one slot (or cancels); that resolution is forwarded back
 * to the agent via the onSubmit callback wired up by `useHumanInTheLoop`.
 */
export function TimePickerCard({
  topic,
  attendee,
  slots,
  status,
  onSubmit,
}: TimePickerCardProps) {
  const [picked, setPicked] = useState<TimeSlot | null>(null);
  const [cancelled, setCancelled] = useState(false);
  const disabled = status !== "executing" || picked !== null || cancelled;

  if (cancelled) {
    return (
      <div
        className="rounded-2xl border border-[#DBDBE5] bg-[#F7F7F9] p-4 text-sm text-[#57575B] max-w-md"
        data-testid="time-picker-cancelled"
      >
        Cancelled — no time picked.
      </div>
    );
  }

  if (picked) {
    return (
      <div
        className="rounded-2xl border border-[#85ECCE4D] bg-[#85ECCE]/10 p-4 max-w-md"
        data-testid="time-picker-picked"
      >
        <p className="text-sm text-[#010507]">
          Booked for <span className="font-semibold">{picked.label}</span>
        </p>
      </div>
    );
  }

  return (
    <div
      className="rounded-2xl border border-[#DBDBE5] bg-white p-5 shadow-sm max-w-md"
      data-testid="time-picker-card"
    >
      <p className="text-[10px] uppercase tracking-[0.14em] text-[#57575B] font-medium">
        Book a call
      </p>
      <h3 className="text-base font-semibold text-[#010507] mt-1.5">{topic}</h3>
      {attendee && (
        <p className="text-sm text-[#57575B] mt-0.5">With {attendee}</p>
      )}

      <p className="text-sm text-[#57575B] mt-4 mb-2">Pick a time:</p>
      <div className="grid grid-cols-2 gap-2">
        {slots.map((s) => (
          <button
            key={s.iso}
            disabled={disabled}
            data-testid="time-picker-slot"
            onClick={() => {
              setPicked(s);
              onSubmit({ chosen_time: s.iso, chosen_label: s.label });
            }}
            className="rounded-xl border border-[#DBDBE5] bg-white px-3 py-2 text-sm font-medium text-[#010507] hover:border-[#BEC2FF] hover:bg-[#BEC2FF1A] disabled:opacity-50 transition-colors"
          >
            {s.label}
          </button>
        ))}
      </div>
      <button
        disabled={disabled}
        onClick={() => {
          setCancelled(true);
          onSubmit({ cancelled: true });
        }}
        className="mt-3 w-full rounded-xl border border-[#E9E9EF] px-3 py-1.5 text-xs text-[#838389] hover:bg-[#FAFAFC] disabled:opacity-50 transition-colors"
      >
        None of these work
      </button>
    </div>
  );
}

