"use client";

/**
 * Declarative Generative UI (A2UI — Dynamic Schema) demo.
 *
 * Pattern:
 *   1. Define a small set of branded React components + Zod schemas in
 *      `./a2ui/definitions.ts` and `./a2ui/renderers.tsx` (the latter calls
 *      `createCatalog(..., { includeBasicCatalog: true })` and exports
 *      `myCatalog`).
 *   2. Pass that catalog to the provider via
 *      `<CopilotKit a2ui={{ catalog: myCatalog }}>`.
 *   3. The provider points at the dedicated runtime at
 *      `/api/copilotkit-declarative-gen-ui`, which renders the A2UI surfaces
 *      the `declarative-gen-ui` agent produces.
 *
 * Reference:
 *   https://docs.copilotkit.ai/integrations/langgraph/generative-ui/a2ui
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";

import { myCatalog } from "./a2ui/catalog";
import { Chat } from "./chat";

export default function DeclarativeGenUIDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-declarative-gen-ui"
      agent="declarative-gen-ui"
      a2ui={{ catalog: myCatalog }}
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

"""Claude Agent SDK backend for the Declarative Generative UI (A2UI Dynamic) demo.

The agent exposes a single `generate_a2ui(context: str)` tool. When called,
it invokes a secondary Claude call bound to the `render_a2ui` tool schema
(forced via `tool_choice`) and returns an `a2ui_operations` container which
the runtime's A2UI middleware detects and forwards to the frontend renderer.

The dedicated runtime route (`api/copilotkit-declarative-gen-ui/route.ts`)
sets `injectA2UITool: false` so the runtime does not double-bind a second
A2UI tool on top of this one — the registered client catalog is still
serialised into `copilotkit.context` so the secondary LLM knows what's
available.

Mirrors the langgraph-python and ag2 references.
"""

from __future__ import annotations

import asyncio
import json
import os
import traceback
from collections.abc import AsyncIterator
from textwrap import dedent
from typing import Any

import anthropic
from ag_ui.core import (
    EventType,
    RunAgentInput,
    RunFinishedEvent,
    RunStartedEvent,
    TextMessageContentEvent,
    TextMessageEndEvent,
    TextMessageStartEvent,
    ToolCallArgsEvent,
    ToolCallEndEvent,
    ToolCallResultEvent,
    ToolCallStartEvent,
)
from ag_ui.encoder import EventEncoder

from tools import (
    RENDER_A2UI_TOOL_SCHEMA,
    build_a2ui_operations_from_tool_call,
)
from agents._anthropic_message_safety import sanitize_unresolved_tool_uses
from agents.claude_agent_sdk_adapter import normalize_claude_model


SYSTEM_PROMPT = dedent("""
    You are a demo assistant for Declarative Generative UI (A2UI — Dynamic
    Schema). Whenever a response would benefit from a rich visual — a
    dashboard, status report, KPI summary, card layout, info grid, a
    pie/donut chart of part-of-whole breakdowns, a bar chart comparing
    values across categories, or anything more structured than plain text —
    call `generate_a2ui` to draw it. The registered catalog includes
    `Card`, `StatusBadge`, `Metric`, `InfoRow`, `PrimaryButton`, `PieChart`,
    and `BarChart` (in addition to the basic A2UI primitives). Prefer
    `PieChart` for part-of-whole breakdowns and `BarChart` for comparisons
    across categories. `generate_a2ui` takes a single `context` argument
    summarising the conversation. Keep chat replies to one short sentence;
    let the UI do the talking.
""").strip()


GENERATE_A2UI_TOOL = {
    "name": "generate_a2ui",
    "description": (
        "Generate dynamic A2UI components based on the conversation. "
        "A secondary LLM designs the UI schema and data using the registered catalog."
    ),
    "input_schema": {
        "type": "object",
        "properties": {
            "context": {
                "type": "string",
                "description": "Conversation context summary the secondary LLM should design UI from.",
            },
        },
        "required": ["context"],
    },
}


def _generate_a2ui(
    context: str, conversation_messages: list[dict[str, Any]] | None = None
) -> dict[str, Any]:
    """Invoke a secondary LLM bound to render_a2ui and return an operations container."""
    client = anthropic.Anthropic(api_key=os.getenv("ANTHROPIC_API_KEY", ""))
    render_tool_schema = {
        "name": RENDER_A2UI_TOOL_SCHEMA["name"],
        "description": RENDER_A2UI_TOOL_SCHEMA["description"],
        "input_schema": RENDER_A2UI_TOOL_SCHEMA["parameters"],
    }
    llm_messages = (
        sanitize_unresolved_tool_uses(conversation_messages)
        if conversation_messages
        else [
            {
                "role": "user",
                "content": "Generate a dynamic A2UI dashboard based on the conversation.",
            }
        ]
    )
    response = client.messages.create(
        model=normalize_claude_model(os.getenv("ANTHROPIC_MODEL", "claude-opus-4-8")),
        max_tokens=4096,
        system=context or "Generate a useful dashboard UI.",
        messages=llm_messages,
        tools=[render_tool_schema],
        tool_choice={"type": "tool", "name": "render_a2ui"},
    )
    for block in response.content:
        if getattr(block, "type", None) == "tool_use" and block.name == "render_a2ui":
            return build_a2ui_operations_from_tool_call(dict(block.input))
    return {"error": "LLM did not call render_a2ui"}




async def run_a2ui_dynamic_agent(input_data: RunAgentInput) -> AsyncIterator[str]:
    """Stream a Claude conversation that may call `generate_a2ui`."""
    encoder = EventEncoder()
    client = anthropic.AsyncAnthropic(api_key=os.getenv("ANTHROPIC_API_KEY", ""))

    messages: list[dict[str, Any]] = []
    for msg in input_data.messages or []:
        role = msg.role.value if hasattr(msg.role, "value") else str(msg.role)
        if role not in ("user", "assistant"):
            continue
        raw = getattr(msg, "content", None)
        content = ""
        if isinstance(raw, str):
            content = raw
        elif isinstance(raw, list):
            parts = []
            for part in raw:
                if hasattr(part, "text"):
                    parts.append(part.text)
                elif isinstance(part, dict) and "text" in part:
                    parts.append(part["text"])
            content = "".join(parts)
        if content:
            messages.append({"role": role, "content": content})

    thread_id = input_data.thread_id or "default"
    run_id = input_data.run_id or "run-1"

    yield encoder.encode(
        RunStartedEvent(type=EventType.RUN_STARTED, thread_id=thread_id, run_id=run_id)
    )

    # Maximum tool iterations per run. `generate_a2ui` normally renders in a
    # single turn, but a misbehaving model could keep re-calling the tool and
    # never yield an empty `tool_calls` turn — which would wedge the run and
    # RUN_FINISHED would never fire (done-signal-missing timeout). Cap the loop
    # so the run always terminates. Mirrors the claude-sdk-typescript sibling's
    # MAX_TOOL_ITERATIONS bound.
    MAX_TOOL_ITERATIONS = 10

    for _iter in range(MAX_TOOL_ITERATIONS):
        msg_id = f"msg-{run_id}-{len(messages)}"
        yield encoder.encode(
            TextMessageStartEvent(
                type=EventType.TEXT_MESSAGE_START,
                message_id=msg_id,
                role="assistant",
            )
        )

        response_text = ""
        tool_calls: list[dict[str, Any]] = []
        try:
            async with client.messages.stream(
                model=normalize_claude_model(
                    os.getenv("ANTHROPIC_MODEL", "claude-opus-4-8")
                ),
                max_tokens=2048,
                system=SYSTEM_PROMPT,
                messages=messages,
                tools=[GENERATE_A2UI_TOOL],
            ) as stream:
                current_tool_id: str | None = None
                current_tool_name: str | None = None
                current_tool_args = ""

                async for event in stream:
                    etype = type(event).__name__
                    if etype == "RawContentBlockStartEvent":
                        block = event.content_block  # type: ignore[attr-defined]
                        if block.type == "tool_use":
                            current_tool_id = block.id
                            current_tool_name = block.name
                            current_tool_args = ""
                            yield encoder.encode(
                                ToolCallStartEvent(
                                    type=EventType.TOOL_CALL_START,
                                    tool_call_id=current_tool_id,
                                    tool_call_name=current_tool_name,
                                    parent_message_id=msg_id,
                                )
                            )
                    elif etype == "RawContentBlockDeltaEvent":
                        delta = event.delta  # type: ignore[attr-defined]
                        if delta.type == "text_delta":
                            response_text += delta.text
                            yield encoder.encode(
                                TextMessageContentEvent(
                                    type=EventType.TEXT_MESSAGE_CONTENT,
                                    message_id=msg_id,
                                    delta=delta.text,
                                )
                            )
                        elif delta.type == "input_json_delta":
                            current_tool_args += delta.partial_json
                            yield encoder.encode(
                                ToolCallArgsEvent(
                                    type=EventType.TOOL_CALL_ARGS,
                                    tool_call_id=current_tool_id or "",
                                    delta=delta.partial_json,
                                )
                            )
                    elif etype in (
                        "RawContentBlockStopEvent",
                        "ParsedContentBlockStopEvent",
                    ):
                        if current_tool_id and current_tool_name:
                            yield encoder.encode(
                                ToolCallEndEvent(
                                    type=EventType.TOOL_CALL_END,
                                    tool_call_id=current_tool_id,
                                )
                            )
                            try:
                                parsed = (
                                    json.loads(current_tool_args)
                                    if current_tool_args
                                    else {}
                                )
                            except json.JSONDecodeError:
                                parsed = {}
                            tool_calls.append(
                                {
                                    "id": current_tool_id,
                                    "name": current_tool_name,
                                    "input": parsed,
                                }
                            )
                            current_tool_id = None
                            current_tool_name = None
                            current_tool_args = ""
        except Exception:
            err_text = f"Agent error: {traceback.format_exc()}"
            yield encoder.encode(
                TextMessageContentEvent(
                    type=EventType.TEXT_MESSAGE_CONTENT,
                    message_id=msg_id,
                    delta=err_text,
                )
            )

        yield encoder.encode(
            TextMessageEndEvent(
                type=EventType.TEXT_MESSAGE_END,
                message_id=msg_id,
            )
        )

        if not tool_calls:
            break

        # Build assistant turn with tool_use blocks.
        assistant_content: list[dict[str, Any]] = []
        if response_text:
            assistant_content.append({"type": "text", "text": response_text})
        for tc in tool_calls:
            assistant_content.append(
                {
                    "type": "tool_use",
                    "id": tc["id"],
                    "name": tc["name"],
                    "input": tc["input"],
                }
            )
        messages.append({"role": "assistant", "content": assistant_content})

        # Execute generate_a2ui and emit tool_result.
        tool_results: list[dict[str, Any]] = []
        for tc in tool_calls:
            if tc["name"] == "generate_a2ui":
                ctx = tc["input"].get("context", "")
                try:
                    # Offload to a worker thread: _generate_a2ui runs a
                    # synchronous anthropic.Anthropic() LLM round-trip, which
                    # would otherwise block the uvicorn event loop and wedge the
                    # :8000 /health endpoint under load.
                    result_obj = await asyncio.to_thread(
                        _generate_a2ui, ctx, conversation_messages=messages
                    )
                    result_text = json.dumps(result_obj)
                except Exception as exc:  # noqa: BLE001 - surface as tool result
                    result_text = json.dumps(
                        {
                            "error": "generate_a2ui failed",
                            "detail": exc.__class__.__name__,
                        }
                    )
            else:
                result_text = json.dumps({"error": f"unknown tool {tc['name']}"})
            yield encoder.encode(
                ToolCallResultEvent(
                    type=EventType.TOOL_CALL_RESULT,
                    tool_call_id=tc["id"],
                    message_id=f"{msg_id}-tool-result-{tc['id']}",
                    content=result_text,
                )
            )
            tool_results.append(
                {
                    "type": "tool_result",
                    "tool_use_id": tc["id"],
                    "content": result_text,
                }
            )
        messages.append({"role": "user", "content": tool_results})

    yield encoder.encode(
        RunFinishedEvent(
            type=EventType.RUN_FINISHED, thread_id=thread_id, run_id=run_id
        )
    )

// Dedicated runtime for the Declarative Generative UI (A2UI — Dynamic Schema)
// cell. Splitting into its own endpoint lets us set
// `a2ui.injectA2UITool: false` — the backend Claude Agent SDK agent owns the
// `generate_a2ui` tool itself, so double-binding from the runtime would
// duplicate the tool slot and confuse the LLM.
//
// Reference:
// - showcase/integrations/langgraph-python/src/app/api/copilotkit-declarative-gen-ui/route.ts
// - src/agents/a2ui_dynamic.py (the Claude Agent SDK backend)

import type { NextRequest } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { createClaudeHttpAgent } from "@/app/api/_shared/claude-http-agent";
import { internalRuntimeErrorResponse } from "@/app/api/_shared/route-error";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

const declarativeGenUiAgent = createClaudeHttpAgent(
  `${AGENT_URL}/declarative-gen-ui`,
);

const runtime = new CopilotRuntime({
  // @ts-ignore -- see main route.ts
  agents: { "declarative-gen-ui": declarativeGenUiAgent },
  a2ui: {
    // The backend agent owns `generate_a2ui` explicitly (see
    // src/agents/a2ui_dynamic.py), so the runtime MUST NOT auto-inject its
    // own A2UI tool on top. The A2UI middleware still runs — it serialises
    // the registered client catalog into the agent's `copilotkit.context`
    // so the secondary LLM inside `generate_a2ui` knows which components to
    // emit — and it still detects the `a2ui_operations` container in the
    // tool result and streams rendered surfaces to the frontend.
    injectA2UITool: false,
    // Models follow the tool-usage guide and omit `catalogId`, and the
    // middleware then falls back to the unregistered spec basic catalog
    // ("Catalog not found" render error). Pin the catalog the page registers.
    defaultCatalogId: "declarative-gen-ui-catalog",
  },
});

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-declarative-gen-ui",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    return internalRuntimeErrorResponse(
      "/api/copilotkit-declarative-gen-ui",
      error,
    );
  }
};

"use client";

/**
 * ShadCN-flavoured Badge primitive (inline-cloned, no `cn()`/`cva`).
 * Variant palette mirrors ShadCN's default/secondary/destructive/outline,
 * extended with `success` / `warning` / `info` for status reporting.
 */
import React from "react";

export type BadgeVariant = "success" | "warning" | "error" | "info";

const VARIANT_CLASSES: Record<BadgeVariant, string> = {
  success: "border-transparent bg-emerald-100 text-emerald-800",
  warning: "border-transparent bg-amber-100 text-amber-800",
  error: "border-transparent bg-rose-100 text-rose-800",
  info: "border-[var(--border)] bg-[var(--muted)] text-[var(--foreground)]",
};

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  variant?: BadgeVariant;
}

export function Badge({
  variant = "info",
  className = "",
  children,
  ...props
}: BadgeProps) {
  return (
    <span
      className={`inline-flex items-center rounded-md border px-2 py-0.5 text-xs font-medium tracking-wide ${VARIANT_CLASSES[variant]} ${className}`}
      {...props}
    >
      {children}
    </span>
  );
}

"use client";

/**
 * ShadCN-flavoured Button primitive (inline-cloned, no `cn()`/`cva`).
 */
import React from "react";

export type ButtonVariant =
  | "default"
  | "secondary"
  | "outline"
  | "ghost"
  | "destructive";
export type ButtonSize = "sm" | "default" | "lg";

const VARIANT_CLASSES: Record<ButtonVariant, string> = {
  default:
    "bg-[var(--primary)] text-[var(--primary-foreground)] hover:bg-[var(--primary)]/90",
  secondary:
    "bg-[var(--secondary)] text-[var(--secondary-foreground)] hover:bg-[var(--secondary)]/80",
  outline:
    "border border-[var(--border)] bg-[var(--card)] text-[var(--foreground)] hover:bg-[var(--muted)]",
  ghost: "bg-transparent text-[var(--foreground)] hover:bg-[var(--muted)]",
  destructive:
    "bg-[var(--destructive)] text-[var(--destructive-foreground)] hover:bg-[var(--destructive)]/90",
};

const SIZE_CLASSES: Record<ButtonSize, string> = {
  sm: "h-8 px-3 text-xs rounded-md",
  default: "h-9 px-4 text-sm rounded-md",
  lg: "h-10 px-6 text-sm rounded-md",
};

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
}

export function Button({
  variant = "default",
  size = "default",
  className = "",
  children,
  ...props
}: ButtonProps) {
  return (
    <button
      className={`inline-flex items-center justify-center gap-2 whitespace-nowrap font-medium transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)] disabled:pointer-events-none disabled:opacity-50 ${VARIANT_CLASSES[variant]} ${SIZE_CLASSES[size]} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
}

"use client";

/**
 * ShadCN-flavoured Card primitive (inline-cloned, no `cn()`/`cva`).
 * Uses the showcase's `--card` / `--border` / `--foreground` /
 * `--muted-foreground` CSS variables so the demo respects light/dark.
 */
import React from "react";

export function Card({
  children,
  className = "",
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={`rounded-xl border border-[var(--border)] bg-[var(--card)] text-[var(--card-foreground)] shadow-sm ${className}`}
      {...props}
    >
      {children}
    </div>
  );
