import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { createClaudeHttpAgent } from "@/app/api/_shared/claude-http-agent";
import { internalRuntimeErrorResponse } from "@/app/api/_shared/route-error";
// CVDIAG backend instrumentation (L1-E). No-op pass-through unless
// CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
import { withCvdiagBackend } from "@/cvdiag-backend";

// The Claude agent backend runs as a separate TypeScript process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

function createAgent() {
  return createClaudeHttpAgent(`${AGENT_URL}/`);
}

// Register the same agent under all names used by demo pages.
// The Claude Agent SDK (TypeScript) backend is a pass-through: it forwards
// whatever tools the AG-UI client provides (frontend-registered via
// useFrontendTool / useRenderTool, plus runtime-injected tools from
// openGenerativeUI / a2ui / mcpApps middleware) to Claude. So distinct
// agent behaviour across demos comes from the frontend, not a per-demo
// backend graph — every demo can share the same HttpAgent target.
// IMPORTANT — read the override block BELOW this list before changing
// any entry: ids marked "NOT pass-through" in the override block are
// re-pointed at dedicated backend endpoints after this loop runs (e.g.
// `gen-ui-agent`, `tool-rendering`, `tool-rendering-*-catchall`,
// `tool-rendering-reasoning-chain`, `subagents`, `shared-state-read-write`,
// `headless-complete`). Those ids appear here only so `Object.keys(agents)`
// enumerates them and probes against the shared runtime resolve cleanly;
// the override block is the source of truth for which backend URL they
// actually hit.
const agentNames = [
  // existing demos
  "agentic_chat",
  "agentic-chat",
  "human_in_the_loop",
  "tool-rendering", // overridden -> /tool-rendering (NOT pass-through)
  "hitl",
  "gen-ui-tool-based",
  "gen-ui-agent", // overridden -> /gen-ui-agent (NOT pass-through)
  "shared-state-read",
  "shared-state-write",
  "shared-state-streaming", // overridden -> /shared-state-streaming
  "subagents", // overridden -> /subagents (NOT pass-through)
  "shared-state-read-write", // overridden -> /shared-state-read-write (NOT pass-through)
  "headless-complete", // overridden -> /headless-complete (NOT pass-through)
  // newly ported demos
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "frontend_tools",
  "threadid-frontend-tool-roundtrip",
  "frontend-tools-async",
  "hitl-in-chat",
  "hitl-in-chat-booking",
  "hitl-in-app",
  "readonly-state-agent-context",
  // runtime-injected demos (A2UI, open-gen-ui, mcp-apps live on dedicated
  // runtimes; here we register the ids so intra-app links and probe
  // requests resolve cleanly against the default runtime too)
  "declarative-gen-ui",
  "open-gen-ui",
  "open-gen-ui-advanced",
  "mcp-apps",
  // post-#4271 demos — each lives on a dedicated runtime, but we register
  // their agent ids here so probes against the shared runtime resolve
  // without 404s.
  "byoc_json_render",
  "declarative_json_render",
  "declarative-hashbrown-demo",
  "beautiful-chat",
  "multimodal-demo",
  "voice-demo",
  "agent-config-demo",
  "auth-demo",
  // Interrupt-adapted scheduling demos — both use useFrontendTool with an
  // async handler to simulate LangGraph interrupt(); the backend is the same
  // pass-through agent.
  "gen-ui-interrupt",
  "interrupt-headless",
  // showcase-fill-186 ports — NOT pass-through: backend owns the tools.
  // See override block below; entries here only seed Object.keys(agents)
  // for probe enumeration.
  "tool-rendering-default-catchall", // overridden -> /tool-rendering
  "tool-rendering-custom-catchall", // overridden -> /tool-rendering
  "tool-rendering-reasoning-chain", // overridden -> /tool-rendering-reasoning-chain
  // Reasoning variants — overridden -> /reasoning (NOT pass-through).
  "reasoning-default",
  "reasoning-custom",
];

const agents: Record<string, AbstractAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent();
}
agents["default"] = createAgent();

// Gen UI (Agent-based) is NOT a pass-through demo: the backend owns the
// `set_steps` tool and streams `state.steps` via STATE_SNAPSHOT (see
// `src/agent_server.ts` `/gen-ui-agent`). Point it at the dedicated
// endpoint — on the pass-through root the model's set_steps calls were
// forwarded to the frontend (which registers no such tool) and the
// multi-leg tool loop never completed.
agents["gen-ui-agent"] = createClaudeHttpAgent(`${AGENT_URL}/gen-ui-agent`);

// Tool Rendering family is likewise NOT pass-through: the pages register
// render-only hooks (no handlers), so frontend execution never returns a
// result and every card stalls in its loading state. The backend owns
// get_weather / search_flights / get_stock_price / roll_d20 at
// `/tool-rendering` (see `src/agent_server.ts`), and the reasoning-chain
// variant adds extended thinking + roll_dice at
// `/tool-rendering-reasoning-chain`.
agents["tool-rendering"] = createClaudeHttpAgent(`${AGENT_URL}/tool-rendering`);
agents["tool-rendering-default-catchall"] = createClaudeHttpAgent(
  `${AGENT_URL}/tool-rendering`,
);
agents["tool-rendering-custom-catchall"] = createClaudeHttpAgent(
  `${AGENT_URL}/tool-rendering`,
);
agents["tool-rendering-reasoning-chain"] = createClaudeHttpAgent(
  `${AGENT_URL}/tool-rendering-reasoning-chain`,
);

// Sub-Agents is NOT pass-through: the backend owns the
// research / writing / critique sub-agent tools and emits delegation
// progress via STATE_SNAPSHOT (see `src/agent_server.ts` `/subagents`).
// The demo page targets `/api/copilotkit-subagents` directly, but probes
// landing on the shared runtime must hit the dedicated backend endpoint
// too — otherwise the pass-through root forwards the supervisor's
// sub-agent tool calls to the frontend (which registers nothing) and the
// multi-leg loop stalls. Mirrors the gen-ui-agent treatment above.
agents["subagents"] = createClaudeHttpAgent(`${AGENT_URL}/subagents`);

// Shared State (Read + Write) is NOT pass-through: the backend reads
// `input.state.preferences` into the system prompt every turn and owns
// the `set_notes` tool that mutates `state.notes` (see
// `src/agent_server.ts` `/shared-state-read-write`). The demo page
// targets `/api/copilotkit-shared-state-read-write` directly; this
// override keeps shared-runtime probes resolving against the same
// backend endpoint so a probe never silently exercises the pass-through.
agents["shared-state-read-write"] = createClaudeHttpAgent(
  `${AGENT_URL}/shared-state-read-write`,
);

agents["shared-state-streaming"] = createClaudeHttpAgent(
  `${AGENT_URL}/shared-state-streaming`,
);

// Headless Chat (Complete) is NOT pass-through: the backend owns
// `get_weather` and `get_stock_price` (see `src/agent_server.ts`
// `/headless-complete`). The demo page targets
// `/api/copilotkit-headless-complete` directly, but registering the id
// here with the same backend URL keeps shared-runtime probes 200-resolving
// against the real handler (matching the file's probe-resolution
// convention for dedicated-runtime demos).
agents["headless-complete"] = createClaudeHttpAgent(
  `${AGENT_URL}/headless-complete`,
);

agents["byoc_json_render"] = createClaudeHttpAgent(
  `${AGENT_URL}/byoc-json-render`,
);

agents["mcp-apps"] = createClaudeHttpAgent(`${AGENT_URL}/mcp-apps`);

// Reasoning variants share the same backend endpoint; the frontend decides
// whether to render the default or custom reasoning slot.
agents["reasoning-default"] = createClaudeHttpAgent(`${AGENT_URL}/reasoning`);
agents["reasoning-custom"] = createClaudeHttpAgent(`${AGENT_URL}/reasoning`);

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

const copilotkitPost = async (req: NextRequest): Promise<Response> => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- Published CopilotRuntime agents type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in source, pending release
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    const err = error as Error;
    console.error(`[copilotkit/route] ERROR: ${err.message}`);
    console.error(`[copilotkit/route] Stack: ${err.stack}`);
    return internalRuntimeErrorResponse("/api/copilotkit", error);
  }
};

// Wrap with CVDIAG backend instrumentation (L1-E). The Claude Agent SDK (TS)
// backend is a pass-through proxy with no per-request named agent, so a fixed
// `agent_name` is stamped. No-op pass-through unless CVDIAG_BACKEND_EMITTER is
// set truthy (default OFF).
export const POST = withCvdiagBackend(copilotkitPost, {
  slug: "claude-sdk-typescript",
  agentName: "claude-agent",
  provider: "anthropic",
});

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

/* HALCYON — a warm-paper editorial theme for CopilotChat.
 *
 * The point of this demo is to show how far a single stylesheet can take
 * CopilotChat away from the default look without touching components or
 * slots. Every selector is namespaced under `.chat-css-demo-scope` so this
 * theme cannot leak into the rest of the showcase.
 *
 * Two layers do the work:
 *   1. v2 token overrides on `[data-copilotkit]` recolor every Tailwind
 *      utility (cpk:bg-muted, cpk:text-foreground, cpk:border, …) the
 *      runtime relies on — see @copilotkit/react-core/v2/styles.css.
 *   2. Targeted class rules on `.copilotKitChat`, `.copilotKitMessage*`,
 *      and `.copilotKitInput` add the editorial details: parchment grain,
 *      corner brackets, serif voice, mono dispatch, ember accents.
 *
 * Class-name reference:
 *   https://docs.copilotkit.ai/custom-look-and-feel/customize-built-in-ui-components
 */

@import url("https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Instrument+Serif:ital@0;1&family=Inter+Tight:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap");

/* HALCYON palette — a private library at golden hour. The whole theme is
 * one warm parchment hue, one warm ink, and a deep copper ember used
 * sparingly so it actually reads as a signal. */
.chat-css-demo-scope {
  --halcyon-paper: #f4efe6;
  --halcyon-paper-soft: #ece6d9;
  --halcyon-paper-elevated: #fbf8f2;
  --halcyon-card: #ffffff;
  --halcyon-rule: #d6cfbe;
  --halcyon-rule-strong: #aea48a;
  --halcyon-ink: #1a1714;
  --halcyon-ink-soft: #3d362e;
  --halcyon-ink-mute: #7a7468;
  --halcyon-ember: #c44a1f;
  --halcyon-ember-bright: #e45f2b;
  --halcyon-ember-soft: #f3d7c5;
  --halcyon-champagne: #98794a;

  --halcyon-display:
    "Instrument Serif", ui-serif, "Iowan Old Style", Georgia, serif;
  --halcyon-serif:
    "Fraunces", "Source Serif Pro", ui-serif, Georgia, "Times New Roman", serif;
  --halcyon-sans:
    "Inter Tight", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  --halcyon-mono:
    "JetBrains Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --halcyon-shadow-soft:
    0 1px 0 rgba(26, 23, 20, 0.04), 0 12px 32px -18px rgba(26, 23, 20, 0.18);
  --halcyon-shadow-ember:
    0 1px 0 rgba(196, 74, 31, 0.18), 0 14px 36px -16px rgba(196, 74, 31, 0.42);
}

/* CopilotKit v2 reads these on the [data-copilotkit] root inside the chat.
 * Re-pointing them under our scope retints every Tailwind utility the
 * runtime renders (user message bubble, prose, borders, focus rings, …)
 * without us having to touch any individual class. */
.chat-css-demo-scope [data-copilotkit] {
  --background: var(--halcyon-paper);
  --foreground: var(--halcyon-ink);
  --card: var(--halcyon-card);
  --card-foreground: var(--halcyon-ink);
  --popover: var(--halcyon-paper-elevated);
  --popover-foreground: var(--halcyon-ink);
  --primary: var(--halcyon-ember);
  --primary-foreground: var(--halcyon-paper-elevated);
  --secondary: var(--halcyon-paper-soft);
  --secondary-foreground: var(--halcyon-ink);
  --muted: var(--halcyon-paper-soft);
  --muted-foreground: var(--halcyon-ink-mute);
  --accent: var(--halcyon-ember-soft);
  --accent-foreground: var(--halcyon-ember);
  --destructive: #b3361b;
  --destructive-foreground: var(--halcyon-paper-elevated);
  --border: var(--halcyon-rule);
  --input: var(--halcyon-rule);
  --ring: var(--halcyon-ember);
  --radius: 0px;
}

/* The chat surface — warm parchment with a single ambient ember glow,
 * a barely-perceptible paper grain via inline SVG noise, and architectural
 * corner brackets. Sharp 90° corners are deliberate; the default look is
 * rounded, so squaring everything off is the fastest visual signal that
 * "this is a different brand". */
.chat-css-demo-scope .copilotKitChat {
  font-family: var(--halcyon-sans);
  color: var(--halcyon-ink);
  background-color: var(--halcyon-paper);
  background-image:
    radial-gradient(
      900px 460px at 0% -10%,
      rgba(228, 95, 43, 0.14),
      transparent 62%
    ),
    radial-gradient(
      720px 380px at 100% 110%,
      rgba(152, 121, 74, 0.08),
      transparent 65%
    ),
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160' viewBox='0 0 160 160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.10 0 0 0 0 0.09 0 0 0 0 0.07 0 0 0 0.045 0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
  border: 1px solid var(--halcyon-rule);
  border-radius: 0;
  box-shadow: var(--halcyon-shadow-soft);
  position: relative;
  overflow: hidden;
}

/* The masthead label — a small mono bar pinned to the top of the surface,
 * playing against the editorial serif voice. Lives on ::before so it
 * tracks the chat root and shows in every state (welcome, mid-thread,
 * empty after clear). */
.chat-css-demo-scope .copilotKitChat::before {
  content: "CopilotChat  ·  Customized with CSS";
  position: absolute;
  top: 18px;
  left: 0;
  right: 0;
  text-align: center;
  font-family: var(--halcyon-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--halcyon-ink-mute);
  white-space: nowrap;
  pointer-events: none;
  z-index: 3;
}


/* The welcome screen — the page-one impression. The default heading is
 * sans-serif and tidy; we replace it with a large italic display serif
 * that wraps the question like a magazine cover line. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] {
  padding-top: 4rem;
}

.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1 {
  font-family: var(--halcyon-display);
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 400;
  font-style: italic;
  color: var(--halcyon-ink);
  letter-spacing: -0.02em;
  line-height: 1.05;
  text-align: center;
  margin: 0 auto 0.6rem;
  max-width: 22ch;
  position: relative;
}

/* A small mono eyebrow above the heading. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::before {
  content: "CopilotKit";
  display: block;
  font-family: var(--halcyon-mono);
  font-size: 11px;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: var(--halcyon-ember);
  margin-bottom: 1.2rem;
}

/* A short rule under the heading as a visual settle point. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::after {
  content: "";
  display: block;
  width: 36px;
  height: 1px;
  background: var(--halcyon-rule-strong);
  margin: 1.4rem auto 0;
}

.chat-css-demo-scope .copilotKitMessages {
  font-family: var(--halcyon-sans);
  background: transparent;
  color: var(--halcyon-ink);
  padding: 5rem 0 2rem;
  line-height: 1.6;
}

/* User message — a "transmission" in JetBrains Mono on a paper card. The
 * outer wrapper is the right-aligning flex column; we leave it transparent
 * and style the inner bubble (which uses cpk:bg-muted, hence we also
 * target the substring class as a stable hook). */
.chat-css-demo-scope .copilotKitMessage.copilotKitUserMessage {
  background: transparent;
  padding: 0;
  border: none;
  box-shadow: none;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitUserMessage
  > [class*="bg-muted"] {
  font-family: var(--halcyon-mono);
  font-size: 0.875rem;
  font-weight: 400;
  color: var(--halcyon-ink);
  background: var(--halcyon-paper-elevated);
  border: 1px solid var(--halcyon-rule);
  border-left: 2px solid var(--halcyon-ember);
  border-radius: 0;
  padding: 12px 16px 12px 18px;
  letter-spacing: -0.005em;
  line-height: 1.55;
  box-shadow: 0 1px 0 rgba(26, 23, 20, 0.03);
  position: relative;
}

/* A mono "→" marker before the user's text to read like a CLI prompt. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitUserMessage
  > [class*="bg-muted"]::before {
  content: "→";
  display: inline-block;
  margin-right: 10px;
  color: var(--halcyon-ember);
  font-weight: 500;
}

/* Assistant message — editorial Fraunces serif, no bubble, just generous
 * paragraphs offset by a thin ember rule on the left. Reads like the
 * voice of a publication, not a chatbot. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage {
  background: transparent;
  color: var(--halcyon-ink);
  font-family: var(--halcyon-serif);
  font-size: 1.0625rem;
  font-weight: 400;
  padding: 4px 0 4px 22px;
  border: none;
  border-radius: 0;
  margin-right: auto;
  margin-bottom: 1.25rem;
  max-width: 78ch;
  position: relative;
}

/* The editorial left rule. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage::before {
  content: "";
  position: absolute;
  top: 0.45em;
  bottom: 0.45em;
  left: 0;
  width: 1px;
  background: var(--halcyon-ember);
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose,
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose p {
  font-family: var(--halcyon-serif);
  font-size: inherit;
  color: inherit;
  line-height: 1.7;
  font-feature-settings: "ss01", "ss02", "ss03", "kern";
  margin: 0 0 0.85em;
}

/* Headings inside assistant content swap to the display serif so a long
 * answer reads like a structured article. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  :is(h1, h2, h3, h4) {
  font-family: var(--halcyon-display);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -0.015em;
  color: var(--halcyon-ink);
  margin: 1em 0 0.4em;
  line-height: 1.15;
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h1 {
  font-size: 2rem;
}
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h2 {
  font-size: 1.55rem;
}
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h3 {
