/* Lists — looser, with serif numerals. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  :is(ul, ol) {
  margin: 0.5em 0 1em;
  padding-left: 1.4em;
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose li {
  margin: 0.25em 0;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  ol
  > li::marker {
  color: var(--halcyon-ember);
  font-feature-settings: "tnum";
  font-weight: 500;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  ul
  > li::marker {
  color: var(--halcyon-ember);
}

/* Blockquote — pull-quote treatment in italic display serif. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  blockquote {
  border-left: 0;
  margin: 1.2em 0;
  padding: 0 0 0 1em;
  font-family: var(--halcyon-display);
  font-style: italic;
  font-size: 1.25em;
  color: var(--halcyon-ink-soft);
  position: relative;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  blockquote::before {
  content: "“";
  position: absolute;
  left: -0.05em;
  top: -0.4em;
  font-size: 2.4em;
  color: var(--halcyon-ember);
  line-height: 1;
