  color: #e8e2d5;
  border: 1px solid var(--halcyon-ink);
  border-radius: 0;
  padding: 14px 16px;
  margin: 1em 0;
  font-family: var(--halcyon-mono);
  font-size: 0.86em;
  line-height: 1.55;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
