const { agent } = useAgent({ agentId: "headless-simple" });
const { copilotkit } = useCopilotKit();
const [input, setInput] = useState("");

const send = (text: string) => {
  const trimmed = text.trim();
  if (!trimmed || agent.isRunning) return;
  agent.addMessage({
    id: createMessageId(),
    role: "user",
    content: trimmed,
  });
  setInput("");
  void copilotkit.runAgent({ agent }).catch((err) => {
    // The Headless Simple demo is the canonical "two hooks, your
    // design system" example users copy-paste as a starting point.
    // Silently swallowing errors here would model broken practice;
    // log so a network failure / runtime error / transport disconnect
    // surfaces in the console for the developer.
    console.error(
      "[claude-sdk-typescript:headless-simple] runAgent failed",
      err,
    );
  });
};

claude-sdk-typescript::frontend-tools.readme:
# Frontend Tools (In-App Actions)

## What This Demo Shows

Frontend tools (a.k.a. "in-app actions") let the agent call functions that live in your React app. The agent reasons about when to invoke them based on natural conversation.

## How to Interact

Try asking:

- "Change the background to a blue-to-purple gradient"
- "Make the background a sunset theme"
- "Set the background to black"

## Technical Details

A frontend tool is registered with `useFrontendTool`:

```tsx
useFrontendTool({
  name: "change_background",
  description: "...",
  parameters: z.object({ background: z.string() }),
  handler: async ({ background }) => {
    setBackground(background);
    return { status: "success" };
  },
});
```

CopilotKit automatically advertises the tool to the agent. The agent decides when to call it based on the conversation, and the handler runs client-side.

