    DECLARATIVE_GEN_UI_SECONDARY_PROMPT,
    A2UI_DEFAULT_GENERATION_GUIDELINES,
    A2UI_DEFAULT_DESIGN_GUIDELINES,
    "Registered catalog/context:",
    agentContext || DECLARATIVE_GEN_UI_CATALOG_GUIDE,
