"use client";

import React, { useEffect, useRef } from "react";
import {
  CopilotKit,
  useAgent,
  UseAgentUpdate,
} from "@copilotkit/react-core/v2";

import type { Preferences } from "./preferences-card";
import { DemoLayout } from "./demo-layout";
import { useSharedStateReadWriteSuggestions } from "./suggestions";

const INITIAL_PREFERENCES: Preferences = {
  name: "",
  tone: "casual",
  language: "English",
  interests: [],
};

// Shape of the bidirectional shared state.
// - `preferences` is WRITTEN by the UI via agent.setState().
// - `notes` is WRITTEN by the agent via its `set_notes` tool and READ
//   by the UI via useAgent().
interface RWAgentState {
  preferences: Preferences;
  notes: string[];
}

export default function SharedStateReadWriteDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="shared-state-read-write">
      <DemoContent />
    </CopilotKit>
  );
}

function DemoContent() {
  // Subscribe the component to agent state changes. Any time the agent
  // mutates its state (e.g. via its `set_notes` tool) this hook fires,
  // we re-render, and the sidebar panels reflect the new values.
  const { agent } = useAgent({
    agentId: "shared-state-read-write",
    updates: [UseAgentUpdate.OnStateChanged],
  });

  useSharedStateReadWriteSuggestions();

  const agentState = agent.state as RWAgentState | undefined;
  const preferences = agentState?.preferences ?? INITIAL_PREFERENCES;
  const notes = agentState?.notes ?? [];
  const latestNotesRef = useRef(notes);

  useEffect(() => {
    latestNotesRef.current = notes;
  }, [notes]);

  // Seed initial preferences + empty notes into agent state once, so the
  // agent has something to read on the very first turn.
  useEffect(() => {
    if (!agentState?.preferences) {
      agent.setState({
        preferences: INITIAL_PREFERENCES,
        notes: [],
      } as RWAgentState);
    }
  }, [agent, agentState?.preferences]);

  // WRITE: every edit in the sidebar goes straight into agent state.
  // On the agent's next turn, `PreferencesInjectorMiddleware` reads this
  // back out of state and adds it to the system prompt — so the UI's
  // writes visibly steer the model.
  const handlePreferencesChange = (next: Preferences) => {
    agent.setState({
      preferences: next,
      notes: latestNotesRef.current, // preserve what the agent has written
    } as RWAgentState);
  };

  // WRITE: let the user clear the agent-authored notes from the UI.
  const handleClearNotes = () => {
    agent.setState({ preferences, notes: [] } as RWAgentState);
  };

  return (
    <DemoLayout
      preferences={preferences}
      notes={notes}
      onPreferencesChange={handlePreferencesChange}
      onClearNotes={handleClearNotes}
    />
  );
}

/**
 * Agent Server for Claude Agent SDK (TypeScript)
 *
 * Express server that hosts a Claude-powered agent backend.
 * The Next.js CopilotKit runtime proxies requests here via AG-UI protocol.
 */

// Cold-start instrumentation: emitted before any side-effect imports so
// Railway logs reveal exactly which phase (module load, Anthropic SDK
// init, express.listen) consumes the watchdog budget. Paired with the
// `[entrypoint] pre-node ...` print in entrypoint.sh so timestamps chain.
// Disambiguates the observed failure class where process claims to be
// listening but /health probes never succeed.
console.log(`[agent_server] module loaded ${new Date().toISOString()}`);

import type { Request, Response } from "express";
import express from "express";
import Anthropic from "@anthropic-ai/sdk";
import { EventEncoder } from "@ag-ui/encoder";
import type { RunAgentInput, Message } from "@ag-ui/core";
import { EventType } from "@ag-ui/core";
import {
  A2UI_DEFAULT_DESIGN_GUIDELINES,
  A2UI_DEFAULT_GENERATION_GUIDELINES,
} from "@copilotkit/shared";
import * as dotenv from "dotenv";
import * as PartialJSON from "partial-json";
import { randomUUID } from "crypto";
import { BYOC_JSON_RENDER_SYSTEM_PROMPT } from "./agent/byoc-json-render-prompt";
import { BYOC_HASHBROWN_SYSTEM_PROMPT } from "./agent/byoc-hashbrown-prompt";
import {
  AGENT_CONFIG_DEFAULT_SYSTEM_PROMPT,
  buildAgentConfigSystemPrompt,
} from "./agent/agent-config-prompt";
import {
  SET_NOTES_TOOL_SCHEMA,
  buildSharedStateReadWriteSystemPrompt,
  coercePreferences,
} from "./agent/shared-state-read-write-prompt";
import {
  SUBAGENT_SYSTEM_BY_NAME,
  SUBAGENT_TOOL_SCHEMAS,
  SUPERVISOR_SYSTEM_PROMPT,
} from "./agent/subagents-prompts";
import type { SubAgentName } from "./agent/subagents-prompts";
import {
  A2UI_FIXED_SYSTEM_PROMPT,
  DISPLAY_FLIGHT_TOOL_SCHEMA,
  buildDisplayFlightOperations,
} from "./agent/a2ui-fixed-prompt";
import {
  A2UI_DYNAMIC_SYSTEM_PROMPT,
  GENERATE_A2UI_TOOL_SCHEMA,
} from "./agent/a2ui-dynamic-prompt";
import {
  HEADLESS_COMPLETE_SYSTEM_PROMPT,
  HEADLESS_GET_REVENUE_CHART_TOOL_SCHEMA,
  HEADLESS_GET_STOCK_PRICE_TOOL_SCHEMA,
  HEADLESS_GET_WEATHER_TOOL_SCHEMA,
  getRevenueChartImpl,
  getStockPriceImpl,
  getWeatherImpl,
} from "./agent/headless-complete-prompt";
import {
  GEN_UI_AGENT_SYSTEM_PROMPT,
  SET_STEPS_TOOL_SCHEMA,
} from "./agent/gen-ui-agent-prompt";
import {
  REASONING_CHAIN_SYSTEM_PROMPT,
  ROLL_D20_TOOL_SCHEMA,
  ROLL_DICE_TOOL_SCHEMA,
  SEARCH_FLIGHTS_TOOL_SCHEMA,
  TOOL_RENDERING_SYSTEM_PROMPT,
  rollD20Impl,
  rollDiceImpl,
  searchFlightsImpl as searchFlightsByRouteImpl,
} from "./agent/tool-rendering-prompts";
import {
  runWithClaudeAgentSdk,
