/**
 * System prompts for the Sub-Agents demo.
 *
 * Mirrors the language used by the LangGraph Python and Google ADK
 * references (`langgraph-python/src/agents/subagents.py`,
 * `google-adk/src/agents/subagents_agent.py`) so the showcase produces
 * comparable output across runtimes.
 *
 * Each sub-agent is a *single Anthropic Messages API call* with a
 * dedicated system prompt — no tools, no recursion. The supervisor sees
 * each delegation as a tool call whose result is the sub-agent's reply.
 */

// Each sub-agent is defined by its own system prompt. The supervisor
// invokes them as tools; on each call the agent server issues a single
// Anthropic Messages API request with the matching prompt below. They
// don't share memory or tools with the supervisor — the supervisor only
// ever sees what the sub-agent returns as a tool result.
export const RESEARCH_SUBAGENT_SYSTEM =
  "You are a research sub-agent. Given a topic, produce a concise " +
  "bulleted list of 3-5 key facts. No preamble, no closing.";

export const WRITING_SUBAGENT_SYSTEM =
  "You are a writing sub-agent. Given a brief and optional source facts, " +
  "produce a polished 1-paragraph draft. Be clear and concrete. No preamble.";

export const CRITIQUE_SUBAGENT_SYSTEM =
  "You are an editorial critique sub-agent. Given a draft, give 2-3 crisp, " +
  "actionable critiques. No preamble.";

export const SUPERVISOR_SYSTEM_PROMPT =
  "You are a supervisor agent that coordinates three specialized " +
  "sub-agents to produce high-quality deliverables.\n\n" +
  "Available sub-agents (call them as tools):\n" +
  "  - research_agent: gathers facts on a topic.\n" +
  "  - writing_agent: turns facts + a brief into a polished draft.\n" +
  "  - critique_agent: reviews a draft and suggests improvements.\n\n" +
  "For most non-trivial user requests, delegate in sequence: research -> " +
  "write -> critique. Pass the relevant facts/draft through the `task` " +
  "argument of each tool. Each tool returns a JSON object shaped " +
  "`{status: 'completed' | 'failed', result?: string, error?: string}`. " +
  "If a sub-agent fails, surface the failure briefly to the user (don't " +
  "fabricate a result) and decide whether to retry. Keep your own " +
  "messages short — explain the plan once, delegate, then return a " +
  "concise summary once done. The UI shows the user a live log of " +
  "every sub-agent delegation, including the in-flight 'running' state.";

export type SubAgentName =
  | "research_agent"
  | "writing_agent"
  | "critique_agent";

export const SUBAGENT_SYSTEM_BY_NAME: Record<SubAgentName, string> = {
  research_agent: RESEARCH_SUBAGENT_SYSTEM,
  writing_agent: WRITING_SUBAGENT_SYSTEM,
  critique_agent: CRITIQUE_SUBAGENT_SYSTEM,
};

// The supervisor delegates by calling tools. Each entry below is an
// Anthropic tool schema that the supervisor LLM "calls" to delegate
// work; the run loop in `agent_server.ts` runs the matching sub-agent
// synchronously, records the delegation into shared agent state, and
// returns the sub-agent's output as a tool_result the supervisor can
// read on its next step.
export const SUBAGENT_TOOL_SCHEMAS = [
  {
    name: "research_agent" as const,
    description:
      "Delegate a research task to the research sub-agent. Use for: " +
      "gathering facts, background, definitions, statistics. Returns a " +
      "JSON object {status, result?, error?}.",
    input_schema: {
      type: "object" as const,
      properties: {
        task: {
          type: "string",
          description: "The research task — a topic or question.",
        },
      },
      required: ["task"],
    },
  },
  {
    name: "writing_agent" as const,
    description:
      "Delegate a drafting task to the writing sub-agent. Use for: " +
      "producing a polished paragraph, draft, or summary. Pass relevant " +
      "facts from prior research inside `task`. Same return shape.",
    input_schema: {
      type: "object" as const,
      properties: {
        task: {
          type: "string",
          description:
            "The drafting brief — include any facts the writer should use.",
        },
      },
      required: ["task"],
    },
  },
  {
    name: "critique_agent" as const,
    description:
      "Delegate a critique task to the critique sub-agent. Use for: " +
      "reviewing a draft and suggesting concrete improvements. Same " +
      "return shape.",
    input_schema: {
      type: "object" as const,
      properties: {
        task: {
          type: "string",
          description: "The draft to critique.",
        },
      },
      required: ["task"],
    },
  },
];

/**
 * Dedicated runtime for the Sub-Agents demo.
 *
 * Proxies to the Claude agent_server's `/subagents` endpoint, where a
 * supervisor LLM delegates to three specialized sub-agents
 * (research / writing / critique) — each implemented as a single
 * secondary Anthropic Messages API call with a sub-agent-specific
 * system prompt. Every delegation appends an entry to
 * `state.delegations` (running -> completed/failed) which the
 * agent_server emits via AG-UI `STATE_SNAPSHOT` so the UI's
 * delegation log updates live as the supervisor fans work out.
 */

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import { randomUUID } from "node:crypto";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { createClaudeHttpAgent } from "@/app/api/_shared/claude-http-agent";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

const subagentsAgent = createClaudeHttpAgent(`${AGENT_URL}/subagents`);

const agents: Record<string, AbstractAgent> = {
  subagents: subagentsAgent,
  default: subagentsAgent,
};

const runtime = new CopilotRuntime({
  // @ts-ignore -- see main route.ts for type-hole notes
  agents,
});

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-subagents",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    // Log full stack server-side, return only an opaque error id to the
    // client. Returning `error.message` / `error.stack` over the wire leaks
    // server internals (file paths, env-derived values, third-party stack
    // frames) to anyone who can hit this endpoint. Reference shape:
    // `mastra/src/app/api/copilotkit/route.ts` `logRouteError`.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        route: "/api/copilotkit-subagents",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

import { Delegation, SubAgentName } from "./delegation-log";

// Inspect the live message stream to find the most recent supervisor
// tool call to a sub-agent that has not yet produced a ToolMessage
// reply. Falls back to `null` when there is no in-flight delegation.
//
// This is intentionally defensive — the v2 message shape can vary
// across runtime versions, so we structurally probe instead of
// relying on a specific TS type.
type RawToolCall = {
  id?: string | null;
  function?: { name?: string | null; arguments?: string | null } | null;
};

type RawMessage = {
  role?: string;
  toolCalls?: RawToolCall[] | null;
  toolCallId?: string | null;
  content?: unknown;
};

export function inferActiveSubAgent(
  delegations: Delegation[],
  messages: unknown,
): { subAgent: SubAgentName; task: string } | null {
  const msgs: RawMessage[] = Array.isArray(messages)
    ? (messages as RawMessage[])
    : [];

  // Collect every tool_call_id that already has a matching tool reply.
  const repliedIds = new Set<string>();
  for (const m of msgs) {
    if (m.role === "tool" && typeof m.toolCallId === "string") {
      repliedIds.add(m.toolCallId);
    }
  }

  const SUB_AGENT_NAMES: ReadonlySet<SubAgentName> = new Set<SubAgentName>([
    "research_agent",
    "writing_agent",
    "critique_agent",
  ]);

  // Walk newest → oldest and return the most recent unanswered call.
  for (let i = msgs.length - 1; i >= 0; i--) {
    const m = msgs[i];
    if (!m || m.role !== "assistant" || !Array.isArray(m.toolCalls)) continue;
    for (let j = m.toolCalls.length - 1; j >= 0; j--) {
      const call = m.toolCalls[j];
      const name = call?.function?.name;
      if (typeof name !== "string") continue;
      if (!SUB_AGENT_NAMES.has(name as SubAgentName)) continue;
      if (typeof call?.id === "string" && repliedIds.has(call.id)) continue;
      const task = extractTask(call?.function?.arguments);
      return { subAgent: name as SubAgentName, task };
    }
  }

  // Fall back: if delegations is non-empty but the supervisor is still
  // running, surface the most recent delegation as a soft signal.
  if (delegations.length > 0) {
    const last = delegations[delegations.length - 1];
    if (last && last.status !== "completed") {
      return { subAgent: last.sub_agent, task: last.task };
    }
  }
  return null;
}

function extractTask(rawArgs: string | null | undefined): string {
  if (!rawArgs) return "(preparing task…)";
  // Streaming tool args may be a partial JSON string. Try a strict
  // parse first, then fall back to a regex sniff for `"task": "..."`.
  try {
    const parsed = JSON.parse(rawArgs);
    if (parsed && typeof parsed === "object" && "task" in parsed) {
      const t = (parsed as { task?: unknown }).task;
      if (typeof t === "string" && t.trim().length > 0) return t;
    }
  } catch {
    const match = rawArgs.match(/"task"\s*:\s*"((?:[^"\\]|\\.)*)/);
    if (match && match[1].length > 0) {
      try {
        return JSON.parse(`"${match[1]}"`);
      } catch {
        return match[1];
      }
    }
  }
  return "(preparing task…)";
}

