      return JSON.stringify(
        buildA2uiOperationsFromRenderArgs(
          (block.input ?? {}) as Record<string, unknown>,
        ),
      );
    }
  }

  return JSON.stringify({ error: "secondary Claude call did not render A2UI" });
}

