"use client";

// Auth demo — framework-native request authentication via the V2 runtime's
// `onRequest` hook. The runtime route (/api/copilotkit-auth) rejects any
// request whose `Authorization: Bearer <demo-token>` header is missing or
// wrong.
//
// UX shape: the demo defaults to UNAUTHENTICATED on first paint so visitors
// land on a clear sign-in card. We don't render `<CopilotKit>` until the user
// has signed in at least once — that sidesteps the transport 401 that would
// otherwise crash `<CopilotChat>` during its initial `/info` handshake.
// After the user signs in once, `<CopilotKit>` stays mounted across the
// sign-out → sign-in cycle so the post-sign-out state can actually
// demonstrate the runtime rejecting unauthenticated requests in the chat
// surface (the whole point of the demo).
//
// Error surfacing: the post-sign-out 401 is captured via the AGENT-SCOPED
// `<CopilotChat onError>` channel, NOT the provider-level `<CopilotKit
// onError>` alone. Agent-run errors (`agent_run_failed`) are reliably
// delivered to the chat-scoped subscription, whereas the provider-level
// handler does not fire for them in this flow — so a demo that relies only
// on `<CopilotKit onError>` never renders the rejection banner. We register
// the same handler on BOTH channels: `<CopilotKit onError>` covers any
// provider-level errors (e.g. the initial `/info` handshake) and
// `<CopilotChat onError>` covers agent-run rejections, which is what the
// sign-out path produces.

import { useCallback, useEffect, useMemo, useState } from "react";
import type { SyntheticEvent } from "react";
import { CopilotKit, CopilotChat } from "@copilotkit/react-core/v2";
import type { CopilotKitCoreErrorCode } from "@copilotkit/react-core/v2";
import { AuthBanner } from "./auth-banner";
import { SignInCard } from "./sign-in-card";
import { useDemoAuth } from "./use-demo-auth";
import { DEMO_TOKEN } from "./demo-token";

interface AuthDemoErrorState {
  message: string;
  code: string;
}

interface AuthErrorEvent {
  error?: {
    message?: string;
    code?: string;
    extensions?: { code?: string };
  } | null;
  code?: CopilotKitCoreErrorCode | string;
  context?: { response?: { status?: number | string } };
}

type AuthErrorInput = AuthErrorEvent | SyntheticEvent<HTMLDivElement>;

function isAuthErrorEvent(event: AuthErrorInput): event is AuthErrorEvent {
  return "error" in event || "code" in event || "context" in event;
}

export default function AuthDemoPage() {
  const {
    isAuthenticated,
    authorizationHeader,
    hasEverSignedIn,
    signIn,
    signOut,
  } = useDemoAuth();

  const headers = useMemo(
    (): Record<string, string> =>
      authorizationHeader ? { Authorization: authorizationHeader } : {},
    [authorizationHeader],
  );

  const [authError, setAuthError] = useState<AuthDemoErrorState | null>(null);

  // Shared error handler wired to BOTH the provider-level and chat-level
  // `onError` channels (see the file header for why both are needed).
  const handleAuthError = useCallback((event: AuthErrorInput) => {
    if (!isAuthErrorEvent(event)) return;
    const code =
      event.code ??
      event.error?.code ??
      event.error?.extensions?.code ??
      event.context?.response?.status?.toString() ??
      "UNKNOWN";
    setAuthError({
      message:
        (event.error?.message && event.error.message.trim()) ||
        (code ? `Request rejected (${code})` : "The request was rejected."),
      code,
    });
  }, []);

  // Clear stale errors as soon as the user re-authenticates. This is the
  // ONLY thing that gates the amber error surface on auth state — the render
  // condition below keys off `authError` alone. Coupling the render to a
  // second `!isAuthenticated` slice (the obvious-but-wrong guard) created a
  // post-sign-out race: the rejection's `onError` fires and calls
  // `setAuthError`, but if that commit landed in a render where the auth
  // state hadn't yet settled to false, `authError && !isAuthenticated`
  // evaluated false and the banner never appeared. Driving the surface off
  // `authError` and clearing it here on re-auth removes the cross-slice
  // ordering dependency: a rejection always renders, and signing back in
  // always wipes it.
  useEffect(() => {
    if (isAuthenticated) setAuthError(null);
  }, [isAuthenticated]);

  if (!hasEverSignedIn) {
    return (
      <div className="flex h-screen flex-col">
        <SignInCard onSignIn={signIn} />
      </div>
    );
  }

  return (
    // `useSingleEndpoint={false}` opts into the V2 multi-endpoint protocol
    // (separate /info, /agents/<id>/run, etc.), which is what this demo's
    // runtime route is wired up for.
    <CopilotKit
      runtimeUrl="/api/copilotkit-auth"
      agent="auth-demo"
      headers={headers}
      useSingleEndpoint={false}
      onError={handleAuthError}
    >
      <div className="flex h-screen flex-col gap-3 p-6">
        <AuthBanner
          authenticated={isAuthenticated}
          onSignOut={signOut}
          onSignIn={() => signIn(DEMO_TOKEN)}
        />
        <header>
          <h1 className="text-lg font-semibold">Authentication</h1>
        </header>
        {authError && (
          <div
            data-testid="auth-demo-error"
            className="rounded-md border border-amber-300 bg-amber-50 px-3 py-2 text-sm text-amber-900"
          >
            <strong className="font-semibold">
              Runtime rejected the request:
            </strong>{" "}
            <span data-testid="auth-demo-error-message">
              {authError.message}
            </span>{" "}
            <code className="ml-1 rounded bg-amber-100 px-1 py-0.5 font-mono text-xs">
              {authError.code}
            </code>
          </div>
        )}
        <div className="flex-1 overflow-hidden rounded-md border border-neutral-200">
          <CopilotChat
            agentId="auth-demo"
            className="h-full"
            onError={handleAuthError}
          />
        </div>
      </div>
    </CopilotKit>
  );
}

/**
 * Dedicated runtime for the /demos/auth cell — Claude Agent SDK port.
 *
 * Demonstrates framework-native request authentication via the V2
 * runtime's `onRequest` hook, which runs before routing and can
 * short-circuit the request by throwing a Response. Validates a static
 * `Authorization: Bearer <DEMO_TOKEN>` header; mismatch throws 401 before
 * the request reaches the agent.
 *
 * Implementation note: the V1 Next.js adapter
 * (`copilotRuntimeNextJSAppRouterEndpoint`) does NOT forward the `hooks`
 * option to the V2 fetch handler. To get `onRequest` wired we use
 * `createCopilotRuntimeHandler` from `@copilotkit/runtime/v2` directly —
 * the framework-agnostic fetch handler that returns a plain
 * `(Request) => Promise<Response>`, which composes cleanly with a
 * Next.js App Router route export.
 */

import type { NextRequest } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { createClaudeHttpAgent } from "@/app/api/_shared/claude-http-agent";
import { DEMO_AUTH_HEADER } from "@/app/demos/auth/demo-token";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

const authDemoAgent = createClaudeHttpAgent(`${AGENT_URL}/`);

const agents: Record<string, AbstractAgent> = {
  "auth-demo": authDemoAgent,
  default: authDemoAgent,
};

const runtime = new CopilotRuntime({
  // @ts-ignore -- see main route.ts
  agents,
});

const BASE_PATH = "/api/copilotkit-auth";

const handler = createCopilotRuntimeHandler({
  runtime,
  basePath: BASE_PATH,
  hooks: {
    onRequest: ({ request }) => {
      const authHeader = request.headers.get("authorization");
      if (authHeader !== DEMO_AUTH_HEADER) {
        throw new Response(
          JSON.stringify({
            error: "unauthorized",
            message:
              "Missing or invalid Authorization header. Click Authenticate above to send messages.",
          }),
          {
            status: 401,
            headers: { "content-type": "application/json" },
          },
        );
      }
    },
  },
});

export const POST = (req: NextRequest) => handler(req);
export const GET = (req: NextRequest) => handler(req);

"use client";

import { Button } from "@/components/ui/button";

interface AuthBannerProps {
  authenticated: boolean;
  onSignOut: () => void;
  onSignIn: () => void;
}

/**
 * Status strip rendered above <CopilotChat /> in both authenticated and
 * post-sign-out states. The post-sign-out (amber) variant exists so the demo
 * actually showcases what its name promises — the runtime rejecting an
 * unauthenticated request — instead of bouncing the user back to the gate
 * page where the rejection never happens.
 *
 * Pure presentational — owns no state itself. Testids are stable contract
 * for QA + Playwright specs.
 */
export function AuthBanner({
  authenticated,
  onSignOut,
  onSignIn,
}: AuthBannerProps) {
  const classes = authenticated
    ? "border-emerald-300 bg-emerald-50 text-emerald-900"
    : "border-amber-300 bg-amber-50 text-amber-900";

  return (
    <div
      data-testid="auth-banner"
      data-authenticated={authenticated ? "true" : "false"}
      className={`flex items-center justify-between gap-3 rounded-md border px-4 py-2 text-sm ${classes}`}
    >
      <span data-testid="auth-status" className="font-medium">
        {authenticated
          ? "✓ Signed in as demo user"
          : "⚠ Signed out — the agent will reject your messages until you sign in."}
      </span>
      {authenticated ? (
        <Button
          type="button"
          data-testid="auth-sign-out-button"
          size="sm"
          variant="outline"
          onClick={onSignOut}
        >
          Sign out
        </Button>
      ) : (
        <Button
          type="button"
          data-testid="auth-authenticate-button"
          size="sm"
          onClick={onSignIn}
        >
          Sign in
        </Button>
      )}
    </div>
  );
}

/**
 * Shared demo-token constant imported by both the client
 * (use-demo-auth.ts) and the server runtime route
 * (api/copilotkit-auth/route.ts). Keeping the constant in one file
 * prevents drift: changing the token in one place changes it everywhere.
 *
 * This is a DEMO token. Never use a hard-coded shared secret for real auth.
 */
export const DEMO_TOKEN = "demo-token-123";

export const DEMO_AUTH_HEADER = `Bearer ${DEMO_TOKEN}`;

"use client";

import { useCallback, useEffect, useState } from "react";
import { DEMO_TOKEN } from "./demo-token";

const STORAGE_KEY = "copilotkit:auth-demo:token";

export interface DemoAuthHandle {
  isAuthenticated: boolean;
  /** The token string when authenticated, otherwise null. */
  token: string | null;
  /** The full `Bearer <token>` value when authenticated, otherwise null. */
  authorizationHeader: string | null;
  /**
   * Whether the user has signed in at least once during the current page
   * session. Used by the page to decide between the first-paint SignInCard
   * (never signed in) and the persistent chat-with-amber-banner state
   * (signed in, then signed out) — the latter is the only state that
   * actually showcases the runtime rejecting unauthenticated requests.
   * Resets on full page reload by design.
   */
  hasEverSignedIn: boolean;
  /** Sign in with the provided token. */
  signIn: (token: string) => void;
  /** Clear the stored token. */
  signOut: () => void;
}

/**
 * Persistent demo auth state for the /demos/auth showcase cell. Tokens are
 * stored in localStorage so a page reload doesn't kick the user back out;
 * first paint of a fresh visitor is unauthenticated, which lets the demo
 * showcase its sign-in CTA up front.
 *
 * This is a DEMO. Never store real bearer tokens in localStorage in a
 * production application — that exposes them to any script running on the
 * page.
 */
export function useDemoAuth(): DemoAuthHandle {
  const [token, setToken] = useState<string | null>(null);
  const [hasEverSignedIn, setHasEverSignedIn] = useState(false);

  // Hydrate from localStorage after mount. Reading on initial render would
  // mismatch SSR (where window is undefined); deferring to useEffect keeps
  // first paint unauthenticated and avoids hydration warnings.
  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      const stored = window.localStorage.getItem(STORAGE_KEY);
      if (stored) {
        setToken(stored);
        setHasEverSignedIn(true);
      }
    } catch {
      // localStorage unavailable (privacy mode, etc.) — fall back to
      // in-memory only.
    }
  }, []);

  const signIn = useCallback((nextToken: string) => {
    setToken(nextToken);
    setHasEverSignedIn(true);
    try {
      window.localStorage.setItem(STORAGE_KEY, nextToken);
    } catch {
      // Ignore — in-memory state still works.
    }
  }, []);

  const signOut = useCallback(() => {
    setToken(null);
    // hasEverSignedIn intentionally stays true so the page keeps showing
    // the chat surface (with amber banner) after sign-out. That is the
    // state that demonstrates the runtime returning 401.
    try {
      window.localStorage.removeItem(STORAGE_KEY);
    } catch {
      // Ignore.
    }
  }, []);

  // The runtime gate compares against a fixed token, so anything other than
  // DEMO_TOKEN won't actually authenticate against the API. We still allow
  // arbitrary strings here because validation is the runtime's job — the UI
  // just owns "what header are we sending".
  return {
    isAuthenticated: token !== null,
    token,
    authorizationHeader: token ? `Bearer ${token}` : null,
    hasEverSignedIn,
    signIn,
    signOut,
  };
}

"use client";

// Tool Rendering — DEFAULT CATCH-ALL variant (simplest).
//
// This cell is the simplest point in the three-way progression. The
// backend exposes a handful of mock tools (get_weather, search_flights,
// get_stock_price, roll_dice) and the frontend ONLY opts into
// CopilotKit's built-in default tool-call card — no per-tool renderers,
// no custom wildcard UI.
//
// `useDefaultRenderTool()` (called with no config) registers the built-
// in `DefaultToolCallRenderer` under the `*` wildcard. That renderer
// shows the tool name, a live status pill (Running → Done), and a
// collapsible "Arguments / Result" section that fills in as the call
// progresses. Without this hook the runtime has NO `*` renderer, so
// `useRenderToolCall` falls through to `null` and tool calls are
// invisible — the user only sees the assistant's final text summary.

import React from "react";
import {
  CopilotKit,
  CopilotChat,
  useDefaultRenderTool,
} from "@copilotkit/react-core/v2";
import { useSuggestions } from "./suggestions";

export default function ToolRenderingDefaultCatchallDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit"
      agent="tool-rendering-default-catchall"
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  // Opt in to CopilotKit's built-in default tool-call card. Called with
  // no config so the package-provided `DefaultToolCallRenderer` is used
  // as the wildcard renderer — this is the "out-of-the-box" UI the cell
  // is meant to showcase.
  useDefaultRenderTool();

  useSuggestions();

  return (
    <CopilotChat
      agentId="tool-rendering-default-catchall"
      className="h-full rounded-2xl"
    />
  );
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { createClaudeHttpAgent } from "@/app/api/_shared/claude-http-agent";
import { internalRuntimeErrorResponse } from "@/app/api/_shared/route-error";
// CVDIAG backend instrumentation (L1-E). No-op pass-through unless
// CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
import { withCvdiagBackend } from "@/cvdiag-backend";

// The Claude agent backend runs as a separate TypeScript process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

function createAgent() {
  return createClaudeHttpAgent(`${AGENT_URL}/`);
}

// Register the same agent under all names used by demo pages.
// The Claude Agent SDK (TypeScript) backend is a pass-through: it forwards
// whatever tools the AG-UI client provides (frontend-registered via
// useFrontendTool / useRenderTool, plus runtime-injected tools from
// openGenerativeUI / a2ui / mcpApps middleware) to Claude. So distinct
// agent behaviour across demos comes from the frontend, not a per-demo
// backend graph — every demo can share the same HttpAgent target.
// IMPORTANT — read the override block BELOW this list before changing
// any entry: ids marked "NOT pass-through" in the override block are
// re-pointed at dedicated backend endpoints after this loop runs (e.g.
// `gen-ui-agent`, `tool-rendering`, `tool-rendering-*-catchall`,
// `tool-rendering-reasoning-chain`, `subagents`, `shared-state-read-write`,
// `headless-complete`). Those ids appear here only so `Object.keys(agents)`
// enumerates them and probes against the shared runtime resolve cleanly;
// the override block is the source of truth for which backend URL they
// actually hit.
const agentNames = [
  // existing demos
  "agentic_chat",
  "agentic-chat",
  "human_in_the_loop",
  "tool-rendering", // overridden -> /tool-rendering (NOT pass-through)
  "hitl",
  "gen-ui-tool-based",
  "gen-ui-agent", // overridden -> /gen-ui-agent (NOT pass-through)
  "shared-state-read",
  "shared-state-write",
  "shared-state-streaming", // overridden -> /shared-state-streaming
  "subagents", // overridden -> /subagents (NOT pass-through)
  "shared-state-read-write", // overridden -> /shared-state-read-write (NOT pass-through)
  "headless-complete", // overridden -> /headless-complete (NOT pass-through)
  // newly ported demos
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "frontend_tools",
  "threadid-frontend-tool-roundtrip",
  "frontend-tools-async",
  "hitl-in-chat",
  "hitl-in-chat-booking",
  "hitl-in-app",
  "readonly-state-agent-context",
  // runtime-injected demos (A2UI, open-gen-ui, mcp-apps live on dedicated
  // runtimes; here we register the ids so intra-app links and probe
  // requests resolve cleanly against the default runtime too)
  "declarative-gen-ui",
  "open-gen-ui",
  "open-gen-ui-advanced",
  "mcp-apps",
  // post-#4271 demos — each lives on a dedicated runtime, but we register
  // their agent ids here so probes against the shared runtime resolve
  // without 404s.
  "byoc_json_render",
  "declarative_json_render",
  "declarative-hashbrown-demo",
  "beautiful-chat",
  "multimodal-demo",
  "voice-demo",
  "agent-config-demo",
  "auth-demo",
  // Interrupt-adapted scheduling demos — both use useFrontendTool with an
  // async handler to simulate LangGraph interrupt(); the backend is the same
  // pass-through agent.
  "gen-ui-interrupt",
  "interrupt-headless",
  // showcase-fill-186 ports — NOT pass-through: backend owns the tools.
  // See override block below; entries here only seed Object.keys(agents)
  // for probe enumeration.
  "tool-rendering-default-catchall", // overridden -> /tool-rendering
  "tool-rendering-custom-catchall", // overridden -> /tool-rendering
  "tool-rendering-reasoning-chain", // overridden -> /tool-rendering-reasoning-chain
  // Reasoning variants — overridden -> /reasoning (NOT pass-through).
  "reasoning-default",
  "reasoning-custom",
];

const agents: Record<string, AbstractAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent();
}
agents["default"] = createAgent();

// Gen UI (Agent-based) is NOT a pass-through demo: the backend owns the
// `set_steps` tool and streams `state.steps` via STATE_SNAPSHOT (see
// `src/agent_server.ts` `/gen-ui-agent`). Point it at the dedicated
// endpoint — on the pass-through root the model's set_steps calls were
// forwarded to the frontend (which registers no such tool) and the
// multi-leg tool loop never completed.
agents["gen-ui-agent"] = createClaudeHttpAgent(`${AGENT_URL}/gen-ui-agent`);

// Tool Rendering family is likewise NOT pass-through: the pages register
// render-only hooks (no handlers), so frontend execution never returns a
// result and every card stalls in its loading state. The backend owns
// get_weather / search_flights / get_stock_price / roll_d20 at
// `/tool-rendering` (see `src/agent_server.ts`), and the reasoning-chain
// variant adds extended thinking + roll_dice at
// `/tool-rendering-reasoning-chain`.
agents["tool-rendering"] = createClaudeHttpAgent(`${AGENT_URL}/tool-rendering`);
agents["tool-rendering-default-catchall"] = createClaudeHttpAgent(
  `${AGENT_URL}/tool-rendering`,
);
agents["tool-rendering-custom-catchall"] = createClaudeHttpAgent(
  `${AGENT_URL}/tool-rendering`,
);
agents["tool-rendering-reasoning-chain"] = createClaudeHttpAgent(
  `${AGENT_URL}/tool-rendering-reasoning-chain`,
);

// Sub-Agents is NOT pass-through: the backend owns the
// research / writing / critique sub-agent tools and emits delegation
// progress via STATE_SNAPSHOT (see `src/agent_server.ts` `/subagents`).
// The demo page targets `/api/copilotkit-subagents` directly, but probes
// landing on the shared runtime must hit the dedicated backend endpoint
// too — otherwise the pass-through root forwards the supervisor's
// sub-agent tool calls to the frontend (which registers nothing) and the
// multi-leg loop stalls. Mirrors the gen-ui-agent treatment above.
agents["subagents"] = createClaudeHttpAgent(`${AGENT_URL}/subagents`);

// Shared State (Read + Write) is NOT pass-through: the backend reads
// `input.state.preferences` into the system prompt every turn and owns
// the `set_notes` tool that mutates `state.notes` (see
// `src/agent_server.ts` `/shared-state-read-write`). The demo page
// targets `/api/copilotkit-shared-state-read-write` directly; this
// override keeps shared-runtime probes resolving against the same
// backend endpoint so a probe never silently exercises the pass-through.
agents["shared-state-read-write"] = createClaudeHttpAgent(
  `${AGENT_URL}/shared-state-read-write`,
);

agents["shared-state-streaming"] = createClaudeHttpAgent(
  `${AGENT_URL}/shared-state-streaming`,
);

// Headless Chat (Complete) is NOT pass-through: the backend owns
// `get_weather` and `get_stock_price` (see `src/agent_server.ts`
// `/headless-complete`). The demo page targets
// `/api/copilotkit-headless-complete` directly, but registering the id
// here with the same backend URL keeps shared-runtime probes 200-resolving
// against the real handler (matching the file's probe-resolution
// convention for dedicated-runtime demos).
agents["headless-complete"] = createClaudeHttpAgent(
  `${AGENT_URL}/headless-complete`,
