    await runAgenticLoop(req, res, {
      systemPrompt: A2UI_DYNAMIC_SYSTEM_PROMPT,
      toolSchemas: [GENERATE_A2UI_TOOL_SCHEMA] as Anthropic.Tool[],
      initialState: {},
    });
  },
);

// Headless Chat (Complete) — backend exposes weather, stock, and revenue
