"use client";

// Headless Interrupt cell — demonstrates `useHeadlessInterrupt`.
//
// Layout: chat on the right, empty app surface on the left. The user
// triggers the agent from a chat suggestion. When the Claude backend surfaces
// a scheduling payload, we render a time-picker popup IN THE APP SURFACE
// (left pane) -- not inside the chat. Picking a slot resolves the pending
// interaction, the popup vanishes, and the agent confirms back in chat.

import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  CopilotKit,
  CopilotChat,
  useAgent,
  useConfigureSuggestions,
  useCopilotKit,
} from "@copilotkit/react-core/v2";
import { generateFallbackSlots } from "../_shared/interrupt-fallback-slots";
import type { TimeSlot } from "../_shared/interrupt-fallback-slots";

const INTERRUPT_EVENT_NAME = "on_interrupt";

type InterruptPayload = {
  topic?: string;
  attendee?: string;
  slots?: TimeSlot[];
};

type InterruptEvent = {
  name: string;
  value: InterruptPayload;
};

export default function InterruptHeadlessDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="interrupt-headless">
      <Layout />
    </CopilotKit>
  );
}

function Layout() {
  const { pending, resolve } = useHeadlessInterrupt("interrupt-headless");

  useConfigureSuggestions({
    suggestions: [
      {
        title: "Book a call with sales",
        message: "Book an intro call with the sales team to discuss pricing.",
      },
      {
        title: "Schedule a 1:1 with Alice",
        message: "Schedule a 1:1 with Alice next week to review Q2 goals.",
      },
    ],
    available: "always",
  });

  return (
    <div className="grid h-screen grid-cols-[1fr_420px] bg-[#FAFAFC]">
      <AppSurface pending={pending} resolve={resolve} />
      <div className="border-l border-[#DBDBE5] bg-white">
        <CopilotChat agentId="interrupt-headless" className="h-full" />
      </div>
    </div>
  );
}

function useHeadlessInterrupt(agentId: string): {
  pending: InterruptEvent | null;
  resolve: (response: unknown) => Promise<unknown>;
} {
  const { copilotkit } = useCopilotKit();
  const { agent } = useAgent({ agentId });
  const [pending, setPending] = useState<InterruptEvent | null>(null);
  const pendingRef = useRef<InterruptEvent | null>(null);
  pendingRef.current = pending;

  useEffect(() => {
    let local: InterruptEvent | null = null;
    const sub = agent.subscribe({
      onCustomEvent: ({ event }) => {
        if (event.name === INTERRUPT_EVENT_NAME) {
          // The AG-UI adapter JSON-stringifies interrupt values, so
          // parse when the value arrives as a string.
          const raw = event.value ?? {};
          local = {
            name: event.name,
            value: (typeof raw === "string"
              ? JSON.parse(raw)
              : raw) as InterruptPayload,
          };
        }
      },
      onRunStartedEvent: () => {
        local = null;
        setPending(null);
      },
      onRunFinalized: () => {
        if (local) {
          setPending(local);
          local = null;
        }
      },
      onRunFailed: () => {
        local = null;
        setPending(null);
      },
    });
    return () => sub.unsubscribe();
  }, [agent]);

  const resolve = useMemo(
    () => async (response: unknown) => {
      const snapshot = pendingRef.current;
      try {
        return await copilotkit.runAgent({
          agent,
          forwardedProps: {
            command: {
              resume: response,
              interruptEvent: snapshot?.value,
            },
          },
        });
      } catch (err) {
        // Catastrophic rejection (network error, auth failure, validation
        // reject) may fire before the run starts, so onRunFailed never runs.
        // Clear pending here so the popup unmounts. Symmetric with the
        // framework resolve catch + onRunFailed handler — all write null,
        // no race. Caller still sees the rethrow.
        console.error(
          "[interrupt-headless] resume runAgent rejected; clearing pending + rethrowing",
          err,
        );
        setPending(null);
        throw err;
      }
    },
    [agent, copilotkit],
  );

  return { pending, resolve };
}

type AppSurfaceProps = {
  pending: InterruptEvent | null;
  resolve: (response: unknown) => Promise<unknown>;
};

function AppSurface({ pending, resolve }: AppSurfaceProps) {
  return (
    <div
      data-testid="interrupt-headless-app-surface"
      className="relative flex h-full flex-col overflow-hidden"
    >
      <header className="border-b border-[#DBDBE5] bg-white px-8 py-5">
        <div className="text-[10px] font-medium uppercase tracking-[0.14em] text-[#57575B]">
          Headless interrupt
        </div>
        <h1 className="text-xl font-semibold text-[#010507]">Scheduling</h1>
      </header>

      <div className="relative flex flex-1 items-center justify-center p-8">
        {pending ? (
          <TimeSlotPopup
            payload={pending.value}
            onPick={(slot) =>
              resolve({ chosen_time: slot.iso, chosen_label: slot.label })
            }
            onCancel={() => resolve({ cancelled: true })}
          />
        ) : (
          <EmptyState />
        )}
      </div>
    </div>
  );
}

function EmptyState() {
  return (
    <div
      data-testid="interrupt-headless-empty"
      className="max-w-sm text-center"
    >
      <div className="mx-auto mb-4 flex h-10 w-10 items-center justify-center rounded-full border border-[#DBDBE5] bg-white text-[#85ECCE]">
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="18"
          height="18"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <rect x="3" y="4" width="18" height="18" rx="2" />
          <path d="M16 2v4M8 2v4M3 10h18" />
        </svg>
      </div>
      <div className="text-sm font-medium text-[#010507]">
        Nothing scheduled yet
      </div>
      <p className="mt-1 text-sm text-[#57575B]">
        Ask the assistant to book something. When it needs your input, a picker
        will appear right here.
      </p>
    </div>
  );
}

type TimeSlotPopupProps = {
  payload: InterruptPayload;
  onPick: (slot: TimeSlot) => void;
  onCancel: () => void;
};

function TimeSlotPopup({ payload, onPick, onCancel }: TimeSlotPopupProps) {
  // Prefer the slots from the interrupt payload — the backend
  // (`interrupt_agent.py:_candidate_slots`) generates them relative to "now"
  // so the picker always shows future times. Fall back to a fresh
  // local-time generator only if the backend didn't supply any.
  const slots =
    payload.slots && payload.slots.length > 0
      ? payload.slots
      : generateFallbackSlots();
  return (
    <div
      role="dialog"
      aria-modal="false"
      data-testid="interrupt-headless-popup"
      className="w-full max-w-md rounded-2xl border border-[#DBDBE5] bg-white p-6 shadow-[0_20px_40px_-20px_rgba(1,5,7,0.25)]"
    >
      <div className="mb-2 flex items-center gap-2">
        <span className="inline-flex h-1.5 w-1.5 animate-pulse rounded-full bg-[#85ECCE]" />
        <span className="text-[10px] font-medium uppercase tracking-[0.14em] text-[#57575B]">
          Pick a time
        </span>
      </div>
      <h2 className="mb-1 text-lg font-semibold text-[#010507]">
        {payload.topic ?? "Meeting"}
      </h2>
      {payload.attendee ? (
        <p className="mb-5 text-sm text-[#57575B]">
          with{" "}
          <span className="font-medium text-[#010507]">{payload.attendee}</span>
        </p>
      ) : (
        <div className="mb-5" />
      )}

      <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
        {slots.map((slot) => (
          <button
            key={slot.iso}
            type="button"
            data-testid={`interrupt-headless-slot-${slot.iso}`}
            onClick={() => onPick(slot)}
            className="rounded-xl border border-[#DBDBE5] bg-white px-3 py-3 text-sm font-medium text-[#010507] transition-colors hover:border-[#BEC2FF] hover:bg-[#BEC2FF1A]"
          >
            {slot.label}
          </button>
        ))}
      </div>

      <button
        type="button"
        data-testid="interrupt-headless-cancel"
        onClick={onCancel}
        className="mt-4 w-full rounded-xl border border-[#DBDBE5] bg-white px-3 py-2 text-xs font-medium uppercase tracking-[0.12em] text-[#57575B] transition-colors hover:bg-[#FAFAFC]"
      >
        Cancel
      </button>
    </div>
  );
}

/**
 * Agent Server for Claude Agent SDK (TypeScript)
 *
 * Express server that hosts a Claude-powered agent backend.
 * The Next.js CopilotKit runtime proxies requests here via AG-UI protocol.
 */

// Cold-start instrumentation: emitted before any side-effect imports so
// Railway logs reveal exactly which phase (module load, Anthropic SDK
// init, express.listen) consumes the watchdog budget. Paired with the
// `[entrypoint] pre-node ...` print in entrypoint.sh so timestamps chain.
// Disambiguates the observed failure class where process claims to be
// listening but /health probes never succeed.
console.log(`[agent_server] module loaded ${new Date().toISOString()}`);

import type { Request, Response } from "express";
import express from "express";
import Anthropic from "@anthropic-ai/sdk";
import { EventEncoder } from "@ag-ui/encoder";
import type { RunAgentInput, Message } from "@ag-ui/core";
import { EventType } from "@ag-ui/core";
import {
  A2UI_DEFAULT_DESIGN_GUIDELINES,
  A2UI_DEFAULT_GENERATION_GUIDELINES,
} from "@copilotkit/shared";
import * as dotenv from "dotenv";
import * as PartialJSON from "partial-json";
import { randomUUID } from "crypto";
import { BYOC_JSON_RENDER_SYSTEM_PROMPT } from "./agent/byoc-json-render-prompt";
import { BYOC_HASHBROWN_SYSTEM_PROMPT } from "./agent/byoc-hashbrown-prompt";
import {
  AGENT_CONFIG_DEFAULT_SYSTEM_PROMPT,
  buildAgentConfigSystemPrompt,
} from "./agent/agent-config-prompt";
import {
  SET_NOTES_TOOL_SCHEMA,
  buildSharedStateReadWriteSystemPrompt,
  coercePreferences,
} from "./agent/shared-state-read-write-prompt";
import {
  SUBAGENT_SYSTEM_BY_NAME,
  SUBAGENT_TOOL_SCHEMAS,
  SUPERVISOR_SYSTEM_PROMPT,
} from "./agent/subagents-prompts";
import type { SubAgentName } from "./agent/subagents-prompts";
import {
  A2UI_FIXED_SYSTEM_PROMPT,
  DISPLAY_FLIGHT_TOOL_SCHEMA,
  buildDisplayFlightOperations,
} from "./agent/a2ui-fixed-prompt";
import {
  A2UI_DYNAMIC_SYSTEM_PROMPT,
  GENERATE_A2UI_TOOL_SCHEMA,
} from "./agent/a2ui-dynamic-prompt";
import {
  HEADLESS_COMPLETE_SYSTEM_PROMPT,
  HEADLESS_GET_REVENUE_CHART_TOOL_SCHEMA,
  HEADLESS_GET_STOCK_PRICE_TOOL_SCHEMA,
  HEADLESS_GET_WEATHER_TOOL_SCHEMA,
  getRevenueChartImpl,
  getStockPriceImpl,
  getWeatherImpl,
} from "./agent/headless-complete-prompt";
import {
  GEN_UI_AGENT_SYSTEM_PROMPT,
  SET_STEPS_TOOL_SCHEMA,
} from "./agent/gen-ui-agent-prompt";
import {
  REASONING_CHAIN_SYSTEM_PROMPT,
  ROLL_D20_TOOL_SCHEMA,
  ROLL_DICE_TOOL_SCHEMA,
  SEARCH_FLIGHTS_TOOL_SCHEMA,
  TOOL_RENDERING_SYSTEM_PROMPT,
  rollD20Impl,
  rollDiceImpl,
  searchFlightsImpl as searchFlightsByRouteImpl,
} from "./agent/tool-rendering-prompts";
import {
  runWithClaudeAgentSdk,
  shouldUseClaudeAgentSdk,
} from "./claude-agent-sdk-adapter";
import { queryDataImpl, renderFlightsImpl } from "./agent/beautiful-chat-tools";
import type { Flight } from "./agent/beautiful-chat-tools";

dotenv.config({ path: ".env.local" });
dotenv.config();

const app = express();
// Increase payload limit so base64-encoded attachments (images, PDFs) up
// to the frontend's 20MB cap fit inside the request body after base64
// expansion and JSON envelope overhead.
app.use(express.json({ limit: "35mb" }));

const HOST = process.env.AGENT_HOST || "0.0.0.0";
const PORT = parseInt(process.env.AGENT_PORT || "8000", 10);
const CLAUDE_MODEL = normalizeAnthropicModel(
  process.env.CLAUDE_MODEL || process.env.ANTHROPIC_MODEL || "claude-opus-4-8",
);
// Anthropic SDK 0.57's types predate adaptive thinking, but its transport
// forwards this API-supported value unchanged.
const ADAPTIVE_THINKING = {
  type: "adaptive",
} as unknown as Anthropic.Messages.ThinkingConfigParam;
const CLAUDE_VISION_MODEL = normalizeAnthropicModel(
  process.env.CLAUDE_VISION_MODEL ||
    process.env.ANTHROPIC_VISION_MODEL ||
    CLAUDE_MODEL,
);

console.log(`[agent_server] pre-Anthropic ${new Date().toISOString()}`);
const anthropic = new Anthropic({
  apiKey: process.env.ANTHROPIC_API_KEY,
});

console.log("[agent_server] Initializing Claude agent server");
console.log(`[agent_server] Model: ${CLAUDE_MODEL}`);
console.log(
  `[agent_server] ANTHROPIC_API_KEY: ${process.env.ANTHROPIC_API_KEY ? "set" : "NOT SET"}`,
);

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Extract inbound diagnostic/context headers that should ride along to the
 * outbound Anthropic call. Only `x-*` headers are forwarded; never forward
 * app/session `authorization` tokens to the provider. Notably,
 * `x-aimock-context` rides via this path so aimock can match the right
 * fixture; without this, every outbound `/v1/messages` request loses the
 * discriminator and aimock returns 404.
 *
 * Returns a plain Record so it can be spread into Anthropic SDK
 * `RequestOptions.headers` on every `messages.stream` / `messages.create`
 * call. We strip `host`, `content-length` and `accept-encoding` because
 * those are connection-level concerns the SDK manages itself.
 */
function extractForwardedHeaders(req: Request): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [key, value] of Object.entries(req.headers)) {
    if (typeof value !== "string") continue;
    const lower = key.toLowerCase();
    if (lower.startsWith("x-")) {
      out[key] = value;
    }
  }
  // CVDIAG (als-snapshot): record whether the inbound x-aimock-context
  // discriminator was present at the moment we capture the inbound
  // headers off the Express request. Never log the full value — prefix
  // only. Header lookups are case-insensitive against the captured map.
  const lookup = (name: string): string | undefined => {
    for (const [k, v] of Object.entries(out)) {
      if (k.toLowerCase() === name) return v;
    }
    return undefined;
  };
  const slug = lookup("x-aimock-context");
  const runId = lookup("x-diag-run-id");
  const hops = lookup("x-diag-hops");
  const hopCount = hops ? hops.split(",").filter(Boolean).length : 0;
  console.log(
    `CVDIAG component=route-claude-sdk-ts boundary=als-snapshot ` +
      `run_id=${runId ?? "none"} slug=${slug ?? "MISSING"} ` +
      `header_present=${slug != null} ` +
      `header_value_prefix=${slug ? slug.slice(0, 12) : ""} ` +
      `hop=${hops ? hopCount : "-"} status=${slug ? "ok" : "miss"} ` +
      `test_id=${lookup("x-test-id") ?? "none"} error=`,
  );
  return out;
}

/**
 * CVDIAG (outbound-llm) choke-point for the claude-sdk-ts backend. Returns
 * a NEW headers map (never mutates the caller's) with this layer's hop tag
 * appended to the x-diag-hops breadcrumb, and logs header presence at the
 * moment the outbound Anthropic request is built. x-diag-run-id /
 * x-diag-hops ride the same x-* forwarding path as x-aimock-context (both
 * captured by `extractForwardedHeaders`); we only append the breadcrumb hop
 * here. Returns the augmented map so callers spread it into the SDK
 * `RequestOptions.headers`.
 */
function diagOutboundHeaders(
  forwardedHeaders: Record<string, string>,
): Record<string, string> {
  const lookup = (name: string): string | undefined => {
    for (const [k, v] of Object.entries(forwardedHeaders)) {
      if (k.toLowerCase() === name) return v;
    }
    return undefined;
  };
  const slug = lookup("x-aimock-context");
  const runId = lookup("x-diag-run-id");
  // GATING RULE: only deviate from the original control flow (append the
  // x-diag-hops breadcrumb, emit the per-outbound CVDIAG log) when a
  // diagnostic header is present (x-diag-run-id OR x-aimock-context). On
  // non-diagnostic traffic return the forwarded headers UNCHANGED so the
  // outbound Anthropic request is byte-identical to pre-instrumentation, and
  // skip the noisy per-outbound log.
  const diagnosticPresent = runId != null || slug != null;
  if (!diagnosticPresent) {
    return forwardedHeaders;
  }
  const priorHops = lookup("x-diag-hops") ?? "";
  const nextHops = priorHops
    ? `${priorHops},backend-claude-sdk-ts`
    : "backend-claude-sdk-ts";
  // Build a fresh map so we don't mutate the shared forwardedHeaders that
  // may be reused across multiple outbound calls in the agentic loop.
  const augmented: Record<string, string> = {
    ...forwardedHeaders,
    "x-diag-hops": nextHops,
  };
  const hopCount = nextHops.split(",").filter(Boolean).length;
  console.log(
    `CVDIAG component=backend-claude-sdk-ts boundary=outbound-llm ` +
      `run_id=${runId ?? "none"} slug=${slug ?? "MISSING"} ` +
      `header_present=${slug != null} ` +
      `header_value_prefix=${slug ? slug.slice(0, 12) : ""} ` +
      `hop=${hopCount} status=${slug ? "ok" : "miss"} ` +
      `test_id=${lookup("x-test-id") ?? "none"} error=`,
  );
  return augmented;
}

/**
 * Convert an AG-UI `binary` content part into an Anthropic ContentBlock.
 * Returns `null` if the part cannot be mapped (unsupported mime/no payload).
 *
 * Claude's Messages API accepts `image` and `document` blocks natively;
 * images use `source: { type: "base64", media_type, data }` and PDFs use
 * `type: "document"` with the same source shape. URL-backed parts are
 * mapped to `source: { type: "url", url }`.
 */
function binaryPartToAnthropic(part: {
  type: "binary";
  mimeType: string;
  data?: string;
  url?: string;
}): Anthropic.ContentBlockParam | null {
  const mime = part.mimeType || "";
  const isImage = isSupportedAnthropicImageMime(mime);
  const isPdf =
    mime === "application/pdf" || mime.toLowerCase().includes("pdf");

  if (mime.startsWith("image/") && !isImage) {
    return {
      type: "text",
      text: `[Attached image: unsupported type ${mime}.]`,
    };
  }
  if (!isImage && !isPdf) return null;

  if (part.data) {
    if (isImage) {
      return {
        type: "image",
        source: {
          type: "base64",
          media_type: mime as
            | "image/jpeg"
            | "image/png"
            | "image/gif"
            | "image/webp",
          data: part.data,
        },
      };
    }
    return {
      type: "document",
      source: {
        type: "base64",
        media_type: "application/pdf",
        data: part.data,
      },
    };
  }

  if (part.url) {
    if (isImage) {
      return {
        type: "image",
        source: { type: "url", url: part.url },
      };
    }
    return {
      type: "document",
      source: { type: "url", url: part.url },
    };
  }

  return null;
}

function isSupportedAnthropicImageMime(mime: string): boolean {
  return (
    mime === "image/jpeg" ||
    mime === "image/png" ||
    mime === "image/gif" ||
    mime === "image/webp"
  );
}

function sourceBackedPartToAnthropic(part: {
  type: "image" | "document";
  source?: {
    type?: string;
    value?: string;
    data?: string;
    url?: string;
    mimeType?: string;
    media_type?: string;
  };
}): Anthropic.ContentBlockParam | null {
  const source = part.source ?? {};
  const mime = source.mimeType ?? source.media_type ?? "";
  const value = source.value ?? source.data;
  const url = source.url ?? (source.type === "url" ? source.value : undefined);

  if (part.type === "image") {
    const imageMime = mime || "image/png";
    if (!isSupportedAnthropicImageMime(imageMime)) {
      return {
        type: "text",
        text: `[Attached image: unsupported type ${imageMime}.]`,
      };
    }
    if (source.type === "data" && value) {
      return {
        type: "image",
        source: {
          type: "base64",
          media_type: imageMime as
            | "image/jpeg"
            | "image/png"
            | "image/gif"
            | "image/webp",
          data: value,
        },
      };
    }
    if (url) {
      return { type: "image", source: { type: "url", url } };
    }
    return null;
  }

  if (part.type === "document") {
    if (source.type === "data" && value) {
      return {
        type: "document",
        source: {
          type: "base64",
          media_type: "application/pdf",
          data: value,
        },
      };
    }
    if (url) {
      return {
        type: "document",
        source: { type: "url", url },
      } as Anthropic.ContentBlockParam;
    }
  }

  return null;
}

function buildAnthropicMessages(messages: Message[]): Anthropic.MessageParam[] {
  const result: Anthropic.MessageParam[] = [];
  const skippedToolUseIds = new Set<string>();

  for (const msg of messages) {
    if (msg.role === "user") {
      const raw = (msg as any).content;
      if (Array.isArray(raw)) {
        // AG-UI content parts — map text + attachments to Anthropic blocks.
        const blocks: Anthropic.ContentBlockParam[] = [];
        for (const part of raw) {
          if (!part || typeof part !== "object") continue;
          if (part.type === "text" && typeof part.text === "string") {
            blocks.push({ type: "text", text: part.text });
          } else if (part.type === "binary") {
            const mapped = binaryPartToAnthropic(part);
            if (mapped) blocks.push(mapped);
          } else if (part.type === "image" || part.type === "document") {
            const mapped = sourceBackedPartToAnthropic(part);
            if (mapped) blocks.push(mapped);
          }
        }
        // Guard: Anthropic rejects user messages with empty content.
        if (blocks.length === 0) {
          blocks.push({
            type: "text",
            text: "[Unsupported attachment omitted.]",
          });
        }
        result.push({ role: "user", content: blocks });
      } else {
        result.push({
          role: "user",
          content: raw ?? "",
        });
      }
    } else if (msg.role === "assistant") {
      const toolCalls = (msg as any).toolCalls as
        | Array<{ id: string; function: { name: string; arguments: string } }>
        | undefined;

      if (toolCalls && toolCalls.length > 0) {
        const content: Anthropic.ContentBlock[] = [];

        const textContent = (msg as any).content;
        if (textContent) {
          content.push({ type: "text", text: textContent, citations: null });
        }

        for (const tc of toolCalls) {
          let input: Record<string, unknown> = {};
          try {
            input = JSON.parse(tc.function.arguments);
          } catch (parseErr) {
            // Surface the failure so we don't silently rewind tool args to
            // {}. For tools like `set_notes` that take an array, an empty
            // dict translates to an empty list and clears the user's notes.
            // Skip the tool_use block so we don't replay corrupted state.
            const message =
              parseErr instanceof Error ? parseErr.message : String(parseErr);
            console.warn(
              `[agent_server] failed to parse tool_use arguments for ${tc.function.name} (id=${tc.id}); skipping replay. error=${message}`,
            );
            if (tc.id) skippedToolUseIds.add(tc.id);
            continue;
          }
          content.push({
            type: "tool_use",
            id: tc.id,
            name: tc.function.name,
            input,
          });
        }

        if (content.length > 0) {
          result.push({ role: "assistant", content });
        }
      } else {
        result.push({
          role: "assistant",
          content: (msg as any).content ?? "",
        });
      }
    } else if (msg.role === "tool") {
      const toolMsg = msg as any;
      const toolCallId = toolMsg.toolCallId ?? "";
      if (!toolCallId || skippedToolUseIds.has(toolCallId)) continue;
      result.push({
        role: "user",
        content: [
          {
            type: "tool_result",
            tool_use_id: toolCallId,
            content:
              typeof toolMsg.content === "string"
                ? toolMsg.content
                : JSON.stringify(toolMsg.content),
          },
        ],
      });
    }
    // skip "system" and "developer" roles — handled separately as system prompt
  }

  return result;
}

function latestUserMessageOnly(messages: Message[]): Message[] {
  for (let index = messages.length - 1; index >= 0; index--) {
    if (messages[index]?.role === "user") {
      return [messages[index]!];
    }
  }
  return [];
}

function buildAgentContextString(context: unknown): string {
  if (!Array.isArray(context) || context.length === 0) return "";

  return context
    .map((entry): string => {
      if (!entry || typeof entry !== "object") return "";
      const record = entry as Record<string, unknown>;
      const description =
        typeof record.description === "string" ? record.description : "";
      const value =
        typeof record.value === "string"
          ? record.value
          : record.value == null
            ? ""
            : JSON.stringify(record.value);
      if (!description && !value) return "";
      return description ? `${description}: ${value}` : value;
    })
    .filter(Boolean)
    .join("\n");
}

function appendContextToSystemPrompt(
  systemPrompt: string,
  contextString: string,
): string {
  if (!contextString) return systemPrompt;
  return `${systemPrompt}\n\nContext:\n${contextString}`;
}

function buildTools(tools: RunAgentInput["tools"]): Anthropic.Tool[] {
  if (!tools || tools.length === 0) return [];

  return tools.map((tool) => {
    let inputSchema: Anthropic.Tool.InputSchema = {
      type: "object",
      properties: {},
    };
    if (tool.parameters) {
      try {
        const parsed =
          typeof tool.parameters === "string"
            ? JSON.parse(tool.parameters)
            : tool.parameters;
        inputSchema = parsed as Anthropic.Tool.InputSchema;
      } catch (parseErr) {
        // Don't silently swap in an empty schema — Claude will then accept
        // any input shape, which compounds whatever caller bug produced
        // the malformed JSON. Warn loudly so the tool definition gets
        // fixed instead of being papered over.
        const message =
          parseErr instanceof Error ? parseErr.message : String(parseErr);
        console.warn(
          `[agent_server] failed to parse tool.parameters for ${tool.name}; using empty schema. error=${message}`,
        );
      }
    }
    return {
      name: tool.name,
      description: tool.description ?? "",
      input_schema: inputSchema,
    };
  });
}

/**
 * Does the user messages contain any binary parts? Used to route the run
 * to the vision-capable Sonnet model instead of the default Haiku.
 */
function messagesHaveAttachments(messages: Message[]): boolean {
  for (const msg of messages) {
    if (msg.role !== "user") continue;
    const content = (msg as any).content;
    if (!Array.isArray(content)) continue;
    for (const part of content) {
      if (
        part &&
        typeof part === "object" &&
        (part.type === "binary" ||
          part.type === "image" ||
          part.type === "document")
      ) {
        return true;
      }
    }
  }
  return false;
}

function normalizeAnthropicModel(model: string): string {
  return model === "claude-sonnet-4.6" ? "claude-sonnet-4-6" : model;
}

interface DemoConfig {
  /** Fixed system prompt. Overridden by `buildSystemPrompt` when provided. */
  systemPrompt?: string;
  /**
   * When present, takes precedence over `systemPrompt` and can read the
   * per-run `forwardedProps` to compose a dynamic prompt (used by
   * the agent-config demo).
   */
  buildSystemPrompt?: (forwardedProps: Record<string, unknown>) => string;
  /** Force vision-capable model regardless of attachment detection. */
  forceVisionModel?: boolean;
  /**
   * Enable Anthropic adaptive thinking and forward `thinking_delta` events
   * as AG-UI REASONING_MESSAGE_* events. Requires a model that supports
   * adaptive thinking. Sets `thinking: { type: "adaptive" }`.
   */
  enableThinking?: boolean;
  /** Override model used when `enableThinking` is set. */
  thinkingModel?: string;
}

