"use client";

import React from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "./_components/card";
import { Button } from "./_components/button";

export interface NotesCardProps {
  notes: string[];
  onClear: () => void;
}

/**
 * Sidebar card that READS agent-authored notes out of shared state.
 *
 * The agent writes these via its `set_notes` tool. The UI reflects every
 * update in real time because the parent page subscribes via
 * `useAgent({ updates: [OnStateChanged] })` and passes `state.notes` in.
 *
 * The "Clear" button is a write-back (UI -> agent state) to demonstrate
 * both directions on the same field.
 */
// Read-side render: this card reflects the agent-authored `notes` slice
// of shared state. The parent page passes `state.notes` in; we never
// touch agent state ourselves — we just render it. The Clear button is
// a small write-back, exposed as an `onClear` prop.
export function NotesCard({ notes, onClear }: NotesCardProps) {
  return (
    <Card data-testid="notes-card" className="w-full">
      <CardHeader>
        <div className="flex items-start justify-between gap-3">
          <div className="space-y-1.5">
            <CardTitle>Agent Scratch pad</CardTitle>
            <CardDescription>
              The agent writes here via its{" "}
              <code className="font-mono text-[11px] text-[#010507]">
                set_notes
              </code>{" "}
              tool. The UI re-renders from shared state.
            </CardDescription>
          </div>
          {notes.length > 0 && (
            <Button
              type="button"
              onClick={onClear}
              data-testid="notes-clear-button"
              variant="destructive"
              size="sm"
              className="uppercase tracking-[0.14em] text-[10px]"
            >
              Clear
            </Button>
          )}
        </div>
      </CardHeader>

      <CardContent>
        {notes.length === 0 ? (
          <div
            data-testid="notes-empty"
            className="text-sm text-[#838389] italic min-h-[160px] flex items-center justify-center text-center px-4 border border-dashed border-[#E9E9EF] rounded-xl bg-[#FAFAFC]"
          >
            the agent will make observations about you and note them here!
          </div>
        ) : (
          <ul
            data-testid="notes-list"
            className="space-y-2 text-sm text-[#010507]"
          >
            {notes.map((note, i) => (
              <li
                key={i}
                data-testid="note-item"
                className="flex gap-2 rounded-lg border border-[#E9E9EF] bg-[#FAFAFC] px-3 py-2"
              >
                <span className="text-[#838389] font-mono text-xs leading-5 select-none">
                  {String(i + 1).padStart(2, "0")}
                </span>
                <span className="flex-1">{note}</span>
              </li>
            ))}
          </ul>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import React from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "./_components/card";
import { Badge } from "./_components/badge";
import { Input, Label, Select } from "./_components/input";

// Data model the UI writes into agent state via agent.setState()
export interface Preferences {
  name: string;
  tone: "formal" | "casual" | "playful";
  language: string;
  interests: string[];
}

export const INTEREST_OPTIONS = [
  "Cooking",
  "Travel",
  "Tech",
  "Music",
  "Sports",
  "Books",
  "Movies",
];

export interface PreferencesCardProps {
  value: Preferences;
  onChange: (next: Preferences) => void;
}

/**
 * Sidebar card — the *only* place where the user edits their preferences.
 *
 * Every change invokes `onChange`, which the parent page routes straight into
 * `agent.setState({ preferences: ... })`. On the next turn, the backend's
 * `PreferencesInjectorMiddleware` reads that same object out of agent state
 * and injects it into the system prompt, so the agent's reply visibly adapts.
 */
// Write-side render: every edit here bubbles up through `onChange`, and
// the parent pipes it straight into `agent.setState({ preferences: ... })`.
// Nothing in this component knows about the agent directly — that's
// intentional: the card is a plain controlled form, and the agent state
// wiring lives one layer up.
export function PreferencesCard({ value, onChange }: PreferencesCardProps) {
  const set = <K extends keyof Preferences>(key: K, v: Preferences[K]) =>
    onChange({ ...value, [key]: v });

  const toggleInterest = (interest: string) => {
    const has = (value.interests ?? []).includes(interest);
    set(
      "interests",
      has
        ? (value.interests ?? []).filter((i) => i !== interest)
        : [...(value.interests ?? []), interest],
    );
  };

  return (
    <Card data-testid="preferences-card" className="w-full">
      <CardHeader>
        <CardTitle>Your preferences</CardTitle>
        <CardDescription>
          These are written into agent state. The agent reads them on every
          turn.
        </CardDescription>
      </CardHeader>

      <CardContent className="space-y-5">
        <div className="space-y-1.5">
          <Label htmlFor="pref-name">Name</Label>
          <Input
            id="pref-name"
            data-testid="pref-name"
            type="text"
            value={value.name}
            onChange={(e) => set("name", e.target.value)}
            placeholder="e.g. Atai"
          />
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div className="space-y-1.5">
            <Label htmlFor="pref-tone">Tone</Label>
            <Select
              id="pref-tone"
              data-testid="pref-tone"
              value={value.tone}
              onChange={(e) =>
                set("tone", e.target.value as Preferences["tone"])
              }
            >
              <option value="formal">Formal</option>
              <option value="casual">Casual</option>
              <option value="playful">Playful</option>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="pref-language">Language</Label>
            <Select
              id="pref-language"
              data-testid="pref-language"
              value={value.language}
              onChange={(e) => set("language", e.target.value)}
            >
              <option>English</option>
              <option>Spanish</option>
              <option>French</option>
              <option>German</option>
              <option>Japanese</option>
            </Select>
          </div>
        </div>

        <div className="space-y-2">
          <Label>Interests</Label>
          <div className="flex flex-wrap gap-2">
            {INTEREST_OPTIONS.map((interest) => {
              const selected = (value.interests ?? []).includes(interest);
              return (
                <button
                  key={interest}
                  type="button"
                  onClick={() => toggleInterest(interest)}
                  className="focus:outline-none"
                >
                  <Badge
                    variant={selected ? "selected" : "outline"}
                    className="cursor-pointer"
                  >
                    {interest}
                  </Badge>
                </button>
              );
            })}
          </div>
        </div>
      </CardContent>

      <CardFooter className="flex-col items-stretch gap-2">
        <div className="text-[10px] uppercase tracking-[0.14em] text-[#838389]">
          Shared state
        </div>
        <pre
          data-testid="pref-state-json"
          className="bg-[#FAFAFC] border border-[#E9E9EF] rounded-lg p-3 text-xs text-[#010507] overflow-x-auto font-mono min-h-[140px] whitespace-pre"
        >
          {JSON.stringify(value, null, 2)}
        </pre>
      </CardFooter>
    </Card>
  );
}

"use client";

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export function useSharedStateReadWriteSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      { title: "Greet me", message: "Say hi and introduce yourself." },
      {
        title: "Remember something",
        message:
          "Remember that I prefer morning meetings and that I don't eat dairy.",
      },
      {
        title: "Plan a weekend",
        message: "Suggest a weekend plan based on my interests.",
      },
    ],
    available: "always",
  });
}

