"use client";

// Tool Rendering — PRIMARY (per-tool + catch-all) variant.
//
// The most sophisticated point in the three-way progression: every
// "interesting" backend tool gets its own dedicated, branded UI, and a
// catch-all paints anything that slips through.
//
//   get_weather     → <WeatherCard />       (per-tool renderer)
//   search_flights  → <FlightListCard />    (per-tool renderer)
//   get_stock_price → <StockCard />         (per-tool renderer)
//   roll_d20        → <D20Card />           (per-tool renderer)
//   *               → <CustomCatchallRenderer /> (wildcard fallback)

import React from "react";
import {
  CopilotKit,
  CopilotChat,
  useRenderTool,
  useDefaultRenderTool,
} from "@copilotkit/react-core/v2";
import { z } from "zod";
import { WeatherCard } from "./weather-card";
import { FlightListCard, type Flight } from "./flight-list-card";
import { StockCard } from "./stock-card";
import { D20Card } from "./d20-card";
import {
  CustomCatchallRenderer,
  type CatchallToolStatus,
} from "./custom-catchall-renderer";
import { parseJsonResult } from "../_shared/parse-json-result";
import { useSuggestions } from "./suggestions";

interface WeatherResult {
  city?: string;
  temperature?: number;
  humidity?: number;
  wind_speed?: number;
  conditions?: string;
}

interface FlightSearchResult {
  origin?: string;
  destination?: string;
  flights?: Flight[];
}

interface StockResult {
  ticker?: string;
  price_usd?: number;
  change_pct?: number;
}

interface D20Result {
  value?: number;
  result?: number;
  sides?: number;
}

export default function ToolRenderingDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="tool-rendering">
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  // Per-tool renderer #1: get_weather → branded WeatherCard.
  useRenderTool(
    {
      name: "get_weather",
      parameters: z.object({
        location: z.string(),
      }),
      render: ({ parameters, result, status }) => {
        const loading = status !== "complete";
        const parsed = parseJsonResult<WeatherResult>(result);
        return (
          <WeatherCard
            loading={loading}
            location={parameters?.location ?? parsed.city ?? ""}
            temperature={parsed.temperature}
            humidity={parsed.humidity}
            windSpeed={parsed.wind_speed}
            conditions={parsed.conditions}
          />
        );
      },
    },
    [],
  );

  // Per-tool renderer #2: search_flights → branded FlightListCard.
  useRenderTool(
    {
      name: "search_flights",
      parameters: z.object({
        origin: z.string(),
        destination: z.string(),
      }),
      render: ({ parameters, result, status }) => {
        const loading = status !== "complete";
        const parsed = parseJsonResult<FlightSearchResult>(result);
        return (
          <FlightListCard
            loading={loading}
            origin={parameters?.origin ?? parsed.origin ?? ""}
            destination={parameters?.destination ?? parsed.destination ?? ""}
            flights={parsed.flights ?? []}
          />
        );
      },
    },
    [],
  );

  // Per-tool renderer #3: get_stock_price → branded StockCard.
  useRenderTool(
    {
      name: "get_stock_price",
      parameters: z.object({
        ticker: z.string(),
      }),
      render: ({ parameters, result, status }) => {
        const loading = status !== "complete";
        const parsed = parseJsonResult<StockResult>(result);
        return (
          <StockCard
            loading={loading}
            ticker={parameters?.ticker ?? parsed.ticker ?? ""}
            priceUsd={parsed.price_usd}
            changePct={parsed.change_pct}
          />
        );
      },
    },
    [],
  );

  // Per-tool renderer #4: roll_d20 → branded D20Card. Each tool call
  // mounts its own card so e2e tests can count them.
  useRenderTool(
    {
      name: "roll_d20",
      parameters: z.object({
        value: z.number().optional(),
      }),
      render: ({ result, status }) => {
        const loading = status !== "complete";
        const parsed = parseJsonResult<D20Result>(result);
        const value =
          typeof parsed.value === "number"
            ? parsed.value
            : typeof parsed.result === "number"
              ? parsed.result
              : undefined;
        return <D20Card loading={loading} value={value} />;
      },
    },
    [],
  );

  // Wildcard catch-all for anything that doesn't match a per-tool
  // renderer above.
  useDefaultRenderTool(
    {
      render: ({ name, parameters, status, result }) => (
        <CustomCatchallRenderer
          name={name}
          parameters={parameters}
          status={status as CatchallToolStatus}
          result={result}
        />
      ),
    },
    [],
  );

  useSuggestions();

  return (
    <CopilotChat agentId="tool-rendering" className="h-full rounded-2xl" />
  );
}

"""
CrewAI tools wrapping shared showcase implementations.

Provides weather, query data, and schedule meeting tools for the crew.
"""

import json

from crewai.tools import BaseTool
from typing import Type
from pydantic import BaseModel, Field

from tools import (
    RENDER_A2UI_TOOL_SCHEMA,
    get_weather_impl,
    query_data_impl,
    schedule_meeting_impl,
    search_flights_impl,
    build_a2ui_operations_from_tool_call,
)
from typing import Any, List, Optional


class GetWeatherInput(BaseModel):
    """Input schema for GetWeatherTool."""

    location: str = Field(..., description="The location to get weather for.")


class GetWeatherTool(BaseTool):
    name: str = "get_weather"
    description: str = (
        "Get current weather for a location. Ensure location is fully spelled out."
    )
    args_schema: Type[BaseModel] = GetWeatherInput

    def _run(self, location: str) -> str:
        return json.dumps(get_weather_impl(location))




class QueryDataInput(BaseModel):
    """Input schema for QueryDataTool."""

    query: str = Field(
        ..., description="The query to run against the financial database."
    )


class QueryDataTool(BaseTool):
    name: str = "query_data"
    description: str = "Query financial database for chart data. Returns data suitable for pie or bar charts."
    args_schema: Type[BaseModel] = QueryDataInput

    def _run(self, query: str) -> str:
        return json.dumps(query_data_impl(query))


class ScheduleMeetingInput(BaseModel):
    """Input schema for ScheduleMeetingTool."""

    reason: str = Field(..., description="Reason for scheduling the meeting.")
    duration_minutes: int = Field(30, description="Duration of the meeting in minutes.")


class ScheduleMeetingTool(BaseTool):
    name: str = "schedule_meeting"
    description: str = (
        "Schedule a meeting with user approval. Returns available time slots."
    )
    args_schema: Type[BaseModel] = ScheduleMeetingInput

    def _run(self, reason: str, duration_minutes: int = 30) -> str:
        return json.dumps(schedule_meeting_impl(reason, duration_minutes))


class SearchFlightsInput(BaseModel):
    """Input schema for SearchFlightsTool."""

    flights: Optional[List[dict]] = Field(
        None,
        description=(
            "Optional route hints from an existing fixture. The mock search "
            "returns the showcase's canonical United and Delta results."
        ),
    )
    origin: str = Field("SFO", description="Origin airport code.")
    destination: str = Field("JFK", description="Destination airport code.")


class SearchFlightsTool(BaseTool):
    name: str = "search_flights"
    description: str = (
        "Search mock flights and display exactly two canonical rich cards: "
        "United at $349 and Delta at $289. Supply only origin and destination."
    )
    args_schema: Type[BaseModel] = SearchFlightsInput

    def _run(
        self,
        flights: Optional[list] = None,
        origin: str = "SFO",
        destination: str = "JFK",
    ) -> str:
        if flights:
            origin = str(flights[0].get("origin") or origin)
            destination = str(flights[0].get("destination") or destination)
        canonical_flights = [
            {
                "airline": "United",
                "airlineLogo": "https://www.google.com/s2/favicons?domain=united.com&sz=128",
                "flightNumber": "UA231",
                "origin": origin,
                "destination": destination,
                "date": "Tue, Aug 18",
                "departureTime": "08:00",
                "arrivalTime": "16:30",
                "duration": "5h 30m",
                "status": "On Time",
                "statusColor": "#22c55e",
                "price": "$349",
                "currency": "USD",
            },
            {
                "airline": "Delta",
                "airlineLogo": "https://www.google.com/s2/favicons?domain=delta.com&sz=128",
                "flightNumber": "DL412",
                "origin": origin,
                "destination": destination,
                "date": "Tue, Aug 18",
                "departureTime": "11:20",
                "arrivalTime": "19:55",
                "duration": "5h 35m",
                "status": "On Time",
                "statusColor": "#22c55e",
                "price": "$289",
                "currency": "USD",
            },
        ]
        result = search_flights_impl(canonical_flights)
        return json.dumps(result)


class GenerateA2uiInput(BaseModel):
    """Input schema for GenerateA2uiTool."""

    context: str = Field(..., description="Conversation context to generate UI for.")


def _generate_a2ui_completion_params(context: str) -> dict[str, Any]:
    return {
        "model": "gpt-5.4",
        "messages": [
            {
                "role": "system",
                "content": context or "Generate a useful dashboard UI.",
            },
            {
                "role": "user",
                "content": "Generate a dynamic A2UI dashboard based on the conversation.",
            },
        ],
        "tools": [{"type": "function", "function": RENDER_A2UI_TOOL_SCHEMA}],
        "tool_choice": {"type": "function", "function": {"name": "render_a2ui"}},
    }


def _generate_a2ui_result(response: Any) -> str:
    if not response.choices[0].message.tool_calls:
        return json.dumps({"error": "LLM did not call render_a2ui"})

    tool_call = response.choices[0].message.tool_calls[0]
    args = json.loads(tool_call.function.arguments)
    result = build_a2ui_operations_from_tool_call(args)
    return json.dumps(result)


class GenerateA2uiTool(BaseTool):
    name: str = "generate_a2ui"
    description: str = (
        "Generate dynamic A2UI components based on the conversation. "
        "A secondary LLM designs the UI schema and data."
    )
    args_schema: Type[BaseModel] = GenerateA2uiInput

    def _run(self, context: str) -> str:
        from openai import OpenAI

        client = OpenAI()
        response = client.chat.completions.create(
            **_generate_a2ui_completion_params(context)
        )
        return _generate_a2ui_result(response)

    async def _arun(self, context: str) -> str:
        from openai import AsyncOpenAI

        async with AsyncOpenAI() as client:
            response = await client.chat.completions.create(
                **_generate_a2ui_completion_params(context)
            )
        return _generate_a2ui_result(response)

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";

// The agent backend runs as a separate process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

function createAgent(path = "/chat") {
  return new HttpAgent({ url: `${AGENT_URL}${path}` });
}

// Cells that only need a plain assistant share the neutral chat Flow on
// `/chat` (src/agents/chat_flow.py). We register many agent names here so
// individual demo pages can scope their per-cell frontend tool / component
// registrations independently; the names below with no explicit override all
// resolve to that Flow. See ../../../../PARITY_NOTES.md (integration root).
//
// The default deliberately is NOT a CrewAI crew endpoint. A crew endpoint
// composes its system message with CrewAI's `build_system_message`, whose
// unconditional boilerplate makes the assistant introduce itself and steer
// every answer back to the crew's purpose.
const agentNames = [
  // Existing base demos
  "agentic_chat",
  "human_in_the_loop",
  "tool-rendering",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-write",
  "shared-state-streaming",
  "shared-state-read-write",
  "subagents",
  // Newly ported in parity PR — chrome / headless
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "headless-complete",
  // Frontend tools / context
  "frontend_tools",
  "frontend-tools-async",
  "readonly-state-agent-context",
  "agent-config",
  // Tool rendering variants
  "tool-rendering-default-catchall",
  "tool-rendering-reasoning-chain",
  // HITL
  "hitl-in-chat",
  "hitl-in-app",
  // Open-ended generative UI
  "open-gen-ui",
  "open-gen-ui-advanced",
];

// Reasoning variants share a native CrewAI Flow. The CrewAI bridge translates
// the reasoning-model stream into AG-UI reasoning and text lifecycles.
const reasoningAgentNames = [
  "reasoning-default",
  "reasoning-custom",
  "reasoning-default-render",
  "agentic-chat-reasoning",
];

const agents: Record<string, AbstractAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent();
}

// CrewAI Flows own the state, tool-result, and delegation lifecycles for
// these cells. Keep every alias explicit: silently falling back to the root
// chat endpoint makes the UI appear connected while dropping the specialized
// AG-UI events that each demo exists to prove.
agents["shared-state-read"] = createAgent("/shared-state-read");
agents["shared-state-write"] = createAgent("/shared-state-read-write");
agents["shared-state-streaming"] = createAgent("/shared-state-streaming");
agents["shared-state-read-write"] = createAgent("/shared-state-read-write");
agents["subagents"] = createAgent("/subagents");
agents["tool-rendering"] = createAgent("/tool-rendering");
agents["tool-rendering-default-catchall"] = createAgent("/tool-rendering");
agents["tool-rendering-custom-catchall"] = createAgent("/tool-rendering");
agents["tool-rendering-reasoning-chain"] = createAgent(
  "/tool-rendering-reasoning",
);
agents["frontend_tools"] = createAgent("/frontend-tools");
agents["frontend-tools-async"] = createAgent("/frontend-tools");
agents["human_in_the_loop"] = createAgent("/frontend-tools");
agents["hitl-in-chat"] = createAgent("/frontend-tools");
agents["hitl-in-app"] = createAgent("/frontend-tools");
agents["headless-complete"] = createAgent("/tool-rendering");
agents["open-gen-ui"] = createAgent("/frontend-tools");
agents["open-gen-ui-advanced"] = createAgent("/frontend-tools");
for (const name of reasoningAgentNames) {
  agents[name] = createAgent("/reasoning");
}
// Interrupt-adapted demos route to the dedicated scheduling Flow backend.
// Both gen-ui-interrupt and interrupt-headless share the same Flow; only the
// frontend UX differs (inline in chat vs. external popup).
agents["gen-ui-interrupt"] = createAgent("/interrupt");
agents["interrupt-headless"] = createAgent("/interrupt");
// gen-ui-agent routes to a dedicated CrewAI Flow backend that owns the
// `set_steps` tool + per-call STATE_SNAPSHOT emit (see
// src/agents/gen_ui_agent.py). A crew endpoint cannot host this demo
// because ChatWithCrewFlow does not surface per-tool state mutations to
// the AG-UI bridge — same architectural reason as
// shared-state-read-write and subagents.
agents["gen-ui-agent"] = createAgent("/gen-ui-agent");
// gen-ui-tool-based has its own Flow (src/agents/gen_ui_tool_based.py) for
// the same reason langgraph-python gives it a dedicated graph: it must force
// a `render_*` chart call on the user turn, which the neutral chat Flow does
// not do.
agents["gen-ui-tool-based"] = createAgent("/gen-ui-tool-based");
// tool-rendering-custom-catchall routes to a dedicated CrewAI Flow
// backend (`/tool-rendering`, src/agents/tool_rendering.py) that emits
// AG-UI TOOL_CALL_* events for `get_weather` / `get_stock_price`.
// `ChatWithCrewFlow` runs backend tools internally without emitting
// tool-call events, so the frontend's custom wildcard renderer
// (`useDefaultRenderTool`) would never paint the
// `[data-testid="custom-wildcard-card"]` shell that the
// `d5-tool-rendering-custom-catchall` probe asserts on.
agents["default"] = createAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- Published CopilotRuntime agents type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in source, pending release
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    // Log full details server-side (operators grep `errorId` to correlate),
    // but never echo `err.message` / `err.stack` back to the HTTP client —
    // that leaks internal paths, dependency versions, and stack traces.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = crypto.randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        scope: "copilotkit/route",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

