            <Badge variant="muted">useAgentContext</Badge>
          </div>
          <h1 className="text-4xl font-semibold tracking-tight text-neutral-900">
            Agent Context Inspector
          </h1>
          <p className="mt-3 max-w-2xl text-base text-neutral-600">
