// Neutral, slightly muted hues that pair with `bg-card` / `--border`
// (zinc/slate-leaning, akin to ShadCN's chart-{1..5} palette).
const CHART_COLORS = [
  "#3F3F46", // zinc-700
  "#71717A", // zinc-500
  "#A1A1AA", // zinc-400
  "#18181B", // zinc-900
  "#52525B", // zinc-600
  "#D4D4D8", // zinc-300
  "#27272A", // zinc-800
] as const;

