"use client";

/**
 * Headless UI: Complete — full headless surface in one demo.
 *
 * Mirror of `headless-simple` plus, layered in via focused hook modules,
 * every render surface CopilotKit exposes:
 *
 *   useToolRenderers       — useRenderTool (weather, stock) + useDefaultRenderTool
 *   useFrontendComponents  — useComponent (highlight_note frontend tool)
 *   useHeadlessSuggestions — useConfigureSuggestions (4 prompts)
 *   useAttachmentsConfig   — useAttachments (image + PDF, base64 inline)
 *
 * Plus, inside the chat shell:
 *
 *   useAgent / useCopilotKit          — read messages, dispatch runs
 *   useRenderToolCall                 — render tool-call cards inline
 *   useRenderActivityMessage          — MCP Apps activity (Excalidraw iframe)
 *   useSuggestions                    — render the configured suggestions
 *
 * The hook calls in `<HeadlessCompleteRoot />` form the demo's entire
 * surface, so a reader can see every capability at a glance before
 * diving into the chat UI.
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";
import { Chat } from "./chat/chat";
import { useFrontendComponents } from "./hooks/use-frontend-components";
import { useHeadlessSuggestions } from "./hooks/use-headless-suggestions";
import { useToolRenderers } from "./hooks/use-tool-renderers";

const AGENT_ID = "headless-complete";

export default function HeadlessCompleteDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit-mcp-apps" agent={AGENT_ID}>
      <HeadlessCompleteRoot />
    </CopilotKit>
  );
}

function HeadlessCompleteRoot() {
  useToolRenderers();
  useFrontendComponents();
  useHeadlessSuggestions();

  return <Chat agentId={AGENT_ID} />;
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";
import { extractForwardedHeaders } from "@/lib/header-forwarding";

// The agent backend runs as a separate process on port 8000.
// agent_server.py mounts ONE ADKAgent middleware per demo at /<agent_name>;
// this runtime maps each agent name to its dedicated backend path.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Each agent NAME corresponds to a path mounted by the Python backend
// (see src/agents/registry.py AGENT_REGISTRY). Names with dashes preserved
// for backwards-compat with already-shipped demos (gen-ui-agent etc.).
const agentNames = [
  // existing demos
  "agentic_chat",
  "tool-rendering",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-read-write",
  "shared-state-streaming",
  "subagents",
  // frontend-only demos (share simple chat agent on the backend)
  "frontend_tools",
  "threadid-frontend-tool-roundtrip",
  "frontend-tools-async",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "headless_complete",
  "voice",
  // reasoning
  "reasoning-custom",
  "reasoning-default",
  // tool-rendering variants
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "tool-rendering-reasoning-chain",
  // hitl variants
  "hitl-in-chat",
  "hitl-in-app",
  "human_in_the_loop",
  // gen-ui-interrupt: Strategy-B scheduling flow (schedule_meeting frontend
  // tool via useHumanInTheLoop). Page binds agentId="gen-ui-interrupt".
  "gen-ui-interrupt",
  // multimodal & state-context
  "multimodal",
  "readonly-state-agent-context",
  "agent_config",
  // a2ui
  "declarative_gen_ui",
  "a2ui_fixed_schema",
  // byoc / declarative
  "declarative-hashbrown",
  "byoc_json_render",
  // open gen ui
  "open_gen_ui",
  "open_gen_ui_advanced",
  // beautiful chat
  "beautiful_chat",
  // auth
  "auth",
  // mcp apps (also wired via separate runtime route copilotkit-mcp-apps)
  "mcp-apps",
  // Neutral default agent. The hitl demo's `useInterrupt` hook binds to
  // the default agent (no agentId), so a `default` slot must exist or the
  // page throws `useAgent: Agent 'default' not found`. Mirrors
  // langgraph-python's `agents["default"]`.
  "default",
];

// Build agents per-request so we can inject inbound x-* headers (e.g.
// x-aimock-context) into the outbound HTTP call to the Python agent_server.
// HttpAgent's `requestInit` spreads `this.headers` into the outbound fetch,
// so populating `headers` from `req.headers` before `copilotHandler` runs
// is sufficient to convey the header to the Python backend, where
// HeaderForwardingHTTPMiddleware then propagates it to Gemini via the
// httpx/aiohttp event hooks installed at import time. See
// `src/lib/header-forwarding.ts` for the shared helper.
function buildAgents(
  headers: Record<string, string>,
): Record<string, AbstractAgent> {
  const agents: Record<string, AbstractAgent> = {};
  for (const name of agentNames) {
    agents[name] = new HttpAgent({ url: `${AGENT_URL}/${name}`, headers });
  }
  return agents;
}

// Module-load cache used only for the agent_count health probe — never
// receives request headers, so it is not used for actual POST traffic.
const healthProbeAgents = buildAgents({});

export const POST = async (req: NextRequest) => {
  try {
    const forwardedHeaders = extractForwardedHeaders(req);
    const agents = buildAgents(forwardedHeaders);

    const runtime = new CopilotRuntime({
      agents,
    });

    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    return await copilotHandler(req);
  } catch (error: unknown) {
    // Log full details server-side (operators grep `errorId` to correlate),
    // but never echo `err.message` / `err.stack` back to the HTTP client —
    // that leaks internal paths, dependency versions, and stack traces.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = crypto.randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        scope: "copilotkit",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    agent_count: Object.keys(healthProbeAgents).length,
    env: {
      GOOGLE_API_KEY: process.env.GOOGLE_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

"use client";

/**
 * Compact chip rendered above the composer for each pending attachment.
 * Shows a thumbnail (image) or icon (document), the filename, and an X
 * button to remove. Doubles as the in-message preview rendered alongside
 * a sent user message in `chat/message-user.tsx`.
 */

import React from "react";
import { File, Loader2, X } from "lucide-react";
import type { Attachment } from "@copilotkit/shared";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export function AttachmentChip({
  attachment,
  onRemove,
}: {
  attachment: Attachment;
  onRemove?: (id: string) => void;
}) {
  const isImage = attachment.type === "image";
  const isUploading = attachment.status === "uploading";
  const src = isImage ? attachmentSrc(attachment) : undefined;

  return (
    <div
      className={cn(
        "group relative inline-flex items-center gap-2 rounded-lg border bg-card px-2 py-1.5 text-xs shadow-sm",
        onRemove ? "pr-7" : "pr-2",
      )}
    >
      <div className="flex h-7 w-7 shrink-0 items-center justify-center overflow-hidden rounded-md bg-muted text-muted-foreground">
        {isUploading ? (
          <Loader2 className="h-4 w-4 animate-spin" />
        ) : isImage && src ? (
          <img
            src={src}
            alt={attachment.filename ?? "attachment"}
            className="h-full w-full object-cover"
          />
        ) : (
          <File className="h-4 w-4" />
        )}
      </div>
      <div className="flex min-w-0 flex-col leading-tight">
        <span className="max-w-[180px] truncate font-medium text-foreground">
          {attachment.filename ?? "attachment"}
        </span>
        <span className="text-[10px] text-muted-foreground">
          {isUploading ? "uploading…" : prettyBytes(attachment.size)}
        </span>
      </div>
      {onRemove && (
        <Button
          type="button"
          size="icon"
          variant="ghost"
          aria-label="Remove attachment"
          onClick={() => onRemove(attachment.id)}
          className="absolute right-0.5 top-1/2 h-5 w-5 -translate-y-1/2"
        >
          <X className="h-3 w-3" />
        </Button>
      )}
    </div>
  );
}

function attachmentSrc(att: Attachment): string | undefined {
  const src = att.source;
  if (src.type === "url") return src.value;
  if (src.type === "data") {
    return `data:${src.mimeType};base64,${src.value}`;
  }
  return undefined;
}

function prettyBytes(size?: number): string {
  if (!size) return "";
  if (size < 1024) return `${size}B`;
  if (size < 1024 * 1024) return `${(size / 1024).toFixed(1)}KB`;
  return `${(size / (1024 * 1024)).toFixed(1)}MB`;
}

"use client";

/**
 * Configures `useAttachments` for the headless-complete demo. Inlines
 * uploads as base64 (no external storage), accepts images and PDFs, and
 * caps each file at 20MB.
 *
 * The hook returns the full attachment pipeline: `fileInputRef` for the
 * hidden `<input type="file">`, `containerRef` for paste support,
 * drag/drop handlers, the live attachment list, plus `consumeAttachments`
 * which is called at submit time and clears the queue.
 */

import { useCallback } from "react";
import {
  useAttachments,
  type UseAttachmentsReturn,
} from "@copilotkit/react-core/v2";
import type { AttachmentUploadResult } from "@copilotkit/shared";

const MAX_FILE_SIZE_BYTES = 20 * 1024 * 1024;
const ACCEPT_MIME = "image/*,application/pdf";

export function useAttachmentsConfig(): UseAttachmentsReturn {
  const onUpload = useCallback(fileToBase64, []);

  return useAttachments({
    config: {
      enabled: true,
      accept: ACCEPT_MIME,
      maxSize: MAX_FILE_SIZE_BYTES,
      onUpload,
      onUploadFailed: (err) => {
        console.warn("[headless-complete] attachment rejected", err);
      },
    },
  });
}

function fileToBase64(file: File): Promise<AttachmentUploadResult> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () =>
      reject(reader.error ?? new Error(`FileReader failed for ${file.name}`));
    reader.onload = () => {
      const result = reader.result;
      if (typeof result !== "string") {
        reject(new Error(`Unexpected FileReader result for ${file.name}`));
        return;
      }
      const commaIdx = result.indexOf(",");
      const base64 = commaIdx >= 0 ? result.slice(commaIdx + 1) : result;
      resolve({
        type: "data",
        value: base64,
        mimeType: file.type || "application/octet-stream",
        metadata: { filename: file.name, size: file.size },
      });
    };
    reader.readAsDataURL(file);
  });
}

"use client";

/**
 * Hand-rolled chat shell.
 *
 * Owns the read/write loop:
 * - `useAgent`        — message list, isRunning, addMessage, abortRun, setMessages
 * - `useCopilotKit`   — `runAgent({ agent })` to dispatch a turn
 *
 * Renders the message tree via `<MessageList />` (which uses
 * `useRenderToolCall` and `useRenderActivityMessage` internally), shows
 * a typing indicator while the agent is thinking, and composes the
 * suggestion bar + composer (with attachments) at the bottom.
 *
 * The visual chrome is identical to `headless-simple/chat.tsx` — same
 * outer wrapper, same `Card` shell, same bubble palette — so the two
 * demos read as a pair.
 */

import React, { useCallback, useState } from "react";
import { useAgent, useCopilotKit } from "@copilotkit/react-core/v2";
import type { Attachment, InputContent } from "@copilotkit/shared";
import { Card, CardContent } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";
import { useAttachmentsConfig } from "../attachments/use-attachments-config";
import { useAutoScroll } from "../hooks/use-auto-scroll";
import { useTypingIndicator } from "../hooks/use-typing-indicator";
import { Composer } from "./composer";
import { EmptyState } from "./empty-state";
import { Header } from "./header";
import { MessageList } from "./message-list";
import { SuggestionBar } from "./suggestion-bar";
import { TypingIndicator } from "./typing-indicator";

export function Chat({ agentId }: { agentId: string }) {
  const { agent } = useAgent({ agentId });
  const { copilotkit } = useCopilotKit();

  const {
    attachments,
    fileInputRef,
    containerRef,
    handleFileUpload,
    handleDragOver,
    handleDragLeave,
    handleDrop,
    dragOver,
    removeAttachment,
    consumeAttachments,
  } = useAttachmentsConfig();

  const [input, setInput] = useState("");
  const messages = agent.messages;
  const { listRef, bottomRef, stickRef } = useAutoScroll(
    messages,
    agent.isRunning,
  );

  // Send pipeline: consume any ready attachments at submit time, build
  // the multimodal `content` array if needed, then dispatch the run.
  const sendText = useCallback(
    (text: string) => {
      const trimmed = text.trim();
      // Consume queued uploads first so they get sent even if the user
      // didn't type any text alongside them.
      const ready = consumeAttachments();
      if (!trimmed && ready.length === 0) return;
      if (agent.isRunning) return;

      stickRef.current = true;

      const content = buildContent(trimmed, ready);
      agent.addMessage({
        id: crypto.randomUUID(),
        role: "user",
        content,
      });
      void copilotkit
        .runAgent({ agent })
        .catch((err) =>
          console.error("[headless-complete] runAgent failed", err),
        );
    },
    [agent, copilotkit, consumeAttachments],
  );

  const handleSend = useCallback(() => {
    sendText(input);
    setInput("");
  }, [input, sendText]);

  const handleSuggestion = useCallback(
    (text: string) => {
      sendText(text);
    },
    [sendText],
  );

  const handleReset = useCallback(() => {
    if (agent.isRunning) {
      try {
        agent.abortRun();
      } catch {
        // no-op: some transports don't support abort
      }
    }
    agent.setMessages([]);
    setInput("");
    stickRef.current = true;
  }, [agent]);

  const showTypingIndicator = useTypingIndicator(messages, agent.isRunning);

  const hasUploadingAttachment = attachments.some(
    (a) => a.status === "uploading",
  );
  const hasReadyAttachment = attachments.some((a) => a.status === "ready");
  const sendDisabled =
    agent.isRunning ||
    hasUploadingAttachment ||
    (!input.trim() && !hasReadyAttachment);
  const canReset = messages.length > 0 || agent.isRunning;
  const hasMessages = messages.length > 0;

  return (
    <div className="flex h-screen w-full justify-center bg-background p-4 sm:p-6">
      <Card className="flex h-full w-full max-w-3xl flex-col gap-0 overflow-hidden border-border py-0 shadow-2xl shadow-black/10">
        <Header onReset={handleReset} canReset={canReset} />

        <CardContent className="flex min-h-0 flex-1 flex-col p-0">
          {!hasMessages ? (
            // Render empty state outside the ScrollArea so flex-1 + justify-
            // center actually fills the available height. Radix ScrollArea
            // wraps its content in a `display: table` div that breaks
            // `h-full` propagation, so a centered empty state inside it
            // hugs the top of the viewport.
            <div className="flex min-h-0 flex-1 flex-col">
              <EmptyState onPick={handleSuggestion} />
            </div>
          ) : (
            <ScrollArea className="min-h-0 flex-1">
              <div
                ref={listRef}
                className={cn("flex flex-col gap-4 px-4 py-4 sm:px-6")}
              >
                <MessageList messages={messages} />
                {showTypingIndicator && <TypingIndicator />}
                <div ref={bottomRef} />
              </div>
            </ScrollArea>
          )}

          {hasMessages && (
            <SuggestionBar
              agentId={agentId}
              isRunning={agent.isRunning}
              onPick={handleSuggestion}
            />
          )}

          <Separator className="bg-border/60" />

          <Composer
            value={input}
            onChange={setInput}
            onSend={handleSend}
            disabled={sendDisabled}
            isRunning={agent.isRunning}
            attachments={attachments}
            onRemoveAttachment={removeAttachment}
            onFileChange={handleFileUpload}
            fileInputRef={fileInputRef}
            containerRef={containerRef}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            dragOver={dragOver}
          />
        </CardContent>
      </Card>
    </div>
  );
}

// Build the user message body. If no attachments, send a plain string
// (legacy shape). If attachments are present, send the multimodal array
// — text first, then each attachment as its own InputContent part.
function buildContent(
  text: string,
  attachments: Attachment[],
): string | InputContent[] {
  if (attachments.length === 0) return text;
  const parts: InputContent[] = [];
  if (text) parts.push({ type: "text", text });
  for (const att of attachments) {
    parts.push({
      type: att.type,
      source: att.source,
      metadata: {
        ...(att.filename ? { filename: att.filename } : {}),
        ...att.metadata,
      },
    } as InputContent);
  }
  return parts;
}

"use client";

/**
 * Bottom-of-chat composer with attachments support.
 *
 * Layout:
 *   [paperclip icon] [textarea] [send icon]
 * with a chip row above the textarea showing pending attachments. The
 * paperclip triggers the hidden `<input type="file">` exposed by
 * `useAttachments`. Drag/drop handlers are attached to the outer
 * container via the same hook so users can drop a file anywhere on the
 * composer surface.
 */

import React, { useEffect, useRef } from "react";
import { ArrowUp, Paperclip } from "lucide-react";
import type { Attachment } from "@copilotkit/shared";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { AttachmentChip } from "../attachments/attachment-preview";

export interface ComposerProps {
  value: string;
  onChange: (next: string) => void;
  onSend: () => void;
  disabled: boolean;
  isRunning: boolean;
  // Attachments — passthrough from `useAttachments`.
  attachments: Attachment[];
  onRemoveAttachment: (id: string) => void;
  onFileChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  fileInputRef: React.RefObject<HTMLInputElement | null>;
  containerRef: React.RefObject<HTMLDivElement | null>;
  onDragOver: (e: React.DragEvent) => void;
  onDragLeave: (e: React.DragEvent) => void;
  onDrop: (e: React.DragEvent) => void;
  dragOver: boolean;
}

export function Composer({
  value,
  onChange,
  onSend,
  disabled,
  isRunning,
  attachments,
  onRemoveAttachment,
  onFileChange,
  fileInputRef,
  containerRef,
  onDragOver,
  onDragLeave,
  onDrop,
  dragOver,
}: ComposerProps) {
  const ref = useRef<HTMLTextAreaElement | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 160)}px`;
  }, [value]);

  return (
    <div
      ref={containerRef}
      data-testid="headless-composer"
      onDragOver={onDragOver}
      onDragLeave={onDragLeave}
      onDrop={onDrop}
      className="bg-background p-3 sm:p-4"
    >
      <div
        className={cn(
          "flex flex-col gap-2 rounded-2xl border border-border/60 bg-muted/50 p-2",
          "focus-within:bg-background focus-within:ring-2 focus-within:ring-ring/40",
          "transition-colors",
          dragOver && "ring-2 ring-primary/60",
        )}
      >
        {attachments.length > 0 && (
          <div className="flex flex-wrap gap-2 px-1 pt-1">
            {attachments.map((a) => (
              <AttachmentChip
                key={a.id}
                attachment={a}
                onRemove={onRemoveAttachment}
              />
            ))}
          </div>
        )}
        <div className="flex items-end gap-2">
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*,application/pdf"
            multiple
            className="hidden"
            onChange={onFileChange}
          />
          <Button
            type="button"
            size="icon"
            variant="ghost"
            aria-label="Attach file"
            onClick={() => fileInputRef.current?.click()}
            className="h-9 w-9 shrink-0 rounded-xl"
            disabled={isRunning}
          >
            <Paperclip className="h-4 w-4" />
          </Button>
          <Textarea
            ref={ref}
            rows={1}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                if (!disabled) onSend();
              }
            }}
            placeholder={
              isRunning
                ? "Agent is responding..."
                : "Message the agent or drop a file..."
            }
            className={cn(
              "min-h-[40px] max-h-40 flex-1 resize-none border-0 bg-transparent",
              "px-2 py-2 text-sm shadow-none",
              "focus-visible:ring-0 focus-visible:border-transparent",
            )}
          />
          <Button
            type="button"
            size="icon"
            onClick={onSend}
            disabled={disabled}
            aria-label="Send message"
            className="h-9 w-9 shrink-0 rounded-xl"
          >
            <ArrowUp className="h-4 w-4" />
          </Button>
        </div>
      </div>
      <p className="mt-2 px-1 text-center text-[11px] text-muted-foreground">
        Press{" "}
        <kbd className="rounded border bg-muted px-1 py-0.5 font-mono text-[10px]">
          Enter
        </kbd>{" "}
        to send,{" "}
        <kbd className="rounded border bg-muted px-1 py-0.5 font-mono text-[10px]">
          Shift+Enter
        </kbd>{" "}
        for a newline
      </p>
    </div>
  );
}

