"use client";

/**
 * Agent Config Object — typed config knobs (tone / expertise / responseLength)
 * forwarded from the provider into the agent so its behavior changes per turn.
 *
 * Wiring: the toggles live in `useAgentConfig`. Each render the resolved
 * config is published to the agent via `useAgentContext` — the v2 idiom
 * for "frontend → agent runtime context". The Python agent picks it up
 * through a before-model callback that reads
 * `state["copilotkit"]["context"]` and injects a derived directive block
 * into the model's system instruction before each call.
 */

import { CopilotKit } from "@copilotkit/react-core/v2";

import { DemoLayout } from "./demo-layout";
import { ConfigContextRelay } from "./config-context-relay";
import { useAgentConfig } from "./use-agent-config";

export default function AgentConfigDemoPage() {
  const { config, setTone, setExpertise, setResponseLength } = useAgentConfig();

  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-agent-config"
      agent="agent-config-demo"
    >
      <ConfigContextRelay config={config} />
      <DemoLayout
        config={config}
        onToneChange={setTone}
        onExpertiseChange={setExpertise}
        onResponseLengthChange={setResponseLength}
      />
    </CopilotKit>
  );
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";
import { extractForwardedHeaders } from "@/lib/header-forwarding";

// The agent backend runs as a separate process on port 8000.
// agent_server.py mounts ONE ADKAgent middleware per demo at /<agent_name>;
// this runtime maps each agent name to its dedicated backend path.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Each agent NAME corresponds to a path mounted by the Python backend
// (see src/agents/registry.py AGENT_REGISTRY). Names with dashes preserved
// for backwards-compat with already-shipped demos (gen-ui-agent etc.).
const agentNames = [
  // existing demos
  "agentic_chat",
  "tool-rendering",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-read-write",
  "shared-state-streaming",
  "subagents",
  // frontend-only demos (share simple chat agent on the backend)
  "frontend_tools",
  "threadid-frontend-tool-roundtrip",
  "frontend-tools-async",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "headless_complete",
  "voice",
  // reasoning
  "reasoning-custom",
  "reasoning-default",
  // tool-rendering variants
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "tool-rendering-reasoning-chain",
  // hitl variants
  "hitl-in-chat",
  "hitl-in-app",
  "human_in_the_loop",
  // gen-ui-interrupt: Strategy-B scheduling flow (schedule_meeting frontend
  // tool via useHumanInTheLoop). Page binds agentId="gen-ui-interrupt".
  "gen-ui-interrupt",
  // multimodal & state-context
  "multimodal",
  "readonly-state-agent-context",
  "agent_config",
  // a2ui
  "declarative_gen_ui",
  "a2ui_fixed_schema",
  // byoc / declarative
  "declarative-hashbrown",
  "byoc_json_render",
  // open gen ui
  "open_gen_ui",
  "open_gen_ui_advanced",
  // beautiful chat
  "beautiful_chat",
  // auth
  "auth",
  // mcp apps (also wired via separate runtime route copilotkit-mcp-apps)
  "mcp-apps",
  // Neutral default agent. The hitl demo's `useInterrupt` hook binds to
  // the default agent (no agentId), so a `default` slot must exist or the
  // page throws `useAgent: Agent 'default' not found`. Mirrors
  // langgraph-python's `agents["default"]`.
  "default",
];

// Build agents per-request so we can inject inbound x-* headers (e.g.
// x-aimock-context) into the outbound HTTP call to the Python agent_server.
// HttpAgent's `requestInit` spreads `this.headers` into the outbound fetch,
// so populating `headers` from `req.headers` before `copilotHandler` runs
// is sufficient to convey the header to the Python backend, where
// HeaderForwardingHTTPMiddleware then propagates it to Gemini via the
// httpx/aiohttp event hooks installed at import time. See
// `src/lib/header-forwarding.ts` for the shared helper.
function buildAgents(
  headers: Record<string, string>,
): Record<string, AbstractAgent> {
  const agents: Record<string, AbstractAgent> = {};
  for (const name of agentNames) {
    agents[name] = new HttpAgent({ url: `${AGENT_URL}/${name}`, headers });
  }
  return agents;
}

// Module-load cache used only for the agent_count health probe — never
// receives request headers, so it is not used for actual POST traffic.
const healthProbeAgents = buildAgents({});

export const POST = async (req: NextRequest) => {
  try {
    const forwardedHeaders = extractForwardedHeaders(req);
    const agents = buildAgents(forwardedHeaders);

    const runtime = new CopilotRuntime({
      agents,
    });

    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    return await copilotHandler(req);
  } catch (error: unknown) {
    // Log full details server-side (operators grep `errorId` to correlate),
    // but never echo `err.message` / `err.stack` back to the HTTP client —
    // that leaks internal paths, dependency versions, and stack traces.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = crypto.randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        scope: "copilotkit",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    agent_count: Object.keys(healthProbeAgents).length,
    env: {
      GOOGLE_API_KEY: process.env.GOOGLE_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

"use client";

import type { ChangeEvent } from "react";
import {
  type AgentConfig,
  EXPERTISE_OPTIONS,
  type Expertise,
  RESPONSE_LENGTH_OPTIONS,
  type ResponseLength,
  TONE_OPTIONS,
  type Tone,
} from "./config-types";

interface ConfigCardProps {
  config: AgentConfig;
  onToneChange: (tone: Tone) => void;
  onExpertiseChange: (expertise: Expertise) => void;
  onResponseLengthChange: (length: ResponseLength) => void;
}

export function ConfigCard({
  config,
  onToneChange,
  onExpertiseChange,
  onResponseLengthChange,
}: ConfigCardProps) {
  return (
    <div
      data-testid="agent-config-card"
      className="flex flex-col gap-2 rounded-md border border-[var(--border)] bg-[var(--bg-surface)] p-4 text-sm"
    >
      <h2 className="text-sm font-semibold">Agent Config</h2>
      <p className="text-xs text-[var(--text-muted)]">
        Change these and send a message to see the agent adapt.
      </p>
      <div className="flex flex-wrap gap-3">
        <label className="flex flex-col gap-1">
          <span className="text-xs font-medium">Tone</span>
          <select
            data-testid="agent-config-tone-select"
            value={config.tone}
            onChange={(e: ChangeEvent<HTMLSelectElement>) =>
              onToneChange(e.target.value as Tone)
            }
            className="rounded border border-[var(--border)] bg-[var(--bg-muted)] px-2 py-1 text-sm"
          >
            {TONE_OPTIONS.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>
        </label>
        <label className="flex flex-col gap-1">
          <span className="text-xs font-medium">Expertise</span>
          <select
            data-testid="agent-config-expertise-select"
            value={config.expertise}
            onChange={(e: ChangeEvent<HTMLSelectElement>) =>
              onExpertiseChange(e.target.value as Expertise)
            }
            className="rounded border border-[var(--border)] bg-[var(--bg-muted)] px-2 py-1 text-sm"
          >
            {EXPERTISE_OPTIONS.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>
        </label>
        <label className="flex flex-col gap-1">
          <span className="text-xs font-medium">Response length</span>
          <select
            data-testid="agent-config-length-select"
            value={config.responseLength}
            onChange={(e: ChangeEvent<HTMLSelectElement>) =>
              onResponseLengthChange(e.target.value as ResponseLength)
            }
            className="rounded border border-[var(--border)] bg-[var(--bg-muted)] px-2 py-1 text-sm"
          >
            {RESPONSE_LENGTH_OPTIONS.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>
        </label>
      </div>
    </div>
  );
}

"use client";

/**
 * Publishes the current agent-config toggles to the agent runtime via
 * `useAgentContext`. Lives inside the `<CopilotKit>` provider so the
 * context store is reachable. The before-model callback on the Python
 * side reads this entry off `state["copilotkit"]["context"]` on every
 * turn and routes it into the model's prompt.
 */

import { useAgentContext } from "@copilotkit/react-core/v2";
import type { AgentConfig } from "./config-types";

export function ConfigContextRelay({ config }: { config: AgentConfig }) {
  useAgentContext({
    description:
      "Agent response preferences. Apply tone, expertise level, and response length to every reply.",
    value: {
      tone: config.tone,
      expertise: config.expertise,
      responseLength: config.responseLength,
    },
  });
  return null;
}

export type Tone = "professional" | "casual" | "enthusiastic";
export type Expertise = "beginner" | "intermediate" | "expert";
export type ResponseLength = "concise" | "detailed";

export interface AgentConfig {
  tone: Tone;
  expertise: Expertise;
  responseLength: ResponseLength;
}

export const DEFAULT_AGENT_CONFIG: AgentConfig = {
  tone: "professional",
  expertise: "intermediate",
  responseLength: "concise",
};

export const TONE_OPTIONS: Tone[] = ["professional", "casual", "enthusiastic"];
export const EXPERTISE_OPTIONS: Expertise[] = [
  "beginner",
  "intermediate",
  "expert",
];
export const RESPONSE_LENGTH_OPTIONS: ResponseLength[] = [
  "concise",
  "detailed",
];

"use client";

import React from "react";
import { CopilotChat } from "@copilotkit/react-core/v2";

import { ConfigCard } from "./config-card";
import type { AgentConfig } from "./config-types";

interface DemoLayoutProps {
  config: AgentConfig;
  onToneChange: (tone: AgentConfig["tone"]) => void;
  onExpertiseChange: (expertise: AgentConfig["expertise"]) => void;
  onResponseLengthChange: (length: AgentConfig["responseLength"]) => void;
}

export function DemoLayout({
  config,
  onToneChange,
  onExpertiseChange,
  onResponseLengthChange,
}: DemoLayoutProps) {
  return (
    <div className="flex h-screen flex-col gap-3 p-6">
      <ConfigCard
        config={config}
        onToneChange={onToneChange}
        onExpertiseChange={onExpertiseChange}
        onResponseLengthChange={onResponseLengthChange}
      />
      <div className="flex-1 overflow-hidden rounded-md border border-[var(--border)]">
        <CopilotChat
          agentId="agent-config-demo"
          className="h-full rounded-md"
        />
      </div>
    </div>
  );
}

"use client";

import { useCallback, useState } from "react";
import {
  type AgentConfig,
  DEFAULT_AGENT_CONFIG,
  type Expertise,
  type ResponseLength,
  type Tone,
} from "./config-types";

export interface UseAgentConfigHandle {
  config: AgentConfig;
  setTone: (tone: Tone) => void;
  setExpertise: (expertise: Expertise) => void;
  setResponseLength: (length: ResponseLength) => void;
  reset: () => void;
}

export function useAgentConfig(): UseAgentConfigHandle {
  const [config, setConfig] = useState<AgentConfig>(DEFAULT_AGENT_CONFIG);

  const setTone = useCallback(
    (tone: Tone) => setConfig((prev) => ({ ...prev, tone })),
    [],
  );
  const setExpertise = useCallback(
    (expertise: Expertise) => setConfig((prev) => ({ ...prev, expertise })),
    [],
  );
  const setResponseLength = useCallback(
    (responseLength: ResponseLength) =>
      setConfig((prev) => ({ ...prev, responseLength })),
    [],
  );
  const reset = useCallback(() => setConfig(DEFAULT_AGENT_CONFIG), []);

  return { config, setTone, setExpertise, setResponseLength, reset };
}

"use client";

/**
 * Beautiful Chat — the flagship CopilotKit showcase cell, ported verbatim
 * from the 4084 reference clone. The 4084 version lived as its own Next.js
 * frontend at `demos/beautiful-chat/frontend/` with a full `src/components`
 * tree + A2UI catalog. Here the same tree is colocated under the cell and
 * re-wired with relative imports.
 *
 * Providers: layout-level `CopilotKit` + `ThemeProvider` wrappers from the
 * original 4084 root layout are applied here instead, because the unified
 * 4085 shell does not give each cell its own layout.tsx.
 *
 * Runtime: this cell uses its own dedicated runtime endpoint
 * (`/api/copilotkit-beautiful-chat`) so it can enable `openGenerativeUI`,
 * `a2ui` with `injectA2UITool: true`, and `mcpApps` simultaneously — the
 * same combined-runtime shape the canonical starter uses — without bleeding
 * those global flags into other cells sharing the main `/api/copilotkit`
 * endpoint. The backend graph is `beautiful_chat` (src/agents/beautiful_chat.py).
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";

import { ThemeProvider } from "./hooks/use-theme";
import { demonstrationCatalog } from "./declarative-generative-ui/renderers";
import { HomePage } from "./home-page";

export default function BeautifulChatPage() {
  return (
    <ThemeProvider>
      <CopilotKit
        runtimeUrl="/api/copilotkit-beautiful-chat"
        agent="beautiful-chat"
        a2ui={{ catalog: demonstrationCatalog }}
        openGenerativeUI={{}}
        /*
         * `useSingleEndpoint` defaults to true (the single-POST-endpoint
         * protocol). The canonical reference sets it to false to use the
         * v2 multi-endpoint protocol (GET /info + POST /agent/{name}/connect),
         * which requires a Hono-based endpoint via `createCopilotEndpoint`.
         * The 4085 showcase uses `copilotRuntimeNextJSAppRouterEndpoint`
         * (single-endpoint), which matches the other 4085 cells — so we
         * use its default behavior here. Functionally equivalent for this demo.
         */
      >
        <HomePage />
      </CopilotKit>
    </ThemeProvider>
  );
}

// Dedicated runtime for the Beautiful Chat flagship showcase cell.
//
// The canonical reference (examples/integrations/langgraph-python) enables
// A2UI, Open Generative UI and MCP Apps on a single runtime for this page;
// this route mirrors that combined-runtime config so non-flagship cells keep
// their per-demo `useFrontendTool` / `useComponent` registrations isolated on
// the main `/api/copilotkit` endpoint. On this integration only the A2UI
// fixed-schema flight surface (backend `search_flights`) and MCP Apps are
// verified; dynamic A2UI and Open Generative UI are not (see PARITY_NOTES.md,
// "Beautiful Chat surfaces").
//
// References:
// - showcase/integrations/langgraph-python/src/app/api/copilotkit-beautiful-chat/route.ts
// - src/app/api/copilotkit-mcp-apps/route.ts (mcpApps config pattern, this package)

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";
import { extractForwardedHeaders } from "@/lib/header-forwarding";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

export const POST = async (req: NextRequest) => {
  try {
    // Per-request build so inbound `x-aimock-context` reaches the Python
    // agent_server. See `src/lib/header-forwarding.ts`.
    const headers = extractForwardedHeaders(req);
    const beautifulChatAgent: AbstractAgent = new HttpAgent({
      url: `${AGENT_URL}/beautiful_chat`,
      headers,
    });

    const agents: Record<string, AbstractAgent> = {
      // The page's <CopilotKit agent="beautiful-chat"> resolves here.
      "beautiful-chat": beautifulChatAgent,
      // Internal components (headless-chat, example-canvas) call `useAgent()`
      // with no args, which defaults to agentId "default". Alias to the same
      // agent so those component hooks resolve instead of throwing
      // "Agent 'default' not found". This matches the canonical's
      // `agents: { default: defaultAgent }` shape.
      default: beautifulChatAgent,
    };

    const runtime = new CopilotRuntime({
      agents,
      // Canonical: openGenerativeUI: true, a2ui.injectA2UITool: false, mcpApps.
      openGenerativeUI: true,
      a2ui: {
        // Mirrors the canonical route's config. `injectA2UITool: false` is
        // load-bearing post-CopilotKit#5611, which otherwise defaults
        // injectA2UITool to true when a provider catalog is present — this
        // integration's adapter does not own a `generate_a2ui` tool the way
        // the canonical backend does, so a second, runtime-injected copy
        // would be the only one in play; see PARITY_NOTES.md ("Beautiful Chat
        // surfaces") for the current A2UI support status on this adapter.
        injectA2UITool: false,
        // Models follow the tool-usage guide and omit `catalogId`, and the
        // middleware then falls back to the unregistered spec basic catalog
        // ("Catalog not found" render error). Pin the catalog the page registers.
        defaultCatalogId: "copilotkit://app-dashboard-catalog",
      },
      mcpApps: {
        servers: [
          {
            type: "http",
            url: process.env.MCP_SERVER_URL || "https://mcp.excalidraw.com/mcp",
            // Stable serverId so persisted threads keep restoring the same MCP
            // server across URL changes.
            serverId: "beautiful_chat_mcp",
          },
        ],
      },
    });

    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-beautiful-chat",
      mode: "single-route",
    });

    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

