"use client";

// Auth demo — framework-native request authentication via the V2 runtime's
// `onRequest` hook. The runtime route (/api/copilotkit-auth) rejects any
// request whose `Authorization: Bearer <demo-token>` header is missing or
// wrong.
//
// UX shape: the demo defaults to UNAUTHENTICATED on first paint so visitors
// land on a clear sign-in card. We don't render `<CopilotKit>` until the user
// has signed in at least once — that sidesteps the transport 401 that would
// otherwise crash `<CopilotChat>` during its initial `/info` handshake.
// After the user signs in once, `<CopilotKit>` stays mounted across the
// sign-out → sign-in cycle so the post-sign-out state can actually
// demonstrate the runtime rejecting unauthenticated requests in the chat
// surface (the whole point of the demo).
//
// Error surfacing: the post-sign-out 401 is captured via the AGENT-SCOPED
// `<CopilotChat onError>` channel, NOT the provider-level `<CopilotKit
// onError>` alone. Agent-run errors (`agent_run_failed`) are reliably
// delivered to the chat-scoped subscription, whereas the provider-level
// handler does not fire for them in this flow — so a demo that relies only
// on `<CopilotKit onError>` never renders the rejection banner. We register
// the same handler on BOTH channels: `<CopilotKit onError>` covers any
// provider-level errors (e.g. the initial `/info` handshake) and
// `<CopilotChat onError>` covers agent-run rejections, which is what the
// sign-out path produces.

import { useCallback, useEffect, useMemo, useState } from "react";
import { CopilotKit, CopilotChat } from "@copilotkit/react-core/v2";
import type { CopilotKitCoreErrorCode } from "@copilotkit/react-core/v2";
import { AuthBanner } from "./auth-banner";
import { SignInCard } from "./sign-in-card";
import { useDemoAuth } from "./use-demo-auth";
import { DEMO_TOKEN } from "./demo-token";

interface AuthDemoErrorState {
  message: string;
  code: CopilotKitCoreErrorCode | string;
}

interface AuthErrorEvent {
  error?: { message?: string } | null;
  code: CopilotKitCoreErrorCode;
}

export default function AuthDemoPage() {
  const {
    isAuthenticated,
    authorizationHeader,
    hasEverSignedIn,
    signIn,
    signOut,
  } = useDemoAuth();

  const headers = useMemo<Record<string, string>>(
    () => (authorizationHeader ? { Authorization: authorizationHeader } : {}),
    [authorizationHeader],
  );

  const [authError, setAuthError] = useState<AuthDemoErrorState | null>(null);

  // Shared error handler wired to BOTH the provider-level and chat-level
  // `onError` channels (see the file header for why both are needed).
  const handleAuthError = useCallback((event: AuthErrorEvent) => {
    setAuthError({
      message:
        (event.error?.message && event.error.message.trim()) ||
        (event.code
          ? `Request rejected (${event.code})`
          : "The request was rejected."),
      code: event.code,
    });
  }, []);

  // Clear stale errors as soon as the user re-authenticates. This is the
  // ONLY thing that gates the amber error surface on auth state — the render
  // condition below keys off `authError` alone. Coupling the render to a
  // second `!isAuthenticated` slice (the obvious-but-wrong guard) created a
  // post-sign-out race: the rejection's `onError` fires and calls
  // `setAuthError`, but if that commit landed in a render where the auth
  // state hadn't yet settled to false, `authError && !isAuthenticated`
  // evaluated false and the banner never appeared. Driving the surface off
  // `authError` and clearing it here on re-auth removes the cross-slice
  // ordering dependency: a rejection always renders, and signing back in
  // always wipes it.
  useEffect(() => {
    if (isAuthenticated) setAuthError(null);
  }, [isAuthenticated]);

  if (!hasEverSignedIn) {
    return (
      <div className="flex h-screen flex-col">
        <SignInCard onSignIn={signIn} />
      </div>
    );
  }

  return (
    // `useSingleEndpoint={false}` opts into the V2 multi-endpoint protocol
    // (separate /info, /agents/<id>/run, etc.), which is what this demo's
    // runtime route is wired up for.
    <CopilotKit
      runtimeUrl="/api/copilotkit-auth"
      agent="auth-demo"
      headers={headers}
      useSingleEndpoint={false}
      onError={handleAuthError}
    >
      <div className="flex h-screen flex-col gap-3 p-6">
        <AuthBanner
          authenticated={isAuthenticated}
          onSignOut={signOut}
          onSignIn={() => signIn(DEMO_TOKEN)}
        />
        <header>
          <h1 className="text-lg font-semibold">Authentication</h1>
        </header>
        {authError && (
          <div
            data-testid="auth-demo-error"
            className="rounded-md border border-amber-300 bg-amber-50 px-3 py-2 text-sm text-amber-900"
          >
            <strong className="font-semibold">
              Runtime rejected the request:
            </strong>{" "}
            <span data-testid="auth-demo-error-message">
              {authError.message}
            </span>{" "}
            <code className="ml-1 rounded bg-amber-100 px-1 py-0.5 font-mono text-xs">
              {authError.code}
            </code>
          </div>
        )}
        <div className="flex-1 overflow-hidden rounded-md border border-neutral-200">
          <CopilotChat
            agentId="auth-demo"
            className="h-full"
            onError={handleAuthError}
          />
        </div>
      </div>
    </CopilotKit>
  );
}

// Dedicated runtime for the /demos/auth cell. Mirrors langgraph-python's
// /api/copilotkit-auth: validate a static `Authorization: Bearer <DEMO_TOKEN>`
// header via the V2 runtime's `onRequest` hook; mismatch throws a 401 before
// the request reaches the agent.

import type { NextRequest } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { HttpAgent } from "@ag-ui/client";

import { DEMO_AUTH_HEADER } from "@/app/demos/auth/demo-token";
import { extractForwardedHeaders } from "@/lib/header-forwarding";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

const BASE_PATH = "/api/copilotkit-auth";

// Build runtime+handler per-request so we can pass inbound `x-*` headers
// (e.g. `x-aimock-context`) into the HttpAgent's outbound fetch to the
// Python agent_server. See `src/lib/header-forwarding.ts` for the
// rationale.
function buildHandler(forwardedHeaders: Record<string, string>) {
  const authDemoAgent = new HttpAgent({
    url: `${AGENT_URL}/auth`,
    headers: forwardedHeaders,
  });

  const runtime = new CopilotRuntime({
    agents: {
      "auth-demo": authDemoAgent,
      default: authDemoAgent,
    },
  });

  return createCopilotRuntimeHandler({
    runtime,
    basePath: BASE_PATH,
    hooks: {
      onRequest: ({ request }) => {
        const authHeader = request.headers.get("authorization");
        if (authHeader !== DEMO_AUTH_HEADER) {
          throw new Response(
            JSON.stringify({
              error: "unauthorized",
              message:
                "Missing or invalid Authorization header. Click Authenticate above to send messages.",
            }),
            { status: 401, headers: { "content-type": "application/json" } },
          );
        }
      },
    },
  });
}

export const POST = (req: NextRequest) =>
  buildHandler(extractForwardedHeaders(req))(req);
export const GET = (req: NextRequest) =>
  buildHandler(extractForwardedHeaders(req))(req);

"use client";

import { Button } from "@/components/ui/button";

interface AuthBannerProps {
  authenticated: boolean;
  onSignOut: () => void;
  onSignIn: () => void;
}

/**
 * Status strip rendered above <CopilotChat /> in both authenticated and
 * post-sign-out states. The post-sign-out (amber) variant exists so the demo
 * actually showcases what its name promises — the runtime rejecting an
 * unauthenticated request — instead of bouncing the user back to the gate
 * page where the rejection never happens.
 *
 * Pure presentational — owns no state itself. Testids are stable contract
 * for QA + Playwright specs.
 */
export function AuthBanner({
  authenticated,
  onSignOut,
  onSignIn,
}: AuthBannerProps) {
  const classes = authenticated
    ? "border-emerald-300 bg-emerald-50 text-emerald-900"
    : "border-amber-300 bg-amber-50 text-amber-900";

  return (
    <div
      data-testid="auth-banner"
      data-authenticated={authenticated ? "true" : "false"}
      className={`flex items-center justify-between gap-3 rounded-md border px-4 py-2 text-sm ${classes}`}
    >
      <span data-testid="auth-status" className="font-medium">
        {authenticated
          ? "✓ Signed in as demo user"
          : "⚠ Signed out — the agent will reject your messages until you sign in."}
      </span>
      {authenticated ? (
        <Button
          type="button"
          data-testid="auth-sign-out-button"
          size="sm"
          variant="outline"
          onClick={onSignOut}
        >
          Sign out
        </Button>
      ) : (
        <Button
          type="button"
          data-testid="auth-authenticate-button"
          size="sm"
          onClick={onSignIn}
        >
          Sign in
        </Button>
      )}
    </div>
  );
}

/**
 * Shared demo-token constant imported by both the client
 * (use-demo-auth.ts) and the server runtime route
 * (api/copilotkit-auth/[[...slug]]/route.ts). Keeping the constant in one file
 * prevents drift: changing the token in one place changes it everywhere.
 *
 * This is a DEMO token. Never use a hard-coded shared secret for real auth.
 */
export const DEMO_TOKEN = "demo-token-123";

export const DEMO_AUTH_HEADER = `Bearer ${DEMO_TOKEN}`;

"use client";

import { useCallback, useEffect, useState } from "react";
import { DEMO_TOKEN } from "./demo-token";

const STORAGE_KEY = "copilotkit:auth-demo:token";

export interface DemoAuthHandle {
  isAuthenticated: boolean;
  /** The token string when authenticated, otherwise null. */
  token: string | null;
  /** The full `Bearer <token>` value when authenticated, otherwise null. */
  authorizationHeader: string | null;
  /**
   * Whether the user has signed in at least once during the current page
   * session. Used by the page to decide between the first-paint SignInCard
   * (never signed in) and the persistent chat-with-amber-banner state
   * (signed in, then signed out) — the latter is the only state that
   * actually showcases the runtime rejecting unauthenticated requests.
   * Resets on full page reload by design.
   */
  hasEverSignedIn: boolean;
  /** Sign in with the provided token. */
  signIn: (token: string) => void;
  /** Clear the stored token. */
  signOut: () => void;
}

/**
 * Persistent demo auth state for the /demos/auth showcase cell. Tokens are
 * stored in localStorage so a page reload doesn't kick the user back out;
 * first paint of a fresh visitor is unauthenticated, which lets the demo
 * showcase its sign-in CTA up front.
 *
 * This is a DEMO. Never store real bearer tokens in localStorage in a
 * production application — that exposes them to any script running on the
 * page.
 */
export function useDemoAuth(): DemoAuthHandle {
  const [token, setToken] = useState<string | null>(null);
  const [hasEverSignedIn, setHasEverSignedIn] = useState(false);

  // Hydrate from localStorage after mount. Reading on initial render would
  // mismatch SSR (where window is undefined); deferring to useEffect keeps
  // first paint unauthenticated and avoids hydration warnings.
  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      const stored = window.localStorage.getItem(STORAGE_KEY);
      if (stored) {
        setToken(stored);
        setHasEverSignedIn(true);
      }
    } catch {
      // localStorage unavailable (privacy mode, etc.) — fall back to
      // in-memory only.
    }
  }, []);

  const signIn = useCallback((nextToken: string) => {
    setToken(nextToken);
    setHasEverSignedIn(true);
    try {
      window.localStorage.setItem(STORAGE_KEY, nextToken);
    } catch {
      // Ignore — in-memory state still works.
    }
  }, []);

  const signOut = useCallback(() => {
    setToken(null);
    // hasEverSignedIn intentionally stays true so the page keeps showing
    // the chat surface (with amber banner) after sign-out. That is the
    // state that demonstrates the runtime returning 401.
    try {
      window.localStorage.removeItem(STORAGE_KEY);
    } catch {
      // Ignore.
    }
  }, []);

  // The runtime gate compares against a fixed token, so anything other than
  // DEMO_TOKEN won't actually authenticate against the API. We still allow
  // arbitrary strings here because validation is the runtime's job — the UI
  // just owns "what header are we sending".
  return {
    isAuthenticated: token !== null,
    token,
    authorizationHeader: token ? `Bearer ${token}` : null,
    hasEverSignedIn,
    signIn,
    signOut,
  };
}

"use client";

import React from "react";
import {
  CopilotKit,
  useAgent,
  UseAgentUpdate,
  useRenderTool,
} from "@copilotkit/react-core/v2";
import { z } from "zod";

import type { Delegation } from "./delegation-log";
import { SubAgentActivityCard } from "./subagent-activity-card";
import type { SubAgentToolStatus } from "./subagent-activity-card";
import { DemoLayout } from "./demo-layout";
import { inferActiveSubAgent } from "./active-subagent";
import { useSubagentsSuggestions } from "./suggestions";

interface SubagentsAgentState {
  delegations?: Delegation[];
}

export default function SubagentsDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="subagents">
      <DemoContent />
    </CopilotKit>
  );
}

function DemoContent() {
  const { agent } = useAgent({
    agentId: "subagents",
    updates: [UseAgentUpdate.OnStateChanged, UseAgentUpdate.OnRunStatusChanged],
  });

  useSubagentsSuggestions();

  // Per-tool renderers — one for each sub-agent tool the supervisor can
  // call. These surface "Researcher is running task Y" inline in the
  // chat stream so the user can see what is happening without staring
  // at the side panel. Each tool's `render` receives streaming
  // parameters + the eventual result + a status that walks
  // inProgress → executing → complete.
  useRenderTool(
    {
      name: "research_agent",
      parameters: z.object({ task: z.string() }),
      render: ({ parameters, status, result }) => (
        <SubAgentActivityCard
          subAgent="research_agent"
          task={parameters?.task}
          status={status as SubAgentToolStatus}
          result={typeof result === "string" ? result : undefined}
        />
      ),
    },
    [],
  );

  useRenderTool(
    {
      name: "writing_agent",
      parameters: z.object({ task: z.string() }),
      render: ({ parameters, status, result }) => (
        <SubAgentActivityCard
          subAgent="writing_agent"
          task={parameters?.task}
          status={status as SubAgentToolStatus}
          result={typeof result === "string" ? result : undefined}
        />
      ),
    },
    [],
  );

  useRenderTool(
    {
      name: "critique_agent",
      parameters: z.object({ task: z.string() }),
      render: ({ parameters, status, result }) => (
        <SubAgentActivityCard
          subAgent="critique_agent"
          task={parameters?.task}
          status={status as SubAgentToolStatus}
          result={typeof result === "string" ? result : undefined}
        />
      ),
    },
    [],
  );

  const agentState = agent.state as SubagentsAgentState | undefined;
  const delegations = agentState?.delegations ?? [];
  const isRunning = agent.isRunning;
  const activeSubAgent = isRunning
    ? inferActiveSubAgent(delegations, agent.messages)
    : null;

  return (
    <DemoLayout
      delegations={delegations}
      isRunning={isRunning}
      activeSubAgent={activeSubAgent}
    />
  );
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";
import { extractForwardedHeaders } from "@/lib/header-forwarding";

// The agent backend runs as a separate process on port 8000.
// agent_server.py mounts ONE AntigravityAgent per demo at /<agent_name>
// via create_antigravity_app; this runtime maps each agent name to its
// dedicated backend path.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Health status endpoint mounted by agent_server's HealthMiddleware, not by
// the AGENT_REGISTRY the AntigravityAgent instances are mounted from — kept
// as a named constant, rather than inlined into the fetch call's template
// literal, so it reads distinctly from an agent name in
// tests/python/test_registry.py's route/registry cross-check.
const AGENT_HEALTH_PATH = "health";

// Each agent NAME corresponds to a path mounted by the Python backend
// (see src/agents/registry.py AGENT_REGISTRY). Names with dashes preserved
// for backwards-compat with already-shipped demos.
const agentNames = [
  "agentic_chat",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "frontend_tools",
  "threadid-frontend-tool-roundtrip",
  "frontend-tools-async",
  "hitl-in-chat",
  "hitl-in-app",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "tool-rendering",
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "tool-rendering-reasoning-chain",
  "reasoning-default",
  "reasoning-custom",
  "subagents",
  "shared-state-read",
  "shared-state-read-write",
  "readonly-state-agent-context",
  "default",
];

// Build agents per-request so we can inject inbound x-* headers (e.g.
// x-aimock-context) into the outbound HTTP call to the Python agent_server.
// HttpAgent's `requestInit` spreads `this.headers` into the outbound fetch,
// so populating `headers` from `req.headers` before `copilotHandler` runs
// conveys the header as far as the Python backend, where
// HeaderForwardingHTTPMiddleware records it on a request-scoped ContextVar.
// It goes NO FURTHER: nothing in this package calls
// `install_global_httpx_hook()`, so no outbound httpx call replays the
// recorded headers — the sub-agent tools stamp `X-AIMock-Context`
// themselves, and the model call is made by the Go harness, which this
// process cannot reach into at all (the Gemini endpoint built in
// `agents/_common.py` carries a static `X-AIMock-Context` for that hop). The agent-hop record is kept for the
// CVDIAG rows. See PARITY_NOTES.md ("LLM path") and
// `src/lib/header-forwarding.ts` for the shared helper.
function buildAgents(
  headers: Record<string, string>,
): Record<string, AbstractAgent> {
  const agents: Record<string, AbstractAgent> = {};
  for (const name of agentNames) {
    agents[name] = new HttpAgent({ url: `${AGENT_URL}/${name}`, headers });
  }
  return agents;
}

// Module-load cache used only for the agent_count health probe — never
// receives request headers, so it is not used for actual POST traffic.
const healthProbeAgents = buildAgents({});

export const POST = async (req: NextRequest) => {
  try {
    const forwardedHeaders = extractForwardedHeaders(req);
    const agents = buildAgents(forwardedHeaders);

    const runtime = new CopilotRuntime({
      agents,
    });

    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    return await copilotHandler(req);
  } catch (error: unknown) {
    // Log full details server-side (operators grep `errorId` to correlate),
    // but never echo `err.message` / `err.stack` back to the HTTP client —
    // that leaks internal paths, dependency versions, and stack traces.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = crypto.randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        scope: "copilotkit",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/${AGENT_HEALTH_PATH}`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    agent_count: Object.keys(healthProbeAgents).length,
    env: {
      GEMINI_API_KEY: process.env.GEMINI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

import type { Delegation, SubAgentName } from "./delegation-log";

// Inspect the live message stream to find the most recent supervisor
// tool call to a sub-agent that has not yet produced a ToolMessage
// reply. Falls back to `null` when there is no in-flight delegation.
//
// This is intentionally defensive — the v2 message shape can vary
// across runtime versions, so we structurally probe instead of
// relying on a specific TS type.
type RawToolCall = {
  id?: string | null;
  function?: { name?: string | null; arguments?: string | null } | null;
};

type RawMessage = {
  role?: string;
  toolCalls?: RawToolCall[] | null;
  toolCallId?: string | null;
  content?: unknown;
};

export function inferActiveSubAgent(
  delegations: Delegation[],
  messages: unknown,
): { subAgent: SubAgentName; task: string } | null {
  const msgs: RawMessage[] = Array.isArray(messages)
    ? (messages as RawMessage[])
    : [];

  // Collect every tool_call_id that already has a matching tool reply.
  const repliedIds = new Set<string>();
  for (const m of msgs) {
    if (m.role === "tool" && typeof m.toolCallId === "string") {
      repliedIds.add(m.toolCallId);
    }
  }

  const SUB_AGENT_NAMES: ReadonlySet<SubAgentName> = new Set<SubAgentName>([
    "research_agent",
    "writing_agent",
    "critique_agent",
  ]);

  // Walk newest → oldest and return the most recent unanswered call.
  for (let i = msgs.length - 1; i >= 0; i--) {
    const m = msgs[i];
    if (!m || m.role !== "assistant" || !Array.isArray(m.toolCalls)) continue;
    for (let j = m.toolCalls.length - 1; j >= 0; j--) {
      const call = m.toolCalls[j];
      const name = call?.function?.name;
      if (typeof name !== "string") continue;
      if (!SUB_AGENT_NAMES.has(name as SubAgentName)) continue;
      if (typeof call?.id === "string" && repliedIds.has(call.id)) continue;
      const task = extractTask(call?.function?.arguments);
      return { subAgent: name as SubAgentName, task };
    }
  }

  // Fall back: if delegations is non-empty but the supervisor is still
  // running, surface the most recent delegation as a soft signal.
  if (delegations.length > 0) {
    const last = delegations[delegations.length - 1];
    if (last && last.status !== "completed") {
      return { subAgent: last.sub_agent, task: last.task };
    }
  }
  return null;
}

function extractTask(rawArgs: string | null | undefined): string {
  if (!rawArgs) return "(preparing task…)";
  // Streaming tool args may be a partial JSON string. Try a strict
  // parse first, then fall back to a regex sniff for `"task": "..."`.
  try {
    const parsed = JSON.parse(rawArgs);
    if (parsed && typeof parsed === "object" && "task" in parsed) {
      const t = (parsed as { task?: unknown }).task;
      if (typeof t === "string" && t.trim().length > 0) return t;
    }
  } catch {
    const match = rawArgs.match(/"task"\s*:\s*"((?:[^"\\]|\\.)*)/);
    if (match && match[1].length > 0) {
      try {
        return JSON.parse(`"${match[1]}"`);
      } catch {
        return match[1];
      }
    }
  }
  return "(preparing task…)";
}

"use client";

import React from "react";

export type SubAgentName =
  | "research_agent"
  | "writing_agent"
  | "critique_agent";

export interface Delegation {
  id: string;
  sub_agent: SubAgentName;
  task: string;
  status: "completed";
  result: string;
}

export interface DelegationLogProps {
  delegations: Delegation[];
  /** True while the supervisor is actively running. */
  isRunning: boolean;
}

const SUB_AGENT_STYLE: Record<
  SubAgentName,
  { label: string; color: string; emoji: string }
> = {
  research_agent: {
    label: "Research",
    color: "bg-[#BEC2FF1A] text-[#010507] border-[#BEC2FF]",
    emoji: "🔎",
  },
  writing_agent: {
    label: "Writing",
    color: "bg-[#85ECCE]/15 text-[#189370] border-[#85ECCE4D]",
    emoji: "✍️",
  },
  critique_agent: {
    label: "Critique",
    color: "bg-[#FFAC4D]/12 text-[#010507] border-[#FFAC4D33]",
    emoji: "🧐",
  },
};

/**
 * Live delegation log — renders the `delegations` slot of agent state.
 *
 * Each entry corresponds to one invocation of a sub-agent. The list
 * grows in real time as the supervisor fans work out to its children.
 * The parent header shows how many sub-agents have been called and
 * whether the supervisor is still running.
 */
// Fixed list of the three sub-agent roles the supervisor can call.
// Rendered as always-visible indicator chips at the top of the log
// (regardless of whether the supervisor has delegated yet) so the user
// — and the e2e suite — can see at a glance which sub-agents exist and
// which are currently active.
const INDICATOR_ROLES: ReadonlyArray<{
  role: "researcher" | "writer" | "critic";
  subAgent: SubAgentName;
}> = [
  { role: "researcher", subAgent: "research_agent" },
  { role: "writer", subAgent: "writing_agent" },
  { role: "critic", subAgent: "critique_agent" },
];

export function DelegationLog({ delegations, isRunning }: DelegationLogProps) {
  const calledRoles = new Set<SubAgentName>(
    delegations.map((d) => d.sub_agent),
  );

  return (
    <div
      data-testid="delegation-log"
      className="w-full h-full flex flex-col bg-white rounded-2xl shadow-sm border border-[#DBDBE5] overflow-hidden"
    >
      <div className="flex items-center justify-between px-6 py-3 border-b border-[#E9E9EF] bg-[#FAFAFC]">
        <div className="flex items-center gap-3">
          <span className="text-lg font-semibold text-[#010507]">
            Sub-agent delegations
          </span>
          {isRunning && (
            <span
              data-testid="supervisor-running"
              className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full border border-[#BEC2FF] bg-[#BEC2FF1A] text-[#010507] text-[10px] font-semibold uppercase tracking-[0.12em]"
            >
              <span className="w-1.5 h-1.5 rounded-full bg-[#010507] animate-pulse" />
              Supervisor running
            </span>
          )}
        </div>
        <span
          data-testid="delegation-count"
          className="text-xs font-mono text-[#838389]"
        >
          {delegations.length} calls
        </span>
      </div>

      <div
        data-testid="subagent-indicators"
        className="flex items-center gap-2 border-b border-[#E9E9EF] bg-white px-6 py-2"
      >
        {INDICATOR_ROLES.map(({ role, subAgent }) => {
          const style = SUB_AGENT_STYLE[subAgent];
          const fired = calledRoles.has(subAgent);
          return (
            <span
              key={role}
              data-testid={`subagent-indicator-${role}`}
              data-role={role}
              data-fired={fired ? "true" : "false"}
              className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold uppercase tracking-[0.1em] border ${style.color} ${
                fired ? "" : "opacity-60"
              }`}
            >
              <span aria-hidden>{style.emoji}</span>
              <span>{style.label}</span>
            </span>
          );
        })}
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {delegations.length === 0 ? (
          <p className="text-[#838389] italic text-sm">
            Ask the supervisor to complete a task. Every sub-agent it calls will
            appear here.
          </p>
        ) : (
          delegations.map((d, idx) => {
            const style = SUB_AGENT_STYLE[d.sub_agent];
            return (
              <div
                key={d.id}
                data-testid="delegation-entry"
                className="border border-[#E9E9EF] rounded-xl p-3 bg-[#FAFAFC]"
              >
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-mono text-[#AFAFB7]">
                      #{idx + 1}
                    </span>
                    <span
                      className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold uppercase tracking-[0.1em] border ${style.color}`}
                    >
                      <span>{style.emoji}</span>
                      <span>{style.label}</span>
                    </span>
                  </div>
                  <span className="text-[10px] uppercase tracking-[0.12em] font-semibold text-[#189370]">
                    {d.status}
                  </span>
                </div>
                <div className="text-xs text-[#57575B] mb-2">
                  <span className="font-semibold text-[#010507]">Task: </span>
                  {d.task}
                </div>
                <div className="text-sm text-[#010507] whitespace-pre-wrap bg-white rounded-lg p-2.5 border border-[#E9E9EF]">
                  {d.result}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

