"use client";

import React from "react";
import {
  CopilotChat,
  CopilotKit,
  useAgent,
  UseAgentUpdate,
} from "@copilotkit/react-core/v2";
import type { Step } from "./InlineAgentStateCard";
import { MessageListWithState } from "./message-list-with-state";
import { useSuggestions } from "./suggestions";

/**
 * Agentic Generative UI — In-Chat State Rendering
 *
 * The deep agent on the backend defines its own state schema
 * (`steps: list[Step]`) and exposes a custom `set_steps` tool that the model
 * calls to mutate that state. Every `set_steps` call streams the updated
 * `steps` to the client.
 *
 * On the client we subscribe to that live state via `useAgent` (v2) and
 * render a single `InlineAgentStateCard` inside the chat transcript via
 * `messageView.children`. The card re-renders in place as state arrives —
 * no per-message claims, no duplicate cards.
 *
 * This mirrors the pattern used by every other integration's gen-ui-agent
 * demo (mastra, strands, ag2, agno, crewai-crews, langgraph-typescript,
 * pydantic-ai, ...) and replaces the earlier `useCoAgentStateRender`
 * approach which produced one card per state-changing message.
 */
export default function GenUiAgentDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="gen-ui-agent">
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

type AgentState = {
  steps?: Step[];
};

function Chat() {
  const { agent } = useAgent({
    agentId: "gen-ui-agent",
    updates: [UseAgentUpdate.OnStateChanged],
  });

  useSuggestions();

  const steps = (agent.state as AgentState | undefined)?.steps ?? [];
  const status = agent.isRunning ? "inProgress" : "complete";

  return (
    <CopilotChat
      agentId="gen-ui-agent"
      className="h-full rounded-2xl"
      messageView={{
        children: ({ messageElements, interruptElement }) => (
          <MessageListWithState
            messageElements={messageElements}
            interruptElement={interruptElement}
            steps={steps}
            status={status}
          />
        ),
      }}
    />
  );
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";
import { extractForwardedHeaders } from "@/lib/header-forwarding";

// The agent backend runs as a separate process on port 8000.
// agent_server.py mounts ONE AntigravityAgent per demo at /<agent_name>
// via create_antigravity_app; this runtime maps each agent name to its
// dedicated backend path.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Health status endpoint mounted by agent_server's HealthMiddleware, not by
// the AGENT_REGISTRY the AntigravityAgent instances are mounted from — kept
// as a named constant, rather than inlined into the fetch call's template
// literal, so it reads distinctly from an agent name in
// tests/python/test_registry.py's route/registry cross-check.
const AGENT_HEALTH_PATH = "health";

// Each agent NAME corresponds to a path mounted by the Python backend
// (see src/agents/registry.py AGENT_REGISTRY). Names with dashes preserved
// for backwards-compat with already-shipped demos.
const agentNames = [
  "agentic_chat",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "frontend_tools",
  "threadid-frontend-tool-roundtrip",
  "frontend-tools-async",
  "hitl-in-chat",
  "hitl-in-app",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "tool-rendering",
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "tool-rendering-reasoning-chain",
  "reasoning-default",
  "reasoning-custom",
  "subagents",
  "shared-state-read",
  "shared-state-read-write",
  "readonly-state-agent-context",
  "default",
];

// Build agents per-request so we can inject inbound x-* headers (e.g.
// x-aimock-context) into the outbound HTTP call to the Python agent_server.
// HttpAgent's `requestInit` spreads `this.headers` into the outbound fetch,
// so populating `headers` from `req.headers` before `copilotHandler` runs
// conveys the header as far as the Python backend, where
// HeaderForwardingHTTPMiddleware records it on a request-scoped ContextVar.
// It goes NO FURTHER: nothing in this package calls
// `install_global_httpx_hook()`, so no outbound httpx call replays the
// recorded headers — the sub-agent tools stamp `X-AIMock-Context`
// themselves, and the model call is made by the Go harness, which this
// process cannot reach into at all (the Gemini endpoint built in
// `agents/_common.py` carries a static `X-AIMock-Context` for that hop). The agent-hop record is kept for the
// CVDIAG rows. See PARITY_NOTES.md ("LLM path") and
// `src/lib/header-forwarding.ts` for the shared helper.
function buildAgents(
  headers: Record<string, string>,
): Record<string, AbstractAgent> {
  const agents: Record<string, AbstractAgent> = {};
  for (const name of agentNames) {
    agents[name] = new HttpAgent({ url: `${AGENT_URL}/${name}`, headers });
  }
  return agents;
}

// Module-load cache used only for the agent_count health probe — never
// receives request headers, so it is not used for actual POST traffic.
const healthProbeAgents = buildAgents({});

export const POST = async (req: NextRequest) => {
  try {
    const forwardedHeaders = extractForwardedHeaders(req);
    const agents = buildAgents(forwardedHeaders);

    const runtime = new CopilotRuntime({
      agents,
    });

    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    return await copilotHandler(req);
  } catch (error: unknown) {
    // Log full details server-side (operators grep `errorId` to correlate),
    // but never echo `err.message` / `err.stack` back to the HTTP client —
    // that leaks internal paths, dependency versions, and stack traces.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = crypto.randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        scope: "copilotkit",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/${AGENT_HEALTH_PATH}`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    agent_count: Object.keys(healthProbeAgents).length,
    env: {
      GEMINI_API_KEY: process.env.GEMINI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

"use client";

import React from "react";

/**
 * Step shape matches the `Step` TypedDict emitted by the Python deep agent's
 * custom `set_steps` tool (see `src/agents/gen_ui_agent.py`).
 * Status transitions: pending -> in_progress -> completed.
 */
export type Step = {
  id: string;
  title: string;
  status: "pending" | "in_progress" | "completed";
};

export function InlineAgentStateCard({
  steps,
  status,
}: {
  steps: Step[];
  status: "inProgress" | "complete";
}) {
  const total = steps.length;
  const done = steps.filter((s) => s.status === "completed").length;
  const headline =
    status === "complete" || (total > 0 && done === total)
      ? `All ${total} steps complete`
      : total > 0
        ? `Step ${Math.min(done + 1, total)} of ${total}`
        : "Planning…";

  return (
    <div
      data-testid="agent-state-card"
      className="my-3 mx-4 rounded-2xl border border-[#DBDBE5] bg-white p-4 shadow-sm"
    >
      <div className="flex items-center gap-2">
        {status === "inProgress" && done < total ? (
          <SpinnerIcon />
        ) : (
          <CheckIcon />
        )}
        <span className="text-sm font-semibold text-[#010507]">{headline}</span>
      </div>

      {steps.length > 0 && (
        <ol className="mt-3 space-y-2">
          {steps.map((step, idx) => (
            <li
              key={step.id ?? idx}
              data-testid="agent-step"
              data-status={step.status}
              className="flex items-start gap-3"
            >
              <StepMarker status={step.status} index={idx} />
              <span
                className={
                  "text-xs leading-5 " +
                  (step.status === "completed"
                    ? "text-[#838389] line-through"
                    : step.status === "in_progress"
                      ? "text-[#010507] font-medium"
                      : "text-[#57575B]")
                }
              >
                {step.title}
              </span>
            </li>
          ))}
        </ol>
      )}
    </div>
  );
}

function StepMarker({
  status,
  index,
}: {
  status: Step["status"];
  index: number;
}) {
  if (status === "completed") {
    return (
      <span className="mt-0.5 inline-flex h-5 w-5 flex-none items-center justify-center rounded-full bg-[#85ECCE] text-[#010507]">
        <svg
          className="h-3 w-3"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={3}
            d="M5 13l4 4L19 7"
          />
        </svg>
      </span>
    );
  }
  if (status === "in_progress") {
    return (
      <span className="mt-0.5 inline-flex h-5 w-5 flex-none items-center justify-center rounded-full bg-[#BEC2FF] text-[#010507]">
        <svg
          className="h-3 w-3 animate-spin"
          xmlns="http://www.w3.org/2000/svg"
          fill="none"
          viewBox="0 0 24 24"
        >
          <circle
            className="opacity-30"
            cx="12"
            cy="12"
            r="10"
            stroke="currentColor"
            strokeWidth="4"
          />
          <path
            className="opacity-90"
            fill="currentColor"
            d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
          />
        </svg>
      </span>
    );
  }
  return (
    <span className="mt-0.5 inline-flex h-5 w-5 flex-none items-center justify-center rounded-full border border-[#DBDBE5] bg-white text-[10px] font-semibold text-[#838389]">
      {index + 1}
    </span>
  );
}

function SpinnerIcon() {
  return (
    <svg
      className="w-4 h-4 animate-spin text-[#010507]"
      xmlns="http://www.w3.org/2000/svg"
      fill="none"
      viewBox="0 0 24 24"
    >
      <circle
        className="opacity-25"
        cx="12"
        cy="12"
        r="10"
        stroke="currentColor"
        strokeWidth="4"
      />
      <path
        className="opacity-75"
        fill="currentColor"
        d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
      />
    </svg>
  );
}

function CheckIcon() {
  return (
    <svg
      className="w-4 h-4 text-[#189370]"
      fill="none"
      stroke="currentColor"
      viewBox="0 0 24 24"
    >
      <path
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth={3}
        d="M5 13l4 4L19 7"
      />
    </svg>
  );
}

"use client";

import React from "react";
import { InlineAgentStateCard } from "./InlineAgentStateCard";
import type { Step } from "./InlineAgentStateCard";

export function MessageListWithState({
  messageElements,
  interruptElement,
  steps,
  status,
}: {
  messageElements: React.ReactNode;
  interruptElement: React.ReactNode;
  steps: Step[];
  status: "inProgress" | "complete";
}) {
  return (
    <div data-testid="copilot-message-list" className="flex flex-col">
      {messageElements}
      {steps.length > 0 && (
        <InlineAgentStateCard steps={steps} status={status} />
      )}
      {interruptElement}
    </div>
  );
}

"use client";

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export function useSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Plan a product launch",
        message: "Plan a product launch for a new mobile app.",
      },
      {
        title: "Organize a team offsite",
        message: "Organize a three-day engineering team offsite.",
      },
      {
        title: "Research a competitor",
        message:
          "Research our top competitor and summarize their strengths and weaknesses.",
      },
    ],
    available: "always",
  });
}

"use client";

// Shared State (Read-only) — the UI publishes a recipe to the agent via
// `agent.setState`; the agent reads that recipe on every turn but does
// not mutate it (the model reads it through the adapter's silent built-in
// `get_shared_state` tool and has no tool that writes it — see
// src/agents/shared_state.py).
//
// Single source of truth: `agent.state.recipe`. The form is a pure
// controlled component on top of that — every edit flows straight into
// `agent.setState({...})` and the next render reflects it.

import React, { useEffect } from "react";
import {
  CopilotKit,
  CopilotSidebar,
  useAgent,
  UseAgentUpdate,
  useConfigureSuggestions,
  useCopilotKit,
} from "@copilotkit/react-core/v2";
import { RecipeCard } from "./recipe-card";
import type { RecipeAgentState, RecipeData } from "./types";
import { INITIAL_RECIPE } from "./types";

export default function SharedStateReadDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="shared-state-read">
      <div className="min-h-screen w-full bg-gray-50">
        <div className="mx-auto max-w-2xl px-4 py-8 md:py-12">
          <Recipe />
        </div>
        <CopilotSidebar
          defaultOpen
          labels={{ modalHeaderTitle: "AI Recipe Assistant" }}
        />
      </div>
    </CopilotKit>
  );
}

function Recipe() {
  const { agent } = useAgent({
    agentId: "shared-state-read",
    updates: [UseAgentUpdate.OnStateChanged, UseAgentUpdate.OnRunStatusChanged],
  });
  const { copilotkit } = useCopilotKit();

  useConfigureSuggestions({
    suggestions: [
      {
        title: "Create Italian recipe",
        message: "Create a delicious Italian pasta recipe.",
      },
      {
        title: "Make it healthier",
        message: "Make the recipe healthier with more vegetables.",
      },
      {
        title: "Suggest variations",
        message: "Suggest some creative variations of this recipe.",
      },
    ],
    available: "always",
  });

  // Seed the initial recipe into agent state once so the agent has
  // something to read on the first turn. After this, every edit lands
  // via `agent.setState` below.
  useEffect(() => {
    if (!(agent.state as RecipeAgentState | undefined)?.recipe) {
      agent.setState({ recipe: INITIAL_RECIPE } satisfies RecipeAgentState);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const recipe =
    (agent.state as RecipeAgentState | undefined)?.recipe ?? INITIAL_RECIPE;

  const handleChange = (next: RecipeData) => {
    agent.setState({ recipe: next } satisfies RecipeAgentState);
  };

  const handleImprove = () => {
    if (agent.isRunning) return;
    agent.addMessage({
      id: crypto.randomUUID(),
      role: "user",
      content: "Improve the recipe",
    });
    void copilotkit
      .runAgent({ agent })
      .catch((err) =>
        console.error("[shared-state-read] runAgent failed", err),
      );
  };

  return (
    <RecipeCard
      recipe={recipe}
      isLoading={agent.isRunning}
      onChange={handleChange}
      onImprove={handleImprove}
    />
  );
}

import type { NextRequest } from "next/server";
