"use client";

/**
 * A2UI Error Recovery demo.
 *
 * Same dynamic-schema A2UI setup as declarative-gen-ui (it reuses that demo's
 * catalog), but it makes the toolkit's validate->retry recovery loop visible.
 * The dedicated runtime at `/api/copilotkit-a2ui-recovery` is configured with
 * `injectA2UITool: false` — the backend agent (`src/agents/a2ui_recovery.py`)
 * owns `generate_a2ui` (an Antigravity server tool, `src/agents/a2ui_dynamic.py`),
 * whose body runs the forced `render_a2ui` sub-agent call and the A2UI
 * toolkit's recovery loop + recovery-exhausted hard-fail envelope
 * (OSS-158 / OSS-375).
 *
 * The two suggestion pills drive aimock fixtures that force:
 *   - HEAL: an invalid first render that recovers to a valid one
 *     (building -> retrying -> painted).
 *   - EXHAUST: an always-invalid render that hits the attempt cap
 *     (a tasteful `failed` state, never a broken surface).
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";

// Reuse the declarative-gen-ui catalog (same components, same catalogId).
import { myCatalog } from "../declarative-gen-ui/a2ui/catalog";
import { Chat } from "./chat";

export default function A2uiRecoveryDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-a2ui-recovery"
      agent="a2ui-recovery"
      a2ui={{ catalog: myCatalog }}
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

// Dedicated runtime for the A2UI Error Recovery demo.
// `a2ui.injectA2UITool: false` — the backend AntigravityAgent OWNS
// `generate_a2ui` (src/agents/a2ui_dynamic.py, wired by
// src/agents/a2ui_recovery.py), whose body runs the forced `render_a2ui`
// sub-agent call + the A2UI toolkit validate->retry recovery loop + the
// recovery-exhausted hard-fail envelope. The runtime must NOT inject a second
// copy; this `false` is load-bearing post CopilotKit#5611 (the provider catalog
// otherwise defaults injectA2UITool to true). The middleware still renders the
// painted / failed end-states from the tool result.
//
// The demo reuses the declarative-gen-ui catalog. The aimock fixtures force the
// inner render_a2ui call to emit an invalid surface once (heal pill) or on
// every attempt (exhaust pill).
//
// Reference:
// - showcase/integrations/langgraph-python/src/app/api/copilotkit-a2ui-recovery/route.ts

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { HttpAgent } from "@ag-ui/client";
import { extractForwardedHeaders } from "@/lib/header-forwarding";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Build per-request so inbound `x-aimock-context` (and other `x-*` headers)
// is forwarded onto the outbound call to the Python agent_server. See
// `src/lib/header-forwarding.ts` for the rationale.
export const POST = async (req: NextRequest) => {
  try {
    const headers = extractForwardedHeaders(req);

    const runtime = new CopilotRuntime({
      agents: {
        "a2ui-recovery": new HttpAgent({
          url: `${AGENT_URL}/a2ui_recovery`,
          headers,
        }),
      },
      a2ui: {
        // The backend owns `generate_a2ui` and its recovery loop; the runtime
        // must not inject a second A2UI tool (see the header comment).
        injectA2UITool: false,
        // The catalog the page registers (declarative-gen-ui/a2ui/catalog.ts).
        defaultCatalogId: "declarative-gen-ui-catalog",
      },
    });

    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-a2ui-recovery",
      mode: "single-route",
    });

    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

"use client";

import { CopilotChat } from "@copilotkit/react-core/v2";
import { useA2uiRecoverySuggestions } from "./suggestions";
// Reuse the declarative-gen-ui sales dataset/context so the healed surface has
// real numbers to render.
import { useSalesAnalystContext } from "../declarative-gen-ui/sales-context";

export function Chat() {
  useA2uiRecoverySuggestions();
  useSalesAnalystContext();
  return <CopilotChat agentId="a2ui-recovery" className="h-full rounded-2xl" />;
}

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

// Two pills exercise the recovery loop deterministically via aimock fixtures
// (showcase/aimock/d6/google-antigravity/a2ui-recovery.json). Prompts are
// unique per integration slug so they don't collide with the declarative-gen-ui
// fixtures or with another framework's recovery fixtures.
//   - "heal":    the first inner render_a2ui attempt is structurally invalid
//                (the root references a missing child); the backend's
//                validate->retry loop regenerates with the errors appended ->
//                valid -> painted.
//   - "exhaust": inner render_a2ui is invalid on every attempt -> attempt cap
//                hit -> a2ui_recovery_exhausted -> tasteful `failed` state.
export function useA2uiRecoverySuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Recover a bad render",
        message:
          "Chart the Antigravity quarterly revenue board and repair a malformed first render.",
      },
      {
        title: "Show an unrecoverable failure",
        message:
          "Chart an Antigravity board that never passes validation so I can preview the fallback.",
      },
    ],
    available: "always",
  });
}

"use client";

import { CopilotKit } from "@copilotkit/react-core/v2";
import { AGENT_ID, Chat } from "./chat";

export default function ByocJsonRenderDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-declarative-json-render"
      agent={AGENT_ID}
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

"""declarative-json-render: the agent replies with a json-render flat spec.

The page's assistant-message slot (`json-render-renderer.tsx`) parses the
reply TEXT as `{ root, elements }` and renders it with `@json-render/react`
against a Zod-validated catalog (MetricCard, BarChart, PieChart). The prompt
is copied from langgraph-python's byoc_json_render_agent.py.

No tools, and deliberately no `response_schema`: the adapter delivers a
schema-constrained answer as shared state, not as the assistant text the
renderer parses. The renderer tolerates code fences and a prose preamble, so
the prompt alone is enough.
"""

from agents._common import build

SYSTEM_PROMPT = """
You are a sales-dashboard UI generator for a BYOC json-render demo.

When the user asks for a UI, respond with **exactly one JSON object** and
nothing else — no prose, no markdown fences, no leading explanation. The
object must match this schema (the "flat element map" format consumed by
`@json-render/react`):

{
  "root": "<id of the root element>",
  "elements": {
    "<id>": {
      "type": "<component name>",
      "props": { ... component-specific props ... },
      "children": [ "<id>", ... ]
    },
    ...
  }
}

Available components (use each name verbatim as "type"):

- MetricCard
  props: { "label": string, "value": string, "trend": string | null }
  Example trend strings: "+12% vs last quarter", "-3% vs last month", null.

- BarChart
  props: {
    "title": string,
    "description": string | null,
    "data": [ { "label": string, "value": number }, ... ]
  }

- PieChart
  props: {
    "title": string,
    "description": string | null,
    "data": [ { "label": string, "value": number }, ... ]
  }

Rules:

1. Output **only** valid JSON. No markdown code fences. No text outside
   the object.
2. Every id referenced in `root` or any `children` array must be a key
   in `elements`.
3. For a multi-component dashboard, use a root MetricCard and list the
   charts in its `children` array, OR pick any element as root and list
   the others as its children. Do not emit orphan elements.
4. Use realistic sales-domain values (revenue, pipeline, conversion,
   categories, months) — the demo is a sales dashboard.
5. `children` is optional but when present must be an array of strings.
6. Never invent component types outside the three listed above.

### Worked example — "Show me the sales dashboard with metrics and a revenue chart"

{
  "root": "revenue-metric",
  "elements": {
    "revenue-metric": {
      "type": "MetricCard",
      "props": {
        "label": "Revenue (Q3)",
        "value": "$1.24M",
        "trend": "+18% vs Q2"
      },
      "children": ["revenue-bar"]
    },
    "revenue-bar": {
      "type": "BarChart",
      "props": {
        "title": "Monthly revenue",
        "description": "Revenue by month across Q3",
        "data": [
          { "label": "Jul", "value": 380000 },
          { "label": "Aug", "value": 410000 },
          { "label": "Sep", "value": 450000 }
        ]
      }
    }
  }
}

### Worked example — "Break down revenue by category as a pie chart"

{
  "root": "category-pie",
  "elements": {
    "category-pie": {
      "type": "PieChart",
      "props": {
        "title": "Revenue by category",
        "description": "Share of total revenue by product category",
        "data": [
          { "label": "Enterprise", "value": 540000 },
          { "label": "SMB", "value": 310000 },
          { "label": "Self-serve", "value": 220000 },
          { "label": "Partner", "value": 170000 }
        ]
      }
    }
  }
}

### Worked example — "Show me monthly expenses as a bar chart"

{
  "root": "expense-bar",
  "elements": {
    "expense-bar": {
      "type": "BarChart",
      "props": {
        "title": "Monthly expenses",
        "description": "Operating expenses by month",
        "data": [
          { "label": "Jul", "value": 210000 },
          { "label": "Aug", "value": 225000 },
          { "label": "Sep", "value": 240000 }
        ]
      }
    }
  }
}

Respond with the JSON object only.
"""


def byoc_json_render_agent():
    return build(system_instructions=SYSTEM_PROMPT.strip())

// Dedicated runtime for the declarative-json-render demo.
//
// Splitting into its own endpoint (mirroring beautiful-chat +
// declarative-gen-ui) keeps the agent isolated from the default multi-agent
// `/api/copilotkit` runtime. The demo page
// (src/app/demos/declarative-json-render/page.tsx) points
// `<CopilotKit runtimeUrl>` here under the agent name `byoc_json_render`.
// The backend (src/agents/byoc_json_render.py) is a tool-less
// AntigravityAgent whose system prompt makes it reply with a
// `{ root, elements }` json-render spec as plain assistant text.
//
// Reference:
// - showcase/integrations/langgraph-python/src/app/api/copilotkit-declarative-json-render/route.ts

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { HttpAgent } from "@ag-ui/client";
import { extractForwardedHeaders } from "@/lib/header-forwarding";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Build per-request so inbound `x-aimock-context` (and other `x-*` headers)
// is forwarded onto the outbound call to the Python agent_server. See
// `src/lib/header-forwarding.ts` for the rationale.
export const POST = async (req: NextRequest) => {
  try {
    const headers = extractForwardedHeaders(req);

    const runtime = new CopilotRuntime({
      agents: {
        byoc_json_render: new HttpAgent({
          url: `${AGENT_URL}/declarative_json_render`,
          headers,
        }),
      },
    });

    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-declarative-json-render",
      mode: "single-route",
    });

    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

import { defineCatalog } from "@json-render/core";
import { schema } from "@json-render/react/schema";
import { z } from "zod4";

const dataPoint = z.object({ label: z.string(), value: z.number() });

export const catalog = defineCatalog(schema, {
  components: {
    MetricCard: {
      props: z.object({
        label: z.string(),
        value: z.string(),
        trend: z.string().nullable(),
      }),
      description:
        "A labelled metric (single number) with an optional trend subtitle",
    },
    BarChart: {
      props: z.object({
        title: z.string(),
        description: z.string().nullable(),
        data: z.array(dataPoint),
      }),
      description:
        "A vertical bar chart for comparing discrete values side by side",
    },
    PieChart: {
      props: z.object({
        title: z.string(),
        description: z.string().nullable(),
        data: z.array(dataPoint),
      }),
      description:
        "A donut-style pie chart for breaking a total down into category slices",
    },
  },
  actions: {},
});

"use client";

import { useRef } from "react";
import {
  BarChart as RechartsBarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Rectangle,
} from "recharts";
import { CHART_COLORS, CHART_CONFIG } from "./chart-config";

export interface BarChartDatum {
  label: string;
  value: number;
}

export interface BarChartComponentProps {
  title: string;
  description?: string | null;
  data: BarChartDatum[];
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function AnimatedBar({ isNew, ...rest }: any) {
  return (
    <g
      style={
        isNew
          ? { animation: "barSlideIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) both" }
          : undefined
      }
    >
      <Rectangle {...rest} />
    </g>
  );
}

export function BarChart({ title, description, data }: BarChartComponentProps) {
  const seen = useRef(new Set<number>());
  const isNew = (i: number) => {
    if (seen.current.has(i)) return false;
    seen.current.add(i);
    return true;
  };

  const hasData = Array.isArray(data) && data.length > 0;

  return (
    <div
      data-testid="bar-chart"
      className="max-w-2xl mx-auto my-4 overflow-hidden rounded-lg border border-[var(--border)] bg-[var(--card)]"
    >
      {hasData && (
        <style>{`@keyframes barSlideIn { from { transform: translateY(40px); opacity: 0; } 20% { opacity: 1; } to { transform: translateY(0); opacity: 1; } }`}</style>
      )}
      <div className="p-6 pb-2">
        <h3 className="text-lg font-semibold leading-none tracking-tight text-[var(--foreground)]">
          {title}
        </h3>
        {description ? (
          <p className="text-sm text-[var(--muted-foreground)]">
            {description}
          </p>
        ) : null}
      </div>
      <div className="p-6 pt-2">
        {hasData ? (
          <ResponsiveContainer width="100%" height={280}>
            <RechartsBarChart
              data={data}
              margin={{ top: 12, right: 12, bottom: 4, left: -8 }}
            >
              <CartesianGrid
                strokeDasharray="3 3"
                stroke="var(--border)"
                vertical={false}
              />
              <XAxis
                dataKey="label"
                tick={{ fontSize: 12, fill: "var(--muted-foreground)" }}
                stroke="var(--border)"
                tickLine={false}
                axisLine={false}
              />
              <YAxis
                tick={{ fontSize: 12, fill: "var(--muted-foreground)" }}
                stroke="var(--border)"
                tickLine={false}
                axisLine={false}
              />
              <Tooltip
                contentStyle={CHART_CONFIG.tooltipStyle}
                cursor={{ fill: "var(--secondary)", opacity: 0.5 }}
              />
              <Bar
                isAnimationActive={false}
                dataKey="value"
                radius={[6, 6, 0, 0]}
                maxBarSize={48}
                shape={(props: unknown) => {
                  const p = props as Record<string, unknown>;
                  return (
                    <AnimatedBar {...p} isNew={isNew(p.index as number)} />
                  );
                }}
              >
                {data.map((_, i) => (
                  <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />
                ))}
              </Bar>
            </RechartsBarChart>
          </ResponsiveContainer>
        ) : (
          <p className="text-[var(--muted-foreground)] text-center py-8 text-sm">
            No data available
          </p>
        )}
      </div>
    </div>
  );
}

export const CHART_COLORS = [
  "#BEC2FF", // lilac-400
  "#85ECCE", // mint-400
  "#FFAC4D", // orange-400
  "#FFF388", // yellow-400
  "#189370", // mint-800
  "#EEE6FE", // primary-100
  "#FA5F67", // red-400
] as const;

export const CHART_CONFIG = {
  tooltipStyle: {
    backgroundColor: "var(--card)",
    border: "1px solid var(--border)",
    borderRadius: "10px",
    padding: "10px 14px",
    color: "var(--foreground)",
    fontSize: "13px",
    fontFamily: "var(--font-body)",
    boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
  },
};

"use client";

import { CHART_COLORS } from "./chart-config";

export interface PieChartDatum {
  label: string;
  value: number;
}

export interface PieChartComponentProps {
  title: string;
  description?: string | null;
  data: PieChartDatum[];
}

function DonutChart({
  data,
  size = 240,
  strokeWidth = 40,
}: {
  data: PieChartDatum[];
  size?: number;
  strokeWidth?: number;
}) {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const center = size / 2;
  const total = data.reduce((sum, d) => sum + (Number(d.value) || 0), 0);

  let accumulated = 0;
  const slices = data.map((item, i) => {
    const arc =
      (total > 0 ? (Number(item.value) || 0) / total : 0) * circumference;
    const dashoffset = -accumulated;
    accumulated += arc;
    return {
      arc,
      gap: circumference - arc,
      dashoffset,
      color: CHART_COLORS[i % CHART_COLORS.length],
    };
  });

  return (
    <svg
      width="100%"
      viewBox={`0 0 ${size} ${size}`}
      className="block mx-auto"
      style={{ maxWidth: size, transform: "scaleX(-1)" }}
    >
      <circle
        cx={center}
        cy={center}
        r={radius}
        fill="none"
        stroke="var(--secondary)"
        strokeWidth={strokeWidth}
      />
      {slices.map((s, i) => (
        <circle
          key={i}
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke={s.color}
          strokeWidth={strokeWidth}
          strokeDasharray={`${s.arc} ${s.gap}`}
          strokeDashoffset={s.dashoffset}
          strokeLinecap="butt"
          transform={`rotate(-90 ${center} ${center})`}
        />
      ))}
    </svg>
  );
}

export function PieChart({ title, description, data }: PieChartComponentProps) {
  const hasData = Array.isArray(data) && data.length > 0;
  const total = hasData
    ? data.reduce((sum, d) => sum + (Number(d.value) || 0), 0)
    : 0;

  return (
    <div
      data-testid="pie-chart"
      className="max-w-lg mx-auto my-4 overflow-hidden rounded-lg border border-[var(--border)] bg-[var(--card)]"
    >
      <div className="p-6 pb-0">
        <h3 className="text-lg font-semibold leading-none tracking-tight text-[var(--foreground)]">
          {title}
        </h3>
        {description ? (
          <p className="text-sm text-[var(--muted-foreground)]">
            {description}
          </p>
        ) : null}
      </div>
      <div className="p-6 pt-4">
        {hasData ? (
          <>
            <DonutChart data={data} />
            <div className="space-y-2 pt-4">
              {data.map((item, i) => {
                const val = Number(item.value) || 0;
                const pct = total > 0 ? ((val / total) * 100).toFixed(0) : 0;
                return (
                  <div key={i} className="flex items-center gap-3 text-sm">
                    <span
                      className="inline-block h-3 w-3 rounded-full shrink-0"
                      style={{
                        backgroundColor: CHART_COLORS[i % CHART_COLORS.length],
                      }}
                    />
                    <span className="flex-1 text-[var(--foreground)] truncate">
                      {item.label}
                    </span>
                    <span className="text-[var(--muted-foreground)] tabular-nums">
                      {val.toLocaleString()}
                    </span>
                    <span className="text-[var(--muted-foreground)] text-sm w-10 text-right tabular-nums">
                      {pct}%
                    </span>
                  </div>
                );
              })}
            </div>
          </>
        ) : (
          <p className="text-[var(--muted-foreground)] text-center py-8 text-sm">
            No data available
          </p>
        )}
      </div>
    </div>
  );
}

