"use client";

// Shared State (Read-only) — the UI publishes a recipe to the agent via
// `agent.setState`; the agent reads that recipe on every turn but does
// not mutate it (the wired graph is the neutral default agent with no
// tools — see manifest entry `shared-state-read`).
//
// Single source of truth: `agent.state.recipe`. The form is a pure
// controlled component on top of that — every edit flows straight into
// `agent.setState({...})` and the next render reflects it.

import React, { useEffect } from "react";
import {
  CopilotKit,
  CopilotSidebar,
  useAgent,
  UseAgentUpdate,
  useConfigureSuggestions,
  useCopilotKit,
} from "@copilotkit/react-core/v2";
import { RecipeCard } from "./recipe-card";
import { INITIAL_RECIPE } from "./types";
import type { RecipeAgentState, RecipeData } from "./types";

export default function SharedStateReadDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="shared-state-read">
      <div className="min-h-screen w-full bg-gray-50">
        <div className="mx-auto max-w-2xl px-4 py-8 md:py-12">
          <Recipe />
        </div>
        <CopilotSidebar
          defaultOpen
          labels={{ modalHeaderTitle: "AI Recipe Assistant" }}
        />
      </div>
    </CopilotKit>
  );
}

function Recipe() {
  const { agent } = useAgent({
    agentId: "shared-state-read",
    updates: [UseAgentUpdate.OnStateChanged, UseAgentUpdate.OnRunStatusChanged],
  });
  const { copilotkit } = useCopilotKit();

  useConfigureSuggestions({
    suggestions: [
      {
        title: "Create Italian recipe",
        message: "Create a delicious Italian pasta recipe.",
      },
      {
        title: "Make it healthier",
        message: "Make the recipe healthier with more vegetables.",
      },
      {
        title: "Suggest variations",
        message: "Suggest some creative variations of this recipe.",
      },
    ],
    available: "always",
  });

  // Seed the initial recipe into agent state once so the agent has
  // something to read on the first turn. After this, every edit lands
  // via `agent.setState` below.
  useEffect(() => {
    if (!(agent.state as RecipeAgentState | undefined)?.recipe) {
      agent.setState({ recipe: INITIAL_RECIPE } satisfies RecipeAgentState);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const recipe =
    (agent.state as RecipeAgentState | undefined)?.recipe ?? INITIAL_RECIPE;

  const handleChange = (next: RecipeData) => {
    agent.setState({ recipe: next } satisfies RecipeAgentState);
  };

  const handleImprove = () => {
    if (agent.isRunning) return;
    agent.addMessage({
      id: crypto.randomUUID(),
      role: "user",
      content: "Improve the recipe",
    });
    void copilotkit
      .runAgent({ agent })
      .catch((err) =>
        console.error("[shared-state-read] runAgent failed", err),
      );
  };

  return (
    <RecipeCard
      recipe={recipe}
      isLoading={agent.isRunning}
      onChange={handleChange}
      onImprove={handleImprove}
    />
  );
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { LangGraphAgent } from "@copilotkit/runtime/langgraph";
import crypto from "node:crypto";

// Emit a structured server-side error log with a correlation id so the
// 500 we return to the client carries no stack/message details (which
// can leak internal config, prompts, or upstream URLs) while operators
// can still grep logs for the same `errorId` to find the full failure.
function logRouteError(err: unknown): string {
  const error = err instanceof Error ? err : new Error(String(err));
  const errorId = crypto.randomUUID();
  console.error(
    JSON.stringify({
      at: new Date().toISOString(),
      level: "error",
      phase: "setup",
      errorId,
      message: error.message,
      stack: error.stack,
    }),
  );
  return errorId;
}

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8123";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

function createAgent(
  graphId: string = "sample_agent",
  options: { recursionLimit?: number } = {},
) {
  // LangGraph's `recursion_limit` defaults to 25 (langchain_core), and
  // `with_config` in Python doesn't propagate when the graph is invoked via
  // the langgraph server's runs API — the `.with_config(...)` wrapper on the
  // graph object isn't visible to the assistant config the server builds per
  // run. Bake the limit into `assistantConfig` here so it travels with every
  // run we kick off through this route. Without this, multi-step graphs like
  // `gen_ui_agent` (which walks ~15 supersteps of set_steps calls, more once
  // prior turns accumulate in the thread) hit the default 25 mid-run and the
  // final state-publishing tool call never streams — the state card then
  // shows stale content from the previous pill. Mirrors langgraph-python.
  return new LangGraphAgent({
    deploymentUrl: `${AGENT_URL}/`,
    graphId,
    assistantConfig: { recursion_limit: options.recursionLimit ?? 100 },
  });
}

const agentNames = [
  "human_in_the_loop",
  "shared-state-read",
  "shared-state-write",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
];

const agents: Record<string, LangGraphAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent();
}

// Dedicated-graph agents for tool-rendering + reasoning demos.
agents["tool-rendering"] = createAgent("tool_rendering");
agents["tool-rendering-default-catchall"] = createAgent("tool_rendering");
agents["tool-rendering-custom-catchall"] = createAgent("tool_rendering");
agents["tool-rendering-reasoning-chain"] = createAgent(
  "tool_rendering_reasoning_chain",
);
// Reasoning variants. The Custom demo (`reasoning-custom`) and the
// Default demo (`reasoning-default`) both share the same backend graph;
// the only difference is whether the frontend overrides the
// `messageView.reasoningMessage` slot. Mirrors langgraph-python.
agents["reasoning-custom"] = createAgent("reasoning_agent");
agents["reasoning-default"] = createAgent("reasoning_agent");

// Agentic Generative UI — dedicated `gen_ui_agent` graph. The agent defines
// its own `steps` state + a `set_steps` tool the model calls to publish plan
// progress; the frontend subscribes via `useAgent`. Previously this name fell
// through the neutral-assistant loop to `sample_agent`, which has no `steps`
// state or `set_steps` tool, so the demo never rendered a progress card.
agents["gen-ui-agent"] = createAgent("gen_ui_agent");

// Interrupt variants — share the dedicated `interrupt_agent` graph that uses
// langgraph's `interrupt()` primitive inside `schedule_meeting`.
agents["gen-ui-interrupt"] = createAgent("interrupt_agent");
agents["interrupt-headless"] = createAgent("interrupt_agent");

// Dedicated-graph agents — each cell has its own LangGraph graph with a
// tailored system prompt (tools=[], CopilotKitMiddleware attached).
agents["frontend_tools"] = createAgent("frontend_tools");
agents["frontend-tools-async"] = createAgent("frontend_tools_async");
agents["hitl-in-app"] = createAgent("hitl_in_app");
// In-Chat HITL via the high-level `useHumanInTheLoop` hook — backend
// agent has zero tools; the frontend-registered `book_call` tool is
// injected into the LLM's tool list by `CopilotKitMiddleware`. Both
// the canonical `hitl-in-chat` demo and the `hitl-in-chat-booking`
// alias share the same backend graph.
agents["hitl-in-chat"] = createAgent("hitl_in_chat");
agents["hitl-in-chat-booking"] = createAgent("hitl_in_chat");
// HITL step-selection: dedicated graph with tools=[] + CopilotKitMiddleware.
// The `human_in_the_loop` alias in the neutral-assistant loop above maps to
// `sample_agent` which has 7+ backend tools and a custom AgentState — the
// frontend-only `generate_task_steps` tool (from useHumanInTheLoop) is the
// ONLY tool this demo needs, so a minimal graph avoids state/tool contention.
agents["human_in_the_loop"] = createAgent("hitl_steps");
agents["readonly-state-agent-context"] = createAgent(
  "readonly_state_agent_context",
);

// Shared State (Read + Write) — bidirectional shared state between UI and
// agent. UI writes `preferences` via agent.setState; middleware reads them
// into the system prompt; agent writes `notes` back via the `set_notes` tool.
agents["shared-state-read-write"] = createAgent("shared_state_read_write");

// Sub-Agents — supervisor delegates to research_agent / writing_agent /
// critique_agent (each a full create_agent under the hood). Every delegation
// is appended to `state.delegations` for live UI rendering.
agents["subagents"] = createAgent("subagents");

// Agentic Chat — dedicated neutral-assistant graph (tools=[] +
// CopilotKitMiddleware). Previously fell through to `sample_agent`. Mirrors
// langgraph-python.
agents["agentic_chat"] = createAgent("agentic_chat");
// Tool-Based Generative UI — chart-viz system prompt lives in its own graph.
// The frontend registers render_bar_chart / render_pie_chart via useComponent;
// CopilotKitMiddleware injects them into the model request. Mirrors
// langgraph-python.
agents["gen-ui-tool-based"] = createAgent("gen_ui_tool_based");
// Shared State: Streaming — dedicated graph with the write_document tool +
// StateStreamingMiddleware for per-token state-delta streaming. Mirrors
// langgraph-python.
agents["shared-state-streaming"] = createAgent("shared_state_streaming");
// Thread-id frontend-tool round-trip — reuses the frontend_tools graph
// (no dedicated graph needed). Mirrors langgraph-python.
agents["threadid-frontend-tool-roundtrip"] = createAgent("frontend_tools");

agents["default"] = createAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    // Log full message + stack server-side under a correlation id; return
    // only the id to the client so we don't leak internal details (upstream
    // URLs, env-driven config, prompts, etc.) into HTTP responses.
    const errorId = logRouteError(error);
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/ok`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
  });
};

"use client";

import React from "react";
import { Sparkles, X } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import { Spinner } from "@/components/ui/spinner";
import { Textarea } from "@/components/ui/textarea";

import {
  cookingTimeValues,
  type Ingredient,
  type RecipeData,
  SkillLevel,
  SpecialPreferences,
} from "./types";

export interface RecipeCardProps {
  recipe: RecipeData;
  isLoading: boolean;
  onChange: (next: RecipeData) => void;
  onImprove: () => void;
}

export function RecipeCard({
  recipe,
  isLoading,
  onChange,
  onImprove,
}: RecipeCardProps) {
  const update = (partial: Partial<RecipeData>) => {
    onChange({ ...recipe, ...partial });
  };

  const updateIngredient = (
    index: number,
    field: keyof Ingredient,
    value: string,
  ) => {
    const next = [...recipe.ingredients];
    next[index] = { ...next[index], [field]: value };
    update({ ingredients: next });
  };

  const updateInstruction = (index: number, value: string) => {
    const next = [...recipe.instructions];
    next[index] = value;
    update({ instructions: next });
  };

  const cookingTimeIndex = String(
    cookingTimeValues.find((t) => t.label === recipe.cooking_time)?.value ?? 3,
  );

  return (
    <form data-testid="recipe-card">
      <Card className="gap-0 border-border/60 py-0 shadow-xs">
        <CardContent className="space-y-6 px-6 py-6 md:px-8 md:py-8">
          <header className="space-y-3">
            <Input
              type="text"
              value={recipe.title || ""}
              onChange={(e) => update({ title: e.target.value })}
              aria-label="Recipe title"
              className="h-auto border-0 bg-transparent px-0 py-1 text-2xl font-bold shadow-none focus-visible:ring-0 md:text-3xl"
            />

            <div className="flex flex-wrap items-center gap-3">
              <div className="flex items-center gap-2">
                <span aria-hidden>🕒</span>
                <Select
                  value={cookingTimeIndex}
                  onValueChange={(value) =>
                    update({
                      cooking_time: cookingTimeValues[Number(value)].label,
                    })
                  }
                >
                  <SelectTrigger size="sm" aria-label="Cooking time">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {cookingTimeValues.map((time) => (
                      <SelectItem key={time.value} value={String(time.value)}>
                        {time.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="flex items-center gap-2">
                <span aria-hidden>🏆</span>
                <Select
                  value={recipe.skill_level}
                  onValueChange={(value) =>
                    update({ skill_level: value as SkillLevel })
                  }
                >
                  <SelectTrigger size="sm" aria-label="Skill level">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {Object.values(SkillLevel).map((level) => (
                      <SelectItem key={level} value={level}>
                        {level}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </header>

          <Separator />

          <section className="space-y-3">
            <h2 className="text-base font-semibold">Dietary Preferences</h2>
            <div className="flex flex-wrap gap-2">
              {Object.values(SpecialPreferences).map((option) => {
                const selected = recipe.special_preferences.includes(option);
                return (
                  <button
                    key={option}
                    type="button"
                    onClick={() =>
                      update({
                        special_preferences: selected
                          ? recipe.special_preferences.filter(
                              (p) => p !== option,
                            )
                          : [...recipe.special_preferences, option],
                      })
                    }
                    aria-pressed={selected}
                    className="rounded-full focus:outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
                  >
                    <Badge
                      variant={selected ? "default" : "outline"}
                      className="cursor-pointer px-3 py-1 text-sm"
                    >
                      {option}
                    </Badge>
                  </button>
                );
              })}
            </div>
          </section>

          <Separator />

          <section className="space-y-3">
            <div className="flex items-center justify-between">
              <h2 className="text-base font-semibold">Ingredients</h2>
              <Button
                data-testid="add-ingredient-button"
                type="button"
                variant="ghost"
                size="sm"
                onClick={() =>
                  update({
                    ingredients: [
                      ...recipe.ingredients,
                      { icon: "🍴", name: "", amount: "" },
                    ],
                  })
                }
              >
                + Add Ingredient
              </Button>
            </div>
            <div data-testid="ingredients-container" className="space-y-2">
              {recipe.ingredients.map((ingredient, index) => (
                <div
                  key={index}
                  data-testid="ingredient-card"
                  className="flex items-center gap-3 rounded-lg border border-border/50 bg-muted/30 p-3"
                >
                  <div className="shrink-0 text-2xl" aria-hidden>
                    {ingredient.icon || "🍴"}
                  </div>
                  <div className="grid min-w-0 flex-1 grid-cols-1 gap-2 sm:grid-cols-[1fr_8rem]">
                    <Input
                      type="text"
                      value={ingredient.name || ""}
                      onChange={(e) =>
                        updateIngredient(index, "name", e.target.value)
                      }
                      placeholder="Ingredient name"
                    />
                    <Input
                      type="text"
                      value={ingredient.amount || ""}
                      onChange={(e) =>
                        updateIngredient(index, "amount", e.target.value)
                      }
                      placeholder="Amount"
                    />
                  </div>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    aria-label="Remove ingredient"
                    className="shrink-0 text-muted-foreground hover:text-destructive"
                    onClick={() =>
                      update({
                        ingredients: recipe.ingredients.filter(
                          (_, i) => i !== index,
                        ),
                      })
                    }
                  >
                    <X />
                  </Button>
                </div>
              ))}
            </div>
          </section>

          <Separator />

          <section className="space-y-3">
            <div className="flex items-center justify-between">
              <h2 className="text-base font-semibold">Instructions</h2>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() =>
                  update({ instructions: [...recipe.instructions, ""] })
                }
              >
                + Add Step
              </Button>
            </div>
            <div data-testid="instructions-container" className="space-y-3">
              {recipe.instructions.map((instruction, index) => (
                <div key={index} className="flex items-start gap-3">
                  <div className="mt-1 flex size-7 shrink-0 items-center justify-center rounded-full bg-primary text-sm font-bold text-primary-foreground">
                    {index + 1}
                  </div>
                  <div className="relative flex-1">
                    <Textarea
                      value={instruction || ""}
                      onChange={(e) => updateInstruction(index, e.target.value)}
                      placeholder="Enter cooking instruction..."
                      rows={2}
                    />
                  </div>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    aria-label="Remove step"
                    className="mt-1 shrink-0 text-muted-foreground hover:text-destructive"
                    onClick={() =>
                      update({
                        instructions: recipe.instructions.filter(
                          (_, i) => i !== index,
                        ),
                      })
                    }
                  >
                    <X />
                  </Button>
                </div>
              ))}
            </div>
          </section>

          <Separator />

          <div className="flex justify-center">
            <Button
              data-testid="improve-button"
              type="button"
              size="lg"
              onClick={onImprove}
              disabled={isLoading}
            >
              {isLoading ? (
                <>
                  <Spinner />
                  Please Wait...
                </>
              ) : (
                <>
                  <Sparkles />
                  Improve with AI
                </>
              )}
            </Button>
          </div>
        </CardContent>
      </Card>
    </form>
  );
}

