console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    // Log full message + stack server-side under a correlation id; return
    // only the id to the client so we don't leak internal details (upstream
    // URLs, env-driven config, prompts, etc.) into HTTP responses.
    const errorId = logRouteError(error);
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/ok`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
  });
};

import { Delegation, SubAgentName } from "./delegation-log";

// Inspect the live message stream to find the most recent supervisor
// tool call to a sub-agent that has not yet produced a ToolMessage
// reply. Falls back to `null` when there is no in-flight delegation.
//
// This is intentionally defensive — the v2 message shape can vary
// across runtime versions, so we structurally probe instead of
// relying on a specific TS type.
type RawToolCall = {
  id?: string | null;
  function?: { name?: string | null; arguments?: string | null } | null;
};

type RawMessage = {
  role?: string;
  toolCalls?: RawToolCall[] | null;
  toolCallId?: string | null;
  content?: unknown;
};

export function inferActiveSubAgent(
  delegations: Delegation[],
  messages: unknown,
): { subAgent: SubAgentName; task: string } | null {
  const msgs: RawMessage[] = Array.isArray(messages)
    ? (messages as RawMessage[])
    : [];

  // Collect every tool_call_id that already has a matching tool reply.
  const repliedIds = new Set<string>();
  for (const m of msgs) {
    if (m.role === "tool" && typeof m.toolCallId === "string") {
      repliedIds.add(m.toolCallId);
    }
  }

  const SUB_AGENT_NAMES: ReadonlySet<SubAgentName> = new Set<SubAgentName>([
    "research_agent",
    "writing_agent",
    "critique_agent",
  ]);

  // Walk newest → oldest and return the most recent unanswered call.
  for (let i = msgs.length - 1; i >= 0; i--) {
    const m = msgs[i];
    if (!m || m.role !== "assistant" || !Array.isArray(m.toolCalls)) continue;
    for (let j = m.toolCalls.length - 1; j >= 0; j--) {
      const call = m.toolCalls[j];
      const name = call?.function?.name;
      if (typeof name !== "string") continue;
      if (!SUB_AGENT_NAMES.has(name as SubAgentName)) continue;
      if (typeof call?.id === "string" && repliedIds.has(call.id)) continue;
      const task = extractTask(call?.function?.arguments);
      return { subAgent: name as SubAgentName, task };
    }
  }

  // Fall back: if delegations is non-empty but the supervisor is still
  // running, surface the most recent delegation as a soft signal.
  if (delegations.length > 0) {
    const last = delegations[delegations.length - 1];
    if (last && last.status !== "completed") {
      return { subAgent: last.sub_agent, task: last.task };
    }
  }
  return null;
}

function extractTask(rawArgs: string | null | undefined): string {
  if (!rawArgs) return "(preparing task…)";
  // Streaming tool args may be a partial JSON string. Try a strict
  // parse first, then fall back to a regex sniff for `"task": "..."`.
  try {
    const parsed = JSON.parse(rawArgs);
    if (parsed && typeof parsed === "object" && "task" in parsed) {
      const t = (parsed as { task?: unknown }).task;
      if (typeof t === "string" && t.trim().length > 0) return t;
    }
  } catch {
    const match = rawArgs.match(/"task"\s*:\s*"((?:[^"\\]|\\.)*)/);
    if (match && match[1].length > 0) {
      try {
        return JSON.parse(`"${match[1]}"`);
      } catch {
        return match[1];
      }
    }
  }
  return "(preparing task…)";
}

"use client";

import React from "react";

export type SubAgentName =
  | "research_agent"
  | "writing_agent"
  | "critique_agent";

export interface Delegation {
  id: string;
  sub_agent: SubAgentName;
  task: string;
  status: "completed";
  result: string;
}

export interface DelegationLogProps {
  delegations: Delegation[];
  /** True while the supervisor is actively running. */
  isRunning: boolean;
}

const SUB_AGENT_STYLE: Record<
  SubAgentName,
  { label: string; color: string; emoji: string }
> = {
  research_agent: {
    label: "Research",
    color: "bg-[#BEC2FF1A] text-[#010507] border-[#BEC2FF]",
    emoji: "🔎",
  },
  writing_agent: {
    label: "Writing",
    color: "bg-[#85ECCE]/15 text-[#189370] border-[#85ECCE4D]",
    emoji: "✍️",
  },
  critique_agent: {
    label: "Critique",
    color: "bg-[#FFAC4D]/12 text-[#010507] border-[#FFAC4D33]",
    emoji: "🧐",
  },
};

/**
 * Live delegation log — renders the `delegations` slot of agent state.
 *
 * Each entry corresponds to one invocation of a sub-agent. The list
 * grows in real time as the supervisor fans work out to its children.
 * The parent header shows how many sub-agents have been called and
 * whether the supervisor is still running.
 */
// Fixed list of the three sub-agent roles the supervisor can call.
// Rendered as always-visible indicator chips at the top of the log
// (regardless of whether the supervisor has delegated yet) so the user
// — and the e2e suite — can see at a glance which sub-agents exist and
// which are currently active.
const INDICATOR_ROLES: ReadonlyArray<{
  role: "researcher" | "writer" | "critic";
  subAgent: SubAgentName;
}> = [
  { role: "researcher", subAgent: "research_agent" },
  { role: "writer", subAgent: "writing_agent" },
  { role: "critic", subAgent: "critique_agent" },
];

export function DelegationLog({ delegations, isRunning }: DelegationLogProps) {
  const calledRoles = new Set<SubAgentName>(
    delegations.map((d) => d.sub_agent),
  );

  return (
    <div
      data-testid="delegation-log"
      className="w-full h-full flex flex-col bg-white rounded-2xl shadow-sm border border-[#DBDBE5] overflow-hidden"
    >
      <div className="flex items-center justify-between px-6 py-3 border-b border-[#E9E9EF] bg-[#FAFAFC]">
        <div className="flex items-center gap-3">
          <span className="text-lg font-semibold text-[#010507]">
            Sub-agent delegations
          </span>
          {isRunning && (
            <span
              data-testid="supervisor-running"
              className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full border border-[#BEC2FF] bg-[#BEC2FF1A] text-[#010507] text-[10px] font-semibold uppercase tracking-[0.12em]"
            >
              <span className="w-1.5 h-1.5 rounded-full bg-[#010507] animate-pulse" />
              Supervisor running
            </span>
          )}
        </div>
        <span
          data-testid="delegation-count"
          className="text-xs font-mono text-[#838389]"
        >
          {delegations.length} calls
        </span>
      </div>

      <div
        data-testid="subagent-indicators"
        className="flex items-center gap-2 border-b border-[#E9E9EF] bg-white px-6 py-2"
      >
        {INDICATOR_ROLES.map(({ role, subAgent }) => {
          const style = SUB_AGENT_STYLE[subAgent];
          const fired = calledRoles.has(subAgent);
          return (
            <span
              key={role}
              data-testid={`subagent-indicator-${role}`}
              data-role={role}
              data-fired={fired ? "true" : "false"}
              className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold uppercase tracking-[0.1em] border ${style.color} ${
                fired ? "" : "opacity-60"
              }`}
            >
              <span aria-hidden>{style.emoji}</span>
              <span>{style.label}</span>
            </span>
          );
        })}
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {delegations.length === 0 ? (
          <p className="text-[#838389] italic text-sm">
            Ask the supervisor to complete a task. Every sub-agent it calls will
            appear here.
          </p>
        ) : (
          delegations.map((d, idx) => {
            const style = SUB_AGENT_STYLE[d.sub_agent];
            return (
              <div
                key={d.id}
                data-testid="delegation-entry"
                className="border border-[#E9E9EF] rounded-xl p-3 bg-[#FAFAFC]"
              >
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-mono text-[#AFAFB7]">
                      #{idx + 1}
                    </span>
                    <span
                      className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold uppercase tracking-[0.1em] border ${style.color}`}
                    >
                      <span>{style.emoji}</span>
                      <span>{style.label}</span>
                    </span>
                  </div>
                  <span className="text-[10px] uppercase tracking-[0.12em] font-semibold text-[#189370]">
                    {d.status}
                  </span>
                </div>
                <div className="text-xs text-[#57575B] mb-2">
                  <span className="font-semibold text-[#010507]">Task: </span>
                  {d.task}
                </div>
                <div className="text-sm text-[#010507] whitespace-pre-wrap bg-white rounded-lg p-2.5 border border-[#E9E9EF]">
                  {d.result}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

"use client";

import React from "react";
import { CopilotChat } from "@copilotkit/react-core/v2";

import { Delegation, SubAgentName, DelegationLog } from "./delegation-log";
import { SupervisorActivityBanner } from "./supervisor-activity-banner";

interface DemoLayoutProps {
  delegations: Delegation[];
  isRunning: boolean;
  activeSubAgent: { subAgent: SubAgentName; task: string } | null;
}

export function DemoLayout({
  delegations,
  isRunning,
  activeSubAgent,
}: DemoLayoutProps) {
  return (
    <div className="flex flex-col md:flex-row h-screen w-full bg-gray-50">
      <section className="flex-1 min-h-0 p-4">
        <DelegationLog delegations={delegations} isRunning={isRunning} />
      </section>
      <aside className="md:w-[420px] md:shrink-0 flex flex-col min-h-0 border-l border-[#DBDBE5] bg-white">
        {activeSubAgent && (
          <SupervisorActivityBanner
            subAgent={activeSubAgent.subAgent}
            task={activeSubAgent.task}
          />
        )}
        <CopilotChat
          agentId="subagents"
          className="flex-1 min-h-0"
          labels={{
            chatInputPlaceholder: "Give the supervisor a task...",
          }}
        />
      </aside>
    </div>
  );
}

"use client";

import React from "react";

import type { SubAgentName } from "./delegation-log";

// In-chat activity card for a single sub-agent invocation. Rendered
// inline in the assistant message stream via `useRenderTool` so the
// user can SEE which sub-agent is running and what task it received,
// without having to look at the side panel.
//
// One card per supervisor → sub-agent tool call. Status walks
// inProgress → executing → complete as the supervisor streams the
// tool args, the sub-agent runs, and the ToolMessage comes back.

export type SubAgentToolStatus = "inProgress" | "executing" | "complete";

const SUB_AGENT_META: Record<
  SubAgentName,
  {
    label: string;
    role: string;
    emoji: string;
    accent: string; // border + bg
    chip: string; // badge tone
  }
> = {
  research_agent: {
    label: "Researcher",
    role: "gathering facts",
    emoji: "🔎",
    accent: "border-[#BEC2FF] bg-[#BEC2FF]/15",
    chip: "border-[#BEC2FF] bg-[#BEC2FF1A] text-[#010507]",
  },
  writing_agent: {
    label: "Writer",
    role: "drafting prose",
    emoji: "✍️",
    accent: "border-[#85ECCE4D] bg-[#85ECCE]/10",
    chip: "border-[#85ECCE4D] bg-[#85ECCE]/20 text-[#189370]",
  },
  critique_agent: {
    label: "Critic",
    role: "reviewing the draft",
    emoji: "🧐",
    accent: "border-[#FFAC4D33] bg-[#FFAC4D]/10",
    chip: "border-[#FFAC4D33] bg-[#FFAC4D]/15 text-[#57575B]",
  },
};

export interface SubAgentActivityCardProps {
  subAgent: SubAgentName;
  task: string | undefined;
  status: SubAgentToolStatus;
  result: string | undefined;
}

// Map the backend tool name (`research_agent`, `writing_agent`,
// `critique_agent`) to the short role used in test selectors. The
// per-role `[data-testid="subagent-card-<role>"]` testid is the stable
// hook the e2e suite uses to count cards and assert per-card content.
const ROLE_TESTID: Record<SubAgentName, "researcher" | "writer" | "critic"> = {
  research_agent: "researcher",
  writing_agent: "writer",
  critique_agent: "critic",
};

export function SubAgentActivityCard({
  subAgent,
  task,
  status,
  result,
}: SubAgentActivityCardProps) {
  const meta = SUB_AGENT_META[subAgent];
  const done = status === "complete";
  const running = !done;
  const roleTestId = `subagent-card-${ROLE_TESTID[subAgent]}`;

  return (
    <div
      data-testid={roleTestId}
      data-subagent-card={ROLE_TESTID[subAgent]}
      data-sub-agent={subAgent}
      data-status={status}
      className={`my-3 overflow-hidden rounded-2xl border bg-white shadow-sm ${meta.accent}`}
    >
      <div className="flex items-center justify-between border-b border-[#E9E9EF] bg-[#FAFAFC] px-4 py-2.5">
        <div className="flex items-center gap-2">
          <span aria-hidden className="text-base leading-none">
            {meta.emoji}
          </span>
          <span className="text-sm font-semibold text-[#010507]">
            {meta.label}
          </span>
          <span className="text-[11px] text-[#838389]">
            {running ? `is ${meta.role}…` : `finished ${meta.role}`}
          </span>
        </div>
        <StatusBadge status={status} chipTone={meta.chip} />
      </div>

      <div className="grid gap-3 p-4 text-sm">
        <Section label="Task">
          {task ? (
            <p
              data-testid="subagent-activity-task"
              className="rounded-lg border border-[#E9E9EF] bg-[#FAFAFC] p-2.5 text-xs text-[#010507] whitespace-pre-wrap"
            >
              {task}
            </p>
          ) : (
            <p className="text-xs italic text-[#838389]">
              waiting for the supervisor to spell out the task…
            </p>
          )}
        </Section>

        <Section label="Result">
          {done ? (
            <div
              data-testid="subagent-result"
              data-subagent-result-role={ROLE_TESTID[subAgent]}
              className="rounded-lg border border-[#E9E9EF] bg-white p-2.5 text-xs text-[#010507] whitespace-pre-wrap"
            >
              {result?.trim() ? result : "(empty)"}
            </div>
          ) : (
            <p className="inline-flex items-center gap-2 text-xs italic text-[#57575B]">
              <span className="inline-block h-1.5 w-1.5 animate-pulse rounded-full bg-[#010507]" />
              {meta.label} is working…
            </p>
          )}
        </Section>
      </div>
    </div>
  );
}

function Section({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div>
      <div className="mb-1.5 text-[10px] font-medium uppercase tracking-[0.14em] text-[#838389]">
        {label}
      </div>
      {children}
    </div>
  );
}

function StatusBadge({
  status,
  chipTone,
}: {
  status: SubAgentToolStatus;
  chipTone: string;
}) {
  const label = describeStatus(status);
  return (
    <span
      data-testid="subagent-status"
      data-status={status}
      className={`rounded-full border px-2.5 py-0.5 text-[10px] font-medium uppercase tracking-[0.14em] ${chipTone}`}
    >
      {label}
    </span>
  );
}

function describeStatus(status: SubAgentToolStatus): string {
  switch (status) {
    case "inProgress":
      return "starting";
    case "executing":
      return "running";
    case "complete":
      return "done";
  }
}

"use client";

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export function useSubagentsSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Write a blog post",
        message:
          "Produce a short blog post about the benefits of cold exposure training. Research first, then write, then critique.",
      },
      {
        title: "Explain a topic",
        message:
          "Explain how large language models handle tool calling. Research, write a paragraph, then critique.",
      },
      {
        title: "Summarize a topic",
        message:
          "Summarize the current state of reusable rockets in 1 polished paragraph, with research and critique.",
      },
    ],
    available: "always",
  });
}

"use client";

import React from "react";

import { SubAgentName } from "./delegation-log";

// Compact sticky banner at the top of the chat panel that names the
// currently-running sub-agent + task. Keeps the user oriented even
// when the per-message activity card has scrolled out of view.
export function SupervisorActivityBanner({
  subAgent,
  task,
}: {
  subAgent: SubAgentName;
  task: string;
}) {
  const labels: Record<SubAgentName, string> = {
    research_agent: "Researcher",
    writing_agent: "Writer",
    critique_agent: "Critic",
  };
  return (
    <div
      data-testid="active-subagent-banner"
      className="flex items-start gap-2 border-b border-[#E9E9EF] bg-[#FAFAFC] px-4 py-2"
    >
      <span className="mt-1 inline-block h-1.5 w-1.5 shrink-0 animate-pulse rounded-full bg-[#010507]" />
      <div className="min-w-0 text-xs text-[#010507]">
        <span className="font-semibold">{labels[subAgent]}</span>
        <span className="text-[#57575B]"> is running:</span>{" "}
        <span className="text-[#57575B] line-clamp-2">{task}</span>
      </div>
    </div>
  );
}

