                      </div>
                      {selected && <Badge variant="success">on</Badge>}
                    </label>
                  );
                })}
              </div>
            </CardContent>
          </Card>

          {/* Published context — full-width JSON viewer */}
          <Card className="lg:col-span-3">
            <CardHeader>
              <div className="flex items-center justify-between">
