// Dedicated runtime for the Multimodal Attachments demo (Wave 2b).
//
// Why its own route? The backing graph (`multimodal`, from
// src/agents/multimodal_agent.py) runs a vision-capable model (gpt-4o). Every
// other cell in the showcase uses a text-only, cheaper model. Registering
// `multimodal` under the shared `/api/copilotkit` runtime would silently upgrade
// *all* cells that share that runtime to a vision model whenever the browser
// routed to this one — wasting tokens and blurring the per-demo cost boundary.
// A dedicated route keeps the vision capability — and its cost — scoped to
// exactly the cell that exercises it, matching the pattern used by
// `/api/copilotkit-beautiful-chat`.
//
// The page at src/app/demos/multimodal/page.tsx points its `runtimeUrl` at
// this endpoint and sets `agent="multimodal-demo"` (the slug registered below).

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { LangGraphAgent } from "@copilotkit/runtime/langgraph";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8123";

const multimodalAgent = new LangGraphAgent({
  deploymentUrl: `${AGENT_URL}/`,
  // graphId references the key in langgraph.json — must match the
  // "multimodal" entry that resolves to src/agents/src/multimodal_agent.py:graph.
  graphId: "multimodal",
});

const agents: Record<string, LangGraphAgent> = {
  // The page's <CopilotKit agent="multimodal-demo"> resolves here.
  "multimodal-demo": multimodalAgent,
  // Alias for any internal component that calls `useAgent()` without args
  // (matches the beautiful-chat route's "default" alias pattern).
  default: multimodalAgent,
};

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- see main route.ts; published CopilotRuntime's `agents`
        // type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects
        // plain Records. Fixed in source, pending release.
        agents,
      }),
      basePath: "/api/copilotkit-multimodal",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

import type { AttachmentUploadResult } from "@copilotkit/shared";

/**
 * `onUpload` must resolve to an `AttachmentUploadResult` (data or url). We
 * always return the `data` variant — the demo inlines base64 instead of
 * uploading to external storage, matching the Wave 2b spec.
 */
type DataUploadResult = Extract<AttachmentUploadResult, { type: "data" }>;

/**
 * Convert a File into the `AttachmentsConfig.onUpload` result shape —
 * inline base64 with the browser-provided mime type. We do this in the
 * browser rather than uploading to external storage because Wave 2b is a
 * self-contained demo; `maxSize: 10 MB` (set below) caps bloat.
 *
 * `FileReader` produces a `data:<mime>;base64,<payload>` URL; we strip the
 * prefix so the runtime forwards the raw base64 value (what the agent
 * expects in `source.value`).
 */
export function fileToDataAttachment(file: File): Promise<DataUploadResult> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () =>
      reject(reader.error ?? new Error(`FileReader failed for ${file.name}`));
    reader.onload = () => {
      const result = reader.result;
      if (typeof result !== "string") {
        reject(new Error(`Unexpected FileReader result type for ${file.name}`));
        return;
      }
      // result looks like "data:image/png;base64,iVBORw0K..." — strip the prefix.
      const commaIdx = result.indexOf(",");
      const base64 = commaIdx >= 0 ? result.slice(commaIdx + 1) : result;
      resolve({
        type: "data",
        value: base64,
        mimeType: file.type || "application/octet-stream",
        metadata: {
          filename: file.name,
          size: file.size,
        },
      });
    };
    reader.readAsDataURL(file);
  });
}

"use client";

/**
 * Legacy-shape rewrite + media-dedupe shim.
 *
 * Three problems this fixes:
 *
 * 1. **Outgoing modern parts are invisible to the agent.** The published
 *    `@ag-ui/langgraph` converter (0.0.x) only understands the legacy
 *    `{ type: "binary", mimeType, data | url }` shape when forwarding
 *    AG-UI messages to LangChain. Modern
 *    `{ type: "image" | "document", source: { type, value, mimeType } }`
 *    parts are silently dropped. In `onRunInitialized` we walk the
 *    outgoing user message and APPEND a legacy `binary` mirror after
 *    every modern media part — we cannot REPLACE the modern part with
 *    `binary` because `CopilotChatUserMessage`'s `getMediaParts` only
 *    renders `image|audio|video|document`, so replacing would make the
 *    attachment visually disappear from the chat once the run snapshot
 *    round-trips through state. APPEND keeps both forms: the modern
 *    part stays for the UI, the legacy `binary` feeds the converter.
 *
 * 2. **Round-tripped media comes back doubled and mistyped.** The
 *    converter sends our `binary` parts out as LangChain `image_url`
 *    and pulls incoming `image_url` parts back in as AG-UI `image`
 *    regardless of mimeType, so PDFs come back as `type: "image"` with
 *    `mimeType: "application/pdf"` and fall to `ImageAttachment` (which
 *    renders a broken `<img>`). The user's original modern part also
 *    survives in state, so the chat shows TWO chips per attachment. On
 *    every `onMessagesSnapshotEvent` and `onRunFinalized` we dedupe by
 *    `source.value` and re-key the `type` field from the mimeType so
 *    PDFs route to `DocumentAttachment` (icon + filename) and images
 *    to `ImageAttachment`.
 */

import { useEffect, useMemo } from "react";
import { useAgent } from "@copilotkit/react-core/v2";

/**
 * Minimal structural shape of an AG-UI message. `@ag-ui/client`'s
 * exported `Message` is a tagged union by role, but for the rewrite
 * we only care about the `user` branch and treat every other role as
 * pass-through. Keeping the type local avoids pulling `@ag-ui/client`
 * into this package's direct dependencies.
 */
type AgentMessage = {
  id?: string;
  role: string;
  content?: unknown;
};

/**
 * Builds the legacy `binary` content part that mirrors a modern
 * `image | document | audio | video` part. Returns `null` if the input
 * is not a multimodal part we need to mirror, or if the part is already
 * a legacy `binary` (idempotent).
 *
 * The published `@ag-ui/langgraph` converter (see `aguiMessagesToLangChain`)
 * only recognizes legacy `binary` parts; modern parts are silently
 * filtered out. We APPEND the legacy mirror alongside the modern part
 * rather than replacing it, because `CopilotChatUserMessage`'s
 * `getMediaParts` only renders `image|audio|video|document` — replacing
 * the modern part with `binary` makes the attachment visually disappear
 * from the chat once the agent run completes (the run-state snapshot
 * round-trips through state and re-renders the user message). Keeping
 * both forms gives the UI something to render AND the converter
 * something to read.
 */
function legacyBinaryFor(part: unknown): unknown | null {
  if (!part || typeof part !== "object") return null;
  const candidate = part as {
    type?: string;
    source?: {
      type?: string;
      value?: string;
      mimeType?: string;
    };
  };
  const type = candidate.type;
  if (
    type !== "image" &&
    type !== "document" &&
    type !== "audio" &&
    type !== "video"
  ) {
    return null;
  }
  const source = candidate.source;
  if (!source || typeof source.value !== "string") {
    return null;
  }
  const mimeType = source.mimeType ?? "application/octet-stream";
  if (source.type === "data") {
    return { type: "binary", mimeType, data: source.value };
  }
  if (source.type === "url") {
    return { type: "binary", mimeType, url: source.value };
  }
  return null;
}

/**
 * Walks a message list and APPENDS a legacy `binary` mirror after every
 * modern `image|document|audio|video` part on user messages, so the
 * outgoing payload contains both forms. Non-user messages, plain-string
 * user messages, and parts that already have a sibling `binary` mirror
 * pass through untouched (idempotent: re-running on already-augmented
 * messages is a no-op).
 *
 * Returns null if nothing changed so the subscriber in
 * `onRunInitialized` can skip a superfluous state write.
 */
function rewriteMessagesForLegacyConverter(
  messages: ReadonlyArray<Readonly<AgentMessage>>,
): AgentMessage[] | null {
  let mutated = false;
  const next = messages.map((message) => {
    if (message.role !== "user") return message as AgentMessage;
    const content = message.content;
    if (!Array.isArray(content)) return message as AgentMessage;

    // Build a key set of `binary` parts already in the message so we
    // don't double-append on a second run.
    const existingBinaryKeys = new Set<string>();
    for (const part of content) {
      if (
        part &&
        typeof part === "object" &&
        (part as { type?: string }).type === "binary"
      ) {
        const p = part as { mimeType?: string; data?: string; url?: string };
        existingBinaryKeys.add(`${p.mimeType ?? ""}::${p.data ?? p.url ?? ""}`);
      }
    }

    let partMutated = false;
    const augmentedParts: unknown[] = [];
    for (const part of content) {
      augmentedParts.push(part);
      const mirror = legacyBinaryFor(part);
      if (!mirror) continue;
      const m = mirror as {
        mimeType?: string;
        data?: string;
        url?: string;
      };
      const key = `${m.mimeType ?? ""}::${m.data ?? m.url ?? ""}`;
      if (existingBinaryKeys.has(key)) continue;
      existingBinaryKeys.add(key);
      augmentedParts.push(mirror);
      partMutated = true;
    }
    if (!partMutated) return message as AgentMessage;
    mutated = true;
    return {
      ...(message as object),
      content: augmentedParts,
    } as AgentMessage;
  });
  return mutated ? next : null;
}

/**
 * Normalize + dedupe media content parts within each user message:
 *
 * 1. **Type normalization.** The @ag-ui/langgraph round-trip through
 *    LangChain emits incoming media parts as `type: "image"` regardless
 *    of the actual mimeType — including `application/pdf` and other
 *    non-image documents — because the converter generates them from
 *    LangChain `image_url` parts indiscriminately. The chat
 *    user-message renderer dispatches by `type` to either
 *    `ImageAttachment` (renders an `<img>`) or `DocumentAttachment`
 *    (renders an icon + filename). A PDF tagged as `image` falls to
 *    `<img>`, fails to load, and shows "Failed to load image" instead
 *    of a PDF chip. Re-key the part type from the mimeType so the
 *    correct renderer fires.
 *
 * 2. **Dedupe by source value.** The same attachment ends up in the
 *    user message twice: once as the modern part the client added,
 *    once as the re-converted shape the snapshot pushes. Strip
 *    duplicates by `source.value` (or `source.url`) regardless of
 *    type so both forms collapse to a single chip.
 */
function normalizePartType(type: string, mimeType: string | undefined): string {
  if (type !== "image" && type !== "document") return type;
  if (!mimeType) return type;
  if (mimeType.startsWith("image/")) return "image";
  if (mimeType.startsWith("audio/")) return "audio";
  if (mimeType.startsWith("video/")) return "video";
  return "document";
}

function dedupeUserMessageMedia(
  messages: ReadonlyArray<Readonly<AgentMessage>>,
): AgentMessage[] | null {
  let mutated = false;
  const next = messages.map((message) => {
    if (message.role !== "user") return message as AgentMessage;
    const content = message.content;
    if (!Array.isArray(content)) return message as AgentMessage;
    const seen = new Set<string>();
    const kept: unknown[] = [];
    let partMutated = false;
    for (const part of content) {
      if (!part || typeof part !== "object") {
        kept.push(part);
        continue;
      }
      const p = part as {
        type?: string;
        source?: { value?: string; url?: string; mimeType?: string };
        data?: string;
        url?: string;
        mimeType?: string;
      };
      const isMedia =
        p.type === "image" ||
        p.type === "document" ||
        p.type === "audio" ||
        p.type === "video";
      if (!isMedia) {
        kept.push(part);
        continue;
      }
      const sourceValue = p.source?.value ?? p.source?.url ?? "";
      if (seen.has(sourceValue)) {
        partMutated = true;
        continue;
      }
      seen.add(sourceValue);
      const normalizedType = normalizePartType(
        p.type ?? "",
        p.source?.mimeType ?? p.mimeType,
      );
      if (normalizedType !== p.type) {
        kept.push({ ...p, type: normalizedType });
        partMutated = true;
      } else {
        kept.push(part);
      }
    }
    if (!partMutated) return message as AgentMessage;
    mutated = true;
    return { ...(message as object), content: kept } as AgentMessage;
  });
  return mutated ? next : null;
}

/**
 * Installs the subscribers on the active agent. Scoped to a small inner
 * component so it can use the `useAgent` hook the <CopilotChat> parent
 * already relies on — subscribing there means we rewrite messages on the
 * *same* agent instance CopilotChat dispatches through, even when threads
 * are cloned or swapped.
 */
export function LegacyConverterShim() {
  const { agent } = useAgent({ agentId: "multimodal-demo" });

  const subscriber = useMemo(
    () => ({
      onRunInitialized: ({
        messages,
      }: {
        messages: ReadonlyArray<Readonly<AgentMessage>>;
      }) => {
        const rewritten = rewriteMessagesForLegacyConverter(messages);
        if (!rewritten) return;
        return { messages: rewritten };
      },
      // After every messages snapshot from the server, strip duplicate
      // media parts and normalize types that the @ag-ui/langgraph
      // round-trip mangled. We hook both `onMessagesSnapshotEvent` and
      // `onRunFinalized` to catch incremental events too — the
      // snapshot fires once at run end, the run-finalized hook fires
      // when the agent transitions out of running.
      onMessagesSnapshotEvent: ({
        messages,
      }: {
        messages: ReadonlyArray<Readonly<AgentMessage>>;
      }) => {
        const deduped = dedupeUserMessageMedia(messages);
        if (!deduped) return;
        return { messages: deduped };
      },
      onRunFinalized: ({
        messages,
      }: {
        messages: ReadonlyArray<Readonly<AgentMessage>>;
      }) => {
        const deduped = dedupeUserMessageMedia(messages);
        if (!deduped) return;
        return { messages: deduped };
      },
    }),
    [],
  );

  useEffect(() => {
    if (!agent) return;
    // AG-UI's AgentSubscriber type is tagged by role; our shim uses a
    // structural message shape and returns only partial mutations, so
    // cast at the subscribe boundary. The cast is safe: our handlers
    // only ever return a messages-mutation or void.
    const handle = agent.subscribe(
      subscriber as unknown as Parameters<typeof agent.subscribe>[0],
    );
    return () => handle.unsubscribe();
  }, [agent, subscriber]);

  return null;
}

"use client";

import { useCallback } from "react";
import { CopilotChat } from "@copilotkit/react-core/v2";
import { fileToDataAttachment } from "./file-to-data-attachment";
import { SampleAttachmentButtons } from "./sample-attachment-buttons";

const MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024; // 10 MB
const ACCEPT_MIME = "image/*,application/pdf";

export function MultimodalChat() {
  // `onUpload` is passed into CopilotChat's `AttachmentsConfig`. Both the
  // paperclip button and the sample-injection path route files through
  // this same function (sample buttons drive CopilotChat's hidden file
  // input, which calls this internally via `useAttachments`). No
  // duplicated upload code lives in the sample-button component.
  const onUpload = useCallback(fileToDataAttachment, []);

  return (
    <>
      {/*
       * Scoped CSS:
       * - `multimodal-attach-attention`: one-shot bounce when the page loads
       *   (lasts ~2.4s, three bounces, then settles). Uses `forwards` so the
       *   button stays at rest after the animation completes — no ambient
       *   jitter that would distract once the user has noticed it.
       * - The `:hover` rule scales the button gently so users get tactile
       *   feedback even after the intro animation has ended.
       *
       * Targeting `[data-testid="copilot-add-menu-button"]` instead of
       * passing a slot override keeps the override surface tiny — the button
       * markup, accessibility, and dropdown wiring all stay owned by
       * CopilotChatInput.
       */}
      <style>{`
        @keyframes multimodal-attach-attention {
          0%, 100% { transform: translateY(0); }
          15% { transform: translateY(-6px); }
          30% { transform: translateY(0); }
          45% { transform: translateY(-4px); }
          60% { transform: translateY(0); }
          75% { transform: translateY(-2px); }
          90% { transform: translateY(0); }
        }
        [data-multimodal-demo-chat-root] [data-testid="copilot-add-menu-button"] {
          animation: multimodal-attach-attention 2.4s ease-in-out 0.4s 1 both;
          transition: transform 150ms ease-out, background-color 150ms ease-out;
        }
        [data-multimodal-demo-chat-root] [data-testid="copilot-add-menu-button"]:hover {
          transform: scale(1.12);
        }
        @media (prefers-reduced-motion: reduce) {
          [data-multimodal-demo-chat-root] [data-testid="copilot-add-menu-button"] {
            animation: none;
          }
        }
      `}</style>
      <div
        data-testid="multimodal-demo-root"
        className="mx-auto flex h-screen max-w-4xl flex-col gap-3 p-4 sm:p-6"
      >
        <SampleAttachmentButtons agentId="multimodal-demo" />

        <div
          data-multimodal-demo-chat-root
          className="min-h-0 flex-1 overflow-hidden rounded-lg border border-black/10 dark:border-white/10"
        >
          <CopilotChat
            agentId="multimodal-demo"
            className="h-full"
            attachments={{
              enabled: true,
              accept: ACCEPT_MIME,
              maxSize: MAX_FILE_SIZE_BYTES,
              onUpload,
              onUploadFailed: (err) => {
                // Log without disrupting the default UI — CopilotChat already
                // shows a toast-style indicator on validation failure.
                console.warn("[multimodal-demo] attachment rejected", err);
              },
            }}
          />
        </div>
      </div>
    </>
  );
}

"use client";

/**
 * Two buttons that auto-attach a bundled sample file (image or PDF) and
 * immediately submit a canned prompt about it.
 *
 * Implementation note: an earlier version of this component drove the
 * chat's hidden `<input type="file">` via DataTransfer + a synthetic
 * `change` event so the sample path went through the same `onUpload` /
 * `useAttachments` pipeline as the paperclip button. That worked for
 * "queue the attachment" but auto-sending the canned prompt afterwards
 * required clicking the send button while the attachment was still in
 * `status: "uploading"`, which `CopilotChat.onSubmitInput` rejects with
 * `"Cannot send while attachments are uploading"` and clears the input
 * regardless. Detecting the upload-complete state from outside the chat
 * meant scraping the spinner overlay, racy on slow renders.
 *
 * This version skips the DOM entirely and goes through the V2 agent
 * surface directly: `agent.addMessage(...)` to enqueue a fully-formed
 * user message (text + attachment content parts), then
 * `copilotkit.runAgent({ agent })` to dispatch it. Matches what
 * `CopilotChat.onSubmitInput` does internally — same shapes, same
 * runtime — but with no upload race because we build the
 * already-base64'd content part ourselves before calling addMessage.
 *
 * The `LegacyConverterShim` in page.tsx still rewrites our modern
 * `image|document` parts to the legacy `binary` shape the published
 * `@ag-ui/langgraph` converter understands, so the agent ultimately
 * receives the attachment in the form `multimodal_agent.py` expects.
 */

import { useCallback, useState } from "react";
import { useAgent, useCopilotKit } from "@copilotkit/react-core/v2";

export interface SampleSpec {
  readonly buttonLabel: string;
  readonly filename: string;
  readonly mimeType: string;
  readonly testId: string;
  readonly fetchUrl: string;
  /**
   * Prompt sent alongside the attachment. Rendered as the user message
   * bubble in chat AND matched against by aimock to return the demo's
   * canned response. Phrased as a long, specific sentence ("demo pdf I
   * just attached" / "demo image I just attached") so it both reads
   * naturally and can't collide with arbitrary user prompts — random
   * uploads phrase questions differently and fall through to the proxy.
   */
  readonly autoPrompt: string;
}

export const SAMPLES: readonly SampleSpec[] = [
  {
    buttonLabel: "Try with sample image",
    filename: "sample.png",
    mimeType: "image/png",
    testId: "multimodal-sample-image-button",
    fetchUrl: "/demo-files/sample.png",
    autoPrompt: "can you tell me what is in this demo image I just attached",
  },
  {
    buttonLabel: "Try with sample PDF",
    filename: "sample.pdf",
    mimeType: "application/pdf",
    testId: "multimodal-sample-pdf-button",
    fetchUrl: "/demo-files/sample.pdf",
    autoPrompt: "can you tell me what is in this demo pdf I just attached",
  },
];

export interface SampleAttachmentButtonsProps {
  /**
   * Agent slug the parent `<CopilotKit agent="...">` provider wires up.
   * The buttons send via `useAgent({ agentId })` so the message lands on
   * the same agent the sibling `<CopilotChat />` is bound to.
   */
  readonly agentId: string;
}

/**
 * Magic-byte prefixes used to validate fetched sample files. We check
 * these because Next.js will happily serve a Git LFS *pointer* file (a
 * short plain-text stub starting with `version https://git-lfs...`) with
 * a `Content-Type: image/png` header if LFS wasn't pulled at build time.
 * Without this guard, the broken pointer bytes get base64-encoded,
 * sent to the agent as a valid-looking PNG, and rendered as a broken
 * <img>. Fail loudly with an actionable error instead.
 */
const MAGIC_BYTES: Record<string, number[]> = {
  "image/png": [0x89, 0x50, 0x4e, 0x47], // ‰PNG
  "application/pdf": [0x25, 0x50, 0x44, 0x46], // %PDF
};

const LFS_POINTER_PREFIX = "version https://git-lfs";

function bytesStartWith(bytes: Uint8Array, prefix: number[]): boolean {
  if (bytes.length < prefix.length) return false;
  for (let i = 0; i < prefix.length; i++) {
    if (bytes[i] !== prefix[i]) return false;
  }
  return true;
}

export interface FetchedSample {
  bytes: Uint8Array;
  base64: string;
  size: number;
}

/**
 * Fetch the sample file, validate its magic bytes, and return both the
 * raw bytes (for size accounting) and a base64 string suitable for
 * dropping into a `source.value` content part.
 */
async function fetchSample(spec: SampleSpec): Promise<FetchedSample> {
  const res = await fetch(spec.fetchUrl);
  if (!res.ok) {
    throw new Error(
      `Could not fetch sample "${spec.filename}" — HTTP ${res.status}. ` +
        `Is the file bundled under public${spec.fetchUrl}?`,
    );
  }
  const buffer = await res.arrayBuffer();
  const bytes = new Uint8Array(buffer);

  const asciiHead = new TextDecoder("utf-8", { fatal: false }).decode(
    bytes.slice(0, Math.min(bytes.length, 64)),
  );
  if (asciiHead.startsWith(LFS_POINTER_PREFIX)) {
    throw new Error(
      `Sample "${spec.filename}" is a Git LFS pointer, not the real asset. ` +
        "The deploy environment needs to run `git lfs pull` (or set " +
        "`GIT_LFS_ENABLED=1`) so the binary is checked out before the Next.js " +
        "app serves it.",
    );
  }

  const expectedMagic = MAGIC_BYTES[spec.mimeType];
  if (expectedMagic && !bytesStartWith(bytes, expectedMagic)) {
    throw new Error(
      `Sample "${spec.filename}" does not have a valid ${spec.mimeType} ` +
        "signature. The file may be corrupted or a wrong asset was committed.",
    );
  }

  // Convert to base64 via FileReader for parity with the paperclip path.
  // The `data:<mime>;base64,<payload>` URL is split — we only need the
  // payload, which becomes the `source.value` of the content part below.
  const blob = new Blob([buffer], { type: spec.mimeType });
  const dataUrl = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () =>
      reject(
        reader.error ?? new Error(`FileReader failed for ${spec.filename}`),
      );
    reader.onload = () => {
      if (typeof reader.result !== "string") {
        reject(new Error(`Unexpected FileReader result for ${spec.filename}`));
        return;
      }
      resolve(reader.result);
    };
    reader.readAsDataURL(blob);
  });
  const commaIdx = dataUrl.indexOf(",");
  const base64 = commaIdx >= 0 ? dataUrl.slice(commaIdx + 1) : dataUrl;

  return { bytes, base64, size: buffer.byteLength };
}

/**
 * Browser-friendly UUID. `crypto.randomUUID` is widely supported but we
 * fall back to a math-based UUIDv4 for the (rare) older runtime.
 */
function generateMessageId(): string {
  if (
    typeof crypto !== "undefined" &&
    typeof crypto.randomUUID === "function"
  ) {
    return crypto.randomUUID();
  }
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

/** The slice of the CopilotKit core that `submitSample` needs. */
type SampleSender = Pick<
  ReturnType<typeof useCopilotKit>["copilotkit"],
  "getAgent" | "runAgent"
>;

/**
 * Fetches the sample and sends it, with its prompt, to the agent the chat
 * observes once the file has loaded. The agent is looked up by id AFTER
 * the fetch, never captured at click time: a click that raced runtime
 * discovery could otherwise hold a provisional stand-in the chat has
 * since dropped, and the reply would land where nothing renders it
 * (PNI-575).
 */
export async function submitSample(
  copilotkit: SampleSender,
  agentId: string,
  spec: SampleSpec,
  load: (spec: SampleSpec) => Promise<FetchedSample> = fetchSample,
): Promise<void> {
  const sample = await load(spec);
  const target = copilotkit.getAgent(agentId);
  if (!target) {
    throw new Error(
      `Agent "${agentId}" is not available. Try again in a moment.`,
    );
  }
  const partType = spec.mimeType === "application/pdf" ? "document" : "image";

  // Build a multimodal user message as content parts: prompt text +
  // the attachment. The `LegacyConverterShim` in page.tsx will
  // rewrite the modern `image|document` part to the legacy `binary`
  // shape the @ag-ui/langgraph converter understands before the
  // request leaves the runtime.
  target.addMessage({
    id: generateMessageId(),
    role: "user",
    content: [
      { type: "text", text: spec.autoPrompt },
      {
        type: partType,
        source: {
          type: "data",
          value: sample.base64,
          mimeType: spec.mimeType,
        },
        metadata: {
          filename: spec.filename,
          size: sample.size,
        },
      },
    ],
  } as Parameters<typeof target.addMessage>[0]);

  await copilotkit.runAgent({ agent: target });
}

export function SampleAttachmentButtons({
  agentId,
}: SampleAttachmentButtonsProps) {
  const { isReady } = useAgent({ agentId });
  const { copilotkit } = useCopilotKit();
  const [loading, setLoading] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const sendSample = useCallback(
    async (spec: SampleSpec): Promise<void> => {
      // Until runtime discovery finishes, useAgent hands out a provisional
      // agent the chat will not keep (PNI-575). Nothing to send to yet.
      if (!isReady) return;
      setError(null);
      setLoading(spec.testId);
      try {
        await submitSample(copilotkit, agentId, spec);
      } catch (err) {
        console.error("[multimodal-demo] sample-attachment send failed", err);
        setError(err instanceof Error ? err.message : "Sample send failed.");
      } finally {
        setLoading(null);
      }
    },
    [agentId, copilotkit, isReady],
  );

  return (
    <div
      data-testid="multimodal-sample-row"
      className="flex flex-wrap items-center gap-2 rounded-md border border-black/10 bg-black/[0.03] px-3 py-2 text-sm dark:border-white/10 dark:bg-white/[0.04]"
    >
      <span className="text-xs font-medium text-black/60 dark:text-white/60">
        Bundled samples:
      </span>
      {SAMPLES.map((spec) => {
        const isLoading = loading === spec.testId;
        return (
          <button
            key={spec.testId}
            type="button"
            data-testid={spec.testId}
            disabled={!isReady || loading !== null}
            onClick={() => void sendSample(spec)}
            className="rounded border border-black/15 bg-white px-3 py-1 text-xs font-medium text-black transition hover:bg-black/5 disabled:cursor-not-allowed disabled:opacity-50 dark:border-white/15 dark:bg-neutral-900 dark:text-white dark:hover:bg-white/5"
          >
            {isLoading ? "Sending…" : spec.buttonLabel}
          </button>
        );
      })}
      {error && (
        <span
          data-testid="multimodal-sample-error"
          className="ml-auto max-w-[24rem] truncate text-xs text-red-600 dark:text-red-400"
          title={error}
        >
          {error}
        </span>
      )}
    </div>
  );
}

"use client";

// Auth demo — framework-native request authentication via the V2 runtime's
// `onRequest` hook. The runtime route (/api/copilotkit-auth) rejects any
// request whose `Authorization: Bearer <demo-token>` header is missing or
// wrong.
//
// UX shape: the demo defaults to UNAUTHENTICATED on first paint so visitors
// land on a clear sign-in card. We don't render `<CopilotKit>` until the user
// has signed in at least once — that sidesteps the transport 401 that would
// otherwise crash `<CopilotChat>` during its initial `/info` handshake.
// After the user signs in once, `<CopilotKit>` stays mounted across the
// sign-out → sign-in cycle so the post-sign-out state can actually
// demonstrate the runtime rejecting unauthenticated requests in the chat
// surface (the whole point of the demo).
//
// Error surfacing: the post-sign-out 401 is captured via the AGENT-SCOPED
// `<CopilotChat onError>` channel, NOT the provider-level `<CopilotKit
// onError>` alone. Agent-run errors (`agent_run_failed`) are reliably
// delivered to the chat-scoped subscription, whereas the provider-level
// handler does not fire for them in this flow — so a demo that relies only
// on `<CopilotKit onError>` never renders the rejection banner. We register
// the same handler on BOTH channels: `<CopilotKit onError>` covers any
// provider-level errors (e.g. the initial `/info` handshake) and
// `<CopilotChat onError>` covers agent-run rejections, which is what the
// sign-out path produces.

import { useCallback, useEffect, useMemo, useState } from "react";
import { CopilotKit, CopilotChat } from "@copilotkit/react-core/v2";
import type { CopilotKitCoreErrorCode } from "@copilotkit/react-core/v2";
import { AuthBanner } from "./auth-banner";
import { SignInCard } from "./sign-in-card";
import { useDemoAuth } from "./use-demo-auth";
import { DEMO_TOKEN } from "./demo-token";

interface AuthDemoErrorState {
  message: string;
  code: CopilotKitCoreErrorCode | string;
}

interface AuthErrorEvent {
  error?: { message?: string } | null;
  code: CopilotKitCoreErrorCode;
}

export default function AuthDemoPage() {
  const {
    isAuthenticated,
    authorizationHeader,
    hasEverSignedIn,
    signIn,
    signOut,
  } = useDemoAuth();

  const headers = useMemo<Record<string, string>>(
    () => (authorizationHeader ? { Authorization: authorizationHeader } : {}),
    [authorizationHeader],
  );

  const [authError, setAuthError] = useState<AuthDemoErrorState | null>(null);

  // Shared error handler wired to BOTH the provider-level and chat-level
  // `onError` channels (see the file header for why both are needed).
  const handleAuthError = useCallback((event: AuthErrorEvent) => {
    setAuthError({
      message:
        (event.error?.message && event.error.message.trim()) ||
        (event.code
          ? `Request rejected (${event.code})`
          : "The request was rejected."),
      code: event.code,
    });
  }, []);

  // Clear stale errors as soon as the user re-authenticates. This is the
  // ONLY thing that gates the amber error surface on auth state — the render
  // condition below keys off `authError` alone. Coupling the render to a
  // second `!isAuthenticated` slice (the obvious-but-wrong guard) created a
  // post-sign-out race: the rejection's `onError` fires and calls
  // `setAuthError`, but if that commit landed in a render where the auth
  // state hadn't yet settled to false, `authError && !isAuthenticated`
  // evaluated false and the banner never appeared. Driving the surface off
  // `authError` and clearing it here on re-auth removes the cross-slice
  // ordering dependency: a rejection always renders, and signing back in
  // always wipes it.
  useEffect(() => {
    if (isAuthenticated) setAuthError(null);
  }, [isAuthenticated]);

  if (!hasEverSignedIn) {
    return (
      <div className="flex h-screen flex-col">
        <SignInCard onSignIn={signIn} />
      </div>
    );
  }

  return (
    // `useSingleEndpoint={false}` opts into the V2 multi-endpoint protocol
    // (separate /info, /agents/<id>/run, etc.), which is what this demo's
    // runtime route is wired up for.
    <CopilotKit
      runtimeUrl="/api/copilotkit-auth"
      agent="auth-demo"
      headers={headers}
      useSingleEndpoint={false}
      onError={handleAuthError}
    >
      <div className="flex h-screen flex-col gap-3 p-6">
        <AuthBanner
          authenticated={isAuthenticated}
          onSignOut={signOut}
          onSignIn={() => signIn(DEMO_TOKEN)}
        />
        <header>
          <h1 className="text-lg font-semibold">Authentication</h1>
        </header>
        {authError && (
          <div
            data-testid="auth-demo-error"
            className="rounded-md border border-amber-300 bg-amber-50 px-3 py-2 text-sm text-amber-900"
          >
            <strong className="font-semibold">
              Runtime rejected the request:
            </strong>{" "}
            <span data-testid="auth-demo-error-message">
              {authError.message}
            </span>{" "}
            <code className="ml-1 rounded bg-amber-100 px-1 py-0.5 font-mono text-xs">
              {authError.code}
            </code>
          </div>
        )}
        <div className="flex-1 overflow-hidden rounded-md border border-neutral-200">
          <CopilotChat
            agentId="auth-demo"
            className="h-full"
            onError={handleAuthError}
          />
        </div>
      </div>
    </CopilotKit>
  );
}

// Dedicated runtime for the /demos/auth cell.
//
// Demonstrates framework-native request authentication via the V2 runtime's
// `onRequest` hook, which runs before routing and can short-circuit the
// request by throwing a Response. We validate a static `Authorization: Bearer
// <DEMO_TOKEN>` header; mismatch throws 401 before the request reaches the
// agent.
//
// Implementation note: the V1 Next.js adapter
// (`copilotRuntimeNextJSAppRouterEndpoint`) does NOT forward the `hooks`
// option to the V2 fetch handler. To get `onRequest` wired, this route uses
// `createCopilotRuntimeHandler` from `@copilotkit/runtime/v2` directly — the
// framework-agnostic fetch handler that returns a plain
// `(Request) => Promise<Response>`, which composes cleanly with a Next.js
// App Router route export.
//
// References:
// - packages/runtime/src/v2/runtime/core/hooks.ts (onRequest semantics)
// - packages/runtime/src/v2/runtime/__tests__/hooks.test.ts (throw Response pattern)

import type { NextRequest } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { LangGraphAgent } from "@copilotkit/runtime/langgraph";
import { DEMO_AUTH_HEADER } from "@/app/demos/auth/demo-token";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8123";

// Reuse the neutral `sample_agent` graph for the authenticated path. The
// point of this demo is the gate mechanism, not per-user agent branching —
// authenticated users get the same behavior as any other neutral demo.
const authDemoAgent = new LangGraphAgent({
  deploymentUrl: `${AGENT_URL}/`,
  graphId: "sample_agent",
});

const runtime = new CopilotRuntime({
  agents: {
    "auth-demo": authDemoAgent,
    // Fallback: useAgent() with no args resolves "default" — alias to the
    // same agent so hooks in the demo page resolve cleanly.
    default: authDemoAgent,
  },
});

const BASE_PATH = "/api/copilotkit-auth";

// Framework-agnostic fetch handler with the auth gate wired up.
const handler = createCopilotRuntimeHandler({
  runtime,
  basePath: BASE_PATH,
  hooks: {
    onRequest: ({ request }) => {
      const authHeader = request.headers.get("authorization");
      if (authHeader !== DEMO_AUTH_HEADER) {
        // Throwing a Response short-circuits the pipeline. The runtime maps
        // thrown Responses to the HTTP response verbatim (status + body).
        throw new Response(
          JSON.stringify({
            error: "unauthorized",
            message:
              "Missing or invalid Authorization header. Click Authenticate above to send messages.",
          }),
          {
            status: 401,
            headers: { "content-type": "application/json" },
          },
        );
      }
    },
  },
});

// Next.js App Router bindings. The handler is framework-agnostic — it takes
// a web Request and returns a web Response — so it drops straight into the
// POST/GET exports without any adapter shim.
export const POST = (req: NextRequest) => handler(req);
export const GET = (req: NextRequest) => handler(req);

