// =====================================================================
// input.addMenuButton
// Only renders if `onAddFile` or `toolsMenu` is set on CopilotChatInput.
// =====================================================================
export function CustomAddMenuButton(
  props: React.ButtonHTMLAttributes<HTMLButtonElement>,
