"use client";

// Custom `reasoningMessage` slot renderer.
//
// Receives the `ReasoningMessage` plus (optionally) the full message list and
// the running state from the slot system. Renders the content inline with a
// visibly tagged amber banner so the user can always see the agent's thinking
// chain — this is the focal UI of the demo.

import React from "react";
import type { ReasoningMessage, Message } from "@ag-ui/core";

export function ReasoningBlock({
  message,
  messages,
  isRunning,
}: {
  message: ReasoningMessage;
  messages?: Message[];
  isRunning?: boolean;
}) {
  const isLatest = messages?.[messages.length - 1]?.id === message.id;
  const isStreaming = !!(isRunning && isLatest);
  const hasContent = !!(message.content && message.content.length > 0);

  return (
    <div
      data-testid="reasoning-block"
      className="my-2 rounded-xl border border-[#DBDBE5] bg-[#BEC2FF1A] px-3.5 py-2.5 text-sm"
    >
      <div className="flex items-center gap-2 font-medium text-[#010507]">
        <span className="inline-block rounded-full border border-[#BEC2FF] bg-white px-2 py-0.5 text-[10px] uppercase tracking-[0.14em] text-[#57575B]">
          Reasoning
        </span>
        <span className="text-[#57575B]">
          {isStreaming ? "Thinking…" : hasContent ? "Agent reasoning" : "…"}
        </span>
      </div>
      {hasContent && (
        <div className="mt-1.5 whitespace-pre-wrap italic text-[#57575B]">
          {message.content}
        </div>
      )}
    </div>
  );
}

"use client";

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

// Suggestions registered via the v2 chat composer hook. Mirrors the
// `reasoning-default` cell so users can compare default vs custom
// reasoning rendering with the same prompt.
//
// IMPORTANT: gpt-5-mini (and OpenAI reasoning models generally) only
// emit `response.reasoning_summary_text.delta` events when there's a
// concrete problem to reason ABOUT. A meta-prompt like "show your
// reasoning step by step" produces no reasoning summary — the model
// recognizes it as a request to reveal chain-of-thought (which it
// refuses) and returns a plain text reply with zero reasoning summary
// content. The reasoning slot then never lights up. A concrete question
// that genuinely requires multi-step thinking reliably triggers it.
export function useReasoningCustomSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Show reasoning",
        message:
          "Explain step by step why the sky appears blue during the day but red at sunset.",
      },
    ],
    available: "always",
  });
}

