  up: "bg-[color-mix(in_oklab,var(--primary)_15%,transparent)] text-[var(--primary)]",
  down: "bg-[color-mix(in_oklab,var(--destructive)_15%,transparent)] text-[var(--destructive)]",
  neutral: "bg-[var(--secondary)] text-[var(--muted-foreground)]",
} as const;

