"use client";

/**
 * Agent Config Object — typed config knobs (tone / expertise / responseLength)
 * forwarded from the provider into the agent so its behavior changes per turn.
 *
 * Wiring: the toggles live in `useAgentConfig`. Each render the resolved
 * config is published to the agent via `useAgentContext` — the v2 idiom
 * for "frontend → agent runtime context" in LangGraph 0.6+. The Python
 * graph picks it up through `CopilotKitMiddleware`, which routes the
 * context entry into the model's prompt before each call.
 *
 * (LangGraph 0.6 deprecated `configurable` in favor of `context`; the
 * `properties` prop on `<CopilotKit>` still works for v1-style relays
 * but goes through `forwardedProps` and does not land in `RunnableConfig`
 * in @ag-ui/langgraph 0.0.31. `useAgentContext` is the supported path.)
 */

import { CopilotKit } from "@copilotkit/react-core/v2";

import { DemoLayout } from "./demo-layout";
import { ConfigContextRelay } from "./config-context-relay";
import { useAgentConfig } from "./use-agent-config";

export default function AgentConfigDemoPage() {
  const { config, setTone, setExpertise, setResponseLength } = useAgentConfig();

  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-agent-config"
      agent="agent-config-demo"
    >
      <ConfigContextRelay config={config} />
      <DemoLayout
        config={config}
        onToneChange={setTone}
        onExpertiseChange={setExpertise}
        onResponseLengthChange={setResponseLength}
      />
    </CopilotKit>
  );
}

// Dedicated runtime for the Agent Config Object demo.
//
// Hosts the `agent_config_agent` graph. The frontend publishes its
// tone / expertise / responseLength toggles to the agent through
// `useAgentContext`, which the runtime serializes onto the AG-UI run as
// a context entry. `CopilotKitMiddleware` on the Python side injects
// that entry into the model's prompt so the same single static system
// prompt adapts its style to whatever the frontend currently has
// selected.
//
// References:
// - src/agents/agent_config_agent.py — the graph
// - src/app/demos/agent-config/config-context-relay.tsx — the
//   `useAgentContext` publisher

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { LangGraphAgent } from "@copilotkit/runtime/langgraph";

const LANGGRAPH_URL =
  process.env.LANGGRAPH_DEPLOYMENT_URL || "http://localhost:8123";

const agentConfigAgent = new LangGraphAgent({
  deploymentUrl: LANGGRAPH_URL,
  graphId: "agent_config_agent",
  langsmithApiKey: process.env.LANGSMITH_API_KEY || "",
});

const agents: Record<string, LangGraphAgent> = {
  // The page's <CopilotKit agent="agent-config-demo"> resolves here.
  "agent-config-demo": agentConfigAgent,
  // Internal components (headless-chat, example-canvas) call `useAgent()`
  // with no args, which defaults to agentId "default". Alias to the same
  // graph so those component hooks resolve instead of throwing
  // "Agent 'default' not found".
  default: agentConfigAgent,
};

const runtime = new CopilotRuntime({
  // @ts-ignore -- Published CopilotRuntime agents type wraps Record in
  // MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in
  // source, pending release.
  agents,
});

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-agent-config",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

"use client";

import type { ChangeEvent } from "react";
import {
  type AgentConfig,
  EXPERTISE_OPTIONS,
  type Expertise,
  RESPONSE_LENGTH_OPTIONS,
  type ResponseLength,
  TONE_OPTIONS,
  type Tone,
} from "./config-types";

interface ConfigCardProps {
  config: AgentConfig;
  onToneChange: (tone: Tone) => void;
  onExpertiseChange: (expertise: Expertise) => void;
  onResponseLengthChange: (length: ResponseLength) => void;
}

export function ConfigCard({
  config,
  onToneChange,
  onExpertiseChange,
  onResponseLengthChange,
}: ConfigCardProps) {
  return (
    <div
      data-testid="agent-config-card"
      className="flex flex-col gap-2 rounded-md border border-[var(--border)] bg-[var(--bg-surface)] p-4 text-sm"
    >
      <h2 className="text-sm font-semibold">Agent Config</h2>
      <p className="text-xs text-[var(--text-muted)]">
        Change these and send a message to see the agent adapt.
      </p>
      <div className="flex flex-wrap gap-3">
        <label className="flex flex-col gap-1">
          <span className="text-xs font-medium">Tone</span>
          <select
            data-testid="agent-config-tone-select"
            value={config.tone}
            onChange={(e: ChangeEvent<HTMLSelectElement>) =>
              onToneChange(e.target.value as Tone)
            }
            className="rounded border border-[var(--border)] bg-[var(--bg-muted)] px-2 py-1 text-sm"
          >
            {TONE_OPTIONS.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>
        </label>
        <label className="flex flex-col gap-1">
          <span className="text-xs font-medium">Expertise</span>
          <select
            data-testid="agent-config-expertise-select"
            value={config.expertise}
            onChange={(e: ChangeEvent<HTMLSelectElement>) =>
              onExpertiseChange(e.target.value as Expertise)
            }
            className="rounded border border-[var(--border)] bg-[var(--bg-muted)] px-2 py-1 text-sm"
          >
            {EXPERTISE_OPTIONS.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>
        </label>
        <label className="flex flex-col gap-1">
          <span className="text-xs font-medium">Response length</span>
          <select
            data-testid="agent-config-length-select"
            value={config.responseLength}
            onChange={(e: ChangeEvent<HTMLSelectElement>) =>
              onResponseLengthChange(e.target.value as ResponseLength)
            }
            className="rounded border border-[var(--border)] bg-[var(--bg-muted)] px-2 py-1 text-sm"
          >
            {RESPONSE_LENGTH_OPTIONS.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>
        </label>
      </div>
    </div>
  );
}

"use client";

/**
 * Publishes the current agent-config toggles to the agent runtime via
 * `useAgentContext`. Lives inside the `<CopilotKit>` provider so the
 * context store is reachable. The middleware on the Python side reads
 * this entry off the agent's runtime context on every turn and routes
 * it into the model's prompt.
 */

import { useAgentContext } from "@copilotkit/react-core/v2";
import type { AgentConfig } from "./config-types";

export function ConfigContextRelay({ config }: { config: AgentConfig }) {
  useAgentContext({
    description:
      "Agent response preferences. Apply tone, expertise level, and response length to every reply.",
    value: {
      tone: config.tone,
      expertise: config.expertise,
      responseLength: config.responseLength,
    },
  });
  return null;
}

export type Tone = "professional" | "casual" | "enthusiastic";
export type Expertise = "beginner" | "intermediate" | "expert";
export type ResponseLength = "concise" | "detailed";

export interface AgentConfig {
  tone: Tone;
  expertise: Expertise;
  responseLength: ResponseLength;
}

export const DEFAULT_AGENT_CONFIG: AgentConfig = {
  tone: "professional",
  expertise: "intermediate",
  responseLength: "concise",
};

export const TONE_OPTIONS: Tone[] = ["professional", "casual", "enthusiastic"];
export const EXPERTISE_OPTIONS: Expertise[] = [
  "beginner",
  "intermediate",
  "expert",
];
export const RESPONSE_LENGTH_OPTIONS: ResponseLength[] = [
  "concise",
  "detailed",
];

"use client";

import React from "react";
import { CopilotChat } from "@copilotkit/react-core/v2";

import { ConfigCard } from "./config-card";
import type { AgentConfig } from "./config-types";

interface DemoLayoutProps {
  config: AgentConfig;
  onToneChange: (tone: AgentConfig["tone"]) => void;
  onExpertiseChange: (expertise: AgentConfig["expertise"]) => void;
  onResponseLengthChange: (length: AgentConfig["responseLength"]) => void;
}

export function DemoLayout({
  config,
  onToneChange,
  onExpertiseChange,
  onResponseLengthChange,
}: DemoLayoutProps) {
  return (
    <div className="flex h-screen flex-col gap-3 p-6">
      <ConfigCard
        config={config}
        onToneChange={onToneChange}
        onExpertiseChange={onExpertiseChange}
        onResponseLengthChange={onResponseLengthChange}
      />
      <div className="flex-1 overflow-hidden rounded-md border border-[var(--border)]">
        <CopilotChat
          agentId="agent-config-demo"
          className="h-full rounded-md"
        />
      </div>
    </div>
  );
}

"use client";

import { useCallback, useState } from "react";
import {
  type AgentConfig,
  DEFAULT_AGENT_CONFIG,
  type Expertise,
  type ResponseLength,
  type Tone,
} from "./config-types";

export interface UseAgentConfigHandle {
  config: AgentConfig;
  setTone: (tone: Tone) => void;
  setExpertise: (expertise: Expertise) => void;
  setResponseLength: (length: ResponseLength) => void;
  reset: () => void;
}

export function useAgentConfig(): UseAgentConfigHandle {
  const [config, setConfig] = useState<AgentConfig>(DEFAULT_AGENT_CONFIG);

  const setTone = useCallback(
    (tone: Tone) => setConfig((prev) => ({ ...prev, tone })),
    [],
  );
  const setExpertise = useCallback(
    (expertise: Expertise) => setConfig((prev) => ({ ...prev, expertise })),
    [],
  );
  const setResponseLength = useCallback(
    (responseLength: ResponseLength) =>
      setConfig((prev) => ({ ...prev, responseLength })),
    [],
  );
  const reset = useCallback(() => setConfig(DEFAULT_AGENT_CONFIG), []);

  return { config, setTone, setExpertise, setResponseLength, reset };
}

"use client";

import React from "react";
import { CopilotKit, CopilotChat } from "@copilotkit/react-core/v2";
import { useAgenticChatSuggestions } from "./suggestions";

export default function AgenticChatDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="agentic_chat">
      <Chat />
    </CopilotKit>
  );
}

function Chat() {
  useAgenticChatSuggestions();
  return <CopilotChat agentId="agentic_chat" />;
}

/**
 * LangGraph TypeScript agent — CopilotKit showcase integration
 *
 * Defines a graph with a chat node and all showcase tools,
 * wired to CopilotKit via the sdk-js LangGraph adapter so frontend actions
 * and shared state flow seamlessly.
 */

import { z } from "zod";
import type { RunnableConfig } from "@langchain/core/runnables";
import { tool } from "@langchain/core/tools";
import { ToolNode } from "@langchain/langgraph/prebuilt";
import type { AIMessage } from "@langchain/core/messages";
import { SystemMessage } from "@langchain/core/messages";
import {
  MemorySaver,
  START,
  StateGraph,
  Annotation,
} from "@langchain/langgraph";
import { ChatOpenAI } from "@langchain/openai";
import { getA2UITools } from "@ag-ui/langgraph";
import { makeChatOpenAI } from "./openai-headers";
import {
  convertActionsToDynamicStructuredTools,
  CopilotKitStateAnnotation,
} from "@copilotkit/sdk-js/langgraph";
import {
  getWeatherImpl,
  queryDataImpl,
  manageSalesTodosImpl,
  getSalesTodosImpl,
  scheduleMeetingImpl,
  searchFlightsImpl,
} from "../../shared-tools";

// ---------------------------------------------------------------------------
// 1. Agent state — extends CopilotKit state with a proverbs list
// ---------------------------------------------------------------------------

const AgentStateAnnotation = Annotation.Root({
  ...CopilotKitStateAnnotation.spec,
  proverbs: Annotation<string[]>,
});

export type AgentState = typeof AgentStateAnnotation.State;

// ---------------------------------------------------------------------------
// 2. Tools — shared implementations wrapped for LangChain
// ---------------------------------------------------------------------------

const getWeather = tool(
  async ({ location }) => JSON.stringify(getWeatherImpl(location)),
  {
    name: "get_weather",
    description: "Get current weather for a location",
    schema: z.object({
      location: z.string().describe("City name"),
    }),
  },
);

const queryData = tool(
  async ({ query }) => JSON.stringify(queryDataImpl(query)),
  {
    name: "query_data",
    description: "Query financial database for chart data",
    schema: z.object({
      query: z.string().describe("Natural language query"),
    }),
  },
);

const manageSalesTodos = tool(
  async ({ todos }) => JSON.stringify(manageSalesTodosImpl(todos)),
  {
    name: "manage_sales_todos",
    description: "Create or update the sales todo list",
    schema: z.object({
      todos: z
        .array(
          z.object({
            id: z.string().optional(),
            title: z.string(),
            stage: z.string().optional(),
            value: z.number().optional(),
            dueDate: z.string().optional(),
            assignee: z.string().optional(),
            completed: z.boolean().optional(),
          }),
        )
        .describe("Array of sales todo items"),
    }),
  },
);

const getSalesTodos = tool(
  async ({ currentTodos }) => JSON.stringify(getSalesTodosImpl(currentTodos)),
  {
    name: "get_sales_todos",
    description: "Get the current sales todo list",
    schema: z.object({
      currentTodos: z
        .array(
          z.object({
            id: z.string().optional(),
            title: z.string().optional(),
            stage: z.string().optional(),
            value: z.number().optional(),
            dueDate: z.string().optional(),
            assignee: z.string().optional(),
            completed: z.boolean().optional(),
          }),
        )
        .optional()
        .nullable()
        .describe("Current todos if any"),
    }),
  },
);

const scheduleMeeting = tool(
  async ({ reason, durationMinutes }) =>
    JSON.stringify(scheduleMeetingImpl(reason, durationMinutes)),
  {
    name: "schedule_meeting",
    description: "Schedule a meeting (requires user approval via HITL)",
    schema: z.object({
      reason: z.string().describe("Reason for the meeting"),
      durationMinutes: z.number().optional().describe("Duration in minutes"),
    }),
  },
);

const searchFlights = tool(
  async ({ flights }) => JSON.stringify(searchFlightsImpl(flights)),
  {
    name: "search_flights",
    description: "Search for available flights",
    schema: z.object({
      flights: z
        .array(
          z.object({
            airline: z.string(),
            airlineLogo: z.string().optional(),
            flightNumber: z.string(),
            origin: z.string(),
            destination: z.string(),
            date: z.string(),
            departureTime: z.string(),
            arrivalTime: z.string(),
            duration: z.string(),
            status: z.string(),
            statusColor: z.string().optional(),
            price: z.string(),
            currency: z.string().optional(),
          }),
        )
        .describe("Array of flight results"),
    }),
  },
);

// Dynamic A2UI via the canonical ag-ui factory (same as beautiful_chat /
// a2ui_dynamic). A secondary LLM designs the surface; the factory forces the
// host catalog and emits the a2ui_operations envelope. Replaces the prior
// hand-rolled generate_a2ui tool.
const generateA2ui = getA2UITools({
  model: new ChatOpenAI({ model: "gpt-5-mini" }),
  defaultCatalogId: "copilotkit://app-dashboard-catalog",
});

const tools = [
  getWeather,
  queryData,
  manageSalesTodos,
  getSalesTodos,
  scheduleMeeting,
  searchFlights,
  generateA2ui,
];

// ---------------------------------------------------------------------------
// 3. Chat node — binds backend + frontend tools, invokes the model
// ---------------------------------------------------------------------------

async function chatNode(state: AgentState, config: RunnableConfig) {
  const model = makeChatOpenAI(config, { model: "gpt-5-mini" });

  const modelWithTools = model.bindTools!([
    ...convertActionsToDynamicStructuredTools(state.copilotkit?.actions ?? []),
    ...tools,
  ]);

  const systemMessage = new SystemMessage({
    content: `You are a helpful assistant. The current proverbs are ${JSON.stringify(state.proverbs)}.`,
  });

  const response = await modelWithTools.invoke(
    [systemMessage, ...state.messages],
    config,
  );

  return { messages: response };
}

// ---------------------------------------------------------------------------
// 4. Routing — send tool calls to tool_node unless they're CopilotKit actions
// ---------------------------------------------------------------------------

function shouldContinue({ messages, copilotkit }: AgentState) {
  const lastMessage = messages[messages.length - 1] as AIMessage;

  if (lastMessage.tool_calls?.length) {
    const actions = copilotkit?.actions;
    const toolCallName = lastMessage.tool_calls![0].name;

    if (!actions || actions.every((action) => action.name !== toolCallName)) {
      return "tool_node";
    }
  }

  return "__end__";
}

// ---------------------------------------------------------------------------
// 5. Compile the graph
// ---------------------------------------------------------------------------

const workflow = new StateGraph(AgentStateAnnotation)
  .addNode("chat_node", chatNode)
  .addNode("tool_node", new ToolNode(tools))
  .addEdge(START, "chat_node")
  .addEdge("tool_node", "chat_node")
  .addConditionalEdges("chat_node", shouldContinue as any);

const memory = new MemorySaver();

export const graph = workflow.compile({
  checkpointer: memory,
});

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import { randomUUID } from "node:crypto";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { LangGraphAgent } from "@copilotkit/runtime/langgraph";
// CVDIAG backend instrumentation (L1-E). No-op pass-through unless
// CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
import { withCvdiagBackend } from "@/cvdiag-backend";

// The LangGraph TypeScript agent runs as a separate process on port 8123
// via @langchain/langgraph-cli. This runtime proxies CopilotKit requests
// to it via AG-UI protocol.
const AGENT_URL =
  process.env.LANGGRAPH_DEPLOYMENT_URL || "http://localhost:8123";

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

function createAgent(graphId: string = "starterAgent") {
  return new LangGraphAgent({
    deploymentUrl: `${AGENT_URL}/`,
    graphId,
  });
}

// Register the same starter agent under all names used by demo pages
// that don't need their own graph.
const starterAgentNames = [
  "agentic_chat",
  "human_in_the_loop",
  "shared-state-read",
  "shared-state-write",
  // Chat-UI demos — all reuse the default starterAgent.
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-customization-css",
  "chat-slots",
  // Headless Chat (Simple) — reuses the default `starterAgent` graph; the
  // demo's surface and frontend tool wiring live in the page component.
  "headless-simple",
  // Hitl demo (original) — reuses starter agent.
  "hitl",
];

const agents: Record<string, LangGraphAgent> = {};
for (const name of starterAgentNames) {
  agents[name] = createAgent();
}
agents["default"] = createAgent();
agents["starterAgent"] = createAgent();

// gen-ui-interrupt + interrupt-headless share the dedicated interrupt_agent
// graph, which uses langgraph's interrupt() primitive inside its
// schedule_meeting tool.
agents["gen-ui-interrupt"] = createAgent("interrupt_agent");
agents["interrupt-headless"] = createAgent("interrupt_agent");

// Demo-specific graphs. Agent name (as used on the frontend
// `<CopilotKit agent="...">` prop) → graphId in src/agent/langgraph.json.
const demoAgents: Record<string, string> = {
  frontend_tools: "frontend_tools",
  "frontend-tools-async": "frontend_tools_async",
  "hitl-in-app": "hitl_in_app",
  // In-Chat HITL — useHumanInTheLoop with frontend-rendered time-picker.
  "hitl-in-chat": "hitl_in_chat",
  "readonly-state-agent-context": "readonly_state_agent_context",
  "shared-state-read-write": "shared_state_read_write",
  "shared-state-streaming": "shared_state_streaming",
  subagents: "subagents",
  "gen-ui-agent": "gen_ui_agent",
  // Tool-Based Generative UI — dedicated data-viz graph; the frontend
  // registers render_bar_chart / render_pie_chart via useComponent.
  "gen-ui-tool-based": "gen_ui_tool_based",
  // Thread-id frontend-tool roundtrip — reuses the frontend_tools graph
  // (non-manifest demo, kept for frontend byte-parity with langgraph-python).
  "threadid-frontend-tool-roundtrip": "frontend_tools",
  // Reasoning demos (reasoning-custom + reasoning-default) share one dedicated
  // reasoning graph — the only frontend difference is the reasoningMessage slot.
  "reasoning-custom": "agentic-chat-reasoning",
  "reasoning-default": "agentic-chat-reasoning",
  // Tool rendering variants all share the ONE tool_rendering graph (same
  // backend tools); the cells differ only in the frontend renderer wiring.
  // Mirrors langgraph-python, which maps all three cells to `tool_rendering`.
  "tool-rendering": "tool_rendering",
  "tool-rendering-default-catchall": "tool_rendering",
  "tool-rendering-custom-catchall": "tool_rendering",
  "tool-rendering-reasoning-chain": "tool-rendering-reasoning-chain",
};
for (const [agentName, graphId] of Object.entries(demoAgents)) {
  agents[agentName] = createAgent(graphId);
}

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

const copilotkitPost = async (req: NextRequest): Promise<Response> => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    // Log full error details server-side with a correlation id, but only
    // return the id (not the message or stack) to the client. Returning
    // raw `err.message` / `err.stack` over the wire leaks internals
    // (file paths, library versions, sometimes secrets in nested error
    // messages) to anyone who can hit /api/copilotkit.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        route: "/api/copilotkit",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

// Wrap with CVDIAG backend instrumentation. `withCvdiagBackend` returns
// `copilotkitPost` unchanged when CVDIAG_BACKEND_EMITTER is off (default), so
// the instrumented path costs nothing in normal operation.
export const POST = withCvdiagBackend(copilotkitPost, {
  slug: "langgraph-typescript",
  agentName: "starterAgent",
  provider: "openai",
});

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/ok`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

