            <h3
              data-testid="weather-city"
              className="text-xl font-semibold capitalize text-[#010507]"
            >
              {location || "Weather"}
            </h3>
            <p className="text-[#57575B] text-sm mt-0.5">
              {loading ? "Fetching weather..." : conditions || "—"}
            </p>
          </div>
          <div className="text-4xl leading-none" aria-hidden>
            {loading ? "..." : conditionsEmoji(conditions)}
          </div>
        </div>

        {!loading && (
          <>
            <div className="mt-5 text-4xl font-semibold text-[#010507] tracking-tight">
              {temperature ?? "--"}&deg;
              <span className="ml-1 text-lg font-normal text-[#57575B]">F</span>
            </div>
            <div className="mt-5 pt-4 border-t border-[#DBDBE5] grid grid-cols-2 gap-3 text-sm">
              <div data-testid="weather-humidity">
                <p className="text-[10px] uppercase tracking-[0.14em] text-[#57575B]">
                  Humidity
                </p>
                <p className="mt-1 font-medium text-[#010507]">
                  {humidity ?? "--"}%
                </p>
              </div>
              <div data-testid="weather-wind">
                <p className="text-[10px] uppercase tracking-[0.14em] text-[#57575B]">
                  Wind
                </p>
                <p className="mt-1 font-medium text-[#010507]">
                  {windSpeed ?? "--"} mph
                </p>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function conditionsEmoji(conditions?: string): string {
  if (!conditions) return "";
  const c = conditions.toLowerCase();
  if (c.includes("sun") || c.includes("clear")) return "sun";
  if (c.includes("rain") || c.includes("storm")) return "rain";
  if (c.includes("cloud")) return "cloud";
  if (c.includes("snow")) return "snow";
  return "";
}

"use client";

import React from "react";
import {
  CopilotChat,
  CopilotKit,
  useComponent,
} from "@copilotkit/react-core/v2";
import { BarChart, barChartPropsSchema } from "./bar-chart";
import { PieChart, pieChartPropsSchema } from "./pie-chart";
import { useSuggestions } from "./suggestions";

function Chat() {
  useComponent({
    name: "render_bar_chart",
    description: "Display a bar chart with labeled numeric values.",
    parameters: barChartPropsSchema,
    render: BarChart,
  });

  useComponent({
    name: "render_pie_chart",
    description: "Display a pie chart with labeled numeric values.",
    parameters: pieChartPropsSchema,
    render: PieChart,
  });

  useSuggestions();

  return (
    <div className="flex justify-center items-center h-screen w-full">
      <div className="h-full w-full max-w-4xl">
        <CopilotChat
          agentId="gen-ui-tool-based"
          className="h-full rounded-2xl"
        />
      </div>
    </div>
  );
}

export default function ControlledGenUiDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="gen-ui-tool-based">
      <Chat />
    </CopilotKit>
  );
}

/**
 * Tool-Based Generative UI agent — TypeScript port of gen_ui_tool_based.py.
 *
 * The frontend registers `render_bar_chart` and `render_pie_chart` via
 * `useComponent`. CopilotKit's LangGraph middleware forwards those as actions
 * on `state.copilotkit.actions`; we bind them so the model can call them.
 *
 * There are no backend tools — the chart components are rendered on the
 * frontend — so the graph ends after the model turn (no tool_node).
 */

import { RunnableConfig } from "@langchain/core/runnables";
import { SystemMessage } from "@langchain/core/messages";
import {
  Annotation,
  MemorySaver,
  START,
  StateGraph,
  messagesStateReducer,
  BaseMessage,
} from "@langchain/langgraph";
import {
  convertActionsToDynamicStructuredTools,
  CopilotKitStateAnnotation,
} from "@copilotkit/sdk-js/langgraph";
import { makeChatOpenAI } from "./openai-headers";

const SYSTEM_PROMPT = `You are a data visualization assistant.

When the user asks for a chart, call \`render_bar_chart\` or \`render_pie_chart\`
with a concise title, short description, and a \`data\` array of
\`{label, value}\` items. Pick bar for comparisons over a small set of
categories; pick pie for composition / share-of-whole.

If the user names a chart subject but does NOT supply concrete numbers
(e.g. "show me a pie chart of website traffic by source"), do NOT ask
them for data. Invent plausible illustrative sample values yourself,
call the appropriate \`render_*\` tool immediately, and briefly note in
the follow-up that the values are illustrative samples. Always render
the chart on the first turn -- never reply with a clarifying question
asking for the data.

Keep chat responses brief -- let the chart do the talking.`;

// Define `messages` explicitly (concrete channel type) rather than relying on
// the spread of `CopilotKitStateAnnotation.spec` alone — the langgraph-api
// schema pre-warmer skips graphs whose state exposes no concrete channel, so
// this graph must carry an explicit `messages` annotation like every other
// registering graph in this package.
const AgentStateAnnotation = Annotation.Root({
  ...CopilotKitStateAnnotation.spec,
  messages: Annotation<BaseMessage[]>({
    reducer: messagesStateReducer,
    default: () => [],
  }),
});

type AgentState = typeof AgentStateAnnotation.State;

async function chatNode(state: AgentState, config: RunnableConfig) {
  const model = makeChatOpenAI(config, { temperature: 0, model: "gpt-5-mini" });

  const modelWithTools = model.bindTools!(
    convertActionsToDynamicStructuredTools(state.copilotkit?.actions ?? []),
  );

  const response = await modelWithTools.invoke(
    [new SystemMessage({ content: SYSTEM_PROMPT }), ...state.messages],
    config,
  );

  return { messages: response };
}

const workflow = new StateGraph(AgentStateAnnotation)
  .addNode("chat_node", chatNode)
  .addEdge(START, "chat_node");

const memory = new MemorySaver();

export const graph = workflow.compile({
  checkpointer: memory,
});

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import { randomUUID } from "node:crypto";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { LangGraphAgent } from "@copilotkit/runtime/langgraph";
// CVDIAG backend instrumentation (L1-E). No-op pass-through unless
// CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
import { withCvdiagBackend } from "@/cvdiag-backend";

// The LangGraph TypeScript agent runs as a separate process on port 8123
// via @langchain/langgraph-cli. This runtime proxies CopilotKit requests
// to it via AG-UI protocol.
const AGENT_URL =
  process.env.LANGGRAPH_DEPLOYMENT_URL || "http://localhost:8123";

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

function createAgent(graphId: string = "starterAgent") {
  return new LangGraphAgent({
    deploymentUrl: `${AGENT_URL}/`,
    graphId,
  });
}

// Register the same starter agent under all names used by demo pages
// that don't need their own graph.
const starterAgentNames = [
  "agentic_chat",
  "human_in_the_loop",
  "shared-state-read",
  "shared-state-write",
  // Chat-UI demos — all reuse the default starterAgent.
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-customization-css",
  "chat-slots",
  // Headless Chat (Simple) — reuses the default `starterAgent` graph; the
  // demo's surface and frontend tool wiring live in the page component.
  "headless-simple",
  // Hitl demo (original) — reuses starter agent.
  "hitl",
];

const agents: Record<string, LangGraphAgent> = {};
for (const name of starterAgentNames) {
  agents[name] = createAgent();
}
agents["default"] = createAgent();
agents["starterAgent"] = createAgent();

// gen-ui-interrupt + interrupt-headless share the dedicated interrupt_agent
// graph, which uses langgraph's interrupt() primitive inside its
// schedule_meeting tool.
agents["gen-ui-interrupt"] = createAgent("interrupt_agent");
agents["interrupt-headless"] = createAgent("interrupt_agent");

// Demo-specific graphs. Agent name (as used on the frontend
// `<CopilotKit agent="...">` prop) → graphId in src/agent/langgraph.json.
const demoAgents: Record<string, string> = {
  frontend_tools: "frontend_tools",
  "frontend-tools-async": "frontend_tools_async",
  "hitl-in-app": "hitl_in_app",
  // In-Chat HITL — useHumanInTheLoop with frontend-rendered time-picker.
  "hitl-in-chat": "hitl_in_chat",
  "readonly-state-agent-context": "readonly_state_agent_context",
  "shared-state-read-write": "shared_state_read_write",
  "shared-state-streaming": "shared_state_streaming",
  subagents: "subagents",
  "gen-ui-agent": "gen_ui_agent",
  // Tool-Based Generative UI — dedicated data-viz graph; the frontend
  // registers render_bar_chart / render_pie_chart via useComponent.
  "gen-ui-tool-based": "gen_ui_tool_based",
  // Thread-id frontend-tool roundtrip — reuses the frontend_tools graph
  // (non-manifest demo, kept for frontend byte-parity with langgraph-python).
  "threadid-frontend-tool-roundtrip": "frontend_tools",
  // Reasoning demos (reasoning-custom + reasoning-default) share one dedicated
  // reasoning graph — the only frontend difference is the reasoningMessage slot.
  "reasoning-custom": "agentic-chat-reasoning",
  "reasoning-default": "agentic-chat-reasoning",
  // Tool rendering variants all share the ONE tool_rendering graph (same
  // backend tools); the cells differ only in the frontend renderer wiring.
  // Mirrors langgraph-python, which maps all three cells to `tool_rendering`.
  "tool-rendering": "tool_rendering",
  "tool-rendering-default-catchall": "tool_rendering",
  "tool-rendering-custom-catchall": "tool_rendering",
  "tool-rendering-reasoning-chain": "tool-rendering-reasoning-chain",
};
for (const [agentName, graphId] of Object.entries(demoAgents)) {
  agents[agentName] = createAgent(graphId);
}

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

const copilotkitPost = async (req: NextRequest): Promise<Response> => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    // Log full error details server-side with a correlation id, but only
    // return the id (not the message or stack) to the client. Returning
    // raw `err.message` / `err.stack` over the wire leaks internals
    // (file paths, library versions, sometimes secrets in nested error
    // messages) to anyone who can hit /api/copilotkit.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        route: "/api/copilotkit",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

// Wrap with CVDIAG backend instrumentation. `withCvdiagBackend` returns
// `copilotkitPost` unchanged when CVDIAG_BACKEND_EMITTER is off (default), so
// the instrumented path costs nothing in normal operation.
export const POST = withCvdiagBackend(copilotkitPost, {
  slug: "langgraph-typescript",
  agentName: "starterAgent",
  provider: "openai",
});

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/ok`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

import React, { useRef } from "react";
import {
  BarChart as RechartsBarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Rectangle,
} from "recharts";
import { z } from "zod";

export const barChartPropsSchema = z.object({
  title: z.string().describe("Chart title"),
  description: z.string().describe("Brief description or subtitle"),
  data: z.array(
    z.object({
      label: z.string(),
      value: z.number(),
    }),
  ),
});

export type BarChartProps = z.infer<typeof barChartPropsSchema>;

export function BarChart({ title, description, data }: BarChartProps) {
  const CHART_COLORS = [
    "#BEC2FF",
    "#85ECCE",
    "#FFAC4D",
    "#FFF388",
    "#189370",
    "#EEE6FE",
    "#FA5F67",
  ];

  const TOOLTIP_STYLE = {
    backgroundColor: "#ffffff",
    border: "1px solid #DBDBE5",
    borderRadius: "12px",
    padding: "10px 14px",
    color: "#010507",
    fontSize: "13px",
    boxShadow: "0 4px 12px rgba(1,5,7,0.06)",
  };

  // Track which bars have already been rendered so only newly-arriving ones animate.
  const seen = useRef(new Set<number>());
  const isNew = (i: number) => {
    if (seen.current.has(i)) return false;
    seen.current.add(i);
    return true;
  };

  if (!data || !Array.isArray(data) || data.length === 0) {
    return (
      <div className="max-w-2xl mx-auto my-4 rounded-2xl border border-[#DBDBE5] bg-white p-6 shadow-sm">
        <div className="font-semibold text-[#010507]">{title}</div>
        <div className="text-sm text-[#57575B]">{description}</div>
        <p className="text-[#AFAFB7] text-center py-8 text-sm">
          No data available
        </p>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto my-4 overflow-hidden rounded-2xl border border-[#DBDBE5] bg-white shadow-sm">
      <style>{`
        @keyframes barSlideIn {
          from { transform: translateY(40px); opacity: 0; }
          20% { opacity: 1; }
          to { transform: translateY(0); opacity: 1; }
        }
      `}</style>
      <div className="p-4 pb-2">
        <div className="font-semibold text-[#010507]">{title}</div>
        <div className="text-sm text-[#57575B]">{description}</div>
      </div>
      <div className="px-4 pb-4">
        <ResponsiveContainer width="100%" height={280}>
          <RechartsBarChart
            data={data}
            margin={{ top: 12, right: 12, bottom: 4, left: -8 }}
          >
            <CartesianGrid
              strokeDasharray="3 3"
              stroke="#E9E9EF"
              vertical={false}
            />
            <XAxis
              dataKey="label"
              tick={{ fontSize: 12, fill: "#838389" }}
              stroke="#E9E9EF"
              tickLine={false}
              axisLine={false}
            />
            <YAxis
              tick={{ fontSize: 12, fill: "#838389" }}
              stroke="#E9E9EF"
              tickLine={false}
              axisLine={false}
            />
            <Tooltip
              contentStyle={TOOLTIP_STYLE}
              cursor={{ fill: "#F0F0F4", opacity: 0.5 }}
            />
            <Bar
              isAnimationActive={false}
              dataKey="value"
              radius={[6, 6, 0, 0]}
              maxBarSize={48}
              shape={(props: any) => (
                <g
                  style={
                    isNew(props.index as number)
                      ? {
                          animation:
                            "barSlideIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) both",
                        }
                      : undefined
                  }
                >
                  <Rectangle {...props} />
                </g>
              )}
            >
              {data.map((_, index) => (
                <Cell
                  key={index}
                  fill={CHART_COLORS[index % CHART_COLORS.length]}
                />
              ))}
            </Bar>
          </RechartsBarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import React from "react";
import { z } from "zod";

export const pieChartPropsSchema = z.object({
  title: z.string().describe("Chart title"),
  description: z.string().describe("Brief description or subtitle"),
  data: z.array(
    z.object({
      label: z.string(),
      value: z.number(),
    }),
  ),
});

export type PieChartProps = z.infer<typeof pieChartPropsSchema>;

export function PieChart({ title, description, data }: PieChartProps) {
  const CHART_COLORS = [
    "#BEC2FF",
    "#85ECCE",
    "#FFAC4D",
    "#FFF388",
    "#189370",
    "#EEE6FE",
    "#FA5F67",
  ];

  if (!data || !Array.isArray(data) || data.length === 0) {
    return (
      <div className="max-w-lg mx-auto my-4 rounded-2xl border border-[#DBDBE5] bg-white p-6 shadow-sm">
        <div className="font-semibold text-[#010507]">{title}</div>
        <div className="text-sm text-[#57575B]">{description}</div>
        <p className="text-[#AFAFB7] text-center py-8 text-sm">
          No data available
        </p>
      </div>
    );
  }

  const total = data.reduce((sum, d) => sum + (Number(d.value) || 0), 0);

  // Donut slice geometry
  const size = 240;
  const strokeWidth = 40;
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const center = size / 2;

  let accumulated = 0;
  const slices = data.map((item, index) => {
    const val = Number(item.value) || 0;
    const ratio = total > 0 ? val / total : 0;
    const arc = ratio * circumference;
    const startAt = accumulated;
    accumulated += arc;
    return {
      arc,
      gap: circumference - arc,
      dashoffset: -startAt,
      color: CHART_COLORS[index % CHART_COLORS.length],
    };
  });

  return (
    <div className="max-w-lg mx-auto my-4 overflow-hidden rounded-2xl border border-[#DBDBE5] bg-white shadow-sm">
      <div className="p-4 pb-0">
        <div className="font-semibold text-[#010507]">{title}</div>
        <div className="text-sm text-[#57575B]">{description}</div>
      </div>
      <div className="px-4 pb-4 pt-4">
        <svg
          width="100%"
          viewBox={`0 0 ${size} ${size}`}
          className="block mx-auto"
          style={{ maxWidth: size, transform: "scaleX(-1)" }}
        >
          <circle
            cx={center}
            cy={center}
            r={radius}
            fill="none"
            stroke="#F0F0F4"
            strokeWidth={strokeWidth}
          />
          {slices.map((slice, i) => (
            <circle
              key={i}
              cx={center}
              cy={center}
              r={radius}
              fill="none"
              stroke={slice.color}
              strokeWidth={strokeWidth}
              strokeDasharray={`${slice.arc} ${slice.gap}`}
              strokeDashoffset={slice.dashoffset}
              strokeLinecap="butt"
              transform={`rotate(-90 ${center} ${center})`}
            />
          ))}
        </svg>

        <div className="space-y-2 pt-4">
          {data.map((item, index) => {
            const val = Number(item.value) || 0;
            const pct = total > 0 ? ((val / total) * 100).toFixed(0) : 0;
            return (
              <div key={index} className="flex items-center gap-3 text-sm">
                <span
                  className="inline-block h-3 w-3 rounded-full shrink-0"
                  style={{
                    backgroundColor: CHART_COLORS[index % CHART_COLORS.length],
                  }}
                />
                <span className="flex-1 text-[#010507] truncate">
                  {item.label}
                </span>
                <span className="text-[#57575B] tabular-nums">
                  {val.toLocaleString()}
                </span>
                <span className="text-[#57575B] text-sm w-10 text-right tabular-nums">
                  {pct}%
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

