  "shared-state-write",
  // Chat-UI demos — all reuse the default starterAgent.
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-customization-css",
  "chat-slots",
  // Headless Chat (Simple) — reuses the default `starterAgent` graph; the
  // demo's surface and frontend tool wiring live in the page component.
  "headless-simple",
  // Hitl demo (original) — reuses starter agent.
  "hitl",
];

const agents: Record<string, LangGraphAgent> = {};
for (const name of starterAgentNames) {
  agents[name] = createAgent();
}
agents["default"] = createAgent();
agents["starterAgent"] = createAgent();

// gen-ui-interrupt + interrupt-headless share the dedicated interrupt_agent
// graph, which uses langgraph's interrupt() primitive inside its
// schedule_meeting tool.
agents["gen-ui-interrupt"] = createAgent("interrupt_agent");
agents["interrupt-headless"] = createAgent("interrupt_agent");

// Demo-specific graphs. Agent name (as used on the frontend
// `<CopilotKit agent="...">` prop) → graphId in src/agent/langgraph.json.
const demoAgents: Record<string, string> = {
  frontend_tools: "frontend_tools",
  "frontend-tools-async": "frontend_tools_async",
  "hitl-in-app": "hitl_in_app",
  // In-Chat HITL — useHumanInTheLoop with frontend-rendered time-picker.
  "hitl-in-chat": "hitl_in_chat",
  "readonly-state-agent-context": "readonly_state_agent_context",
  "shared-state-read-write": "shared_state_read_write",
  "shared-state-streaming": "shared_state_streaming",
  subagents: "subagents",
  "gen-ui-agent": "gen_ui_agent",
  // Tool-Based Generative UI — dedicated data-viz graph; the frontend
  // registers render_bar_chart / render_pie_chart via useComponent.
  "gen-ui-tool-based": "gen_ui_tool_based",
  // Thread-id frontend-tool roundtrip — reuses the frontend_tools graph
  // (non-manifest demo, kept for frontend byte-parity with langgraph-python).
  "threadid-frontend-tool-roundtrip": "frontend_tools",
  // Reasoning demos (reasoning-custom + reasoning-default) share one dedicated
  // reasoning graph — the only frontend difference is the reasoningMessage slot.
  "reasoning-custom": "agentic-chat-reasoning",
  "reasoning-default": "agentic-chat-reasoning",
  // Tool rendering variants all share the ONE tool_rendering graph (same
  // backend tools); the cells differ only in the frontend renderer wiring.
  // Mirrors langgraph-python, which maps all three cells to `tool_rendering`.
  "tool-rendering": "tool_rendering",
  "tool-rendering-default-catchall": "tool_rendering",
  "tool-rendering-custom-catchall": "tool_rendering",
  "tool-rendering-reasoning-chain": "tool-rendering-reasoning-chain",
};
for (const [agentName, graphId] of Object.entries(demoAgents)) {
  agents[agentName] = createAgent(graphId);
}

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

const copilotkitPost = async (req: NextRequest): Promise<Response> => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    // Log full error details server-side with a correlation id, but only
    // return the id (not the message or stack) to the client. Returning
    // raw `err.message` / `err.stack` over the wire leaks internals
    // (file paths, library versions, sometimes secrets in nested error
    // messages) to anyone who can hit /api/copilotkit.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        route: "/api/copilotkit",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

// Wrap with CVDIAG backend instrumentation. `withCvdiagBackend` returns
// `copilotkitPost` unchanged when CVDIAG_BACKEND_EMITTER is off (default), so
// the instrumented path costs nothing in normal operation.
export const POST = withCvdiagBackend(copilotkitPost, {
  slug: "langgraph-typescript",
  agentName: "starterAgent",
  provider: "openai",
});

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/ok`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

"use client";

import React, { useCallback, useState } from "react";

export type SlotColor =
  | "indigo"
  | "violet"
  | "emerald"
  | "sky"
  | "amber"
  | "rose"
  | "orange"
  | "red"
  | "yellow"
  | "pink"
  | "cyan"
  | "teal"
  | "lime"
  | "fuchsia";

// Static lookups so Tailwind v4's source scanner finds every class string at
// build time. Dynamic concatenation like `border-${color}-400` would not work.
export const SLOT_COLORS: Record<
  SlotColor,
  { border: string; label: string; ring: string }
> = {
  indigo: {
    border: "border-indigo-400",
    label: "bg-indigo-500",
    ring: "ring-indigo-400/40",
  },
  violet: {
    border: "border-violet-400",
    label: "bg-violet-500",
    ring: "ring-violet-400/40",
  },
  emerald: {
    border: "border-emerald-400",
    label: "bg-emerald-500",
    ring: "ring-emerald-400/40",
  },
  sky: {
    border: "border-sky-400",
    label: "bg-sky-500",
    ring: "ring-sky-400/40",
  },
  amber: {
    border: "border-amber-400",
    label: "bg-amber-500",
    ring: "ring-amber-400/40",
  },
  rose: {
    border: "border-rose-400",
    label: "bg-rose-500",
    ring: "ring-rose-400/40",
  },
  orange: {
    border: "border-orange-400",
    label: "bg-orange-500",
    ring: "ring-orange-400/40",
  },
  red: {
    border: "border-red-400",
    label: "bg-red-500",
    ring: "ring-red-400/40",
  },
  yellow: {
    border: "border-yellow-400",
    label: "bg-yellow-500",
    ring: "ring-yellow-400/40",
  },
  pink: {
    border: "border-pink-400",
    label: "bg-pink-500",
    ring: "ring-pink-400/40",
  },
  cyan: {
    border: "border-cyan-400",
    label: "bg-cyan-500",
    ring: "ring-cyan-400/40",
  },
  teal: {
    border: "border-teal-400",
    label: "bg-teal-500",
    ring: "ring-teal-400/40",
  },
  lime: {
    border: "border-lime-400",
    label: "bg-lime-500",
    ring: "ring-lime-400/40",
  },
  fuchsia: {
    border: "border-fuchsia-400",
    label: "bg-fuchsia-500",
    ring: "ring-fuchsia-400/40",
  },
};

/**
 * Wraps a slot region with a dashed outline plus a small clickable badge
 * that copies the slot's component path to the clipboard.
 *
 * The label is opacity-0 by default and turns visible only when this marker
 * is hovered AND no descendant marker is also hovered. Markers nest
 * (welcomeScreen wraps welcomeMessage / input / suggestionView), so a plain
 * `:hover .slot-label { opacity: 1 }` would light up every nested label.
 * The `:not(:has(.slot-marker:hover))` predicate isolates each marker.
 */
export function SlotMarker({
  color,
  label,
  children,
  inline,
  className,
}: {
  color: SlotColor;
  label: string;
  children: React.ReactNode;
  inline?: boolean;
  className?: string;
}) {
  const c = SLOT_COLORS[color];
  const [copied, setCopied] = useState(false);

  const onCopy = useCallback(
    async (e: React.MouseEvent<HTMLButtonElement>) => {
      e.preventDefault();
      e.stopPropagation();
      try {
        await navigator.clipboard.writeText(label);
        setCopied(true);
        setTimeout(() => setCopied(false), 1100);
      } catch {
        // clipboard may be unavailable (e.g. insecure context); silently no-op
      }
    },
    [label],
  );

  return (
    <span
      data-slot-label={label}
      className={`slot-marker relative ${inline ? "inline-flex" : "flex"} border border-dashed ${c.border} rounded-lg p-1 ${className ?? ""}`}
      style={{ flexDirection: inline ? "row" : "column" }}
    >
      <button
        type="button"
        onClick={onCopy}
        title={copied ? "Copied!" : `Copy slot path: ${label}`}
        aria-label={`Copy slot path ${label}`}
        className={`slot-label absolute -top-2 left-2 inline-flex items-center gap-1 rounded ${c.label} text-white text-[9px] font-bold uppercase tracking-wider px-1.5 py-px shadow-sm z-10 whitespace-nowrap opacity-0 transition-opacity hover:brightness-110 cursor-pointer pointer-events-auto font-mono normal-case tracking-normal`}
      >
        <span>{copied ? "Copied" : label}</span>
        <span aria-hidden="true" className="text-white/70 text-[8px]">
          {copied ? "✓" : "⧉"}
        </span>
      </button>
      <span style={{ display: "contents" }}>{children}</span>
    </span>
  );
}

// Docs-only snippet — not imported or rendered. The langgraph-python
// chat-slots production demo registers a dozen slot overrides at once
// (see page.tsx) with `as unknown as typeof X` casts that exist to
// satisfy the WithSlots types when the wrappers are structurally
// compatible but not nominally identical. That's necessary in the
// running app but obscures the teaching shape.
//
// This file gives the slots docs page (custom-look-and-feel/slots.mdx)
// three minimal teaching examples — the welcome screen, assistant
// message, and disclaimer slot patterns — without changing the
// production demo's runtime behavior. See agentic-chat /
// chat-component.snippet.tsx for the same sibling-file pattern.

import type {
  CopilotChatAssistantMessage,
  CopilotChatInput,
  CopilotChatView,
} from "@copilotkit/react-core/v2";

declare const CustomWelcomeScreen: React.ComponentType;
declare const CustomAssistantMessage: React.ComponentType;
declare const CustomDisclaimer: React.ComponentType;

export function ChatSlotsTeachingExtracts() {
  const welcomeScreen =
    CustomWelcomeScreen as unknown as typeof CopilotChatView.WelcomeScreen;

  const messageView = {
    assistantMessage:
      CustomAssistantMessage as unknown as typeof CopilotChatAssistantMessage,
  };

  const input = {
    disclaimer:
      CustomDisclaimer as unknown as typeof CopilotChatInput.Disclaimer,
  };

  return { welcomeScreen, messageView, input };
}

"use client";

import React from "react";
import {
  CopilotChatAssistantMessage,
  CopilotChatUserMessage,
  CopilotChatReasoningMessage,
  CopilotChatMessageView,
  CopilotChatView,
  CopilotChatInput,
  CopilotChatSuggestionPill,
  type CopilotChatAssistantMessageProps,
  type CopilotChatUserMessageProps,
  type CopilotChatReasoningMessageProps,
  type CopilotChatSuggestionPillProps,
} from "@copilotkit/react-core/v2";
import { SlotMarker } from "./slot-marker";

// =====================================================================
// welcomeScreen + welcomeScreen.welcomeMessage
// The welcomeScreen receives `input` and `suggestionView` as elements; we
// also expose the `welcomeMessage` sub-slot to show that slots can nest.
// =====================================================================
export function CustomWelcomeMessage(
  props: React.HTMLAttributes<HTMLDivElement>,
) {
  return (
    <SlotMarker color="violet" label="WelcomeScreen.WelcomeMessage">
      <div
        {...props}
        className="text-center px-4 py-3 text-sm text-muted-foreground"
        data-testid="custom-welcome-message"
      >
        Hover any region to see its slot path · click the badge to copy
      </div>
    </SlotMarker>
  );
}

export function CustomWelcomeScreen({
  input,
  suggestionView,
}: {
  input: React.ReactElement;
  suggestionView: React.ReactElement;
  welcomeMessage?: React.ReactElement;
}) {
  return (
    <SlotMarker color="indigo" label="WelcomeScreen" className="flex-1 m-3">
      <div
        data-testid="custom-welcome-screen"
        className="flex-1 flex flex-col items-center justify-center px-4 py-6 gap-4 w-full"
      >
        <CustomWelcomeMessage />
        <div className="w-full max-w-2xl">{input}</div>
        <div className="flex justify-center">{suggestionView}</div>
      </div>
    </SlotMarker>
  );
}

// =====================================================================
// messageView.assistantMessage
// =====================================================================
export function CustomAssistantMessage(
  props: CopilotChatAssistantMessageProps,
) {
  return (
    <SlotMarker
      color="emerald"
      label="MessageView.AssistantMessage"
      className="my-3"
    >
      <CopilotChatAssistantMessage {...props} />
    </SlotMarker>
  );
}

// =====================================================================
// messageView.userMessage
// =====================================================================
export function CustomUserMessage(props: CopilotChatUserMessageProps) {
