"use client";

/**
 * A2UI Error Recovery demo.
 *
 * Same dynamic-schema A2UI setup as declarative-gen-ui (it reuses that demo's
 * catalog), but it makes the toolkit's validate->retry recovery loop visible.
 * The dedicated runtime at `/api/copilotkit-a2ui-recovery` is configured with
 * `injectA2UITool: false` — the backend agent (`src/agents/recovery_agent.py`)
 * owns `generate_a2ui` via `ag_ui_langgraph.get_a2ui_tools`, whose body runs
 * the forced `render_a2ui` sub-agent and the recovery loop + recovery-exhausted
 * hard-fail envelope IN-GRAPH (OSS-158 / OSS-375).
 *
 * The two suggestion pills drive aimock fixtures that force:
 *   - HEAL: an invalid first render that recovers to a valid one
 *     (building -> retrying -> painted).
 *   - EXHAUST: an always-invalid render that hits the attempt cap
 *     (a tasteful `failed` state, never a broken surface).
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";

// Reuse the declarative-gen-ui catalog (same components, same catalogId).
import { myCatalog } from "../declarative-gen-ui/a2ui/catalog";
import { Chat } from "./chat";

export default function A2uiRecoveryDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-a2ui-recovery"
      agent="a2ui-recovery"
      a2ui={{ catalog: myCatalog }}
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

/**
 * LangGraph TypeScript agent for the A2UI Error Recovery demo (OSS-158 / OSS-375).
 *
 * Same dynamic-schema A2UI setup as `a2ui-dynamic.ts` (declarative-gen-ui), but
 * with the toolkit's validate->retry recovery loop made *visible*. The two
 * aimock pills drive the inner `render_a2ui` sub-agent two ways:
 *   - HEAL pill: attempt 1 (aimock sequenceIndex 0) is structurally INVALID
 *     (the root references a missing child) — the validate->retry loop rejects
 *     it and retries; attempt 2 (sequenceIndex 1) is VALID and paints.
 *   - EXHAUST pill: every attempt is structurally invalid (the root references
 *     a missing child), so the validate->retry loop hits the cap and the tool
 *     returns the `a2ui_recovery_exhausted` hard-fail envelope, which the
 *     renderer surfaces as a tasteful `failed` state (no broken surface).
 *
 * Backend-owned wiring: unlike the declarative-gen-ui demo (which relies on the
 * CopilotKit runtime auto-injecting `generate_a2ui`), this agent OWNS the tool
 * via `@ag-ui/langgraph` `getA2UITools`, whose body runs the `render_a2ui`
 * sub-agent + the toolkit recovery loop IN-GRAPH. The dedicated route sets
 * `injectA2UITool: false` so the runtime does not inject a second copy.
 *
 * Header forwarding (load-bearing for aimock D6 stability — OSS-583):
 * `getA2UITools` invokes its inner `render_a2ui` sub-agent via a CONFIG-LESS
 * `model.stream(...)` call, so the config-based header-forwarding path used by
 * every other langgraph-typescript agent (`makeChatOpenAI`, which reads
 * `config.configurable.copilotkit_forwarded_headers`) can NOT reach the inner
 * render call. Without forwarding, the inner render's aimock request carries no
 * `x-test-id`, so aimock buckets its `sequenceIndex` state under the shared
 * `DEFAULT_TEST_ID` — which the harness never resets between runs. Result: the
 * heal fixture's seq0(invalid)->seq1(valid) staging works on the FIRST run but
 * the consumed valid response is never re-served on subsequent runs (the loop
 * then exhausts and reds). This mirrors the flake mastra solved at the fetch
 * layer (`_header_forwarding.ts`).
 *
 * Fix (mirrors the mastra fetch+ALS mechanism, adapted to the LangGraph server):
 * an AsyncLocalStorage store holds the inbound `x-*` headers; the models' custom
 * `fetch` merges them onto every outbound OpenAI call (including the inner
 * render). The store is bound by `wrapModelCall` / `wrapToolCall` middleware,
 * which read `copilotkit_forwarded_headers` off the per-call runtime config and
 * run the handler inside `store.run(...)` — enclosing the outer emit AND the
 * config-less inner render sub-agent stream (which executes inside the tool
 * handler). A `beforeAgent`+`enterWith` binding does NOT work here: Pregel runs
 * each node in a separate async context, so the store would not reach the tool
 * node.
 *
 * Mirrors `showcase/integrations/langgraph-python/src/agents/recovery_agent.py`.
 * Catalog is reused from declarative-gen-ui ("declarative-gen-ui-catalog"); the
 * Vantage Threads sales dataset + composition rules arrive from the frontend via
 * App Context (declarative-gen-ui/sales-context.ts).
 */

import { AsyncLocalStorage } from "node:async_hooks";
import { createAgent, createMiddleware } from "langchain";
import { copilotkitMiddleware } from "@copilotkit/sdk-js/langgraph";
import { ChatOpenAI } from "@langchain/openai";
import { getA2UITools } from "@ag-ui/langgraph";
import type { A2UIAttemptRecord } from "@ag-ui/langgraph";

const SYSTEM_PROMPT =
  "You are the embedded sales analyst for Vantage Threads, the fictional B2B " +
  "apparel company described in your App Context. Answer every business " +
  "question by calling `generate_a2ui` to draw a rich visual surface, and keep " +
  "the chat reply to one short sentence. Ground every number in the sales " +
  "dataset from your App Context. `generate_a2ui` handles the rendering — and " +
  "its automatic recovery — for you.";

/**
 * ALS-bound snapshot of the inbound `x-*` headers for the current graph run.
 * Populated by `headerForwardingMiddleware`'s `wrapModelCall` / `wrapToolCall`
 * hooks (which read the config and run the handler inside `store.run(...)`; note
 * there is deliberately no `beforeAgent` binding — see below) and read by
 * `forwardingFetch` on every outbound OpenAI call — including the config-less
 * inner `render_a2ui` sub-agent stream.
 */
const forwardedHeadersStore = new AsyncLocalStorage<Record<string, string>>();

/** Merge the ALS-bound `x-*` headers onto every outbound OpenAI request so the
 *  inner render sub-agent's aimock call carries `x-test-id` / `x-aimock-context`. */
const forwardingFetch: typeof fetch = (input, init) => {
  const forwarded = forwardedHeadersStore.getStore() ?? {};
  const merged = new Headers(init?.headers);
  for (const [k, v] of Object.entries(forwarded)) {
    // Don't clobber an explicit per-call header.
    if (!merged.has(k)) merged.set(k, v);
  }
  return fetch(input, { ...init, headers: merged });
};

/** Read the `copilotkit_forwarded_headers` map (set by @ag-ui/langgraph) off a
 *  configurable object, keeping only string `x-*` entries. */
function extractXHeaders(
  configurable: Record<string, unknown> | undefined,
): Record<string, string> {
  const raw = configurable?.copilotkit_forwarded_headers;
  const out: Record<string, string> = {};
  if (raw && typeof raw === "object") {
    for (const [k, v] of Object.entries(raw as Record<string, unknown>)) {
      if (typeof v === "string" && k.toLowerCase().startsWith("x-")) {
        out[k.toLowerCase()] = v;
      }
    }
  }
  return out;
}

/**
 * Bind the inbound `x-*` headers into ALS around the model call AND the tool
 * call, so every outbound OpenAI request inside either — including the
 * config-less inner `render_a2ui` sub-agent stream that runs inside the tool
 * handler — sees them via `forwardingFetch`.
 *
 * Why `wrapModelCall`/`wrapToolCall` and NOT `beforeAgent`+`enterWith`: the
 * LangGraph Pregel executor dispatches each node (beforeAgent, model, tool) in
 * a SEPARATE async context, so a store set with `enterWith` in `beforeAgent`
 * does not propagate into the later tool node. `wrapToolCall` instead runs the
 * tool `handler` INSIDE this hook's async scope, so `forwardedHeadersStore.run`
 * correctly encloses the inner render sub-agent's fetch.
 */
const headerForwardingMiddleware = createMiddleware({
  name: "a2ui-recovery-header-forwarding",
  wrapModelCall: (
    request: { runtime?: { configurable?: Record<string, unknown> } },
    handler: (req: any) => any,
  ) => {
    const headers = extractXHeaders(request?.runtime?.configurable);
    return forwardedHeadersStore.run(headers, () => handler(request));
  },
  wrapToolCall: (
    request: { runtime?: { configurable?: Record<string, unknown> } },
    handler: (req: any) => any,
  ) => {
    const headers = extractXHeaders(request?.runtime?.configurable);
    return forwardedHeadersStore.run(headers, () => handler(request));
  },
});

const a2uiTool = getA2UITools({
  model: new ChatOpenAI({
    model: "gpt-5-mini",
    configuration: { fetch: forwardingFetch },
  }),
  defaultCatalogId: "declarative-gen-ui-catalog",
  // Recovery loop runs by default; pinned here so the renderer's "Retrying…
  // (N/M)" label matches the adapter's cap.
  recovery: { maxAttempts: 3 },
  onA2UIAttempt: (rec: A2UIAttemptRecord) => {
    // Dev observability: each attempt (incl. rejected ones) is logged.
    // eslint-disable-next-line no-console
    console.log(
      `[a2ui recovery] attempt ${rec.attempt}: ${rec.ok ? "valid" : "invalid"}`,
      rec.errors,
    );
  },
});

export const graph = createAgent({
  model: new ChatOpenAI({
    model: "gpt-5-mini",
    configuration: { fetch: forwardingFetch },
  }),
  // Cast: tool typed against @ag-ui/langgraph's own @langchain/core peer.
  tools: [a2uiTool as any],
  middleware: [headerForwardingMiddleware, copilotkitMiddleware],
  systemPrompt: SYSTEM_PROMPT,
});

// Dedicated runtime for the A2UI Error Recovery demo.
// `a2ui.injectA2UITool: false` — the backend LangGraph (TS) agent OWNS
// `generate_a2ui` via `@ag-ui/langgraph` `getA2UITools` (see
// src/agent/recovery-agent.ts), whose body runs the `render_a2ui` sub-agent +
// the toolkit validate->retry recovery loop + the recovery-exhausted hard-fail
// envelope IN-GRAPH (OSS-158 / OSS-375). The runtime must NOT inject a second
// copy (double-bind); this `false` is load-bearing post CopilotKit#5611 (the
// provider catalog otherwise defaults injectA2UITool to true). The middleware
// still renders the building -> retrying (N/M) -> painted / failed lifecycle.
//
// The demo reuses the declarative-gen-ui catalog. The aimock fixtures force the
// inner render_a2ui sub-agent to emit free-form/sloppy args the middleware heals
// (heal pill) or a structurally-invalid surface on every attempt (exhaust pill).

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { LangGraphAgent } from "@copilotkit/runtime/langgraph";

const LANGGRAPH_URL =
  process.env.LANGGRAPH_DEPLOYMENT_URL || "http://localhost:8123";

const recoveryAgent = new LangGraphAgent({
  deploymentUrl: `${LANGGRAPH_URL}/`,
  graphId: "a2ui_recovery",
  langsmithApiKey: process.env.LANGSMITH_API_KEY || "",
});

const runtime = new CopilotRuntime({
  // @ts-ignore -- see main route.ts
  agents: { "a2ui-recovery": recoveryAgent },
  a2ui: {
    injectA2UITool: false,
    // Reuse the catalog the page registers (shared with declarative-gen-ui).
    defaultCatalogId: "declarative-gen-ui-catalog",
  },
});

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-a2ui-recovery",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

"use client";

import { CopilotChat } from "@copilotkit/react-core/v2";
import { useA2uiRecoverySuggestions } from "./suggestions";
// Reuse the declarative-gen-ui sales dataset/context so the healed surface has
// real numbers to render.
import { useSalesAnalystContext } from "../declarative-gen-ui/sales-context";

export function Chat() {
  useA2uiRecoverySuggestions();
  useSalesAnalystContext();
  return <CopilotChat agentId="a2ui-recovery" className="h-full rounded-2xl" />;
}

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

// Two pills exercise the recovery loop deterministically via aimock fixtures
// (showcase/aimock/d6/langgraph-typescript/a2ui-recovery.json). Prompts are
// UNIQUE per framework slug: the inner render_a2ui calls carry no
// x-aimock-context, so identical prompts across frameworks would collide in the
// shared aimock matcher. These langgraph-typescript strings mirror the probe
// (harness/src/probes/scripts/d5-a2ui-recovery.ts PROMPTS["langgraph-typescript"]).
//   - "heal":    inner render_a2ui returns free-form/sloppy args (components &
//                data as JSON strings) -> middleware parse_and_fix heals them
//                into a valid surface in a single pass -> painted.
//   - "exhaust": inner render_a2ui is invalid on every attempt -> attempt cap
//                hit -> a2ui_recovery_exhausted -> tasteful `failed` state.
export function useA2uiRecoverySuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Recover a bad render",
        message: "Lay out a sales KPI panel and heal a broken first attempt.",
      },
      {
        title: "Show an unrecoverable failure",
        message:
          "Lay out a KPI panel that never passes validation so I can reveal the fallback.",
      },
    ],
    available: "always",
  });
}

"use client";

/**
 * MCP Apps demo.
 *
 * MCP Apps are MCP servers that expose tools with associated UI resources.
 * The CopilotKit runtime is wired with `mcpApps: { servers: [...] }`
 * (see `src/app/api/copilotkit-mcp-apps/route.ts`), which auto-applies the
 * MCP Apps middleware. When the agent calls an MCP tool, the middleware
 * fetches the associated UI resource and emits an activity event; the
 * built-in `MCPAppsActivityRenderer` registered by `CopilotKitProvider`
 * renders the sandboxed iframe inline in the chat — no app-side renderer
 * registration required.
 *
 * This cell points at the public Excalidraw MCP app (https://mcp.excalidraw.com).
 *
 * Reference:
 * https://docs.copilotkit.ai/integrations/langgraph/generative-ui/mcp-apps
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";
import { Chat } from "./chat";

export default function MCPAppsDemo() {
  // No `renderActivityMessages`, no `useRenderActivityMessage` — the
  // CopilotKitProvider auto-registers the built-in `MCPAppsActivityRenderer`
  // for the "mcp-apps" activity type. A plain <CopilotChat /> is enough.
  return (
    <CopilotKit runtimeUrl="/api/copilotkit-mcp-apps" agent="mcp-apps">
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

/**
 * LangGraph TypeScript agent for the CopilotKit MCP Apps demo.
 *
 * This agent has no bespoke tools — the CopilotKit runtime is wired with
 * `mcpApps: { servers: [...] }` pointing at the public Excalidraw MCP
 * server (see `src/app/api/copilotkit-mcp-apps/route.ts`). The runtime
 * auto-applies the MCP Apps middleware which exposes the remote MCP
 * server's tools to this agent at request time and emits the activity
 * events that CopilotKit's built-in `MCPAppsActivityRenderer` renders in
 * the chat as a sandboxed iframe.
 *
 * Ported from `src/agents/mcp_apps_agent.py`.
 *
 * NOTE: The TS runtime performs MCP tool injection via the A2UI/MCP-Apps
 * middleware before the graph sees the request. The graph itself doesn't
 * need bespoke MCP client wiring.
 */

import { RunnableConfig } from "@langchain/core/runnables";
import { AIMessage, SystemMessage } from "@langchain/core/messages";
import {
  MemorySaver,
  START,
  END,
  StateGraph,
  Annotation,
} from "@langchain/langgraph";
import { ChatOpenAI } from "@langchain/openai";
import { makeChatOpenAI } from "./openai-headers";

import {
  convertActionsToDynamicStructuredTools,
  CopilotKitStateAnnotation,
} from "@copilotkit/sdk-js/langgraph";

const SYSTEM_PROMPT = `You draw simple diagrams in Excalidraw via the MCP tool.

SPEED MATTERS. Produce a correct-enough diagram fast; do not optimize
for polish. Target: one tool call, done in seconds.

When the user asks for a diagram:
1. Call \`create_view\` ONCE with 3-5 elements total: shapes + arrows +
   an optional title text.
2. Use straightforward shapes (rectangle, ellipse, diamond) with plain
   \`label\` fields (\`{"text": "...", "fontSize": 18}\`) on them.
3. Connect with arrows. Endpoints can be element centers or simple
   coordinates — you don't need edge anchors / fixedPoint bindings.
4. Include ONE \`cameraUpdate\` at the END of the elements array that
   frames the whole diagram. Use an approved 4:3 size (600x450 or
   800x600). No opening camera needed.
5. Reply with ONE short sentence describing what you drew.

Every element needs a unique string \`id\` (e.g. \`"b1"\`, \`"a1"\`,
\`"title"\`). Standard sizes: rectangles 160x70, ellipses/diamonds
120x80, 40-80px gap between shapes.

Do NOT:
- Call \`read_me\`. You already know the basic shape API.
- Make multiple \`create_view\` calls.
- Iterate or refine. Ship on the first shot.
- Add decorative colors / fills / zone backgrounds unless the user
  explicitly asks for them.
- Add labels on arrows unless crucial.

If the user asks for something specific (colors, more elements,
particular layout), follow their lead — but still in ONE call.`;

const AgentStateAnnotation = Annotation.Root({
  ...CopilotKitStateAnnotation.spec,
});

export type AgentState = typeof AgentStateAnnotation.State;

async function chatNode(state: AgentState, config: RunnableConfig) {
  // gpt-5-mini for speed — Excalidraw element emission is simple JSON and
  // we're biasing hard toward sub-30s generation.
  const model = makeChatOpenAI(config, {
    temperature: 0,
    model: "gpt-5-mini",
  });

  // The MCP Apps middleware injects MCP tools into state.copilotkit.actions
  // alongside any frontend actions, so a single bind picks up everything.
  const copilotActions = convertActionsToDynamicStructuredTools(
    state.copilotkit?.actions ?? [],
  );

  const modelWithTools =
    copilotActions.length > 0 ? model.bindTools!(copilotActions) : model;

  const systemMessage = new SystemMessage({ content: SYSTEM_PROMPT });

  const response = await modelWithTools.invoke(
    [systemMessage, ...state.messages],
    config,
  );

  return { messages: response };
}

function shouldContinue({ messages }: AgentState) {
  const lastMessage = messages[messages.length - 1] as AIMessage;
  // All tool calls are frontend (MCP-injected) actions — never locally
  // handled. End the run and let the runtime dispatch them.
  return lastMessage.tool_calls?.length ? END : END;
}

const workflow = new StateGraph(AgentStateAnnotation)
  .addNode("chat_node", chatNode)
  .addEdge(START, "chat_node")
  .addConditionalEdges("chat_node", shouldContinue as any);

const memory = new MemorySaver();

export const graph = workflow.compile({
  checkpointer: memory,
});

// CopilotKit runtime for the MCP Apps cell — shared by two demos:
//   - headless-complete (cell exercises MCP Apps rendering via a hand-rolled
//     useRenderActivityMessage in use-rendered-messages.tsx)
//   - mcp-apps (relies on CopilotKit's built-in MCPAppsActivityRenderer)
//
// The runtime's `mcpApps` config auto-applies the MCP Apps middleware to the
// agent: when the agent calls a tool backed by an MCP UI resource, the
// middleware fetches the resource and emits the activity event that the
// built-in `MCPAppsActivityRenderer` (registered by CopilotKit internally)
// renders in the chat as a sandboxed iframe.
//
// Reference:
// https://docs.copilotkit.ai/integrations/langgraph/generative-ui/mcp-apps

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import { randomUUID } from "node:crypto";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { LangGraphAgent } from "@copilotkit/runtime/langgraph";

const LANGGRAPH_URL =
  process.env.LANGGRAPH_DEPLOYMENT_URL || "http://localhost:8123";

const headlessCompleteAgent = new LangGraphAgent({
  deploymentUrl: `${LANGGRAPH_URL}/`,
  graphId: "headless_complete",
  langsmithApiKey: process.env.LANGSMITH_API_KEY || "",
});

const mcpAppsAgent = new LangGraphAgent({
  deploymentUrl: `${LANGGRAPH_URL}/`,
  graphId: "mcp_apps",
  langsmithApiKey: process.env.LANGSMITH_API_KEY || "",
});

// The `mcpApps.servers` config is all you need server-side. The runtime
// auto-applies the MCP Apps middleware to every registered agent: on each
// MCP tool call it fetches the associated UI resource and emits an
// `activity` event that the built-in `MCPAppsActivityRenderer` renders
// inline in the chat.
const runtime = new CopilotRuntime({
  // @ts-ignore -- Published CopilotRuntime agents type wraps Record in
  // MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in
  // source, pending release.
  agents: {
    "headless-complete": headlessCompleteAgent,
    "mcp-apps": mcpAppsAgent,
  },
  mcpApps: {
    servers: [
      {
        type: "http",
        url: process.env.MCP_SERVER_URL || "https://mcp.excalidraw.com",
        // Always pin a stable `serverId`. Without it CopilotKit hashes the
        // URL, and a URL change silently breaks restoration of persisted
        // MCP Apps in prior conversation threads.
        serverId: "excalidraw",
      },
    ],
  },
});

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-mcp-apps",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    // Log full error details server-side with a correlation id, but only
    // return the id (not the message or stack) to the client. Returning
    // raw `err.message` / `err.stack` over the wire leaks internals
    // (file paths, library versions, sometimes secrets in nested error
    // messages) to anyone who can hit /api/copilotkit-mcp-apps.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        route: "/api/copilotkit-mcp-apps",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

"use client";

import { CopilotChat } from "@copilotkit/react-core/v2";
import { useMcpAppsSuggestions } from "./suggestions";

export function Chat() {
  useMcpAppsSuggestions();
  return <CopilotChat agentId="mcp-apps" className="h-full rounded-2xl" />;
}

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export function useMcpAppsSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Draw a flowchart",
        message: "Use Excalidraw to draw a simple flowchart with three steps.",
      },
      {
        title: "Sketch a system diagram",
        message:
          "Open Excalidraw and sketch a system diagram with a client, server, and database.",
      },
    ],
    available: "always",
  });
}

