"use client";

import { useRef } from "react";
import {
  BarChart as RechartsBarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Rectangle,
} from "recharts";
import { CHART_COLORS, CHART_CONFIG } from "./chart-config";

export interface BarChartDatum {
  label: string;
  value: number;
}

export interface BarChartComponentProps {
  title: string;
  description?: string | null;
  data: BarChartDatum[];
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function AnimatedBar({ isNew, ...rest }: any) {
  return (
    <g
      style={
        isNew
          ? { animation: "barSlideIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) both" }
          : undefined
      }
    >
      <Rectangle {...rest} />
    </g>
  );
}

export function BarChart({ title, description, data }: BarChartComponentProps) {
  const seen = useRef(new Set<number>());
  const isNew = (i: number) => {
    if (seen.current.has(i)) return false;
    seen.current.add(i);
    return true;
  };

  const hasData = Array.isArray(data) && data.length > 0;

  return (
    <div
      data-testid="bar-chart"
      className="max-w-2xl mx-auto my-4 overflow-hidden rounded-lg border border-[var(--border)] bg-[var(--card)]"
    >
      {hasData && (
        <style>{`@keyframes barSlideIn { from { transform: translateY(40px); opacity: 0; } 20% { opacity: 1; } to { transform: translateY(0); opacity: 1; } }`}</style>
      )}
      <div className="p-6 pb-2">
        <h3 className="text-lg font-semibold leading-none tracking-tight text-[var(--foreground)]">
          {title}
        </h3>
        {description ? (
          <p className="text-sm text-[var(--muted-foreground)]">
            {description}
          </p>
        ) : null}
      </div>
      <div className="p-6 pt-2">
        {hasData ? (
          <ResponsiveContainer width="100%" height={280}>
            <RechartsBarChart
              data={data}
              margin={{ top: 12, right: 12, bottom: 4, left: -8 }}
            >
              <CartesianGrid
                strokeDasharray="3 3"
                stroke="var(--border)"
                vertical={false}
              />
              <XAxis
                dataKey="label"
                tick={{ fontSize: 12, fill: "var(--muted-foreground)" }}
                stroke="var(--border)"
                tickLine={false}
                axisLine={false}
              />
              <YAxis
                tick={{ fontSize: 12, fill: "var(--muted-foreground)" }}
                stroke="var(--border)"
                tickLine={false}
                axisLine={false}
              />
              <Tooltip
                contentStyle={CHART_CONFIG.tooltipStyle}
                cursor={{ fill: "var(--secondary)", opacity: 0.5 }}
              />
              <Bar
                isAnimationActive={false}
                dataKey="value"
                radius={[6, 6, 0, 0]}
                maxBarSize={48}
                shape={(props: unknown) => {
                  const p = props as Record<string, unknown>;
                  return (
                    <AnimatedBar {...p} isNew={isNew(p.index as number)} />
                  );
                }}
              >
                {data.map((_, i) => (
                  <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />
                ))}
              </Bar>
            </RechartsBarChart>
          </ResponsiveContainer>
        ) : (
          <p className="text-[var(--muted-foreground)] text-center py-8 text-sm">
            No data available
          </p>
        )}
      </div>
    </div>
  );
}

export const CHART_COLORS = [
  "#BEC2FF", // lilac-400
  "#85ECCE", // mint-400
  "#FFAC4D", // orange-400
  "#FFF388", // yellow-400
  "#189370", // mint-800
  "#EEE6FE", // primary-100
  "#FA5F67", // red-400
] as const;

export const CHART_CONFIG = {
  tooltipStyle: {
    backgroundColor: "var(--card)",
    border: "1px solid var(--border)",
    borderRadius: "10px",
    padding: "10px 14px",
    color: "var(--foreground)",
    fontSize: "13px",
    fontFamily: "var(--font-body)",
    boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
  },
};

"use client";

import { CHART_COLORS } from "./chart-config";

export interface PieChartDatum {
  label: string;
  value: number;
}

export interface PieChartComponentProps {
  title: string;
  description?: string | null;
  data: PieChartDatum[];
}

function DonutChart({
  data,
  size = 240,
  strokeWidth = 40,
}: {
  data: PieChartDatum[];
  size?: number;
  strokeWidth?: number;
}) {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const center = size / 2;
  const total = data.reduce((sum, d) => sum + (Number(d.value) || 0), 0);

  let accumulated = 0;
  const slices = data.map((item, i) => {
    const arc =
      (total > 0 ? (Number(item.value) || 0) / total : 0) * circumference;
    const dashoffset = -accumulated;
    accumulated += arc;
    return {
      arc,
      gap: circumference - arc,
      dashoffset,
      color: CHART_COLORS[i % CHART_COLORS.length],
    };
  });

  return (
    <svg
      width="100%"
      viewBox={`0 0 ${size} ${size}`}
      className="block mx-auto"
      style={{ maxWidth: size, transform: "scaleX(-1)" }}
    >
      <circle
        cx={center}
        cy={center}
        r={radius}
        fill="none"
        stroke="var(--secondary)"
        strokeWidth={strokeWidth}
      />
      {slices.map((s, i) => (
        <circle
          key={i}
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke={s.color}
          strokeWidth={strokeWidth}
          strokeDasharray={`${s.arc} ${s.gap}`}
          strokeDashoffset={s.dashoffset}
          strokeLinecap="butt"
          transform={`rotate(-90 ${center} ${center})`}
        />
      ))}
    </svg>
  );
}

export function PieChart({ title, description, data }: PieChartComponentProps) {
  const hasData = Array.isArray(data) && data.length > 0;
  const total = hasData
    ? data.reduce((sum, d) => sum + (Number(d.value) || 0), 0)
    : 0;

  return (
    <div
      data-testid="pie-chart"
      className="max-w-lg mx-auto my-4 overflow-hidden rounded-lg border border-[var(--border)] bg-[var(--card)]"
    >
      <div className="p-6 pb-0">
        <h3 className="text-lg font-semibold leading-none tracking-tight text-[var(--foreground)]">
          {title}
        </h3>
        {description ? (
          <p className="text-sm text-[var(--muted-foreground)]">
            {description}
          </p>
        ) : null}
      </div>
      <div className="p-6 pt-4">
        {hasData ? (
          <>
            <DonutChart data={data} />
            <div className="space-y-2 pt-4">
              {data.map((item, i) => {
                const val = Number(item.value) || 0;
                const pct = total > 0 ? ((val / total) * 100).toFixed(0) : 0;
                return (
                  <div key={i} className="flex items-center gap-3 text-sm">
                    <span
                      className="inline-block h-3 w-3 rounded-full shrink-0"
                      style={{
                        backgroundColor: CHART_COLORS[i % CHART_COLORS.length],
                      }}
                    />
                    <span className="flex-1 text-[var(--foreground)] truncate">
                      {item.label}
                    </span>
                    <span className="text-[var(--muted-foreground)] tabular-nums">
                      {val.toLocaleString()}
                    </span>
                    <span className="text-[var(--muted-foreground)] text-sm w-10 text-right tabular-nums">
                      {pct}%
                    </span>
                  </div>
                );
              })}
            </div>
          </>
        ) : (
          <p className="text-[var(--muted-foreground)] text-center py-8 text-sm">
            No data available
          </p>
        )}
      </div>
    </div>
  );
}

"use client";

import {
  CopilotChat,
  CopilotChatAssistantMessage,
} from "@copilotkit/react-core/v2";
import { JsonRenderAssistantMessage } from "./json-render-renderer";
import { useByocJsonRenderSuggestions } from "./suggestions";

export const AGENT_ID = "byoc_json_render";

export function Chat() {
  useByocJsonRenderSuggestions();

  return (
    <CopilotChat
      agentId={AGENT_ID}
      className="h-full rounded-2xl"
      messageView={{
        assistantMessage:
          JsonRenderAssistantMessage as unknown as typeof CopilotChatAssistantMessage,
      }}
    />
  );
}

"use client";

import { useMemo } from "react";
import {
  CopilotChatAssistantMessage,
  type CopilotChatAssistantMessageProps,
} from "@copilotkit/react-core/v2";
import { JSONUIProvider, Renderer } from "@json-render/react";
import { registry } from "./registry";
import type { JsonRenderSpec } from "./types";

const ALLOWED_TYPES = new Set(["MetricCard", "BarChart", "PieChart"]);

export function JsonRenderAssistantMessage(
  props: CopilotChatAssistantMessageProps,
) {
  const content =
    typeof props.message.content === "string" ? props.message.content : "";
  const spec = useMemo(() => parseSpec(content), [content]);

  // Stream not yet a valid spec (or plain prose) — render the default bubble.
  if (!spec) return <CopilotChatAssistantMessage {...props} />;

  return (
    <div
      data-testid="copilot-assistant-message"
      data-message-role="assistant"
      className="w-full"
    >
      <div data-testid="json-render-root" className="w-full">
        <JSONUIProvider registry={registry}>
          <Renderer
            spec={spec as unknown as Parameters<typeof Renderer>[0]["spec"]}
            registry={registry}
          />
        </JSONUIProvider>
      </div>
    </div>
  );
}

/** Parse a json-render spec out of the assistant content, tolerating code fences and prose. */
function parseSpec(raw: string): JsonRenderSpec | null {
  const jsonText = extractJsonObject(raw);
  if (!jsonText) return null;

  let parsed: unknown;
  try {
    parsed = JSON.parse(jsonText);
  } catch {
    return null;
  }

  if (!isRecord(parsed)) return null;
  const { root, elements } = parsed as { root?: unknown; elements?: unknown };
  if (typeof root !== "string" || !isRecord(elements) || !(root in elements)) {
    return null;
  }

  for (const el of Object.values(elements)) {
    if (!isRecord(el)) return null;
    if (typeof el.type !== "string" || !ALLOWED_TYPES.has(el.type)) return null;
    if (el.props !== undefined && !isRecord(el.props)) return null;
  }

  return parsed as unknown as JsonRenderSpec;
}

/** Strip code fences, then return the first balanced {...} object as a string. */
function extractJsonObject(raw: string): string | null {
  if (!raw?.trim()) return null;
  const fence = /```(?:json)?\s*([\s\S]*?)```/i.exec(raw);
  const candidate = (fence ? fence[1] : raw).trim();
  const start = candidate.indexOf("{");
  if (start === -1) return null;

  let depth = 0;
  let inString = false;
  let escape = false;
  for (let i = start; i < candidate.length; i++) {
    const ch = candidate[i];
    if (escape) {
      escape = false;
      continue;
    }
    if (inString) {
      if (ch === "\\") escape = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') {
      inString = true;
      continue;
    }
    if (ch === "{") depth++;
    else if (ch === "}" && --depth === 0) return candidate.slice(start, i + 1);
  }
  return null;
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

"use client";

export interface MetricCardComponentProps {
  label: string;
  value: string;
  trend?: string | null;
}

export function MetricCard({ label, value, trend }: MetricCardComponentProps) {
  const direction = inferTrendDirection(trend);

  return (
    <div
      data-testid="metric-card"
      className="max-w-xs mx-auto my-3 rounded-lg border border-[var(--border)] bg-[var(--card)] p-5"
    >
      <div className="text-xs font-medium uppercase tracking-wider text-[var(--muted-foreground)]">
        {label}
      </div>
      <div className="mt-1 text-3xl font-semibold tabular-nums text-[var(--foreground)]">
        {value}
      </div>
      {trend ? (
        <div
          className={`mt-2 inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium ${BADGE_CLASS[direction]}`}
        >
          {trend}
        </div>
      ) : null}
    </div>
  );
}

function inferTrendDirection(
  trend: string | null | undefined,
): "up" | "down" | "neutral" {
  const t = trend?.trim();
  if (!t) return "neutral";
  if (t.startsWith("+")) return "up";
  if (t.startsWith("-") || t.startsWith("−")) return "down";
  return "neutral";
}

const BADGE_CLASS = {
  up: "bg-[color-mix(in_oklab,var(--primary)_15%,transparent)] text-[var(--primary)]",
  down: "bg-[color-mix(in_oklab,var(--destructive)_15%,transparent)] text-[var(--destructive)]",
  neutral: "bg-[var(--secondary)] text-[var(--muted-foreground)]",
} as const;

import { defineRegistry } from "@json-render/react";
import { catalog } from "./catalog";
import { MetricCard, type MetricCardComponentProps } from "./metric-card";
import { BarChart, type BarChartComponentProps } from "./charts/bar-chart";
import { PieChart, type PieChartComponentProps } from "./charts/pie-chart";

export const { registry } = defineRegistry(catalog, {
  components: {
    // The agent may nest charts inside a MetricCard root — forward children.
    MetricCard: ({ props, children }) => (
      <div className="flex w-full flex-col items-stretch gap-3">
        <MetricCard {...(props as MetricCardComponentProps)} />
        {children}
      </div>
    ),
    BarChart: ({ props }) => (
      <BarChart {...(props as BarChartComponentProps)} />
    ),
    PieChart: ({ props }) => (
      <PieChart {...(props as PieChartComponentProps)} />
    ),
  },
});

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export const BYOC_JSON_RENDER_SUGGESTIONS = [
  {
    title: "Sales dashboard",
    message: "Show me the sales dashboard with metrics and a revenue chart",
  },
  {
    title: "Revenue by category",
    message: "Break down revenue by category as a pie chart",
  },
  {
    title: "Expense trend",
    message: "Show me monthly expenses as a bar chart",
  },
];

export function useByocJsonRenderSuggestions() {
  useConfigureSuggestions({
    suggestions: BYOC_JSON_RENDER_SUGGESTIONS,
    available: "always",
  });
}

export interface JsonRenderSpec {
  root: string;
  elements: Record<
    string,
    { type: string; props: Record<string, unknown>; children?: string[] }
  >;
}

"use client";

/**
 * Beautiful Chat — the flagship CopilotKit showcase cell, ported verbatim
 * from the 4084 reference clone. The 4084 version lived as its own Next.js
 * frontend at `demos/beautiful-chat/frontend/` with a full `src/components`
 * tree + A2UI catalog. Here the same tree is colocated under the cell and
 * re-wired with relative imports.
 *
 * Providers: layout-level `CopilotKit` + `ThemeProvider` wrappers from the
 * original 4084 root layout are applied here instead, because the unified
 * 4085 shell does not give each cell its own layout.tsx.
 *
 * Runtime: this cell uses its own dedicated runtime endpoint
 * (`/api/copilotkit-beautiful-chat`) so it can enable `openGenerativeUI`,
 * `a2ui` with `injectA2UITool: true`, and `mcpApps` simultaneously — the
 * same combined-runtime shape the canonical starter uses — without bleeding
 * those global flags into other cells sharing the main `/api/copilotkit`
 * endpoint. The backend graph is `beautiful_chat` (src/agents/beautiful_chat.py).
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";

import { ThemeProvider } from "./hooks/use-theme";
import { demonstrationCatalog } from "./declarative-generative-ui/renderers";
import { HomePage } from "./home-page";

export default function BeautifulChatPage() {
  return (
    <ThemeProvider>
      <CopilotKit
        runtimeUrl="/api/copilotkit-beautiful-chat"
        agent="beautiful-chat"
        a2ui={{ catalog: demonstrationCatalog }}
        openGenerativeUI={{}}
        /*
         * `useSingleEndpoint` defaults to true (the single-POST-endpoint
         * protocol). The canonical reference sets it to false to use the
         * v2 multi-endpoint protocol (GET /info + POST /agent/{name}/connect),
         * which requires a Hono-based endpoint via `createCopilotEndpoint`.
         * The 4085 showcase uses `copilotRuntimeNextJSAppRouterEndpoint`
         * (single-endpoint), which matches the other 4085 cells — so we
         * use its default behavior here. Functionally equivalent for this demo.
         */
      >
        <HomePage />
      </CopilotKit>
    </ThemeProvider>
  );
}

/**
 * Beautiful Chat — LangGraph TypeScript agent backing the flagship showcase cell.
 *
 * Ported from langgraph-python/src/agents/beautiful_chat.py. The Python version
 * uses LangChain's create_agent + CopilotKitMiddleware + StateStreamingMiddleware;
 * this port stays closer to the showcase's existing TS pattern (single
 * StateGraph with chat + tool_node, CopilotKit state annotation) so it fits the
 * kitchen-sink layout already established in graph.ts.
 *
 * Local tools:
 *   - query_data           — natural-language query over beautiful-chat-data/db.csv
 *   - manage_todos         — create/update todo list with auto-assigned ids
 *   - get_todos            — read current todos from agent state
 *   - search_flights       — fixed-schema A2UI flight search (2 flights)
 *
 * Dynamic A2UI uses the AG-UI generation tool and its bounded validation/retry
 * loop, with the runtime-provided catalog and usage guide.
 *
 * Data files: ./beautiful-chat-data/db.csv + schemas/flight_schema.json
 */

import { randomUUID } from "node:crypto";
import { promises as fs } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { z } from "zod";
import type { RunnableConfig } from "@langchain/core/runnables";
import { tool } from "@langchain/core/tools";
import type { ToolRunnableConfig } from "@langchain/core/tools";
import { ToolNode } from "@langchain/langgraph/prebuilt";
import type { AIMessage } from "@langchain/core/messages";
import { SystemMessage, ToolMessage } from "@langchain/core/messages";
import {
  Annotation,
  Command,
  getCurrentTaskInput,
  MemorySaver,
  START,
  StateGraph,
} from "@langchain/langgraph";
import { makeChatOpenAI } from "./openai-headers";
import { getA2UITools } from "@ag-ui/langgraph";
import { a2uiContext } from "../../_shared/ts/a2ui/context";
import {
  convertActionsToDynamicStructuredTools,
  copilotkitEmitState,
  CopilotKitStateAnnotation,
} from "@copilotkit/sdk-js/langgraph";

// ---------------------------------------------------------------------------
// 1. Agent state
// ---------------------------------------------------------------------------

const TodoSchema = z.object({
  id: z.string().optional(),
  title: z.string(),
  description: z.string().optional(),
  emoji: z.string().optional(),
  status: z.enum(["pending", "completed"]).optional(),
});

type Todo = z.infer<typeof TodoSchema>;

const BeautifulChatStateAnnotation = Annotation.Root({
  ...CopilotKitStateAnnotation.spec,
  "ag-ui": Annotation<Record<string, unknown>>,
  todos: Annotation<Todo[]>,
});

export type BeautifulChatState = typeof BeautifulChatStateAnnotation.State;

// ---------------------------------------------------------------------------
// 2. Data loading (at module-init time to avoid repeated FS hits)
// ---------------------------------------------------------------------------

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DATA_DIR = path.join(__dirname, "beautiful-chat-data");

let cachedRows: Record<string, string>[] | null = null;
async function loadRows(): Promise<Record<string, string>[]> {
  if (cachedRows) return cachedRows;
  const csvPath = path.join(DATA_DIR, "db.csv");
  const raw = await fs.readFile(csvPath, "utf-8");
  const lines = raw.trim().split(/\r?\n/);
  const header = lines[0].split(",");
  cachedRows = lines.slice(1).map((line) => {
    const cols = line.split(",");
    const obj: Record<string, string> = {};
    header.forEach((h, i) => {
      obj[h] = cols[i] ?? "";
    });
    return obj;
  });
  return cachedRows;
}

let cachedFlightSchema: unknown[] | null = null;
async function loadFlightSchema(): Promise<unknown[]> {
  if (cachedFlightSchema) return cachedFlightSchema;
  const schemaPath = path.join(DATA_DIR, "schemas", "flight_schema.json");
  const raw = await fs.readFile(schemaPath, "utf-8");
  const schema: unknown[] = JSON.parse(raw);
  cachedFlightSchema = schema;
  return schema;
}

// ---------------------------------------------------------------------------
// 3. Tools
// ---------------------------------------------------------------------------

const queryData = tool(
  async ({ query: _query }) => {
    const rows = await loadRows();
    return JSON.stringify(rows);
  },
  {
    name: "query_data",
    description:
      "Query the database, takes natural language. Always call before showing a chart or graph.",
    schema: z.object({
      query: z.string().describe("Natural-language query"),
    }),
  },
);

const manageTodos = tool(
  async ({ todos }, config: ToolRunnableConfig) => {
    const toolCallId = config.toolCall?.id;
    if (typeof toolCallId !== "string" || toolCallId.length === 0) {
      throw new Error(
        "manage_todos: missing tool_call_id — tool was invoked outside a " +
          "ToolNode context.",
      );
    }

    const withIds = todos.map((t) => ({
      ...t,
      id: t.id && t.id.length > 0 ? t.id : randomUUID(),
    }));

    // Emit state to the frontend immediately so the canvas updates.
    // The Command below updates the graph's internal state, but the
    // CopilotKit AG-UI pipeline only picks up state from explicit
    // copilotkit_emit_state events (like Python's StateStreamingMiddleware
    // does). Without this, useAgent().state.todos stays empty.
    await copilotkitEmitState(config, { todos: withIds });

    return new Command({
      update: {
        todos: withIds,
        messages: [
          new ToolMessage({
            content: "Successfully updated todos",
            name: "manage_todos",
            id: randomUUID(),
            tool_call_id: toolCallId,
          }),
        ],
      },
    });
  },
  {
    name: "manage_todos",
    description: "Manage the current todos.",
    schema: z.object({
      todos: z.array(TodoSchema).describe("Array of todo items"),
    }),
  },
);

const getTodos = tool(
  async (_input, config: ToolRunnableConfig) => {
    const state = getCurrentTaskInput<BeautifulChatState>(config);
    return JSON.stringify(state.todos ?? []);
  },
  {
    name: "get_todos",
    description: "Get the current todos.",
    schema: z.object({}),
  },
);

const CATALOG_ID = "copilotkit://app-dashboard-catalog";
const FLIGHT_SURFACE_ID = "flight-search-results";

// All fields optional (matching Python's total=False) so the LLM/aimock
// fixture can omit auxiliary fields without tripping zod validation.
const FlightSchema = z.object({
  airline: z.string().optional(),
  airlineLogo: z.string().optional(),
  flightNumber: z.string().optional(),
  origin: z.string().optional(),
  destination: z.string().optional(),
  date: z.string().optional(),
  departureTime: z.string().optional(),
  arrivalTime: z.string().optional(),
  duration: z.string().optional(),
  status: z.string().optional(),
  price: z.string().optional(),
});

const searchFlights = tool(
  async ({ flights }) => {
    const schema = await loadFlightSchema();
    const ops = [
      {
        version: "v0.9",
        createSurface: {
          surfaceId: FLIGHT_SURFACE_ID,
          catalogId: CATALOG_ID,
        },
      },
      {
        version: "v0.9",
        updateComponents: {
          surfaceId: FLIGHT_SURFACE_ID,
          components: schema,
        },
      },
      {
        version: "v0.9",
        updateDataModel: {
          surfaceId: FLIGHT_SURFACE_ID,
          path: "/",
          value: { flights },
        },
      },
    ];
    return JSON.stringify({ a2ui_operations: ops });
  },
  {
    name: "search_flights",
    description:
      "Search for flights and display the results as rich cards. Return exactly 2 flights.",
    schema: z.object({
      flights: z.array(FlightSchema).describe("Array of flight result objects"),
    }),
  },
);

// Backend tools remain local; toolsForRun adds catalog-bound UI generation.
const tools = [queryData, manageTodos, getTodos, searchFlights];

// Keep generation in the graph so malformed output gets the toolkit's bounded
// validate/retry loop and terminal failure envelope, rather than a synthetic
// "rendered" result for an unvalidated frontend action.
function toolsForRun(state: BeautifulChatState, config: RunnableConfig) {
  const context = a2uiContext(state);
  const actions = Array.isArray(context.properties.actions)
    ? context.properties.actions
    : [];
  const renderName =
    typeof context.properties.inject_a2ui_tool === "string"
      ? context.properties.inject_a2ui_tool
      : "render_a2ui";
  const enabled =
    context.properties.inject_a2ui_tool ??
    actions.some(
      (action) => (action.function?.name ?? action.name) === renderName,
    );
  if (!enabled) return { context, actions, localTools: tools };
  const generator = getA2UITools({
    model: makeChatOpenAI(config, { model: "gpt-5-mini" }),
    defaultCatalogId: context.catalogId ?? CATALOG_ID,
    catalog: context.catalog,
  });
  const generationTool = tool(
    async (input, toolConfig: ToolRunnableConfig) => {
      if (!context.catalog || !context.catalogId) {
        return JSON.stringify({
          code: "a2ui_recovery_exhausted",
          error:
            "The frontend A2UI component schema is missing. Enable catalog schema context before requesting a dashboard.",
          attempts: [],
        });
      }
      const runtimeConfig = { ...toolConfig, state: context.state };
      return generator.invoke(input, runtimeConfig);
    },
    {
      name: generator.name,
      description: generator.description,
      schema: generator.schema,
    },
  );
  return {
    context,
    actions: actions.filter(
      (action) => (action.function?.name ?? action.name) !== renderName,
    ),
    localTools: [...tools, generationTool],
  };
}

// ---------------------------------------------------------------------------
// 4. Chat node
// ---------------------------------------------------------------------------

const SYSTEM_PROMPT = `
You are a polished, professional demo assistant. Keep responses to 1-2 sentences.

Tool guidance:
- Flights: call search_flights to show flight cards with a pre-built schema.
- Dashboards & rich UI: call generate_a2ui to create dashboard UIs with metrics,
  charts, tables, and cards. It handles rendering automatically.
- Charts: call query_data first, then render with the chart component.
- Todos: enable app mode first, then manage todos.
- If UI generation reports exhausted recovery, explain the failure briefly;
  do not claim it rendered or start another generation attempt automatically.
`;

async function chatNode(state: BeautifulChatState, config: RunnableConfig) {
  const model = makeChatOpenAI(config, {
    model: "gpt-5-mini",
    modelKwargs: { parallel_tool_calls: false },
  });

  const { context, actions, localTools } = toolsForRun(state, config);
  const modelWithTools = model.bindTools!([
    ...convertActionsToDynamicStructuredTools(actions),
    ...localTools,
  ]);

  const systemMessage = new SystemMessage({
    content: `${SYSTEM_PROMPT}\n\n${context.prompt}`,
  });

  const response = await modelWithTools.invoke(
    [systemMessage, ...state.messages],
    config,
  );

  return { messages: response };
}

// ---------------------------------------------------------------------------
// 5. Routing
// ---------------------------------------------------------------------------

function shouldContinue(state: BeautifulChatState) {
  const { messages } = state;
  const lastMessage = messages[messages.length - 1] as AIMessage;
  if (lastMessage.tool_calls?.length) {
    const actions = a2uiContext(state).properties.actions;
    const toolCallName = lastMessage.tool_calls![0].name;
    if (
      toolCallName === "generate_a2ui" ||
      !Array.isArray(actions) ||
      actions.every(
        (action) => (action.function?.name ?? action.name) !== toolCallName,
      )
    ) {
      return "tool_node";
    }
  }
  return "__end__";
}

// ---------------------------------------------------------------------------
// 6. Compile
// ---------------------------------------------------------------------------

const workflow = new StateGraph(BeautifulChatStateAnnotation)
  .addNode("chat_node", chatNode)
  .addNode("tool_node", (state, config) =>
    new ToolNode(toolsForRun(state, config).localTools).invoke(state, config),
  )
  .addEdge(START, "chat_node")
  .addEdge("tool_node", "chat_node")
  .addConditionalEdges("chat_node", shouldContinue as any);

const memory = new MemorySaver();

export const graph = workflow.compile({
  checkpointer: memory,
});

// Dedicated runtime for the Beautiful Chat flagship showcase cell.
//
// Beautiful Chat exercises A2UI (dynamic + fixed schema), Open Generative UI,
// and MCP Apps simultaneously — the same combined-runtime shape the canonical
// starter uses. The other langgraph-typescript cells share the default
// /api/copilotkit endpoint, so we split these flags off into their own route
// here to avoid bleeding them globally.
//
// Ported from langgraph-python/src/app/api/copilotkit-beautiful-chat/route.ts.

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { LangGraphAgent } from "@copilotkit/runtime/langgraph";

const LANGGRAPH_URL =
  process.env.LANGGRAPH_DEPLOYMENT_URL || "http://localhost:8123";

const beautifulChatAgent = new LangGraphAgent({
  deploymentUrl: `${LANGGRAPH_URL}/`,
  graphId: "beautiful_chat",
  langsmithApiKey: process.env.LANGSMITH_API_KEY || "",
});

const agents: Record<string, LangGraphAgent> = {
  // The page's <CopilotKit agent="beautiful-chat"> resolves here.
  "beautiful-chat": beautifulChatAgent,
  // Internal components (headless-chat, example-canvas) may call `useAgent()`
  // with no args, which defaults to "default". Alias to the same graph so
  // those component hooks resolve instead of throwing "Agent 'default' not
  // found".
  default: beautifulChatAgent,
};

const runtime = new CopilotRuntime({
  // @ts-ignore -- matches main route.ts pattern
  agents,
  openGenerativeUI: true,
  a2ui: {
    // Inject the dynamic `generate_a2ui` tool into the agent
    injectA2UITool: true,
    // Models follow the tool-usage guide and omit `catalogId`, and the
    // middleware then falls back to the unregistered spec basic catalog
    // ("Catalog not found" render error). Pin the catalog the page registers.
    defaultCatalogId: "copilotkit://app-dashboard-catalog",
  },
  mcpApps: {
    servers: [
      {
        type: "http",
        url: process.env.MCP_SERVER_URL || "https://mcp.excalidraw.com",
        serverId: "beautiful_chat_mcp",
      },
    ],
  },
});

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-beautiful-chat",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

