"use client";

import { CopilotKit } from "@copilotkit/react-core/v2";
import { VoiceChat } from "./voice-chat";

export default function VoiceDemoPage() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-voice"
      agent="voice-demo"
      useSingleEndpoint={false}
      // The dev-only `<cpk-web-inspector>` overlay (auto-enabled on
      // localhost via shouldShowDevConsole) intercepts pointer events
      // on top of the voice sample-audio button, so dev/D5 probe runs
      // can't click it through Playwright. Production isn't localhost
      // so the inspector never mounts there — voice is D5 in prod and
      // D4 locally for this reason alone. Disable explicitly here so
      // the demo behaves the same in both environments.
      enableInspector={false}
    >
      <VoiceChat />
    </CopilotKit>
  );
}

/**
 * LangGraph TypeScript agent — CopilotKit showcase integration
 *
 * Defines a graph with a chat node and all showcase tools,
 * wired to CopilotKit via the sdk-js LangGraph adapter so frontend actions
 * and shared state flow seamlessly.
 */

import { z } from "zod";
import type { RunnableConfig } from "@langchain/core/runnables";
import { tool } from "@langchain/core/tools";
import { ToolNode } from "@langchain/langgraph/prebuilt";
import type { AIMessage } from "@langchain/core/messages";
import { SystemMessage } from "@langchain/core/messages";
import {
  MemorySaver,
  START,
  StateGraph,
  Annotation,
} from "@langchain/langgraph";
import { ChatOpenAI } from "@langchain/openai";
import { getA2UITools } from "@ag-ui/langgraph";
import { makeChatOpenAI } from "./openai-headers";
import {
  convertActionsToDynamicStructuredTools,
  CopilotKitStateAnnotation,
} from "@copilotkit/sdk-js/langgraph";
import {
  getWeatherImpl,
  queryDataImpl,
  manageSalesTodosImpl,
  getSalesTodosImpl,
  scheduleMeetingImpl,
  searchFlightsImpl,
} from "../../shared-tools";

// ---------------------------------------------------------------------------
// 1. Agent state — extends CopilotKit state with a proverbs list
// ---------------------------------------------------------------------------

const AgentStateAnnotation = Annotation.Root({
  ...CopilotKitStateAnnotation.spec,
  proverbs: Annotation<string[]>,
});

export type AgentState = typeof AgentStateAnnotation.State;

// ---------------------------------------------------------------------------
// 2. Tools — shared implementations wrapped for LangChain
// ---------------------------------------------------------------------------

const getWeather = tool(
  async ({ location }) => JSON.stringify(getWeatherImpl(location)),
  {
    name: "get_weather",
    description: "Get current weather for a location",
    schema: z.object({
      location: z.string().describe("City name"),
    }),
  },
);

const queryData = tool(
  async ({ query }) => JSON.stringify(queryDataImpl(query)),
  {
    name: "query_data",
    description: "Query financial database for chart data",
    schema: z.object({
      query: z.string().describe("Natural language query"),
    }),
  },
);

const manageSalesTodos = tool(
  async ({ todos }) => JSON.stringify(manageSalesTodosImpl(todos)),
  {
    name: "manage_sales_todos",
    description: "Create or update the sales todo list",
    schema: z.object({
      todos: z
        .array(
          z.object({
            id: z.string().optional(),
            title: z.string(),
            stage: z.string().optional(),
            value: z.number().optional(),
            dueDate: z.string().optional(),
            assignee: z.string().optional(),
            completed: z.boolean().optional(),
          }),
        )
        .describe("Array of sales todo items"),
    }),
  },
);

const getSalesTodos = tool(
  async ({ currentTodos }) => JSON.stringify(getSalesTodosImpl(currentTodos)),
  {
    name: "get_sales_todos",
    description: "Get the current sales todo list",
    schema: z.object({
      currentTodos: z
        .array(
          z.object({
            id: z.string().optional(),
            title: z.string().optional(),
            stage: z.string().optional(),
            value: z.number().optional(),
            dueDate: z.string().optional(),
            assignee: z.string().optional(),
            completed: z.boolean().optional(),
          }),
        )
        .optional()
        .nullable()
        .describe("Current todos if any"),
    }),
  },
);

const scheduleMeeting = tool(
  async ({ reason, durationMinutes }) =>
    JSON.stringify(scheduleMeetingImpl(reason, durationMinutes)),
  {
    name: "schedule_meeting",
    description: "Schedule a meeting (requires user approval via HITL)",
    schema: z.object({
      reason: z.string().describe("Reason for the meeting"),
      durationMinutes: z.number().optional().describe("Duration in minutes"),
    }),
  },
);

const searchFlights = tool(
  async ({ flights }) => JSON.stringify(searchFlightsImpl(flights)),
  {
    name: "search_flights",
    description: "Search for available flights",
    schema: z.object({
      flights: z
        .array(
          z.object({
            airline: z.string(),
            airlineLogo: z.string().optional(),
            flightNumber: z.string(),
            origin: z.string(),
            destination: z.string(),
            date: z.string(),
            departureTime: z.string(),
            arrivalTime: z.string(),
            duration: z.string(),
            status: z.string(),
            statusColor: z.string().optional(),
            price: z.string(),
            currency: z.string().optional(),
          }),
        )
        .describe("Array of flight results"),
    }),
  },
);

// Dynamic A2UI via the canonical ag-ui factory (same as beautiful_chat /
// a2ui_dynamic). A secondary LLM designs the surface; the factory forces the
// host catalog and emits the a2ui_operations envelope. Replaces the prior
// hand-rolled generate_a2ui tool.
const generateA2ui = getA2UITools({
  model: new ChatOpenAI({ model: "gpt-5-mini" }),
  defaultCatalogId: "copilotkit://app-dashboard-catalog",
});

const tools = [
  getWeather,
  queryData,
  manageSalesTodos,
  getSalesTodos,
  scheduleMeeting,
  searchFlights,
  generateA2ui,
];

// ---------------------------------------------------------------------------
// 3. Chat node — binds backend + frontend tools, invokes the model
// ---------------------------------------------------------------------------

async function chatNode(state: AgentState, config: RunnableConfig) {
  const model = makeChatOpenAI(config, { model: "gpt-5-mini" });

  const modelWithTools = model.bindTools!([
    ...convertActionsToDynamicStructuredTools(state.copilotkit?.actions ?? []),
    ...tools,
  ]);

  const systemMessage = new SystemMessage({
    content: `You are a helpful assistant. The current proverbs are ${JSON.stringify(state.proverbs)}.`,
  });

  const response = await modelWithTools.invoke(
    [systemMessage, ...state.messages],
    config,
  );

  return { messages: response };
}

// ---------------------------------------------------------------------------
// 4. Routing — send tool calls to tool_node unless they're CopilotKit actions
// ---------------------------------------------------------------------------

function shouldContinue({ messages, copilotkit }: AgentState) {
  const lastMessage = messages[messages.length - 1] as AIMessage;

  if (lastMessage.tool_calls?.length) {
    const actions = copilotkit?.actions;
    const toolCallName = lastMessage.tool_calls![0].name;

    if (!actions || actions.every((action) => action.name !== toolCallName)) {
      return "tool_node";
    }
  }

  return "__end__";
}

// ---------------------------------------------------------------------------
// 5. Compile the graph
// ---------------------------------------------------------------------------

const workflow = new StateGraph(AgentStateAnnotation)
  .addNode("chat_node", chatNode)
  .addNode("tool_node", new ToolNode(tools))
  .addEdge(START, "chat_node")
  .addEdge("tool_node", "chat_node")
  .addConditionalEdges("chat_node", shouldContinue as any);

const memory = new MemorySaver();

export const graph = workflow.compile({
  checkpointer: memory,
});

// Dedicated runtime for the /demos/voice cell.
//
// Goals
// -----
// 1. Advertise `audioFileTranscriptionEnabled: true` on `/info` so the chat
//    composer renders the mic button.
// 2. Handle `POST /transcribe` by invoking an OpenAI-backed
//    `TranscriptionServiceOpenAI` (from `@copilotkit/voice`), so recorded
//    audio is transcribed and the transcript auto-sends.
// 3. Return a deterministic 4xx when `OPENAI_API_KEY` is not configured,
//    instead of an opaque 5xx. The V2 runtime's `handleTranscribe` maps
//    error messages containing "api key" or "unauthorized" to
//    `AUTH_FAILED → HTTP 401`, so throwing with that message funnels the
//    missing-key case into the intended 4xx path.
//
// Implementation
// --------------
// Wires the **V2** `CopilotRuntime` directly (from `@copilotkit/runtime/v2`)
// because the V1 wrapper in `@copilotkit/runtime` drops the
// `transcriptionService` option on the floor (see the TODO on the V1
// constructor). V2 URL-routes on `/info`, `/agent/:id/run`, `/transcribe`,
// etc., so the route file lives at `[[...slug]]/route.ts` to catch all
// sub-paths under `/api/copilotkit-voice`.

import type { NextRequest } from "next/server";
import {
  CopilotRuntime,
  TranscriptionService,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { TranscribeFileOptions } from "@copilotkit/runtime/v2";
import { LangGraphAgent } from "@copilotkit/runtime/langgraph";
import { TranscriptionServiceOpenAI } from "@copilotkit/voice";
import OpenAI from "openai";

const LANGGRAPH_URL =
  process.env.AGENT_URL ||
  process.env.LANGGRAPH_DEPLOYMENT_URL ||
  "http://localhost:8123";

const voiceDemoAgent = new LangGraphAgent({
  deploymentUrl: `${LANGGRAPH_URL}/`,
  graphId: "starterAgent",
});

/**
 * Transcription service wrapper that reports a clean, typed auth error when
 * OPENAI_API_KEY is not configured. When the key is present we delegate to
 * the real OpenAI-backed service; any upstream Whisper error keeps its
 * natural categorization.
 */
class GuardedOpenAITranscriptionService extends TranscriptionService {
  private delegate: TranscriptionServiceOpenAI | null;

  constructor() {
    super();
    const apiKey = process.env.OPENAI_API_KEY;
    this.delegate = apiKey
      ? new TranscriptionServiceOpenAI({ openai: new OpenAI({ apiKey }) })
      : null;
  }

  async transcribeFile(options: TranscribeFileOptions): Promise<string> {
    if (!this.delegate) {
      // "api key" substring → handleTranscribe maps to AUTH_FAILED → 401.
      throw new Error(
        "OPENAI_API_KEY not configured for this deployment (api key missing). " +
          "Set OPENAI_API_KEY to enable voice transcription.",
      );
    }
    return this.delegate.transcribeFile(options);
  }
}

// Cache the runtime + handler across invocations so the transcription service
// is constructed once per Node process instead of per request. The guarded
// service reads OPENAI_API_KEY lazily in its transcribeFile call path, so
// deferring construction past module load is not required for cold-start
// safety under missing-key conditions.
let cachedHandler: ((req: Request) => Promise<Response>) | null = null;
function getHandler(): (req: Request) => Promise<Response> {
  if (cachedHandler) return cachedHandler;

  const runtime = new CopilotRuntime({
    // @ts-ignore -- Published CopilotRuntime agents type wraps Record in
    // MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in
    // source, pending release.
    agents: {
      // The page mounts <CopilotKit agent="voice-demo">; resolve that to
      // the neutral sample_agent graph.
      "voice-demo": voiceDemoAgent,
      // useAgent() with no args defaults to "default"; alias so any internal
      // default-agent lookups resolve against the same graph.
      default: voiceDemoAgent,
    },
    transcriptionService: new GuardedOpenAITranscriptionService(),
  });

  cachedHandler = createCopilotRuntimeHandler({
    runtime,
    basePath: "/api/copilotkit-voice",
  });
  return cachedHandler;
}

// Next.js App Router bindings. This file lives at
// `src/app/api/copilotkit-voice/[[...slug]]/route.ts` — the catchall slug
// pattern forwards every sub-path (`/info`, `/agent/:id/run`,
// `/transcribe`, ...) to the V2 handler so its URL router can dispatch.
export const POST = (req: NextRequest) => getHandler()(req);
export const GET = (req: NextRequest) => getHandler()(req);
export const PUT = (req: NextRequest) => getHandler()(req);
export const DELETE = (req: NextRequest) => getHandler()(req);

"use client";

/**
 * Sample-audio button for the voice demo.
 *
 * Pure test/demo affordance: clicking the button synchronously injects a
 * canned phrase into the chat composer via `onTranscribed(sampleText)`.
 * No microphone permission, no audio fetch, no `/transcribe` round trip
 * — those concerns belong to the mic button rendered by `<CopilotChat />`.
 * Keeping this affordance deterministic means the d5-voice probe and the
 * Playwright e2e never depend on the runtime's transcription endpoint
 * being healthy or on any specific aimock fixture surviving across
 * environments.
 */
export interface SampleAudioButtonProps {
  /** Called with the canned sample text when the button is clicked. */
  onTranscribed: (text: string) => void;
  /**
   * Phrase injected into the composer when the button is clicked. Used as
   * the tooltip so users can preview what the sample says without taking
   * up visual space on the page.
   */
  sampleText: string;
}

export function SampleAudioButton({
  onTranscribed,
  sampleText,
}: SampleAudioButtonProps) {
  return (
    <button
      type="button"
      data-testid="voice-sample-audio-button"
      onClick={() => onTranscribed(sampleText)}
      title={`Inserts: "${sampleText}"`}
      className="inline-flex w-fit items-center gap-2 rounded-md border border-black/10 bg-white px-3 py-1.5 text-xs font-medium hover:bg-black/5 dark:border-white/10 dark:bg-black/30 dark:hover:bg-white/10"
    >
      <span aria-hidden>🎙</span>
      <span>Try a sample audio</span>
    </button>
  );
}

"use client";

import { useCallback } from "react";
import { CopilotChat } from "@copilotkit/react-core/v2";
import { SampleAudioButton } from "./sample-audio-button";

const AGENT_ID = "voice-demo";
const SAMPLE_TEXT = "What is the weather in Tokyo?";

// Voice demo.
//
// Two affordances live on this page:
//
// 1. The default mic button rendered by <CopilotChat /> when the runtime at
//    RUNTIME_URL advertises `audioFileTranscriptionEnabled: true`. Click it,
//    speak, click again — text is transcribed into the composer.
//
// 2. The <SampleAudioButton /> below the chat, which synchronously injects a
//    canned phrase into the chat's textarea (bypassing mic permissions and
//    the runtime's transcription endpoint so Playwright and screenshot flows
//    work too). The mic path is the only affordance that exercises real
//    transcription; the sample button is a deterministic test/demo
//    affordance.
//
// Injecting text into the composer goes through the DOM: CopilotChat owns its
// input state internally (no external controlled-input API on v2 today), but
// the textarea is tagged `data-testid="copilot-chat-textarea"`. Setting its
// value via the native HTMLTextareaElement value setter and dispatching a
// synthetic `input` event is the React-compatible way to flip the managed
// state without reaching into CopilotChat's internals.
export function VoiceChat() {
  const handleTranscribed = useCallback((text: string) => {
    if (typeof document === "undefined") return;
    const textarea = document.querySelector<HTMLTextAreaElement>(
      '[data-testid="copilot-chat-textarea"]',
    );
    if (!textarea) {
      console.warn(
        "[voice-demo] could not find copilot-chat-textarea to populate",
      );
      return;
    }
    // React tracks its own "last known value" on controlled inputs. Calling
    // the native setter is what makes React observe the change on the next
    // input event.
    const nativeSetter = Object.getOwnPropertyDescriptor(
      window.HTMLTextAreaElement.prototype,
      "value",
    )?.set;
    if (nativeSetter) {
      nativeSetter.call(textarea, text);
    } else {
      textarea.value = text;
    }
    textarea.dispatchEvent(new Event("input", { bubbles: true }));
    textarea.focus();
  }, []);

  return (
    <div className="flex h-screen flex-col gap-3 p-6">
      <div className="flex items-center justify-between gap-3">
        <h1 className="text-lg font-semibold">Voice input</h1>
        <SampleAudioButton
          onTranscribed={handleTranscribed}
          sampleText={SAMPLE_TEXT}
        />
      </div>
      <div className="min-h-0 flex-1 overflow-hidden rounded-md border border-black/10 dark:border-white/10">
        <CopilotChat agentId={AGENT_ID} className="h-full" />
      </div>
    </div>
  );
}

