export function Composer({
  value,
  onChange,
  onSend,
  disabled,
  isRunning,
  attachments,
  onRemoveAttachment,
  onFileChange,
  fileInputRef,
  containerRef,
  onDragOver,
  onDragLeave,
  onDrop,
  dragOver,
}: ComposerProps) {
  const ref = useRef<HTMLTextAreaElement | null>(null);

  useEffect(() => {
    const el = ref.current;
