files.content:
"""Multimodal demo backend (Langroid).

Vision-capable agent (gpt-4o) for the ``/demos/multimodal`` cell. Accepts
image and PDF attachments injected via CopilotChat's AttachmentsConfig
pipeline. Mirrors the langgraph-python sibling
(``showcase/integrations/langgraph-python/src/agents/multimodal_agent.py``)
so the two demos exercise comparable behavior.

Wire format
===========
Attachments arrive in user-message content as either:

1. ``{"type": "image", "source": {"type": "data", "value": "<b64>",
   "mimeType": "image/png"}}`` — modern AG-UI shape that CopilotChat
   emits natively.
2. ``{"type": "binary", "mimeType": "application/pdf", "data": "<b64>"}``
   — legacy AG-UI binary part the langgraph-python integration's
   ``onRunInitialized`` shim normalizes to. Kept for interop in case a
   future runtime path forwards through that converter.

Image parts are forwarded to OpenAI as ``image_url`` content parts with
inline ``data:<mime>;base64,...`` URLs; gpt-4o reads them natively. PDF
parts are flattened to text with ``pypdf`` (gpt-4o cannot read PDFs
directly), with a typed placeholder when extraction fails so the model
can at least tell the user the document was unreadable.

Wired up by ``agent_server.py`` at ``POST /multimodal``.
"""

from __future__ import annotations

import asyncio
import base64
import io
import json
import logging
import os
import uuid
from typing import Any, AsyncGenerator

import httpx
import openai
import pydantic
from ag_ui.core import (
    EventType,
    RunAgentInput,
    RunErrorEvent,
    RunFinishedEvent,
    RunStartedEvent,
    TextMessageContentEvent,
    TextMessageEndEvent,
    TextMessageStartEvent,
)
from fastapi import Request
from fastapi.responses import JSONResponse, StreamingResponse

logger = logging.getLogger(__name__)


_SYSTEM_PROMPT = (
    "You are a helpful assistant. The user may attach images or documents "
    "(PDFs). When they do, analyze the attachment carefully and answer the "
    "user's question. If no attachment is present, answer the text question "
    "normally. Keep responses concise (1-3 sentences) unless asked to go deep."
)


# ---------------------------------------------------------------------------
# PDF flattening
# ---------------------------------------------------------------------------


def _extract_pdf_text(b64: str) -> str:
    """Decode an inline-base64 PDF and extract its text.

    Returns an empty string when decoding or extraction fails. Caller
    decides whether to inline the text or substitute a placeholder.
    """
    try:
        raw = base64.b64decode(b64, validate=False)
    except (ValueError, TypeError) as exc:
        logger.warning("multimodal: base64 decode failed: %s", exc)
        return ""
    try:
        # Lazy import — keeps the module importable even if pypdf is
        # missing at dev-server boot.
        from pypdf import PdfReader  # type: ignore[import-not-found]
    except ImportError as exc:
        logger.warning(
            "multimodal: pypdf not installed — PDF text unavailable: %s", exc
        )
        return ""
    try:
        reader = PdfReader(io.BytesIO(raw))
        pages = [page.extract_text() or "" for page in reader.pages]
        return "\n\n".join(pages).strip()
    except Exception as exc:  # noqa: BLE001 — pypdf failure shouldn't 500 the run
        logger.warning("multimodal: pypdf extraction failed: %s", exc)
        return ""


# ---------------------------------------------------------------------------
# Content-part normalization
# ---------------------------------------------------------------------------


def _normalize_part(part: Any) -> dict[str, Any] | None:
    """Map an inbound content part to an OpenAI content part.

    Returns ``None`` when the part is not understood (caller can drop or
    fall back to text). Recognises:

    - ``{"type": "text", "text": "..."}`` — passthrough.
    - ``{"type": "image", "source": {"type": "data", "value": "<b64>", "mimeType": "..."}}``
    - ``{"type": "document", "source": {"type": "data", "value": "<b64>", "mimeType": "..."}}``
    - ``{"type": "binary", "mimeType": "...", "data": "<b64>"}`` (legacy)
    - ``{"type": "image_url", "image_url": {"url": "data:..."}}`` (already OpenAI shape)
    - bare strings (treated as text).
    - Pydantic model instances (e.g. ``TextInputContent``, ``ImageInputContent``,
      ``DocumentInputContent`` from ``ag_ui.core``) — converted to dicts via
      ``model_dump()`` so the rest of the function can use ``.get()``.
    """
    if isinstance(part, str):
        if not part:
            return None
        return {"type": "text", "text": part}
    # Pydantic model instances (from ag_ui.core deserialization) are not
    # dicts but expose model_dump(). Convert once so the rest of the
    # function can use dict-style .get() access uniformly.
    if not isinstance(part, dict):
        if hasattr(part, "model_dump"):
            part = part.model_dump(by_alias=True)
        else:
            return None
    ptype = part.get("type")

    if ptype == "text":
        text = part.get("text")
        if isinstance(text, str) and text:
            return {"type": "text", "text": text}
        return None

    if ptype == "image_url":
        # Already OpenAI shape — pass through after light validation.
        image_url = part.get("image_url")
        if isinstance(image_url, str) and image_url:
            return {"type": "image_url", "image_url": {"url": image_url}}
        if isinstance(image_url, dict):
            url = image_url.get("url")
            if isinstance(url, str) and url:
                return {"type": "image_url", "image_url": {"url": url}}
        return None

    if ptype in ("image", "document"):
        source = part.get("source")
        if not isinstance(source, dict):
            return None
        if source.get("type") != "data":
            # url-based parts not supported by this agent path today —
            # the demo only emits inline base64.
            return None
        value = source.get("value")
        mime = source.get("mimeType")
        if not isinstance(value, str) or not isinstance(mime, str):
            return None
        if ptype == "image" or mime.startswith("image/"):
            return {
                "type": "image_url",
                "image_url": {"url": f"data:{mime};base64,{value}"},
            }
        if "pdf" in mime.lower():
            text = _extract_pdf_text(value)
            if not text:
                return {
                    "type": "text",
                    "text": "[Attached document: PDF could not be read.]",
                }
            return {"type": "text", "text": f"[Attached document]\n{text}"}
        return None

    if ptype == "binary":
        mime = part.get("mimeType") or ""
        data = part.get("data")
        if not isinstance(mime, str) or not isinstance(data, str):
            return None
        if mime.startswith("image/"):
            return {
                "type": "image_url",
                "image_url": {"url": f"data:{mime};base64,{data}"},
            }
        if "pdf" in mime.lower():
            text = _extract_pdf_text(data)
            if not text:
                return {
                    "type": "text",
                    "text": "[Attached document: PDF could not be read.]",
                }
            return {"type": "text", "text": f"[Attached document]\n{text}"}
        return None

    return None


def _build_user_content(content: Any) -> Any:
    """Translate user-message content into an OpenAI-compatible payload.

    Returns either a raw string (when there's only one text part — a
    common single-message case) or the list-of-parts shape that gpt-4o
    expects for multimodal turns.
    """
    if isinstance(content, str):
        return content
    if not isinstance(content, list):
        return ""
    parts: list[dict[str, Any]] = []
    for raw in content:
        normalized = _normalize_part(raw)
        if normalized is not None:
            parts.append(normalized)
    if not parts:
        return ""
    if len(parts) == 1 and parts[0].get("type") == "text":
        return parts[0].get("text") or ""
    return parts


def _build_messages(messages: Any, system_prompt: str) -> list[dict[str, Any]]:
    """Build the OpenAI messages list, preserving multimodal user parts."""
    out: list[dict[str, Any]] = [{"role": "system", "content": system_prompt}]
    if not messages:
        return out
    for msg in messages:
        role = (
            getattr(msg, "role", None) if not isinstance(msg, dict) else msg.get("role")
        )
        if not isinstance(role, str):
            continue
        content = (
            getattr(msg, "content", None)
            if not isinstance(msg, dict)
            else msg.get("content")
        )
        if role == "user":
            built = _build_user_content(content)
            if built:
                out.append({"role": "user", "content": built})
        elif role == "assistant":
            if isinstance(content, str) and content:
                out.append({"role": "assistant", "content": content})
        elif role == "system":
            if isinstance(content, str) and content:
                out.append({"role": "system", "content": content})
    return out


# ---------------------------------------------------------------------------
# SSE handler
# ---------------------------------------------------------------------------


def _sse_line(event: Any) -> str:
    if hasattr(event, "model_dump"):
        data = event.model_dump(by_alias=True, exclude_none=True)
    else:
        data = dict(event)
    return f"data: {json.dumps(data)}\n\n"


async def handle_run(request: Request) -> StreamingResponse:
    """AG-UI ``/multimodal`` SSE handler — vision-capable streaming."""
    error_id = str(uuid.uuid4())
    try:
        body = await request.json()
    except (json.JSONDecodeError, ValueError) as exc:
        logger.exception("multimodal: failed to parse body (error_id=%s)", error_id)
        return JSONResponse(
            {
                "error": "Invalid JSON body",
                "errorId": error_id,
                "class": exc.__class__.__name__,
            },
            status_code=400,
        )
    try:
        run_input = RunAgentInput(**body)
    except (pydantic.ValidationError, TypeError, ValueError) as exc:
        logger.exception("multimodal: invalid RunAgentInput (error_id=%s)", error_id)
        return JSONResponse(
            {
                "error": "Invalid RunAgentInput payload",
                "errorId": error_id,
                "class": exc.__class__.__name__,
            },
            status_code=422,
        )

    oai_messages = _build_messages(run_input.messages, _SYSTEM_PROMPT)
    # Force a vision-capable model. We deliberately ignore LANGROID_MODEL
    # here — the unified text-only agents are configured with cheaper
    # models, and this demo's whole point is the vision path.
    model = os.getenv("MULTIMODAL_MODEL", "gpt-4o")
    thread_id = run_input.thread_id or str(uuid.uuid4())

    async def event_stream() -> AsyncGenerator[str, None]:
        run_id = str(uuid.uuid4())
        message_id = str(uuid.uuid4())

        yield _sse_line(
            RunStartedEvent(
                type=EventType.RUN_STARTED,
                thread_id=thread_id,
                run_id=run_id,
            )
        )
        yield _sse_line(
            TextMessageStartEvent(
                type=EventType.TEXT_MESSAGE_START, message_id=message_id
            )
        )

        try:
            client = openai.AsyncOpenAI()
            stream = await client.chat.completions.create(
                model=model,
                messages=oai_messages,
                stream=True,
            )
            async for chunk in stream:
                if not chunk.choices:
                    continue
                delta = chunk.choices[0].delta
                text = getattr(delta, "content", None)
                if text:
                    yield _sse_line(
                        TextMessageContentEvent(
                            type=EventType.TEXT_MESSAGE_CONTENT,
                            message_id=message_id,
                            delta=text,
                        )
                    )
        except (openai.APIError, httpx.HTTPError, asyncio.TimeoutError) as exc:
            logger.exception("multimodal: OpenAI streaming call failed")
            yield _sse_line(
                TextMessageEndEvent(
                    type=EventType.TEXT_MESSAGE_END, message_id=message_id
                )
            )
            yield _sse_line(
                RunErrorEvent(
                    type=EventType.RUN_ERROR,
                    message=f"Agent run failed: {exc.__class__.__name__}",
                )
            )
            yield _sse_line(
                RunFinishedEvent(
                    type=EventType.RUN_FINISHED,
                    thread_id=thread_id,
                    run_id=run_id,
                )
            )
            return

        yield _sse_line(
            TextMessageEndEvent(type=EventType.TEXT_MESSAGE_END, message_id=message_id)
        )
        yield _sse_line(
            RunFinishedEvent(
                type=EventType.RUN_FINISHED,
                thread_id=thread_id,
                run_id=run_id,
            )
        )

    return StreamingResponse(
        event_stream(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )

// Dedicated runtime for the Multimodal Attachments demo (Langroid).
//
// Why its own route? The backing agent (`multimodal_agent.py`) runs a
// vision-capable model (gpt-4o). Every other cell in the showcase uses a
// text-only, cheaper model. Registering this agent under the shared
// `/api/copilotkit` runtime would silently upgrade *all* cells that share
// that runtime to a vision model whenever the browser routed to this one
// — wasting tokens and blurring the per-demo cost boundary.
//
// The page at `src/app/demos/multimodal/page.tsx` points its `runtimeUrl`
// here and sets `agent="multimodal-demo"`.

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { HttpAgent } from "@ag-ui/client";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

const multimodalAgent = new HttpAgent({ url: `${AGENT_URL}/multimodal` });

const agents = {
  // The page mounts <CopilotKit agent="multimodal-demo">.
  "multimodal-demo": multimodalAgent,
  // useAgent() with no args defaults to "default"; alias for safety.
  default: multimodalAgent,
};

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- see main route.ts
        agents,
      }),
      basePath: "/api/copilotkit-multimodal",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

import type { AttachmentUploadResult } from "@copilotkit/shared";

/**
 * `onUpload` must resolve to an `AttachmentUploadResult` (data or url). We
 * always return the `data` variant — the demo inlines base64 instead of
 * uploading to external storage, matching the Wave 2b spec.
 */
type DataUploadResult = Extract<AttachmentUploadResult, { type: "data" }>;

/**
 * Convert a File into the `AttachmentsConfig.onUpload` result shape —
 * inline base64 with the browser-provided mime type. We do this in the
 * browser rather than uploading to external storage because Wave 2b is a
 * self-contained demo; `maxSize: 10 MB` (set below) caps bloat.
 *
 * `FileReader` produces a `data:<mime>;base64,<payload>` URL; we strip the
 * prefix so the runtime forwards the raw base64 value (what the agent
 * expects in `source.value`).
 */
export function fileToDataAttachment(file: File): Promise<DataUploadResult> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () =>
      reject(reader.error ?? new Error(`FileReader failed for ${file.name}`));
    reader.onload = () => {
      const result = reader.result;
      if (typeof result !== "string") {
        reject(new Error(`Unexpected FileReader result type for ${file.name}`));
        return;
      }
      // result looks like "data:image/png;base64,iVBORw0K..." — strip the prefix.
      const commaIdx = result.indexOf(",");
      const base64 = commaIdx >= 0 ? result.slice(commaIdx + 1) : result;
      resolve({
        type: "data",
        value: base64,
        mimeType: file.type || "application/octet-stream",
        metadata: {
          filename: file.name,
          size: file.size,
        },
      });
    };
    reader.readAsDataURL(file);
  });
}

"use client";

/**
 * Legacy-shape rewrite + media-dedupe shim.
 *
 * Three problems this fixes:
 *
 * 1. **Outgoing modern parts are invisible to the agent.** The published
 *    `@ag-ui/langgraph` converter (0.0.x) only understands the legacy
 *    `{ type: "binary", mimeType, data | url }` shape when forwarding
 *    AG-UI messages to LangChain. Modern
 *    `{ type: "image" | "document", source: { type, value, mimeType } }`
 *    parts are silently dropped. In `onRunInitialized` we walk the
 *    outgoing user message and APPEND a legacy `binary` mirror after
 *    every modern media part — we cannot REPLACE the modern part with
 *    `binary` because `CopilotChatUserMessage`'s `getMediaParts` only
 *    renders `image|audio|video|document`, so replacing would make the
 *    attachment visually disappear from the chat once the run snapshot
 *    round-trips through state. APPEND keeps both forms: the modern
 *    part stays for the UI, the legacy `binary` feeds the converter.
 *
 * 2. **Round-tripped media comes back doubled and mistyped.** The
 *    converter sends our `binary` parts out as LangChain `image_url`
 *    and pulls incoming `image_url` parts back in as AG-UI `image`
 *    regardless of mimeType, so PDFs come back as `type: "image"` with
 *    `mimeType: "application/pdf"` and fall to `ImageAttachment` (which
 *    renders a broken `<img>`). The user's original modern part also
 *    survives in state, so the chat shows TWO chips per attachment. On
 *    every `onMessagesSnapshotEvent` and `onRunFinalized` we dedupe by
 *    `source.value` and re-key the `type` field from the mimeType so
 *    PDFs route to `DocumentAttachment` (icon + filename) and images
 *    to `ImageAttachment`.
 */

import { useEffect, useMemo } from "react";
import { useAgent } from "@copilotkit/react-core/v2";

/**
 * Minimal structural shape of an AG-UI message. `@ag-ui/client`'s
 * exported `Message` is a tagged union by role, but for the rewrite
 * we only care about the `user` branch and treat every other role as
 * pass-through. Keeping the type local avoids pulling `@ag-ui/client`
 * into this package's direct dependencies.
 */
type AgentMessage = {
  id?: string;
  role: string;
  content?: unknown;
};

/**
 * Builds the legacy `binary` content part that mirrors a modern
 * `image | document | audio | video` part. Returns `null` if the input
 * is not a multimodal part we need to mirror, or if the part is already
 * a legacy `binary` (idempotent).
 *
 * The published `@ag-ui/langgraph` converter (see `aguiMessagesToLangChain`)
 * only recognizes legacy `binary` parts; modern parts are silently
 * filtered out. We APPEND the legacy mirror alongside the modern part
 * rather than replacing it, because `CopilotChatUserMessage`'s
 * `getMediaParts` only renders `image|audio|video|document` — replacing
 * the modern part with `binary` makes the attachment visually disappear
 * from the chat once the agent run completes (the run-state snapshot
 * round-trips through state and re-renders the user message). Keeping
 * both forms gives the UI something to render AND the converter
 * something to read.
 */
function legacyBinaryFor(part: unknown): unknown | null {
  if (!part || typeof part !== "object") return null;
  const candidate = part as {
    type?: string;
    source?: {
      type?: string;
      value?: string;
      mimeType?: string;
    };
  };
  const type = candidate.type;
  if (
    type !== "image" &&
    type !== "document" &&
    type !== "audio" &&
    type !== "video"
  ) {
    return null;
  }
  const source = candidate.source;
  if (!source || typeof source.value !== "string") {
    return null;
  }
  const mimeType = source.mimeType ?? "application/octet-stream";
  if (source.type === "data") {
    return { type: "binary", mimeType, data: source.value };
  }
  if (source.type === "url") {
    return { type: "binary", mimeType, url: source.value };
  }
  return null;
}

/**
 * Walks a message list and APPENDS a legacy `binary` mirror after every
 * modern `image|document|audio|video` part on user messages, so the
 * outgoing payload contains both forms. Non-user messages, plain-string
 * user messages, and parts that already have a sibling `binary` mirror
 * pass through untouched (idempotent: re-running on already-augmented
 * messages is a no-op).
 *
 * Returns null if nothing changed so the subscriber in
 * `onRunInitialized` can skip a superfluous state write.
 */
function rewriteMessagesForLegacyConverter(
  messages: ReadonlyArray<Readonly<AgentMessage>>,
): AgentMessage[] | null {
  let mutated = false;
  const next = messages.map((message) => {
    if (message.role !== "user") return message as AgentMessage;
    const content = message.content;
    if (!Array.isArray(content)) return message as AgentMessage;

    // Build a key set of `binary` parts already in the message so we
    // don't double-append on a second run.
    const existingBinaryKeys = new Set<string>();
    for (const part of content) {
      if (
        part &&
        typeof part === "object" &&
        (part as { type?: string }).type === "binary"
      ) {
        const p = part as { mimeType?: string; data?: string; url?: string };
        existingBinaryKeys.add(`${p.mimeType ?? ""}::${p.data ?? p.url ?? ""}`);
      }
    }

    let partMutated = false;
    const augmentedParts: unknown[] = [];
    for (const part of content) {
      augmentedParts.push(part);
      const mirror = legacyBinaryFor(part);
      if (!mirror) continue;
      const m = mirror as {
        mimeType?: string;
        data?: string;
        url?: string;
      };
      const key = `${m.mimeType ?? ""}::${m.data ?? m.url ?? ""}`;
      if (existingBinaryKeys.has(key)) continue;
      existingBinaryKeys.add(key);
      augmentedParts.push(mirror);
      partMutated = true;
    }
    if (!partMutated) return message as AgentMessage;
    mutated = true;
    return {
      ...(message as object),
      content: augmentedParts,
    } as AgentMessage;
  });
  return mutated ? next : null;
}

/**
 * Normalize + dedupe media content parts within each user message:
 *
 * 1. **Type normalization.** The @ag-ui/langgraph round-trip through
 *    LangChain emits incoming media parts as `type: "image"` regardless
 *    of the actual mimeType — including `application/pdf` and other
 *    non-image documents — because the converter generates them from
 *    LangChain `image_url` parts indiscriminately. The chat
 *    user-message renderer dispatches by `type` to either
 *    `ImageAttachment` (renders an `<img>`) or `DocumentAttachment`
 *    (renders an icon + filename). A PDF tagged as `image` falls to
 *    `<img>`, fails to load, and shows "Failed to load image" instead
 *    of a PDF chip. Re-key the part type from the mimeType so the
 *    correct renderer fires.
 *
 * 2. **Dedupe by source value.** The same attachment ends up in the
 *    user message twice: once as the modern part the client added,
 *    once as the re-converted shape the snapshot pushes. Strip
 *    duplicates by `source.value` (or `source.url`) regardless of
 *    type so both forms collapse to a single chip.
 */
function normalizePartType(type: string, mimeType: string | undefined): string {
  if (type !== "image" && type !== "document") return type;
  if (!mimeType) return type;
  if (mimeType.startsWith("image/")) return "image";
  if (mimeType.startsWith("audio/")) return "audio";
  if (mimeType.startsWith("video/")) return "video";
  return "document";
}

function dedupeUserMessageMedia(
  messages: ReadonlyArray<Readonly<AgentMessage>>,
): AgentMessage[] | null {
  let mutated = false;
  const next = messages.map((message) => {
    if (message.role !== "user") return message as AgentMessage;
    const content = message.content;
    if (!Array.isArray(content)) return message as AgentMessage;
    const seen = new Set<string>();
    const kept: unknown[] = [];
    let partMutated = false;
    for (const part of content) {
      if (!part || typeof part !== "object") {
        kept.push(part);
        continue;
      }
      const p = part as {
        type?: string;
        source?: { value?: string; url?: string; mimeType?: string };
        data?: string;
        url?: string;
        mimeType?: string;
      };
      const isMedia =
        p.type === "image" ||
        p.type === "document" ||
        p.type === "audio" ||
        p.type === "video";
      if (!isMedia) {
        kept.push(part);
        continue;
      }
      const sourceValue = p.source?.value ?? p.source?.url ?? "";
      if (seen.has(sourceValue)) {
        partMutated = true;
        continue;
      }
      seen.add(sourceValue);
      const normalizedType = normalizePartType(
        p.type ?? "",
        p.source?.mimeType ?? p.mimeType,
      );
      if (normalizedType !== p.type) {
        kept.push({ ...p, type: normalizedType });
        partMutated = true;
      } else {
        kept.push(part);
      }
    }
    if (!partMutated) return message as AgentMessage;
    mutated = true;
    return { ...(message as object), content: kept } as AgentMessage;
  });
  return mutated ? next : null;
}

/**
 * Installs the subscribers on the active agent. Scoped to a small inner
 * component so it can use the `useAgent` hook the <CopilotChat> parent
 * already relies on — subscribing there means we rewrite messages on the
 * *same* agent instance CopilotChat dispatches through, even when threads
 * are cloned or swapped.
 */
export function LegacyConverterShim() {
  const { agent } = useAgent({ agentId: "multimodal-demo" });

  const subscriber = useMemo(
    () => ({
      onRunInitialized: ({
        messages,
      }: {
        messages: ReadonlyArray<Readonly<AgentMessage>>;
      }) => {
        const rewritten = rewriteMessagesForLegacyConverter(messages);
        if (!rewritten) return;
        return { messages: rewritten };
      },
      // After every messages snapshot from the server, strip duplicate
      // media parts and normalize types that the @ag-ui/langgraph
      // round-trip mangled. We hook both `onMessagesSnapshotEvent` and
      // `onRunFinalized` to catch incremental events too — the
      // snapshot fires once at run end, the run-finalized hook fires
      // when the agent transitions out of running.
      onMessagesSnapshotEvent: ({
        messages,
      }: {
        messages: ReadonlyArray<Readonly<AgentMessage>>;
      }) => {
        const deduped = dedupeUserMessageMedia(messages);
        if (!deduped) return;
        return { messages: deduped };
      },
      onRunFinalized: ({
        messages,
      }: {
        messages: ReadonlyArray<Readonly<AgentMessage>>;
      }) => {
        const deduped = dedupeUserMessageMedia(messages);
        if (!deduped) return;
        return { messages: deduped };
      },
    }),
    [],
  );

  useEffect(() => {
    if (!agent) return;
    // AG-UI's AgentSubscriber type is tagged by role; our shim uses a
    // structural message shape and returns only partial mutations, so
    // cast at the subscribe boundary. The cast is safe: our handlers
    // only ever return a messages-mutation or void.
    const handle = agent.subscribe(
      subscriber as unknown as Parameters<typeof agent.subscribe>[0],
    );
    return () => handle.unsubscribe();
  }, [agent, subscriber]);

  return null;
}

