          />
        </div>
      </div>
    </>
  );
}

"use client";

/**
 * Two buttons that auto-attach a bundled sample file (image or PDF) and
 * immediately submit a canned prompt about it.
 *
 * Implementation note: an earlier version of this component drove the
 * chat's hidden `<input type="file">` via DataTransfer + a synthetic
 * `change` event so the sample path went through the same `onUpload` /
 * `useAttachments` pipeline as the paperclip button. That worked for
 * "queue the attachment" but auto-sending the canned prompt afterwards
 * required clicking the send button while the attachment was still in
 * `status: "uploading"`, which `CopilotChat.onSubmitInput` rejects with
 * `"Cannot send while attachments are uploading"` and clears the input
 * regardless. Detecting the upload-complete state from outside the chat
 * meant scraping the spinner overlay, racy on slow renders.
 *
 * This version skips the DOM entirely and goes through the V2 agent
 * surface directly: `agent.addMessage(...)` to enqueue a fully-formed
 * user message (text + attachment content parts), then
 * `copilotkit.runAgent({ agent })` to dispatch it. Matches what
 * `CopilotChat.onSubmitInput` does internally — same shapes, same
 * runtime — but with no upload race because we build the
 * already-base64'd content part ourselves before calling addMessage.
 *
 * The `LegacyConverterShim` in page.tsx still rewrites our modern
 * `image|document` parts to the legacy `binary` shape the published
 * `@ag-ui/langgraph` converter understands, so the agent ultimately
 * receives the attachment in the form `multimodal_agent.py` expects.
 */

import { useCallback, useState } from "react";
import { useAgent, useCopilotKit } from "@copilotkit/react-core/v2";

export interface SampleSpec {
  readonly buttonLabel: string;
  readonly filename: string;
  readonly mimeType: string;
  readonly testId: string;
  readonly fetchUrl: string;
  /**
   * Prompt sent alongside the attachment. Rendered as the user message
   * bubble in chat AND matched against by aimock to return the demo's
   * canned response. Phrased as a long, specific sentence ("demo pdf I
   * just attached" / "demo image I just attached") so it both reads
   * naturally and can't collide with arbitrary user prompts — random
   * uploads phrase questions differently and fall through to the proxy.
   */
  readonly autoPrompt: string;
}

export const SAMPLES: readonly SampleSpec[] = [
  {
    buttonLabel: "Try with sample image",
    filename: "sample.png",
    mimeType: "image/png",
    testId: "multimodal-sample-image-button",
    fetchUrl: "/demo-files/sample.png",
    autoPrompt: "can you tell me what is in this demo image I just attached",
  },
  {
    buttonLabel: "Try with sample PDF",
    filename: "sample.pdf",
    mimeType: "application/pdf",
    testId: "multimodal-sample-pdf-button",
    fetchUrl: "/demo-files/sample.pdf",
    autoPrompt: "can you tell me what is in this demo pdf I just attached",
  },
];

export interface SampleAttachmentButtonsProps {
  /**
   * Agent slug the parent `<CopilotKit agent="...">` provider wires up.
   * The buttons send via `useAgent({ agentId })` so the message lands on
   * the same agent the sibling `<CopilotChat />` is bound to.
   */
  readonly agentId: string;
}

/**
 * Magic-byte prefixes used to validate fetched sample files. We check
 * these because Next.js will happily serve a Git LFS *pointer* file (a
 * short plain-text stub starting with `version https://git-lfs...`) with
 * a `Content-Type: image/png` header if LFS wasn't pulled at build time.
 * Without this guard, the broken pointer bytes get base64-encoded,
 * sent to the agent as a valid-looking PNG, and rendered as a broken
 * <img>. Fail loudly with an actionable error instead.
 */
const MAGIC_BYTES: Record<string, number[]> = {
  "image/png": [0x89, 0x50, 0x4e, 0x47], // ‰PNG
  "application/pdf": [0x25, 0x50, 0x44, 0x46], // %PDF
};

const LFS_POINTER_PREFIX = "version https://git-lfs";

function bytesStartWith(bytes: Uint8Array, prefix: number[]): boolean {
  if (bytes.length < prefix.length) return false;
  for (let i = 0; i < prefix.length; i++) {
    if (bytes[i] !== prefix[i]) return false;
  }
  return true;
}

export interface FetchedSample {
  bytes: Uint8Array;
  base64: string;
  size: number;
}

/**
 * Fetch the sample file, validate its magic bytes, and return both the
 * raw bytes (for size accounting) and a base64 string suitable for
 * dropping into a `source.value` content part.
 */
async function fetchSample(spec: SampleSpec): Promise<FetchedSample> {
  const res = await fetch(spec.fetchUrl);
  if (!res.ok) {
    throw new Error(
      `Could not fetch sample "${spec.filename}" — HTTP ${res.status}. ` +
        `Is the file bundled under public${spec.fetchUrl}?`,
    );
  }
  const buffer = await res.arrayBuffer();
  const bytes = new Uint8Array(buffer);

  const asciiHead = new TextDecoder("utf-8", { fatal: false }).decode(
    bytes.slice(0, Math.min(bytes.length, 64)),
  );
  if (asciiHead.startsWith(LFS_POINTER_PREFIX)) {
    throw new Error(
      `Sample "${spec.filename}" is a Git LFS pointer, not the real asset. ` +
        "The deploy environment needs to run `git lfs pull` (or set " +
        "`GIT_LFS_ENABLED=1`) so the binary is checked out before the Next.js " +
        "app serves it.",
    );
  }

  const expectedMagic = MAGIC_BYTES[spec.mimeType];
  if (expectedMagic && !bytesStartWith(bytes, expectedMagic)) {
    throw new Error(
      `Sample "${spec.filename}" does not have a valid ${spec.mimeType} ` +
        "signature. The file may be corrupted or a wrong asset was committed.",
    );
  }

  // Convert to base64 via FileReader for parity with the paperclip path.
  // The `data:<mime>;base64,<payload>` URL is split — we only need the
  // payload, which becomes the `source.value` of the content part below.
  const blob = new Blob([buffer], { type: spec.mimeType });
  const dataUrl = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () =>
      reject(
        reader.error ?? new Error(`FileReader failed for ${spec.filename}`),
      );
    reader.onload = () => {
      if (typeof reader.result !== "string") {
        reject(new Error(`Unexpected FileReader result for ${spec.filename}`));
        return;
      }
      resolve(reader.result);
    };
    reader.readAsDataURL(blob);
  });
  const commaIdx = dataUrl.indexOf(",");
  const base64 = commaIdx >= 0 ? dataUrl.slice(commaIdx + 1) : dataUrl;

  return { bytes, base64, size: buffer.byteLength };
}

/**
 * Browser-friendly UUID. `crypto.randomUUID` is widely supported but we
 * fall back to a math-based UUIDv4 for the (rare) older runtime.
 */
function generateMessageId(): string {
  if (
    typeof crypto !== "undefined" &&
    typeof crypto.randomUUID === "function"
  ) {
    return crypto.randomUUID();
  }
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

/** The slice of the CopilotKit core that `submitSample` needs. */
type SampleSender = Pick<
  ReturnType<typeof useCopilotKit>["copilotkit"],
  "getAgent" | "runAgent"
>;

/**
 * Fetches the sample and sends it, with its prompt, to the agent the chat
 * observes once the file has loaded. The agent is looked up by id AFTER
 * the fetch, never captured at click time: a click that raced runtime
 * discovery could otherwise hold a provisional stand-in the chat has
 * since dropped, and the reply would land where nothing renders it
 * (PNI-575).
 */
export async function submitSample(
  copilotkit: SampleSender,
  agentId: string,
  spec: SampleSpec,
  load: (spec: SampleSpec) => Promise<FetchedSample> = fetchSample,
): Promise<void> {
  const sample = await load(spec);
  const target = copilotkit.getAgent(agentId);
  if (!target) {
    throw new Error(
      `Agent "${agentId}" is not available. Try again in a moment.`,
    );
  }
  const partType = spec.mimeType === "application/pdf" ? "document" : "image";

  // Build a multimodal user message as content parts: prompt text +
  // the attachment. The `LegacyConverterShim` in page.tsx will
  // rewrite the modern `image|document` part to the legacy `binary`
  // shape the @ag-ui/langgraph converter understands before the
  // request leaves the runtime.
  target.addMessage({
    id: generateMessageId(),
    role: "user",
    content: [
      { type: "text", text: spec.autoPrompt },
      {
        type: partType,
        source: {
          type: "data",
          value: sample.base64,
          mimeType: spec.mimeType,
        },
        metadata: {
          filename: spec.filename,
          size: sample.size,
        },
      },
    ],
  } as Parameters<typeof target.addMessage>[0]);

  await copilotkit.runAgent({ agent: target });
}

export function SampleAttachmentButtons({
  agentId,
}: SampleAttachmentButtonsProps) {
  const { isReady } = useAgent({ agentId });
  const { copilotkit } = useCopilotKit();
  const [loading, setLoading] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const sendSample = useCallback(
    async (spec: SampleSpec): Promise<void> => {
      // Until runtime discovery finishes, useAgent hands out a provisional
      // agent the chat will not keep (PNI-575). Nothing to send to yet.
      if (!isReady) return;
      setError(null);
      setLoading(spec.testId);
      try {
        await submitSample(copilotkit, agentId, spec);
      } catch (err) {
        console.error("[multimodal-demo] sample-attachment send failed", err);
        setError(err instanceof Error ? err.message : "Sample send failed.");
      } finally {
        setLoading(null);
      }
    },
    [agentId, copilotkit, isReady],
  );

  return (
    <div
      data-testid="multimodal-sample-row"
      className="flex flex-wrap items-center gap-2 rounded-md border border-black/10 bg-black/[0.03] px-3 py-2 text-sm dark:border-white/10 dark:bg-white/[0.04]"
    >
      <span className="text-xs font-medium text-black/60 dark:text-white/60">
        Bundled samples:
      </span>
      {SAMPLES.map((spec) => {
        const isLoading = loading === spec.testId;
        return (
          <button
            key={spec.testId}
            type="button"
            data-testid={spec.testId}
            disabled={!isReady || loading !== null}
            onClick={() => void sendSample(spec)}
            className="rounded border border-black/15 bg-white px-3 py-1 text-xs font-medium text-black transition hover:bg-black/5 disabled:cursor-not-allowed disabled:opacity-50 dark:border-white/15 dark:bg-neutral-900 dark:text-white dark:hover:bg-white/5"
          >
            {isLoading ? "Sending…" : spec.buttonLabel}
          </button>
        );
      })}
      {error && (
        <span
          data-testid="multimodal-sample-error"
          className="ml-auto max-w-[24rem] truncate text-xs text-red-600 dark:text-red-400"
          title={error}
        >
          {error}
        </span>
      )}
    </div>
  );
}

"use client";

/**
 * MCP Apps demo.
 *
 * MCP Apps are MCP servers that expose tools with associated UI resources.
 * The CopilotKit runtime is wired with `mcpApps: { servers: [...] }`
 * (see `src/app/api/copilotkit-mcp-apps/route.ts`), which auto-applies the
 * MCP Apps middleware. When the agent calls an MCP tool, the middleware
 * fetches the associated UI resource and emits an activity event; the
 * built-in `MCPAppsActivityRenderer` registered by `CopilotKitProvider`
 * renders the sandboxed iframe inline in the chat — no app-side renderer
 * registration required.
 *
 * This cell points at the public Excalidraw MCP app (https://mcp.excalidraw.com).
 *
 * Reference:
 * https://docs.copilotkit.ai/integrations/langgraph/generative-ui/mcp-apps
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";
import { Chat } from "./chat";

export default function MCPAppsDemo() {
  // No `renderActivityMessages`, no `useRenderActivityMessage` — the
  // CopilotKitProvider auto-registers the built-in `MCPAppsActivityRenderer`
  // for the "mcp-apps" activity type. A plain <CopilotChat /> is enough.
  return (
    <CopilotKit runtimeUrl="/api/copilotkit-mcp-apps" agent="mcp-apps">
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

"""MCP Apps demo backend (Langroid).

The CopilotKit runtime is wired with ``mcpApps: { servers: [...] }`` (see
``src/app/api/copilotkit-mcp-apps/route.ts``); the runtime auto-applies
the MCP Apps middleware, which injects the remote MCP server's tools
into the AG-UI run input at request time and emits the activity events
that CopilotKit's built-in ``MCPAppsActivityRenderer`` renders inline
in the chat as a sandboxed iframe.

Because the tool catalog is supplied by the runtime per-request (in
``RunAgentInput.tools``), the Python agent for this demo does **not**
declare any langroid ``ToolMessage`` subclasses. We forward the inbound
tool list straight to the OpenAI chat completions API and surface
whatever tool calls the model emits — the runtime middleware on the
TypeScript side picks them up, fetches the MCP UI resource, and emits
the activity events that render the iframe.

The handler is wired up by ``agent_server.py`` at ``POST /mcp-apps``.
"""

from __future__ import annotations

import asyncio
import json
import logging
import os
import uuid
from typing import Any, AsyncGenerator

import httpx
import openai
import pydantic
from ag_ui.core import (
    EventType,
    RunAgentInput,
    RunErrorEvent,
    RunFinishedEvent,
    RunStartedEvent,
    TextMessageContentEvent,
    TextMessageEndEvent,
    TextMessageStartEvent,
    ToolCallArgsEvent,
    ToolCallEndEvent,
    ToolCallStartEvent,
)
from fastapi import Request
from fastapi.responses import JSONResponse, StreamingResponse

logger = logging.getLogger(__name__)


# Speed-biased system prompt — mirrors the langgraph-python MCP Apps
# agent. We want one fast tool call that produces a correct-enough
# diagram; we are not optimizing for polish.
_SYSTEM_PROMPT = """\
You draw simple diagrams in Excalidraw via the MCP tool.

SPEED MATTERS. Produce a correct-enough diagram fast; do not optimize
for polish. Target: one tool call, done in seconds.

When the user asks for a diagram:
1. Call `create_view` ONCE with 3-5 elements total: shapes + arrows +
   an optional title text.
2. Use straightforward shapes (rectangle, ellipse, diamond) with plain
   `label` fields (`{"text": "...", "fontSize": 18}`) on them.
3. Connect with arrows. Endpoints can be element centers or simple
   coordinates — you don't need edge anchors / fixedPoint bindings.
4. Include ONE `cameraUpdate` at the END of the elements array that
   frames the whole diagram. Use an approved 4:3 size (600x450 or
   800x600). No opening camera needed.
5. Reply with ONE short sentence describing what you drew.

Every element needs a unique string `id` (e.g. "b1", "a1", "title").
Standard sizes: rectangles 160x70, ellipses/diamonds 120x80, 40-80px
gap between shapes.

Do NOT:
- Call `read_me`. You already know the basic shape API.
- Make multiple `create_view` calls.
- Iterate or refine. Ship on the first shot.
- Add decorative colors / fills / zone backgrounds unless the user
  explicitly asks for them.
- Add labels on arrows unless crucial.
"""


# ---------------------------------------------------------------------------
# AG-UI message → OpenAI message conversion (compact mirror of agui_adapter)
# ---------------------------------------------------------------------------


def _agui_messages_to_openai(messages: Any, system_prompt: str) -> list[dict[str, Any]]:
    """Translate AG-UI typed messages into OpenAI chat completion shape.

    Mirrors the conversion in ``agents.agui_adapter`` but is duplicated
    locally to keep this module's dependency surface small (the unified
    adapter pulls in ``ALL_TOOLS`` and other unrelated machinery).
    """
    out: list[dict[str, Any]] = [{"role": "system", "content": system_prompt}]
    if not messages:
        return out
    for msg in messages:
        role = (
            getattr(msg, "role", None) if not isinstance(msg, dict) else msg.get("role")
        )
        if not isinstance(role, str):
            continue
        if role == "tool":
            tool_call_id = (
                getattr(msg, "tool_call_id", None)
                if not isinstance(msg, dict)
                else msg.get("tool_call_id")
            )
            content = (
                getattr(msg, "content", "")
                if not isinstance(msg, dict)
                else msg.get("content", "")
            ) or ""
            if tool_call_id:
                out.append(
                    {
                        "role": "tool",
                        "tool_call_id": str(tool_call_id),
                        "content": str(content),
                    }
                )
            continue
        if role == "assistant":
            content = (
                getattr(msg, "content", None)
                if not isinstance(msg, dict)
                else msg.get("content")
            )
            tool_calls_raw = (
                getattr(msg, "tool_calls", None)
                if not isinstance(msg, dict)
                else msg.get("tool_calls")
            )
            entry: dict[str, Any] = {"role": "assistant"}
            if content:
                entry["content"] = str(content)
            if tool_calls_raw:
                tcs: list[dict[str, Any]] = []
                for tc in tool_calls_raw:
                    tc_id = getattr(tc, "id", None)
                    fn = getattr(tc, "function", None)
                    if fn is None and isinstance(tc, dict):
                        fn_name = (tc.get("function") or {}).get("name", "")
                        fn_args = (tc.get("function") or {}).get("arguments", "")
                        tc_id = tc_id or tc.get("id", "")
                    else:
                        fn_name = getattr(fn, "name", "") if fn else ""
                        fn_args = getattr(fn, "arguments", "") if fn else ""
                    if tc_id and fn_name:
                        tcs.append(
                            {
                                "id": str(tc_id),
                                "type": "function",
                                "function": {
                                    "name": str(fn_name),
                                    "arguments": str(fn_args),
                                },
                            }
                        )
                if tcs:
                    entry["tool_calls"] = tcs
                    if "content" not in entry:
                        # OpenAI requires content to be null (not missing)
                        # when tool_calls are present.
                        entry["content"] = None
            else:
                if "content" not in entry:
                    entry["content"] = ""
            out.append(entry)
            continue
        if role in ("user", "system", "developer"):
            content = (
                getattr(msg, "content", None)
                if not isinstance(msg, dict)
                else msg.get("content")
            )
            if isinstance(content, str):
                out.append({"role": role, "content": content})
    return out


def _runtime_tools_to_openai(tools: Any) -> list[dict[str, Any]]:
    """Convert the AG-UI ``RunAgentInput.tools`` array into OpenAI shape.

    The MCP Apps middleware on the TypeScript side advertises the remote
    MCP server's tools to the agent via this field. Each tool is a
    ``{ name, description, parameters }`` triple.
    """
    if not tools:
        return []
    converted: list[dict[str, Any]] = []
    for tool in tools:
        name = (
            getattr(tool, "name", None)
            if not isinstance(tool, dict)
            else tool.get("name")
        )
        if not isinstance(name, str) or not name:
            continue
        description = (
            getattr(tool, "description", "")
            if not isinstance(tool, dict)
            else tool.get("description", "")
        ) or ""
        parameters = (
            getattr(tool, "parameters", None)
            if not isinstance(tool, dict)
            else tool.get("parameters")
        )
        if parameters is None:
            parameters = {"type": "object", "properties": {}}
        converted.append(
            {
                "type": "function",
                "function": {
                    "name": name,
                    "description": str(description),
                    "parameters": parameters,
                },
            }
        )
    return converted


# ---------------------------------------------------------------------------
# SSE plumbing
# ---------------------------------------------------------------------------


def _sse_line(event: Any) -> str:
    if hasattr(event, "model_dump"):
        data = event.model_dump(by_alias=True, exclude_none=True)
    else:
        data = dict(event)
    return f"data: {json.dumps(data)}\n\n"


async def handle_run(request: Request) -> StreamingResponse:
    """AG-UI ``/mcp-apps`` SSE handler — streams text + tool-call events."""
    error_id = str(uuid.uuid4())
    try:
        body = await request.json()
    except (json.JSONDecodeError, ValueError) as exc:
        logger.exception("mcp-apps: failed to parse body (error_id=%s)", error_id)
        return JSONResponse(
            {
                "error": "Invalid JSON body",
                "errorId": error_id,
                "class": exc.__class__.__name__,
            },
            status_code=400,
        )
    try:
        run_input = RunAgentInput(**body)
    except (pydantic.ValidationError, TypeError, ValueError) as exc:
        logger.exception("mcp-apps: invalid RunAgentInput (error_id=%s)", error_id)
        return JSONResponse(
            {
                "error": "Invalid RunAgentInput payload",
                "errorId": error_id,
                "class": exc.__class__.__name__,
            },
            status_code=422,
        )

    oai_messages = _agui_messages_to_openai(run_input.messages, _SYSTEM_PROMPT)
    oai_tools = _runtime_tools_to_openai(getattr(run_input, "tools", None))
    model = os.getenv("LANGROID_MODEL", "gpt-4o-mini")
    thread_id = run_input.thread_id or str(uuid.uuid4())

    async def event_stream() -> AsyncGenerator[str, None]:
        run_id = str(uuid.uuid4())
        yield _sse_line(
            RunStartedEvent(
                type=EventType.RUN_STARTED,
                thread_id=thread_id,
                run_id=run_id,
            )
        )

        try:
            client = openai.AsyncOpenAI()
            response = await client.chat.completions.create(
                model=model,
                messages=oai_messages,
                tools=oai_tools if oai_tools else openai.NOT_GIVEN,
            )
        except (openai.APIError, httpx.HTTPError, asyncio.TimeoutError) as exc:
            logger.exception("mcp-apps: OpenAI call failed")
            yield _sse_line(
                RunErrorEvent(
                    type=EventType.RUN_ERROR,
                    message=f"Agent run failed: {exc.__class__.__name__}",
                )
            )
            yield _sse_line(
                RunFinishedEvent(
                    type=EventType.RUN_FINISHED,
                    thread_id=thread_id,
                    run_id=run_id,
                )
            )
            return

        choice = response.choices[0].message if response.choices else None
        if choice is None:
            yield _sse_line(
                RunFinishedEvent(
                    type=EventType.RUN_FINISHED,
                    thread_id=thread_id,
                    run_id=run_id,
                )
            )
            return

        # Emit any tool calls the model produced. The MCP Apps middleware on
        # the TypeScript side intercepts these to fetch the UI resource and
        # render the activity iframe.
        tool_calls = getattr(choice, "tool_calls", None) or []
        for tc in tool_calls:
            tc_id = str(getattr(tc, "id", None) or uuid.uuid4())
            fn = getattr(tc, "function", None)
            tc_name = getattr(fn, "name", "") if fn else ""
            tc_args = getattr(fn, "arguments", "") if fn else ""
            if not tc_name:
                continue
            yield _sse_line(
                ToolCallStartEvent(
                    type=EventType.TOOL_CALL_START,
                    tool_call_id=tc_id,
                    tool_call_name=tc_name,
                )
            )
            if tc_args:
                yield _sse_line(
                    ToolCallArgsEvent(
                        type=EventType.TOOL_CALL_ARGS,
                        tool_call_id=tc_id,
                        delta=str(tc_args),
                    )
                )
            yield _sse_line(
                ToolCallEndEvent(
                    type=EventType.TOOL_CALL_END,
                    tool_call_id=tc_id,
                )
            )

        # Surface any narration text the model produced alongside the tool
        # call. Many models reply with both a one-liner and a tool call.
        content = getattr(choice, "content", None) or ""
        if content:
            msg_id = str(uuid.uuid4())
            yield _sse_line(
                TextMessageStartEvent(
                    type=EventType.TEXT_MESSAGE_START, message_id=msg_id
                )
            )
            yield _sse_line(
                TextMessageContentEvent(
                    type=EventType.TEXT_MESSAGE_CONTENT,
                    message_id=msg_id,
                    delta=content,
                )
            )
            yield _sse_line(
                TextMessageEndEvent(type=EventType.TEXT_MESSAGE_END, message_id=msg_id)
            )

        yield _sse_line(
            RunFinishedEvent(
                type=EventType.RUN_FINISHED,
                thread_id=thread_id,
                run_id=run_id,
            )
        )

    return StreamingResponse(
        event_stream(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )

// CopilotKit runtime for the MCP Apps cell (Langroid).
//
// The runtime's `mcpApps` config auto-applies the MCP Apps middleware:
// when the agent calls a tool backed by an MCP UI resource, the
// middleware fetches the resource and emits the activity event that the
// built-in `MCPAppsActivityRenderer` (registered by CopilotKit
// internally) renders inline in the chat as a sandboxed iframe.
//
// The agent itself is the no-tools FastAPI handler at
// `${AGENT_URL}/mcp-apps` — see `src/agents/mcp_apps_agent.py`. The
// runtime forwards the MCP tool catalog through `RunAgentInput.tools`,
// the agent forwards it to OpenAI, and any tool calls the model emits
// flow back through the middleware.
//
// Reference:
// https://docs.copilotkit.ai/integrations/langgraph/generative-ui/mcp-apps

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { HttpAgent } from "@ag-ui/client";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

const mcpAppsAgent = new HttpAgent({ url: `${AGENT_URL}/mcp-apps` });

// headless-complete shares this runtime (its page wires
// runtimeUrl="/api/copilotkit-mcp-apps") but is backed by the unified
// Langroid agent on "/" — the same backend the main route registers it
// against.
const headlessCompleteAgent = new HttpAgent({ url: `${AGENT_URL}/` });

const runtime = new CopilotRuntime({
  // @ts-ignore -- see main route.ts; published CopilotRuntime's `agents`
  // type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects
  // plain Records. Fixed in source, pending release.
  agents: {
    "headless-complete": headlessCompleteAgent,
    "mcp-apps": mcpAppsAgent,
    default: mcpAppsAgent,
  },
  mcpApps: {
    servers: [
      {
        type: "http",
        url: process.env.MCP_SERVER_URL || "https://mcp.excalidraw.com",
        // Always pin a stable `serverId`. Without it CopilotKit hashes the
        // URL, and a URL change silently breaks restoration of persisted
        // MCP Apps in prior conversation threads.
        serverId: "excalidraw",
      },
    ],
  },
});

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-mcp-apps",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

"use client";

import { CopilotChat } from "@copilotkit/react-core/v2";
import { useMcpAppsSuggestions } from "./suggestions";

export function Chat() {
  useMcpAppsSuggestions();
  return <CopilotChat agentId="mcp-apps" className="h-full rounded-2xl" />;
}

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export function useMcpAppsSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Draw a flowchart",
        message: "Use Excalidraw to draw a simple flowchart with three steps.",
      },
      {
        title: "Sketch a system diagram",
        message:
          "Open Excalidraw and sketch a system diagram with a client, server, and database.",
      },
    ],
    available: "always",
  });
}

