            const pct = total > 0 ? ((val / total) * 100).toFixed(0) : 0;
            return (
              <div
                key={index}
                className="flex items-center gap-3 text-sm transition-opacity duration-300 ease-out"
                style={{ opacity: 1 }}
              >
                <span
                  className="inline-block h-3 w-3 rounded-full shrink-0"
