"use client";

// Tool Rendering — DEFAULT CATCH-ALL variant (simplest).
//
// This cell is the simplest point in the three-way progression. The
// backend exposes a handful of mock tools (get_weather, search_flights,
// get_stock_price, roll_dice) and the frontend ONLY opts into
// CopilotKit's built-in default tool-call card — no per-tool renderers,
// no custom wildcard UI.
//
// `useDefaultRenderTool()` (called with no config) registers the built-
// in `DefaultToolCallRenderer` under the `*` wildcard. That renderer
// shows the tool name, a live status pill (Running → Done), and a
// collapsible "Arguments / Result" section that fills in as the call
// progresses. Without this hook the runtime has NO `*` renderer, so
// `useRenderToolCall` falls through to `null` and tool calls are
// invisible — the user only sees the assistant's final text summary.

import React from "react";
import {
  CopilotKit,
  CopilotChat,
  useDefaultRenderTool,
} from "@copilotkit/react-core/v2";
import { useSuggestions } from "./suggestions";

export default function ToolRenderingDefaultCatchallDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit"
      agent="tool-rendering-default-catchall"
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  // Opt in to CopilotKit's built-in default tool-call card. Called with
  // no config so the package-provided `DefaultToolCallRenderer` is used
  // as the wildcard renderer — this is the "out-of-the-box" UI the cell
  // is meant to showcase.
  useDefaultRenderTool();

  useSuggestions();

  return (
    <CopilotChat
      agentId="tool-rendering-default-catchall"
      className="h-full rounded-2xl"
    />
  );
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";

// The agent backend runs as a separate process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

function createAgent(subpath: string = "") {
  return new HttpAgent({ url: `${AGENT_URL}${subpath}/run` });
}

// Shared-router agents — every id here resolves to the same backend + same
// tool set. Per-demo behavior is driven by the frontend (tools, suggestions,
// render slots).
const sharedAgentNames = [
  "agentic_chat",
  "tool-rendering",
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "shared-state-read",
  "shared-state-write",
  "shared-state-streaming",
  "frontend_tools",
  "prebuilt_sidebar",
  "prebuilt_popup",
  "chat_slots",
  "chat_customization_css",
  "headless_simple",
  "headless_complete",
  "readonly_state_agent_context",
  "human_in_the_loop",
  // Hyphenated aliases matching what the demo pages actually request
  // (mirrors langgraph-python's naming). The underscore names above are
  // kept as additive aliases.
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "headless-complete",
  "readonly-state-agent-context",
  // Requested by demos/threadid-frontend-tool-roundtrip via /api/copilotkit;
  // no dedicated agent_server.py mount exists — the shared default router
  // serves it.
  "threadid-frontend-tool-roundtrip",
];

// Specialized routers live at dedicated subpaths on the agent_server so the
// distinct system prompt / tool set / model can surface through this same
// runtime. Each subpath matches the `include_router(..., prefix=)` in
// src/agent_server.py.
const specializedAgents: Record<string, string> = {
  "agentic-chat-reasoning": "/reasoning",
  "reasoning-default-render": "/reasoning",
  "tool-rendering-reasoning-chain": "/tool-rendering-reasoning-chain",
  "shared-state-read-write": "/shared-state-read-write",
  "gen-ui-agent": "/gen-ui-agent",
  "gen-ui-tool-based": "/gen-ui-tool-based",
  // frontend-tools-async injects an async `query_notes` useFrontendTool at
  // request time; its dedicated router (make_request_aware_router) forwards
  // injected tools, which the shared FixedAGUIChatWorkflow catch-all does not.
  // Both the hyphenated (page-requested) and underscore (alias) ids route here.
  "frontend-tools-async": "/frontend-tools-async",
  frontend_tools_async: "/frontend-tools-async",
  "beautiful-chat": "/beautiful-chat",
  hitl_in_app: "/hitl-in-app",
  // Hyphenated names the hitl demo pages actually request. Both route to
  // the DEDICATED routers mounted in src/agent_server.py (lines ~105-106) —
  // a sharedAgentNames alias would silently route them to the default
  // backend instead.
  "hitl-in-app": "/hitl-in-app",
  "hitl-in-chat": "/hitl-in-chat",
  subagents: "/subagents",
  // Interrupt-adapted scheduling demos — both gen-ui-interrupt and
  // interrupt-headless share the same backend agent; only the frontend
  // UX differs (inline picker in chat vs. external popup).
  "gen-ui-interrupt": "/interrupt",
  "interrupt-headless": "/interrupt",
};

const agents: Record<string, AbstractAgent> = {};
for (const name of sharedAgentNames) {
  agents[name] = createAgent();
}
for (const [name, subpath] of Object.entries(specializedAgents)) {
  agents[name] = createAgent(subpath);
}
agents["default"] = createAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- see main route.ts; published CopilotRuntime's `agents`
        // type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects
        // plain Records. Fixed in source, pending release.
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    const err = error as Error;
    console.error(`[copilotkit/route] ERROR: ${err.message}`);
    console.error(`[copilotkit/route] Stack: ${err.stack}`);
    return NextResponse.json(
      { error: err.message, stack: err.stack },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

import * as React from "react";

// Inline-cloned shadcn/ui <Badge />. Plain Tailwind classes — no `cn()`,
// no `cva`. Local to this demo only.

type Variant = "default" | "secondary" | "outline" | "success" | "warning";

const variantClasses: Record<Variant, string> = {
  default: "border-transparent bg-neutral-900 text-neutral-50",
  secondary: "border-transparent bg-neutral-100 text-neutral-900",
  outline: "border-neutral-200 text-neutral-900",
  success: "border-transparent bg-emerald-100 text-emerald-700",
  warning: "border-transparent bg-amber-100 text-amber-700",
};

export interface BadgeProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: Variant;
}

export function Badge({
  className = "",
  variant = "default",
  ...props
}: BadgeProps) {
  return (
    <div
      className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-[10px] font-medium uppercase tracking-wider transition-colors ${variantClasses[variant]} ${className}`}
      {...props}
    />
  );
}

import * as React from "react";

// Inline-cloned shadcn/ui <Card /> primitives. Hand-written with plain
// Tailwind classes — no `cn()` helper, no `cva`, no Radix primitives.
// Local to this demo only.

export const Card = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className = "", ...props }, ref) => (
  <div
    ref={ref}
    className={`rounded-lg border border-neutral-200 bg-white text-neutral-950 shadow-sm ${className}`}
    {...props}
  />
));
Card.displayName = "Card";

export const CardHeader = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className = "", ...props }, ref) => (
  <div
    ref={ref}
    className={`flex flex-col space-y-1.5 p-4 ${className}`}
    {...props}
  />
));
CardHeader.displayName = "CardHeader";

export const CardTitle = React.forwardRef<
  HTMLHeadingElement,
  React.HTMLAttributes<HTMLHeadingElement>
>(({ className = "", ...props }, ref) => (
  <h3
    ref={ref}
    className={`text-sm font-semibold leading-none tracking-tight text-neutral-900 ${className}`}
    {...props}
  />
));
CardTitle.displayName = "CardTitle";

export const CardContent = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className = "", ...props }, ref) => (
  <div ref={ref} className={`p-4 pt-0 ${className}`} {...props} />
));
CardContent.displayName = "CardContent";

"use client";

import React from "react";
import { Card, CardContent, CardHeader, CardTitle } from "./card";
import { Badge } from "./badge";

// Catch-all tool-call renderer for the tool-rendering-default-catchall
// demo, restyled with inline-cloned shadcn primitives. The demo's
// conceptual point is unchanged: a SINGLE wildcard renderer paints every
// tool call (no per-tool renderers). We just give that wildcard a
// shadcn-flavored visual.

export type CatchallToolStatus = "inProgress" | "executing" | "complete";

export interface ShadcnCatchallRendererProps {
  name: string;
  status: CatchallToolStatus;
  parameters: unknown;
  result: string | undefined;
}

export function ShadcnCatchallRenderer({
  name,
  status,
  parameters,
  result,
}: ShadcnCatchallRendererProps) {
  const parsedResult = parseResult(result);
  const done = status === "complete";

  return (
    <Card
      data-testid="shadcn-catchall-card"
      data-tool-name={name}
      data-status={status}
      className="my-3 overflow-hidden"
    >
      <CardHeader className="flex flex-row items-center justify-between space-y-0 border-b border-neutral-200 bg-neutral-50/60 py-3">
        <div className="flex items-center gap-2">
          <span className="text-[10px] font-medium uppercase tracking-wider text-neutral-500">
            Tool
          </span>
          <CardTitle
            data-testid="shadcn-catchall-tool-name"
            className="font-mono text-sm text-neutral-900"
          >
            {name}
          </CardTitle>
        </div>
        <StatusBadge status={status} />
      </CardHeader>

      <CardContent className="grid gap-3 p-4 text-sm">
        <Section label="Arguments">
          <pre
            data-testid="shadcn-catchall-args"
            className="overflow-x-auto rounded-md border border-neutral-200 bg-neutral-50 p-2.5 font-mono text-xs text-neutral-900"
          >
            {safeStringify(parameters)}
          </pre>
        </Section>

        <Section label="Result">
          {done ? (
            <pre
              data-testid="shadcn-catchall-result"
              className="overflow-x-auto rounded-md border border-emerald-200 bg-emerald-50 p-2.5 font-mono text-xs text-neutral-900"
            >
              {parsedResult !== undefined
                ? safeStringify(parsedResult)
                : "(empty)"}
            </pre>
          ) : (
            <p className="text-xs italic text-neutral-500">
              waiting for tool to finish…
            </p>
          )}
        </Section>
      </CardContent>
    </Card>
  );
}

function Section({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div>
      <div className="mb-1.5 text-[10px] font-medium uppercase tracking-wider text-neutral-500">
        {label}
      </div>
      {children}
    </div>
  );
}

function StatusBadge({ status }: { status: CatchallToolStatus }) {
  const { label, variant } = describeStatus(status);
  return (
    <Badge data-testid="shadcn-catchall-status" variant={variant}>
      {label}
    </Badge>
  );
}

function describeStatus(status: CatchallToolStatus): {
  label: string;
  variant: "secondary" | "warning" | "success";
} {
  switch (status) {
    case "inProgress":
      return { label: "streaming", variant: "warning" };
    case "executing":
      return { label: "running", variant: "secondary" };
    case "complete":
      return { label: "done", variant: "success" };
  }
}

function parseResult(result: string | undefined): unknown {
  if (result === undefined || result === null) return undefined;
  if (typeof result !== "string") return result;
  try {
    return JSON.parse(result);
  } catch {
    return result;
  }
}

function safeStringify(value: unknown): string {
  try {
    return JSON.stringify(value, null, 2);
  } catch {
    return String(value);
  }
}

"use client";

