"use client";

/**
 * Headless = bring-your-own-UI. Simple = the smallest possible chat using
 * the two core hooks (`useAgent` + `useCopilotKit`), styled with shadcn/ui.
 */

import { CopilotKit } from "@copilotkit/react-core/v2";
import { Chat } from "./chat";

export default function HeadlessSimpleDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="headless-simple">
      <Chat />
    </CopilotKit>
  );
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";

// The agent backend runs as a separate process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

function createAgent(subpath: string = "") {
  return new HttpAgent({ url: `${AGENT_URL}${subpath}/run` });
}

// Shared-router agents — every id here resolves to the same backend + same
// tool set. Per-demo behavior is driven by the frontend (tools, suggestions,
// render slots).
const sharedAgentNames = [
  "agentic_chat",
  "tool-rendering",
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "shared-state-read",
  "shared-state-write",
  "shared-state-streaming",
  "frontend_tools",
  "prebuilt_sidebar",
  "prebuilt_popup",
  "chat_slots",
  "chat_customization_css",
  "headless_simple",
  "headless_complete",
  "readonly_state_agent_context",
  "human_in_the_loop",
  // Hyphenated aliases matching what the demo pages actually request
  // (mirrors langgraph-python's naming). The underscore names above are
  // kept as additive aliases.
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "headless-complete",
  "readonly-state-agent-context",
  // Requested by demos/threadid-frontend-tool-roundtrip via /api/copilotkit;
  // no dedicated agent_server.py mount exists — the shared default router
  // serves it.
  "threadid-frontend-tool-roundtrip",
];

// Specialized routers live at dedicated subpaths on the agent_server so the
// distinct system prompt / tool set / model can surface through this same
// runtime. Each subpath matches the `include_router(..., prefix=)` in
// src/agent_server.py.
const specializedAgents: Record<string, string> = {
  "agentic-chat-reasoning": "/reasoning",
  "reasoning-default-render": "/reasoning",
  "tool-rendering-reasoning-chain": "/tool-rendering-reasoning-chain",
  "shared-state-read-write": "/shared-state-read-write",
  "gen-ui-agent": "/gen-ui-agent",
  "gen-ui-tool-based": "/gen-ui-tool-based",
  // frontend-tools-async injects an async `query_notes` useFrontendTool at
  // request time; its dedicated router (make_request_aware_router) forwards
  // injected tools, which the shared FixedAGUIChatWorkflow catch-all does not.
  // Both the hyphenated (page-requested) and underscore (alias) ids route here.
  "frontend-tools-async": "/frontend-tools-async",
  frontend_tools_async: "/frontend-tools-async",
  "beautiful-chat": "/beautiful-chat",
  hitl_in_app: "/hitl-in-app",
  // Hyphenated names the hitl demo pages actually request. Both route to
  // the DEDICATED routers mounted in src/agent_server.py (lines ~105-106) —
  // a sharedAgentNames alias would silently route them to the default
  // backend instead.
  "hitl-in-app": "/hitl-in-app",
  "hitl-in-chat": "/hitl-in-chat",
  subagents: "/subagents",
  // Interrupt-adapted scheduling demos — both gen-ui-interrupt and
  // interrupt-headless share the same backend agent; only the frontend
  // UX differs (inline picker in chat vs. external popup).
  "gen-ui-interrupt": "/interrupt",
  "interrupt-headless": "/interrupt",
};

const agents: Record<string, AbstractAgent> = {};
for (const name of sharedAgentNames) {
  agents[name] = createAgent();
}
for (const [name, subpath] of Object.entries(specializedAgents)) {
  agents[name] = createAgent(subpath);
}
agents["default"] = createAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- see main route.ts; published CopilotRuntime's `agents`
        // type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects
        // plain Records. Fixed in source, pending release.
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    const err = error as Error;
    console.error(`[copilotkit/route] ERROR: ${err.message}`);
    console.error(`[copilotkit/route] Stack: ${err.stack}`);
    return NextResponse.json(
      { error: err.message, stack: err.stack },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

"use client";

/**
 * The whole demo, in one screenful: two hooks turn a shadcn shell into a
 * working chat. `useAgent` exposes the message log + run state for one
 * agent; `useCopilotKit` runs it.
 */

import { useState } from "react";
import { useAgent, useCopilotKit } from "@copilotkit/react-core/v2";
import { Sparkles } from "lucide-react";

import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";

import { AssistantBubble, UserBubble } from "./message-bubble";
import { Composer } from "./composer";
import { EmptyState } from "./empty-state";
import { TypingIndicator } from "./typing-indicator";

export function Chat() {
  const { agent } = useAgent({ agentId: "headless-simple" });
  const { copilotkit } = useCopilotKit();
  const [input, setInput] = useState("");

  const send = (text: string) => {
    const trimmed = text.trim();
    if (!trimmed || agent.isRunning) return;
    agent.addMessage({
      id: crypto.randomUUID(),
      role: "user",
      content: trimmed,
    });
    setInput("");
    void copilotkit.runAgent({ agent }).catch((err) => {
      // The Headless Simple demo is the canonical "two hooks, your
      // design system" example users copy-paste as a starting point.
      // Silently swallowing errors here would model broken practice;
      // log so a network failure / runtime error / transport disconnect
      // surfaces in the console for the developer.
      console.error("[langgraph-python:headless-simple] runAgent failed", err);
    });
  };

  // Render only plain user/assistant text — Simple skips tool/system/etc.
  const visible = agent.messages.flatMap((m) => {
    if (m.role !== "user" && m.role !== "assistant") return [];
    if (typeof m.content !== "string" || m.content.length === 0) return [];
    return [{ id: m.id, role: m.role, content: m.content }];
  });

  const last = visible[visible.length - 1];
  const showTyping = agent.isRunning && (!last || last.role === "user");

  const hasMessages = visible.length > 0;

  return (
    <div className="flex h-screen w-full justify-center bg-background p-4 sm:p-6">
      <Card className="flex h-full w-full max-w-3xl flex-col gap-0 overflow-hidden border-border py-0 shadow-2xl shadow-black/10">
        <CardHeader className="border-b border-border/60 py-4">
          <CardTitle className="flex items-center gap-2 text-base">
            <Sparkles className="h-4 w-4 text-primary" aria-hidden="true" />
            Headless Chat
          </CardTitle>
          <CardDescription>
            Two hooks, your design system — that&apos;s the whole demo.
          </CardDescription>
        </CardHeader>

        <CardContent className="flex min-h-0 flex-1 flex-col p-0">
          {!hasMessages ? (
            // Render empty state OUTSIDE ScrollArea so flex-1 + justify-
            // center can vertically center it. Radix ScrollArea wraps
            // content in a `display: table` div that breaks `h-full`
            // propagation, so a centered child inside it hugs the top.
            <div className="flex min-h-0 flex-1 flex-col">
              <EmptyState onPick={send} />
            </div>
          ) : (
            <ScrollArea className="min-h-0 flex-1">
              <div className="flex flex-col gap-4 px-4 py-4 sm:px-6">
                {visible.map((m) =>
                  m.role === "user" ? (
                    <UserBubble key={m.id} content={m.content} />
                  ) : (
                    <AssistantBubble key={m.id} content={m.content} />
                  ),
                )}
                {showTyping && <TypingIndicator />}
              </div>
            </ScrollArea>
          )}

          <Separator className="bg-border/60" />

          <Composer
            value={input}
            onChange={setInput}
            onSend={() => send(input)}
            disabled={!input.trim() || agent.isRunning}
          />
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

/** Bottom-of-chat input. Enter sends, Shift+Enter inserts a newline. */

import { ArrowUp } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

export function Composer({
  value,
  onChange,
  onSend,
  disabled,
}: {
  value: string;
  onChange: (next: string) => void;
  onSend: () => void;
  disabled: boolean;
}) {
  return (
    <div data-testid="headless-composer" className="bg-background p-3 sm:p-4">
      <div
        className={cn(
          "flex items-end gap-2 rounded-2xl border border-border/60 bg-muted/50 p-2",
          "focus-within:bg-background focus-within:ring-2 focus-within:ring-ring/40",
          "transition-colors",
        )}
      >
        <Textarea
          rows={1}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              if (!disabled) onSend();
            }
          }}
          placeholder="Message the agent..."
          className={cn(
            "min-h-[40px] max-h-40 flex-1 resize-none border-0 bg-transparent",
            "px-2 py-2 text-sm shadow-none",
            "focus-visible:ring-0 focus-visible:border-transparent",
          )}
        />
        <Button
          type="button"
          size="icon"
          onClick={onSend}
          disabled={disabled}
          aria-label="Send message"
          className="h-9 w-9 shrink-0 rounded-xl"
        >
          <ArrowUp className="h-4 w-4" />
        </Button>
      </div>
    </div>
  );
}

"use client";

/** First-load pane: heading, sparkles icon, and three sample prompt chips. */

import { Sparkles } from "lucide-react";
import { Badge } from "@/components/ui/badge";

const SAMPLES = [
  "Say hello in one short sentence.",
  "Tell me a one-line joke.",
  "Give me a fun fact.",
];

export function EmptyState({ onPick }: { onPick: (text: string) => void }) {
  return (
    <div className="flex h-full flex-1 flex-col items-center justify-center gap-6 px-8 py-10 text-center">
      <div className="flex flex-col items-center gap-2">
        <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-primary/10 text-primary">
          <Sparkles className="h-6 w-6" aria-hidden="true" />
        </div>
        <h2 className="text-lg font-semibold tracking-tight">
          Start a conversation
        </h2>
        <p className="max-w-sm text-sm text-muted-foreground">
          Two hooks, one shadcn shell — text in, text out.
        </p>
      </div>
      <div className="flex w-full max-w-md flex-wrap items-center justify-center gap-2">
        {SAMPLES.map((s) => (
          <Badge
            key={s}
            asChild
            variant="secondary"
            className="cursor-pointer px-3 py-1.5 text-xs font-normal hover:bg-secondary/80"
          >
            <button type="button" onClick={() => onPick(s)}>
              {s}
            </button>
          </Badge>
        ))}
      </div>
    </div>
  );
}

"use client";

/** User and assistant bubbles. Plain text only — Simple skips markdown. */

import { Bot, User } from "lucide-react";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";

export function UserBubble({ content }: { content: string }) {
  return (
