// Dedicated runtime for the A2UI Fixed Schema demo.
//
// The backend agent (src/agents/a2ui_fixed.py) emits a STREAMED `render_a2ui`
// tool-CALL carrying the pre-authored flight schema plus a runtime data model.
// The A2UI middleware watches that streamed call (because `injectA2UITool: true`
// populates its watched-names set with `render_a2ui`) and streams the rendered
// surface to the frontend's fixed catalog. A `TOOL_CALL_RESULT` does NOT mount
// the surface — the llama-index AG-UI adapter only re-emits results via
// `MESSAGES_SNAPSHOT`, which the middleware ignores — so the agent re-emits the
// fixed schema as a streamed `render_a2ui` call instead (see the agent docstring).

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

const a2uiFixedAgent = new HttpAgent({
  url: `${AGENT_URL}/a2ui-fixed/run`,
});

const runtime = new CopilotRuntime({
  // @ts-ignore -- see main route.ts
  agents: { "a2ui-fixed-schema": a2uiFixedAgent as AbstractAgent },
  a2ui: {
    // Set `true` so the middleware WATCHES the `render_a2ui` tool-call name
    // (the watched-names set is only populated when the tool is injected). The
    // backend re-emits the fixed schema as a streamed `render_a2ui` call that
    // the middleware mounts the surface from; it does NOT call the injected
    // tool itself (the backend `display_flight` tool produces the schema).
    injectA2UITool: true,
  },
});

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-a2ui-fixed-schema",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

import * as React from "react";

/**
 * ShadCN-style Badge primitive (inline-cloned for this demo).
 * Plain Tailwind classes, no `cn()`/`cva` helpers.
 */
type Variant = "default" | "secondary" | "outline" | "success";

const variantClasses: Record<Variant, string> = {
  default: "border-transparent bg-neutral-900 text-neutral-50",
  secondary: "border-transparent bg-neutral-100 text-neutral-900",
  outline: "border-neutral-200 text-neutral-700 bg-white",
  success: "border-transparent bg-emerald-100 text-emerald-700",
};

export interface BadgeProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: Variant;
}

export function Badge({
  className = "",
  variant = "default",
  ...props
}: BadgeProps) {
  return (
    <div
      className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium tracking-wide ${variantClasses[variant]} ${className}`}
      {...props}
    />
  );
}

import * as React from "react";

/**
 * ShadCN-style Button primitive (inline-cloned for this demo).
 * Plain Tailwind classes, no `cn()`/`cva` helpers.
 */
type Variant = "default" | "outline" | "secondary" | "ghost" | "success";
type Size = "default" | "sm" | "lg";

const baseClasses =
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-neutral-950 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-60";

const variantClasses: Record<Variant, string> = {
  default: "bg-neutral-900 text-neutral-50 shadow-sm hover:bg-neutral-800",
  outline:
    "border border-neutral-200 bg-white text-neutral-900 shadow-sm hover:bg-neutral-100",
  secondary: "bg-neutral-100 text-neutral-900 shadow-sm hover:bg-neutral-200",
  ghost: "hover:bg-neutral-100 hover:text-neutral-900",
  success:
    "bg-emerald-50 text-emerald-700 border border-emerald-200 shadow-sm hover:bg-emerald-50",
};

const sizeClasses: Record<Size, string> = {
  default: "h-10 px-4 py-2",
  sm: "h-8 rounded-md px-3 text-xs",
  lg: "h-11 rounded-md px-6",
};

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Variant;
  size?: Size;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    { className = "", variant = "default", size = "default", ...props },
    ref,
  ) => {
    return (
      <button
        ref={ref}
        className={`${baseClasses} ${variantClasses[variant]} ${sizeClasses[size]} ${className}`}
        {...props}
      />
    );
  },
);
Button.displayName = "Button";

