    get_stock_price: stockPriceTool,
    roll_d20: rollD20Tool,
  },
  // Gold parity (tool_rendering_agent.py uses gpt-5.4). On gpt-5-mini this agent
  // prefixed the flights turn with a restatement of the PREVIOUS turn's
