"use client";

// Chat Customization (CSS) — every visual choice in this demo lives in
// theme.css and is scoped to the `.chat-css-demo-scope` wrapper. The page
// intentionally stays minimal so the contrast against the default look
// comes entirely from the stylesheet.
//
// https://docs.copilotkit.ai/custom-look-and-feel/customize-built-in-ui-components

import React from "react";
import { CopilotKit, CopilotChat } from "@copilotkit/react-core/v2";
import "./theme.css";

export default function ChatCustomizationCssDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="chat-customization-css">
      <div className="flex justify-center items-center h-screen w-full bg-white p-6">
        <div className="chat-css-demo-scope h-full w-full max-w-4xl">
          <CopilotChat
            agentId="chat-customization-css"
            className="h-full"
            attachments={{ enabled: true }}
          />
        </div>
      </div>
    </CopilotKit>
  );
}

import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { MastraAgent, getLocalAgent } from "@ag-ui/mastra";
import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import crypto from "node:crypto";
import { mastra } from "@/mastra";
// `withForwardedHeaders` binds inbound x-* headers (e.g. x-aimock-context)
// into an AsyncLocalStorage scope so the wrapped @ai-sdk/openai provider's
// fetch can re-attach them on outbound LLM calls. Required because the
// @ag-ui/mastra adapter does not forward inbound headers to Vercel AI SDK.
import { withForwardedHeaders } from "@/mastra/_header_forwarding";
// CVDIAG backend instrumentation (L1-E). No-op pass-through unless
// CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
import { withCvdiagBackend } from "@/cvdiag-backend";

// The V2 runtime has no service adapters: Mastra agents drive the LLM
// themselves and the runtime only brokers AG-UI events between the frontend
// and the agent. Under V1 this route passed `ExperimentalEmptyAdapter` to say
// exactly that; there is now no adapter to choose, so nothing to configure.

// The Mastra config registers a single local agent (`weatherAgent`), but the
// demo pages request a variety of agent names (`agentic_chat`,
// `human_in_the_loop`, etc.). Mirror the crewai-crews pattern and expose the
// same underlying agent under every name the demos ask for so the runtime can
// resolve them. `mastra-weatherAgent` is also preserved for backend smoke tests.
//
// NOTE: This aliasing makes demo pages load without agent-name 404s.
// Demos that depend on specific agent capabilities (HITL interrupts,
// streaming state, gen-ui steps) remain limited by weatherAgent's features.
// Full feature parity requires dedicated Mastra agents per demo — see
// crewai-crews for the precedent pattern.
//
// IMPORTANT: This is the single source of truth for demo agent names. Any new
// demo added under `src/app/demos/<name>/` that calls the CopilotKit runtime
// MUST be added here, otherwise the runtime will return agent-not-found errors.
// There is no central registry — this list IS the registry.
export const demoAgentNames = [
  "agentic_chat",
  "human_in_the_loop",
  "tool-rendering",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-write",
  "shared-state-read-write",
  "shared-state-streaming",
  "subagents",
  // Parity-with-langgraph-python demos — all currently map to the same
  // underlying weatherAgent. Each gets a unique resourceId so working-memory
  // buckets don't cross-contaminate. A future refactor can split these into
  // dedicated Mastra agents when per-demo behavior diverges from weatherAgent.
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "frontend_tools",
  "frontend-tools-async",
  "hitl-in-chat",
  "hitl-in-app",
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  // Reasoning cells. The demo pages request these agent names verbatim
  // (`agent="reasoning-default"` / `agent="reasoning-custom"`); they must be
  // registered here or the runtime returns agent-not-found and the chat never
  // starts (no reasoning stream renders). These are the agent-name equivalents
  // of the `reasoning-default-render` / `agentic-chat-reasoning` manifest
  // feature keys — see tests/vitest/demoAgentNames.parity.test.ts, which
  // enforces that every page `agent="…"` literal appears in this list.
  "reasoning-default",
  "reasoning-custom",
  "readonly-state-agent-context",
  "agent-config",
  "declarative-gen-ui",
  "a2ui-fixed-schema",
  "headless-complete",
  "tool-rendering-reasoning-chain",
  "gen-ui-interrupt",
  "interrupt-headless",
] as const;

// Per-demo override map: any demo alias listed here resolves to a dedicated
// Mastra agent instead of the shared weatherAgent. Add a mapping here when a
// demo needs its own system prompt / tool set (e.g. the headless-complete
// demo uses a prompt that routes weather/stock/highlight requests).
const demoAgentIdOverrides: Partial<Record<DemoAgentName, string>> = {
  "headless-complete": "headlessCompleteAgent",
  "shared-state-read-write": "sharedStateReadWriteAgent",
  "shared-state-streaming": "sharedStateStreamingAgent",
  "gen-ui-agent": "genUiAgent",
  subagents: "subagentsSupervisorAgent",
  "gen-ui-interrupt": "interruptAgent",
  "interrupt-headless": "interruptAgent",
  // Reasoning cells use a dedicated reasoning-capable agent (Responses API +
  // reasoning-summary streaming). Mapping them to the default weatherAgent
  // (gpt-4o) meant no reasoning items were ever emitted and the reasoning slot
  // stayed dark. See src/mastra/agents/index.ts (reasoningAgent).
  "reasoning-default": "reasoningAgent",
  "reasoning-custom": "reasoningAgent",
  // Reasoning + backend tool-rendering chain: dedicated agent registers the
  // four chain tools (weather/flights/stock/dice) under the fixture tool-call
  // names so Mastra executes each leg and the multi-turn chain reaches its
  // closing narration.
  "tool-rendering-reasoning-chain": "reasoningChainAgent",
  // Plain tool-rendering + its catch-all variants share one backend bound to
  // all four demo tools (get_weather, search_flights, get_stock_price,
  // roll_d20) — mirrors gold tool_rendering_agent.py. Without this they fell
  // back to weatherAgent, which lacks get_stock_price/roll_d20, so the Stock,
  // d20, and Chain pills emitted uncallable tool calls and rendered no card.
  "tool-rendering": "toolRenderingAgent",
  "tool-rendering-default-catchall": "toolRenderingAgent",
  "tool-rendering-custom-catchall": "toolRenderingAgent",
};

export type DemoAgentName = (typeof demoAgentNames)[number];

// Narrowed agent-map type. Keys are exactly the demo aliases plus
// `weatherAgent`; values are the non-null result of `getLocalAgent`. If
// someone drops `as const` on `demoAgentNames` or widens this type back to
// `Record<string, ...>`, the type-level test under tests/vitest/builtAgents.types.test.ts
// should break `tsc --noEmit`.
// Baseline local-agent keys Mastra registers under — these are the keys
// handed back from `MastraAgent.getLocalAgents({ mastra })`. Keep this
// narrowed alongside `mastra.agents` in `src/mastra/index.ts`; any agent
// added there must be added here too.
export type LocalMastraAgentName =
  | "weatherAgent"
  | "headlessCompleteAgent"
  | "sharedStateReadWriteAgent"
  | "sharedStateStreamingAgent"
  | "genUiAgent"
  | "subagentsSupervisorAgent"
  | "interruptAgent"
  | "multimodalAgent"
  | "mcpAppsAgent"
  | "byocHashbrownAgent";

export type BuiltAgents = Record<
  DemoAgentName | LocalMastraAgentName,
  NonNullable<ReturnType<typeof getLocalAgent>>
>;

// Baseline resourceId for weatherAgent. Kept as a named const so tests and
// future refactors don't have to hardcode the string.
const weatherResourceId = "mastra-weatherAgent";

// Exported for tests; production callers should use `getAgents()` below so the
// result is memoized across requests.
export function buildAgents(
  mastraInstance: typeof mastra = mastra,
): BuiltAgents {
  // Mastra Memory requires a non-empty resourceId whenever a threadId is
  // supplied (the CopilotKit runtime always supplies threadId). Passing an
  // empty string causes Mastra to throw AGENT_MEMORY_MISSING_RESOURCE_ID on
  // every chat turn, which breaks the agentic-chat and tool-rendering demos.
  //
  // Give each demo its own stable resourceId so working-memory buckets don't
  // cross-contaminate between demos. `mastra-weatherAgent` keeps a baseline id
  // for direct smoke-test traffic that hits the underlying agent name.
  // Dedicated per-local-agent resourceIds. `getLocalAgents` applies one
  // resourceId to every local agent, which would make headlessCompleteAgent
  // share weatherAgent's working-memory bucket. Rebind each local agent
  // under its own id via `getLocalAgent` (keyed by agentId) so the buckets
  // stay disjoint.
  const baseLocalAgents = MastraAgent.getLocalAgents({
    mastra: mastraInstance,
    resourceId: weatherResourceId,
  });
  if (!baseLocalAgents.weatherAgent) {
    throw new Error(
      "weatherAgent missing from Mastra config — required for demo aliases",
    );
  }
  if (!baseLocalAgents.headlessCompleteAgent) {
    throw new Error(
      "headlessCompleteAgent missing from Mastra config — required for headless-complete demo alias",
    );
  }
  if (!baseLocalAgents.sharedStateReadWriteAgent) {
    throw new Error(
      "sharedStateReadWriteAgent missing from Mastra config — required for shared-state-read-write demo alias",
    );
  }
  if (!baseLocalAgents.sharedStateStreamingAgent) {
    throw new Error(
      "sharedStateStreamingAgent missing from Mastra config — required for shared-state-streaming demo alias",
    );
  }
  if (!baseLocalAgents.genUiAgent) {
    throw new Error(
      "genUiAgent missing from Mastra config — required for gen-ui-agent demo alias",
    );
  }
  if (!baseLocalAgents.subagentsSupervisorAgent) {
    throw new Error(
      "subagentsSupervisorAgent missing from Mastra config — required for subagents demo alias",
    );
  }
  if (!baseLocalAgents.interruptAgent) {
    throw new Error(
      "interruptAgent missing from Mastra config — required for gen-ui-interrupt/interrupt-headless demos",
    );
  }
  if (!baseLocalAgents.multimodalAgent) {
    throw new Error(
      "multimodalAgent missing from Mastra config — required for /demos/multimodal",
    );
  }
  if (!baseLocalAgents.mcpAppsAgent) {
    throw new Error(
      "mcpAppsAgent missing from Mastra config — required for /demos/mcp-apps",
    );
  }
  if (!baseLocalAgents.byocHashbrownAgent) {
    throw new Error(
      "byocHashbrownAgent missing from Mastra config — required for /demos/byoc-hashbrown",
    );
  }
  const headlessCompleteAgentInstance = getLocalAgent({
    mastra: mastraInstance,
    agentId: "headlessCompleteAgent",
    resourceId: "mastra-headlessCompleteAgent",
  });
  if (!headlessCompleteAgentInstance) {
    throw new Error("getLocalAgent returned null for headlessCompleteAgent");
  }
  const sharedStateRWAgentInstance = getLocalAgent({
    mastra: mastraInstance,
    agentId: "sharedStateReadWriteAgent",
    resourceId: "mastra-sharedStateReadWriteAgent",
  });
  if (!sharedStateRWAgentInstance) {
    throw new Error(
      "getLocalAgent returned null for sharedStateReadWriteAgent",
    );
  }
  const sharedStateStreamingAgentInstance = getLocalAgent({
    mastra: mastraInstance,
    agentId: "sharedStateStreamingAgent",
    resourceId: "mastra-sharedStateStreamingAgent",
  });
  if (!sharedStateStreamingAgentInstance) {
    throw new Error(
      "getLocalAgent returned null for sharedStateStreamingAgent",
    );
  }
  const genUiAgentInstance = getLocalAgent({
    mastra: mastraInstance,
    agentId: "genUiAgent",
    resourceId: "mastra-genUiAgent",
  });
  if (!genUiAgentInstance) {
    throw new Error("getLocalAgent returned null for genUiAgent");
  }
  const subagentsSupervisorAgentInstance = getLocalAgent({
    mastra: mastraInstance,
    agentId: "subagentsSupervisorAgent",
    resourceId: "mastra-subagentsSupervisorAgent",
  });
  if (!subagentsSupervisorAgentInstance) {
    throw new Error("getLocalAgent returned null for subagentsSupervisorAgent");
  }
  const interruptAgentInstance = getLocalAgent({
    mastra: mastraInstance,
    agentId: "interruptAgent",
    resourceId: "mastra-interruptAgent",
  });
  if (!interruptAgentInstance) {
    throw new Error("getLocalAgent returned null for interruptAgent");
  }
  const multimodalAgentInstance = getLocalAgent({
    mastra: mastraInstance,
    agentId: "multimodalAgent",
    resourceId: "mastra-multimodalAgent",
  });
  if (!multimodalAgentInstance) {
    throw new Error("getLocalAgent returned null for multimodalAgent");
  }
  const mcpAppsAgentInstance = getLocalAgent({
    mastra: mastraInstance,
    agentId: "mcpAppsAgent",
    resourceId: "mastra-mcpAppsAgent",
  });
  if (!mcpAppsAgentInstance) {
    throw new Error("getLocalAgent returned null for mcpAppsAgent");
  }
  const byocHashbrownAgentInstance = getLocalAgent({
    mastra: mastraInstance,
    agentId: "byocHashbrownAgent",
    resourceId: "mastra-byocHashbrownAgent",
  });
  if (!byocHashbrownAgentInstance) {
    throw new Error("getLocalAgent returned null for byocHashbrownAgent");
  }
  const localAgents = {
    weatherAgent: baseLocalAgents.weatherAgent,
    headlessCompleteAgent: headlessCompleteAgentInstance,
    sharedStateReadWriteAgent: sharedStateRWAgentInstance,
    sharedStateStreamingAgent: sharedStateStreamingAgentInstance,
    genUiAgent: genUiAgentInstance,
    subagentsSupervisorAgent: subagentsSupervisorAgentInstance,
    interruptAgent: interruptAgentInstance,
    multimodalAgent: multimodalAgentInstance,
    mcpAppsAgent: mcpAppsAgentInstance,
    byocHashbrownAgent: byocHashbrownAgentInstance,
  };

  // Guard against silent shadowing: if Mastra ever registers a local agent
  // whose key collides with a demo alias, the spread order below would
  // silently overwrite it (or vice versa). Fail loudly instead. We check
  // both the curated `localAgents` map AND the full set of keys returned
  // by `MastraAgent.getLocalAgents` — the latter catches rogue agents we
  // don't know about yet (e.g. someone registers a new Mastra agent whose
  // name happens to match a demo alias).
  const knownLocalAgentKeys = new Set([
    ...Object.keys(localAgents),
    ...Object.keys(baseLocalAgents),
  ]);
  const collisions = demoAgentNames.filter((name) =>
    knownLocalAgentKeys.has(name),
  );
  if (collisions.length > 0) {
    throw new Error(
      `demoAgentNames collide with existing Mastra local agents: ${collisions.join(", ")}`,
    );
  }

  // Track every resourceId we hand out so we can fail loudly if two demos
  // accidentally share one (would cause cross-demo working-memory contamination).
  const resourceIdByAgent = new Map<string, string>();
  resourceIdByAgent.set("weatherAgent", weatherResourceId);
  // `getLocalAgents` above calls every local agent with the baseline
  // `weatherResourceId`. For the dedicated headless-complete agent we want
  // its own bucket so its working-memory doesn't collide with weatherAgent.
  // Re-bind it under a dedicated resourceId here (the lookup below resolves
  // via `getLocalAgent`, keyed by agentId).
  resourceIdByAgent.set(
    "headlessCompleteAgent",
    "mastra-headlessCompleteAgent",
  );
  resourceIdByAgent.set(
    "sharedStateReadWriteAgent",
    "mastra-sharedStateReadWriteAgent",
  );
  resourceIdByAgent.set(
    "sharedStateStreamingAgent",
    "mastra-sharedStateStreamingAgent",
  );
  resourceIdByAgent.set("genUiAgent", "mastra-genUiAgent");
  resourceIdByAgent.set(
    "subagentsSupervisorAgent",
    "mastra-subagentsSupervisorAgent",
  );
  resourceIdByAgent.set("interruptAgent", "mastra-interruptAgent");
  resourceIdByAgent.set("multimodalAgent", "mastra-multimodalAgent");
  resourceIdByAgent.set("mcpAppsAgent", "mastra-mcpAppsAgent");
  resourceIdByAgent.set("byocHashbrownAgent", "mastra-byocHashbrownAgent");

  const demoAliases: Record<
    string,
    NonNullable<ReturnType<typeof getLocalAgent>>
  > = {};
  for (const name of demoAgentNames) {
    const resourceId = `mastra-${name}`;
    const agentId = demoAgentIdOverrides[name] ?? "weatherAgent";
    const agent = getLocalAgent({
      mastra: mastraInstance,
      agentId,
      resourceId,
    });
    if (!agent) {
      throw new Error(
        `getLocalAgent returned null for ${name} (agentId="${agentId}")`,
      );
    }
    demoAliases[name] = agent;
    resourceIdByAgent.set(name, resourceId);
  }

  // Assert resourceId uniqueness across every agent we're about to expose.
  const seen = new Map<string, string>();
  for (const [agentName, resourceId] of resourceIdByAgent) {
    const existing = seen.get(resourceId);
    if (existing) {
      throw new Error(
        `duplicate resourceId "${resourceId}" shared by agents "${existing}" and "${agentName}"`,
      );
    }
    seen.set(resourceId, agentName);
  }

  // Belt-and-suspenders: we already threw above on any collision between
  // demo alias names and locally-registered Mastra agent names, so in
  // practice neither spread can clobber the other. We still spread
  // `localAgents` LAST as a defensive fallback — if the collision guard is
  // ever weakened in a future refactor, the real Mastra-registered agent
  // (here, `weatherAgent`) wins over any accidental demo-alias of the same
  // name. Removing either half of this (the collision check OR the spread
  // order) leaves us one edit away from a silent shadowing bug.
  return {
    ...demoAliases,
    ...localAgents,
  } as BuiltAgents;
}

// RUNTIME ASSUMPTION: This module assumes the Next.js App Router Node runtime
// (not Edge). `cachedAgents` is a module-scoped singleton; in Node the module
// is evaluated once per server process, so the cache lives for the lifetime
// of the process. Under Edge runtime the module could be re-evaluated per
// request in some deployments, defeating memoization — if we ever switch this
// route to `export const runtime = "edge"`, revisit this cache.
let cachedAgents: BuiltAgents | null = null;
function getAgents(): BuiltAgents {
  if (cachedAgents === null) {
    cachedAgents = buildAgents();
  }
  return cachedAgents;
}

// Test hook: reset memoized agents so unit tests can observe rebuilds.
export function __resetAgentsCacheForTests(): void {
  cachedAgents = null;
}

// Emit a structured error log with a correlation id. Extracted so every
// failure path uses an identical shape — operators grep for `errorId`
// regardless of where the failure occurred. Phases:
//   - "setup": everything that happens BEFORE headers flush. Covers agent
//     cache construction, runtime instantiation, and synchronous failures
//     inside `wrapStreamingResponse` (malformed Response from copilotHandler,
//     etc.) — all of which still allow us to return a 500 JSON envelope.
//   - "stream": mid-stream failures observed by the body wrapper AFTER
//     headers have been committed — we can no longer change the status, only
//     log.
// Returns the generated errorId so callers can include it in client-facing
// responses when appropriate.
function logRouteError(err: unknown, phase: "setup" | "stream"): string {
  const error = err instanceof Error ? err : new Error(String(err));
  const errorId = crypto.randomUUID();
  console.error(
    JSON.stringify({
      at: new Date().toISOString(),
      level: "error",
      phase,
      errorId,
      message: error.message,
      stack: error.stack,
    }),
  );
  return errorId;
}

// Wrap a streaming Response body with a TransformStream that forwards chunks
// verbatim but catches any error thrown by the upstream source AFTER headers
// have been flushed. Without this, a rejection inside copilotHandler's SSE
// loop escapes every try/catch and leaves the frontend with a mute aborted
// stream — no log, no errorId, no way to correlate.
//
// We cannot turn a half-flushed 200 into a 500 (headers are already out) but
// we CAN guarantee the failure is logged server-side with the same errorId
// shape as the pre-stream path. Operators grepping logs for the errorId
// pattern will find both classes of failure.
function wrapStreamingResponse(response: Response): Response {
  // Non-streaming (or empty) responses pass through untouched.
  if (!response.body) {
    return response;
  }

  const source = response.body;
  const monitored = new ReadableStream<Uint8Array>({
    async start(controller) {
      const reader = source.getReader();
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          controller.enqueue(value);
        }
        controller.close();
      } catch (err) {
        // The frontend will see an aborted stream regardless; our job is to
        // leave a server-side breadcrumb with a correlation id.
        logRouteError(err, "stream");
        try {
          controller.error(err);
        } catch {
          // controller already errored/closed — nothing more to do.
        }
      } finally {
        try {
          reader.releaseLock();
        } catch {
          // lock already released
        }
      }
    },
    cancel(reason) {
      return source.cancel(reason);
    },
  });

  return new Response(monitored, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  });
}

// Next.js App Router POST handler for CopilotKit runtime requests. Wraps the
// runtime's handler so three classes of failure are logged with a
// correlation id:
//   1. Synchronous construction errors (bad mastra config, missing
//      weatherAgent, etc.) — caught by the outer try/catch, 500 returned.
//   2. Synchronous wrap-time errors (e.g. malformed Response from
//      copilotHandler that makes `wrapStreamingResponse` itself throw) —
//      caught separately so we can cancel the upstream body before the 500
//      goes out. Without this cancel, the ReadableStream returned by
//      copilotHandler leaks (no consumer ever reads it).
//   3. Mid-stream errors (thrown after response headers have been flushed)
//      — caught inside the TransformStream in `wrapStreamingResponse`.
const copilotkitPost = async (req: NextRequest): Promise<Response> =>
  // Bind inbound x-* headers into ALS for the duration of this request so
  // the wrapped @ai-sdk/openai provider's fetch can attach them on every
  // outbound LLM call (e.g. x-aimock-context for aimock fixture matching).
  withForwardedHeaders(req, async () => {
    let response: Response | undefined;
    try {
      const runtime = new CopilotRuntime({
        agents: getAgents(),
      });

      const copilotHandler = createCopilotRuntimeHandler({
        runtime,
        basePath: "/api/copilotkit",
        mode: "single-route",
      });

      response = await copilotHandler(req);
    } catch (err) {
      const errorId = logRouteError(err, "setup");
      return NextResponse.json(
        { error: "internal runtime error", errorId },
        { status: 500 },
      );
    }

    try {
      return wrapStreamingResponse(response);
    } catch (err) {
      // `wrapStreamingResponse` threw synchronously (e.g. malformed
      // `response.headers`). The upstream ReadableStream has been produced
      // but nobody is going to consume it — cancel it explicitly to release
      // whatever resources the runtime holds open behind the body. Swallow
      // errors from cancel itself; we're already on the 500 path.
      try {
        await response.body?.cancel();
      } catch {
        // best-effort cleanup; the primary error is already being logged below
      }
      const errorId = logRouteError(err, "setup");
      return NextResponse.json(
        { error: "internal runtime error", errorId },
        { status: 500 },
      );
    }
  });

// Wrap with CVDIAG backend instrumentation (L1-E). No-op pass-through unless
// CVDIAG_BACKEND_EMITTER is set truthy (default OFF).
export const POST = withCvdiagBackend(copilotkitPost, {
  slug: "mastra",
  agentName: "weatherAgent",
  provider: "openai",
});

/* HALCYON — a warm-paper editorial theme for CopilotChat.
 *
 * The point of this demo is to show how far a single stylesheet can take
 * CopilotChat away from the default look without touching components or
 * slots. Every selector is namespaced under `.chat-css-demo-scope` so this
 * theme cannot leak into the rest of the showcase.
 *
 * Two layers do the work:
 *   1. v2 token overrides on `[data-copilotkit]` recolor every Tailwind
 *      utility (cpk:bg-muted, cpk:text-foreground, cpk:border, …) the
 *      runtime relies on — see @copilotkit/react-core/v2/styles.css.
 *   2. Targeted class rules on `.copilotKitChat`, `.copilotKitMessage*`,
 *      and `.copilotKitInput` add the editorial details: parchment grain,
 *      corner brackets, serif voice, mono dispatch, ember accents.
 *
 * Class-name reference:
 *   https://docs.copilotkit.ai/custom-look-and-feel/customize-built-in-ui-components
 */

@import url("https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Instrument+Serif:ital@0;1&family=Inter+Tight:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap");

/* HALCYON palette — a private library at golden hour. The whole theme is
 * one warm parchment hue, one warm ink, and a deep copper ember used
 * sparingly so it actually reads as a signal. */
.chat-css-demo-scope {
  --halcyon-paper: #f4efe6;
  --halcyon-paper-soft: #ece6d9;
  --halcyon-paper-elevated: #fbf8f2;
  --halcyon-card: #ffffff;
  --halcyon-rule: #d6cfbe;
  --halcyon-rule-strong: #aea48a;
  --halcyon-ink: #1a1714;
  --halcyon-ink-soft: #3d362e;
  --halcyon-ink-mute: #7a7468;
  --halcyon-ember: #c44a1f;
  --halcyon-ember-bright: #e45f2b;
  --halcyon-ember-soft: #f3d7c5;
  --halcyon-champagne: #98794a;

  --halcyon-display:
    "Instrument Serif", ui-serif, "Iowan Old Style", Georgia, serif;
  --halcyon-serif:
    "Fraunces", "Source Serif Pro", ui-serif, Georgia, "Times New Roman", serif;
  --halcyon-sans:
    "Inter Tight", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  --halcyon-mono:
    "JetBrains Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --halcyon-shadow-soft:
    0 1px 0 rgba(26, 23, 20, 0.04), 0 12px 32px -18px rgba(26, 23, 20, 0.18);
  --halcyon-shadow-ember:
    0 1px 0 rgba(196, 74, 31, 0.18), 0 14px 36px -16px rgba(196, 74, 31, 0.42);
}

/* CopilotKit v2 reads these on the [data-copilotkit] root inside the chat.
 * Re-pointing them under our scope retints every Tailwind utility the
 * runtime renders (user message bubble, prose, borders, focus rings, …)
 * without us having to touch any individual class. */
.chat-css-demo-scope [data-copilotkit] {
  --background: var(--halcyon-paper);
  --foreground: var(--halcyon-ink);
  --card: var(--halcyon-card);
  --card-foreground: var(--halcyon-ink);
  --popover: var(--halcyon-paper-elevated);
  --popover-foreground: var(--halcyon-ink);
  --primary: var(--halcyon-ember);
  --primary-foreground: var(--halcyon-paper-elevated);
  --secondary: var(--halcyon-paper-soft);
  --secondary-foreground: var(--halcyon-ink);
  --muted: var(--halcyon-paper-soft);
  --muted-foreground: var(--halcyon-ink-mute);
  --accent: var(--halcyon-ember-soft);
  --accent-foreground: var(--halcyon-ember);
  --destructive: #b3361b;
  --destructive-foreground: var(--halcyon-paper-elevated);
  --border: var(--halcyon-rule);
  --input: var(--halcyon-rule);
  --ring: var(--halcyon-ember);
  --radius: 0px;
}

/* The chat surface — warm parchment with a single ambient ember glow,
 * a barely-perceptible paper grain via inline SVG noise, and architectural
 * corner brackets. Sharp 90° corners are deliberate; the default look is
 * rounded, so squaring everything off is the fastest visual signal that
 * "this is a different brand". */
.chat-css-demo-scope .copilotKitChat {
  font-family: var(--halcyon-sans);
  color: var(--halcyon-ink);
  background-color: var(--halcyon-paper);
  background-image:
    radial-gradient(
      900px 460px at 0% -10%,
      rgba(228, 95, 43, 0.14),
      transparent 62%
    ),
    radial-gradient(
      720px 380px at 100% 110%,
      rgba(152, 121, 74, 0.08),
      transparent 65%
    ),
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160' viewBox='0 0 160 160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.10 0 0 0 0 0.09 0 0 0 0 0.07 0 0 0 0.045 0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
  border: 1px solid var(--halcyon-rule);
  border-radius: 0;
  box-shadow: var(--halcyon-shadow-soft);
  position: relative;
  overflow: hidden;
}

/* The masthead label — a small mono bar pinned to the top of the surface,
 * playing against the editorial serif voice. Lives on ::before so it
 * tracks the chat root and shows in every state (welcome, mid-thread,
 * empty after clear). */
.chat-css-demo-scope .copilotKitChat::before {
  content: "CopilotChat  ·  Customized with CSS";
  position: absolute;
  top: 18px;
  left: 0;
  right: 0;
  text-align: center;
  font-family: var(--halcyon-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--halcyon-ink-mute);
  white-space: nowrap;
  pointer-events: none;
  z-index: 3;
}


/* The welcome screen — the page-one impression. The default heading is
 * sans-serif and tidy; we replace it with a large italic display serif
 * that wraps the question like a magazine cover line. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] {
  padding-top: 4rem;
}

.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1 {
  font-family: var(--halcyon-display);
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 400;
  font-style: italic;
  color: var(--halcyon-ink);
  letter-spacing: -0.02em;
  line-height: 1.05;
  text-align: center;
  margin: 0 auto 0.6rem;
  max-width: 22ch;
  position: relative;
}

/* A small mono eyebrow above the heading. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::before {
  content: "CopilotKit";
  display: block;
  font-family: var(--halcyon-mono);
  font-size: 11px;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: var(--halcyon-ember);
  margin-bottom: 1.2rem;
}

/* A short rule under the heading as a visual settle point. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::after {
  content: "";
  display: block;
  width: 36px;
  height: 1px;
  background: var(--halcyon-rule-strong);
  margin: 1.4rem auto 0;
}

.chat-css-demo-scope .copilotKitMessages {
  font-family: var(--halcyon-sans);
  background: transparent;
  color: var(--halcyon-ink);
  padding: 5rem 0 2rem;
  line-height: 1.6;
}

/* User message — a "transmission" in JetBrains Mono on a paper card. The
 * outer wrapper is the right-aligning flex column; we leave it transparent
 * and style the inner bubble (which uses cpk:bg-muted, hence we also
 * target the substring class as a stable hook). */
.chat-css-demo-scope .copilotKitMessage.copilotKitUserMessage {
  background: transparent;
  padding: 0;
  border: none;
  box-shadow: none;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitUserMessage
  > [class*="bg-muted"] {
  font-family: var(--halcyon-mono);
  font-size: 0.875rem;
  font-weight: 400;
  color: var(--halcyon-ink);
  background: var(--halcyon-paper-elevated);
  border: 1px solid var(--halcyon-rule);
  border-left: 2px solid var(--halcyon-ember);
  border-radius: 0;
  padding: 12px 16px 12px 18px;
  letter-spacing: -0.005em;
  line-height: 1.55;
  box-shadow: 0 1px 0 rgba(26, 23, 20, 0.03);
  position: relative;
}

/* A mono "→" marker before the user's text to read like a CLI prompt. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitUserMessage
  > [class*="bg-muted"]::before {
  content: "→";
  display: inline-block;
  margin-right: 10px;
  color: var(--halcyon-ember);
  font-weight: 500;
}

/* Assistant message — editorial Fraunces serif, no bubble, just generous
 * paragraphs offset by a thin ember rule on the left. Reads like the
 * voice of a publication, not a chatbot. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage {
  background: transparent;
  color: var(--halcyon-ink);
  font-family: var(--halcyon-serif);
  font-size: 1.0625rem;
  font-weight: 400;
  padding: 4px 0 4px 22px;
  border: none;
  border-radius: 0;
  margin-right: auto;
  margin-bottom: 1.25rem;
  max-width: 78ch;
  position: relative;
}

/* The editorial left rule. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage::before {
  content: "";
  position: absolute;
  top: 0.45em;
  bottom: 0.45em;
  left: 0;
  width: 1px;
  background: var(--halcyon-ember);
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose,
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose p {
  font-family: var(--halcyon-serif);
  font-size: inherit;
  color: inherit;
  line-height: 1.7;
  font-feature-settings: "ss01", "ss02", "ss03", "kern";
  margin: 0 0 0.85em;
}

/* Headings inside assistant content swap to the display serif so a long
 * answer reads like a structured article. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  :is(h1, h2, h3, h4) {
  font-family: var(--halcyon-display);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -0.015em;
  color: var(--halcyon-ink);
  margin: 1em 0 0.4em;
  line-height: 1.15;
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h1 {
  font-size: 2rem;
}
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h2 {
  font-size: 1.55rem;
}
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h3 {
  font-size: 1.25rem;
}

/* Lists — looser, with serif numerals. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  :is(ul, ol) {
  margin: 0.5em 0 1em;
  padding-left: 1.4em;
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose li {
  margin: 0.25em 0;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  ol
  > li::marker {
  color: var(--halcyon-ember);
  font-feature-settings: "tnum";
  font-weight: 500;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  ul
  > li::marker {
  color: var(--halcyon-ember);
}

/* Blockquote — pull-quote treatment in italic display serif. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  blockquote {
  border-left: 0;
  margin: 1.2em 0;
  padding: 0 0 0 1em;
  font-family: var(--halcyon-display);
  font-style: italic;
  font-size: 1.25em;
  color: var(--halcyon-ink-soft);
  position: relative;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  blockquote::before {
  content: "“";
  position: absolute;
  left: -0.05em;
  top: -0.4em;
  font-size: 2.4em;
  color: var(--halcyon-ember);
  line-height: 1;
}

/* Inline code — small ember chip on a tinted card. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose code {
  font-family: var(--halcyon-mono);
  font-size: 0.86em;
  font-weight: 500;
  color: var(--halcyon-ember);
  background: var(--halcyon-ember-soft);
  border: 1px solid color-mix(in srgb, var(--halcyon-ember) 22%, transparent);
  border-radius: 0;
  padding: 1px 6px;
}

/* Code block — dark ink card flipped against the parchment. The contrast
 * is deliberate; it reads like a code excerpt set in a printed book. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose pre,
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  div[data-streamdown="code-block"]
  > pre {
  background: var(--halcyon-ink) !important;
  color: #e8e2d5;
  border: 1px solid var(--halcyon-ink);
  border-radius: 0;
  padding: 14px 16px;
  margin: 1em 0;
  font-family: var(--halcyon-mono);
  font-size: 0.86em;
  line-height: 1.55;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    var(--halcyon-shadow-soft);
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  pre
  code {
  background: transparent;
  color: inherit;
  border: none;
  padding: 0;
}

/* Anchor links — ember underline in classic editorial style. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose a {
  color: var(--halcyon-ember);
  text-decoration-line: underline;
  text-decoration-color: color-mix(
    in srgb,
    var(--halcyon-ember) 35%,
    transparent
  );
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: text-decoration-color 160ms ease;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  a:hover {
  text-decoration-color: var(--halcyon-ember);
}

/* Horizontal rule — short, centered, ornament-like. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose hr {
  border: none;
  height: 1px;
  background: var(--halcyon-rule);
  width: 64px;
  margin: 1.6em auto;
}

/* Composer — a sharp paper card with an ember focus rule. The default
 * pill is rounded; squaring it off is again the visual cue that this is
 * a different brand. The wrapper around .copilotKitInput uses a fixed
 * white background in v2, so we override it directly. */
.chat-css-demo-scope .copilotKitInput {
  font-family: var(--halcyon-sans) !important;
  background: var(--halcyon-card) !important;
  border: 1px solid var(--halcyon-rule);
  border-radius: 0 !important;
  padding: 14px 16px;
  min-height: 56px;
  box-shadow:
    0 1px 0 rgba(26, 23, 20, 0.03),
    0 8px 24px -16px rgba(26, 23, 20, 0.18);
  transition:
    border-color 200ms ease,
    box-shadow 200ms ease,
    transform 120ms ease;
}

.chat-css-demo-scope .copilotKitInput:focus-within {
  border-color: var(--halcyon-ember);
  box-shadow:
    0 0 0 3px rgba(196, 74, 31, 0.12),
    0 1px 0 rgba(196, 74, 31, 0.18),
    0 14px 36px -16px rgba(196, 74, 31, 0.22);
  transform: translateY(-1px);
}

.chat-css-demo-scope .copilotKitInput textarea {
  font-family: var(--halcyon-sans) !important;
  font-size: 1rem;
  font-weight: 400;
  color: var(--halcyon-ink);
  line-height: 1.55;
  letter-spacing: -0.005em;
}

.chat-css-demo-scope .copilotKitInput textarea::placeholder {
  color: var(--halcyon-ink-mute);
  font-style: italic;
  opacity: 1;
}

/* The send button — a square ember chit, not the default circular pill.
 * v2 ships this as `<Button variant="chatInputToolbarPrimary"
 * size="chatInputToolbarIcon" data-testid="copilot-send-button">`, which
 * compiles to `cpk:bg-black cpk:text-white cpk:rounded-full cpk:h-9
 * cpk:w-9`. We override every one of those tokens so the brand wins. */
.chat-css-demo-scope button[data-testid="copilot-send-button"] {
  background-color: var(--halcyon-ember) !important;
  color: var(--halcyon-paper-elevated) !important;
  border: 1px solid var(--halcyon-ember) !important;
  border-radius: 2px !important;
  height: 36px !important;
  width: 36px !important;
  box-shadow: var(--halcyon-shadow-ember);
  transition:
    transform 150ms ease,
    box-shadow 150ms ease,
    background-color 150ms ease;
}

.chat-css-demo-scope button[data-testid="copilot-send-button"]:hover {
  background-color: var(--halcyon-ember-bright) !important;
  transform: translateY(-1px);
}

.chat-css-demo-scope button[data-testid="copilot-send-button"]:disabled {
  background-color: var(--halcyon-paper-soft) !important;
  color: var(--halcyon-ink-mute) !important;
  border-color: var(--halcyon-rule) !important;
  box-shadow: none;
  transform: none;
  opacity: 1 !important;
}

.chat-css-demo-scope button[data-testid="copilot-send-button"] svg {
  color: inherit;
}

/* Secondary input chrome (add-menu plus, mic, transcribe) — ghost squares
 * with an ember tint on hover. v2's `chatInputToolbarSecondary` variant
 * uses transparent bg + #444 text, which we re-tint to match the brand. */
.chat-css-demo-scope
  .copilotKitInput
  button:not([data-testid="copilot-send-button"]) {
  border-radius: 2px !important;
  color: var(--halcyon-ink-soft) !important;
  transition:
    color 150ms ease,
    background-color 150ms ease;
}

.chat-css-demo-scope
  .copilotKitInput
  button:not([data-testid="copilot-send-button"]):hover {
  color: var(--halcyon-ember) !important;
  background-color: var(--halcyon-ember-soft) !important;
}

/* Suggestion pills — sharp outlined chips, not rounded balloons. The
 * inner suggestion text uses the editorial mono so it reads like a
 * curated set of dispatch options. */
.chat-css-demo-scope [class*="copilotKitSuggestion"] {
  background: transparent;
  color: var(--halcyon-ink-soft);
  border: 1px solid var(--halcyon-rule);
  border-radius: 0;
  padding: 8px 14px;
  font-family: var(--halcyon-mono);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  transition:
    color 150ms ease,
    border-color 150ms ease,
    background 150ms ease,
    transform 150ms ease;
}

.chat-css-demo-scope [class*="copilotKitSuggestion"]:hover {
  color: var(--halcyon-ember);
  border-color: var(--halcyon-ember);
  background: var(--halcyon-ember-soft);
  transform: translateY(-1px);
}

.chat-css-demo-scope [data-copilotkit] ::-webkit-scrollbar {
  width: 4px;
}

.chat-css-demo-scope [data-copilotkit] ::-webkit-scrollbar-thumb {
  background: var(--halcyon-rule-strong);
  border-radius: 0;
}

.chat-css-demo-scope [data-copilotkit] ::-webkit-scrollbar-thumb:hover {
  background: var(--halcyon-ember);
}

.chat-css-demo-scope [data-copilotkit] * {
  scrollbar-width: thin;
  scrollbar-color: var(--halcyon-rule-strong) transparent;
}

.chat-css-demo-scope ::selection {
  background: var(--halcyon-ember-soft);
  color: var(--halcyon-ember);
}

/* A single, restrained entrance for the welcome screen — staggered fade-up
 * on the eyebrow / heading / rule. No infinite loops, no bouncy easing. */
@keyframes halcyon-rise {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1 {
  animation: halcyon-rise 700ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::before {
  animation: halcyon-rise 600ms cubic-bezier(0.2, 0.7, 0.2, 1) 80ms both;
}

@media (prefers-reduced-motion: reduce) {
  .chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1,
  .chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::before {
    animation: none;
  }
}

