"use client";

/**
 * A2UI Error Recovery demo (Mastra, OSS-422).
 *
 * Same dynamic-schema A2UI setup as declarative-gen-ui (it reuses that demo's
 * catalog), but it makes the toolkit's validate->retry recovery loop visible.
 * The dedicated runtime at `/api/copilotkit-a2ui-recovery` is configured with
 * `a2ui.injectA2UITool: false` — the backend agent (`a2uiRecoveryAgent`) owns
 * `generate_a2ui` via `getA2UITools`, whose body runs the forced `render_a2ui`
 * sub-agent and the recovery loop + recovery-exhausted hard-fail envelope
 * (OSS-413 feature; mirrors langgraph-python + strands recovery cells).
 *
 * The two suggestion pills drive aimock fixtures that force:
 *   - HEAL: an invalid first render that recovers to a valid one
 *     (building -> retrying -> painted).
 *   - EXHAUST: an always-invalid render that hits the attempt cap
 *     (a tasteful `failed` state, never a broken surface).
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";

// Reuse the declarative-gen-ui catalog (same components, same catalogId).
import { myCatalog } from "../declarative-gen-ui/a2ui/catalog";
import { Chat } from "./chat";

export default function A2uiRecoveryDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-a2ui-recovery"
      agent="a2ui-recovery"
      a2ui={{ catalog: myCatalog }}
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

// Dedicated runtime for the A2UI Error Recovery cell (Mastra, OSS-422).
//
// Scoped so the a2ui options for this cell stay isolated from the shared
// `/api/copilotkit` route. The backend `a2uiRecoveryAgent` OWNS `generate_a2ui`
// via getA2UITools (which runs the forced render_a2ui subagent + the toolkit
// validate->retry recovery loop + the recovery-exhausted hard-fail), so the
// runtime must NOT inject a second copy — hence `a2ui.injectA2UITool: false`.
// Mirrors the langgraph-python / strands recovery routes.

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { getLocalAgent } from "@ag-ui/mastra";
import { mastra } from "@/mastra";
import { withForwardedHeaders } from "@/mastra/_header_forwarding";

const recoveryAgent = getLocalAgent({
  mastra,
  agentId: "a2uiRecoveryAgent",
  resourceId: "mastra-a2uiRecoveryAgent",
});

if (!recoveryAgent) {
  throw new Error(
    "getLocalAgent returned null for a2uiRecoveryAgent — required for /demos/a2ui-recovery",
  );
}

const runtime = new CopilotRuntime({
  // @ts-ignore -- see main route.ts (published agents type wraps Record)
  agents: {
    "a2ui-recovery": recoveryAgent,
    default: recoveryAgent,
  },
  a2ui: {
    // a2uiRecoveryAgent already owns `generate_a2ui` (getA2UITools) — don't
    // let the runtime double-inject it.
    injectA2UITool: false,
    // The page registers the declarative-gen-ui catalog; pin it so the render
    // subagent grounds against the same components (and doesn't fall back to
    // the basic spec catalog).
    defaultCatalogId: "declarative-gen-ui-catalog",
  },
});

export const POST = async (req: NextRequest) =>
  withForwardedHeaders(req, async () => {
    try {
      const copilotHandler = createCopilotRuntimeHandler({
        runtime,
        basePath: "/api/copilotkit-a2ui-recovery",
        mode: "single-route",
      });
      return await copilotHandler(req);
    } catch (error: unknown) {
      const e = error as { message?: string; stack?: string };
      return NextResponse.json(
        { error: e.message, stack: e.stack },
        { status: 500 },
      );
    }
  });

"use client";

import { CopilotChat } from "@copilotkit/react-core/v2";
import { useA2uiRecoverySuggestions } from "./suggestions";

export function Chat() {
  useA2uiRecoverySuggestions();
  return <CopilotChat agentId="a2ui-recovery" className="h-full rounded-2xl" />;
}

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

// Two pills exercise the recovery loop deterministically via aimock fixtures
// (showcase/aimock/d6/mastra/a2ui-recovery.json). Prompts are UNIQUE within the
// mastra context AND across frameworks (no substring overlap) so the context-less
// inner render_a2ui fixtures don't collide with google-adk's (load-order-first
// match — see the A2UI recovery memory).
//   - "heal":    inner render_a2ui attempt 1 is structurally invalid ->
//                validate->retry -> attempt 2 valid -> painted.
//   - "exhaust": inner render_a2ui invalid on every attempt -> attempt cap hit
//                -> a2ui_recovery_exhausted -> tasteful `failed` state.
export function useA2uiRecoverySuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Recover a bad render",
        message:
          "Draft the Vantage quarterly revenue tile and mend a botched opening attempt.",
      },
      {
        title: "Show an unrecoverable failure",
        message:
          "Draft a Vantage board that flunks every validation sweep so I can preview the fallback.",
      },
    ],
    available: "always",
  });
}

