export function ActivityWrapper({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex w-full justify-start">
      <div className="w-full max-w-full overflow-hidden rounded-2xl border bg-card shadow-sm">
        {children}
      </div>
    </div>
