export const toolRenderingAgent = new Agent({
  id: "tool-rendering-agent",
  name: "Tool Rendering Agent",
  tools: {
    get_weather: weatherTool,
    search_flights: searchFlightsTool,
    get_stock_price: stockPriceTool,
    roll_d20: rollD20Tool,
