"use client";

/**
 * MCP Apps demo.
 *
 * MCP Apps are MCP servers that expose tools with associated UI resources.
 * The CopilotKit runtime is wired with `mcpApps: { servers: [...] }`
 * (see `src/app/api/copilotkit-mcp-apps/route.ts`), which auto-applies the
 * MCP Apps middleware. When the agent calls an MCP tool, the middleware
 * fetches the associated UI resource and emits an activity event; the
 * built-in `MCPAppsActivityRenderer` registered by `CopilotKitProvider`
 * renders the sandboxed iframe inline in the chat — no app-side renderer
 * registration required.
 *
 * This cell points at the public Excalidraw MCP app (https://mcp.excalidraw.com).
 *
 * Reference:
 * https://docs.copilotkit.ai/integrations/langgraph/generative-ui/mcp-apps
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";
import { Chat } from "./chat";

export default function MCPAppsDemo() {
  // No `renderActivityMessages`, no `useRenderActivityMessage` — the
  // CopilotKitProvider auto-registers the built-in `MCPAppsActivityRenderer`
  // for the "mcp-apps" activity type. A plain <CopilotChat /> is enough.
  return (
    <CopilotKit runtimeUrl="/api/copilotkit-mcp-apps" agent="mcp-apps">
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

// CopilotKit runtime for the MCP Apps cell.
//
// The runtime's `mcpApps` config auto-applies the MCP Apps middleware to the
// agent: when the agent calls a tool backed by an MCP UI resource, the
// middleware fetches the resource and emits the activity event that the
// built-in `MCPAppsActivityRenderer` (registered by CopilotKit internally)
// renders in the chat as a sandboxed iframe.

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { getLocalAgent } from "@ag-ui/mastra";
import { mastra } from "@/mastra";
import { withForwardedHeaders } from "@/mastra/_header_forwarding";

const mcpAppsAgent = getLocalAgent({
  mastra,
  agentId: "mcpAppsAgent",
  resourceId: "mastra-mcp-apps",
});
if (!mcpAppsAgent) {
  throw new Error("getLocalAgent returned null for mcpAppsAgent");
}

// headless-complete shares this runtime (its page wires
// runtimeUrl="/api/copilotkit-mcp-apps") but is backed by the dedicated
// headlessCompleteAgent — the same Mastra agent + resourceId the main
// route registers it against.
const headlessCompleteAgent = getLocalAgent({
  mastra,
  agentId: "headlessCompleteAgent",
  resourceId: "mastra-headlessCompleteAgent",
});
if (!headlessCompleteAgent) {
  throw new Error("getLocalAgent returned null for headlessCompleteAgent");
}

// The `mcpApps.servers` config is all you need server-side. The runtime
// auto-applies the MCP Apps middleware to every registered agent: on each
// MCP tool call it fetches the associated UI resource and emits an
// `activity` event that the built-in `MCPAppsActivityRenderer` renders
// inline in the chat.
const runtime = new CopilotRuntime({
  // @ts-ignore -- see main route.ts; published CopilotRuntime's `agents`
  // type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects
  // plain Records. Fixed in source, pending release.
  agents: {
    "headless-complete": headlessCompleteAgent,
    "mcp-apps": mcpAppsAgent,
    default: mcpAppsAgent,
  },
  mcpApps: {
    servers: [
      {
        type: "http",
        url: process.env.MCP_SERVER_URL || "https://mcp.excalidraw.com",
        // Always pin a stable `serverId`. Without it CopilotKit hashes the
        // URL, and a URL change silently breaks restoration of persisted
        // MCP Apps in prior conversation threads.
        serverId: "excalidraw",
      },
    ],
  },
});

export const POST = async (req: NextRequest) =>
  withForwardedHeaders(req, async () => {
    try {
      const copilotHandler = createCopilotRuntimeHandler({
        runtime,
        basePath: "/api/copilotkit-mcp-apps",
        mode: "single-route",
      });
      return await copilotHandler(req);
    } catch (error: unknown) {
      const e = error as { message?: string; stack?: string };
      return NextResponse.json(
        { error: e.message, stack: e.stack },
        { status: 500 },
      );
    }
  });

"use client";

import { CopilotChat } from "@copilotkit/react-core/v2";
import { useMcpAppsSuggestions } from "./suggestions";

export function Chat() {
  useMcpAppsSuggestions();
  return <CopilotChat agentId="mcp-apps" className="h-full rounded-2xl" />;
}

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export function useMcpAppsSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Draw a flowchart",
        message: "Use Excalidraw to draw a simple flowchart with three steps.",
      },
      {
        title: "Sketch a system diagram",
        message:
          "Open Excalidraw and sketch a system diagram with a client, server, and database.",
      },
    ],
    available: "always",
  });
}

// Header-forwarding shim: the ag-ui/mastra adapter does not propagate
// inbound x-* headers (e.g. x-aimock-context) to the Vercel AI SDK provider.
// `@/mastra/_header_forwarding` re-exports `openai` with a fetch wrapper
// that merges ALS-bound headers into every outbound LLM call. The
// CopilotKit route is responsible for binding the per-request snapshot via
// `withForwardedHeaders(req, () => handleRequest(req))`.
import { openai } from "@/mastra/_header_forwarding";
import { Agent } from "@mastra/core/agent";
import { stepCountIs } from "ai";
import {
  weatherTool,
  stockPriceTool,
  revenueChartTool,
  queryDataTool,
  manageTodosTool,
  getTodosTool,
  scheduleMeetingTool,
  scheduleMeetingInterruptTool,
  searchFlightsTool,
  searchFlightsA2uiTool,
  rollDiceTool,
  rollD20Tool,
  generateA2uiTool,
  setNotesTool,
  setStepsTool,
  researchAgentTool,
  writingAgentTool,
  critiqueAgentTool,
  browseWebTool,
  runDeepResearchTool,
} from "@/mastra/tools";
import { LibSQLStore } from "@mastra/libsql";
import { z } from "zod";
import { Memory } from "@mastra/memory";
import type { RequestContext } from "@mastra/core/request-context";
// Backend-owned A2UI with the toolkit validate->retry recovery loop (OSS-422).
// `@ag-ui/mastra/a2ui` is a bridge-free subpath (avoids the Mastra bundler vs
// @ag-ui/client→uuid clash); mirrors langgraph's get_a2ui_tools.
import { getA2UITools } from "@ag-ui/mastra/a2ui";

export const AgentState = z.object({
  proverbs: z.array(z.string()).default([]),
  // Beautiful Chat's app-mode todo canvas reads `agent.state.todos`. The
  // `manage_todos` tool writes the list into working memory (see
  // writeTodosToWorkingMemory), which the bridge surfaces as a STATE_SNAPSHOT —
  // so the slice MUST be declared here or the write has nowhere to land and the
  // panel stays on "No todos yet" (OSS-452). Shape mirrors langgraph-python's
  // Todo (beautiful_chat.py) and the shared frontend's Todo interface.
  // Optional/defaulted so every other weatherAgent-backed demo is unaffected.
  todos: z
    .array(
      z.object({
        id: z.string(),
        title: z.string(),
        description: z.string(),
        emoji: z.string(),
        status: z.enum(["pending", "completed"]),
      }),
    )
    .default([]),
});

/**
 * Persistent SQLite URL for working-memory storage.
 *
 * Why not `file::memory:`: an in-memory store resets on every process
 * restart. For demos that surface user state to the UI (notes panel, agent
 * delegations, preferences), that is silent data loss — the user adds notes,
 * the dev hits save, Next.js HMR restarts the server, and the notes vanish
 * with no error.
 *
 * Tests can override via `MASTRA_WORKING_MEMORY_URL=file::memory:` to keep
 * fixture isolation. The default is a relative file path so the DB lives
 * next to the package and survives reloads.
 */
export const WORKING_MEMORY_DB_URL =
  process.env.MASTRA_WORKING_MEMORY_URL ?? "file:./mastra-memory.db";

/**
 * Shared-state schema for the Shared State (Read + Write) demo.
 *
 * - `preferences` is WRITTEN by the UI via `agent.setState({ preferences })`.
 *   The AG-UI Mastra adapter merges `input.state` into the thread's
 *   `workingMemory` metadata before each run, so the LLM sees the latest UI
 *   preferences as part of working memory on every turn.
 * - `notes` is WRITTEN by the agent (via the `set_notes` tool) and READ by
 *   the UI via `useAgent({ updates: [OnStateChanged] })`. Mastra emits a
 *   `STATE_SNAPSHOT` after each run with the working-memory contents.
 */
export const SharedStateRWAgentState = z.object({
  preferences: z
    .object({
      name: z.string().default(""),
      tone: z.enum(["formal", "casual", "playful"]).default("casual"),
      language: z.string().default("English"),
      interests: z.array(z.string()).default([]),
    })
    .default({
      name: "",
      tone: "casual",
      language: "English",
      interests: [],
    }),
  notes: z.array(z.string()).default([]),
});

/**
 * Shared-state schema for the Sub-Agents demo.
 *
 * `delegations` is appended to by the supervisor as it fans out work to the
 * research / writing / critique sub-agents. The UI subscribes via
 * `useAgent({ updates: [OnStateChanged] })` and renders a live delegation
 * log.
 */
export const SubagentsAgentState = z.object({
  delegations: z
    .array(
      z.object({
        id: z.string(),
        sub_agent: z.enum([
          "research_agent",
          "writing_agent",
          "critique_agent",
        ]),
        task: z.string(),
        status: z.enum(["running", "completed", "failed"]),
        result: z.string(),
      }),
    )
    .default([]),
});

/**
 * Shared-state schema for the Gen UI Agent demo.
 *
 * `steps` is WRITTEN by the agent (via the `set_steps` tool) and READ by
 * the UI via `useAgent({ updates: [OnStateChanged] })`. Mastra includes
 * the `steps` field in its working-memory schema, so after each run-cycle
 * the AG-UI adapter emits a `STATE_SNAPSHOT` and the UI re-renders the
 * progress card.
 *
 * Status transitions: pending -> in_progress -> completed.
 */
export const GenUiAgentState = z.object({
  steps: z
    .array(
      z.object({
        id: z.string(),
        title: z.string(),
        status: z.enum(["pending", "in_progress", "completed"]),
      }),
    )
    .default([]),
});

/**
 * Shared-state schema for the Shared State (Streaming) demo.
 *
 * `document` is streamed token-by-token into shared state as the agent
 * writes. Mastra parity for the LangGraph `StateStreamingMiddleware` /
 * predictive-state pattern: instead of a `write_document` tool whose arg is
 * forwarded per-token, this agent calls Mastra's built-in
 * `updateWorkingMemory` tool with the growing document. The AG-UI Mastra
 * adapter intercepts that tool call's STREAMING args (OSS-414) and emits a
 * leading `STATE_SNAPSHOT` followed by incremental `STATE_DELTA`s on the
 * `document` key, so `useAgent({ updates:[OnStateChanged] })` sees
 * `state.document` grow live.
 */
export const SharedStateStreamingAgentState = z.object({
  document: z.string().default(""),
});

export const weatherAgent = new Agent({
  id: "weather-agent",
  name: "Weather Agent",
  tools: {
    get_weather: weatherTool,
    query_data: queryDataTool,
    manage_todos: manageTodosTool,
    get_todos: getTodosTool,
    schedule_meeting: scheduleMeetingTool,
    search_flights: searchFlightsTool,
    generate_a2ui: generateA2uiTool,
  },
  model: openai("gpt-5-mini"),
  instructions: "You are a helpful assistant.",
  memory: new Memory({
    storage: new LibSQLStore({
      id: "weather-agent-memory",
      url: WORKING_MEMORY_DB_URL,
    }),
    options: {
      workingMemory: {
        enabled: true,
        schema: AgentState,
      },
    },
  }),
});

