"use client";

/**
 * Background Agents demo.
 *
 * Mastra natively supports background tasks. The `background-agents` agent
 * wires a `run_deep_research` tool flagged `background: { enabled: true }`.
 * When the agent calls it, Mastra dispatches the work to its
 * BackgroundTaskManager instead of running it inline, and MastraAgent surfaces
 * that as an AG-UI activity event (activity type `mastra-background-task`)
 * rather than a normal tool pill. The Copilot Runtime forwards the activity to
 * the client, where the `backgroundTaskActivityRenderer` registered below via
 * `renderActivityMessages` paints a live "working" card.
 *
 * The standard `<CopilotChat />` renders activity messages inline in the
 * transcript using the registered renderer — no custom message list needed.
 *
 * Terminal-state note: on the dispatching turn Mastra delivers the task's
 * `started` lifecycle plus a placeholder result and defers real completion out
 * of band, so within the turn the card stays in the "working" state.
 *
 * Runtime: `src/app/api/copilotkit-background-agents/route.ts`.
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";
import { Chat } from "./chat";
import { backgroundTaskActivityRenderer } from "./activity-card";

const activityRenderers = [backgroundTaskActivityRenderer];

export default function BackgroundAgentsDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-background-agents"
      agent="background-agents"
      renderActivityMessages={activityRenderers}
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

// CopilotKit runtime for the Background Agents cell (Mastra, OSS-426).
//
// The `background-agents` Mastra agent wires the backgroundable
// `run_deep_research` tool. Mastra natively supports background tasks: when the
// model calls that tool it is dispatched to Mastra's BackgroundTaskManager
// (enabled on the Mastra instance in `src/mastra/index.ts` via
// `backgroundTasks: { enabled: true }`), which emits the background-task
// lifecycle chunks. MastraAgent maps those to AG-UI activity events → a live
// activity card in the chat.
//
// Completion is OUT OF BAND by design. Mastra's `untilIdle: true` is documented
// to hold the run open and pipe the manager pubsub chunks (including
// `background-task-completed`) into the same `fullStream` so the card could flip
// to "Completed" in-turn — and the bridge DOES map every lifecycle chunk. But
// that only works when the dispatched task actually EXECUTES before the idle
// window closes, which requires a background worker/queue picking the task up.
// In this single-process Next.js demo there is no such worker: empirically the
// tool's `execute` never fires within the run, so no `background-task-completed`
// chunk is ever produced — `untilIdle` just holds the stream open for the full
// idle timeout (many wasted re-entry LLM calls, a flaky/slow card render) while
// the card stays "working" regardless. So we DON'T use it: the plain
// `getLocalAgent` path lets the run close right after `background-task-started`,
// the "working" activity card paints fast and deterministically, and completion
// is delivered out of band (a later turn / the task manager) exactly as the
// demo's tool, renderer, and e2e document. See
// `src/mastra/tools/background-research.ts` and `tests/e2e/background-agents.spec.ts`.

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { getLocalAgent } from "@ag-ui/mastra";
import { mastra } from "@/mastra";
import { withForwardedHeaders } from "@/mastra/_header_forwarding";

const backgroundAgentsAgent = getLocalAgent({
  mastra,
  agentId: "backgroundAgentsAgent",
  resourceId: "mastra-background-agents",
});

if (!backgroundAgentsAgent) {
  throw new Error(
    "getLocalAgent returned null for backgroundAgentsAgent — required for /demos/background-agents",
  );
}

const runtime = new CopilotRuntime({
  // @ts-ignore -- see main route.ts
  agents: {
    "background-agents": backgroundAgentsAgent,
    default: backgroundAgentsAgent,
  },
});

export const POST = async (req: NextRequest) =>
  withForwardedHeaders(req, async () => {
    try {
      const copilotHandler = createCopilotRuntimeHandler({
        runtime,
        basePath: "/api/copilotkit-background-agents",
        mode: "single-route",
      });
      return await copilotHandler(req);
    } catch (error: unknown) {
      const e = error as { message?: string; stack?: string };
      return NextResponse.json(
        { error: e.message, stack: e.stack },
        { status: 500 },
      );
    }
  });

"use client";

/**
 * Renderer for the `mastra-background-task` activity.
 *
 * MastraAgent emits an AG-UI `ACTIVITY_SNAPSHOT` (activity type
 * `mastra-background-task`) when Mastra dispatches a backgroundable tool, then
 * `ACTIVITY_DELTA`s as the task's lifecycle advances. The content payload is
 * the shape the adapter documents on its exported
 * `MASTRA_BACKGROUND_TASK_ACTIVITY_TYPE` constant.
 *
 * Terminal-state note: on the dispatching turn Mastra delivers `started` plus
 * a placeholder result and defers real completion out of band, so within the
 * turn the card's status stays `running` — this renderer is built around the
 * live "working" state and simply reflects whatever `status` the adapter sets.
 */

import React from "react";
import { z } from "zod";
import type { ReactActivityMessageRenderer } from "@copilotkit/react-core/v2";

export const MASTRA_BACKGROUND_TASK_ACTIVITY_TYPE = "mastra-background-task";

// Content shape for the background-task activity. Kept loose (`.passthrough()`,
// optional fields) because the adapter fills the payload progressively across
// snapshot + deltas — only `status` is relied on for the card state.
const backgroundTaskContentSchema = z
  .object({
    taskId: z.string().optional(),
    toolName: z.string().optional(),
    toolCallId: z.string().optional(),
    status: z.string().optional(),
    args: z.record(z.unknown()).optional(),
    outputs: z.array(z.unknown()).optional(),
    result: z.unknown().optional(),
    error: z.unknown().optional(),
  })
  .passthrough();

type BackgroundTaskContent = z.infer<typeof backgroundTaskContentSchema>;

function statusLabel(status: string | undefined): {
  text: string;
  working: boolean;
} {
  switch (status) {
    case "completed":
      return { text: "Completed", working: false };
    case "failed":
      return { text: "Failed", working: false };
    case "cancelled":
      return { text: "Cancelled", working: false };
    case "suspended":
      return { text: "Paused", working: false };
    default:
      // "running" / "resumed" / anything in-flight
      return { text: "Working…", working: true };
  }
}

function BackgroundTaskCard({ content }: { content: BackgroundTaskContent }) {
  const { text, working } = statusLabel(content.status);
  const topic =
    (content.args?.topic as string | undefined) ??
    (content.toolName ? content.toolName.replace(/[-_]/g, " ") : "task");

  return (
    <div
      className="flex w-full justify-start"
      data-testid="background-task-activity"
      data-status={content.status ?? "running"}
    >
      <div className="w-full max-w-md rounded-2xl border bg-card p-4 shadow-sm">
        <div className="flex items-center gap-3">
          {working ? (
            <span
              className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-muted-foreground border-t-transparent"
              aria-hidden
            />
          ) : (
            <span
              className="inline-block h-4 w-4 rounded-full bg-muted-foreground"
              aria-hidden
            />
          )}
          <div className="flex flex-col">
            <span className="text-sm font-medium">Deep research</span>
            <span className="text-xs text-muted-foreground">{topic}</span>
          </div>
          <span
            className="ml-auto rounded-full bg-muted px-2 py-0.5 text-xs font-medium text-muted-foreground"
            data-testid="background-task-status"
          >
            {text}
          </span>
        </div>
        {working && (
          <p className="mt-3 text-xs text-muted-foreground">
            Running in the background — the conversation stays responsive while
            this task works.
          </p>
        )}
      </div>
    </div>
  );
}

export const backgroundTaskActivityRenderer: ReactActivityMessageRenderer<BackgroundTaskContent> =
  {
    activityType: MASTRA_BACKGROUND_TASK_ACTIVITY_TYPE,
    content: backgroundTaskContentSchema,
    render: ({ content }) => <BackgroundTaskCard content={content} />,
  };

"use client";

import { CopilotChat } from "@copilotkit/react-core/v2";
import { useBackgroundAgentsSuggestions } from "./suggestions";

export function Chat() {
  useBackgroundAgentsSuggestions();
  return (
    <CopilotChat agentId="background-agents" className="h-full rounded-2xl" />
  );
}

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export function useBackgroundAgentsSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Research AI agent frameworks",
        message:
          "Kick off deep research on the current landscape of AI agent frameworks.",
      },
      {
        title: "Investigate renewable energy trends",
        message:
          "Kick off deep research on emerging renewable energy trends for 2026.",
      },
    ],
    available: "always",
  });
}

// Header-forwarding shim: the ag-ui/mastra adapter does not propagate
// inbound x-* headers (e.g. x-aimock-context) to the Vercel AI SDK provider.
// `@/mastra/_header_forwarding` re-exports `openai` with a fetch wrapper
// that merges ALS-bound headers into every outbound LLM call. The
// CopilotKit route is responsible for binding the per-request snapshot via
// `withForwardedHeaders(req, () => handleRequest(req))`.
import { openai } from "@/mastra/_header_forwarding";
import { Agent } from "@mastra/core/agent";
import { stepCountIs } from "ai";
import {
  weatherTool,
  stockPriceTool,
  revenueChartTool,
  queryDataTool,
  manageTodosTool,
  getTodosTool,
  scheduleMeetingTool,
  scheduleMeetingInterruptTool,
  searchFlightsTool,
  searchFlightsA2uiTool,
  rollDiceTool,
  rollD20Tool,
  generateA2uiTool,
  setNotesTool,
  setStepsTool,
  researchAgentTool,
  writingAgentTool,
  critiqueAgentTool,
  browseWebTool,
  runDeepResearchTool,
} from "@/mastra/tools";
import { LibSQLStore } from "@mastra/libsql";
import { z } from "zod";
import { Memory } from "@mastra/memory";
import type { RequestContext } from "@mastra/core/request-context";
// Backend-owned A2UI with the toolkit validate->retry recovery loop (OSS-422).
// `@ag-ui/mastra/a2ui` is a bridge-free subpath (avoids the Mastra bundler vs
// @ag-ui/client→uuid clash); mirrors langgraph's get_a2ui_tools.
import { getA2UITools } from "@ag-ui/mastra/a2ui";

export const AgentState = z.object({
  proverbs: z.array(z.string()).default([]),
  // Beautiful Chat's app-mode todo canvas reads `agent.state.todos`. The
  // `manage_todos` tool writes the list into working memory (see
  // writeTodosToWorkingMemory), which the bridge surfaces as a STATE_SNAPSHOT —
  // so the slice MUST be declared here or the write has nowhere to land and the
  // panel stays on "No todos yet" (OSS-452). Shape mirrors langgraph-python's
  // Todo (beautiful_chat.py) and the shared frontend's Todo interface.
  // Optional/defaulted so every other weatherAgent-backed demo is unaffected.
  todos: z
    .array(
      z.object({
        id: z.string(),
        title: z.string(),
        description: z.string(),
        emoji: z.string(),
        status: z.enum(["pending", "completed"]),
      }),
    )
    .default([]),
});

/**
 * Persistent SQLite URL for working-memory storage.
 *
 * Why not `file::memory:`: an in-memory store resets on every process
 * restart. For demos that surface user state to the UI (notes panel, agent
 * delegations, preferences), that is silent data loss — the user adds notes,
 * the dev hits save, Next.js HMR restarts the server, and the notes vanish
 * with no error.
 *
 * Tests can override via `MASTRA_WORKING_MEMORY_URL=file::memory:` to keep
 * fixture isolation. The default is a relative file path so the DB lives
 * next to the package and survives reloads.
 */
export const WORKING_MEMORY_DB_URL =
  process.env.MASTRA_WORKING_MEMORY_URL ?? "file:./mastra-memory.db";

/**
 * Shared-state schema for the Shared State (Read + Write) demo.
 *
 * - `preferences` is WRITTEN by the UI via `agent.setState({ preferences })`.
 *   The AG-UI Mastra adapter merges `input.state` into the thread's
 *   `workingMemory` metadata before each run, so the LLM sees the latest UI
 *   preferences as part of working memory on every turn.
 * - `notes` is WRITTEN by the agent (via the `set_notes` tool) and READ by
 *   the UI via `useAgent({ updates: [OnStateChanged] })`. Mastra emits a
 *   `STATE_SNAPSHOT` after each run with the working-memory contents.
 */
export const SharedStateRWAgentState = z.object({
  preferences: z
    .object({
      name: z.string().default(""),
      tone: z.enum(["formal", "casual", "playful"]).default("casual"),
      language: z.string().default("English"),
      interests: z.array(z.string()).default([]),
    })
    .default({
      name: "",
      tone: "casual",
      language: "English",
      interests: [],
    }),
  notes: z.array(z.string()).default([]),
});

/**
 * Shared-state schema for the Sub-Agents demo.
 *
 * `delegations` is appended to by the supervisor as it fans out work to the
 * research / writing / critique sub-agents. The UI subscribes via
 * `useAgent({ updates: [OnStateChanged] })` and renders a live delegation
 * log.
 */
export const SubagentsAgentState = z.object({
  delegations: z
    .array(
      z.object({
        id: z.string(),
        sub_agent: z.enum([
          "research_agent",
          "writing_agent",
          "critique_agent",
        ]),
        task: z.string(),
        status: z.enum(["running", "completed", "failed"]),
        result: z.string(),
      }),
    )
    .default([]),
});

/**
 * Shared-state schema for the Gen UI Agent demo.
 *
 * `steps` is WRITTEN by the agent (via the `set_steps` tool) and READ by
 * the UI via `useAgent({ updates: [OnStateChanged] })`. Mastra includes
 * the `steps` field in its working-memory schema, so after each run-cycle
 * the AG-UI adapter emits a `STATE_SNAPSHOT` and the UI re-renders the
 * progress card.
 *
 * Status transitions: pending -> in_progress -> completed.
 */
export const GenUiAgentState = z.object({
  steps: z
    .array(
      z.object({
        id: z.string(),
        title: z.string(),
        status: z.enum(["pending", "in_progress", "completed"]),
      }),
    )
    .default([]),
});

/**
 * Shared-state schema for the Shared State (Streaming) demo.
 *
 * `document` is streamed token-by-token into shared state as the agent
 * writes. Mastra parity for the LangGraph `StateStreamingMiddleware` /
 * predictive-state pattern: instead of a `write_document` tool whose arg is
 * forwarded per-token, this agent calls Mastra's built-in
 * `updateWorkingMemory` tool with the growing document. The AG-UI Mastra
 * adapter intercepts that tool call's STREAMING args (OSS-414) and emits a
 * leading `STATE_SNAPSHOT` followed by incremental `STATE_DELTA`s on the
 * `document` key, so `useAgent({ updates:[OnStateChanged] })` sees
 * `state.document` grow live.
 */
export const SharedStateStreamingAgentState = z.object({
  document: z.string().default(""),
});

export const weatherAgent = new Agent({
  id: "weather-agent",
  name: "Weather Agent",
  tools: {
    get_weather: weatherTool,
    query_data: queryDataTool,
    manage_todos: manageTodosTool,
    get_todos: getTodosTool,
    schedule_meeting: scheduleMeetingTool,
    search_flights: searchFlightsTool,
    generate_a2ui: generateA2uiTool,
  },
  model: openai("gpt-5-mini"),
  instructions: "You are a helpful assistant.",
  memory: new Memory({
    storage: new LibSQLStore({
      id: "weather-agent-memory",
      url: WORKING_MEMORY_DB_URL,
    }),
    options: {
      workingMemory: {
        enabled: true,
        schema: AgentState,
      },
    },
  }),
});

// Dedicated agent for the headless-complete demo. Exercises the full
// generative-UI stack when the chat UI is composed manually: two backend
// tools (weather + stock price) wired through `useRenderTool`, plus a
// frontend-registered `highlight_note` tool the agent can invoke via the
// same tool-call channel. The system prompt nudges the model toward the
// right surface per user question and falls back to plain text otherwise.
//
// Note: `highlight_note` is intentionally NOT declared here — it's a
// frontend-only tool registered via `useComponent` in the demo's
// `tool-renderers.tsx`. The agent picks it up through CopilotKit's
// frontend-tool forwarding when `copilotkit.runAgent` is called.
export const headlessCompleteAgent = new Agent({
  id: "headless-complete-agent",
  name: "Headless Complete Agent",
  // Register under the snake_case names the aimock fixtures + useRenderTool
  // renderers emit (get_weather / get_stock_price / get_revenue_chart). Object
  // shorthand ({ weatherTool, stockPriceTool }) exposed the JS variable names
  // instead, so the fixture-scripted get_* tool calls were never executable and
  // the WeatherCard / StockCard / ChartCard stalled in their "running" state.
  // Mirrors gold langgraph-python headless_complete.py tools=[...].
  tools: {
    get_weather: weatherTool,
    get_stock_price: stockPriceTool,
    get_revenue_chart: revenueChartTool,
  },
  model: openai("gpt-5-mini"),
  instructions: `You are a helpful, concise assistant wired into a headless chat surface that demonstrates CopilotKit's full rendering stack. Pick the right surface for each user question and fall back to plain text when none of the tools fit.

Routing rules:
  - If the user asks about weather for a place, call \`get_weather\` with the location.
  - If the user asks about a stock or ticker (AAPL, TSLA, MSFT, ...), call \`get_stock_price\` with the ticker.
  - If the user asks you to highlight, flag, or mark a short note or phrase, call the frontend \`highlight_note\` tool with the text and a color (yellow, pink, green, or blue). Do NOT ask the user for the color — pick a sensible one if they didn't say.
  - Otherwise, reply in plain text.

After a tool returns, write one short sentence summarizing the result. Never fabricate data a tool could provide.`,
  memory: new Memory({
    storage: new LibSQLStore({
      id: "headless-complete-agent-memory",
