background-agents-agent.code:
/**
 * Background Agents demo agent (OSS-426).
 *
 * Wires the backgroundable `run_deep_research` tool. When the user asks to
 * research a topic, the agent calls the tool once; Mastra dispatches it as a
 * background task (the instance enables the BackgroundTaskManager in
 * `src/mastra/index.ts`) and MastraAgent surfaces it as a live "working"
 * activity card instead of a normal tool pill. Completion is out of band —
 * see `src/mastra/tools/background-research.ts`.
 */
export const backgroundAgentsAgent = new Agent({
  id: "background-agents",
  name: "Background Agents Agent",
  tools: { runDeepResearchTool },
  model: openai("gpt-5-mini"),
  instructions: `You are a research assistant that dispatches long-running work to the background.

When the user asks you to research, investigate, look into, or dig into a topic, you MUST call the \`run_deep_research\` tool ONCE with a concise \`topic\` describing what to research. That kicks the work off in the background so the conversation can continue.

After you call the tool, send ONE short assistant message telling the user the deep-research task is now running in the background and that you'll surface the findings when it completes. Do not call the tool more than once per request, and do not wait for results before replying.`,
  memory: new Memory({
    storage: new LibSQLStore({
      id: "background-agents-agent-memory",
      url: WORKING_MEMORY_DB_URL,
    }),
    options: {
      workingMemory: {
        enabled: true,
        schema: AgentState,
      },
    },
  }),
});

observational-memory-agent.code:
/**
 * Mastra agent backing the Observational Memory demo (OSS-427).
 *
 * Observational Memory (OM) is a Mastra `Memory` feature: as the conversation
 * grows, Mastra runs an Observer agent OUT OF BAND that reads the unobserved
 * messages, compresses them into structured observations, and activates those
 * observations into the working context. OM surfaces this background work on
 * the agent's `fullStream` as typed `data-om-*` chunks, which MastraAgent maps
 * to AG-UI activity events (activityType `mastra-observational-memory`).
 *
 * TWO independent opt-ins: (1) HERE — enable OM on the agent's `Memory` via
 * `options.observationalMemory`; (2) in the route — the surfacing toggle
 * `getLocalAgents({ mastra, observationalMemory: true })`.
 *
 * Config notes (verified vs @mastra/memory 1.22): `scope:'thread'` is required
 * for the async buffering path (`'resource'` throws); the trigger is UNOBSERVED
 * message-token SIZE (not turn count) with a reliable 600/300 floor (200/100
 * no-ops) — the demo pills send SIZABLE messages to trip it; a config object
 * requires an explicit model (the library default is a Gemini 2.5 Flash model,
 * which a new Google API key cannot call), pinned to the forwarding `openai` so
 * the Observer call routes through the header shim.
 */
export const observationalMemoryAgent = new Agent({
  id: "observational-memory-agent",
  name: "Observational Memory Agent",
  model: openai("gpt-5-mini"),
  instructions: `You are a helpful assistant with a long memory. The user will share large amounts of context about their work, projects, and preferences across the conversation. Read what they share carefully, answer their questions directly and concisely, and lean on everything they've told you so far. Keep replies focused — a few short paragraphs at most.`,
  memory: new Memory({
    storage: new LibSQLStore({
      id: "observational-memory-agent-memory",
      url: WORKING_MEMORY_DB_URL,
    }),
    options: {
      workingMemory: {
        enabled: true,
        schema: AgentState,
      },
      observationalMemory: {
        scope: "thread",
        observation: { messageTokens: 600, bufferTokens: 300 },
        model: openai("gpt-5-mini"),
      },
    },
  }),
});

background-research-tool.code:
/**
 * Backgroundable deep-research tool for the Background Agents demo.
 *
 * Mastra natively supports background tasks: a tool marked
 * `background: { enabled: true }` is dispatched to Mastra's
 * BackgroundTaskManager instead of running inline in the agentic loop
 * (the manager itself is enabled on the Mastra instance via
 * `new Mastra({ backgroundTasks: { enabled: true } })` — see
 * `src/mastra/index.ts`). When the model calls this tool, Mastra emits a
 * `background-task-started` lifecycle chunk on the run stream and returns
 * a placeholder tool-result so the conversation can continue.
 *
 * MastraAgent (the AG-UI adapter) maps that lifecycle chunk to an AG-UI
 * `ACTIVITY_SNAPSHOT` (activity type `mastra-background-task`) carrying the
 * task's status, and SUPPRESSES the normal tool-call render — so the work
 * surfaces ONLY as a live "working" activity card, never as an orphan tool
 * pill. The Copilot Runtime forwards those activity events to the client,
 * where a `renderActivityMessages` renderer paints the card.
 *
 * Terminal-state note: on the dispatching run's stream Mastra emits the
 * `started` lifecycle plus a placeholder result; the real completion is
 * delivered out of band (a later turn), so within this turn the card's
 * status stays `running`. The demo is intentionally designed around the
 * "working" state.
 */
import { createTool } from "@mastra/core/tools";
import { z } from "zod";

export const runDeepResearchTool = createTool({
  id: "run_deep_research",
  description:
    "Kick off a long-running deep-research task on a topic. This runs in " +
    "the background while the conversation continues — call it once when " +
    "the user asks to research, investigate, or dig into a topic.",
  inputSchema: z.object({
    topic: z.string().describe("The topic to research in depth."),
  }),
  // Marks this tool eligible for background execution. Combined with the
  // instance-level `backgroundTasks: { enabled: true }`, a call to this
  // tool is dispatched to the BackgroundTaskManager and emits a
  // `background-task-started` lifecycle chunk.
  background: { enabled: true },
  execute: async ({ topic }) => {
    // This body only runs when the task is actually executed by the
    // background worker. On the dispatching turn Mastra returns a
    // placeholder result instead, so the demo does not depend on this
    // value being surfaced within the turn.
    return JSON.stringify({
      topic,
      summary: `Deep research on "${topic}" completed.`,
    });
  },
});

files.content:
"use client";

/**
 * Browser Use (Mastra, OSS-91).
 *
 * A Mastra browser-navigation agent: you chat, the agent drives a REAL local
 * headless browser (Playwright Chromium — no hosted-browser API key), and the
 * results render inline in the CopilotKit chat as cards. Modeled on Mastra's
 * HackerNews browser example.
 *
 * Mastra-only + real-LLM: browser navigation is non-deterministic (live pages
 * change every request), so this cell has NO aimock replay fixture and is not
 * a D6 cell. See qa/browser-use.md and tests/e2e/browser-use.spec.ts.
 *
 * Runtime requirement: the local Chromium binary must be installed once via
 * `npx playwright install chromium`. If it is missing, the `browse_web` tool
 * returns a structured error the agent relays instead of crashing.
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";
import { Chat } from "./chat";

export default function BrowserUseDemo() {
  return (
