"use client";

/**
 * Observational Memory demo (Mastra).
 *
 * Observational Memory (OM) is a Mastra `Memory` feature: as the conversation
 * grows past a token threshold, Mastra runs an Observer OUT OF BAND that reads
 * the unobserved messages, compresses them into structured observations, and
 * activates them into the working context. Mastra streams that background work
 * on the run's `fullStream` as typed `data-om-*` chunks.
 *
 * The AG-UI Mastra adapter maps those chunks to AG-UI activity events
 * (activityType `mastra-observational-memory`) when the surfacing toggle is on
 * (see `src/app/api/copilotkit-observational-memory/route.ts`). We register a
 * custom activity renderer via `<CopilotKit renderActivityMessages={...}>` so
 * the "agent is compressing / activating memory" work renders inline as a
 * distinct card in the chat transcript.
 *
 * TRIGGER: OM fires on unobserved MESSAGE-TOKEN SIZE, not turn count. The two
 * suggestion pills send deliberately large multi-paragraph messages so a
 * single click crosses the threshold and the Observer runs.
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";
import { Chat } from "./chat";
import { observationalMemoryActivityRenderer } from "./activity-renderer";

export default function ObservationalMemoryDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit-observational-memory"
      agent="observational-memory"
      renderActivityMessages={[observationalMemoryActivityRenderer]}
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

// CopilotKit runtime for the Observational Memory cell.
//
// Observational Memory (OM) is a Mastra `Memory` feature the agent opts into
// (see `observationalMemoryAgent` in src/mastra/agents/index.ts). As the
// conversation grows, Mastra runs an Observer out of band that compresses the
// unobserved messages into observations and activates them — surfacing that
// work on the run's `fullStream` as `data-om-*` chunks.
//
// The AG-UI Mastra adapter only maps those chunks to AG-UI activity events
// when the surfacing toggle is on. That toggle lives on `getLocalAgents`
// (PLURAL) — `getLocalAgent` (singular) does NOT expose it — so we build the
// agent set with `observationalMemory: true` and pick our agent out of the
// returned record (keyed by the Mastra registration key,
// `observationalMemoryAgent`).

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { getLocalAgents } from "@ag-ui/mastra";
import { mastra } from "@/mastra";
import { withForwardedHeaders } from "@/mastra/_header_forwarding";

// `observationalMemory: true` is the adapter surfacing opt-in (default OFF).
// It only controls whether the bridge FORWARDS the `data-om-*` chunks the
// agent streams — the agent must ALSO have OM enabled on its Memory (it does).
const localAgents = getLocalAgents({
  mastra,
  resourceId: "mastra-observationalMemoryAgent",
  observationalMemory: true,
});

const observationalMemoryAgent = localAgents["observationalMemoryAgent"];
if (!observationalMemoryAgent) {
  throw new Error(
    "getLocalAgents did not return observationalMemoryAgent — required for /demos/observational-memory",
  );
}

const runtime = new CopilotRuntime({
  agents: {
    "observational-memory": observationalMemoryAgent,
    default: observationalMemoryAgent,
  },
});

export const POST = async (req: NextRequest) =>
  withForwardedHeaders(req, async () => {
    try {
      const copilotHandler = createCopilotRuntimeHandler({
        runtime,
        basePath: "/api/copilotkit-observational-memory",
        mode: "single-route",
      });
      return await copilotHandler(req);
    } catch (error: unknown) {
      const e = error as { message?: string; stack?: string };
      return NextResponse.json(
        { error: e.message, stack: e.stack },
        { status: 500 },
      );
    }
  });

"use client";

import React from "react";
import { z } from "zod";
import type { ReactActivityMessageRenderer } from "@copilotkit/react-core/v2";

// Inlined from @ag-ui/mastra's `MASTRA_OBSERVATIONAL_MEMORY_ACTIVITY_TYPE`.
// We intentionally do NOT import the bridge here: it re-exports the Node-only
// `@mastra/core` (fs / stream/web), which webpack refuses to bundle into a
// client component. The activity type is a stable protocol string, so a local
// constant is the correct client-side reference. Kept in sync with the bridge.
const MASTRA_OBSERVATIONAL_MEMORY_ACTIVITY_TYPE = "mastra-observational-memory";

/**
 * Content schema for the Mastra Observational Memory activity.
 *
 * Mirrors the shape documented on `MASTRA_OBSERVATIONAL_MEMORY_ACTIVITY_TYPE`
 * in @ag-ui/mastra. All fields but `cycleId`/`phase`/`status` are optional —
 * which fields are present depends on the OM phase (buffering vs activation).
 * Everything is `.optional()`/`.passthrough()`-tolerant so a future bridge
 * that adds fields still validates.
 */
export const omActivityContentSchema = z
  .object({
    cycleId: z.string(),
    operationType: z.enum(["observation", "reflection"]).optional(),
    phase: z.string(),
    status: z.string(),
    threadId: z.string().optional(),
    observations: z.string().optional(),
    currentTask: z.string().optional(),
    suggestedResponse: z.string().optional(),
    tokensToObserve: z.number().optional(),
    tokensObserved: z.number().optional(),
    bufferedTokens: z.number().optional(),
    observationTokens: z.number().optional(),
    tokensActivated: z.number().optional(),
    chunksActivated: z.number().optional(),
    messagesActivated: z.number().optional(),
    triggeredBy: z.string().optional(),
    durationMs: z.number().optional(),
    startedAt: z.string().optional(),
    completedAt: z.string().optional(),
    error: z.string().optional(),
  })
  .passthrough();

type OMActivityContent = z.infer<typeof omActivityContentSchema>;

const PHASE_LABEL: Record<string, string> = {
  observation: "Observing conversation",
  buffering: "Compressing memory",
  activation: "Activating observations",
};

const STATUS_LABEL: Record<string, string> = {
  running: "Working",
  completed: "Compressed",
  activated: "Activated",
  failed: "Failed",
};

function StatusDot({ status }: { status: string }) {
  const color =
    status === "failed"
      ? "#ef4444"
      : status === "running"
        ? "#f59e0b"
        : "#10b981";
  const pulse = status === "running";
  return (
    <span
      data-testid="om-status-dot"
      style={{
        display: "inline-block",
        width: 8,
        height: 8,
        borderRadius: "50%",
        background: color,
        animation: pulse ? "om-pulse 1.2s ease-in-out infinite" : undefined,
      }}
    />
  );
}

/**
 * Inline card rendered for each OM activity cycle. One card per `cycleId`;
 * it advances running -> completed -> activated as deltas arrive.
 */
function OMActivityCard({ content }: { content: OMActivityContent }) {
  const phaseLabel = PHASE_LABEL[content.phase] ?? content.phase;
  const statusLabel = STATUS_LABEL[content.status] ?? content.status;

  return (
    <div
      data-testid="om-activity-card"
      data-om-phase={content.phase}
      data-om-status={content.status}
      style={{
        border: "1px solid rgba(148, 163, 184, 0.3)",
        borderRadius: 12,
        padding: "10px 14px",
        margin: "8px 0",
        background: "rgba(148, 163, 184, 0.06)",
        fontSize: 13,
      }}
    >
      <style>{`@keyframes om-pulse{0%,100%{opacity:1}50%{opacity:0.35}}`}</style>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          fontWeight: 600,
        }}
      >
        <StatusDot status={content.status} />
        <span>{phaseLabel}</span>
        <span style={{ opacity: 0.5, fontWeight: 400 }}>· {statusLabel}</span>
      </div>
      {content.observations ? (
        <div
          data-testid="om-observations"
          style={{ marginTop: 6, opacity: 0.85, lineHeight: 1.4 }}
        >
          {content.observations}
        </div>
      ) : null}
      {typeof content.bufferedTokens === "number" ||
      typeof content.tokensActivated === "number" ? (
        <div style={{ marginTop: 6, opacity: 0.6, fontSize: 12 }}>
          {typeof content.bufferedTokens === "number"
            ? `${content.bufferedTokens} tokens buffered`
            : null}
          {typeof content.tokensActivated === "number"
            ? `${content.tokensActivated} tokens activated`
            : null}
        </div>
      ) : null}
      {content.error ? (
        <div style={{ marginTop: 6, color: "#ef4444" }}>{content.error}</div>
      ) : null}
    </div>
  );
}

/**
 * Activity renderer registered on `<CopilotKit renderActivityMessages={...}>`.
