 */
export const observationalMemoryActivityRenderer: ReactActivityMessageRenderer<OMActivityContent> =
  {
    activityType: MASTRA_OBSERVATIONAL_MEMORY_ACTIVITY_TYPE,
    content: omActivityContentSchema,
