agents["hitl-in-chat"] = createReplaySafeAgent("/hitl-in-chat", ["book_call"]);

// Generative UI Agent — backend with `set_steps` tool + `steps` state
// schema mirrored from LGP's gen_ui_agent. The frontend renders a live
