}

export function DemoLayout({
  userName,
  userTimezone,
  recentActivity,
  onUserNameChange,
  onUserTimezoneChange,
  onToggleActivity,
}: DemoLayoutProps) {
  const publishedContext = {
    name: userName,
    timezone: userTimezone,
    recentActivity,
  };

  return (
    <main className="min-h-screen w-full bg-neutral-50 px-6 py-10 md:px-10 md:py-14">
