    },
    [],
  );

  useRenderTool(
    {
      name: "get_revenue_chart",
      parameters: z.object({}),
      render: ({ result, status }) => {
        const r = parseJsonResult<{
          title: string;
          subtitle: string;
          data: ChartPoint[];
        }>(result);
        return (
