  font-family: var(--halcyon-mono);
  font-size: 0.86em;
  font-weight: 500;
  color: var(--halcyon-ember);
  background: var(--halcyon-ember-soft);
  border: 1px solid color-mix(in srgb, var(--halcyon-ember) 22%, transparent);
  border-radius: 0;
