            </div>
            <div
              data-testid="stock-price"
              className="mt-1 text-2xl font-semibold text-[#010507] tracking-tight"
            >
              {priceUsd !== undefined ? `$${priceUsd.toFixed(2)}` : "—"}
            </div>
