/**
 * Shared demo-token constant imported by both the client
 * (use-demo-auth.ts) and the server runtime route
 * (api/copilotkit-auth/route.ts). Keeping the constant in one file
 * prevents drift: changing the token in one place changes it everywhere.
 *
 * This is a DEMO token. Never use a hard-coded shared secret for real auth.
 */
export const DEMO_TOKEN = "demo-token-123";

export const DEMO_AUTH_HEADER = `Bearer ${DEMO_TOKEN}`;

"use client";

import { useCallback, useEffect, useState } from "react";
import { DEMO_TOKEN } from "./demo-token";

const STORAGE_KEY = "copilotkit:auth-demo:token";

export interface DemoAuthHandle {
  isAuthenticated: boolean;
  /** The token string when authenticated, otherwise null. */
  token: string | null;
  /** The full `Bearer <token>` value when authenticated, otherwise null. */
  authorizationHeader: string | null;
  /**
   * Whether the user has signed in at least once during the current page
   * session. Used by the page to decide between the first-paint SignInCard
   * (never signed in) and the persistent chat-with-amber-banner state
   * (signed in, then signed out) — the latter is the only state that
   * actually showcases the runtime rejecting unauthenticated requests.
   * Resets on full page reload by design.
   */
  hasEverSignedIn: boolean;
  /** Sign in with the provided token. */
  signIn: (token: string) => void;
  /** Clear the stored token. */
  signOut: () => void;
}

/**
 * Persistent demo auth state for the /demos/auth showcase cell. Tokens are
 * stored in localStorage so a page reload doesn't kick the user back out;
 * first paint of a fresh visitor is unauthenticated, which lets the demo
 * showcase its sign-in CTA up front.
 *
 * This is a DEMO. Never store real bearer tokens in localStorage in a
 * production application — that exposes them to any script running on the
 * page.
 */
export function useDemoAuth(): DemoAuthHandle {
  const [token, setToken] = useState<string | null>(null);
  const [hasEverSignedIn, setHasEverSignedIn] = useState(false);

  // Hydrate from localStorage after mount. Reading on initial render would
  // mismatch SSR (where window is undefined); deferring to useEffect keeps
  // first paint unauthenticated and avoids hydration warnings.
  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      const stored = window.localStorage.getItem(STORAGE_KEY);
      if (stored) {
        setToken(stored);
        setHasEverSignedIn(true);
      }
    } catch {
      // localStorage unavailable (privacy mode, etc.) — fall back to
      // in-memory only.
    }
  }, []);

  const signIn = useCallback((nextToken: string) => {
    setToken(nextToken);
    setHasEverSignedIn(true);
    try {
      window.localStorage.setItem(STORAGE_KEY, nextToken);
    } catch {
      // Ignore — in-memory state still works.
    }
  }, []);

  const signOut = useCallback(() => {
    setToken(null);
    // hasEverSignedIn intentionally stays true so the page keeps showing
    // the chat surface (with amber banner) after sign-out. That is the
    // state that demonstrates the runtime returning 401.
    try {
      window.localStorage.removeItem(STORAGE_KEY);
    } catch {
      // Ignore.
    }
  }, []);

  // The runtime gate compares against a fixed token, so anything other than
  // DEMO_TOKEN won't actually authenticate against the API. We still allow
  // arbitrary strings here because validation is the runtime's job — the UI
  // just owns "what header are we sending".
  return {
    isAuthenticated: token !== null,
    token,
    authorizationHeader: token ? `Bearer ${token}` : null,
    hasEverSignedIn,
    signIn,
    signOut,
  };
}

"use client";

// Reasoning — Default
//
// Pairs with `reasoning-custom` (the Custom variant) so users can
// compare default vs custom reasoning rendering side by side. This cell
// renders <CopilotChat> with NO slot override — reasoning messages are
// rendered by the built-in `CopilotChatReasoningMessage` component
// (Thinking… / Thought for X header with an expandable content region).
//
// Both demos share the same backend (`reasoning_agent` graph) and the
// same runtime URL (/api/copilotkit). The only difference is whether the
// `messageView.reasoningMessage` slot is overridden.

import { CopilotKit, CopilotChat } from "@copilotkit/react-core/v2";
import { useReasoningDefaultSuggestions } from "./suggestions";

const AGENT_ID = "reasoning-default";

export default function ReasoningDefaultDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent={AGENT_ID}>
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  useReasoningDefaultSuggestions();
  return <CopilotChat agentId={AGENT_ID} className="h-full rounded-2xl" />;
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";
import crypto from "node:crypto";

// The agent backend runs as a separate process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

function createAgent() {
  return new HttpAgent({ url: `${AGENT_URL}/` });
}

// Register the same agent under all names used by demo pages.
const agentNames = [
  "agentic_chat",
  "human_in_the_loop",
  "tool-rendering",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-write",
  "shared-state-read-write",
  "shared-state-streaming",
  "subagents",
  // Prebuilt chat UI demos
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "chat-customization-css",
  "headless-simple",
  "headless-complete",
  "beautiful-chat",
  // Frontend tool demos
  "frontend-tools",
  "frontend-tools-async",
  "threadid-frontend-tool-roundtrip",
  "hitl-in-app",
  "hitl-in-chat",
  // Generative UI demos
  "declarative-gen-ui",
  "a2ui-fixed-schema",
  "open-gen-ui",
  "open-gen-ui-advanced",
  // Tool rendering variants
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  // Readonly state
  "readonly-state-agent-context",
];

const agents: Record<string, AbstractAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent();
}
agents["default"] = createAgent();

// Demo-specific agents with distinct backend prompts live at dedicated
// sub-paths on the PydanticAI server (see src/agent_server.py). Override
// the URL for those agent ids so they proxy to the right backend mount
// instead of the shared sales agent at the root.
agents["headless-complete"] = new HttpAgent({
  url: `${AGENT_URL}/headless_complete/`,
});
agents["shared-state-read-write"] = new HttpAgent({
  url: `${AGENT_URL}/shared_state_read_write/`,
});
agents["subagents"] = new HttpAgent({
  url: `${AGENT_URL}/subagents/`,
});
agents["gen-ui-tool-based"] = new HttpAgent({
  url: `${AGENT_URL}/gen_ui_tool_based/`,
});

// In-Chat HITL — chat-only agent; the `book_call` tool is defined on the
// frontend via `useHumanInTheLoop`. Backed by the dedicated mount at
// `/hitl_in_chat` (see src/agent_server.py).
agents["hitl-in-chat"] = new HttpAgent({
  url: `${AGENT_URL}/hitl_in_chat/`,
});

// Reasoning trio — both reasoning cells share the same backend agent
// (custom-slot vs default-slot is a frontend-only distinction).
agents["reasoning-custom"] = new HttpAgent({
  url: `${AGENT_URL}/reasoning/`,
});
agents["reasoning-default"] = new HttpAgent({
  url: `${AGENT_URL}/reasoning/`,
});
agents["tool-rendering-reasoning-chain"] = new HttpAgent({
  url: `${AGENT_URL}/tool_rendering_reasoning_chain/`,
});

// Interrupt-adapted scheduling demos — both gen-ui-interrupt and
// interrupt-headless share the same backend agent; only the frontend UX
// differs (inline picker in chat vs. external popup).
agents["gen-ui-interrupt"] = new HttpAgent({
  url: `${AGENT_URL}/interrupt/`,
});
agents["interrupt-headless"] = new HttpAgent({
  url: `${AGENT_URL}/interrupt/`,
});

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- Published CopilotRuntime agents type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in source, pending release
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    const err = error instanceof Error ? error : new Error(String(error));
    // Log the full error server-side (including stack) but return only a
    // generic message + correlation id to the client. Returning err.message
    // and err.stack to the client leaks internal paths, dependency names,
    // and stack frames — useful for debugging, but unsafe to surface in a
    // production response. Operators correlate via `errorId`.
    const errorId = crypto.randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

"use client";

