  return (
    <div
      data-testid="weather-card"
      className="rounded-2xl mt-4 mb-4 max-w-md w-full bg-[#EDEDF5] border border-[#DBDBE5] text-[#010507] shadow-sm"
    >
      <div className="p-5">
        <div className="flex items-start justify-between gap-4">
          <div>
            <div className="text-[10px] uppercase tracking-[0.14em] text-[#57575B] mb-1">
              Current weather
            </div>
            <h3
              data-testid="weather-city"
              className="text-xl font-semibold capitalize text-[#010507]"
            >
              {location || "Weather"}
            </h3>
            <p className="text-[#57575B] text-sm mt-0.5">
              {loading ? "Fetching weather..." : conditions || "—"}
            </p>
          </div>
          <div className="text-4xl leading-none" aria-hidden>
            {loading ? "..." : conditionsEmoji(conditions)}
          </div>
        </div>

        {!loading && (
          <>
            <div className="mt-5 text-4xl font-semibold text-[#010507] tracking-tight">
              {temperature ?? "--"}&deg;
              <span className="ml-1 text-lg font-normal text-[#57575B]">F</span>
            </div>
            <div className="mt-5 pt-4 border-t border-[#DBDBE5] grid grid-cols-2 gap-3 text-sm">
              <div data-testid="weather-humidity">
                <p className="text-[10px] uppercase tracking-[0.14em] text-[#57575B]">
                  Humidity
                </p>
                <p className="mt-1 font-medium text-[#010507]">
                  {humidity ?? "--"}%
                </p>
              </div>
              <div data-testid="weather-wind">
                <p className="text-[10px] uppercase tracking-[0.14em] text-[#57575B]">
                  Wind
                </p>
                <p className="mt-1 font-medium text-[#010507]">
                  {windSpeed ?? "--"} mph
                </p>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function conditionsEmoji(conditions?: string): string {
  if (!conditions) return "";
  const c = conditions.toLowerCase();
  if (c.includes("sun") || c.includes("clear")) return "sun";
  if (c.includes("rain") || c.includes("storm")) return "rain";
  if (c.includes("cloud")) return "cloud";
  if (c.includes("snow")) return "snow";
  return "";
}

"use client";

/**
 * MCP Apps demo.
 *
 * MCP Apps are MCP servers that expose tools with associated UI resources.
 * The CopilotKit runtime is wired with `mcpApps: { servers: [...] }`
 * (see `src/app/api/copilotkit-mcp-apps/route.ts`), which auto-applies the
 * MCP Apps middleware. When the agent calls an MCP tool, the middleware
 * fetches the associated UI resource and emits an activity event; the
 * built-in `MCPAppsActivityRenderer` registered by `CopilotKitProvider`
 * renders the sandboxed iframe inline in the chat — no app-side renderer
 * registration required.
 *
 * This cell points at the public Excalidraw MCP app (https://mcp.excalidraw.com).
 *
 * Reference:
 * https://docs.copilotkit.ai/integrations/langgraph/generative-ui/mcp-apps
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";
import { Chat } from "./chat";

export default function MCPAppsDemo() {
  // No `renderActivityMessages`, no `useRenderActivityMessage` — the
  // CopilotKitProvider auto-registers the built-in `MCPAppsActivityRenderer`
  // for the "mcp-apps" activity type. A plain <CopilotChat /> is enough.
  return (
    <CopilotKit runtimeUrl="/api/copilotkit-mcp-apps" agent="mcp-apps">
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

// CopilotKit runtime for the MCP Apps cell.
//
// The runtime's `mcpApps` config auto-applies the MCP Apps middleware to the
// agent: when the agent calls a tool backed by an MCP UI resource, the
// middleware fetches the resource and emits the activity event that the
// built-in `MCPAppsActivityRenderer` (registered by CopilotKit internally)
// renders in the chat as a sandboxed iframe.
//
// The PydanticAI agent itself is a no-tools agent mounted at `/mcp_apps`
// in `src/agent_server.py`; the runtime's mcpApps middleware injects the
// remote MCP server's tools into each request.
//
// Reference:
// https://docs.copilotkit.ai/integrations/langgraph/generative-ui/mcp-apps

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

const agents: Record<string, AbstractAgent> = {
  // headless-complete shares this runtime (its page wires
  // runtimeUrl="/api/copilotkit-mcp-apps") but is backed by the dedicated
  // /headless_complete/ mount — the same backend the main route registers
  // it against.
  "headless-complete": new HttpAgent({
    url: `${AGENT_URL}/headless_complete/`,
  }),
  "mcp-apps": new HttpAgent({ url: `${AGENT_URL}/mcp_apps/` }),
};

// The `mcpApps.servers` config is all you need server-side. The runtime
// auto-applies the MCP Apps middleware to every registered agent: on each
// MCP tool call it fetches the associated UI resource and emits an
// `activity` event that the built-in `MCPAppsActivityRenderer` renders
// inline in the chat.
const runtime = new CopilotRuntime({
  // The explicit `Record<string, AbstractAgent>` annotation on `agents`
  // above narrows the value to the type CopilotRuntime's `agents` map
  // expects; see main route.ts for the underlying published-type quirk
  // (MaybePromise<NonEmptyRecord<...>> around the Record). Fixed in
  // source, pending release.
  agents,
  mcpApps: {
    servers: [
      {
        type: "http",
        url: process.env.MCP_SERVER_URL || "https://mcp.excalidraw.com",
        // Always pin a stable `serverId`. Without it CopilotKit hashes the
        // URL, and a URL change silently breaks restoration of persisted
        // MCP Apps in prior conversation threads.
        serverId: "excalidraw",
      },
    ],
  },
});

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime,
      basePath: "/api/copilotkit-mcp-apps",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

