      agent="a2ui-fixed-schema"
      a2ui={{ catalog: catalog }}
    >
      <div className="flex justify-center items-center h-screen w-full bg-neutral-50">
        <div className="h-full w-full max-w-4xl border-x border-neutral-200 bg-white">
          <Chat />
        </div>
