@RestController
public class A2uiFixedSchemaController {

    private final AgUiService agUiService;
    private final ChatModel chatModel;

    @Autowired
    public A2uiFixedSchemaController(AgUiService agUiService, ChatModel chatModel) {
        this.agUiService = agUiService;
        this.chatModel = chatModel;
    }

    @PostMapping("/a2ui-fixed-schema/run")
    public ResponseEntity<SseEmitter> run(@RequestBody AgUiParameters params) {
        MessageListFilter.filterNulls(params);
        StreamingToolAgent agent = buildAgent();
        SseEmitter emitter = agUiService.runAgent(agent, params);
        return ResponseEntity.ok()
                .cacheControl(CacheControl.noCache())
                .body(emitter);
    }

    private StreamingToolAgent buildAgent() {
        return StreamingToolAgent.builder()
                .agentId("a2ui-fixed-schema")
                .chatModel(chatModel)
                .systemMessage("""
                        You are a flight-search assistant. When the user asks about a flight,
                        call the display_flight tool with the origin airport code, destination
                        airport code, airline, and price string (e.g. "$289"). Use 3-letter
                        airport codes. After calling the tool, reply with a brief confirmation
                        in plain text.
                        """)
                .toolCallback(
                        FunctionToolCallback.builder("display_flight", new DisplayFlightTool())
                                .description("Display a flight card for the given trip")
                                .inputType(DisplayFlightTool.Request.class)
                                .build()
                )
                .build();
    }
}

package com.copilotkit.showcase.springai.tools;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.util.List;
import java.util.Map;
import java.util.function.Function;

/**
 * A2UI Fixed Schema display tool.
 *
 * Emits a fixed "Flight Card" component tree plus a data model populated
 * with the provided origin/destination/airline/price. The frontend catalog
 * at src/app/demos/a2ui-fixed-schema/a2ui/ pins each component name to a
 * React renderer.
 *
 * Registered as "display_flight" on the dedicated a2ui-fixed-schema agent
 * bean (see AgentConfigFixedSchema).
 */
public class DisplayFlightTool implements Function<DisplayFlightTool.Request, String> {

    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final String CATALOG_ID = "copilotkit://flight-fixed-catalog";
    private static final String SURFACE_ID = "flight-fixed-schema";

    public record Request(String origin, String destination, String airline, String price) {}

    // The fixed-schema flight component tree. Spring AI doesn't ship a
    // JSON-loading helper analogous to `a2ui.load_schema(...)`, so the
    // schema is declared inline as a Java constant — equivalent to
    // deserialising a `flight_schema.json` file at startup. The frontend
    // catalog (`copilotkit://flight-fixed-catalog`) resolves each
    // `component` name to a React renderer.
    private static final List<Map<String, Object>> FLIGHT_SCHEMA = List.of(
            Map.of("id", "root", "component", "Card", "child", "content"),
            Map.of("id", "content", "component", "Column",
                    "children", List.of("title", "route", "meta", "bookButton")),
            Map.of("id", "title", "component", "Title", "text", "Flight Details"),
            Map.of("id", "route", "component", "Row", "justify", "spaceBetween",
                    "align", "center", "children", List.of("from", "arrow", "to")),
            Map.of("id", "from", "component", "Airport",
                    "code", Map.of("path", "/origin")),
            Map.of("id", "arrow", "component", "Arrow"),
            Map.of("id", "to", "component", "Airport",
                    "code", Map.of("path", "/destination")),
            Map.of("id", "meta", "component", "Row", "justify", "spaceBetween",
                    "align", "center", "children", List.of("airline", "price")),
            Map.of("id", "airline", "component", "AirlineBadge",
                    "name", Map.of("path", "/airline")),
            Map.of("id", "price", "component", "PriceTag",
                    "amount", Map.of("path", "/price")),
            Map.of("id", "bookButton", "component", "Button",
                    "variant", "primary", "child", "bookButtonLabel",
                    "action", Map.of(
                            "event", Map.of(
                                    "name", "book_flight",
                                    "context", Map.of(
                                            "origin", Map.of("path", "/origin"),
                                            "destination", Map.of("path", "/destination"),
                                            "airline", Map.of("path", "/airline"),
                                            "price", Map.of("path", "/price")
                                    )
                            )
                    )),
            Map.of("id", "bookButtonLabel", "component", "Text", "text", "Book flight")
    );

    @Override
    public String apply(Request request) {
        try {
            // Emit v0.9 nested A2UI operations. The middleware parses
            // `a2ui_operations` from any TOOL_CALL_RESULT and expects each op
            // to carry `"version":"v0.9"` with a camelCase operation key
            // (`createSurface`, `updateComponents`, `updateDataModel`) and the
            // data nested under `value` (not `data`). This matches the Python
            // SDK shape in sdk-python/copilotkit/a2ui.py.
            var ops = List.of(
                    Map.of("version", "v0.9",
                            "createSurface", Map.of(
                                    "surfaceId", SURFACE_ID,
                                    "catalogId", CATALOG_ID)),
                    Map.of("version", "v0.9",
                            "updateComponents", Map.of(
                                    "surfaceId", SURFACE_ID,
                                    "components", FLIGHT_SCHEMA)),
                    Map.of("version", "v0.9",
                            "updateDataModel", Map.of(
                                    "surfaceId", SURFACE_ID,
                                    "path", "/",
                                    "value", Map.of(
                                            "origin", request.origin(),
                                            "destination", request.destination(),
                                            "airline", request.airline(),
                                            "price", request.price()
                                    )))
            );
            return MAPPER.writeValueAsString(Map.of("a2ui_operations", ops));
        } catch (Exception e) {
            return "{\"error\":\"" + e.getMessage().replace("\"", "'") + "\"}";
        }
    }
}

