            {result !== undefined && (
              <div>
                <div className="mb-1 text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">
                  Output
                </div>
                <pre className="overflow-x-auto rounded-md border bg-muted p-2 font-mono text-[11px] leading-snug text-foreground">
