"use client";

/**
 * Beautiful Chat — the flagship CopilotKit showcase cell, ported verbatim
 * from the 4084 reference clone. The 4084 version lived as its own Next.js
 * frontend at `demos/beautiful-chat/frontend/` with a full `src/components`
 * tree + A2UI catalog. Here the same tree is colocated under the cell and
 * re-wired with relative imports.
 *
 * Providers: layout-level `CopilotKit` + `ThemeProvider` wrappers from the
 * original 4084 root layout are applied here instead, because the unified
 * 4085 shell does not give each cell its own layout.tsx.
 *
 * Runtime: this cell uses its own dedicated runtime endpoint
 * (`/api/copilotkit-beautiful-chat`) so it can enable `openGenerativeUI`,
 * `a2ui` with `injectA2UITool: false`, and `mcpApps` simultaneously — the
 * same combined-runtime shape the canonical starter uses — without bleeding
 * those global flags into other cells sharing the main `/api/copilotkit`
 * endpoint. The backend graph is `beautiful_chat` (src/agents/beautiful_chat.py).
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";

import { ThemeProvider } from "./hooks/use-theme";
import { demonstrationCatalog } from "./declarative-generative-ui/renderers";
import { HomePage } from "./home-page";

export default function BeautifulChatPage() {
  return (
    <ThemeProvider>
      <CopilotKit
        runtimeUrl="/api/copilotkit-beautiful-chat"
        agent="beautiful-chat"
        a2ui={{ catalog: demonstrationCatalog }}
        openGenerativeUI={{}}
        /*
         * `useSingleEndpoint` defaults to true (the single-POST-endpoint
         * protocol). The canonical reference sets it to false to use the
         * v2 multi-endpoint protocol (GET /info + POST /agent/{name}/connect),
         * which requires a Hono-based endpoint via `createCopilotEndpoint`.
         * The 4085 showcase uses `copilotRuntimeNextJSAppRouterEndpoint`
         * (single-endpoint), which matches the other 4085 cells — so we
         * use its default behavior here. Functionally equivalent for this demo.
         */
      >
        <HomePage />
      </CopilotKit>
    </ThemeProvider>
  );
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";

// The Spring AI agent backend runs as a separate Java process.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

function createAgent(path = "/") {
  return new HttpAgent({ url: `${AGENT_URL}${path}` });
}

// Register the same Spring AI agent (backed by a single Spring-AI ChatClient
// on the Java side) under every name used by the demo pages in this package.
// Each entry proxies CopilotKit requests to the same Spring endpoint —
// per-demo behavior differences live on the frontend in the form of
// useFrontendTool / useRenderTool / useHumanInTheLoop / useAgentContext
// hooks registered on each page.
const agentNames = [
  "agentic_chat",
  "human_in_the_loop",
  "tool-rendering",
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-write",
  "shared-state-read-write",
  "shared-state-streaming",
  "subagents",
  "chat-customization-css",
  "frontend_tools",
  "frontend-tools-async",
  "hitl-in-chat",
  "hitl-in-app",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "headless-simple",
  "headless-complete",
  "readonly-state-agent-context",
  "auth",
  "open-gen-ui",
  "beautiful-chat",
  // NOTE: `tool-rendering-reasoning-chain` is intentionally NOT registered
  // here. It is declared NSF in manifest.yaml (no parallel multi-tool-call
  // streaming surface to interleave with reasoning frames on spring-ai), and
  // routing it to the default Spring agent at `/` silently bypassed the
  // reasoning workaround and rendered a regular tool-rendering run, hiding
  // the NSF. With no registration the page errors loudly when probed —
  // appropriate for a not-supported feature.
  "mcp-apps",
  "byoc-hashbrown",
];

// Reasoning agent names — backed by the dedicated Spring-AI reasoning
// controller at /reasoning (ReasoningController). The AG-UI Java SDK at
// Spring AI 1.0.1 has no REASONING_MESSAGE_* subtypes in its typed event
// model (the SDK only knows THINKING_*, which @ag-ui/client silently drops),
// so ReasoningController takes over its own SseEmitter and writes raw-JSON
// REASONING_MESSAGE_START/CONTENT/END frames whose `type` literal matches
// the @ag-ui/core zod schema — the frontend then renders them via the
// `reasoningMessage` slot: CopilotKit's built-in card for
// `reasoning-default`, the custom amber ReasoningBlock for
// `reasoning-custom`. This is the Spring/Java reimplementation of ag2's
// reasoning_agent.py. The demo pages use the ids `reasoning-default` /
// `reasoning-custom`; both share the one reasoning backend.
// Mirrors ag2's route.ts `reasoningAgentNames`. NOTE:
// `tool-rendering-reasoning-chain`, `reasoning-default-render`, and
// `agentic-chat-reasoning` are NOT listed here — they are declared NSF in
// manifest.yaml (no parallel multi-tool-call streaming surface to interleave
// with reasoning frames on spring-ai for tool-rendering-reasoning-chain; no
// matching backend surface for the other two). With no registration the
// pages error loudly when probed — appropriate for not-supported features.
const reasoningAgentNames = ["reasoning-default", "reasoning-custom"];

// Agent names routed to the interrupt-adapted scheduling backend. Both
// gen-ui-interrupt and interrupt-headless share the same Spring AI scheduling
// agent; only the frontend UX differs (inline picker in chat vs. external
// popup driven by useFrontendTool).
const interruptAgentNames = ["gen-ui-interrupt", "interrupt-headless"];

const agents: Record<string, AbstractAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent();
}
for (const name of interruptAgentNames) {
  agents[name] = createAgent("/interrupt-adapted");
}
for (const name of reasoningAgentNames) {
  agents[name] = createAgent("/reasoning/");
}
// gen-ui-agent has a dedicated Java controller (GenUiAgentController @ /gen-ui-agent/run)
// that drives the set_steps state-card chain; override the shared-root registration.
agents["gen-ui-agent"] = createAgent("/gen-ui-agent/run");
// subagents likewise has a dedicated Java controller (SubagentsController @
// /subagents/run) that emits the research/writing/critique sub-agent
// TOOL_CALL chains the subagent cards render from. The shared-root
// registration above routed it to the default StreamingToolAgent, which has
// no research_agent/writing_agent/critique_agent tools — the run produced a
// final summary but zero subagent cards. Override to the dedicated controller.
agents["subagents"] = createAgent("/subagents/run");
agents["default"] = createAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- see main route.ts; published CopilotRuntime's `agents`
        // type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects
        // plain Records. Fixed in source, pending release.
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    // Log full details server-side (operators grep `errorId` to correlate),
    // but never echo `err.message` / `err.stack` back to the HTTP client —
    // that leaks internal paths, dependency versions, and stack traces.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = crypto.randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        scope: "copilotkit/route",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

"use client";

import { useAgent } from "@copilotkit/react-core/v2";
import { TodoList } from "./todo-list";

export function ExampleCanvas() {
  const { agent } = useAgent({ agentId: "beautiful-chat" });

  return (
    <div className="h-full overflow-y-auto bg-[--background]">
      <div className="max-w-4xl mx-auto px-8 py-10 h-full">
        <TodoList
          todos={agent.state?.todos || []}
          onUpdate={(updatedTodos) => agent.setState({ todos: updatedTodos })}
          isAgentRunning={agent.isRunning}
        />
      </div>
    </div>
  );
}

"use client";

import { useState, useRef, useEffect } from "react";
import { Card } from "../ui/card";
import { Checkbox } from "../ui/checkbox";
import { Button } from "../ui/button";
import { X } from "lucide-react";
import { cn } from "../../lib/utils";

interface Todo {
  id: string;
  title: string;
  description: string;
  emoji: string;
  status: "pending" | "completed";
}

interface TodoCardProps {
  todo: Todo;
  onToggleStatus: (todo: Todo) => void;
  onDelete: (todo: Todo) => void;
  onUpdateTitle: (todoId: string, title: string) => void;
  onUpdateDescription: (todoId: string, description: string) => void;
  onUpdateEmoji: (todoId: string, emoji: string) => void;
}

const EMOJI_OPTIONS = ["✅", "🔥", "🎯", "💡", "🚀"];

export function TodoCard({
  todo,
  onToggleStatus,
  onDelete,
  onUpdateTitle,
  onUpdateDescription,
  onUpdateEmoji,
}: TodoCardProps) {
  const [editingField, setEditingField] = useState<
    "title" | "description" | null
  >(null);
  const [editValue, setEditValue] = useState("");
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const isCompleted = todo.status === "completed";
  const truncatedDescription =
    todo.description.length > 120
      ? todo.description.slice(0, 120) + "..."
      : todo.description;

  const startEdit = (field: "title" | "description") => {
    setEditingField(field);
    setEditValue(field === "title" ? todo.title : todo.description);
  };

  const saveEdit = (field: "title" | "description") => {
    if (editValue.trim()) {
      if (field === "title") {
        onUpdateTitle(todo.id, editValue.trim());
      } else {
        onUpdateDescription(todo.id, editValue.trim());
      }
    }
    setEditingField(null);
    setEditValue("");
  };

  const cancelEdit = () => {
    setEditingField(null);
    setEditValue("");
  };

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height =
        textareaRef.current.scrollHeight + "px";
    }
  }, [editValue]);

  return (
    <Card
      className={cn(
        "group relative p-5 transition-all duration-150",
        isCompleted && "opacity-60",
      )}
    >
      {/* Delete — top right on hover */}
      <Button
        variant="ghost"
        size="icon"
        onClick={() => onDelete(todo)}
        className="absolute top-3 right-3 h-7 w-7 opacity-0 group-hover:opacity-100 transition-opacity"
        aria-label="Delete todo"
      >
        <X className="h-3.5 w-3.5" />
      </Button>

      {/* Emoji avatar */}
      <div className="relative inline-block mb-3">
        <button
          onClick={() => setShowEmojiPicker(!showEmojiPicker)}
          className={cn(
            "block text-3xl leading-none cursor-pointer rounded-xl p-2 transition-colors",
            isCompleted ? "bg-[var(--muted)]" : "bg-[var(--secondary)]",
          )}
          aria-label="Change emoji"
        >
          {todo.emoji}
        </button>

        {showEmojiPicker && (
          <div className="absolute top-0 left-full ml-2 z-10 flex gap-1 p-1.5 rounded-full bg-[var(--card)] border border-[var(--border)] shadow-lg">
            {EMOJI_OPTIONS.map((emoji) => (
              <button
                key={emoji}
                onClick={() => {
                  onUpdateEmoji(todo.id, emoji);
                  setShowEmojiPicker(false);
                }}
                className="text-lg w-8 h-8 flex items-center justify-center rounded-full cursor-pointer transition-colors hover:bg-[var(--secondary)]"
              >
                {emoji}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Title */}
      <div className="flex items-start gap-3">
        <Checkbox
          checked={isCompleted}
          onCheckedChange={() => onToggleStatus(todo)}
          className="mt-[2px]"
        />

        <div className="flex-1 min-w-0">
          {editingField === "title" ? (
            <input
              type="text"
              value={editValue}
              onChange={(e) => setEditValue(e.target.value)}
              onBlur={() => saveEdit("title")}
              onKeyDown={(e) => {
                if (e.key === "Enter") saveEdit("title");
                if (e.key === "Escape") cancelEdit();
              }}
              className="w-full text-base font-semibold focus:outline-none bg-transparent text-[var(--foreground)] border-b-2 border-[var(--primary)] pb-[2px]"
              autoFocus
              aria-label="Edit todo title"
            />
          ) : (
            <div
              onClick={() => startEdit("title")}
              className={cn(
                "text-base font-semibold cursor-text break-words leading-snug",
                isCompleted
                  ? "text-[var(--muted-foreground)] line-through"
                  : "text-[var(--foreground)]",
              )}
            >
              {todo.title}
            </div>
          )}

          {editingField === "description" ? (
            <textarea
              ref={textareaRef}
              value={editValue}
              onChange={(e) => setEditValue(e.target.value)}
              onBlur={() => saveEdit("description")}
              onKeyDown={(e) => {
                if (e.key === "Escape") cancelEdit();
              }}
              className="w-full mt-1.5 text-sm leading-relaxed focus:outline-none resize-none bg-transparent text-[var(--muted-foreground)] border-b-2 border-[var(--primary)] pb-[2px]"
              rows={1}
              autoFocus
              aria-label="Edit todo description"
            />
          ) : (
            <p
              onClick={() => startEdit("description")}
              className={cn(
                "mt-1.5 text-sm leading-relaxed cursor-text",
                isCompleted
                  ? "text-[var(--muted-foreground)] line-through"
                  : "text-[var(--muted-foreground)]",
              )}
            >
              {truncatedDescription}
            </p>
          )}
        </div>
      </div>
    </Card>
  );
}

