import java.util.ArrayList;
import java.util.UUID;

import static com.agui.server.EventFactory.runErrorEvent;
import static com.agui.server.EventFactory.runFinishedEvent;
import static com.agui.server.EventFactory.runStartedEvent;
import static com.agui.server.EventFactory.textMessageContentEvent;
import static com.agui.server.EventFactory.textMessageEndEvent;
import static com.agui.server.EventFactory.textMessageStartEvent;

/**
 * BYOC json-render demo controller.
 *
 * <p>Runs a zero-tool agent whose system prompt instructs the LLM to emit a
 * single JSON object matching the {@code @json-render/react} flat-spec format:
 * {@code { root, elements }}. The frontend parses the JSON and renders it
 * through a Zod-validated catalog of three components (MetricCard, BarChart,
 * PieChart).
 *
 * <p>The system prompt is explicit about JSON-only output; the frontend's
 * parser tolerates code fences and prose preamble defensively.
 */
@RestController
public class ByocJsonRenderController {

    private static final Logger log =
            LoggerFactory.getLogger(ByocJsonRenderController.class);

    private static final String AGENT_ID = "byoc_json_render";

    private final AgUiService agUiService;
    private final ChatModel chatModel;

    @Autowired
    public ByocJsonRenderController(AgUiService agUiService, ChatModel chatModel) {
        this.agUiService = agUiService;
        this.chatModel = chatModel;
    }

    @PostMapping("/byoc-json-render/run")
    public ResponseEntity<SseEmitter> run(@RequestBody AgUiParameters params) {
        MessageListFilter.filterNulls(params);
        ByocJsonRenderAgent agent = new ByocJsonRenderAgent(chatModel);
        SseEmitter emitter = agUiService.runAgent(agent, params);
        return ResponseEntity.ok()
                .cacheControl(CacheControl.noCache())
                .body(emitter);
    }

    /**
     * Per-request agent. Zero tools, JSON-object response format, sales-dashboard
     * system prompt. The model emits a single JSON object that the frontend's
     * {@code JsonRenderAssistantMessage} parses and renders via
     * {@code @json-render/react}.
     */
    static class ByocJsonRenderAgent extends PropagatingLocalAgent {

        private final ChatClient chatClient;

        ByocJsonRenderAgent(ChatModel chatModel) {
            super(AGENT_ID, new State(), new ArrayList<>());
            this.chatClient = ChatClient.builder(chatModel).build();
        }

        @Override
        protected void run(RunAgentInput input, AgentSubscriber subscriber) {
            this.combineMessages(input);

            String messageId = UUID.randomUUID().toString();
            String threadId = input.threadId();
            String runId = input.runId();

            // RUN_STARTED must precede every terminal RUN_ERROR — AG-UI clients
            // drop a RUN_ERROR that arrives without a started run, hanging the
            // UI. Emit it BEFORE reading the user message so the no-user-message
            // / null-content error paths still terminate a started run.
            this.emitEvent(runStartedEvent(threadId, runId), subscriber);

            // Null-guard the message + content: getLatestUserMessage only throws
            // AGUIException when NO user message exists; a present-but-empty or
            // null-content message returns normally and would NPE downstream.
            // Treat empty content as a handled error.
            String userContent;
            try {
                userContent = this.getLatestUserMessage(messages).getContent();
            } catch (AGUIException e) {
                log.error("Failed to read latest user message", e);
                this.emitEvent(runErrorEvent(String.format(
                        "agent run failed: %s (see server logs)",
                        e.getClass().getSimpleName())), subscriber);
                this.emitEvent(runFinishedEvent(threadId, runId), subscriber);
                subscriber.onRunFinalized(
                        new AgentSubscriberParams(input.messages(), state, this, input));
                return;
            }
            if (!StringUtils.hasText(userContent)) {
                log.warn("Latest user message has null/blank content");
                this.emitEvent(runErrorEvent(
                        "agent run failed: user message was empty"), subscriber);
                this.emitEvent(runFinishedEvent(threadId, runId), subscriber);
                subscriber.onRunFinalized(
                        new AgentSubscriberParams(input.messages(), state, this, input));
                return;
            }

            this.emitEvent(textMessageStartEvent(messageId, "assistant"), subscriber);

            AssistantMessage assistantMessage = new AssistantMessage();
            assistantMessage.setId(messageId);
            assistantMessage.setName(this.agentId);
            assistantMessage.setContent("");

            try {
                ChatResponse response = chatClient.prompt(
                            Prompt.builder().content(userContent).build())
                        .system(SYSTEM_PROMPT)
                        .call()
                        .chatResponse();

                if (response == null
                        || response.getResult() == null
                        || response.getResult().getOutput() == null) {
                    log.warn("ChatClient returned an empty result (no output)");
                    this.emitEvent(textMessageEndEvent(messageId), subscriber);
                    this.emitEvent(runErrorEvent(
                            "agent run failed: model returned an empty result"), subscriber);
                    this.emitEvent(runFinishedEvent(threadId, runId), subscriber);
                    subscriber.onRunFinalized(
                            new AgentSubscriberParams(input.messages(), state, this, input));
                    return;
                }

                String text = response.getResult().getOutput().getText();
                if (!StringUtils.hasText(text)) {
                    log.warn("ChatClient returned a null/blank text response");
                    this.emitEvent(textMessageEndEvent(messageId), subscriber);
                    this.emitEvent(runErrorEvent(
                            "agent run failed: model returned an empty response"), subscriber);
                    this.emitEvent(runFinishedEvent(threadId, runId), subscriber);
                    subscriber.onRunFinalized(
                            new AgentSubscriberParams(input.messages(), state, this, input));
                    return;
                }

                this.emitEvent(textMessageContentEvent(messageId, text), subscriber);
                assistantMessage.setContent(text);
            } catch (Exception e) {
                log.error("ChatClient call failed", e);
                this.emitEvent(textMessageEndEvent(messageId), subscriber);
                this.emitEvent(runErrorEvent(String.format(
                        "agent run failed: %s (see server logs)",
                        e.getClass().getSimpleName())), subscriber);
                this.emitEvent(runFinishedEvent(threadId, runId), subscriber);
                subscriber.onRunFinalized(
                        new AgentSubscriberParams(input.messages(), state, this, input));
                return;
            }

            this.emitEvent(textMessageEndEvent(messageId), subscriber);
            subscriber.onNewMessage(assistantMessage);
            this.emitEvent(runFinishedEvent(threadId, runId), subscriber);
            subscriber.onRunFinalized(
                    new AgentSubscriberParams(input.messages(), state, this, input));
        }
    }

    /**
     * System prompt instructing the LLM to emit a flat-spec JSON object for
     * {@code @json-render/react}. Matches the Python reference agent's prompt.
     */
    static final String SYSTEM_PROMPT = """
        You are a sales-dashboard UI generator for a BYOC json-render demo.

        When the user asks for a UI, respond with **exactly one JSON object** and
        nothing else — no prose, no markdown fences, no leading explanation. The
        object must match this schema (the "flat element map" format consumed by
        `@json-render/react`):

        {
          "root": "<id of the root element>",
          "elements": {
            "<id>": {
              "type": "<component name>",
              "props": { ... component-specific props ... },
              "children": [ "<id>", ... ]
            },
            ...
          }
        }

        Available components (use each name verbatim as "type"):

        - MetricCard
          props: { "label": string, "value": string, "trend": string | null }
          Example trend strings: "+12% vs last quarter", "-3% vs last month", null.

        - BarChart
          props: {
            "title": string,
            "description": string | null,
            "data": [ { "label": string, "value": number }, ... ]
          }

        - PieChart
          props: {
            "title": string,
            "description": string | null,
            "data": [ { "label": string, "value": number }, ... ]
          }

        Rules:

        1. Output **only** valid JSON. No markdown code fences. No text outside
           the object.
        2. Every id referenced in `root` or any `children` array must be a key
           in `elements`.
        3. For a multi-component dashboard, use a root MetricCard and list the
           charts in its `children` array, OR pick any element as root and list
           the others as its children. Do not emit orphan elements.
        4. Use realistic sales-domain values (revenue, pipeline, conversion,
           categories, months) — the demo is a sales dashboard.
        5. `children` is optional but when present must be an array of strings.
        6. Never invent component types outside the three listed above.

        ### Worked example — "Show me the sales dashboard with metrics and a revenue chart"

        {
          "root": "revenue-metric",
          "elements": {
            "revenue-metric": {
              "type": "MetricCard",
              "props": {
                "label": "Revenue (Q3)",
                "value": "$1.24M",
                "trend": "+18% vs Q2"
              },
              "children": ["revenue-bar"]
            },
            "revenue-bar": {
              "type": "BarChart",
              "props": {
                "title": "Monthly revenue",
                "description": "Revenue by month across Q3",
                "data": [
                  { "label": "Jul", "value": 380000 },
                  { "label": "Aug", "value": 410000 },
                  { "label": "Sep", "value": 450000 }
                ]
              }
            }
          }
        }

        ### Worked example — "Break down revenue by category as a pie chart"

        {
          "root": "category-pie",
          "elements": {
            "category-pie": {
              "type": "PieChart",
              "props": {
                "title": "Revenue by category",
                "description": "Share of total revenue by product category",
                "data": [
                  { "label": "Enterprise", "value": 540000 },
                  { "label": "SMB", "value": 310000 },
                  { "label": "Self-serve", "value": 220000 },
                  { "label": "Partner", "value": 170000 }
                ]
              }
            }
          }
        }

        ### Worked example — "Show me monthly expenses as a bar chart"

        {
          "root": "expense-bar",
          "elements": {
            "expense-bar": {
              "type": "BarChart",
              "props": {
                "title": "Monthly expenses",
                "description": "Operating expenses by month",
                "data": [
                  { "label": "Jul", "value": 210000 },
                  { "label": "Aug", "value": 225000 },
                  { "label": "Sep", "value": 240000 }
                ]
              }
            }
          }
        }

        Respond with the JSON object only.
        """.strip();
}

"use client";

import {
  CopilotKit,
  CopilotChat,
  useHumanInTheLoop,
} from "@copilotkit/react-core/v2";
import { z } from "zod";
import type { TimeSlot } from "./_components/time-picker-card";
import { TimePickerCard } from "./_components/time-picker-card";
import { generateFallbackSlots } from "../_shared/interrupt-fallback-slots";
import { useGenUiInterruptSuggestions } from "./suggestions";

export default function GenUiInterruptDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="gen-ui-interrupt">
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  useGenUiInterruptSuggestions();

  // This framework has no LangGraph-style `interrupt()` primitive, so the
  // LangGraph showcase's `useInterrupt({ renderInChat: true })` hook is
  // silently dead here — it listens for AG-UI `interrupt` events that this
  // backend never emits, leaving the chat stuck on the "[Scheduling...]"
  // tool-call placeholder.
  //
  // The backend instead exposes `schedule_meeting` as a tool the model is
  // instructed to call (Strategy B); the frontend registers a matching
  // `useHumanInTheLoop` here, renders the picker inline, and resolves the
  // call via `respond(...)`. UX matches LGP's interrupt-rendered card; the
  // mechanism differs.
  useHumanInTheLoop({
    agentId: "gen-ui-interrupt",
    name: "schedule_meeting",
    description:
      "Ask the user to pick a meeting time. The picker renders inline in " +
      "the chat; the chosen slot is returned to the agent so it can confirm.",
    parameters: z.object({
      topic: z
        .string()
        .describe("What the meeting is about (e.g. 'Intro with sales')"),
      attendee: z
        .string()
        .optional()
        .describe("Who the meeting is with (e.g. 'Alice')"),
    }),
    render: ({ args, respond }: any) => {
      // `TimePickerCard` here is the gen-ui-interrupt-specific variant
      // (under `_components/`) that gates buttons on its own internal
      // `picked`/`cancelled` state — it doesn't take a `status` prop like
      // the hitl-in-chat version. That's fine: the buttons stay clickable
      // until the user makes a choice and `respond(...)` resolves the
      // tool call.
      const topic = (args?.topic as string | undefined) ?? "a call";
      const attendee = args?.attendee as string | undefined;
      const slots = generateFallbackSlots();
      return (
        <TimePickerCard
          topic={topic}
          attendee={attendee}
          slots={slots}
          onSubmit={(result) => respond?.(result)}
        />
      );
    },
  });

  return (
    <CopilotChat agentId="gen-ui-interrupt" className="h-full rounded-2xl" />
  );
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";

// The Spring AI agent backend runs as a separate Java process.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

function createAgent(path = "/") {
  return new HttpAgent({ url: `${AGENT_URL}${path}` });
}

// Register the same Spring AI agent (backed by a single Spring-AI ChatClient
// on the Java side) under every name used by the demo pages in this package.
// Each entry proxies CopilotKit requests to the same Spring endpoint —
// per-demo behavior differences live on the frontend in the form of
// useFrontendTool / useRenderTool / useHumanInTheLoop / useAgentContext
// hooks registered on each page.
const agentNames = [
  "agentic_chat",
  "human_in_the_loop",
  "tool-rendering",
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-write",
  "shared-state-read-write",
  "shared-state-streaming",
  "subagents",
  "chat-customization-css",
  "frontend_tools",
  "frontend-tools-async",
  "hitl-in-chat",
  "hitl-in-app",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "headless-simple",
  "headless-complete",
  "readonly-state-agent-context",
  "auth",
  "open-gen-ui",
  "beautiful-chat",
  // NOTE: `tool-rendering-reasoning-chain` is intentionally NOT registered
  // here. It is declared NSF in manifest.yaml (no parallel multi-tool-call
  // streaming surface to interleave with reasoning frames on spring-ai), and
  // routing it to the default Spring agent at `/` silently bypassed the
  // reasoning workaround and rendered a regular tool-rendering run, hiding
  // the NSF. With no registration the page errors loudly when probed —
  // appropriate for a not-supported feature.
  "mcp-apps",
  "byoc-hashbrown",
];

// Reasoning agent names — backed by the dedicated Spring-AI reasoning
// controller at /reasoning (ReasoningController). The AG-UI Java SDK at
// Spring AI 1.0.1 has no REASONING_MESSAGE_* subtypes in its typed event
// model (the SDK only knows THINKING_*, which @ag-ui/client silently drops),
// so ReasoningController takes over its own SseEmitter and writes raw-JSON
// REASONING_MESSAGE_START/CONTENT/END frames whose `type` literal matches
// the @ag-ui/core zod schema — the frontend then renders them via the
// `reasoningMessage` slot: CopilotKit's built-in card for
// `reasoning-default`, the custom amber ReasoningBlock for
// `reasoning-custom`. This is the Spring/Java reimplementation of ag2's
// reasoning_agent.py. The demo pages use the ids `reasoning-default` /
// `reasoning-custom`; both share the one reasoning backend.
// Mirrors ag2's route.ts `reasoningAgentNames`. NOTE:
// `tool-rendering-reasoning-chain`, `reasoning-default-render`, and
// `agentic-chat-reasoning` are NOT listed here — they are declared NSF in
// manifest.yaml (no parallel multi-tool-call streaming surface to interleave
// with reasoning frames on spring-ai for tool-rendering-reasoning-chain; no
// matching backend surface for the other two). With no registration the
// pages error loudly when probed — appropriate for not-supported features.
const reasoningAgentNames = ["reasoning-default", "reasoning-custom"];

// Agent names routed to the interrupt-adapted scheduling backend. Both
// gen-ui-interrupt and interrupt-headless share the same Spring AI scheduling
// agent; only the frontend UX differs (inline picker in chat vs. external
// popup driven by useFrontendTool).
const interruptAgentNames = ["gen-ui-interrupt", "interrupt-headless"];

const agents: Record<string, AbstractAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent();
}
for (const name of interruptAgentNames) {
  agents[name] = createAgent("/interrupt-adapted");
}
for (const name of reasoningAgentNames) {
  agents[name] = createAgent("/reasoning/");
}
// gen-ui-agent has a dedicated Java controller (GenUiAgentController @ /gen-ui-agent/run)
// that drives the set_steps state-card chain; override the shared-root registration.
agents["gen-ui-agent"] = createAgent("/gen-ui-agent/run");
// subagents likewise has a dedicated Java controller (SubagentsController @
// /subagents/run) that emits the research/writing/critique sub-agent
// TOOL_CALL chains the subagent cards render from. The shared-root
// registration above routed it to the default StreamingToolAgent, which has
// no research_agent/writing_agent/critique_agent tools — the run produced a
// final summary but zero subagent cards. Override to the dedicated controller.
agents["subagents"] = createAgent("/subagents/run");
agents["default"] = createAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) => {
  const url = req.url;
  const contentType = req.headers.get("content-type");
  if (ROUTE_DEBUG) {
    console.log(
      `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
    );
  }

  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- see main route.ts; published CopilotRuntime's `agents`
        // type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects
        // plain Records. Fixed in source, pending release.
        agents,
      }),
      basePath: "/api/copilotkit",
      mode: "single-route",
    });

    const response = await copilotHandler(req);
    if (!response.ok) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    } else if (ROUTE_DEBUG) {
      console.log(`[copilotkit/route] Response status: ${response.status}`);
    }
    return response;
  } catch (error: unknown) {
    // Log full details server-side (operators grep `errorId` to correlate),
    // but never echo `err.message` / `err.stack` back to the HTTP client —
    // that leaks internal paths, dependency versions, and stack traces.
    const err = error instanceof Error ? error : new Error(String(error));
    const errorId = crypto.randomUUID();
    console.error(
      JSON.stringify({
        at: new Date().toISOString(),
        level: "error",
        scope: "copilotkit/route",
        errorId,
        message: err.message,
        stack: err.stack,
      }),
    );
    return NextResponse.json(
      { error: "internal runtime error", errorId },
      { status: 500 },
    );
  }
};

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

