  font-size: 2.4em;
  color: var(--halcyon-ember);
  line-height: 1;
}

/* Inline code — small ember chip on a tinted card. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose code {
  font-family: var(--halcyon-mono);
  font-size: 0.86em;
