"use client";

/**
 * Declarative Generative UI — A2UI Fixed Schema demo.
 *
 * In the fixed-schema flavor of A2UI, the component tree (schema) lives on
 * the frontend and the agent only streams *data* into the data model. The
 * flight card is ASSEMBLED from small sub-components in
 * `src/agents/a2ui_schemas/flight_schema.json` (Card > Column > [Title, Row, …]).
 *
 * - Definitions (zod schemas): `./a2ui/definitions.ts`
 * - Renderers (React): `./a2ui/renderers.tsx`
 * - Catalog wiring: `./a2ui/catalog.ts` (includes the basic catalog)
 * - Agent: `src/agents/a2ui_fixed.py` (emits an `a2ui_operations` container)
 *
 * Reference:
 * https://docs.copilotkit.ai/integrations/langgraph/generative-ui/a2ui/fixed-schema
 */

import React from "react";
import { CopilotKit } from "@copilotkit/react-core/v2";

import { catalog } from "./a2ui/catalog";
import { Chat } from "./chat";

export default function A2UIFixedSchemaDemo() {
  return (
    // `a2ui.catalog` wires the fixed catalog into the A2UI activity renderer.
    <CopilotKit
      runtimeUrl="/api/copilotkit-a2ui-fixed-schema"
      agent="a2ui-fixed-schema"
      a2ui={{ catalog: catalog }}
    >
      <div className="flex justify-center items-center h-screen w-full bg-neutral-50">
        <div className="h-full w-full max-w-4xl border-x border-neutral-200 bg-white">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

"""A2UI dynamic generation — Strands ``generate_a2ui`` tool.

Mirrors the per-demo specialization pattern used by ``gen_ui_agent.py`` and
``a2ui_dynamic.py``: this module owns the tool definition and its structured
error shape, and ``agent.py`` wires it into the shared ``StrandsAgent``
instance.

It also keeps this integration's slice of the A2UI docs honest. The
``backend-render-operations`` region below is what
`/aws-strands/generative-ui/a2ui/fixed-schema` renders, and a region starts at
the top of its file so the snippet carries its own imports (see the
marker-hoist sweep in 34b6418). While the tool lived in ``agent.py`` that made
the published snippet the whole 1688-line module; here the snippet is just the
tool (OSS-901).
"""

import json
import logging
import uuid
from typing import TypedDict

from strands import tool
from strands.types.tools import ToolContext
from tools.a2ui_catalog import read_client_catalog, validate_client_surface

# Shared implementation emits the A2UI v0.9 envelope detected by middleware.
from tools import build_a2ui_operations_from_tool_call

logger = logging.getLogger(__name__)


class _A2uiError(TypedDict):
    """Structured error contract shared with google-adk and langroid."""

    error: str
    message: str
    remediation: str


@tool(context=True)
def generate_a2ui(context: str, tool_context: ToolContext) -> str:
    """Generate a host-catalog A2UI surface, or a structured tool error.

    Args:
        context: Conversation context to generate UI from
    """
    try:
        catalog = read_client_catalog(
            tool_context.agent.state.get("agui_context") or []
        )
    except (ValueError, TypeError) as exc:
        return json.dumps(
            _A2uiError(
                error="a2ui_missing_catalog",
                message=str(exc),
                remediation="Register an A2UI catalog on the host and forward its component schema in request context.",
            )
        )

    surface_id = f"dashboard-{uuid.uuid4()}"
    # Read query results from the executing agent, not a model-authored summary.
    # The primary model often supplies only layout instructions in `context`.
    user_request = ""
    query_ids = set()
    query_results = []
    for message in tool_context.agent.messages:
        for block in message.get("content", []):
            if message.get("role") == "user" and isinstance(block.get("text"), str):
                user_request = block["text"]
            call = block.get("toolUse", {})
            if call.get("name") == "query_data":
                query_ids.add(call["toolUseId"])
            result = block.get("toolResult", {})
            if result.get("toolUseId") in query_ids:
                query_results.append(result.get("content", []))

    tool_schema = {
        "type": "function",
        "function": {
            "name": "render_a2ui",
            "description": "Render a dynamic A2UI v0.9 surface.",
            "parameters": {
                "type": "object",
                "properties": {
                    "catalogId": {"type": "string", "enum": [catalog["catalogId"]]},
                    "components": {"type": "array", "items": {"type": "object"}},
                    "data": {"type": "object"},
                },
                "required": ["catalogId", "components"],
            },
        },
    }

    # Wrap the OpenAI call so raw SDK / transport failures do NOT bubble up
    # through the strands tool machinery as uncaught exceptions. Return a
    # structured error with remediation instead — the LLM can surface this
    # to the user. Mirrors the google-adk and langroid sibling agents'
    # error-handling shape — keep all three in sync.
    #
    # Exception scope is broad on the SDK side but still bounded:
    #   * ``openai.OpenAIError`` covers config-time failures (e.g. from
    #     ``OpenAI()`` constructor when ``OPENAI_API_KEY`` is unset).
    #     ``APIError`` subclasses (RateLimitError, APIConnectionError,
    #     AuthenticationError, BadRequestError, etc.) are also caught via
    #     the broader ``except`` tuple. Verified against ``openai>=1.0`` —
    #     re-check hierarchy on major version bumps.
    #   * ``httpx.HTTPError`` covers transport failures (ConnectError,
    #     ReadTimeout, RemoteProtocolError) that can escape below the SDK's
    #     wrap layer in rare cases.
    # Programmer errors (AttributeError, NameError, TypeError from bad
    # kwargs, etc.) still propagate so bugs are not silently swallowed as
    # "LLM error". Note the client construction itself is inside the try
    # block for the same reason.
    import openai as _openai_mod
    import httpx as _httpx_mod

    try:
        client = _openai_mod.OpenAI()
        response = client.chat.completions.create(
            model="gpt-5-mini",
            messages=[
                {
                    "role": "system",
                    "content": (
                        "CRITICAL: Generate a flat A2UI v0.9 surface using only the host catalog below. "
                        "The root component must have id root. Never add a property not declared "
                        "in that component schema (other than id). Use the exact component properties "
                        "and actual query results supplied in the request. Do not invent data. "
                        "Calculate totals and chart series from those results. If a requested "
                        "metric cannot be derived, label it unavailable instead of leaving it blank.\n"
                        + json.dumps(catalog)
                    ),
                },
                {
                    "role": "user",
                    "content": (
                        user_request or context or "Generate a useful dashboard UI."
                    )
                    + "\n\nAuthoritative query_data results:\n"
                    + json.dumps(query_results),
                },
            ],
            tools=[tool_schema],
            tool_choice={"type": "function", "function": {"name": "render_a2ui"}},
        )
    except (_openai_mod.OpenAIError, _httpx_mod.HTTPError) as exc:
        logger.exception("generate_a2ui: OpenAI API call failed")
        return json.dumps(
            _A2uiError(
                error="a2ui_llm_error",
                message=f"Secondary A2UI LLM call failed: {exc.__class__.__name__}",
                remediation=(
                    "Verify OPENAI_API_KEY is set and the OpenAI service is reachable. "
                    "See server logs for the full traceback."
                ),
            )
        )

    if not response.choices:
        logger.warning("generate_a2ui: OpenAI response contained no choices")
        return json.dumps(
            _A2uiError(
                error="a2ui_empty_response",
                message="Secondary A2UI LLM returned no choices.",
                remediation="Retry; if this persists, check OpenAI status.",
            )
        )

    tool_calls = response.choices[0].message.tool_calls
    if not tool_calls:
        logger.warning(
            "generate_a2ui: OpenAI response had no tool_calls despite forced tool_choice"
        )
        return json.dumps(
            _A2uiError(
                error="a2ui_no_tool_call",
                message="Secondary A2UI LLM did not call render_a2ui.",
                remediation=(
                    "Retry the request. If this persists, verify the tool_choice "
                    "schema matches the OpenAI API contract."
                ),
            )
        )

    tool_call = tool_calls[0]
    try:
        args = json.loads(tool_call.function.arguments)
    except (ValueError, TypeError) as exc:
        logger.exception(
            "generate_a2ui: failed to parse render_a2ui tool arguments as JSON"
        )
        return json.dumps(
            _A2uiError(
                error="a2ui_invalid_arguments",
                message=f"Could not parse render_a2ui arguments: {exc}",
                remediation="Retry the request; the secondary LLM emitted malformed JSON.",
            )
        )

    try:
        if isinstance(args, dict):
            args["surfaceId"] = surface_id
        validate_client_surface(args, catalog)
    except ValueError as exc:
        return json.dumps(
            _A2uiError(
                error="a2ui_invalid_surface",
                message=str(exc),
                remediation="Generate a surface matching the supplied host catalog and component schemas.",
            )
        )

    result = build_a2ui_operations_from_tool_call(args)
    return json.dumps(result)

// Dedicated runtime for the Declarative Generative UI (A2UI fixed-schema) demo.

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import { HttpAgent } from "@ag-ui/client";

const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

function createAgent() {
  // Dedicated backend agent mounted at /a2ui-fixed-schema (see
  // src/agent_server.py). It owns the `display_flight` tool which emits its
  // own a2ui_operations envelope; the runtime A2UIMiddleware paints it. No
  // `a2ui: { injectA2UITool }` flag is needed — the envelope mechanism does
  // not require runtime tool injection.
  return new HttpAgent({ url: `${AGENT_URL}/a2ui-fixed-schema/` });
}

const a2uiFixedAgent = createAgent();
const agents = {
  "a2ui-fixed-schema": a2uiFixedAgent,
  default: a2uiFixedAgent,
};

export const POST = async (req: NextRequest) => {
  try {
    const copilotHandler = createCopilotRuntimeHandler({
      runtime: new CopilotRuntime({
        // @ts-ignore -- Published CopilotRuntime agents type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in source, pending release
        agents,
        // Enable the A2UIMiddleware so it detects the `a2ui_operations`
        // envelope the dedicated `a2ui_fixed_schema` backend agent's
        // `display_flight` tool returns and converts it into A2UI activity
        // events the page's catalog renders. `injectA2UITool: false` because
        // the agent emits the envelope itself (no generate_a2ui injection).
        // Mirrors the beautiful-chat route. Pin the catalog the page registers
        // so the middleware doesn't fall back to the unregistered basic catalog.
        a2ui: {
          injectA2UITool: false,
          defaultCatalogId: "copilotkit://flight-fixed-catalog",
        },
      }),
      basePath: "/api/copilotkit-a2ui-fixed-schema",
      mode: "single-route",
    });
    return await copilotHandler(req);
  } catch (error: unknown) {
    const e = error as { message?: string; stack?: string };
    return NextResponse.json(
      { error: e.message, stack: e.stack },
      { status: 500 },
    );
  }
};

import * as React from "react";

/**
 * ShadCN-style Badge primitive (inline-cloned for this demo).
 * Plain Tailwind classes, no `cn()`/`cva` helpers.
 */
type Variant = "default" | "secondary" | "outline" | "success";

const variantClasses: Record<Variant, string> = {
  default: "border-transparent bg-neutral-900 text-neutral-50",
  secondary: "border-transparent bg-neutral-100 text-neutral-900",
  outline: "border-neutral-200 text-neutral-700 bg-white",
  success: "border-transparent bg-emerald-100 text-emerald-700",
};

export interface BadgeProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: Variant;
}

export function Badge({
  className = "",
  variant = "default",
  ...props
}: BadgeProps) {
  return (
    <div
      className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium tracking-wide ${variantClasses[variant]} ${className}`}
      {...props}
    />
  );
}

import * as React from "react";

/**
 * ShadCN-style Button primitive (inline-cloned for this demo).
 * Plain Tailwind classes, no `cn()`/`cva` helpers.
 */
type Variant = "default" | "outline" | "secondary" | "ghost" | "success";
type Size = "default" | "sm" | "lg";

const baseClasses =
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-neutral-950 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-60";

const variantClasses: Record<Variant, string> = {
  default: "bg-neutral-900 text-neutral-50 shadow-sm hover:bg-neutral-800",
  outline:
    "border border-neutral-200 bg-white text-neutral-900 shadow-sm hover:bg-neutral-100",
  secondary: "bg-neutral-100 text-neutral-900 shadow-sm hover:bg-neutral-200",
  ghost: "hover:bg-neutral-100 hover:text-neutral-900",
  success:
    "bg-emerald-50 text-emerald-700 border border-emerald-200 shadow-sm hover:bg-emerald-50",
};

const sizeClasses: Record<Size, string> = {
  default: "h-10 px-4 py-2",
  sm: "h-8 rounded-md px-3 text-xs",
  lg: "h-11 rounded-md px-6",
};

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: Variant;
  size?: Size;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    { className = "", variant = "default", size = "default", ...props },
    ref,
  ) => {
    return (
      <button
        ref={ref}
        className={`${baseClasses} ${variantClasses[variant]} ${sizeClasses[size]} ${className}`}
        {...props}
      />
    );
  },
);
Button.displayName = "Button";

import * as React from "react";

/**
 * ShadCN-style Card primitive (inline-cloned for this demo).
 * Plain Tailwind classes, no `cn()`/`cva` helpers.
 */
export const Card = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className = "", ...props }, ref) => (
  <div
    ref={ref}
    className={`rounded-xl border border-neutral-200 bg-white text-neutral-950 shadow-sm ${className}`}
    {...props}
  />
));
Card.displayName = "Card";

export const CardHeader = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className = "", ...props }, ref) => (
  <div
    ref={ref}
    className={`flex flex-col space-y-1.5 p-5 pb-3 ${className}`}
    {...props}
  />
));
CardHeader.displayName = "CardHeader";

export const CardTitle = React.forwardRef<
  HTMLHeadingElement,
  React.HTMLAttributes<HTMLHeadingElement>
>(({ className = "", ...props }, ref) => (
  <h3
    ref={ref}
    className={`text-base font-semibold leading-none tracking-tight text-neutral-900 ${className}`}
    {...props}
  />
));
CardTitle.displayName = "CardTitle";

export const CardContent = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className = "", ...props }, ref) => (
  <div ref={ref} className={`p-5 pt-0 ${className}`} {...props} />
));
CardContent.displayName = "CardContent";

export const CardFooter = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className = "", ...props }, ref) => (
  <div
    ref={ref}
    className={`flex items-center p-5 pt-0 ${className}`}
    {...props}
  />
));
CardFooter.displayName = "CardFooter";

import * as React from "react";

/**
 * ShadCN-style Separator primitive (inline-cloned for this demo).
 * Plain Tailwind classes; uses a div instead of Radix to keep dependencies minimal.
 */
export interface SeparatorProps extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: "horizontal" | "vertical";
}

export function Separator({
  className = "",
  orientation = "horizontal",
  ...props
}: SeparatorProps) {
  const orientationClasses =
    orientation === "horizontal" ? "h-px w-full" : "h-full w-px";
  return (
    <div
      role="separator"
      aria-orientation={orientation}
      className={`shrink-0 bg-neutral-200 ${orientationClasses} ${className}`}
      {...props}
    />
  );
}

"use client";

/**
 * Fixed A2UI catalog — wires definitions to renderers.
 *
 * `includeBasicCatalog: true` merges CopilotKit's built-in components
 * (Card, Column, Row, Text, Button, Divider, …) into this catalog, so
 * the agent's fixed schema (src/agents/a2ui_schemas/flight_schema.json) can
 * compose custom and basic components interchangeably.
 */
import { createCatalog } from "@copilotkit/a2ui-renderer";

import { definitions } from "./definitions";
import { renderers } from "./renderers";

export const CATALOG_ID = "copilotkit://flight-fixed-catalog";

export const catalog = createCatalog(definitions, renderers, {
  catalogId: CATALOG_ID,
  includeBasicCatalog: true,
});

/**
 * A2UI catalog DEFINITIONS — platform-agnostic.
 *
 * Each entry declares a component name + its Zod props schema. The basic
 * catalog (Card, Column, Row, Text, Button, …) ships with CopilotKit and
 * is mixed in via `createCatalog(..., { includeBasicCatalog: true })`, so
 * we only declare the project-specific additions and the visual overrides
 * here. (Custom entries with the same name as a basic component override
 * the basic one — Catalog dedupes by `comp.name`, last-write-wins.)
 *
 * IMPORTANT — path bindings: fields that can be bound to a data-model path
 * (e.g. `{ path: "/origin" }` in the fixed schema JSON) must declare their
 * Zod type as a union of `z.string()` and `z.object({ path: z.string() })`.
 * The A2UI `GenericBinder` uses this union to detect the field as dynamic
 * and resolve the path against the current data model at render time. Using
 * plain `z.string()` causes the raw `{ path }` object to reach the
 * renderer, which React then throws on (error #31 "object with keys {path}").
 * This matches the canonical catalog's `DynString` helper:
 *   examples/integrations/langgraph-python/src/app/declarative-generative-ui/definitions.ts
 */
import { z } from "zod";
import type { CatalogDefinitions } from "@copilotkit/a2ui-renderer";

/**
 * Dynamic string: literal OR a data-model path binding. The GenericBinder
 * resolves path bindings to the actual value at render time.
 */
const DynString = z.union([z.string(), z.object({ path: z.string() })]);

export const definitions = {
  /**
   * Card override: gives the outer flight-card container a ShadCN look
   * (rounded-xl, neutral-200 border, soft shadow). The basic catalog's
   * Card uses inline styles; overriding here lets the demo's renderer
   * adopt the demo's Tailwind aesthetic without touching the schema JSON.
   */
  Card: {
    description: "A container card with a single child.",
    props: z.object({
      child: z.string(),
    }),
  },
  Title: {
    description: "A prominent heading for the flight card.",
    props: z.object({
      text: DynString,
    }),
  },
  Airport: {
    description: "A 3-letter airport code, displayed large.",
    props: z.object({
      code: DynString,
    }),
  },
  Arrow: {
    description: "A right-pointing arrow used between airports.",
    props: z.object({}),
  },
  AirlineBadge: {
    description: "A pill-styled airline name tag.",
    props: z.object({
      name: DynString,
    }),
  },
  PriceTag: {
    description: "A stylized price display (e.g. '$289').",
    props: z.object({
      amount: DynString,
    }),
  },
  /**
   * Button override: swaps in an ActionButton renderer that tracks
   * its own `done` state so clicking "Book flight" visually updates to
   * a "Booked ✓" confirmation. The basic catalog's Button is stateless,
   * so without this override the click fires the action but the button
   * looks unchanged. Mirrors the pattern in beautiful-chat
   * (src/app/demos/beautiful-chat/declarative-generative-ui/renderers.tsx).
   */
  Button: {
    description:
      "An interactive button with an action event. Use 'child' with a Text component ID for the label. After click, the button shows a confirmation state.",
    props: z.object({
      child: z
        .string()
        .describe(
          "The ID of the child component (e.g. a Text component for the label).",
        ),
      variant: z.enum(["primary", "secondary", "ghost"]).optional(),
      // Union with { event } so GenericBinder resolves this as ACTION → callable () => void.
      action: z
        .union([
          z.object({
            event: z.object({
              name: z.string(),
              context: z.record(z.any()).optional(),
            }),
          }),
          z.null(),
        ])
        .optional(),
    }),
  },
} satisfies CatalogDefinitions;

export type Definitions = typeof definitions;

"use client";

import { CopilotChat } from "@copilotkit/react-core/v2";
import { useA2UIFixedSchemaSuggestions } from "./suggestions";

export function Chat() {
  useA2UIFixedSchemaSuggestions();
  return (
