"use client";

import React from "react";
import {
  CopilotKit,
  useAgent,
  UseAgentUpdate,
} from "@copilotkit/react-core/v2";

import { DemoLayout } from "./demo-layout";
import { useSharedStateStreamingSuggestions } from "./suggestions";

interface StreamingAgentState {
  document?: string;
}

export default function SharedStateStreamingDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="shared-state-streaming">
      <DemoContent />
    </CopilotKit>
  );
}

function DemoContent() {
  // Subscribe to BOTH state changes and run-status changes. The former
  // drives the per-token document rerender; the latter toggles the
  // "LIVE" badge when the agent starts / stops.
  const { agent } = useAgent({
    agentId: "shared-state-streaming",
    updates: [UseAgentUpdate.OnStateChanged, UseAgentUpdate.OnRunStatusChanged],
  });

  useSharedStateStreamingSuggestions();

  const agentState = agent.state as StreamingAgentState | undefined;
  const document = agentState?.document ?? "";
  const isRunning = agent.isRunning;

  return <DemoLayout document={document} isStreaming={isRunning} />;
}

"use client";

import React from "react";
import { CopilotSidebar } from "@copilotkit/react-core/v2";

import { DocumentView } from "./document-view";

interface DemoLayoutProps {
  document: string;
  isStreaming: boolean;
}

export function DemoLayout({ document, isStreaming }: DemoLayoutProps) {
  return (
    <div className="h-screen w-full bg-gray-50">
      <main className="flex h-full min-h-0 flex-col p-4">
        <DocumentView content={document} isStreaming={isStreaming} />
      </main>
      <CopilotSidebar
        agentId="shared-state-streaming"
        defaultOpen={true}
        labels={{
          chatInputPlaceholder: "Ask me to write something...",
        }}
      />
    </div>
  );
}

"use client";

import React from "react";

export interface DocumentViewProps {
  /** Current document text. Grows token-by-token while the agent is streaming. */
  content: string;
  /** True while the agent is actively running. Used to show a live indicator. */
  isStreaming: boolean;
}

/**
 * Live document panel — renders the `document` slot of agent state.
 *
 * On every streamed token, the parent re-renders this component with a
 * longer `content` string. We surface:
 *
 *   - a "LIVE" badge + blinking cursor while the agent is running
 *   - the current character count (a cheap but visible token-ish counter)
 *   - the growing document text
 *
 * Together they make the per-token delta stream obvious to a viewer.
 */
export function DocumentView({ content, isStreaming }: DocumentViewProps) {
  const charCount = content.length;

  return (
    <div
      data-testid="document-view"
      className="w-full h-full flex flex-col bg-white rounded-2xl shadow-sm border border-[#DBDBE5] overflow-hidden"
    >
      <div className="flex items-center justify-between px-6 py-3 border-b border-[#E9E9EF] bg-[#FAFAFC]">
        <div className="flex items-center gap-3">
          <span className="text-lg font-semibold text-[#010507]">Document</span>
          {isStreaming && (
            <span
              data-testid="document-live-badge"
              className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-[#FA5F67] text-white text-[10px] font-semibold uppercase tracking-[0.14em]"
            >
              <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse" />
              Live
            </span>
          )}
        </div>
        <span
          data-testid="document-char-count"
          className="text-xs text-[#838389] font-mono"
        >
          {charCount} chars
        </span>
      </div>

      <div className="flex-1 overflow-y-auto p-6">
        {content.length === 0 && !isStreaming ? (
          <p className="text-[#838389] italic">
            Ask the agent to write something — its output will stream here token
            by token.
          </p>
        ) : (
          <div
            data-testid="document-content"
            className="whitespace-pre-wrap text-[#010507] leading-relaxed font-serif"
          >
            {content}
            {isStreaming && (
              <span className="inline-block w-2 h-5 bg-[#010507] ml-0.5 align-text-bottom animate-pulse" />
            )}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export function useSharedStateStreamingSuggestions() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Write a short poem",
        message: "Write a short poem about autumn leaves.",
      },
      {
        title: "Draft an email",
        message:
          "Draft a polite email declining a meeting next Tuesday afternoon.",
      },
      {
        title: "Explain quantum computing",
        message:
          "Write a 2-paragraph explanation of quantum computing for a curious teenager.",
      },
    ],
    available: "always",
  });
}

