"use client";

// Chat Customization (CSS) — every visual choice in this demo lives in
// theme.css and is scoped to the `.chat-css-demo-scope` wrapper. The page
// intentionally stays minimal so the contrast against the default look
// comes entirely from the stylesheet.
//
// https://docs.copilotkit.ai/custom-look-and-feel/customize-built-in-ui-components

import React from "react";
import { CopilotKit, CopilotChat } from "@copilotkit/react-core/v2";
import "./theme.css";

export default function ChatCustomizationCssDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="chat-customization-css">
      <div className="flex justify-center items-center h-screen w-full bg-white p-6">
        <div className="chat-css-demo-scope h-full w-full max-w-4xl">
          <CopilotChat
            agentId="chat-customization-css"
            className="h-full"
            attachments={{ enabled: true }}
          />
        </div>
      </div>
    </CopilotKit>
  );
}

/**
 * Agent factories for the Strands TypeScript showcase backend.
 *
 * `buildShowcaseAgent` is the single shared agent that serves the vast
 * majority of demos (the frontend differentiates each demo via
 * useFrontendTool / useRenderTool / useHumanInTheLoop / useAgentContext).
 * It mirrors the Python sibling's `build_showcase_agent` minus A2UI.
 *
 * The tool-free specialized agents (voice, byoc-hashbrown, byoc-json-render)
 * are mounted on dedicated sub-paths by `server.ts`.
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Agent, tool } from "@strands-agents/sdk";
import { z } from "zod";
import type { RunAgentInput } from "@ag-ui/core";
import { StrandsAgent } from "@ag-ui/aws-strands";
import type { StrandsAgentConfig } from "@ag-ui/aws-strands";
import {
  A2UI_OPERATIONS_KEY,
  createSurface,
  updateComponents,
  updateDataModel,
} from "@ag-ui/a2ui-toolkit";
import { createModel } from "./model-factory";
import { SHOWCASE_TOOLS } from "./tools";
import { BoardStateStrandsAgent } from "./todo-state-sync";
import {
  withStateContext,
  salesStateFromArgs,
  salesStateFromResult,
  notesStateFromArgs,
  stepsStateFromArgs,
  documentStateFromArgs,
  makeSubagentStateFromResult,
} from "./state";
import {
  SYSTEM_PROMPT,
  VOICE_SYSTEM_PROMPT,
  BYOC_HASHBROWN_SYSTEM_PROMPT,
  BYOC_JSON_RENDER_SYSTEM_PROMPT,
} from "./prompts";

export class ShowcaseStrandsAgent extends BoardStateStrandsAgent {
  override async *run(inputData: RunAgentInput) {
    // The adapter exposes context during model calls and restores history afterward.
    yield* super.run(withStateContext(inputData));
  }
}

export async function buildShowcaseAgent(
  openaiApi: "chat" | "responses" = "chat",
): Promise<StrandsAgent> {
  const config: StrandsAgentConfig = {
    toolBehaviors: {
      // The tool keeps the sales pipeline in appState; this snapshot, built
      // from the args, only carries it to the UI. Keep the call/result in
      // message snapshots too so completed threads can replay them.
      manage_sales_todos: {
        stateFromArgs: salesStateFromArgs,
      },
      get_sales_todos: { stateFromResult: salesStateFromResult },
      // Shared State (Read + Write) — notes panel.
      set_notes: { stateFromArgs: notesStateFromArgs },
      // gen-ui-agent — live progress card driven by set_steps transitions.
      set_steps: { stateFromArgs: stepsStateFromArgs },
      // shared-state-streaming — stream the document string into state.
      write_document: { stateFromArgs: documentStateFromArgs },
      // Sub-agents — append a delegation entry carrying the actual output.
      research_agent: {
        stateFromResult: makeSubagentStateFromResult("research_agent"),
      },
      writing_agent: {
        stateFromResult: makeSubagentStateFromResult("writing_agent"),
      },
      critique_agent: {
        stateFromResult: makeSubagentStateFromResult("critique_agent"),
      },
    },
  };

  const strandsAgent = new Agent({
    model: await createModel({ openaiApi }),
    systemPrompt: SYSTEM_PROMPT,
    tools: SHOWCASE_TOOLS,
  });

  return new ShowcaseStrandsAgent({
    agent: strandsAgent,
    name: "strands_agent",
    description:
      "A polished CopilotKit demo assistant: chat, tools, shared state, HITL, sub-agents.",
    config,
  });
}

/**
 * Published Strands Chat Completions drops parallel call indices before native
 * aggregation. Responses preserves each call and emits complete, ordered blocks.
 * Rich chat intentionally buffers tool arguments; the shared agent keeps Chat
 * for demos that demonstrate progressive state and UI updates.
 */
export function buildRichChatAgent(): Promise<StrandsAgent> {
  return buildShowcaseAgent("responses");
}

/** Tool-free agent for the voice demo (transcription + basic chat). */
export async function buildVoiceAgent(): Promise<StrandsAgent> {
  const strandsAgent = new Agent({
    model: await createModel(),
    systemPrompt: VOICE_SYSTEM_PROMPT,
    tools: [],
  });
  return new StrandsAgent({
    agent: strandsAgent,
    name: "voice_agent",
    description: "Simple assistant for the voice demo — no tools.",
  });
}

/** Tool-free hashbrown UI-kit envelope generator (declarative-hashbrown). */
export async function buildByocHashbrownAgent(): Promise<StrandsAgent> {
  const strandsAgent = new Agent({
    model: await createModel(),
    systemPrompt: BYOC_HASHBROWN_SYSTEM_PROMPT,
    tools: [],
  });
  return new StrandsAgent({
    agent: strandsAgent,
    name: "byoc_hashbrown",
    description:
      "Hashbrown UI-kit envelope generator for the declarative-hashbrown demo.",
  });
}

/** Tool-free json-render flat-spec generator (declarative-json-render). */
export async function buildByocJsonRenderAgent(): Promise<StrandsAgent> {
  const strandsAgent = new Agent({
    model: await createModel(),
    systemPrompt: BYOC_JSON_RENDER_SYSTEM_PROMPT,
    tools: [],
  });
  return new StrandsAgent({
    agent: strandsAgent,
    name: "byoc_json_render",
    description:
      "json-render flat-spec generator for the declarative-json-render demo.",
  });
}

// ---------------------------------------------------------------------------
// A2UI Fixed Schema (declarative-generative-ui) — dedicated backend tool.
// ---------------------------------------------------------------------------
//
// Unlike the dynamic A2UI demo (which relies on the adapter auto-injecting a
// `generate_a2ui` tool to *generate* a surface), the fixed-schema demo wires a
// single plain backend tool — `display_flight` — that returns the
// `a2ui_operations` envelope (createSurface -> updateComponents ->
// updateDataModel). The component tree is fixed and authored ahead of time
// (./a2ui_schemas/flight_schema.json); only the *data* changes per call. The
// runtime A2UIMiddleware detects the envelope in the tool result and paints.
// No sub-agent, no generation, no `generate_a2ui` injection.
//
// The schema's component names + data paths must match the showcase frontend
// catalog at src/app/demos/a2ui-fixed-schema/a2ui/{definitions,renderers,
// catalog}.ts — catalog id `copilotkit://flight-fixed-catalog`. This mirrors
// the canonical langgraph-python demo (src/agents/a2ui_fixed.py).

const _A2UI_DIR = dirname(fileURLToPath(import.meta.url));

const A2UI_FIXED_CATALOG_ID = "copilotkit://flight-fixed-catalog";
const A2UI_FIXED_SURFACE_ID = "flight-fixed-schema";

// Fixed, pre-authored component layout. Loaded from JSON so it can be authored
// and reviewed independently of the agent code.
const FLIGHT_SCHEMA: Array<Record<string, unknown>> = JSON.parse(
  readFileSync(join(_A2UI_DIR, "a2ui_schemas", "flight_schema.json"), "utf-8"),
);

const A2UI_FIXED_SYSTEM_PROMPT =
  "You help users find flights. When asked about a flight, call " +
  "`display_flight` exactly ONCE with origin, destination, airline, and " +
  'price. Use short airport codes (e.g. "SFO", "JFK") for ' +
  'origin/destination and a price string like "$289". The tool\'s return ' +
  "value is an A2UI surface descriptor — the flight card is already rendered " +
  "to the user; do NOT call `display_flight` again for the same trip and do " +
  "NOT repeat the flight details in text. After the tool returns, reply with " +
  "one short confirmation sentence and stop.";

/**
 * Dedicated agent for the A2UI fixed-schema demo. Returns the envelope as a
 * plain OBJECT (not a JSON string): the Strands TS SDK wraps an object
 * tool-return in a `json` content block the adapter reads and re-stringifies
 * into the TOOL_CALL_RESULT the client A2UIMiddleware scans for
 * `a2ui_operations`. (A bare string return lands in no content block and the
 * result comes through empty — unlike the Python SDK, which wraps strings.)
 */
export async function buildA2uiFixedSchemaAgent(): Promise<StrandsAgent> {
  const displayFlight = tool({
    name: "display_flight",
    description:
      "Show a flight card for the given trip. Use short airport codes " +
      '(e.g. "SFO", "JFK") for origin/destination and a price string like ' +
      '"$289". After this tool returns, the flight card is already rendered ' +
      "to the user via the A2UI surface — do NOT call it again for the same " +
      "flight; reply with one short confirmation sentence and stop.",
    inputSchema: z.object({
      origin: z.string().describe('Origin airport code, e.g. "SFO".'),
      destination: z.string().describe('Destination airport code, e.g. "JFK".'),
      airline: z.string().describe('Airline name, e.g. "United".'),
      price: z.string().describe('Price string, e.g. "$289".'),
    }),
    callback: ({ origin, destination, airline, price }) => ({
      [A2UI_OPERATIONS_KEY]: [
        createSurface(A2UI_FIXED_SURFACE_ID, A2UI_FIXED_CATALOG_ID),
        updateComponents(A2UI_FIXED_SURFACE_ID, FLIGHT_SCHEMA),
        updateDataModel(A2UI_FIXED_SURFACE_ID, {
          origin,
          destination,
          airline,
          price,
        }),
      ],
    }),
  });

  const strandsAgent = new Agent({
    // Chat Completions API: the Responses adapter buffers tool-call argument
    // deltas, which would defeat A2UI's progressive surface streaming.
    model: await createModel({ openaiApi: "chat" }),
    systemPrompt: A2UI_FIXED_SYSTEM_PROMPT,
    tools: [displayFlight],
  });

  return new StrandsAgent({
    agent: strandsAgent,
    name: "a2ui_fixed_schema",
    description:
      "A2UI surface from a fixed, pre-authored schema (direct backend tool)",
  });
}

// ---------------------------------------------------------------------------
// A2UI Dynamic Schema (declarative-gen-ui) — adapter auto-injects generate_a2ui.
// ---------------------------------------------------------------------------
//
// Unlike the fixed-schema demo (which wires a `display_flight` tool returning a
// pre-authored envelope), the dynamic demo lets the agent *generate* the
// surface layout on the fly. The Next.js route
// (app/api/copilotkit-declarative-gen-ui/route.ts) sets
// `a2ui: { injectA2UITool: true, defaultCatalogId: "declarative-gen-ui-catalog" }`;
// the runtime forwards the flag, the Strands adapter auto-injects a
// `generate_a2ui` tool and drives a secondary render planner. The
// `config.a2ui` block below supplies the catalog id stamped into generated
// surfaces and the composition guide that teaches the planner the page's
// catalog. Mirrors the ag-ui dynamic-schema reference example.
//
// The compositionGuide MUST describe the catalog the page registers at
// src/app/demos/declarative-gen-ui/a2ui/{definitions,renderers,catalog}.ts
// (catalog id `declarative-gen-ui-catalog`): Card / StatusBadge / Metric /
// InfoRow / PrimaryButton / PieChart / BarChart / DataTable, composed inside
// the basic catalog's Row / Column / Text (`includeBasicCatalog: true`).
//
// Grounding dataset + composition rules are kept in spirit with the frontend
// `sales-context.ts` (SALES_DATASET + COMPOSITION_RULES) the page registers via
// `useAgentContext`. The frontend context steers the PRIMARY agent; this
// compositionGuide is the channel the adapter feeds to the secondary
// `render_a2ui` planner (it gets `guidelines`, not the frontend App Context),
// so the planner is self-contained.

const A2UI_DYNAMIC_CATALOG_ID = "declarative-gen-ui-catalog";

const A2UI_DYNAMIC_SALES_DATASET = `Vantage Threads (fictional B2B apparel company) — Q2 sales data. Ground every visual in these numbers; invent only plausible details consistent with them.
- Quarterly revenue: $4.2M (up 12% QoQ). New customers: 186 (up 8%). Win rate: 31% (down 2pts). Avg deal size: $22.6k (up 5%).
- Revenue by region: North America $1.9M, EMEA $1.3M, APAC $720k, LATAM $280k.
- Monthly revenue: Jan $1.21M, Feb $1.34M, Mar $1.65M, Apr $1.38M, May $1.42M, Jun $1.40M.
- Reps (vs quota): Dana Whitfield 124%, Marcus Lee 108%, Priya Sharma 97%, Tom Okafor 88%, Elena Vasquez 71%.
- At-risk: total $615k ARR across 3 accounts — Northwind Retail ($340k renewal, no contact 6 weeks; severity high), Cascadia Outfitters ($180k, champion left; severity medium), Atlas Goods ($95k, stalled legal review; severity medium).
- Biggest account: Meridian Apparel Group — owner Dana Whitfield, region North America, ARR $612k, renewal Sep 30, last contact 3 days ago, health green, 4 open opportunities worth $210k.
- Meridian revenue by product line: Outerwear $260k, Footwear $180k, Accessories $112k, Custom $60k.`;

const A2UI_DYNAMIC_COMPOSITION_RULES = `Use ONLY these exact component names (the registered catalog — any other name fails to render): Card, Column, Row, Text, Metric, PieChart, BarChart, DataTable, StatusBadge, InfoRow, PrimaryButton. The single-value KPI tile component is named exactly "Metric" (NOT "MetricTile" or "MetricCard").

Pick A2UI components by the shape of the question — never ask which chart the user wants:
1. Overall snapshot / "sales dashboard" → a Column (gap 16) whose first child is a Row (gap 16) of 4 Metric components (each with trend + trendValue), followed by a Row with a PieChart (revenue by region) next to a BarChart (monthly revenue, all six months Jan-Jun). Do NOT wrap the dashboard in a surrounding Card — the charts carry their own card chrome. Do NOT use StatusBadge, DataTable, or InfoRow here.
2. Rep / team performance → a Column (gap 16) with a Card containing a DataTable (columns: rep, attainment, pipeline) next to or above a BarChart of quota attainment % per rep — no StatusBadge or InfoRow.
3. Risk / health checks → a Column (gap 16): first a Row (gap 16) of 3 Metric components (ARR at risk $615k trend down, accounts at risk 3, biggest exposure Northwind $340k), then a Row (gap 16) with one compact Card per at-risk account (title = account name, subtitle = ARR at stake) containing a StatusBadge (error for high severity, warning otherwise) above a one-line Text with the reason and the recommended next action — no DataTable or InfoRow.
4. Single account/entity details → a Row (gap 16) with a Card of InfoRow facts (owner, region, ARR, renewal date, last contact) next to a PieChart of that account's revenue by product line — no DataTable or StatusBadge.
5. Part-of-whole follow-ups → PieChart; trends or comparisons over time/categories → BarChart.
Compose generously — a dashboard should feel like a real analytics product, not a single widget.`;

const A2UI_DYNAMIC_COMPOSITION_GUIDE = `${A2UI_DYNAMIC_SALES_DATASET}\n\n${A2UI_DYNAMIC_COMPOSITION_RULES}`;

// Mirrors the langgraph-python demo's a2ui_dynamic.py SYSTEM_PROMPT.
const A2UI_DYNAMIC_SYSTEM_PROMPT =
  "You are the embedded sales analyst for Vantage Threads, the fictional " +
  "B2B apparel company described in your App Context. Answer every " +
  "business question by calling `generate_a2ui` to draw a rich visual " +
  "surface, and keep the chat reply to one short sentence.\n\n" +
  "Ground every number in the sales dataset from App Context — never " +
  "invent figures that contradict it. Follow the dashboard composition " +
  "rules from App Context when choosing components: pick the component " +
  "by the shape of the question (snapshot → composed KPI dashboard with " +
  "charts; team performance → table; risk → status badges; single " +
  "account → info rows; part-of-whole → pie; trend/comparison → bar). " +
  "Never ask the user which chart they want. `generate_a2ui` takes no " +
  "arguments and handles the rendering automatically. Compose " +
  "generously — a dashboard should feel like a real analytics product, " +
  "not a single widget.";

/**
 * Dedicated agent for the A2UI dynamic-schema demo. Wires NO `generate_a2ui`
 * tool — the runtime's `injectA2UITool: true` makes the adapter auto-inject it
 * and drive a secondary render planner to GENERATE the surface.
 */
export async function buildA2uiDynamicAgent(): Promise<StrandsAgent> {
  const strandsAgent = new Agent({
    // Chat Completions API: the Responses adapter buffers tool-call argument
    // deltas, which would defeat A2UI's progressive surface streaming.
    model: await createModel({ openaiApi: "chat" }),
    systemPrompt: A2UI_DYNAMIC_SYSTEM_PROMPT,
  });

  const config: StrandsAgentConfig = {
    a2ui: {
      defaultCatalogId: A2UI_DYNAMIC_CATALOG_ID,
      guidelines: { compositionGuide: A2UI_DYNAMIC_COMPOSITION_GUIDE },
    },
  };

  return new StrandsAgent({
    agent: strandsAgent,
    name: "a2ui_dynamic_schema",
    description:
      "Dynamic A2UI surfaces generated on the fly (auto-injected tool)",
    config,
  });
}

// ---------------------------------------------------------------------------
// A2UI Error Recovery (a2ui-recovery) — adapter auto-injects + runs recovery.
// ---------------------------------------------------------------------------
//
// Same auto-injected dynamic-schema setup as buildA2uiDynamicAgent, but the
// aimock fixtures force the inner render_a2ui to emit free-form/sloppy args
// (heal pill) or a structurally-invalid surface on every attempt (exhaust
// pill). The Strands adapter runs the toolkit validate->retry recovery loop on
// its auto-inject path (default 3 attempts) and returns the
// a2ui_recovery_exhausted hard-fail envelope when the cap is hit — so this
// agent wires NO tool, unlike the langgraph/ADK siblings (which own the tool
// explicitly via getA2UITools + injectA2UITool:false). Mirrors the ag-ui dojo
// aws-strands recovery example.

/**
 * Dedicated agent for the A2UI error-recovery demo. Wires NO `generate_a2ui`
 * tool — the runtime's `injectA2UITool: true` makes the adapter auto-inject it,
 * drive the secondary render planner, and run the recovery loop.
 */
export async function buildA2uiRecoveryAgent(): Promise<StrandsAgent> {
  const strandsAgent = new Agent({
    // Chat Completions API: the Responses adapter buffers tool-call argument
    // deltas, which would defeat A2UI's progressive surface streaming.
    model: await createModel({ openaiApi: "chat" }),
    systemPrompt: A2UI_DYNAMIC_SYSTEM_PROMPT,
  });

  const config: StrandsAgentConfig = {
    a2ui: {
      defaultCatalogId: A2UI_DYNAMIC_CATALOG_ID,
      guidelines: { compositionGuide: A2UI_DYNAMIC_COMPOSITION_GUIDE },
    },
  };

  return new StrandsAgent({
    agent: strandsAgent,
    name: "a2ui_recovery",
    description:
      "Dynamic A2UI with automatic error recovery (auto-injected tool)",
    config,
  });
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent, HttpAgentConfig } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";
import { AsyncLocalStorage } from "node:async_hooks";

// The agent backend runs as a separate process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

// Per-request inbound x-* forwarding over the HttpAgent proxy hop. The Next
// route is a bare proxy; the model call happens in the Express agent (:8000).
// @ag-ui/client's HttpAgent `headers` are STATIC (construction-time), so the
// per-request seam is its `fetch` option: a custom fetch that reads an
// AsyncLocalStorage snapshot (seeded by the POST handler below) and injects the
// inbound x-* (incl. x-aimock-strict / x-test-id / x-diag-*) onto the outbound
// POST. These then arrive on req.headers at the Express endpoint, where the
// agent-side middleware reads them. Byte-identical to a plain fetch when no x-*
// are in scope, so demo traffic proxies unchanged.
const proxyHeaders = new AsyncLocalStorage<Record<string, string>>();

function extractXHeaders(req: NextRequest): Record<string, string> {
  const out: Record<string, string> = {};
  req.headers.forEach((value, key) => {
    const lower = key.toLowerCase();
    if (lower.startsWith("x-")) out[lower] = value;
  });
  return out;
}

const forwardingProxyFetch: NonNullable<HttpAgentConfig["fetch"]> = (
  url,
  requestInit,
) => {
  const forwarded = proxyHeaders.getStore() ?? {};
  if (Object.keys(forwarded).length === 0) return fetch(url, requestInit);
  const merged = new Headers(requestInit?.headers);
  for (const [k, v] of Object.entries(forwarded)) {
    if (!merged.has(k)) merged.set(k, v);
  }
  return fetch(url, { ...requestInit, headers: merged });
};

function createAgent(path = "/") {
  return new HttpAgent({
    url: `${AGENT_URL}${path}`,
    fetch: forwardingProxyFetch,
  });
}

// Register the same agent under all names used by demo pages.
// Strands runs a single shared backend agent; per-demo differentiation
// happens on the frontend (useFrontendTool / useRenderTool / useHumanInTheLoop
// / useAgentContext / A2UI catalogs). Every demo page's `agent=` prop must
// resolve to a name in this list.
const agentNames = [
  // Original blitz set
  "agentic_chat",
  "human_in_the_loop",
  "tool-rendering",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-write",
  "shared-state-streaming",
  "subagents",
  // Chat UI / chrome demos
  "chat-customization-css",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "headless-simple",
  "headless-complete",
  // Reasoning
  "reasoning-default",
  "reasoning-custom",
  // Frontend tools
  "frontend_tools",
  "frontend-tools-async",
  // HITL
  "hitl-in-chat",
  "hitl-in-app",
  // Tool rendering variants
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "tool-rendering-reasoning-chain",
  // State / context
  "readonly-state-agent-context",
  "shared-state-read-write",
  // Modalities
  "multimodal",
  "voice",
  // Misc
  "auth",
  "agent-config",
  // BYOC renderers (wave 2)
  "byoc-hashbrown-demo",
  "byoc_json_render",
  // Open Generative UI (wave 2)
  "open-gen-ui",
  "open-gen-ui-advanced",
  // Polished chat shell (simplified port — wave 2 follow-up)
  "beautiful-chat",
  // Interrupt demos, served by the dedicated native-interrupt agent below
  "gen-ui-interrupt",
  "interrupt-headless",
];

// Agent names whose backend is a dedicated sub-application rather than the
// shared agent at the root. The interrupt demos need a `schedule_meeting` that
// pauses natively; the reasoning demos need the Responses API with reasoning
// summaries, which the shared chat-completions agent does not emit.
const dedicatedAgentPaths: Record<string, string> = {
  "beautiful-chat": "/beautiful-chat/",
  "gen-ui-interrupt": "/interrupt/",
  "interrupt-headless": "/interrupt/",
  "reasoning-default": "/reasoning/",
  "reasoning-custom": "/reasoning/",
  "tool-rendering-reasoning-chain": "/reasoning-chain/",
};

const agents: Record<string, AbstractAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent(dedicatedAgentPaths[name] ?? "/");
}
agents["default"] = createAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) =>
  // Snapshot the inbound x-* into ALS for the duration of the request so the
  // HttpAgent's forwardingProxyFetch can inject them onto the outbound POST to
  // the Express agent. Only headers PRESENT inbound are forwarded — never
  // hardcoded — so non-diagnostic demo traffic is byte-identical.
  proxyHeaders.run(extractXHeaders(req), async () => {
    const url = req.url;
    const contentType = req.headers.get("content-type");
    if (ROUTE_DEBUG) {
      console.log(
        `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
      );
    }

    try {
      const copilotHandler = createCopilotRuntimeHandler({
        runtime: new CopilotRuntime({
          // @ts-ignore -- Published CopilotRuntime agents type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in source, pending release
          agents,
        }),
        basePath: "/api/copilotkit",
        mode: "single-route",
      });

      const response = await copilotHandler(req);
      if (!response.ok) {
        console.log(`[copilotkit/route] Response status: ${response.status}`);
      } else if (ROUTE_DEBUG) {
        console.log(`[copilotkit/route] Response status: ${response.status}`);
      }
      return response;
    } catch (error: unknown) {
      const err = error as Error;
      console.error(`[copilotkit/route] ERROR: ${err.message}`);
      console.error(`[copilotkit/route] Stack: ${err.stack}`);
      return NextResponse.json(
        { error: err.message, stack: err.stack },
        { status: 500 },
      );
    }
  });

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

/* HALCYON — a warm-paper editorial theme for CopilotChat.
 *
 * The point of this demo is to show how far a single stylesheet can take
 * CopilotChat away from the default look without touching components or
 * slots. Every selector is namespaced under `.chat-css-demo-scope` so this
 * theme cannot leak into the rest of the showcase.
 *
 * Two layers do the work:
 *   1. v2 token overrides on `[data-copilotkit]` recolor every Tailwind
 *      utility (cpk:bg-muted, cpk:text-foreground, cpk:border, …) the
 *      runtime relies on — see @copilotkit/react-core/v2/styles.css.
 *   2. Targeted class rules on `.copilotKitChat`, `.copilotKitMessage*`,
 *      and `.copilotKitInput` add the editorial details: parchment grain,
 *      corner brackets, serif voice, mono dispatch, ember accents.
 *
 * Class-name reference:
 *   https://docs.copilotkit.ai/custom-look-and-feel/customize-built-in-ui-components
 */

@import url("https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Instrument+Serif:ital@0;1&family=Inter+Tight:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap");

/* HALCYON palette — a private library at golden hour. The whole theme is
 * one warm parchment hue, one warm ink, and a deep copper ember used
 * sparingly so it actually reads as a signal. */
.chat-css-demo-scope {
  --halcyon-paper: #f4efe6;
  --halcyon-paper-soft: #ece6d9;
  --halcyon-paper-elevated: #fbf8f2;
  --halcyon-card: #ffffff;
  --halcyon-rule: #d6cfbe;
  --halcyon-rule-strong: #aea48a;
  --halcyon-ink: #1a1714;
  --halcyon-ink-soft: #3d362e;
  --halcyon-ink-mute: #7a7468;
  --halcyon-ember: #c44a1f;
  --halcyon-ember-bright: #e45f2b;
  --halcyon-ember-soft: #f3d7c5;
  --halcyon-champagne: #98794a;

  --halcyon-display:
    "Instrument Serif", ui-serif, "Iowan Old Style", Georgia, serif;
  --halcyon-serif:
    "Fraunces", "Source Serif Pro", ui-serif, Georgia, "Times New Roman", serif;
  --halcyon-sans:
    "Inter Tight", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
  --halcyon-mono:
    "JetBrains Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --halcyon-shadow-soft:
    0 1px 0 rgba(26, 23, 20, 0.04), 0 12px 32px -18px rgba(26, 23, 20, 0.18);
  --halcyon-shadow-ember:
    0 1px 0 rgba(196, 74, 31, 0.18), 0 14px 36px -16px rgba(196, 74, 31, 0.42);
}

/* CopilotKit v2 reads these on the [data-copilotkit] root inside the chat.
 * Re-pointing them under our scope retints every Tailwind utility the
 * runtime renders (user message bubble, prose, borders, focus rings, …)
 * without us having to touch any individual class. */
.chat-css-demo-scope [data-copilotkit] {
  --background: var(--halcyon-paper);
  --foreground: var(--halcyon-ink);
  --card: var(--halcyon-card);
  --card-foreground: var(--halcyon-ink);
  --popover: var(--halcyon-paper-elevated);
  --popover-foreground: var(--halcyon-ink);
  --primary: var(--halcyon-ember);
  --primary-foreground: var(--halcyon-paper-elevated);
  --secondary: var(--halcyon-paper-soft);
  --secondary-foreground: var(--halcyon-ink);
  --muted: var(--halcyon-paper-soft);
  --muted-foreground: var(--halcyon-ink-mute);
  --accent: var(--halcyon-ember-soft);
  --accent-foreground: var(--halcyon-ember);
  --destructive: #b3361b;
  --destructive-foreground: var(--halcyon-paper-elevated);
  --border: var(--halcyon-rule);
  --input: var(--halcyon-rule);
  --ring: var(--halcyon-ember);
  --radius: 0px;
}

/* The chat surface — warm parchment with a single ambient ember glow,
 * a barely-perceptible paper grain via inline SVG noise, and architectural
 * corner brackets. Sharp 90° corners are deliberate; the default look is
 * rounded, so squaring everything off is the fastest visual signal that
 * "this is a different brand". */
.chat-css-demo-scope .copilotKitChat {
  font-family: var(--halcyon-sans);
  color: var(--halcyon-ink);
  background-color: var(--halcyon-paper);
  background-image:
    radial-gradient(
      900px 460px at 0% -10%,
      rgba(228, 95, 43, 0.14),
      transparent 62%
    ),
    radial-gradient(
      720px 380px at 100% 110%,
      rgba(152, 121, 74, 0.08),
      transparent 65%
    ),
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160' viewBox='0 0 160 160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.10 0 0 0 0 0.09 0 0 0 0 0.07 0 0 0 0.045 0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
  border: 1px solid var(--halcyon-rule);
  border-radius: 0;
  box-shadow: var(--halcyon-shadow-soft);
  position: relative;
  overflow: hidden;
}

/* The masthead label — a small mono bar pinned to the top of the surface,
 * playing against the editorial serif voice. Lives on ::before so it
 * tracks the chat root and shows in every state (welcome, mid-thread,
 * empty after clear). */
.chat-css-demo-scope .copilotKitChat::before {
  content: "CopilotChat  ·  Customized with CSS";
  position: absolute;
  top: 18px;
  left: 0;
  right: 0;
  text-align: center;
  font-family: var(--halcyon-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--halcyon-ink-mute);
  white-space: nowrap;
  pointer-events: none;
  z-index: 3;
}


/* The welcome screen — the page-one impression. The default heading is
 * sans-serif and tidy; we replace it with a large italic display serif
 * that wraps the question like a magazine cover line. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] {
  padding-top: 4rem;
}

.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1 {
  font-family: var(--halcyon-display);
  font-size: clamp(2.4rem, 5vw, 4rem);
  font-weight: 400;
  font-style: italic;
  color: var(--halcyon-ink);
  letter-spacing: -0.02em;
  line-height: 1.05;
  text-align: center;
  margin: 0 auto 0.6rem;
  max-width: 22ch;
  position: relative;
}

/* A small mono eyebrow above the heading. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::before {
  content: "CopilotKit";
  display: block;
  font-family: var(--halcyon-mono);
  font-size: 11px;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: var(--halcyon-ember);
  margin-bottom: 1.2rem;
}

/* A short rule under the heading as a visual settle point. */
.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::after {
  content: "";
  display: block;
  width: 36px;
  height: 1px;
  background: var(--halcyon-rule-strong);
  margin: 1.4rem auto 0;
}

.chat-css-demo-scope .copilotKitMessages {
  font-family: var(--halcyon-sans);
  background: transparent;
  color: var(--halcyon-ink);
  padding: 5rem 0 2rem;
  line-height: 1.6;
}

/* User message — a "transmission" in JetBrains Mono on a paper card. The
 * outer wrapper is the right-aligning flex column; we leave it transparent
 * and style the inner bubble (which uses cpk:bg-muted, hence we also
 * target the substring class as a stable hook). */
.chat-css-demo-scope .copilotKitMessage.copilotKitUserMessage {
  background: transparent;
  padding: 0;
  border: none;
  box-shadow: none;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitUserMessage
  > [class*="bg-muted"] {
  font-family: var(--halcyon-mono);
  font-size: 0.875rem;
  font-weight: 400;
  color: var(--halcyon-ink);
  background: var(--halcyon-paper-elevated);
  border: 1px solid var(--halcyon-rule);
  border-left: 2px solid var(--halcyon-ember);
  border-radius: 0;
  padding: 12px 16px 12px 18px;
  letter-spacing: -0.005em;
  line-height: 1.55;
  box-shadow: 0 1px 0 rgba(26, 23, 20, 0.03);
  position: relative;
}

/* A mono "→" marker before the user's text to read like a CLI prompt. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitUserMessage
  > [class*="bg-muted"]::before {
  content: "→";
  display: inline-block;
  margin-right: 10px;
  color: var(--halcyon-ember);
  font-weight: 500;
}

/* Assistant message — editorial Fraunces serif, no bubble, just generous
 * paragraphs offset by a thin ember rule on the left. Reads like the
 * voice of a publication, not a chatbot. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage {
  background: transparent;
  color: var(--halcyon-ink);
  font-family: var(--halcyon-serif);
  font-size: 1.0625rem;
  font-weight: 400;
  padding: 4px 0 4px 22px;
  border: none;
  border-radius: 0;
  margin-right: auto;
  margin-bottom: 1.25rem;
  max-width: 78ch;
  position: relative;
}

/* The editorial left rule. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage::before {
  content: "";
  position: absolute;
  top: 0.45em;
  bottom: 0.45em;
  left: 0;
  width: 1px;
  background: var(--halcyon-ember);
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose,
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose p {
  font-family: var(--halcyon-serif);
  font-size: inherit;
  color: inherit;
  line-height: 1.7;
  font-feature-settings: "ss01", "ss02", "ss03", "kern";
  margin: 0 0 0.85em;
}

/* Headings inside assistant content swap to the display serif so a long
 * answer reads like a structured article. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  :is(h1, h2, h3, h4) {
  font-family: var(--halcyon-display);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -0.015em;
  color: var(--halcyon-ink);
  margin: 1em 0 0.4em;
  line-height: 1.15;
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h1 {
  font-size: 2rem;
}
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h2 {
  font-size: 1.55rem;
}
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose h3 {
  font-size: 1.25rem;
}

/* Lists — looser, with serif numerals. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  :is(ul, ol) {
  margin: 0.5em 0 1em;
  padding-left: 1.4em;
}

.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose li {
  margin: 0.25em 0;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  ol
  > li::marker {
  color: var(--halcyon-ember);
  font-feature-settings: "tnum";
  font-weight: 500;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  ul
  > li::marker {
  color: var(--halcyon-ember);
}

/* Blockquote — pull-quote treatment in italic display serif. */
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  blockquote {
  border-left: 0;
  margin: 1.2em 0;
  padding: 0 0 0 1em;
  font-family: var(--halcyon-display);
  font-style: italic;
  font-size: 1.25em;
  color: var(--halcyon-ink-soft);
  position: relative;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  blockquote::before {
  content: "“";
  position: absolute;
  left: -0.05em;
  top: -0.4em;
  font-size: 2.4em;
  color: var(--halcyon-ember);
  line-height: 1;
}

/* Inline code — small ember chip on a tinted card. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose code {
  font-family: var(--halcyon-mono);
  font-size: 0.86em;
  font-weight: 500;
  color: var(--halcyon-ember);
  background: var(--halcyon-ember-soft);
  border: 1px solid color-mix(in srgb, var(--halcyon-ember) 22%, transparent);
  border-radius: 0;
  padding: 1px 6px;
}

/* Code block — dark ink card flipped against the parchment. The contrast
 * is deliberate; it reads like a code excerpt set in a printed book. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose pre,
.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  div[data-streamdown="code-block"]
  > pre {
  background: var(--halcyon-ink) !important;
  color: #e8e2d5;
  border: 1px solid var(--halcyon-ink);
  border-radius: 0;
  padding: 14px 16px;
  margin: 1em 0;
  font-family: var(--halcyon-mono);
  font-size: 0.86em;
  line-height: 1.55;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    var(--halcyon-shadow-soft);
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  pre
  code {
  background: transparent;
  color: inherit;
  border: none;
  padding: 0;
}

/* Anchor links — ember underline in classic editorial style. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose a {
  color: var(--halcyon-ember);
  text-decoration-line: underline;
  text-decoration-color: color-mix(
    in srgb,
    var(--halcyon-ember) 35%,
    transparent
  );
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: text-decoration-color 160ms ease;
}

.chat-css-demo-scope
  .copilotKitMessage.copilotKitAssistantMessage
  .prose
  a:hover {
  text-decoration-color: var(--halcyon-ember);
}

/* Horizontal rule — short, centered, ornament-like. */
.chat-css-demo-scope .copilotKitMessage.copilotKitAssistantMessage .prose hr {
  border: none;
  height: 1px;
  background: var(--halcyon-rule);
  width: 64px;
  margin: 1.6em auto;
}

/* Composer — a sharp paper card with an ember focus rule. The default
 * pill is rounded; squaring it off is again the visual cue that this is
 * a different brand. The wrapper around .copilotKitInput uses a fixed
 * white background in v2, so we override it directly. */
.chat-css-demo-scope .copilotKitInput {
  font-family: var(--halcyon-sans) !important;
  background: var(--halcyon-card) !important;
  border: 1px solid var(--halcyon-rule);
  border-radius: 0 !important;
  padding: 14px 16px;
  min-height: 56px;
  box-shadow:
    0 1px 0 rgba(26, 23, 20, 0.03),
    0 8px 24px -16px rgba(26, 23, 20, 0.18);
  transition:
    border-color 200ms ease,
    box-shadow 200ms ease,
    transform 120ms ease;
}

.chat-css-demo-scope .copilotKitInput:focus-within {
  border-color: var(--halcyon-ember);
  box-shadow:
    0 0 0 3px rgba(196, 74, 31, 0.12),
    0 1px 0 rgba(196, 74, 31, 0.18),
    0 14px 36px -16px rgba(196, 74, 31, 0.22);
  transform: translateY(-1px);
}

.chat-css-demo-scope .copilotKitInput textarea {
  font-family: var(--halcyon-sans) !important;
  font-size: 1rem;
  font-weight: 400;
  color: var(--halcyon-ink);
  line-height: 1.55;
  letter-spacing: -0.005em;
}

.chat-css-demo-scope .copilotKitInput textarea::placeholder {
  color: var(--halcyon-ink-mute);
  font-style: italic;
  opacity: 1;
}

/* The send button — a square ember chit, not the default circular pill.
 * v2 ships this as `<Button variant="chatInputToolbarPrimary"
 * size="chatInputToolbarIcon" data-testid="copilot-send-button">`, which
 * compiles to `cpk:bg-black cpk:text-white cpk:rounded-full cpk:h-9
 * cpk:w-9`. We override every one of those tokens so the brand wins. */
.chat-css-demo-scope button[data-testid="copilot-send-button"] {
  background-color: var(--halcyon-ember) !important;
  color: var(--halcyon-paper-elevated) !important;
  border: 1px solid var(--halcyon-ember) !important;
  border-radius: 2px !important;
  height: 36px !important;
  width: 36px !important;
  box-shadow: var(--halcyon-shadow-ember);
  transition:
    transform 150ms ease,
    box-shadow 150ms ease,
    background-color 150ms ease;
}

.chat-css-demo-scope button[data-testid="copilot-send-button"]:hover {
  background-color: var(--halcyon-ember-bright) !important;
  transform: translateY(-1px);
}

.chat-css-demo-scope button[data-testid="copilot-send-button"]:disabled {
  background-color: var(--halcyon-paper-soft) !important;
  color: var(--halcyon-ink-mute) !important;
  border-color: var(--halcyon-rule) !important;
  box-shadow: none;
  transform: none;
  opacity: 1 !important;
}

.chat-css-demo-scope button[data-testid="copilot-send-button"] svg {
  color: inherit;
}

/* Secondary input chrome (add-menu plus, mic, transcribe) — ghost squares
 * with an ember tint on hover. v2's `chatInputToolbarSecondary` variant
 * uses transparent bg + #444 text, which we re-tint to match the brand. */
.chat-css-demo-scope
  .copilotKitInput
  button:not([data-testid="copilot-send-button"]) {
  border-radius: 2px !important;
  color: var(--halcyon-ink-soft) !important;
  transition:
    color 150ms ease,
    background-color 150ms ease;
}

.chat-css-demo-scope
  .copilotKitInput
  button:not([data-testid="copilot-send-button"]):hover {
  color: var(--halcyon-ember) !important;
  background-color: var(--halcyon-ember-soft) !important;
}

/* Suggestion pills — sharp outlined chips, not rounded balloons. The
 * inner suggestion text uses the editorial mono so it reads like a
 * curated set of dispatch options. */
.chat-css-demo-scope [class*="copilotKitSuggestion"] {
  background: transparent;
  color: var(--halcyon-ink-soft);
  border: 1px solid var(--halcyon-rule);
  border-radius: 0;
  padding: 8px 14px;
  font-family: var(--halcyon-mono);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  transition:
    color 150ms ease,
    border-color 150ms ease,
    background 150ms ease,
    transform 150ms ease;
}

.chat-css-demo-scope [class*="copilotKitSuggestion"]:hover {
  color: var(--halcyon-ember);
  border-color: var(--halcyon-ember);
  background: var(--halcyon-ember-soft);
  transform: translateY(-1px);
}

.chat-css-demo-scope [data-copilotkit] ::-webkit-scrollbar {
  width: 4px;
}

.chat-css-demo-scope [data-copilotkit] ::-webkit-scrollbar-thumb {
  background: var(--halcyon-rule-strong);
  border-radius: 0;
}

.chat-css-demo-scope [data-copilotkit] ::-webkit-scrollbar-thumb:hover {
  background: var(--halcyon-ember);
}

.chat-css-demo-scope [data-copilotkit] * {
  scrollbar-width: thin;
  scrollbar-color: var(--halcyon-rule-strong) transparent;
}

.chat-css-demo-scope ::selection {
  background: var(--halcyon-ember-soft);
  color: var(--halcyon-ember);
}

/* A single, restrained entrance for the welcome screen — staggered fade-up
 * on the eyebrow / heading / rule. No infinite loops, no bouncy easing. */
@keyframes halcyon-rise {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1 {
  animation: halcyon-rise 700ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

.chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::before {
  animation: halcyon-rise 600ms cubic-bezier(0.2, 0.7, 0.2, 1) 80ms both;
}

@media (prefers-reduced-motion: reduce) {
  .chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1,
  .chat-css-demo-scope [data-testid="copilot-welcome-screen"] h1::before {
    animation: none;
  }
}

