"use client";

import React from "react";
import type {
  CopilotChatAssistantMessage,
  CopilotChatUserMessage,
  CopilotChatReasoningMessage,
  CopilotChatView,
  CopilotChatInput,
} from "@copilotkit/react-core/v2";
import { CopilotKit, CopilotChat } from "@copilotkit/react-core/v2";
import {
  CustomWelcomeScreen,
  CustomAssistantMessage,
  CustomUserMessage,
  CustomReasoningMessage,
  CustomCursor,
  CustomTextArea,
  CustomSendButton,
  CustomDisclaimer,
  CustomAddMenuButton,
  CustomSuggestionContainer,
  CustomSuggestion,
  CustomScrollToBottomButton,
  CustomFeather,
} from "./slot-wrappers";
import { makeSlotOverride } from "../_shared/slot-override";
import { useChatSlotsSuggestions } from "./suggestions";

// "Slot Atlas" — every overrideable slot on CopilotChat is wrapped in a
// dashed, color-coded marker so a developer can see at a glance what is
// customizable and where it lives. Hover any region to reveal its slot path.
export default function ChatSlotsDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="chat-slots">
      <div className="flex flex-col h-screen w-full bg-background">
        <div className="flex-1 flex justify-center items-stretch p-4 min-h-0">
          <div className="h-full w-full max-w-5xl">
            <Chat />
          </div>
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  useChatSlotsSuggestions();

  // Slot overrides go through `makeSlotOverride<TDefault>(component)` so
  // the cast is centralized in one named helper instead of sprinkled
  // through this file. See `../_shared/slot-override.ts` for the why.
  const welcomeScreen =
    makeSlotOverride<typeof CopilotChatView.WelcomeScreen>(CustomWelcomeScreen);

  // The input prop accepts both slot overrides AND CopilotChatInput's rest
  // props (toolsMenu, mode, etc.) merged together. We seed `toolsMenu` so the
  // addMenuButton slot has a reason to render.
  const input = {
    textArea:
      makeSlotOverride<typeof CopilotChatInput.TextArea>(CustomTextArea),
    sendButton:
      makeSlotOverride<typeof CopilotChatInput.SendButton>(CustomSendButton),
    disclaimer:
      makeSlotOverride<typeof CopilotChatInput.Disclaimer>(CustomDisclaimer),
    addMenuButton:
      makeSlotOverride<typeof CopilotChatInput.AddMenuButton>(
        CustomAddMenuButton,
      ),
    toolsMenu: [
      {
        label: "Demo tool (no-op)",
        action: () => {},
      },
    ],
  };

  const messageView = {
    assistantMessage: makeSlotOverride<typeof CopilotChatAssistantMessage>(
      CustomAssistantMessage,
    ),
    userMessage:
      makeSlotOverride<typeof CopilotChatUserMessage>(CustomUserMessage),
    reasoningMessage: makeSlotOverride<typeof CopilotChatReasoningMessage>(
      CustomReasoningMessage,
    ),
    cursor: CustomCursor,
  };

  const suggestionView = {
    container: CustomSuggestionContainer,
    suggestion: CustomSuggestion,
  };

  const scrollView = {
    scrollToBottomButton: CustomScrollToBottomButton,
    feather: CustomFeather,
  };

  return (
    <CopilotChat
      agentId="chat-slots"
      className="h-full rounded-2xl border border-border/60 bg-card overflow-hidden"
      welcomeScreen={welcomeScreen}
      input={input}
      messageView={messageView}
      suggestionView={suggestionView}
      scrollView={scrollView}
    />
  );
}

/**
 * Agent factories for the Strands TypeScript showcase backend.
 *
 * `buildShowcaseAgent` is the single shared agent that serves the vast
 * majority of demos (the frontend differentiates each demo via
 * useFrontendTool / useRenderTool / useHumanInTheLoop / useAgentContext).
 * It mirrors the Python sibling's `build_showcase_agent` minus A2UI.
 *
 * The tool-free specialized agents (voice, byoc-hashbrown, byoc-json-render)
 * are mounted on dedicated sub-paths by `server.ts`.
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Agent, tool } from "@strands-agents/sdk";
import { z } from "zod";
import type { RunAgentInput } from "@ag-ui/core";
import { StrandsAgent } from "@ag-ui/aws-strands";
import type { StrandsAgentConfig } from "@ag-ui/aws-strands";
import {
  A2UI_OPERATIONS_KEY,
  createSurface,
  updateComponents,
  updateDataModel,
} from "@ag-ui/a2ui-toolkit";
import { createModel } from "./model-factory";
import { SHOWCASE_TOOLS } from "./tools";
import { BoardStateStrandsAgent } from "./todo-state-sync";
import {
  withStateContext,
  salesStateFromArgs,
  salesStateFromResult,
  notesStateFromArgs,
  stepsStateFromArgs,
  documentStateFromArgs,
  makeSubagentStateFromResult,
} from "./state";
import {
  SYSTEM_PROMPT,
  VOICE_SYSTEM_PROMPT,
  BYOC_HASHBROWN_SYSTEM_PROMPT,
  BYOC_JSON_RENDER_SYSTEM_PROMPT,
} from "./prompts";

export class ShowcaseStrandsAgent extends BoardStateStrandsAgent {
  override async *run(inputData: RunAgentInput) {
    // The adapter exposes context during model calls and restores history afterward.
    yield* super.run(withStateContext(inputData));
  }
}

export async function buildShowcaseAgent(
  openaiApi: "chat" | "responses" = "chat",
): Promise<StrandsAgent> {
  const config: StrandsAgentConfig = {
    toolBehaviors: {
      // The tool keeps the sales pipeline in appState; this snapshot, built
      // from the args, only carries it to the UI. Keep the call/result in
      // message snapshots too so completed threads can replay them.
      manage_sales_todos: {
        stateFromArgs: salesStateFromArgs,
      },
      get_sales_todos: { stateFromResult: salesStateFromResult },
      // Shared State (Read + Write) — notes panel.
      set_notes: { stateFromArgs: notesStateFromArgs },
      // gen-ui-agent — live progress card driven by set_steps transitions.
      set_steps: { stateFromArgs: stepsStateFromArgs },
      // shared-state-streaming — stream the document string into state.
      write_document: { stateFromArgs: documentStateFromArgs },
      // Sub-agents — append a delegation entry carrying the actual output.
      research_agent: {
        stateFromResult: makeSubagentStateFromResult("research_agent"),
      },
      writing_agent: {
        stateFromResult: makeSubagentStateFromResult("writing_agent"),
      },
      critique_agent: {
        stateFromResult: makeSubagentStateFromResult("critique_agent"),
      },
    },
  };

  const strandsAgent = new Agent({
    model: await createModel({ openaiApi }),
    systemPrompt: SYSTEM_PROMPT,
    tools: SHOWCASE_TOOLS,
  });

  return new ShowcaseStrandsAgent({
    agent: strandsAgent,
    name: "strands_agent",
    description:
      "A polished CopilotKit demo assistant: chat, tools, shared state, HITL, sub-agents.",
    config,
  });
}

