"use client";

import { useState } from "react";
import {
  CopilotKit,
  CopilotPopup,
  useFrontendTool,
} from "@copilotkit/react-core/v2";
import { z } from "zod";
import type { PendingApproval } from "./approval-dialog";
import { ApprovalDialog } from "./approval-dialog";
import { TicketsPanel } from "./tickets-panel";
import { useHitlInAppSuggestions } from "./suggestions";

export default function HitlInAppDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="hitl-in-app">
      <Layout />
    </CopilotKit>
  );
}

// Internal state shape: the args the agent passed plus the `resolve`
// fn we captured from the Promise returned by the tool handler.
type ResolveFn = (value: { approved: boolean; reason?: string }) => void;
type DialogState =
  | { open: false }
  | { open: true; pending: PendingApproval; resolve: ResolveFn };

function Layout() {
  const [dialog, setDialog] = useState<DialogState>({ open: false });

  useHitlInAppSuggestions();

  useFrontendTool({
    name: "request_user_approval",
    description:
      "Ask the operator to approve or reject an action before you take it. " +
      "The operator will respond via an in-app modal dialog that appears " +
      "OUTSIDE the chat surface. The tool returns an object of the shape " +
      "{ approved: boolean, reason?: string }.",
    parameters: z.object({
      message: z
        .string()
        .describe(
          "Short summary of the action needing approval (include concrete numbers / IDs).",
        ),
      context: z
        .string()
        .optional()
        .describe(
          "Optional extra context — e.g. the ticket ID or policy rule.",
        ),
    }),
    handler: async ({
      message,
      context,
    }: {
      message: string;
      context?: string;
    }) => {
      // Return a Promise whose `resolve` we stash into state. The modal
      // dialog calls `resolve(...)` when the user clicks Approve / Reject,
      // which completes THIS handler and hands the value back to the
      // agent as the tool result.
      return await new Promise<{ approved: boolean; reason?: string }>(
        (resolve) => {
          setDialog({ open: true, pending: { message, context }, resolve });
        },
      );
    },
  });

  const handleResolve = (result: { approved: boolean; reason?: string }) => {
    if (dialog.open) {
      dialog.resolve(result);
      setDialog({ open: false });
    }
  };

  return (
    <div className="h-screen bg-gray-50">
      <TicketsPanel />
      <CopilotPopup
        agentId="hitl-in-app"
        defaultOpen={true}
        labels={{
          chatInputPlaceholder: "Type a message",
        }}
      />
      {dialog.open && (
        <ApprovalDialog pending={dialog.pending} onResolve={handleResolve} />
      )}
    </div>
  );
}

/**
 * Agent factories for the Strands TypeScript showcase backend.
 *
 * `buildShowcaseAgent` is the single shared agent that serves the vast
 * majority of demos (the frontend differentiates each demo via
 * useFrontendTool / useRenderTool / useHumanInTheLoop / useAgentContext).
 * It mirrors the Python sibling's `build_showcase_agent` minus A2UI.
 *
 * The tool-free specialized agents (voice, byoc-hashbrown, byoc-json-render)
 * are mounted on dedicated sub-paths by `server.ts`.
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Agent, tool } from "@strands-agents/sdk";
import { z } from "zod";
import type { RunAgentInput } from "@ag-ui/core";
import { StrandsAgent } from "@ag-ui/aws-strands";
import type { StrandsAgentConfig } from "@ag-ui/aws-strands";
import {
  A2UI_OPERATIONS_KEY,
  createSurface,
  updateComponents,
  updateDataModel,
} from "@ag-ui/a2ui-toolkit";
import { createModel } from "./model-factory";
import { SHOWCASE_TOOLS } from "./tools";
import { BoardStateStrandsAgent } from "./todo-state-sync";
import {
  withStateContext,
  salesStateFromArgs,
  salesStateFromResult,
  notesStateFromArgs,
  stepsStateFromArgs,
  documentStateFromArgs,
  makeSubagentStateFromResult,
} from "./state";
import {
  SYSTEM_PROMPT,
  VOICE_SYSTEM_PROMPT,
  BYOC_HASHBROWN_SYSTEM_PROMPT,
  BYOC_JSON_RENDER_SYSTEM_PROMPT,
} from "./prompts";

export class ShowcaseStrandsAgent extends BoardStateStrandsAgent {
  override async *run(inputData: RunAgentInput) {
    // The adapter exposes context during model calls and restores history afterward.
    yield* super.run(withStateContext(inputData));
  }
}

export async function buildShowcaseAgent(
  openaiApi: "chat" | "responses" = "chat",
): Promise<StrandsAgent> {
  const config: StrandsAgentConfig = {
    toolBehaviors: {
      // The tool keeps the sales pipeline in appState; this snapshot, built
      // from the args, only carries it to the UI. Keep the call/result in
      // message snapshots too so completed threads can replay them.
      manage_sales_todos: {
        stateFromArgs: salesStateFromArgs,
      },
      get_sales_todos: { stateFromResult: salesStateFromResult },
      // Shared State (Read + Write) — notes panel.
      set_notes: { stateFromArgs: notesStateFromArgs },
      // gen-ui-agent — live progress card driven by set_steps transitions.
      set_steps: { stateFromArgs: stepsStateFromArgs },
      // shared-state-streaming — stream the document string into state.
      write_document: { stateFromArgs: documentStateFromArgs },
      // Sub-agents — append a delegation entry carrying the actual output.
      research_agent: {
        stateFromResult: makeSubagentStateFromResult("research_agent"),
      },
      writing_agent: {
        stateFromResult: makeSubagentStateFromResult("writing_agent"),
      },
      critique_agent: {
        stateFromResult: makeSubagentStateFromResult("critique_agent"),
      },
    },
  };

  const strandsAgent = new Agent({
    model: await createModel({ openaiApi }),
    systemPrompt: SYSTEM_PROMPT,
    tools: SHOWCASE_TOOLS,
  });

  return new ShowcaseStrandsAgent({
    agent: strandsAgent,
    name: "strands_agent",
    description:
      "A polished CopilotKit demo assistant: chat, tools, shared state, HITL, sub-agents.",
    config,
  });
}

