// Tool Rendering — PRIMARY (per-tool + catch-all) variant.
//
// The most sophisticated point in the three-way progression: every
// "interesting" backend tool gets its own dedicated, branded UI, and a
// catch-all paints anything that slips through.
//
//   get_weather     → <WeatherCard />       (per-tool renderer)
//   search_flights  → <FlightListCard />    (per-tool renderer)
//   get_stock_price → <StockCard />         (per-tool renderer)
//   roll_d20        → <D20Card />           (per-tool renderer)
//   *               → <CustomCatchallRenderer /> (wildcard fallback)

import React from "react";
import {
  CopilotKit,
  CopilotChat,
  useRenderTool,
  useDefaultRenderTool,
} from "@copilotkit/react-core/v2";
import { z } from "zod";
import { WeatherCard } from "./weather-card";
import { FlightListCard } from "./flight-list-card";
import type { Flight } from "./flight-list-card";
import { StockCard } from "./stock-card";
import { D20Card } from "./d20-card";
import { CustomCatchallRenderer } from "./custom-catchall-renderer";
import type { CatchallToolStatus } from "./custom-catchall-renderer";
import { parseJsonResult } from "../_shared/parse-json-result";
import { useSuggestions } from "./suggestions";

interface WeatherResult {
  city?: string;
  temperature?: number;
  humidity?: number;
  wind_speed?: number;
  conditions?: string;
}

interface FlightSearchResult {
  origin?: string;
  destination?: string;
  flights?: Flight[];
}

interface StockResult {
  ticker?: string;
  price_usd?: number;
  change_pct?: number;
}

interface D20Result {
  value?: number;
  result?: number;
  sides?: number;
}

export default function ToolRenderingDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="tool-rendering">
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  // Per-tool renderer #1: get_weather → branded WeatherCard.
  useRenderTool(
    {
      name: "get_weather",
      parameters: z.object({
        location: z.string(),
      }),
      render: ({ parameters, result, status }) => {
        const loading = status !== "complete";
        const parsed = parseJsonResult<WeatherResult>(result);
        return (
          <WeatherCard
            loading={loading}
            location={parameters?.location ?? parsed.city ?? ""}
            temperature={parsed.temperature}
            humidity={parsed.humidity}
            windSpeed={parsed.wind_speed}
            conditions={parsed.conditions}
          />
        );
      },
    },
    [],
  );

  // Per-tool renderer #2: search_flights → branded FlightListCard.
  useRenderTool(
    {
      name: "search_flights",
      parameters: z.object({
        origin: z.string(),
        destination: z.string(),
      }),
      render: ({ parameters, result, status }) => {
        const loading = status !== "complete";
        const parsed = parseJsonResult<FlightSearchResult>(result);
        return (
          <FlightListCard
            loading={loading}
            origin={parameters?.origin ?? parsed.origin ?? ""}
            destination={parameters?.destination ?? parsed.destination ?? ""}
            flights={parsed.flights ?? []}
          />
        );
      },
    },
    [],
  );

  // Per-tool renderer #3: get_stock_price → branded StockCard.
  useRenderTool(
    {
      name: "get_stock_price",
      parameters: z.object({
        ticker: z.string(),
      }),
      render: ({ parameters, result, status }) => {
        const loading = status !== "complete";
        const parsed = parseJsonResult<StockResult>(result);
        return (
          <StockCard
            loading={loading}
            ticker={parameters?.ticker ?? parsed.ticker ?? ""}
            priceUsd={parsed.price_usd}
            changePct={parsed.change_pct}
          />
        );
      },
    },
    [],
  );

  // Per-tool renderer #4: roll_d20 → branded D20Card. Each tool call
  // mounts its own card so e2e tests can count them.
  useRenderTool(
    {
      name: "roll_d20",
      parameters: z.object({
        value: z.number().optional(),
      }),
      render: ({ result, status }) => {
        const loading = status !== "complete";
        const parsed = parseJsonResult<D20Result>(result);
        const value =
          typeof parsed.value === "number"
            ? parsed.value
            : typeof parsed.result === "number"
              ? parsed.result
              : undefined;
        return <D20Card loading={loading} value={value} />;
      },
    },
    [],
  );

  // Wildcard catch-all for anything that doesn't match a per-tool
  // renderer above.
  useDefaultRenderTool(
    {
      render: ({ name, parameters, status, result }) => (
        <CustomCatchallRenderer
          name={name}
          parameters={parameters}
          status={status as CatchallToolStatus}
          result={result}
        />
      ),
    },
    [],
  );

  useSuggestions();

  return (
    <CopilotChat agentId="tool-rendering" className="h-full rounded-2xl" />
  );
}

/**
 * Agent factories for the Strands TypeScript showcase backend.
 *
 * `buildShowcaseAgent` is the single shared agent that serves the vast
 * majority of demos (the frontend differentiates each demo via
 * useFrontendTool / useRenderTool / useHumanInTheLoop / useAgentContext).
 * It mirrors the Python sibling's `build_showcase_agent` minus A2UI.
 *
 * The tool-free specialized agents (voice, byoc-hashbrown, byoc-json-render)
 * are mounted on dedicated sub-paths by `server.ts`.
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Agent, tool } from "@strands-agents/sdk";
import { z } from "zod";
import type { RunAgentInput } from "@ag-ui/core";
import { StrandsAgent } from "@ag-ui/aws-strands";
import type { StrandsAgentConfig } from "@ag-ui/aws-strands";
import {
  A2UI_OPERATIONS_KEY,
  createSurface,
  updateComponents,
  updateDataModel,
} from "@ag-ui/a2ui-toolkit";
import { createModel } from "./model-factory";
import { SHOWCASE_TOOLS } from "./tools";
import { BoardStateStrandsAgent } from "./todo-state-sync";
import {
  withStateContext,
  salesStateFromArgs,
  salesStateFromResult,
  notesStateFromArgs,
  stepsStateFromArgs,
  documentStateFromArgs,
  makeSubagentStateFromResult,
} from "./state";
import {
  SYSTEM_PROMPT,
  VOICE_SYSTEM_PROMPT,
  BYOC_HASHBROWN_SYSTEM_PROMPT,
  BYOC_JSON_RENDER_SYSTEM_PROMPT,
} from "./prompts";

export class ShowcaseStrandsAgent extends BoardStateStrandsAgent {
  override async *run(inputData: RunAgentInput) {
    // The adapter exposes context during model calls and restores history afterward.
    yield* super.run(withStateContext(inputData));
  }
}

export async function buildShowcaseAgent(
  openaiApi: "chat" | "responses" = "chat",
): Promise<StrandsAgent> {
  const config: StrandsAgentConfig = {
    toolBehaviors: {
      // The tool keeps the sales pipeline in appState; this snapshot, built
      // from the args, only carries it to the UI. Keep the call/result in
      // message snapshots too so completed threads can replay them.
      manage_sales_todos: {
        stateFromArgs: salesStateFromArgs,
      },
      get_sales_todos: { stateFromResult: salesStateFromResult },
      // Shared State (Read + Write) — notes panel.
      set_notes: { stateFromArgs: notesStateFromArgs },
      // gen-ui-agent — live progress card driven by set_steps transitions.
      set_steps: { stateFromArgs: stepsStateFromArgs },
      // shared-state-streaming — stream the document string into state.
      write_document: { stateFromArgs: documentStateFromArgs },
      // Sub-agents — append a delegation entry carrying the actual output.
      research_agent: {
        stateFromResult: makeSubagentStateFromResult("research_agent"),
      },
      writing_agent: {
        stateFromResult: makeSubagentStateFromResult("writing_agent"),
      },
      critique_agent: {
        stateFromResult: makeSubagentStateFromResult("critique_agent"),
      },
    },
  };

  const strandsAgent = new Agent({
    model: await createModel({ openaiApi }),
    systemPrompt: SYSTEM_PROMPT,
    tools: SHOWCASE_TOOLS,
  });

  return new ShowcaseStrandsAgent({
    agent: strandsAgent,
    name: "strands_agent",
    description:
      "A polished CopilotKit demo assistant: chat, tools, shared state, HITL, sub-agents.",
    config,
  });
}

/**
 * Published Strands Chat Completions drops parallel call indices before native
 * aggregation. Responses preserves each call and emits complete, ordered blocks.
 * Rich chat intentionally buffers tool arguments; the shared agent keeps Chat
 * for demos that demonstrate progressive state and UI updates.
 */
export function buildRichChatAgent(): Promise<StrandsAgent> {
  return buildShowcaseAgent("responses");
}

