"use client";

// Tool Rendering — REASONING CHAIN variant.
//
// A single cell that composes two previously-separate patterns:
//
//   1. Reasoning tokens rendered via a custom `reasoningMessage` slot —
//      the same approach used by the `reasoning-custom` cell.
//   2. Sequential tool calls rendered with:
//        get_weather     → <WeatherCard />
//        search_flights  → <FlightListCard />
//        *               → <CustomCatchallRenderer />
//      mirroring the `tool-rendering` (primary) cell.

import React from "react";
import type { CopilotChatReasoningMessage } from "@copilotkit/react-core/v2";
import {
  CopilotKit,
  CopilotChat,
  useRenderTool,
  useDefaultRenderTool,
  useConfigureSuggestions,
} from "@copilotkit/react-core/v2";
import { z } from "zod";
import { ReasoningBlock } from "./reasoning-block";
import { WeatherCard } from "./weather-card";
import { FlightListCard } from "./flight-list-card";
import type { Flight } from "./flight-list-card";
import { CustomCatchallRenderer } from "./custom-catchall-renderer";
import type { CatchallToolStatus } from "./custom-catchall-renderer";
import { parseJsonResult } from "../_shared/parse-json-result";

interface WeatherResult {
  city?: string;
  temperature?: number;
  humidity?: number;
  wind_speed?: number;
  conditions?: string;
}

interface FlightSearchResult {
  origin?: string;
  destination?: string;
  flights?: Flight[];
}

export default function ToolRenderingReasoningChainDemo() {
  return (
    <CopilotKit
      runtimeUrl="/api/copilotkit"
      agent="tool-rendering-reasoning-chain"
    >
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  useRenderTool(
    {
      name: "get_weather",
      parameters: z.object({ location: z.string() }),
      render: ({ parameters, result, status }) => {
        const loading = status !== "complete";
        const parsed = parseJsonResult<WeatherResult>(result);
        return (
          <WeatherCard
            loading={loading}
            location={parameters?.location ?? parsed.city ?? ""}
            temperature={parsed.temperature}
            humidity={parsed.humidity}
            windSpeed={parsed.wind_speed}
            conditions={parsed.conditions}
          />
        );
      },
    },
    [],
  );

  useRenderTool(
    {
      name: "search_flights",
      parameters: z.object({
        origin: z.string(),
        destination: z.string(),
      }),
      render: ({ parameters, result, status }) => {
        const loading = status !== "complete";
        const parsed = parseJsonResult<FlightSearchResult>(result);
        return (
          <FlightListCard
            loading={loading}
            origin={parameters?.origin ?? parsed.origin ?? ""}
            destination={parameters?.destination ?? parsed.destination ?? ""}
            flights={parsed.flights ?? []}
          />
        );
      },
    },
    [],
  );

  useDefaultRenderTool(
    {
      render: ({ name, parameters, status, result }) => (
        <CustomCatchallRenderer
          name={name}
          parameters={parameters}
          status={status as CatchallToolStatus}
          result={result}
        />
      ),
    },
    [],
  );

  useConfigureSuggestions({
    suggestions: [
      {
        title: "Compare two stocks",
        message: "Compare AAPL and MSFT stocks for me.",
      },
      {
        title: "Chain of dice rolls",
        message: "Roll a 20-sided die for me and compare it to a smaller one.",
      },
      {
        title: "Flights + destination weather",
        message: "Find flights from SFO to JFK and show me the weather there.",
      },
    ],
    available: "always",
  });

  return (
    <CopilotChat
      agentId="tool-rendering-reasoning-chain"
      className="h-full rounded-2xl"
      messageView={{
        reasoningMessage: ReasoningBlock as typeof CopilotChatReasoningMessage,
      }}
    />
  );
}

/**
 * Reasoning agents: emit AG-UI REASONING_MESSAGE_* events.
 *
 * Mirrors the Python siblings `agents/reasoning_agent.py` and
 * `agents/reasoning_chain_agent.py`.
 *
 * Why a reasoning model plus the Responses API: the OpenAI Responses API
 * streams `response.reasoning_summary_text.delta` items only for native
 * reasoning models (gpt-5, o3, o4-mini and friends). The Strands bridge
 * translates those into AG-UI REASONING_MESSAGE_* events with
 * `role: "reasoning"`, which the frontend renders through the
 * `reasoningMessage` slot. gpt-4o emits no reasoning items, so the showcase's
 * default chat-completions model would never light the slot up.
 *
 * `buildReasoningAgent` is tool-free and serves reasoning-default and
 * reasoning-custom. `buildReasoningChainAgent` adds the four mock tools the
 * tool-rendering-reasoning-chain demo paints per-tool renderers for; each pill
 * drives a chained pair of calls, so the agent has to own every tool in the
 * chain to reach the closing narration.
 */

import { Agent, tool } from "@strands-agents/sdk";
import { z } from "zod";
import { StrandsAgent } from "@ag-ui/aws-strands";
import { createModel } from "./model-factory";

export const REASONING_MODEL = process.env.OPENAI_REASONING_MODEL ?? "gpt-5.4";

/** Responses-API model that streams reasoning summaries on every turn. */
function reasoningModel() {
  return createModel({
    openaiApi: "responses",
    reasoning: true,
    openaiModelId: REASONING_MODEL,
  });
}

const REASONING_SYSTEM_PROMPT =
  "You are a helpful assistant. For each user question, first think " +
  "step-by-step about the approach, then give a concise answer.";

/** Tool-free agent backing reasoning-default and reasoning-custom. */
export async function buildReasoningAgent(): Promise<StrandsAgent> {
  return new StrandsAgent({
    agent: new Agent({
      model: await reasoningModel(),
      systemPrompt: REASONING_SYSTEM_PROMPT,
      tools: [],
    }),
    name: "reasoning",
    description:
      "Strands agent that streams reasoning summaries alongside its answer",
  });
}

const getWeather = tool({
  name: "get_weather",
  description: "Get the current weather for a given location.",
  inputSchema: z.object({
    location: z.string().describe("City or airport to report on."),
  }),
  callback: ({ location }) => ({
    city: location,
    temperature: 68,
    humidity: 55,
    wind_speed: 10,
    conditions: "Sunny",
  }),
});

const searchFlights = tool({
  name: "search_flights",
  description:
    "Search mock flights from an origin airport to a destination airport.",
  inputSchema: z.object({
    origin: z.string().describe("Origin airport code."),
    destination: z.string().describe("Destination airport code."),
  }),
  callback: ({ origin, destination }) => ({
    origin,
    destination,
    flights: [
      {
        airline: "United",
        flight: "UA231",
        depart: "08:15",
        arrive: "16:45",
        price_usd: 348,
      },
      {
        airline: "Delta",
        flight: "DL412",
        depart: "11:20",
        arrive: "19:55",
        price_usd: 312,
      },
      {
        airline: "JetBlue",
        flight: "B6722",
        depart: "17:05",
        arrive: "01:30",
        price_usd: 289,
      },
    ],
  }),
});

const getStockPrice = tool({
  name: "get_stock_price",
  description: "Get a mock current price for a stock ticker.",
  inputSchema: z.object({
    ticker: z.string().describe("Ticker symbol to quote."),
    price_usd: z.number().optional().describe("Optional scripted price."),
    change_pct: z
      .number()
      .optional()
      .describe("Optional scripted percentage change."),
  }),
  // The optional arguments let the model (or an aimock fixture) script a
  // deterministic quote: when supplied they are echoed back verbatim.
  callback: ({ ticker, price_usd, change_pct }) => ({
    ticker: ticker.toUpperCase(),
    price_usd:
      price_usd !== undefined
        ? Math.round(price_usd * 100) / 100
        : Math.round((100 + Math.random() * 400) * 100) / 100,
    change_pct:
      change_pct !== undefined
        ? Math.round(change_pct * 100) / 100
        : Math.round((Math.random() < 0.5 ? -1 : 1) * Math.random() * 300) /
          100,
  }),
});

const rollDice = tool({
  name: "roll_dice",
  description: "Roll a single die with the given number of sides.",
  inputSchema: z.object({
    sides: z.number().default(6).describe("Number of faces on the die."),
  }),
  callback: ({ sides }) => ({
    sides,
    result: 1 + Math.floor(Math.random() * Math.max(2, sides)),
  }),
});

const REASONING_CHAIN_SYSTEM_PROMPT = `You are a helpful travel & lifestyle concierge with mock tools for weather, flights, stock prices, and dice rolls -- they all return fake data, so call them liberally.

Your habit is to CHAIN tools when one answer naturally invites another. For a single user question, call at least TWO tools in succession when the topic allows, then compose your final reply. Default chains:
  - 'What's the weather in <city>?' -> call get_weather(<city>), then call search_flights(origin='SFO', destination=<city>) so the user also sees how to get there.
  - 'How is <ticker> doing?' -> call get_stock_price(<ticker>), then call get_stock_price on a comparable ticker (e.g. 'MSFT' or 'GOOGL') so the user can compare.
  - 'Roll a 20-sided die' -> call roll_dice(sides=20), then call roll_dice again with a different number of sides so the user sees a contrast.
  - 'Find flights from <a> to <b>' -> call search_flights(a, b), then call get_weather(<b>) for the destination.

Only skip chaining when the user has clearly asked for a single, atomic answer and more tool calls would feel intrusive. Never fabricate data that a tool could provide.`;

/** Agent backing tool-rendering-reasoning-chain. */
export async function buildReasoningChainAgent(): Promise<StrandsAgent> {
  return new StrandsAgent({
    agent: new Agent({
      model: await reasoningModel(),
      systemPrompt: REASONING_CHAIN_SYSTEM_PROMPT,
      tools: [getWeather, searchFlights, getStockPrice, rollDice],
    }),
    name: "reasoning_chain",
    description:
      "Strands agent that chains mock tools while streaming reasoning summaries",
  });
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent, HttpAgentConfig } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";
import { AsyncLocalStorage } from "node:async_hooks";

// The agent backend runs as a separate process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

// Per-request inbound x-* forwarding over the HttpAgent proxy hop. The Next
// route is a bare proxy; the model call happens in the Express agent (:8000).
// @ag-ui/client's HttpAgent `headers` are STATIC (construction-time), so the
// per-request seam is its `fetch` option: a custom fetch that reads an
// AsyncLocalStorage snapshot (seeded by the POST handler below) and injects the
// inbound x-* (incl. x-aimock-strict / x-test-id / x-diag-*) onto the outbound
// POST. These then arrive on req.headers at the Express endpoint, where the
// agent-side middleware reads them. Byte-identical to a plain fetch when no x-*
// are in scope, so demo traffic proxies unchanged.
const proxyHeaders = new AsyncLocalStorage<Record<string, string>>();

function extractXHeaders(req: NextRequest): Record<string, string> {
  const out: Record<string, string> = {};
  req.headers.forEach((value, key) => {
    const lower = key.toLowerCase();
    if (lower.startsWith("x-")) out[lower] = value;
  });
  return out;
}

const forwardingProxyFetch: NonNullable<HttpAgentConfig["fetch"]> = (
  url,
  requestInit,
) => {
  const forwarded = proxyHeaders.getStore() ?? {};
  if (Object.keys(forwarded).length === 0) return fetch(url, requestInit);
  const merged = new Headers(requestInit?.headers);
  for (const [k, v] of Object.entries(forwarded)) {
    if (!merged.has(k)) merged.set(k, v);
  }
  return fetch(url, { ...requestInit, headers: merged });
};

function createAgent(path = "/") {
  return new HttpAgent({
    url: `${AGENT_URL}${path}`,
    fetch: forwardingProxyFetch,
  });
}

// Register the same agent under all names used by demo pages.
// Strands runs a single shared backend agent; per-demo differentiation
// happens on the frontend (useFrontendTool / useRenderTool / useHumanInTheLoop
// / useAgentContext / A2UI catalogs). Every demo page's `agent=` prop must
// resolve to a name in this list.
const agentNames = [
  // Original blitz set
  "agentic_chat",
  "human_in_the_loop",
  "tool-rendering",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-write",
  "shared-state-streaming",
  "subagents",
  // Chat UI / chrome demos
  "chat-customization-css",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "headless-simple",
  "headless-complete",
  // Reasoning
  "reasoning-default",
  "reasoning-custom",
  // Frontend tools
  "frontend_tools",
  "frontend-tools-async",
  // HITL
  "hitl-in-chat",
  "hitl-in-app",
  // Tool rendering variants
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "tool-rendering-reasoning-chain",
  // State / context
  "readonly-state-agent-context",
  "shared-state-read-write",
  // Modalities
  "multimodal",
  "voice",
  // Misc
  "auth",
  "agent-config",
  // BYOC renderers (wave 2)
  "byoc-hashbrown-demo",
  "byoc_json_render",
  // Open Generative UI (wave 2)
  "open-gen-ui",
  "open-gen-ui-advanced",
  // Polished chat shell (simplified port — wave 2 follow-up)
  "beautiful-chat",
  // Interrupt demos, served by the dedicated native-interrupt agent below
  "gen-ui-interrupt",
  "interrupt-headless",
];

// Agent names whose backend is a dedicated sub-application rather than the
// shared agent at the root. The interrupt demos need a `schedule_meeting` that
// pauses natively; the reasoning demos need the Responses API with reasoning
// summaries, which the shared chat-completions agent does not emit.
const dedicatedAgentPaths: Record<string, string> = {
  "beautiful-chat": "/beautiful-chat/",
  "gen-ui-interrupt": "/interrupt/",
  "interrupt-headless": "/interrupt/",
  "reasoning-default": "/reasoning/",
  "reasoning-custom": "/reasoning/",
  "tool-rendering-reasoning-chain": "/reasoning-chain/",
};

const agents: Record<string, AbstractAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent(dedicatedAgentPaths[name] ?? "/");
}
agents["default"] = createAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) =>
  // Snapshot the inbound x-* into ALS for the duration of the request so the
  // HttpAgent's forwardingProxyFetch can inject them onto the outbound POST to
  // the Express agent. Only headers PRESENT inbound are forwarded — never
  // hardcoded — so non-diagnostic demo traffic is byte-identical.
  proxyHeaders.run(extractXHeaders(req), async () => {
    const url = req.url;
    const contentType = req.headers.get("content-type");
    if (ROUTE_DEBUG) {
      console.log(
        `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
      );
    }

    try {
      const copilotHandler = createCopilotRuntimeHandler({
        runtime: new CopilotRuntime({
          // @ts-ignore -- Published CopilotRuntime agents type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in source, pending release
          agents,
        }),
        basePath: "/api/copilotkit",
        mode: "single-route",
      });

      const response = await copilotHandler(req);
      if (!response.ok) {
        console.log(`[copilotkit/route] Response status: ${response.status}`);
      } else if (ROUTE_DEBUG) {
        console.log(`[copilotkit/route] Response status: ${response.status}`);
      }
      return response;
    } catch (error: unknown) {
      const err = error as Error;
      console.error(`[copilotkit/route] ERROR: ${err.message}`);
      console.error(`[copilotkit/route] Stack: ${err.stack}`);
      return NextResponse.json(
        { error: err.message, stack: err.stack },
        { status: 500 },
      );
    }
  });

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

"use client";

import React from "react";

// Branded catch-all renderer for tools that don't have a dedicated
// per-tool renderer. Registered via `useDefaultRenderTool` in page.tsx,
// this component handles every tool call NOT claimed by a named
// `useRenderTool` registration (e.g. get_stock_price, roll_dice).
//
// Shows the tool name, a status badge, pretty-printed arguments, and
// the result (as JSON). Each cell is self-contained, so this file is
// intentionally duplicated from the `tool-rendering-custom-catchall`
// cell rather than imported across cell boundaries.

export type CatchallToolStatus = "inProgress" | "executing" | "complete";

export interface CustomCatchallRendererProps {
  name: string;
  status: CatchallToolStatus;
  parameters: unknown;
  result: string | undefined;
}

export function CustomCatchallRenderer({
  name,
  status,
  parameters,
  result,
}: CustomCatchallRendererProps) {
  const parsedResult = parseResult(result);
  const done = status === "complete";

  return (
    <div
      data-testid="custom-catchall-card"
      data-tool-name={name}
      data-status={status}
      className="my-3 overflow-hidden rounded-2xl border border-[#DBDBE5] bg-white shadow-sm"
    >
      <div className="flex items-center justify-between border-b border-[#E9E9EF] bg-[#FAFAFC] px-4 py-2.5">
        <div className="flex items-center gap-2">
          <span className="text-[10px] uppercase tracking-[0.14em] text-[#838389]">
            Tool
          </span>
          <span
            data-testid="custom-catchall-tool-name"
            className="font-mono text-sm text-[#010507]"
          >
            {name}
          </span>
        </div>
        <StatusBadge status={status} />
      </div>

      <div className="grid gap-3 p-4 text-sm">
        <Section label="Arguments">
          <pre
            data-testid="custom-catchall-args"
            className="overflow-x-auto rounded-lg border border-[#E9E9EF] bg-[#FAFAFC] p-2.5 font-mono text-xs text-[#010507]"
          >
            {safeStringify(parameters)}
          </pre>
        </Section>

        <Section label="Result">
          {done ? (
            <pre
              data-testid="custom-catchall-result"
              className="overflow-x-auto rounded-lg border border-[#85ECCE4D] bg-[#85ECCE]/10 p-2.5 font-mono text-xs text-[#010507]"
            >
              {parsedResult !== undefined
                ? safeStringify(parsedResult)
                : "(empty)"}
            </pre>
          ) : (
            <p className="text-xs italic text-[#838389]">
              waiting for tool to finish…
            </p>
          )}
        </Section>
      </div>
    </div>
  );
}

function Section({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div>
      <div className="mb-1.5 text-[10px] font-medium uppercase tracking-[0.14em] text-[#838389]">
        {label}
      </div>
      {children}
    </div>
  );
}

function StatusBadge({ status }: { status: CatchallToolStatus }) {
  const { label, tone } = describeStatus(status);
  return (
    <span
      data-testid="custom-catchall-status"
      className={`rounded-full px-2.5 py-0.5 text-[10px] font-medium uppercase tracking-[0.14em] ${tone}`}
    >
      {label}
    </span>
  );
}

function describeStatus(status: CatchallToolStatus): {
  label: string;
  tone: string;
} {
  switch (status) {
    case "inProgress":
      return {
        label: "streaming",
        tone: "border border-[#FFAC4D33] bg-[#FFAC4D]/15 text-[#57575B]",
      };
    case "executing":
      return {
        label: "running",
        tone: "border border-[#BEC2FF] bg-[#BEC2FF1A] text-[#010507]",
      };
    case "complete":
      return {
        label: "done",
        tone: "border border-[#85ECCE4D] bg-[#85ECCE]/20 text-[#189370]",
      };
  }
}

function parseResult(result: string | undefined): unknown {
  if (result === undefined || result === null) return undefined;
  if (typeof result !== "string") return result;
  try {
    return JSON.parse(result);
  } catch {
    return result;
  }
}

function safeStringify(value: unknown): string {
  try {
    return JSON.stringify(value, null, 2);
  } catch {
    return String(value);
  }
}

