      className="max-w-xs mx-auto my-3 rounded-lg border border-[var(--border)] bg-[var(--card)] p-5"
    >
      <div className="text-xs font-medium uppercase tracking-wider text-[var(--muted-foreground)]">
        {label}
      </div>
      <div className="mt-1 text-3xl font-semibold tabular-nums text-[var(--foreground)]">
        {value}
      </div>
      {trend ? (
        <div
          className={`mt-2 inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium ${BADGE_CLASS[direction]}`}
        >
          {trend}
        </div>
      ) : null}
    </div>
  );
}

function inferTrendDirection(
  trend: string | null | undefined,
): "up" | "down" | "neutral" {
  const t = trend?.trim();
  if (!t) return "neutral";
  if (t.startsWith("+")) return "up";
  if (t.startsWith("-") || t.startsWith("−")) return "down";
  return "neutral";
}

const BADGE_CLASS = {
  up: "bg-[color-mix(in_oklab,var(--primary)_15%,transparent)] text-[var(--primary)]",
  down: "bg-[color-mix(in_oklab,var(--destructive)_15%,transparent)] text-[var(--destructive)]",
  neutral: "bg-[var(--secondary)] text-[var(--muted-foreground)]",
} as const;

import { defineRegistry } from "@json-render/react";
import { catalog } from "./catalog";
import { MetricCard } from "./metric-card";
import type { MetricCardComponentProps } from "./metric-card";
import { BarChart } from "./charts/bar-chart";
import type { BarChartComponentProps } from "./charts/bar-chart";
import { PieChart } from "./charts/pie-chart";
import type { PieChartComponentProps } from "./charts/pie-chart";

export const { registry } = defineRegistry(catalog, {
  components: {
    // The agent may nest charts inside a MetricCard root — forward children.
    MetricCard: ({ props, children }) => (
      <div className="flex w-full flex-col items-stretch gap-3">
        <MetricCard {...(props as MetricCardComponentProps)} />
        {children}
      </div>
    ),
    BarChart: ({ props }) => (
      <BarChart {...(props as BarChartComponentProps)} />
    ),
    PieChart: ({ props }) => (
      <PieChart {...(props as PieChartComponentProps)} />
    ),
  },
});

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

export const BYOC_JSON_RENDER_SUGGESTIONS = [
  {
    title: "Sales dashboard",
    message: "Show me the sales dashboard with metrics and a revenue chart",
  },
  {
    title: "Revenue by category",
    message: "Break down revenue by category as a pie chart",
  },
  {
    title: "Expense trend",
    message: "Show me monthly expenses as a bar chart",
  },
];

export function useByocJsonRenderSuggestions() {
  useConfigureSuggestions({
    suggestions: BYOC_JSON_RENDER_SUGGESTIONS,
    available: "always",
  });
}

export interface JsonRenderSpec {
  root: string;
  elements: Record<
    string,
    { type: string; props: Record<string, unknown>; children?: string[] }
  >;
}

