"use client";

import { useState } from "react";
import {
  CopilotKit,
  CopilotChat,
  useInterrupt,
} from "@copilotkit/react-core/v2";
import type { TimeSlot } from "./_components/time-picker-card";
import { TimePickerCard } from "./_components/time-picker-card";
import { generateFallbackSlots } from "../_shared/interrupt-fallback-slots";
import { useGenUiInterruptSuggestions } from "./suggestions";

// Shape the backend `schedule_meeting` tool pauses with: its `interrupt()`
// `reason` payload. `slots` is absent on the Strands path (the tool passes only
// topic and attendee), so the picker falls back to generated slots.
type SchedulingPayload = {
  topic?: string;
  attendee?: string;
  slots?: TimeSlot[];
};

// Read the tool's `interrupt()` reason off an AG-UI interrupt.
//
// The two bridges expose it on different channels: `ag_ui_strands` (Python)
// carries the reason object under `metadata.reason`, while the published
// `@ag-ui/aws-strands` 0.2.3 JSON-encodes it into `message` instead. Both are
// read so one page serves both, and the legacy event value is read last for
// adapters that pass the payload through unwrapped.
/**
 * JSON.parse that never throws and never returns a primitive. Both readers run
 * inside a React render callback, where a throw takes the whole pane down.
 */
function parseObject(raw: string | undefined): Record<string, unknown> | null {
  if (!raw) return null;
  try {
    const parsed: unknown = JSON.parse(raw);
    return parsed && typeof parsed === "object"
      ? (parsed as Record<string, unknown>)
      : null;
  } catch {
    return null;
  }
}

function readSchedulingPayload(
  interrupt: { metadata?: unknown; message?: string } | null | undefined,
  eventValue: unknown,
): SchedulingPayload {
  const metadata = interrupt?.metadata as
    | { reason?: SchedulingPayload }
    | undefined;
  if (metadata?.reason && typeof metadata.reason === "object") {
    return metadata.reason;
  }

  // The published TypeScript bridge JSON-encodes the reason into `message`
  // instead of carrying it on metadata.
  const decoded = parseObject(interrupt?.message);
  if (decoded) {
    const nested = (decoded as { reason?: SchedulingPayload }).reason;
    return nested && typeof nested === "object"
      ? nested
      : (decoded as SchedulingPayload);
  }

  // Legacy channel: some adapters pass the payload through as the event value,
  // JSON-encoded or not.
  const legacy =
    typeof eventValue === "string" ? parseObject(eventValue) : eventValue;
  if (!legacy || typeof legacy !== "object") return {};
  const wrapped = (legacy as { metadata?: { reason?: SchedulingPayload } })
    .metadata?.reason;
  if (wrapped && typeof wrapped === "object") return wrapped;
  return legacy as SchedulingPayload;
}

export default function GenUiInterruptDemo() {
  return (
    <CopilotKit runtimeUrl="/api/copilotkit" agent="gen-ui-interrupt">
      <div className="flex justify-center items-center h-screen w-full">
        <div className="h-full w-full max-w-4xl">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

function Chat() {
  // The failure banner lives OUTSIDE the interrupt element on purpose. The hook
  // caches the element it rendered, so a picker already on screen never sees an
  // updated prop: a flag threaded into the card would keep showing a stale
  // failure on the NEXT booking, before that booking's resume has even started.
  const [resumeFailed, setResumeFailed] = useState(false);

  return (
    <div className="flex h-full flex-col">
      {resumeFailed && (
        <div
          role="alert"
          data-testid="time-picker-resume-error"
          className="m-4 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800"
        >
          Your previous selection could not be sent. Please try booking again.
        </div>
      )}
      <div className="min-h-0 flex-1">
        <InterruptChat setResumeFailed={setResumeFailed} />
      </div>
    </div>
  );
}

function InterruptChat({
  setResumeFailed,
}: {
  setResumeFailed: (failed: boolean) => void;
}) {
  useGenUiInterruptSuggestions();

  // Native interrupt path. The backend `schedule_meeting` tool calls Strands'
  // `context.interrupt(...)`; the @ag-ui/aws-strands bridge finishes the run
  // with `outcome.type === "interrupt"`. Where the tool's `reason` travels
  // depends on the bridge version, so the reader below accepts both channels.
  // `resolve(...)` resumes the same Strands run, handing the selection back to
  // that `interrupt()` call.
  useInterrupt({
    agentId: "gen-ui-interrupt",
    renderInChat: true,
    render: ({ event, interrupt, resolve }) => {
      const payload = readSchedulingPayload(interrupt, event.value);
      const slots =
        payload.slots && payload.slots.length > 0
          ? payload.slots
          : generateFallbackSlots();
      return (
        <TimePickerCard
          topic={payload.topic ?? "a call"}
          attendee={payload.attendee}
          slots={slots}
          onSubmit={(result) => {
            setResumeFailed(false);
            // Defer resolve so React commits the picked/cancelled badge before
            // useInterrupt clears the interrupt element (a single rAF is not
            // reliable: it can fire before React's commit). The rejection is
            // re-surfaced rather than dropped, because the card has already
            // shown a green "Booked" badge by then and a silently failed
            // resume would leave the user reading a success that never
            // happened.
            window.setTimeout(() => {
              void resolve(result).catch((error: unknown) => {
                setResumeFailed(true);
                queueMicrotask(() => {
                  throw error;
                });
              });
            }, 500);
          }}
        />
      );
    },
  });

  return (
    <CopilotChat agentId="gen-ui-interrupt" className="h-full rounded-2xl" />
  );
}

/**
 * Dedicated Strands agent for the two interrupt demos.
 *
 * Mirrors the Python sibling's `agents/interrupt_agent.py`.
 *
 * `schedule_meeting` pauses itself through Strands' native interrupt system:
 * `context.interrupt(...)` halts the agent loop and the AG-UI bridge finishes
 * the run with `RUN_FINISHED` carrying `outcome.type === "interrupt"`. The
 * frontend renders the time picker from the interrupt payload, and resuming on
 * the same `threadId` returns the user's choice to that same `interrupt()`
 * call, so the tool body continues where it left off.
 *
 * How the resume payload arrives depends on the bridge, so the tool normalises
 * both shapes (see `readResume`): the pinned `@ag-ui/aws-strands` 0.2.3 passes
 * the client's payload through and cancels with `{ status: "cancelled" }`,
 * while the Python bridge wraps a resolved answer as `{ response: ... }` and
 * cancels with `{ cancelled: true }`.
 *
 * This is a dedicated agent rather than a tool on the shared showcase agent
 * because the shared agent already owns a `schedule_meeting` that answers
 * straight away. One tool name cannot both answer immediately for the other
 * demos and pause for these two, so the pausing version gets its own mount.
 *
 * Pause and resume happen in the same process here, so no `SessionManager` is
 * needed. Durable resume across a restart requires one.
 *
 * Docs: https://strandsagents.com/docs/user-guide/concepts/interrupts/
 */

import { Agent, tool } from "@strands-agents/sdk";
import { z } from "zod";
import { StrandsAgent } from "@ag-ui/aws-strands";
import { createModel } from "./model-factory";

/** What the picker sends back. */
interface MeetingChoice {
  chosen_time?: string;
  chosen_label?: string;
  cancelled?: boolean;
  status?: string;
}

/**
 * What the bridge hands a resumed tool. Two shapes are in circulation:
 *
 * - `@ag-ui/aws-strands` 0.2.3 (the pinned release) passes the client's payload
 *   through untouched, and signals a cancel as `{ status: "cancelled" }`.
 * - `ag_ui_strands` (Python) wraps it as `{ response: payload }`, and signals a
 *   cancel as `{ cancelled: true }`.
 *
 * Reading only one of them silently mis-reports the other: a resolved pick
 * arrives with no recognised answer and the tool tells the model the user never
 * picked a time.
 */
interface ResumeEnvelope {
  /** `null` when the client answered with no payload at all. */
  response?: MeetingChoice | null;
  cancelled?: boolean;
  status?: string;
}

/** Normalise both envelope shapes to `{ choice, cancelled }`. */
export function readResume(
  answer: ResumeEnvelope | MeetingChoice | null | undefined,
): {
  choice: MeetingChoice;
  cancelled: boolean;
} {
  const envelope: ResumeEnvelope =
    answer && typeof answer === "object" ? answer : {};
  const inner =
    "response" in envelope
      ? envelope.response
      : (answer as MeetingChoice | null | undefined);
  const choice: MeetingChoice = inner && typeof inner === "object" ? inner : {};
  const cancelled = Boolean(
    envelope.cancelled ||
    envelope.status === "cancelled" ||
    choice.cancelled ||
    choice.status === "cancelled",
  );
  return { choice, cancelled };
}

export const scheduleMeeting = tool({
  name: "schedule_meeting",
  description:
    "Ask the user to pick a meeting time, then confirm what was scheduled.",
  inputSchema: z.object({
    topic: z.string().describe("Short description of the meeting purpose."),
    attendee: z.string().optional().describe("Who the meeting is with."),
  }),
  callback: ({ topic, attendee }, context) => {
    // Typed optional by the SDK, so this is checked rather than asserted: with
    // no context there is nothing to pause on, and pretending otherwise would
    // schedule a meeting the user never saw.
    if (!context) {
      throw new Error("schedule_meeting needs a tool context to pause on");
    }

    // `attendee` is optional and the reason has to be JSON, which has no
    // `undefined`, so it is omitted rather than sent as undefined.
    const answer = context.interrupt<ResumeEnvelope>({
      name: "schedule_meeting",
      reason: attendee === undefined ? { topic } : { topic, attendee },
    });

    // Three cancel shapes reach here: each bridge's own sentinel for a
    // cancelled resume entry, and the picker's Cancel button, which resolves
    // with a `cancelled` flag inside the payload.
    const { choice, cancelled } = readResume(answer);
    if (cancelled) {
      return `User cancelled. Meeting NOT scheduled: ${topic}`;
    }

    const label = choice.chosen_label || choice.chosen_time;
    return label
      ? `Meeting scheduled for ${label}: ${topic}`
      : `User did not pick a time. Meeting NOT scheduled: ${topic}`;
  },
});

const SYSTEM_PROMPT = `You are a scheduling assistant.

Whenever the user asks you to book a call or schedule a meeting, you MUST call
the \`schedule_meeting\` tool. Pass a short \`topic\` describing the purpose and,
if known, an \`attendee\` describing who the meeting is with.

The tool pauses execution and shows the user a time picker. Once it resumes with
their choice, briefly confirm whether the meeting was scheduled and at what
time, or note that the user cancelled. Do not ask for approval yourself: always
call the tool and let the picker handle the decision. Keep responses short and
friendly.

Never claim a meeting is scheduled unless the tool result says so.`;

/** Build the agent backing gen-ui-interrupt and interrupt-headless. */
export async function buildInterruptAgent(): Promise<StrandsAgent> {
  return new StrandsAgent({
    agent: new Agent({
      model: await createModel(),
      systemPrompt: SYSTEM_PROMPT,
      tools: [scheduleMeeting],
    }),
    name: "interrupt",
    description:
      "Strands agent whose scheduling tool pauses natively for the user to pick a time",
  });
}

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import {
  CopilotRuntime,
  createCopilotRuntimeHandler,
} from "@copilotkit/runtime/v2";
import type { AbstractAgent, HttpAgentConfig } from "@ag-ui/client";
import { HttpAgent } from "@ag-ui/client";
import { AsyncLocalStorage } from "node:async_hooks";

// The agent backend runs as a separate process on port 8000.
// This runtime proxies CopilotKit requests to it via AG-UI protocol.
const AGENT_URL = process.env.AGENT_URL || "http://localhost:8000";

// Per-request request/response logging is gated behind this flag (default off).
// Under d6 probe fan-out, unconditional per-request logs flooded Railway's
// 500-logs/sec cap and killed the replica ("Messages dropped" → container stop).
// Set SHOWCASE_ROUTE_DEBUG=1 to re-enable verbose per-request tracing locally.
const ROUTE_DEBUG =
  process.env.SHOWCASE_ROUTE_DEBUG === "1" ||
  process.env.SHOWCASE_ROUTE_DEBUG === "true";

console.log("[copilotkit/route] Initializing CopilotKit runtime");
console.log(`[copilotkit/route] AGENT_URL: ${AGENT_URL}`);

// Per-request inbound x-* forwarding over the HttpAgent proxy hop. The Next
// route is a bare proxy; the model call happens in the Express agent (:8000).
// @ag-ui/client's HttpAgent `headers` are STATIC (construction-time), so the
// per-request seam is its `fetch` option: a custom fetch that reads an
// AsyncLocalStorage snapshot (seeded by the POST handler below) and injects the
// inbound x-* (incl. x-aimock-strict / x-test-id / x-diag-*) onto the outbound
// POST. These then arrive on req.headers at the Express endpoint, where the
// agent-side middleware reads them. Byte-identical to a plain fetch when no x-*
// are in scope, so demo traffic proxies unchanged.
const proxyHeaders = new AsyncLocalStorage<Record<string, string>>();

function extractXHeaders(req: NextRequest): Record<string, string> {
  const out: Record<string, string> = {};
  req.headers.forEach((value, key) => {
    const lower = key.toLowerCase();
    if (lower.startsWith("x-")) out[lower] = value;
  });
  return out;
}

const forwardingProxyFetch: NonNullable<HttpAgentConfig["fetch"]> = (
  url,
  requestInit,
) => {
  const forwarded = proxyHeaders.getStore() ?? {};
  if (Object.keys(forwarded).length === 0) return fetch(url, requestInit);
  const merged = new Headers(requestInit?.headers);
  for (const [k, v] of Object.entries(forwarded)) {
    if (!merged.has(k)) merged.set(k, v);
  }
  return fetch(url, { ...requestInit, headers: merged });
};

function createAgent(path = "/") {
  return new HttpAgent({
    url: `${AGENT_URL}${path}`,
    fetch: forwardingProxyFetch,
  });
}

// Register the same agent under all names used by demo pages.
// Strands runs a single shared backend agent; per-demo differentiation
// happens on the frontend (useFrontendTool / useRenderTool / useHumanInTheLoop
// / useAgentContext / A2UI catalogs). Every demo page's `agent=` prop must
// resolve to a name in this list.
const agentNames = [
  // Original blitz set
  "agentic_chat",
  "human_in_the_loop",
  "tool-rendering",
  "gen-ui-tool-based",
  "gen-ui-agent",
  "shared-state-read",
  "shared-state-write",
  "shared-state-streaming",
  "subagents",
  // Chat UI / chrome demos
  "chat-customization-css",
  "prebuilt-sidebar",
  "prebuilt-popup",
  "chat-slots",
  "headless-simple",
  "headless-complete",
  // Reasoning
  "reasoning-default",
  "reasoning-custom",
  // Frontend tools
  "frontend_tools",
  "frontend-tools-async",
  // HITL
  "hitl-in-chat",
  "hitl-in-app",
  // Tool rendering variants
  "tool-rendering-default-catchall",
  "tool-rendering-custom-catchall",
  "tool-rendering-reasoning-chain",
  // State / context
  "readonly-state-agent-context",
  "shared-state-read-write",
  // Modalities
  "multimodal",
  "voice",
  // Misc
  "auth",
  "agent-config",
  // BYOC renderers (wave 2)
  "byoc-hashbrown-demo",
  "byoc_json_render",
  // Open Generative UI (wave 2)
  "open-gen-ui",
  "open-gen-ui-advanced",
  // Polished chat shell (simplified port — wave 2 follow-up)
  "beautiful-chat",
  // Interrupt demos, served by the dedicated native-interrupt agent below
  "gen-ui-interrupt",
  "interrupt-headless",
];

// Agent names whose backend is a dedicated sub-application rather than the
// shared agent at the root. The interrupt demos need a `schedule_meeting` that
// pauses natively; the reasoning demos need the Responses API with reasoning
// summaries, which the shared chat-completions agent does not emit.
const dedicatedAgentPaths: Record<string, string> = {
  "beautiful-chat": "/beautiful-chat/",
  "gen-ui-interrupt": "/interrupt/",
  "interrupt-headless": "/interrupt/",
  "reasoning-default": "/reasoning/",
  "reasoning-custom": "/reasoning/",
  "tool-rendering-reasoning-chain": "/reasoning-chain/",
};

const agents: Record<string, AbstractAgent> = {};
for (const name of agentNames) {
  agents[name] = createAgent(dedicatedAgentPaths[name] ?? "/");
}
agents["default"] = createAgent();

console.log(
  `[copilotkit/route] Registered ${Object.keys(agents).length} agent names: ${Object.keys(agents).join(", ")}`,
);

export const POST = async (req: NextRequest) =>
  // Snapshot the inbound x-* into ALS for the duration of the request so the
  // HttpAgent's forwardingProxyFetch can inject them onto the outbound POST to
  // the Express agent. Only headers PRESENT inbound are forwarded — never
  // hardcoded — so non-diagnostic demo traffic is byte-identical.
  proxyHeaders.run(extractXHeaders(req), async () => {
    const url = req.url;
    const contentType = req.headers.get("content-type");
    if (ROUTE_DEBUG) {
      console.log(
        `[copilotkit/route] POST ${url} (content-type: ${contentType})`,
      );
    }

    try {
      const copilotHandler = createCopilotRuntimeHandler({
        runtime: new CopilotRuntime({
          // @ts-ignore -- Published CopilotRuntime agents type wraps Record in MaybePromise<NonEmptyRecord<...>> which rejects plain Records; fixed in source, pending release
          agents,
        }),
        basePath: "/api/copilotkit",
        mode: "single-route",
      });

      const response = await copilotHandler(req);
      if (!response.ok) {
        console.log(`[copilotkit/route] Response status: ${response.status}`);
      } else if (ROUTE_DEBUG) {
        console.log(`[copilotkit/route] Response status: ${response.status}`);
      }
      return response;
    } catch (error: unknown) {
      const err = error as Error;
      console.error(`[copilotkit/route] ERROR: ${err.message}`);
      console.error(`[copilotkit/route] Stack: ${err.stack}`);
      return NextResponse.json(
        { error: err.message, stack: err.stack },
        { status: 500 },
      );
    }
  });

export const GET = async () => {
  if (ROUTE_DEBUG) {
    console.log("[copilotkit/route] GET /api/copilotkit (health probe)");
  }

  let agentStatus = "unknown";
  try {
    const res = await fetch(`${AGENT_URL}/health`, {
      signal: AbortSignal.timeout(3000),
    });
    agentStatus = res.ok ? "reachable" : `error (${res.status})`;
  } catch (e: unknown) {
    agentStatus = `unreachable (${(e as Error).message})`;
  }

  return NextResponse.json({
    status: "ok",
    agent_url: AGENT_URL,
    agent_status: agentStatus,
    env: {
      OPENAI_API_KEY: process.env.OPENAI_API_KEY ? "set" : "NOT SET",
      NODE_ENV: process.env.NODE_ENV,
    },
  });
};

